/// Paket 39: Mevcut 'alisveris' ve 'tamamlanan' kayıt biçimleri değiştirilmez.
/// Kategori/miktar notları ayrı bir anahtarda saklanır.
class SmartShoppingPage extends StatefulWidget {
  const SmartShoppingPage({super.key});
  @override
  State<SmartShoppingPage> createState() => _SmartShoppingPageState();
}

class _SmartShoppingPageState extends State<SmartShoppingPage> {
  static const _purple = Color(0xFF48235F);
  static const _pink = Color(0xFFFFF7FC);
  static const _categories = <String>[
    'Tümü', 'Sebze & Meyve', 'Et & Balık', 'Süt & Kahvaltılık',
    'Bakliyat & Tahıl', 'Baharat & Sos', 'Temizlik', 'Bebek', 'Diğer',
  ];
  final _items = <String>[];
  final _done = <String>{};
  final _details = <String, Map<String, String>>{};
  // Büyük alışveriş listelerinde aynı anda yalnızca bir sayfa oluşturulur.
  static const int _shoppingPageSize = 30;
  int _shoppingPage = 0;
  String _query = '';
  String _category = 'Tümü';
  bool _hideDone = false;
  bool _loading = true;
  double _budget = 0;
  final _prices = <String, double>{};
  final _actualPrices = <String, double>{};
  final _history = <Map<String, dynamic>>[];
  final _monthlyBudgets = <String, double>{};
  String _historyQuery = '';
  // Named lists are independent snapshots. The shared 'alisveris' key remains
  // the active list for other app screens and is never replaced automatically.
  final _namedLists = <Map<String, dynamic>>[];
  final _shoppingPlans = <Map<String, dynamic>>[];
  final _consumptionGoals = <String, double>{};
  final _kitchenWaste = <Map<String, dynamic>>[];
  final _kitchenMeals = <Map<String, dynamic>>[];
  final _customRecipes = <Map<String, dynamic>>[];
  // Fiyatlar kanonik birim başına TL olarak tutulur (g/ml/adet).
  final _ingredientUnitPrices = <String, double>{};
  final _mealTemplates = <Map<String, dynamic>>[];
  final _savedMenuDrafts = <Map<String, dynamic>>[];
  // Kalıcı çöp kutusu: önceki veri anahtarlarından bağımsız tutulur.
  final _kitchenTrash = <Map<String, dynamic>>[];
  static const _kitchenTrashKey = 'paket39_kitchen_trash_v1';
  static const _savedMenuDraftsKey = 'paket39_saved_menu_drafts_v1';
  final _kitchenWeeklyBudgets = <String, double>{};
  static const _kitchenWeeklyBudgetKey = 'paket39_kitchen_weekly_budgets_v1';
  static const _mealTemplatesKey = 'paket39_meal_templates_v1';
  static const _ingredientUnitPricesKey = 'paket39_ingredient_unit_prices_v1';
  static const _customRecipesKey = 'paket39_custom_recipes_v1';
  static const _wasteKey = 'paket39_kitchen_waste_v1';
  static const _mealsKey = 'paket39_kitchen_meals_v1';
  static const _plansKey = 'paket39_shopping_plans_v1';
  static const _goalsKey = 'paket39_consumption_goals_v1';
  static const _namedListsKey = 'paket39_named_shopping_lists_v1';
  static const _templates = <String, List<String>>{
    'Haftalık market': ['Süt', 'Yumurta', 'Ekmek', 'Yoğurt', 'Domates', 'Salatalık'],
    'Bebek ihtiyaçları': ['Bebek bezi', 'Islak mendil', 'Bebek şampuanı'],
    'Temizlik': ['Bulaşık deterjanı', 'Çamaşır deterjanı', 'Çöp poşeti'],
    'Kahvaltılık': ['Peynir', 'Zeytin', 'Yumurta', 'Ekmek', 'Süt'],
  };

  String _monthKey([DateTime? date]) {
    final d = date ?? DateTime.now();
    return '${d.year}-${d.month.toString().padLeft(2, '0')}';
  }


  @override
  void initState() { super.initState(); _load(); }

  Future<void> _load() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final items = (jsonDecode(prefs.getString('alisveris') ?? '[]') as List)
          .map((e) => e.toString()).toList();
      final done = (jsonDecode(prefs.getString('tamamlanan') ?? '[]') as List)
          .map((e) => e.toString()).toSet();
      final raw = jsonDecode(prefs.getString('paket39_shopping_details_v1') ?? '{}') as Map;
      final budget = prefs.getDouble('paket39_shopping_budget_v1') ?? 0;
      final rawPrices = jsonDecode(prefs.getString('paket39_shopping_prices_v1') ?? '{}') as Map;
      final rawActual = jsonDecode(prefs.getString('paket39_shopping_actual_prices_v1') ?? '{}') as Map;
      final rawHistory = jsonDecode(prefs.getString('paket39_shopping_history_v1') ?? '[]') as List;
      final rawWaste = jsonDecode(prefs.getString(_wasteKey) ?? '[]') as List;
      final rawMeals = jsonDecode(prefs.getString(_mealsKey) ?? '[]') as List;
      final rawCustomRecipes = jsonDecode(prefs.getString(_customRecipesKey) ?? '[]') as List;
      final rawWeeklyBudgets = jsonDecode(prefs.getString(_kitchenWeeklyBudgetKey) ?? '{}') as Map;
      final rawMealTemplates = jsonDecode(prefs.getString(_mealTemplatesKey) ?? '[]') as List;
      final rawMenuDrafts = jsonDecode(prefs.getString(_savedMenuDraftsKey) ?? '[]') as List;
      final rawTrash = jsonDecode(prefs.getString(_kitchenTrashKey) ?? '[]') as List;
      final rawUnitPrices = jsonDecode(prefs.getString(_ingredientUnitPricesKey) ?? '{}') as Map;
      final rawPlans = jsonDecode(prefs.getString(_plansKey) ?? '[]') as List;
      final rawGoals = jsonDecode(prefs.getString(_goalsKey) ?? '{}') as Map;
      final rawNamedLists = jsonDecode(prefs.getString(_namedListsKey) ?? '[]') as List;
      final rawMonthlyBudgets = jsonDecode(prefs.getString('paket39_monthly_shopping_budgets_v1') ?? '{}') as Map;
      if (!mounted) return;
      setState(() {
        _savedMenuDrafts..clear()..addAll(rawMenuDrafts.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _kitchenTrash..clear()..addAll(rawTrash.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _kitchenWaste..clear()..addAll(rawWaste.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _kitchenMeals..clear()..addAll(rawMeals.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _customRecipes..clear()..addAll(rawCustomRecipes.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _kitchenWeeklyBudgets..clear()..addAll(rawWeeklyBudgets.map((k,v) => MapEntry(k.toString(), _planNum(v))));
        _mealTemplates..clear()..addAll(rawMealTemplates.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _ingredientUnitPrices..clear()..addAll(rawUnitPrices.map((k,v) => MapEntry(k.toString(), _planNum(v))));
        _shoppingPlans..clear()..addAll(rawPlans.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _consumptionGoals..clear()..addAll(rawGoals.map((k,v) => MapEntry(k.toString(), (v as num).toDouble())));
        _namedLists..clear()..addAll(rawNamedLists.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _budget = budget;
        _monthlyBudgets..clear()..addAll(rawMonthlyBudgets.map((k, v) => MapEntry(k.toString(), (v as num).toDouble())));
        _actualPrices..clear()..addAll(rawActual.map((k, v) => MapEntry(k.toString(), (v as num).toDouble())));
        _history..clear()..addAll(rawHistory.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
        _prices..clear()..addAll(rawPrices.map((k, v) => MapEntry(k.toString(), (v as num).toDouble())));
        _items..clear()..addAll(items);
        _done..clear()..addAll(done);
        _details.clear();
        for (final entry in raw.entries) {
          if (entry.value is Map) {
            _details[entry.key.toString()] = (entry.value as Map)
                .map((key, value) => MapEntry(key.toString(), value.toString()));
          }
        }
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _loading = false);
      _notice('Liste okunamadı; mevcut veriler değiştirilmedi.');
    }
  }

  Future<void> _save() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final ok1 = await prefs.setString('alisveris', jsonEncode(_items));
      final ok2 = await prefs.setString('tamamlanan', jsonEncode(_done.toList()));
      final ok3 = await prefs.setString('paket39_shopping_details_v1', jsonEncode(_details));
      final ok4 = await prefs.setDouble('paket39_shopping_budget_v1', _budget);
      final ok5 = await prefs.setString('paket39_shopping_prices_v1', jsonEncode(_prices));
      final ok6 = await prefs.setString('paket39_shopping_actual_prices_v1', jsonEncode(_actualPrices));
      final ok7 = await prefs.setString('paket39_shopping_history_v1', jsonEncode(_history));
      final ok8 = await prefs.setString('paket39_monthly_shopping_budgets_v1', jsonEncode(_monthlyBudgets));
      final ok9 = await prefs.setString(_namedListsKey, jsonEncode(_namedLists));
      final ok10 = await prefs.setString(_plansKey, jsonEncode(_shoppingPlans));
      final ok11 = await prefs.setString(_goalsKey, jsonEncode(_consumptionGoals));
      final ok12 = await prefs.setString(_wasteKey, jsonEncode(_kitchenWaste));
      final ok13 = await prefs.setString(_mealsKey, jsonEncode(_kitchenMeals));
      final ok14 = await prefs.setString(_customRecipesKey, jsonEncode(_customRecipes));
      final ok15 = await prefs.setString(_ingredientUnitPricesKey, jsonEncode(_ingredientUnitPrices));
      final ok16 = await prefs.setString(_mealTemplatesKey, jsonEncode(_mealTemplates));
      final ok17 = await prefs.setString(_kitchenWeeklyBudgetKey, jsonEncode(_kitchenWeeklyBudgets));
      final ok18 = await prefs.setString(_savedMenuDraftsKey, jsonEncode(_savedMenuDrafts));
      final ok19 = await prefs.setString(_kitchenTrashKey, jsonEncode(_kitchenTrash));
      if (!ok19 || !ok18 || !ok17 || !ok16 || !ok15 || !ok14 || !ok12 || !ok13 || !ok10 || !ok11 || !ok9 || !ok1 || !ok2 || !ok3 || !ok4 || !ok5 || !ok6 || !ok7 || !ok8) throw StateError('Kaydetme başarısız');
    } catch (_) { _notice('Değişiklik kaydedilemedi.'); }
  }

  Map<String, dynamic> _activeSnapshot(String title) => <String, dynamic>{
    'id': DateTime.now().microsecondsSinceEpoch.toString(),
    'title': title,
    'updated': DateTime.now().toIso8601String(),
    'items': List<String>.from(_items),
    'done': _done.toList(),
    'details': _details.map((k, v) => MapEntry(k, Map<String, String>.from(v))),
    'prices': Map<String, double>.from(_prices),
    'actualPrices': Map<String, double>.from(_actualPrices),
  };

  Future<String?> _askListName({String? initial}) async {
    final controller = TextEditingController(text: initial ?? '');
    final name = await showDialog<String>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Alışveriş listesi adı'),
      content: TextField(controller: controller, maxLength: 60,
        decoration: const InputDecoration(hintText: 'Örn. Haftalık market'),
        autofocus: true),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final value = controller.text.trim();
          if (value.isNotEmpty) Navigator.pop(ctx, value);
        }, child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(controller);
    return name;
  }

  Future<void> _saveNamedList() async {
    final title = await _askListName();
    if (title == null || !mounted) return;
    setState(() => _namedLists.insert(0, _activeSnapshot(title)));
    await _save();
    _notice('“$title” ayrı liste olarak kaydedildi.');
  }

  Future<void> _addNamedItems(Map<String, dynamic> record) async {
    final names = ((record['items'] as List?) ?? []).map((e) => e.toString()).toList();
    final existing = _items.map(_normalizeName).toSet();
    final additions = <String>[];
    for (final name in names) {
      if (name.trim().isNotEmpty && existing.add(_normalizeName(name))) additions.add(name);
    }
    if (additions.isEmpty) { _notice('Bu listedeki ürünler zaten aktif listede.'); return; }
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Aktif alışveriş listesine ekle'),
      content: Text('${additions.length} yeni ürün eklenecek. Aktif ürünler ve kayıtları korunacak.'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Ekle'))],
    ));
    if (confirmed != true || !mounted) return;
    final details = record['details'] is Map ? record['details'] as Map : <String, dynamic>{};
    final prices = record['prices'] is Map ? record['prices'] as Map : <String, dynamic>{};
    setState(() {
      for (final name in additions) {
        _items.add(name);
        if (details[name] is Map) {
          _details[name] = (details[name] as Map).map((k, v) => MapEntry(k.toString(), v.toString()));
        }
        if (prices[name] is num) _prices[name] = (prices[name] as num).toDouble();
      }
    });
    await _save();
    _notice('${additions.length} ürün aktif listeye eklendi.');
  }

  Future<void> _createFromTemplate() async {
    final selected = await showModalBottomSheet<String>(context: context, builder: (ctx) => SafeArea(
      child: ListView(shrinkWrap: true, children: [
        const ListTile(title: Text('Hazır alışveriş şablonları')),
        ..._templates.entries.map((e) => ListTile(
          title: Text(e.key), subtitle: Text('${e.value.length} ürün'),
          trailing: const Icon(Icons.chevron_right), onTap: () => Navigator.pop(ctx, e.key))),
      ])));
    if (selected == null || !mounted) return;
    final title = await _askListName(initial: selected);
    if (title == null || !mounted) return;
    final names = _templates[selected]!;
    final record = <String, dynamic>{
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': title, 'updated': DateTime.now().toIso8601String(),
      'items': List<String>.from(names), 'done': <String>[],
      'details': <String, dynamic>{}, 'prices': <String, dynamic>{},
      'actualPrices': <String, dynamic>{},
    };
    setState(() => _namedLists.insert(0, record));
    await _save();
    _notice('Şablon “$title” olarak kaydedildi. Aktif liste değiştirilmedi.');
  }

  Future<void> _shareList(Map<String, dynamic> record) async {
    final names = ((record['items'] as List?) ?? []).map((e) => e.toString()).toList();
    final completed = ((record['done'] as List?) ?? []).map((e) => e.toString()).toSet();
    final body = <String>[record['title']?.toString() ?? 'Alışveriş listesi', '',
      ...names.map((e) => '${completed.contains(e) ? '☑' : '☐'} $e')].join('\n');
    await Clipboard.setData(ClipboardData(text: body));
    _notice('Liste panoya kopyalandı; mesaj veya e-postaya yapıştırabilirsin.');
  }

  // Aşama 123–127: Miktar/birim ve birim fiyatı, eski toplam fiyat
  // alanlarından ayrı saklanır. Eski kayıtlar otomatik olarak korunur.
  static const _units = <String>['adet', 'kg', 'g', 'L', 'ml', 'paket', 'kutu'];

  Map<String, dynamic> _namedQuantity(Map<String, dynamic> record, String name) {
    final raw = record['quantities'] is Map ? (record['quantities'] as Map)[name] : null;
    if (raw is Map) return Map<String, dynamic>.from(raw);
    return <String, dynamic>{'amount': 1.0, 'unit': 'adet'};
  }

  double _namedItemTotal(Map<String, dynamic> record, String name) {
    final unitPrices = record['unitPrices'] is Map ? record['unitPrices'] as Map : <String, dynamic>{};
    final unitPrice = unitPrices[name];
    if (unitPrice is num && unitPrice.isFinite && unitPrice >= 0) {
      final amount = _namedQuantity(record, name)['amount'];
      return unitPrice.toDouble() * (amount is num ? amount.toDouble() : 1.0);
    }
    final prices = record['prices'] is Map ? record['prices'] as Map : <String, dynamic>{};
    final price = prices[name];
    return price is num && price.isFinite && price >= 0 ? price.toDouble() : 0;
  }

  String _namedCategory(Map<String, dynamic> record, String name) {
    final details = record['details'] is Map ? record['details'] as Map : <String, dynamic>{};
    final item = details[name];
    final category = item is Map ? item['category']?.toString() : null;
    return category != null && _categories.contains(category) && category != 'Tümü'
        ? category : _guess(name);
  }

  Future<void> _editNamedQuantity(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final existing = _namedQuantity(record, name);
    final amountInput = TextEditingController(text: (existing['amount'] ?? 1).toString());
    final unitPrices = record['unitPrices'] is Map ? record['unitPrices'] as Map : <String, dynamic>{};
    final priceInput = TextEditingController(text: unitPrices[name]?.toString() ?? '');
    String unit = _units.contains(existing['unit']) ? existing['unit'].toString() : 'adet';
    final result = await showDialog<(double, String, double?)>(context: context,
      builder: (dialog) => StatefulBuilder(builder: (dialog, update) => AlertDialog(
        title: Text('$name • Miktar ve birim fiyat'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(controller: amountInput, keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Miktar (0’dan büyük)')),
          DropdownButtonFormField<String>(initialValue: unit,
            items: _units.map((u) => DropdownMenuItem(value: u, child: Text(u))).toList(),
            onChanged: (v) { if (v != null) update(() => unit = v); },
            decoration: const InputDecoration(labelText: 'Birim')),
          TextField(controller: priceInput, keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Birim fiyatı (TL)',
              helperText: 'Boş bırakılırsa eski toplam tahmini fiyat kullanılır.')),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Vazgeç')),
          FilledButton(onPressed: () {
            final amount = double.tryParse(amountInput.text.trim().replaceAll(',', '.'));
            final raw = priceInput.text.trim();
            final price = raw.isEmpty ? null : double.tryParse(raw.replaceAll(',', '.'));
            if (amount == null || !amount.isFinite || amount <= 0 ||
                (raw.isNotEmpty && (price == null || !price.isFinite || price < 0))) { return ; }
            Navigator.pop(dialog, (amount, unit, price));
          }, child: const Text('Kaydet'))],
      )));
    disposeAfterDialog(amountInput);
    disposeAfterDialog(priceInput);
    if (result == null || !mounted) return;
    setState(() {
      final quantities = record['quantities'] is Map
          ? Map<String, dynamic>.from(record['quantities'] as Map) : <String, dynamic>{};
      quantities[name] = {'amount': result.$1, 'unit': result.$2};
      record['quantities'] = quantities;
      final unitPriceMap = record['unitPrices'] is Map
          ? Map<String, dynamic>.from(record['unitPrices'] as Map) : <String, dynamic>{};
      if (result.$3 == null) { unitPriceMap.remove(name); } else { unitPriceMap[name] = result.$3; }
      record['unitPrices'] = unitPriceMap;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  // Aşama 128–132: Marka ve market bilgileri ayrı alanda saklanır;
  // eski liste kayıtları bu alan olmadan da açılabilir.
  Map<String, String> _namedProductMeta(Map<String, dynamic> record, String name) {
    final raw = record['productMeta'] is Map ? (record['productMeta'] as Map)[name] : null;
    if (raw is! Map) return <String, String>{'brand': '', 'store': ''};
    return <String, String>{'brand': raw['brand']?.toString() ?? '',
      'store': raw['store']?.toString() ?? ''};
  }

  Future<void> _editNamedProductMeta(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final current = _namedProductMeta(record, name);
    final brand = TextEditingController(text: current['brand']);
    final store = TextEditingController(text: current['store']);
    final accepted = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$name • Ürün detayları'),
      content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: brand, maxLength: 80,
          decoration: const InputDecoration(labelText: 'Marka', hintText: 'Örn. marka adı')),
        TextField(controller: store, maxLength: 80,
          decoration: const InputDecoration(labelText: 'Market / mağaza', hintText: 'Örn. market adı')),
        const Text('Bilgiler yalnızca bu kayıtlı listedeki ürün için geçerlidir.'),
      ])),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Kaydet'))],
    ));
    final newBrand = brand.text.trim();
    final newStore = store.text.trim();
    disposeAfterDialog(brand);
    disposeAfterDialog(store);
    if (accepted != true || !mounted) return;
    setState(() {
      final meta = record['productMeta'] is Map
          ? Map<String, dynamic>.from(record['productMeta'] as Map) : <String, dynamic>{};
      if (newBrand.isEmpty && newStore.isEmpty) {
        meta.remove(name);
      } else {
        meta[name] = <String, String>{'brand': newBrand, 'store': newStore};
      }
      record['productMeta'] = meta;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  // Aşama 133–137: Stok/SKT bilgileri, kayıtlı listeye özgü ek alanlardır.
  static const _storagePlaces = <String>['Belirtilmedi', 'Buzdolabı', 'Dondurucu', 'Kiler', 'Diğer'];

  Map<String, String> _namedStock(Map<String, dynamic> record, String name) {
    final raw = record['stockMeta'] is Map ? (record['stockMeta'] as Map)[name] : null;
    if (raw is! Map) return {'expiry': '', 'storage': 'Belirtilmedi', 'amount': '', 'minimum': '', 'updated': ''};
    final storage = raw['storage']?.toString() ?? 'Belirtilmedi';
    return {'expiry': raw['expiry']?.toString() ?? '',
      'storage': _storagePlaces.contains(storage) ? storage : 'Belirtilmedi',
      'amount': raw['amount']?.toString() ?? '', 'minimum': raw['minimum']?.toString() ?? '',
      'updated': raw['updated']?.toString() ?? ''};
  }

  DateTime? _expiryDate(String raw) {
    if (raw.isEmpty) return null;
    final parsed = DateTime.tryParse(raw);
    return parsed == null ? null : DateTime(parsed.year, parsed.month, parsed.day);
  }

  int? _expiryDays(Map<String, dynamic> record, String name) {
    final expiry = _expiryDate(_namedStock(record, name)['expiry'] ?? '');
    if (expiry == null) return null;
    final now = DateTime.now();
    return expiry.difference(DateTime(now.year, now.month, now.day)).inDays;
  }

  String _expiryLabel(Map<String, dynamic> record, String name) {
    final days = _expiryDays(record, name);
    if (days == null) return 'SKT belirtilmedi';
    if (days < 0) return 'SKT geçti (${days.abs()} gün)';
    if (days == 0) return 'SKT bugün';
    if (days <= 7) return 'SKT yaklaşıyor ($days gün)';
    return 'SKT: ${_namedStock(record, name)['expiry']}';
  }

  Future<void> _editNamedStock(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final existing = _namedStock(record, name);
    DateTime? selectedDate = _expiryDate(existing['expiry'] ?? '');
    String storage = existing['storage'] ?? 'Belirtilmedi';
    final accepted = await showDialog<bool>(context: context,
      builder: (dialog) => StatefulBuilder(builder: (dialog, update) => AlertDialog(
        title: Text('$name • Stok ve saklama'),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          ListTile(contentPadding: EdgeInsets.zero,
            title: const Text('Son kullanma tarihi'),
            subtitle: Text(selectedDate == null ? 'Belirtilmedi' :
              '${selectedDate!.day.toString().padLeft(2, '0')}.${selectedDate!.month.toString().padLeft(2, '0')}.${selectedDate!.year}'),
            trailing: const Icon(Icons.calendar_month_outlined),
            onTap: () async {
              final date = await showDatePicker(context: dialog,
                initialDate: selectedDate ?? DateTime.now(),
                firstDate: DateTime(2000), lastDate: DateTime(2100));
              if (date != null) update(() => selectedDate = date);
            }),
          TextButton(onPressed: () => update(() => selectedDate = null),
            child: const Text('Tarihi temizle')),
          DropdownButtonFormField<String>(initialValue: storage,
            decoration: const InputDecoration(labelText: 'Saklama yeri'),
            items: _storagePlaces.map((place) => DropdownMenuItem(value: place, child: Text(place))).toList(),
            onChanged: (value) { if (value != null) update(() => storage = value); }),
        ]),
        actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Kaydet'))],
      )));
    if (accepted != true || !mounted) return;
    setState(() {
      final meta = record['stockMeta'] is Map
        ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
      final date = selectedDate == null ? '' :
        '${selectedDate!.year}-${selectedDate!.month.toString().padLeft(2, '0')}-${selectedDate!.day.toString().padLeft(2, '0')}';
      if (date.isEmpty && storage == 'Belirtilmedi' && (existing['amount'] ?? '').isEmpty && (existing['minimum'] ?? '').isEmpty) {
        meta.remove(name);
      } else {
        meta[name] = {...existing, 'expiry': date, 'storage': storage};
      }
      record['stockMeta'] = meta;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  // Aşama 148–157: Her kayıtlı liste için kalıcı stok hareket günlüğü.
  List<Map<String, dynamic>> _stockMovements(Map<String, dynamic> record) =>
      (record['stockMovements'] as List? ?? const [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e)).toList();

  void _recordStockMovement(Map<String, dynamic> record, String name,
      double before, double after, String reason) {
    if ((before - after).abs() < 0.000001) return;
    final entries = _stockMovements(record);
    entries.insert(0, <String, dynamic>{
      'date': DateTime.now().toIso8601String(),
      'product': name,
      'before': before,
      'after': after,
      'change': after - before,
      'reason': reason,
      'unit': _namedQuantity(record, name)['unit'] ?? 'Adet',
    });
    record['stockMovements'] = entries;
  }

  DateTime? _movementDate(Map<String, dynamic> movement) =>
      DateTime.tryParse(movement['date']?.toString() ?? '');

  double _consumptionPerDay(Map<String, dynamic> record, String name) {
    final outgoing = _stockMovements(record).where((m) =>
        m['product'] == name && (m['change'] is num) &&
        (m['change'] as num) < 0 && _movementDate(m) != null).toList();
    if (outgoing.isEmpty) return 0;
    final dates = outgoing.map((m) => _movementDate(m)!).toList()..sort();
    final days = DateTime.now().difference(dates.first).inHours / 24.0;
    final span = days < 1 ? 1.0 : days;
    final used = outgoing.fold<double>(0, (sum, m) =>
        sum - (m['change'] as num).toDouble());
    return used / span;
  }

  String _stockForecast(Map<String, dynamic> record, String name) {
    final current = _namedStock(record, name)['amount'] ?? '';
    if (current.isEmpty) return 'Stok tanımlı değil';
    final rate = _consumptionPerDay(record, name);
    if (rate <= 0) return 'Tahmin için tüketim kaydı gerekli';
    final remaining = _stockNumber(current) / rate;
    if (remaining <= 0) return 'Stok tükendi';
    return 'Yaklaşık ${remaining.ceil()} gün';
  }

  void _showStockMovements(Map<String, dynamic> record) {
    String period = 'Tümü';
    String query = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final entries = _stockMovements(record).where((m) {
          final date = _movementDate(m);
          if (date == null) return false;
          final days = now.difference(date).inDays;
          final within = period == 'Günlük' ?
              date.year == now.year && date.month == now.month && date.day == now.day :
              period == 'Haftalık' ? days >= 0 && days < 7 :
              period == 'Aylık' ? date.year == now.year && date.month == now.month : true;
          return within && (m['product']?.toString().toLowerCase().contains(query.toLowerCase()) ?? false);
        }).toList();
        final incoming = entries.fold<double>(0, (sum, m) {
          final change = (m['change'] as num?)?.toDouble() ?? 0;
          return sum + (change > 0 ? change : 0);
        });
        final outgoing = entries.fold<double>(0, (sum, m) {
          final change = (m['change'] as num?)?.toDouble() ?? 0;
          return sum + (change < 0 ? -change : 0);
        });
        return SafeArea(child: FractionallySizedBox(heightFactor: .88,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Stok hareketleri ve tüketim analizi',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text(record['title']?.toString() ?? ''),
            const SizedBox(height: 8),
            TextField(decoration: const InputDecoration(
              prefixIcon: Icon(Icons.search), labelText: 'Ürün ara'),
              onChanged: (v) => refresh(() => query = v)),
            Wrap(spacing: 6, children: ['Tümü', 'Günlük', 'Haftalık', 'Aylık'].map((p) =>
              ChoiceChip(label: Text(p), selected: period == p,
                onSelected: (_) => refresh(() => period = p))).toList()),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${entries.length} hareket • Giriş: ${incoming.toStringAsFixed(1)} • Çıkış: ${outgoing.toStringAsFixed(1)}'),
                const Text('Farklı birimlerdeki miktarlar ayrı değerlendirilmelidir.',
                  style: TextStyle(fontSize: 11)),
              ]))),
            if (entries.isEmpty) const ListTile(title: Text('Bu dönemde stok hareketi yok.')),
            ...entries.map((m) {
              final change = (m['change'] as num?)?.toDouble() ?? 0;
              final date = _movementDate(m)!;
              return ListTile(
                leading: Icon(change > 0 ? Icons.add_circle_outline : Icons.remove_circle_outline,
                  color: change > 0 ? Colors.green : Colors.deepOrange),
                title: Text(m['product']?.toString() ?? ''),
                subtitle: Text('${date.day.toString().padLeft(2, '0')}.${date.month.toString().padLeft(2, '0')}.${date.year} • ${m['reason'] ?? ''} • ${m['before']} → ${m['after']}'),
                trailing: Text('${change > 0 ? '+' : ''}${change.toStringAsFixed(1)} ${m['unit'] ?? ''}'),
              );
            }),
            const Divider(),
            const Text('Tüketim hızı ve stok yenileme önerileri',
              style: TextStyle(fontWeight: FontWeight.bold)),
            const Text('Tahminler yalnızca bu sürümden itibaren kaydedilen stok çıkışlarına dayanır.',
              style: TextStyle(fontSize: 11)),
            ...(record['items'] as List? ?? const []).map((rawName) {
              final name = rawName.toString();
              final rate = _consumptionPerDay(record, name);
              final current = _namedStock(record, name);
              final min = _stockNumber(current['minimum']);
              final amount = _stockNumber(current['amount']);
              final need = (min - amount).clamp(0.0, double.infinity);
              return ListTile(title: Text(name),
                subtitle: Text('Ortalama tüketim: ${rate.toStringAsFixed(2)}/gün • Tahmini bitiş: ${_stockForecast(record, name)}'),
                trailing: need > 0 ? Text('Öneri: +${need.toStringAsFixed(1)}') : null);
            }),
          ])));
      }));
  }

  // Aşama 158–167: Ayrıntılı stok işlemleri ve raporlama.
  Future<void> _manualStockMovement(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final stock = _namedStock(record, name);
    final qty = TextEditingController(text: '1');
    final note = TextEditingController();
    bool incoming = true;
    final accepted = await showDialog<bool>(context: context,
      builder: (dialog) => StatefulBuilder(builder: (dialog, update) => AlertDialog(
        title: Text('$name • Stok hareketi'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          SegmentedButton<bool>(segments: const [
            ButtonSegment(value: true, label: Text('Giriş')),
            ButtonSegment(value: false, label: Text('Çıkış'))],
            selected: {incoming}, onSelectionChanged: (v) => update(() => incoming = v.first)),
          TextField(controller: qty, keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Miktar')),
          TextField(controller: note, maxLength: 120,
            decoration: const InputDecoration(labelText: 'Açıklama (isteğe bağlı)')),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () {
            final value = double.tryParse(qty.text.replaceAll(',', '.'));
            if (value != null && value > 0 && value.isFinite) Navigator.pop(dialog, true);
          }, child: const Text('Kaydet'))],
      )));
    final value = double.tryParse(qty.text.replaceAll(',', '.'));
    final reason = note.text.trim();
    disposeAfterDialog(qty); disposeAfterDialog(note);
    if (accepted != true || !mounted || value == null) return;
    if ((stock['amount'] ?? '').isEmpty) { _notice('Önce stok miktarını tanımlayın.'); return; }
    final before = _stockNumber(stock['amount']);
    if (!incoming && value > before) { _notice('Çıkış miktarı mevcut stoktan büyük olamaz.'); return; }
    final after = before + (incoming ? value : -value);
    setState(() {
      _recordStockMovement(record, name, before, after,
          '${incoming ? 'Stok girişi' : 'Stok çıkışı'}${reason.isEmpty ? '' : ' • $reason'}');
      final meta = record['stockMeta'] is Map
          ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
      meta[name] = {...stock, 'amount': after.toString(),
        'updated': DateTime.now().toIso8601String()};
      record['stockMeta'] = meta;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  String _stockCsvCell(Object? value) =>
      '"${(value ?? '').toString().replaceAll('"', '""')}"';

  void _showAdvancedStock(Map<String, dynamic> record) {
    String product = 'Tümü';
    DateTime? from;
    DateTime? to;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final names = (record['items'] as List? ?? const [])
            .map((e) => e.toString()).toList();
        final all = _stockMovements(record);
        final entries = all.where((m) {
          final date = _movementDate(m);
          if (date == null) return false;
          if (product != 'Tümü' && m['product'] != product) return false;
          if (from != null && date.isBefore(DateTime(from!.year, from!.month, from!.day))) return false;
          if (to != null && !date.isBefore(DateTime(to!.year, to!.month, to!.day + 1))) return false;
          return true;
        }).toList();
        final incoming = entries.where((m) => ((m['change'] as num?)?.toDouble() ?? 0) > 0).length;
        final outgoing = entries.where((m) => ((m['change'] as num?)?.toDouble() ?? 0) < 0).length;
        final tracked = names.where((n) => (_namedStock(record, n)['amount'] ?? '').isNotEmpty).toList();
        final low = tracked.where((n) => _stockIsLow(record, n)).toList();
        final critical = low.where((n) => _stockNumber(_namedStock(record, n)['amount']) == 0).toList();
        final inventoryValue = tracked.fold<double>(0, (sum, n) =>
          sum + _stockNumber(_namedStock(record, n)['amount']) *
          (_namedItemTotal(record, n) / (_stockNumber(_namedQuantity(record, n)['amount']) > 0
              ? _stockNumber(_namedQuantity(record, n)['amount']) : 1)));
        final categories = <String, double>{};
        for (final n in tracked) {
          final cat = _namedCategory(record, n);
          final count = _stockNumber(_namedStock(record, n)['amount']);
          final qty = _stockNumber(_namedQuantity(record, n)['amount']);
          final unitPrice = _namedItemTotal(record, n) / (qty > 0 ? qty : 1);
          categories[cat] = (categories[cat] ?? 0) + count * unitPrice;
        }
        final ranked = tracked.toList()..sort((a, b) {
          final sa = _namedStock(record, a);
          final sb = _namedStock(record, b);
          final ra = _stockNumber(sa['minimum']) > 0
              ? _stockNumber(sa['amount']) / _stockNumber(sa['minimum']) : double.infinity;
          final rb = _stockNumber(sb['minimum']) > 0
              ? _stockNumber(sb['amount']) / _stockNumber(sb['minimum']) : double.infinity;
          return ra.compareTo(rb);
        });
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Gelişmiş stok kontrol paneli',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text('${record['title']} • ${tracked.length} stok takipli ürün'),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Tahmini stok değeri: ${_money(inventoryValue)}',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
                Text('Kritik/tükenen: ${critical.length} • Azalan: ${low.length}'),
                const Text('Değerler kayıtlı tahmini birim fiyatlara dayanır; farklı birimler doğrudan toplanmaz.',
                  style: TextStyle(fontSize: 11)),
              ]))),
            const Text('Kategori bazında tahmini stok değeri',
              style: TextStyle(fontWeight: FontWeight.bold)),
            ...categories.entries.map((e) => ListTile(dense: true,
              title: Text(e.key), trailing: Text(_money(e.value)))),
            const Divider(),
            const Text('Kritik stok önceliği', style: TextStyle(fontWeight: FontWeight.bold)),
            ...ranked.take(12).map((n) {
              final st = _namedStock(record, n);
              return ListTile(dense: true, title: Text(n),
                subtitle: Text('Stok: ${st['amount']} • Minimum: ${st['minimum']}'),
                trailing: Icon(_stockIsLow(record, n) ? Icons.warning_amber : Icons.check_circle_outline,
                  color: _stockIsLow(record, n) ? Colors.deepOrange : Colors.green));
            }),
            const Divider(),
            const Text('Hareket filtreleri ve istatistikleri',
              style: TextStyle(fontWeight: FontWeight.bold)),
            DropdownButtonFormField<String>(initialValue: product,
              decoration: const InputDecoration(labelText: 'Ürün'),
              items: ['Tümü', ...names].map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(),
              onChanged: (v) => refresh(() => product = v ?? 'Tümü')),
            Wrap(spacing: 8, children: [
              OutlinedButton(onPressed: () async {
                final d = await showDatePicker(context: ctx,
                  initialDate: from ?? DateTime.now(), firstDate: DateTime(2000), lastDate: DateTime(2100));
                if (d != null) refresh(() => from = d);
              }, child: Text(from == null ? 'Başlangıç tarihi' : '${from!.day}.${from!.month}.${from!.year}')),
              OutlinedButton(onPressed: () async {
                final d = await showDatePicker(context: ctx,
                  initialDate: to ?? DateTime.now(), firstDate: DateTime(2000), lastDate: DateTime(2100));
                if (d != null) refresh(() => to = d);
              }, child: Text(to == null ? 'Bitiş tarihi' : '${to!.day}.${to!.month}.${to!.year}')),
              TextButton(onPressed: () => refresh(() { from = null; to = null; product = 'Tümü'; }),
                child: const Text('Filtreleri temizle')),
            ]),
            Text('${entries.length} hareket • $incoming giriş • $outgoing çıkış'),
            FilledButton.icon(onPressed: () async {
              final rows = <String>['Tarih,Ürün,Önce,Sonra,Değişim,Birim,Açıklama'];
              for (final m in entries) {
                rows.add([m['date'], m['product'], m['before'], m['after'],
                  m['change'], m['unit'], m['reason']].map(_stockCsvCell).join(','));
              }
              await Clipboard.setData(ClipboardData(text: '\uFEFF${rows.join('\r\n')}'));
              if (mounted) _notice('CSV verisi panoya kopyalandı. .csv dosyasına yapıştırabilirsiniz.');
            }, icon: const Icon(Icons.table_chart_outlined),
              label: const Text('Filtrelenmiş CSV verisini kopyala')),
            ...entries.take(100).map((m) => ListTile(dense: true,
              title: Text(m['product']?.toString() ?? ''),
              subtitle: Text('${m['date']} • ${m['reason'] ?? ''}'),
              trailing: Text('${m['change']} ${m['unit'] ?? ''}'))),
          ])));
      }));
  }

  // Aşama 168–177: Geri alınabilir stok hareketleri, sayım ve hedef yönetimi.
  double _stockTarget(Map<String, dynamic> record, String name) {
    final targets = record['stockTargets'];
    final raw = targets is Map ? targets[name] : null;
    return (raw is num ? raw.toDouble() : double.tryParse('$raw')) ?? 0;
  }

  Future<void> _setStockTarget(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final controller = TextEditingController(text: _stockTarget(record, name) == 0
        ? '' : _stockTarget(record, name).toString());
    final ok = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$name • Hedef stok'),
      content: TextField(controller: controller,
        keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Hedef miktar',
          helperText: 'Boş bırakılırsa hedef kaldırılır.')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Kaydet'))],
    ));
    final raw = controller.text.trim().replaceAll(',', '.');
    disposeAfterDialog(controller);
    final value = double.tryParse(raw);
    if (ok != true || !mounted) return;
    if (raw.isNotEmpty && (value == null || !value.isFinite || value < 0)) {
      _notice('Geçerli bir hedef miktar girin.'); return;
    }
    setState(() {
      final targets = record['stockTargets'] is Map
          ? Map<String, dynamic>.from(record['stockTargets'] as Map) : <String, dynamic>{};
      if (raw.isEmpty) { targets.remove(name); } else { targets[name] = value; }
      record['stockTargets'] = targets;
    });
    refresh(() {});
    await _save();
  }

  Future<void> _undoStockMovement(Map<String, dynamic> record, int index,
      void Function(void Function()) refresh) async {
    final movements = _stockMovements(record);
    if (index < 0 || index >= movements.length) return;
    final movement = movements[index];
    if (movement['reversed'] == true) { _notice('Bu hareket zaten geri alınmış.'); return; }
    final name = movement['product']?.toString() ?? '';
    if (!(record['items'] as List? ?? []).contains(name)) {
      _notice('Ürün artık bu listede bulunmuyor.'); return;
    }
    final change = (movement['change'] as num?)?.toDouble() ?? 0;
    final stock = _namedStock(record, name);
    final current = _stockNumber(stock['amount']);
    final next = current - change;
    if (next < 0) { _notice('Geri alma işlemi negatif stok oluşturur.'); return; }
    final approved = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Stok hareketini geri al'),
      content: Text('$name için ${change.toStringAsFixed(2)} miktarlık hareket ters kayıtla düzeltilecek. Mevcut stok: $current'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Geri al'))],
    ));
    if (approved != true || !mounted) return;
    setState(() {
      movements[index]['reversed'] = true;
      movements.insert(0, <String, dynamic>{
        'date': DateTime.now().toIso8601String(), 'product': name,
        'before': current, 'after': next, 'change': -change,
        'reason': 'Hareket geri alma', 'unit': movement['unit'] ?? 'Adet',
        'reversal': true,
      });
      record['stockMovements'] = movements;
      final meta = record['stockMeta'] is Map
          ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
      meta[name] = {...stock, 'amount': next.toString(), 'updated': DateTime.now().toIso8601String()};
      record['stockMeta'] = meta;
    });
    refresh(() {});
    await _save();
  }

  Future<void> _editStockMovementReason(Map<String, dynamic> record, int index,
      void Function(void Function()) refresh) async {
    final movements = _stockMovements(record);
    if (index < 0 || index >= movements.length) return;
    final controller = TextEditingController(text: movements[index]['reason']?.toString() ?? '');
    final ok = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Hareket açıklamasını düzenle'),
      content: TextField(controller: controller, maxLength: 120,
        decoration: const InputDecoration(labelText: 'Açıklama')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Kaydet'))],
    ));
    final reason = controller.text.trim();
    disposeAfterDialog(controller);
    if (ok != true || !mounted) return;
    setState(() {
      movements[index]['reason'] = reason;
      record['stockMovements'] = movements;
    });
    refresh(() {});
    await _save();
  }

  void _showMovementCorrections(Map<String, dynamic> record) {
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final movements = _stockMovements(record);
        return SafeArea(child: FractionallySizedBox(heightFactor: .8,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Hareket düzeltme ve geri alma',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Açıklamalar düzenlenebilir. Miktar hataları ters hareketle düzeltilir; kayıt silinmez.'),
            ...movements.asMap().entries.map((entry) {
              final i = entry.key;
              final m = entry.value;
              return ListTile(title: Text(m['product']?.toString() ?? ''),
                subtitle: Text('${m['date']} • ${m['reason']} • ${m['change']}'),
                trailing: PopupMenuButton<String>(
                  onSelected: (action) {
                    if (action == 'edit') _editStockMovementReason(record, i, refresh);
                    if (action == 'undo') _undoStockMovement(record, i, refresh);
                  }, itemBuilder: (_) => [
                    const PopupMenuItem(value: 'edit', child: Text('Açıklamayı düzenle')),
                    if (m['reversed'] != true && m['reversal'] != true)
                      const PopupMenuItem(value: 'undo', child: Text('Hareketi geri al')),
                  ]),
              );
            }),
          ])));
      }));
  }

  void _showStockCount(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    final actual = <String, double>{};
    final countNote = TextEditingController();
    final controllers = <String, TextEditingController>{};
    for (final name in names) {
      controllers[name] = TextEditingController(text: _namedStock(record, name)['amount'] ?? '');
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final differences = names.where((n) => actual.containsKey(n) &&
            (actual[n]! - _stockNumber(_namedStock(record, n)['amount'])).abs() > 0.000001).toList();
        final counts = (record['stockCounts'] as List? ?? const []).whereType<Map>().toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Stok sayımı ve fark kontrolü',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text(record['title']?.toString() ?? ''),
            TextField(controller: countNote, decoration: const InputDecoration(labelText: 'Sayım açıklaması (isteğe bağlı)')),
            const Text('Fiziksel miktarları girin. Kaydetmeden önce farkları kontrol edin.'),
            ...names.map((name) => ListTile(
              title: Text(name),
              subtitle: Text('Sistem: ${_namedStock(record, name)['amount']?.isEmpty == true ? 'Tanımsız' : _namedStock(record, name)['amount']} • Hedef: ${_stockTarget(record, name)}'),
              trailing: SizedBox(width: 110, child: TextField(controller: controllers[name],
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Fiziksel'),
                onChanged: (v) => refresh(() {
                  final parsed = double.tryParse(v.replaceAll(',', '.'));
                  if (parsed != null && parsed.isFinite && parsed >= 0) {
                    actual[name] = parsed;
                  } else { actual.remove(name); }
                }))),
            )),
            Text('Farklı ürün sayısı: ${differences.length}'),
            ...differences.map((n) => ListTile(
              title: Text(n),
              subtitle: Text('Sistem: ${_namedStock(record, n)['amount']} • Fiziksel: ${actual[n]}'),
              trailing: Text('Fark: ${(actual[n]! - _stockNumber(_namedStock(record, n)['amount'])).toStringAsFixed(2)}'),
            )),
            FilledButton.icon(icon: const Icon(Icons.fact_check_outlined),
              label: const Text('Sayımı kaydet ve stokları eşitle'),
              onPressed: actual.isEmpty ? null : () async {
                final confirm = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                  title: const Text('Stok sayımını kaydet'),
                  content: Text('${actual.length} ürün sayıldı, ${differences.length} üründe fark var. Stok miktarları fiziksel sayımla eşitlenecek.'),
                  actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
                    FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Onayla'))],
                ));
                if (confirm != true || !mounted) return;
                setState(() {
                  final meta = record['stockMeta'] is Map
                      ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
                  final rows = <Map<String, dynamic>>[];
                  for (final entry in actual.entries) {
                    final stock = _namedStock(record, entry.key);
                    final before = _stockNumber(stock['amount']);
                    final after = entry.value;
                    rows.add({'product': entry.key, 'system': before, 'physical': after,
                      'difference': after - before});
                    _recordStockMovement(record, entry.key, before, after, 'Fiziksel stok sayımı');
                    meta[entry.key] = {...stock, 'amount': after.toString(),
                      'updated': DateTime.now().toIso8601String()};
                  }
                  record['stockMeta'] = meta;
                  final history = (record['stockCounts'] as List? ?? const []).toList();
                  history.insert(0, {'date': DateTime.now().toIso8601String(), 'note': countNote.text.trim(), 'rows': rows});
                  record['stockCounts'] = history;
                });
                await _save();
                if (ctx.mounted) Navigator.pop(ctx);
                _notice('Stok sayımı kaydedildi.');
              }),
            const Divider(),
            const Text('Sayım geçmişi', style: TextStyle(fontWeight: FontWeight.bold)),
            if (counts.isEmpty) const Text('Henüz sayım kaydı bulunmuyor.'),
            ...counts.map((count) {
              final rows = (count['rows'] as List? ?? const []).whereType<Map>().toList();
              final date = count['date']?.toString() ?? '';
              return ExpansionTile(title: Text('$date • ${rows.length} ürün'), subtitle: Text(count['note']?.toString() ?? ''), children: [
                ...rows.map((r) => ListTile(title: Text(r['product']?.toString() ?? ''),
                  subtitle: Text('${r['system']} → ${r['physical']}'),
                  trailing: Text('Fark: ${r['difference']}'))),
                TextButton.icon(icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala'),
                  onPressed: () async {
                    final csv = <String>['Ürün,Sistem,Fiziksel,Fark',
                      ...rows.map((r) => [r['product'], r['system'], r['physical'], r['difference']]
                          .map((v) => '"${v.toString().replaceAll('"', '""')}"').join(','))].join('\n');
                    await Clipboard.setData(ClipboardData(text: csv));
                    _notice('Sayım raporu panoya kopyalandı.');
                  }),
              ]);
            }),
          ])));
      }));
  }

  // Aşama 178–187: Sayım notları, filtreler, fark değerleme ve karşılaştırma.
  void _showStockCountAnalytics(Map<String, dynamic> record) {
    String search = '';
    DateTime? from;
    DateTime? until;
    String? firstDate;
    String? secondDate;
    final counts = (record['stockCounts'] as List? ?? const [])
        .whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
    DateTime? parsedDate(Object? value) => DateTime.tryParse(value?.toString() ?? '');
    List<Map<String, dynamic>> rowsOf(Map<String, dynamic> count) =>
        (count['rows'] as List? ?? const []).whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e)).toList();
    double number(Object? value) => double.tryParse(value?.toString() ?? '') ?? 0;
    double unitPrice(String product) {
      final qty = _stockNumber(_namedQuantity(record, product)['amount']);
      return _namedItemTotal(record, product) / (qty > 0 ? qty : 1);
    }
    String dateLabel(Map<String, dynamic> count) => count['date']?.toString() ?? '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final filtered = counts.where((c) {
          final date = parsedDate(c['date']);
          if (from != null && (date == null || date.isBefore(DateTime(from!.year, from!.month, from!.day)))) return false;
          if (until != null && (date == null || !date.isBefore(DateTime(until!.year, until!.month, until!.day + 1)))) return false;
          return search.isEmpty || dateLabel(c).toLowerCase().contains(search) ||
            (c['note']?.toString().toLowerCase().contains(search) ?? false) ||
            rowsOf(c).any((r) => (r['product']?.toString().toLowerCase() ?? '').contains(search));
        }).toList();
        final allRows = filtered.expand(rowsOf).toList();
        final differences = allRows.where((r) => number(r['difference']).abs() > 0.000001).toList();
        final exact = allRows.length - differences.length;
        final accuracy = allRows.isEmpty ? 0.0 : 100 * exact / allRows.length;
        final positive = differences.where((r) => number(r['difference']) > 0).length;
        final negative = differences.where((r) => number(r['difference']) < 0).length;
        final value = differences.fold<double>(0, (sum, r) => sum +
          number(r['difference']).abs() * unitPrice(r['product']?.toString() ?? ''));
        final productDiffs = <String, double>{};
        for (final row in differences) {
          final name = row['product']?.toString() ?? '';
          productDiffs[name] = (productDiffs[name] ?? 0) + number(row['difference']).abs();
        }
        final ranked = productDiffs.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
        final dateOptions = counts.map(dateLabel).toList();
        Map<String, dynamic>? getCount(String? date) {
          if (date == null) return null;
          for (final c in counts) { if (dateLabel(c) == date) return c; }
          return null;
        }
        final older = getCount(firstDate);
        final newer = getCount(secondDate);
        final comparison = <String, List<double>>{};
        if (older != null && newer != null) {
          for (final r in rowsOf(older)) {
            comparison[r['product']?.toString() ?? ''] = [number(r['physical']), double.nan];
          }
          for (final r in rowsOf(newer)) {
            final key = r['product']?.toString() ?? '';
            comparison.putIfAbsent(key, () => [double.nan, double.nan])[1] = number(r['physical']);
          }
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .92, child:
          ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Stok sayım analizleri', style: TextStyle(fontSize: 21, fontWeight: FontWeight.bold, color: _purple)),
            Text(record['title']?.toString() ?? ''),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün, açıklama veya tarih ara'), onChanged: (v) => refresh(() => search = v.toLowerCase().trim())),
            Wrap(spacing: 8, children: [
              OutlinedButton(onPressed: () async {
                final d = await showDatePicker(context: ctx, initialDate: from ?? DateTime.now(),
                  firstDate: DateTime(2020), lastDate: DateTime(2100));
                if (d != null) refresh(() => from = d);
              }, child: Text(from == null ? 'Başlangıç tarihi' : '${from!.day}.${from!.month}.${from!.year}')),
              OutlinedButton(onPressed: () async {
                final d = await showDatePicker(context: ctx, initialDate: until ?? DateTime.now(),
                  firstDate: DateTime(2020), lastDate: DateTime(2100));
                if (d != null) refresh(() => until = d);
              }, child: Text(until == null ? 'Bitiş tarihi' : '${until!.day}.${until!.month}.${until!.year}')),
              TextButton(onPressed: () => refresh(() { from = null; until = null; search = ''; }),
                child: const Text('Tarih filtrelerini temizle')),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Sayım: ${filtered.length} • Kontrol edilen ürün: ${allRows.length}'),
                Text('Eşleşen: $exact • Farklı: ${differences.length} • Uyum: %${accuracy.toStringAsFixed(1)}'),
                Text('Fazla stok: $positive • Eksik stok: $negative'),
                Text('Tahmini mutlak fark değeri: ${_money(value)}'),
                const Text('Değerleme, kayıtlı tahmini birim fiyatlara dayanır.'),
              ]))),
            const Text('En çok fark oluşan ürünler', style: TextStyle(fontWeight: FontWeight.bold)),
            if (ranked.isEmpty) const Text('Seçilen aralıkta stok farkı bulunamadı.'),
            ...ranked.take(15).map((e) => ListTile(title: Text(e.key),
              trailing: Text('Toplam fark: ${e.value.toStringAsFixed(2)}'))),
            const Divider(),
            const Text('Sayım geçmişi ve detayları', style: TextStyle(fontWeight: FontWeight.bold)),
            ...filtered.map((c) {
              final rows = rowsOf(c);
              return ExpansionTile(title: Text(dateLabel(c)),
                subtitle: Text('${rows.length} ürün • ${c['note']?.toString() ?? ''}'),
                children: rows.where((r) => search.isEmpty ||
                  (r['product']?.toString().toLowerCase() ?? '').contains(search) ||
                  dateLabel(c).toLowerCase().contains(search) ||
                  (c['note']?.toString().toLowerCase().contains(search) ?? false))
                  .map((r) => ListTile(title: Text(r['product']?.toString() ?? ''),
                    subtitle: Text('${r['system']} → ${r['physical']}'),
                    trailing: Text('${r['difference']} • ${_money(number(r['difference']).abs() * unitPrice(r['product']?.toString() ?? ''))}'))).toList());
            }),
            const Divider(),
            const Text('İki sayımı karşılaştır', style: TextStyle(fontWeight: FontWeight.bold)),
            if (dateOptions.length < 2) const Text('Karşılaştırma için en az iki sayım kaydı gerekir.'),
            if (dateOptions.length >= 2) ...[
              DropdownButtonFormField<String>(initialValue: firstDate,
                hint: const Text('İlk sayım'), items: dateOptions.map((d) => DropdownMenuItem(value: d, child: Text(d))).toList(),
                onChanged: (v) => refresh(() => firstDate = v)),
              DropdownButtonFormField<String>(initialValue: secondDate,
                hint: const Text('İkinci sayım'), items: dateOptions.map((d) => DropdownMenuItem(value: d, child: Text(d))).toList(),
                onChanged: (v) => refresh(() => secondDate = v)),
              ...comparison.entries.where((e) => e.value.every((v) => v.isFinite)).map((e) =>
                ListTile(title: Text(e.key), subtitle: Text('${e.value[0]} → ${e.value[1]}'),
                  trailing: Text('Δ ${(e.value[1] - e.value[0]).toStringAsFixed(2)}'))),
            ],
            OutlinedButton.icon(icon: const Icon(Icons.copy), label: const Text('Filtreli sayım raporunu CSV kopyala'),
              onPressed: () async {
                final lines = <String>['Tarih,Açıklama,Ürün,Sistem,Fiziksel,Fark,Tahmini Fark TL'];
                for (final c in filtered) {
                  for (final r in rowsOf(c)) {
                    if (search.isNotEmpty && !dateLabel(c).toLowerCase().contains(search) &&
                        !(c['note']?.toString().toLowerCase().contains(search) ?? false) &&
                        !(r['product']?.toString().toLowerCase().contains(search) ?? false)) { continue ; }
                    final vals = <Object?>[dateLabel(c), c['note'], r['product'], r['system'], r['physical'],
                      r['difference'], number(r['difference']).abs() * unitPrice(r['product']?.toString() ?? '')];
                    lines.add(vals.map((v) => '"${(v ?? '').toString().replaceAll('"', '""')}"').join(','));
                  }
                }
                await Clipboard.setData(ClipboardData(text: lines.join('\n')));
                _notice('Filtreli sayım raporu panoya kopyalandı.');
              }),
          ])));
      }));
  }

  void _showStockTargets(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) => SafeArea(
        child: FractionallySizedBox(heightFactor: .8,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Stok hedefleri ve yenileme paneli',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text('${names.length} ürün • hedefi girilen ürünler önceliklidir.'),
            ...names.map((name) {
              final current = _namedStock(record, name);
              final amount = _stockNumber(current['amount']);
              final min = _stockNumber(current['minimum']);
              final target = _stockTarget(record, name);
              final desired = target > 0 ? target : min;
              final shortage = (desired - amount).clamp(0.0, double.infinity);
              return ListTile(
                title: Text(name),
                subtitle: Text('Mevcut: $amount • Minimum: $min • Hedef: $target\nÖnerilen alım: ${shortage.toStringAsFixed(1)}'),
                isThreeLine: true,
                leading: Icon(shortage > 0 ? Icons.warning_amber : Icons.check_circle_outline,
                  color: shortage > 0 ? Colors.deepOrange : Colors.green),
                trailing: IconButton(icon: const Icon(Icons.edit_outlined),
                  onPressed: () => _setStockTarget(record, name, refresh)),
              );
            }),
          ])))));
  }

  // Aşama 188–197: Stok tüketim ve satın alma planlama analizi.
  // Sadece kaydedilmiş negatif stok hareketleri tüketim sayılır;
  // sayım düzeltmeleri ve geri almalar talep tahminini bozmasın diye dışlanır.
  bool _isConsumptionMovement(Map<String, dynamic> movement) {
    final change = (movement['change'] as num?)?.toDouble() ?? 0;
    final reason = (movement['reason'] ?? '').toString().toLowerCase();
    return change < 0 && !reason.contains('sayım') &&
        !reason.contains('düzeltme') && !reason.contains('geri al');
  }

  double _consumedBetween(Map<String, dynamic> record, String name,
      DateTime start, DateTime end) => _stockMovements(record).where((m) {
        final date = _movementDate(m);
        return m['product'] == name && _isConsumptionMovement(m) &&
            date != null && !date.isBefore(start) && date.isBefore(end);
      }).fold<double>(0, (sum, m) =>
          sum - ((m['change'] as num?)?.toDouble() ?? 0));

  double _stockUnitCost(Map<String, dynamic> record, String name) {
    final quantity = _stockNumber(_namedQuantity(record, name)['amount']?.toString());
    return _namedItemTotal(record, name) / (quantity > 0 ? quantity : 1);
  }

  void _showConsumptionPlanning(Map<String, dynamic> record) {
    String query = '';
    String sort = 'En çok tüketilen';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final thisWeek = today.subtract(Duration(days: today.weekday - 1));
        final previousWeek = thisWeek.subtract(const Duration(days: 7));
        final thisMonth = DateTime(now.year, now.month);
        final previousMonth = DateTime(now.year, now.month - 1);
        final nextMonth = DateTime(now.year, now.month + 1);
        final names = (record['items'] as List? ?? const [])
            .map((e) => e.toString()).where((e) =>
                e.toLowerCase().contains(query.toLowerCase())).toList();
        final rows = names.map((name) {
          final week = _consumedBetween(record, name, thisWeek, now.add(const Duration(seconds: 1)));
          final oldWeek = _consumedBetween(record, name, previousWeek, thisWeek);
          final month = _consumedBetween(record, name, thisMonth, nextMonth);
          final oldMonth = _consumedBetween(record, name, previousMonth, thisMonth);
          final movements = _stockMovements(record).where((m) =>
              m['product'] == name && _isConsumptionMovement(m) &&
              _movementDate(m) != null).toList();
          final oldest = movements.isEmpty ? null : movements.map((m) =>
              _movementDate(m)!).reduce((a, b) => a.isBefore(b) ? a : b);
          final days = oldest == null ? 0.0 :
              (now.difference(oldest).inMinutes / 1440).clamp(1.0, double.infinity);
          final total = movements.fold<double>(0, (sum, m) =>
              sum - ((m['change'] as num?)?.toDouble() ?? 0));
          final rate = days == 0 ? 0.0 : total / days;
          final stock = _namedStock(record, name);
          final amount = _stockNumber(stock['amount']);
          final minimum = _stockNumber(stock['minimum']);
          final target = _stockTarget(record, name);
          final monthlyNeed = rate * 30;
          final desired = [minimum, target, monthlyNeed].reduce((a, b) => a > b ? a : b);
          final buy = (desired - amount).clamp(0.0, double.infinity);
          final cost = _stockUnitCost(record, name);
          return <String, dynamic>{'name': name, 'week': week, 'oldWeek': oldWeek,
            'month': month, 'oldMonth': oldMonth, 'total': total,
            'rate': rate, 'amount': amount, 'buy': buy, 'cost': cost,
            'monthlyNeed': monthlyNeed, 'hasHistory': movements.isNotEmpty,
            'unit': _namedQuantity(record, name)['unit']?.toString() ?? 'adet'};
        }).toList();
        rows.sort((a, b) {
          if (sort == 'Ürün A–Z') { return (a['name'] as String).compareTo(b['name'] as String); }
          if (sort == 'Yenileme maliyeti') {
            return
              ((b['buy'] as double) * (b['cost'] as double)).compareTo(
                  (a['buy'] as double) * (a['cost'] as double));
          }
          return (b['total'] as double).compareTo(a['total'] as double);
        });
        final totalCost = rows.fold<double>(0, (sum, r) =>
            sum + (r['buy'] as double) * (r['cost'] as double));
        final tracked = rows.where((r) => r['hasHistory'] == true).length;
        String trend(double current, double previous) {
          if (previous == 0) return current > 0 ? 'Yeni tüketim' : 'Veri yok';
          final percent = (current - previous) / previous * 100;
          return '${percent >= 0 ? '+' : ''}${percent.toStringAsFixed(0)}%';
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Tüketim ve satın alma planlama',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text(record['title']?.toString() ?? ''),
            const SizedBox(height: 8),
            TextField(decoration: const InputDecoration(
              labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => query = v)),
            DropdownButtonFormField<String>(initialValue: sort,
              decoration: const InputDecoration(labelText: 'Sıralama'),
              items: ['En çok tüketilen', 'Yenileme maliyeti', 'Ürün A–Z']
                  .map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
              onChanged: (v) => refresh(() => sort = v ?? sort)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Tüketim kaydı olan ürün: $tracked / ${rows.length}'),
                Text('Tahmini yenileme maliyeti: ${_money(totalCost)}',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
                const Text('Plan: 30 günlük tahmini ihtiyaç, minimum ve hedef stoktan en yüksek olanı esas alır.'),
              ]))),
            const Text('Ürün bazında tüketim ve fiyat geçmişi',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (rows.isEmpty) const ListTile(title: Text('Ürün bulunamadı.')),
            ...rows.map((r) {
              final name = r['name'] as String;
              final unit = r['unit'] as String;
              final week = r['week'] as double;
              final oldWeek = r['oldWeek'] as double;
              final month = r['month'] as double;
              final oldMonth = r['oldMonth'] as double;
              final rate = r['rate'] as double;
              final amount = r['amount'] as double;
              final buy = r['buy'] as double;
              final cost = r['cost'] as double;
              return Card(child: ExpansionTile(
                title: Text(name),
                subtitle: Text('Bu ay: ${month.toStringAsFixed(1)} $unit • '
                  'Önerilen alım: ${buy.toStringAsFixed(1)} $unit'),
                trailing: Text(_money(buy * cost)),
                childrenPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                children: [
                  Text('Haftalık tüketim: ${week.toStringAsFixed(2)} $unit '
                    '(önceki hafta: ${oldWeek.toStringAsFixed(2)}) • ${trend(week, oldWeek)}'),
                  Text('Aylık tüketim: ${month.toStringAsFixed(2)} $unit '
                    '(önceki ay: ${oldMonth.toStringAsFixed(2)}) • ${trend(month, oldMonth)}'),
                  Text('Ortalama günlük: ${rate.toStringAsFixed(2)} $unit'),
                  Text('30 günlük ihtiyaç: ${(r['monthlyNeed'] as double).toStringAsFixed(1)} $unit'),
                  Text('Mevcut stok: ${amount.toStringAsFixed(1)} $unit'),
                  Text('Tahmini bitiş: ${rate > 0 ? '${(amount / rate).ceil()} gün' : 'Yeterli tüketim verisi yok'}'),
                  Text('Tahmini birim maliyet: ${_money(cost)}'),
                  Text('Bu ay tüketim maliyeti: ${_money(month * cost)}'),
                  Text('Önerilen yenileme: ${buy.toStringAsFixed(1)} $unit • ${_money(buy * cost)}'),
                  if (r['hasHistory'] != true)
                    const Text('Tahmin için stok çıkış kaydı oluşturulmalı.',
                      style: TextStyle(color: Colors.deepOrange)),
                  const SizedBox(height: 6),
                  const Text('Geçmiş tüketim hareketleri',
                    style: TextStyle(fontWeight: FontWeight.bold)),
                  ..._stockMovements(record).where((m) =>
                      m['product'] == name && _isConsumptionMovement(m))
                      .take(8).map((m) => ListTile(dense: true,
                        title: Text(m['reason']?.toString() ?? 'Stok çıkışı'),
                        subtitle: Text(m['date']?.toString().split('T').first ?? ''),
                        trailing: Text('${m['change']} $unit'))),
                ],
              ));
            }),
            const SizedBox(height: 8),
            const Text('Tahminler kaydedilen stok çıkışlarından hesaplanır; '
              'farklı ürünlerin birimleri birbiriyle toplanmaz. '
              'Fiyatlar güncel kayıtlı tahmini birim fiyatlardır.',
              style: TextStyle(fontSize: 12)),
          ])));
      }));
  }

  // Aşama 7648–7897: Birden çok ürünü tek işlemde hedef stoğa tamamlama.
  // Stok hareketleri mevcut kayıt biçiminde saklanır; yeni veri anahtarı yoktur.
  void _showBulkStockReplenishment(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? const [])
        .map((e) => e.toString()).toSet().toList();
    final selected = <String>{};
    bool onlyBelowTarget = true;
    String search = '';
    double targetFor(String name) {
      final explicit = _stockTarget(record, name);
      final minimum = _stockNumber(_namedStock(record, name)['minimum']);
      return explicit > 0 ? explicit : minimum;
    }
    bool eligible(String name) {
      final stock = _namedStock(record, name);
      final raw = stock['amount'] ?? '';
      final target = targetFor(name);
      return raw.isNotEmpty && target > 0 &&
          _stockNumber(raw) >= 0 && _stockNumber(raw) < target;
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final eligibleNames = names.where(eligible).toList();
        final visible = names.where((name) =>
            (!onlyBelowTarget || eligible(name)) &&
            name.toLowerCase().contains(search.toLowerCase())).toList();
        final actionable = selected.where(eligible).toList();
        final totalAddition = actionable.fold<double>(0, (sum, name) => sum +
            (targetFor(name) - _stockNumber(_namedStock(record, name)['amount'])));
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Toplu stok yenileme', style: TextStyle(
                fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text(record['title']?.toString() ?? ''),
            const SizedBox(height: 8),
            const Text('Hedef stok varsa hedefe, yoksa minimum seviyeye tamamlar. '
                'Miktarı tanımsız ürünler değiştirilmez. Birimler ürün bazında korunur.'),
            TextField(decoration: const InputDecoration(
                prefixIcon: Icon(Icons.search), labelText: 'Ürün ara'),
              onChanged: (value) => refresh(() => search = value)),
            SwitchListTile(title: const Text('Yalnızca yenilenmesi gerekenler'),
              value: onlyBelowTarget,
              onChanged: (value) => refresh(() => onlyBelowTarget = value)),
            Text('${eligibleNames.length} ürün yenilenebilir • ${actionable.length} seçili'),
            Wrap(spacing: 8, children: [
              OutlinedButton.icon(icon: const Icon(Icons.select_all),
                label: const Text('Görünen uygunları seç'),
                onPressed: () => refresh(() {
                  selected.addAll(visible.where(eligible));
                })),
              OutlinedButton.icon(icon: const Icon(Icons.clear_all),
                label: const Text('Seçimi temizle'),
                onPressed: () => refresh(selected.clear)),
            ]),
            if (visible.isEmpty) const ListTile(
              title: Text('Bu filtrede ürün bulunamadı.')),
            ...visible.map((name) {
              final stock = _namedStock(record, name);
              final canUpdate = eligible(name);
              final current = stock['amount'] ?? '';
              final target = targetFor(name);
              final unit = _namedQuantity(record, name)['unit'] ?? 'Adet';
              return CheckboxListTile(
                value: selected.contains(name),
                onChanged: canUpdate ? (value) => refresh(() {
                  if (value == true) { selected.add(name); }
                  else { selected.remove(name); }
                }) : null,
                title: Text(name),
                subtitle: Text('Mevcut: ${current.isEmpty ? 'Tanımsız' : current} $unit'
                    ' • Hedef: $target $unit'
                    '${canUpdate ? ' • Eklenecek: ${(target - _stockNumber(current)).toStringAsFixed(2)} $unit' : ' • İşlem gerekmiyor'}'),
              );
            }),
            const Divider(),
            Text('${actionable.length} ürün için stok girişi hazırlanıyor.'),
            const Text('Farklı birimlerdeki miktarlar birbiriyle toplanmaz.'),
            if (actionable.isNotEmpty)
              Text('Sayısal farklar toplamı (yalnızca bilgi): ${totalAddition.toStringAsFixed(2)}'),
            FilledButton.icon(icon: const Icon(Icons.inventory_2_outlined),
              label: const Text('Seçilen ürünleri hedefe tamamla'),
              onPressed: actionable.isEmpty ? null : () async {
                // Önizleme ve onaydan önce hedefler tekrar hesaplanır.
                final pending = selected.where(eligible).toList();
                if (pending.isEmpty) { refresh(() {}); return; }
                final confirmed = await showDialog<bool>(context: ctx,
                  builder: (dialog) => AlertDialog(
                    title: const Text('Toplu stok girişini onayla'),
                    content: Text('${pending.length} ürün hedef stok seviyesine tamamlanacak. '
                        'Her ürün için ayrı stok hareketi oluşturulacak. '
                        'Mevcut alışveriş listesi değişmeyecek.'),
                    actions: [
                      TextButton(onPressed: () => Navigator.pop(dialog, false),
                        child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, true),
                        child: const Text('Onayla')),
                    ],
                  ));
                if (confirmed != true || !mounted) return;
                var changed = 0;
                setState(() {
                  final meta = record['stockMeta'] is Map
                      ? Map<String, dynamic>.from(record['stockMeta'] as Map)
                      : <String, dynamic>{};
                  for (final name in pending) {
                    if (!eligible(name)) continue;
                    final old = _namedStock(record, name);
                    final before = _stockNumber(old['amount']);
                    final after = targetFor(name);
                    _recordStockMovement(record, name, before, after,
                        'Toplu hedef stok yenileme');
                    meta[name] = {...old, 'amount': after.toString(),
                      'updated': DateTime.now().toIso8601String()};
                    changed++;
                  }
                  record['stockMeta'] = meta;
                  record['updated'] = DateTime.now().toIso8601String();
                });
                await _save();
                if (ctx.mounted) Navigator.pop(ctx);
                _notice('$changed ürünün stoku hedef seviyeye tamamlandı.');
              }),
          ])));
      }),
    );
  }

  // Aşama 138–147: Stok seviyesi, minimum eşik ve alışverişe aktarım.
  double _stockNumber(String? value) =>
      double.tryParse((value ?? '').replaceAll(',', '.')) ?? 0;

  bool _stockIsLow(Map<String, dynamic> record, String name) {
    final stock = _namedStock(record, name);
    if ((stock['minimum'] ?? '').isEmpty || (stock['amount'] ?? '').isEmpty) return false;
    return _stockNumber(stock['amount']) <= _stockNumber(stock['minimum']);
  }

  Future<void> _editStockLevels(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final existing = _namedStock(record, name);
    final amount = TextEditingController(text: existing['amount']);
    final minimum = TextEditingController(text: existing['minimum']);
    final accepted = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
      title: Text('$name • Stok miktarı'),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: amount, keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(labelText: 'Mevcut stok miktarı')),
        TextField(controller: minimum, keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(labelText: 'Minimum stok miktarı')),
        const SizedBox(height: 8),
        const Text('Miktarlar ürünün kayıtlı birimiyle değerlendirilir.'),
      ]),
      actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final a = double.tryParse(amount.text.trim().replaceAll(',', '.'));
          final m = double.tryParse(minimum.text.trim().replaceAll(',', '.'));
          if ((amount.text.trim().isEmpty || (a != null && a >= 0 && a.isFinite)) &&
              (minimum.text.trim().isEmpty || (m != null && m >= 0 && m.isFinite))) {
            Navigator.pop(dialog, true);
          }
        }, child: const Text('Kaydet'))],
    ));
    final a = amount.text.trim().replaceAll(',', '.');
    final m = minimum.text.trim().replaceAll(',', '.');
    disposeAfterDialog(amount); disposeAfterDialog(minimum);
    if (accepted != true || !mounted) return;
    setState(() {
      final meta = record['stockMeta'] is Map
          ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
      if (a.isNotEmpty) {
        _recordStockMovement(record, name,
          _stockNumber(existing['amount']), _stockNumber(a), 'Manuel stok düzeltmesi');
      }
      meta[name] = {...existing, 'amount': a, 'minimum': m,
        'updated': DateTime.now().toIso8601String()};
      record['stockMeta'] = meta;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  Future<void> _adjustStock(Map<String, dynamic> record, String name, double change,
      void Function(void Function()) refresh) async {
    final existing = _namedStock(record, name);
    if ((existing['amount'] ?? '').isEmpty) {
      _notice('Önce stok miktarını tanımlayın.');
      return;
    }
    final next = (_stockNumber(existing['amount']) + change).clamp(0.0, double.infinity);
    setState(() {
      final meta = record['stockMeta'] is Map
          ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
      _recordStockMovement(record, name, _stockNumber(existing['amount']),
          next.toDouble(), change > 0 ? 'Stok girişi' : 'Stok çıkışı');
      meta[name] = {...existing, 'amount': next.toString(),
        'updated': DateTime.now().toIso8601String()};
      record['stockMeta'] = meta;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  Future<void> _addLowStockToActive(Map<String, dynamic> record) async {
    final names = (record['items'] as List? ?? []).map((e) => e.toString())
        .where((name) => _stockIsLow(record, name)).toList();
    if (names.isEmpty) { _notice('Minimum seviyeye ulaşan ürün bulunamadı.'); return; }
    final approved = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
      title: const Text('Eksilen ürünleri alışverişe ekle'),
      content: Text('${names.length} ürün aktif alışveriş listesine eklenecek. Mevcut ürünler tekrar eklenmez.'),
      actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Ekle'))],
    ));
    if (approved != true || !mounted) return;
    int added = 0;
    setState(() {
      for (final name in names) {
        if (!_items.contains(name)) { _items.add(name); added++; }
      }
    });
    await _save();
    _notice('$added ürün aktif alışveriş listesine eklendi.');
  }

  void _showLowStockSummary(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    final tracked = names.where((n) => (_namedStock(record, n)['amount'] ?? '').isNotEmpty).toList();
    final low = names.where((n) => _stockIsLow(record, n)).toList();
    final depleted = tracked.where((n) => _stockNumber(_namedStock(record, n)['amount']) == 0).toList();
    final untracked = names.length - tracked.length;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .8,
        child: ListView(padding: const EdgeInsets.all(16), children: [
          const Text('Stok kontrol paneli', style: TextStyle(fontSize: 21, fontWeight: FontWeight.bold)),
          Text('${names.length} ürün • ${tracked.length} stok kayıtlı • ${low.length} azalan • ${depleted.length} tükenen • $untracked takipsiz'),
          const Divider(),
          if (low.isEmpty) const ListTile(title: Text('Minimum seviyeye ulaşan ürün yok.')),
          ...low.map((name) {
            final stock = _namedStock(record, name);
            return ListTile(leading: const Icon(Icons.warning_amber_rounded, color: Colors.deepOrange),
              title: Text(name), subtitle: Text('Mevcut: ${stock['amount']} • Minimum: ${stock['minimum']} • ${_namedQuantity(record, name)['unit']}'),
              trailing: Text(stock['updated']?.isEmpty == true ? '' : 'Güncellendi'));
          }),
          const Divider(),
          FilledButton.icon(onPressed: () async {
            Navigator.pop(ctx);
            await _addLowStockToActive(record);
          }, icon: const Icon(Icons.add_shopping_cart), label: const Text('Azalan ürünleri alışverişe ekle')),
          TextButton.icon(onPressed: () {
            final report = 'Stok özeti\n${record['title']}\n'
                '${low.map((n) => '$n: ${_namedStock(record, n)['amount']} / min ${_namedStock(record, n)['minimum']}').join('\n')}';
            Clipboard.setData(ClipboardData(text: report));
            _notice('Stok özeti panoya kopyalandı.');
          }, icon: const Icon(Icons.copy), label: const Text('Azalan stok raporunu kopyala')),
        ]))));
  }

  void _showStockSummary(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    final dated = names.where((name) => _expiryDays(record, name) != null).toList()
      ..sort((a, b) => _expiryDays(record, a)!.compareTo(_expiryDays(record, b)!));
    final urgent = dated.where((name) => _expiryDays(record, name)! <= 7).toList();
    final places = <String, int>{};
    for (final name in names) {
      final place = _namedStock(record, name)['storage'] ?? 'Belirtilmedi';
      places[place] = (places[place] ?? 0) + 1;
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .82,
        child: ListView(padding: const EdgeInsets.all(18), children: [
          const Text('Gıda ve ürün takip özeti', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          Text('${names.length} ürün • ${dated.length} SKT kayıtlı • ${urgent.length} ürünün SKT’si 7 gün içinde veya geçmiş'),
          const SizedBox(height: 12),
          const Text('Saklama yerleri', style: TextStyle(fontWeight: FontWeight.bold)),
          ...places.entries.map((e) => ListTile(dense: true, title: Text(e.key), trailing: Text('${e.value} ürün'))),
          const Divider(),
          const Text('Son kullanma tarihine göre', style: TextStyle(fontWeight: FontWeight.bold)),
          if (dated.isEmpty) const ListTile(title: Text('Henüz son kullanma tarihi girilmedi.')),
          ...dated.map((name) => ListTile(
            leading: Icon(Icons.event_note, color: _expiryDays(record, name)! <= 7 ? Colors.red : _purple),
            title: Text(name), subtitle: Text(_expiryLabel(record, name)),
            trailing: Text(_namedStock(record, name)['storage'] ?? ''))),
          const SizedBox(height: 12),
          const Text('Bilgilendirme: SKT uyarıları yalnızca bu ekran açıldığında gösterilir; bildirim gönderilmez.'),
        ]))));
  }

  // Aşama 8648–8897: SKT, tüketim önceliği ve israf riskini birlikte yönet.
  // Yalnızca mevcut stok ve hareketleri okur; kayıtları kendiliğinden değiştirmez.
  // Aşama 8898–9147: Tarif / stok eşleştirme asistanı.
  // Yalnızca aynı birim ailesindeki miktarlar karşılaştırılır; tanımsız stok
  // ve SKT geçmiş ürünler otomatik olarak kullanılabilir sayılmaz.
  void _showRecipeStockAssistant(Map<String, dynamic> record) {
    String query = '';
    String filter = 'Tümü';
    int portions = 2;
    bool onlyExpiring = false;
    final selected = <String>{};
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();

    Map<String, dynamic> evaluate(Map<String, dynamic> recipe) {
      final parts = <Map<String, dynamic>>[];
      var missing = 0;
      var expiring = 0;
      var ready = 0;
      var unknown = 0;
      for (final raw in (recipe['ingredients'] as List? ?? []).whereType<Map>()) {
        final ingredient = raw['name']?.toString().trim() ?? '';
        final unit = raw['unit']?.toString() ?? 'adet';
        final required = _planNum(raw['quantity']) * portions;
        if (ingredient.isEmpty || required <= 0) continue;
        final matching = names.where((n) => _normalizeName(n) == _normalizeName(ingredient)).toList();
        String status = 'Stok bulunamadı';
        double available = 0;
        String? product;
        int? days;
        for (final name in matching) {
          final meta = _namedStock(record, name);
          final amountText = meta['amount'] ?? '';
          final savedUnit = _namedQuantity(record, name)['unit']?.toString() ?? '';
          if (amountText.trim().isEmpty || !_units.contains(savedUnit)) {
            status = 'Miktar veya birim tanımsız';
            continue;
          }
          final quantity = double.tryParse(amountText.replaceAll(',', '.'));
          if (quantity == null || !quantity.isFinite || quantity < 0) {
            status = 'Geçersiz stok';
            continue;
          }
          final needCanonical = _canonicalKitchenQuantity(required, unit);
          final haveCanonical = _canonicalKitchenQuantity(quantity, savedUnit);
          if (needCanonical['unit'] != haveCanonical['unit']) {
            status = 'Birim uyuşmuyor';
            continue;
          }
          product = name;
          available = _planNum(haveCanonical['quantity']);
          days = _expiryDays(record, name);
          final need = _planNum(needCanonical['quantity']);
          status = days != null && days < 0 ? 'SKT geçmiş' :
              available >= need ? 'Yeterli' : 'Eksik';
          break;
        }
        if (status == 'Yeterli') ready++;
        if (status == 'Eksik' || status == 'Stok bulunamadı') missing++;
        if (status != 'Yeterli' && status != 'Eksik' && status != 'Stok bulunamadı') unknown++;
        if (days != null && days >= 0 && days <= 3 && status == 'Yeterli') expiring++;
        parts.add({'name': ingredient, 'unit': unit, 'required': required,
          'available': available, 'product': product, 'status': status, 'days': days});
      }
      return {'recipe': recipe, 'parts': parts, 'ready': ready, 'missing': missing,
        'unknown': unknown, 'expiring': expiring,
        'complete': parts.isNotEmpty && ready == parts.length};
    }

    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        final results = _customRecipes.map(evaluate).where((r) {
          final recipe = r['recipe'] as Map<String, dynamic>;
          final text = '${recipe['name']} ${(r['parts'] as List).map((p) => p['name']).join(' ')}'.toLowerCase();
          if (!text.contains(query.toLowerCase())) return false;
          if (onlyExpiring && (r['expiring'] as int) == 0) return false;
          if (filter == 'Hazır' && r['complete'] != true) return false;
          if (filter == 'Eksik' && (r['missing'] as int) == 0) return false;
          if (filter == 'Kontrol gerekli' && (r['unknown'] as int) == 0) return false;
          return true;
        }).toList()..sort((a,b) {
          final expiry = (b['expiring'] as int).compareTo(a['expiring'] as int);
          return expiry != 0 ? expiry : (b['ready'] as int).compareTo(a['ready'] as int);
        });
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Tarif ve stok mutfak asistanı', style: TextStyle(
              fontSize: 21, fontWeight: FontWeight.bold, color: _purple)),
            Text('${record['title'] ?? 'Liste'} • ${_customRecipes.length} kişisel tarif'),
            const Text('Yalnızca bu listedeki stoklar değerlendirilir. Birim uyuşmazlığı ve geçmiş SKT otomatik tüketilmez.'),
            Wrap(spacing: 8, children: [1,2,3,4,6,8].map((n) => ChoiceChip(
              label: Text('$n porsiyon'), selected: portions == n,
              onSelected: (_) => refresh(() {portions = n; selected.clear();}))).toList()),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Tarif veya malzeme ara'),
              onChanged: (v) => refresh(() => query = v)),
            DropdownButtonFormField<String>(initialValue: filter,
              decoration: const InputDecoration(labelText: 'Tarif durumu'),
              items: ['Tümü','Hazır','Eksik','Kontrol gerekli'].map((v) =>
                DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) => refresh(() => filter = v ?? 'Tümü')),
            SwitchListTile(title: const Text('SKT yaklaşan ürünleri kullanan tarifler'),
              value: onlyExpiring, onChanged: (v) => refresh(() => onlyExpiring = v)),
            Text('Görüntülenen tarif: ${results.length} • Hazır: ${results.where((r) => r['complete'] == true).length}'),
            if (_customRecipes.isEmpty) const Text('Önce Kendi Tariflerim bölümünden malzemeli tarif oluşturun.'),
            ...results.map((r) {
              final recipe = r['recipe'] as Map<String, dynamic>;
              final title = recipe['name']?.toString() ?? 'Tarif';
              final parts = r['parts'] as List<Map<String, dynamic>>;
              return Card(child: ExpansionTile(
                title: Text(title),
                subtitle: Text('Hazır ${r['ready']}/${parts.length} • Eksik ${r['missing']} • '
                  'Kontrol ${r['unknown']} • SKT öncelikli ${r['expiring']}'),
                children: [
                  ...parts.map((part) => ListTile(dense: true,
                    title: Text('${part['name']} • ${_planNum(part['required']).toStringAsFixed(2)} ${part['unit']}'),
                    subtitle: Text('${part['status']} • Eşleşen: ${part['product'] ?? 'Yok'}'
                      '${part['days'] == null ? '' : ' • SKT ${part['days']} gün'}'),
                  )),
                  Wrap(spacing: 6, children: [
                    OutlinedButton.icon(onPressed: () async {
                      final needed = parts.where((p) => p['status'] == 'Eksik' ||
                        p['status'] == 'Stok bulunamadı').toList();
                      final existing = _items.map(_normalizeName).toSet();
                      final additions = needed.where((p) => !existing.contains(
                        _normalizeName(p['name'].toString()))).toList();
                      if (additions.isEmpty) {
                        _notice('Eklenecek yeni malzeme yok. Mevcut ürünler değiştirilmedi.'); return;
                      }
                      final yes = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
                        title: const Text('Eksikleri alışverişe ekle'),
                        content: Text('${additions.length} yeni ürün eklenecek. Miktar ve birimleri notta gösterilecek.'),
                        actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                          FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Ekle'))]));
                      if (yes != true || !mounted) return;
                      setState(() {
                        for (final part in additions) {
                          final name = part['name'].toString();
                          if (_items.any((n) => _normalizeName(n) == _normalizeName(name))) continue;
                          _items.add(name);
                          _details[name] = {'note': '$title için ${_planNum(part['required']).toStringAsFixed(2)} ${part['unit']} gerekli'};
                        }
                      });
                      await _save();
                      _notice('${additions.length} malzeme alışveriş listesine eklendi.');
                    }, icon: const Icon(Icons.add_shopping_cart),
                      label: const Text('Eksikleri alışverişe ekle')),
                    FilledButton.tonalIcon(onPressed: r['complete'] != true ? null : () async {
                      final yes = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
                        title: const Text('Tarif malzemelerini tüket'),
                        content: Text('$title • $portions porsiyon. ${parts.length} ürünün stoku düşülecek ve hareket kaydı oluşturulacak.'),
                        actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                          FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Onayla'))]));
                      if (yes != true || !mounted) return;
                      // Confirm sonrası stokları yeniden değerlendir; başka işlem yapıldıysa dur.
                      final latest = evaluate(recipe);
                      if (latest['complete'] != true) {
                        _notice('Stok değişti; işlemi yeniden kontrol edin.'); refresh(() {}); return;
                      }
                      final currentParts = latest['parts'] as List<Map<String, dynamic>>;
                      final deductions = <String, double>{};
                      for (final part in currentParts) {
                        final product = part['product']?.toString();
                        if (product == null) return;
                        final stockUnit = _namedQuantity(record, product)['unit']?.toString() ?? '';
                        final requiredCanonical = _canonicalKitchenQuantity(
                          _planNum(part['required']), part['unit'].toString());
                        final oneCanonical = _canonicalKitchenQuantity(1, stockUnit);
                        if (oneCanonical['unit'] != requiredCanonical['unit']) return;
                        deductions[product] = (deductions[product] ?? 0) +
                          _planNum(requiredCanonical['quantity']) / _planNum(oneCanonical['quantity']);
                      }
                      for (final entry in deductions.entries) {
                        if (_stockNumber(_namedStock(record, entry.key)['amount']) + 0.000001 < entry.value) {
                          _notice('Yetersiz stok: ${entry.key}'); return;
                        }
                      }
                      setState(() {
                        final meta = record['stockMeta'] is Map
                          ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
                        for (final entry in deductions.entries) {
                          final old = _namedStock(record, entry.key);
                          final before = _stockNumber(old['amount']);
                          final after = (before - entry.value).clamp(0.0, double.infinity).toDouble();
                          _recordStockMovement(record, entry.key, before, after,
                            'Tarif tüketimi: $title ($portions porsiyon)');
                          meta[entry.key] = {...old, 'amount': after.toString(),
                            'updated': DateTime.now().toIso8601String()};
                        }
                        record['stockMeta'] = meta;
                        record['updated'] = DateTime.now().toIso8601String();
                      });
                      await _save();
                      if (sheet.mounted) refresh(() {});
                      _notice('$title için stok tüketimi kaydedildi.');
                    }, icon: const Icon(Icons.restaurant), label: const Text('Tarifi hazırla / stoktan düş')),
                    TextButton.icon(onPressed: () async {
                      final csv = <String>['Malzeme;Miktar;Birim;Durum;Stok ürünü;SKT gün',
                        ...parts.map((p) => '${_planCsvCell(p['name'])};${p['required']};'
                          '${_planCsvCell(p['unit'])};${_planCsvCell(p['status'])};'
                          '${_planCsvCell(p['product'] ?? '')};${p['days'] ?? ''}')].join('\n');
                      await Clipboard.setData(ClipboardData(text: csv));
                      _notice('Tarif stok raporu panoya kopyalandı.');
                    }, icon: const Icon(Icons.copy), label: const Text('Malzeme raporu')),
                  ]),
                ],
              ));
            }),
          ])));
      }));
  }

  void _showExpiryIntelligence(Map<String, dynamic> record) {
    String query = '';
    String filter = 'Tümü';
    String place = 'Tümü';
    String order = 'SKT (erken önce)';
    int horizon = 7;
    bool onlyInStock = true;
    final filters = <String>['Tümü', 'Geçmiş', 'Bugün', 'Yaklaşıyor', 'Güvenli', 'SKT yok', 'İsraf riski'];
    final orders = <String>['SKT (erken önce)', 'SKT (geç önce)', 'Stok (çok önce)', 'İsim'];
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final names = (record['items'] as List? ?? const [])
            .map((e) => e.toString()).toSet().toList();
        final places = <String>{'Tümü', ...names.map((n) =>
            _namedStock(record, n)['storage'] ?? 'Belirtilmedi')}.toList()..sort();
        final today = DateTime.now();
        final start = DateTime(today.year, today.month, today.day);
        double amount(String n) => _stockNumber(_namedStock(record, n)['amount']);
        int? days(String n) => _expiryDays(record, n);
        double rate(String n) => _consumptionPerDay(record, n);
        double predictedWaste(String n) {
          final d = days(n);
          if (d == null || amount(n) <= 0) return 0;
          final usableDays = d < 0 ? 0.0 : d.toDouble() + 1;
          final possibleUse = rate(n) * usableDays;
          return (amount(n) - possibleUse).clamp(0.0, double.infinity).toDouble();
        }
        bool risk(String n) => days(n) != null && days(n)! <= horizon &&
            predictedWaste(n) > 0.000001 && rate(n) > 0;
        String status(String n) {
          final d = days(n);
          if (d == null) return 'SKT yok';
          if (d < 0) return 'Geçmiş';
          if (d == 0) return 'Bugün';
          if (d <= horizon) return 'Yaklaşıyor';
          return 'Güvenli';
        }
        final filtered = names.where((n) {
          if (onlyInStock && amount(n) <= 0) return false;
          if (query.isNotEmpty && !n.toLowerCase().contains(query.toLowerCase())) return false;
          if (place != 'Tümü' && _namedStock(record, n)['storage'] != place) return false;
          if (filter == 'İsraf riski') return risk(n);
          return filter == 'Tümü' || status(n) == filter;
        }).toList();
        filtered.sort((a, b) {
          if (order == 'İsim') return a.toLowerCase().compareTo(b.toLowerCase());
          if (order == 'Stok (çok önce)') return amount(b).compareTo(amount(a));
          final da = days(a) ?? 999999;
          final db = days(b) ?? 999999;
          return order == 'SKT (geç önce)' ? db.compareTo(da) : da.compareTo(db);
        });
        final expired = names.where((n) => amount(n) > 0 && (days(n) ?? 999999) < 0).length;
        final urgent = names.where((n) => amount(n) > 0 &&
            (days(n) ?? 999999) >= 0 && (days(n) ?? 999999) <= horizon).length;
        final noDate = names.where((n) => amount(n) > 0 && days(n) == null).length;
        final atRisk = names.where(risk).length;
        Future<void> copyReport() async {
          String cell(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
          final lines = <String>[
            ['Ürün','Stok','Saklama','SKT','Kalan gün','Durum','Günlük tüketim','SKT öncesi tahmini tüketim','İsraf riski miktarı']
                .map(cell).join(';'),
            ...filtered.map((n) {
              final d = days(n);
              final possible = d == null ? 0.0 : rate(n) * (d < 0 ? 0 : d + 1);
              return [n, amount(n), _namedStock(record,n)['storage'],
                _namedStock(record,n)['expiry'], d ?? '', status(n),
                rate(n).toStringAsFixed(3), possible.toStringAsFixed(2),
                rate(n) > 0 ? predictedWaste(n).toStringAsFixed(2) : 'Veri yetersiz']
                .map(cell).join(';');
            }),
          ];
          await Clipboard.setData(ClipboardData(text: lines.join('\n')));
          if (mounted) _notice('SKT raporu CSV biçiminde panoya kopyalandı.');
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .93,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı SKT ve israf önleme',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 6),
            const Text('Stoklar, SKT ve geçmiş tüketim birlikte değerlendirilir. Otomatik stok düşümü yapılmaz.'),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 6, children: [
              Chip(label: Text('Geçmiş: $expired')),
              Chip(label: Text('$horizon gün içinde: $urgent')),
              Chip(label: Text('SKT eksik: $noDate')),
              Chip(label: Text('Tahmini israf riski: $atRisk')),
            ]),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün ara'), onChanged: (v) => refresh(() => query = v.trim())),
            const SizedBox(height: 8),
            Wrap(spacing: 8, runSpacing: 4, children: [
              DropdownButton<String>(value: filter, items: filters.map((v) =>
                DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) => refresh(() => filter = v ?? 'Tümü')),
              DropdownButton<String>(value: place, items: places.map((v) =>
                DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) => refresh(() => place = v ?? 'Tümü')),
              DropdownButton<String>(value: order, items: orders.map((v) =>
                DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) => refresh(() => order = v ?? orders.first)),
            ]),
            Row(children: [
              const Text('Uyarı penceresi: '),
              DropdownButton<int>(value: horizon, items: [3,7,14,30].map((v) =>
                DropdownMenuItem(value: v, child: Text('$v gün'))).toList(),
                onChanged: (v) => refresh(() => horizon = v ?? 7)),
              const Spacer(),
              const Text('Stokta olanlar'),
              Switch(value: onlyInStock, onChanged: (v) => refresh(() => onlyInStock = v)),
            ]),
            FilledButton.icon(onPressed: copyReport,
              icon: const Icon(Icons.copy_all_outlined),
              label: Text('Filtrelenen ${filtered.length} ürünü CSV kopyala')),
            const SizedBox(height: 8),
            Text('Gösterilen ürün: ${filtered.length}',
              style: const TextStyle(fontWeight: FontWeight.bold)),
            if (filtered.isEmpty) const ListTile(title: Text('Bu koşullarda ürün bulunamadı.')),
            ...filtered.map((n) {
              final d = days(n);
              final r = rate(n);
              final waste = predictedWaste(n);
              final storage = _namedStock(record, n)['storage'] ?? 'Belirtilmedi';
              final priority = d == null ? 'SKT girilmeli' : d < 0
                  ? 'SKT geçmiş: kullanmadan önce güvenliği değerlendir'
                  : d == 0 ? 'Bugün tüketim önceliği'
                  : d <= horizon ? 'Öncelikli tüketim' : 'Normal';
              final suggestion = d == null ? 'SKT tanımlanmadı.'
                  : r <= 0 ? 'Tüketim geçmişi yetersiz; israf miktarı hesaplanamaz.'
                  : waste > 0 ? 'Tahmini ${waste.toStringAsFixed(2)} birim SKT öncesi tüketilemeyebilir.'
                  : 'Mevcut tüketim hızında SKT öncesi tüketilebilir.';
              return Card(child: ListTile(
                leading: Icon(d != null && d <= horizon
                    ? Icons.warning_amber_rounded : Icons.inventory_2_outlined,
                    color: d != null && d <= horizon ? Colors.deepOrange : _purple),
                title: Text(n), isThreeLine: true,
                subtitle: Text('Stok: ${amount(n).toStringAsFixed(2)} • $storage\n'
                    '${_expiryLabel(record,n)} • $priority\n'
                    'Günlük tüketim: ${r.toStringAsFixed(2)} • $suggestion'),
              ));
            }),
            const SizedBox(height: 12),
            const Text('Tahmin, kayıtlı stok hareketlerine dayanır; ürünün gerçek güvenliğini veya yenilebilirliğini garanti etmez. '
              'SKT geçmiş ürünleri tüketme kararı için bu hesaplamayı kullanmayın.'),
            Text('Rapor tarihi: ${start.day}.${start.month}.${start.year}'),
          ])));
      }),
    );
  }

  Map<String, double> _namedStoreTotals(Map<String, dynamic> record) {
    final totals = <String, double>{};
    for (final name in (record['items'] as List? ?? []).map((e) => e.toString())) {
      final store = _namedProductMeta(record, name)['store']!.trim();
      final label = store.isEmpty ? 'Market belirtilmedi' : store;
      totals[label] = (totals[label] ?? 0) + _namedItemTotal(record, name);
    }
    return totals;
  }

  void _showNamedSummary(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    final done = (record['done'] as List? ?? []).map((e) => e.toString()).toSet();
    final categories = <String, double>{};
    for (final name in names) {
      final category = _namedCategory(record, name);
      categories[category] = (categories[category] ?? 0) + _namedItemTotal(record, name);
    }
    final total = _namedListTotal(record);
    final budget = _namedBudget(record);
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .72,
        child: ListView(padding: const EdgeInsets.all(16), children: [
          Text(record['title']?.toString() ?? 'Liste özeti',
            style: const TextStyle(fontSize: 22, fontWeight: FontWeight.bold, color: _purple)),
          Text('Toplam ${names.length} ürün • ${names.where(done.contains).length} ürün alındı'),
          LinearProgressIndicator(value: names.isEmpty ? 0 : names.where(done.contains).length / names.length,
            color: _purple),
          const SizedBox(height: 12),
          Text('Tahmini toplam: ${_money(total)}'),
          Text('Liste bütçesi: ${budget > 0 ? _money(budget) : 'Belirlenmedi'}'),
          if (budget > 0) Text('Bütçe farkı: ${_money(budget - total)}',
            style: TextStyle(color: total > budget ? Colors.red : Colors.green.shade800)),
          const SizedBox(height: 12),
          const Text('Kategori bazında tahmini maliyet',
            style: TextStyle(fontWeight: FontWeight.bold)),
          ...categories.entries.map((e) => ListTile(dense: true,
            title: Text(e.key), trailing: Text(_money(e.value)))),
          const Divider(),
          const Text('Market bazında tahmini maliyet',
            style: TextStyle(fontWeight: FontWeight.bold)),
          ..._namedStoreTotals(record).entries.map((e) => ListTile(dense: true,
            title: Text(e.key), trailing: Text(_money(e.value)))),
          const Divider(),
          const Text('Ürün detayları', style: TextStyle(fontWeight: FontWeight.bold)),
          ...names.map((name) {
            final quantity = _namedQuantity(record, name);
            return ListTile(dense: true, title: Text(name),
              subtitle: Text('${quantity['amount']} ${quantity['unit']} • ${_namedCategory(record, name)}\nMarka: ${_namedProductMeta(record, name)['brand']!.isEmpty ? 'Belirtilmedi' : _namedProductMeta(record, name)['brand']} • Market: ${_namedProductMeta(record, name)['store']!.isEmpty ? 'Belirtilmedi' : _namedProductMeta(record, name)['store']} • ${_namedStock(record, name)['storage']} • ${_expiryLabel(record, name)} • Stok: ${_namedStock(record, name)['amount']!.isEmpty ? 'Belirtilmedi' : _namedStock(record, name)['amount']} ${_stockIsLow(record, name) ? '⚠ Azaldı' : ''}'),
              trailing: Text(_money(_namedItemTotal(record, name))));
          }),
          const Text('Fiyat girilmemiş ürünler toplamda 0 TL kabul edilir.',
            style: TextStyle(fontSize: 11)),
        ]))));
  }

  double _namedListTotal(Map<String, dynamic> record) {
    final names = (record['items'] as List? ?? []).map((e) => e.toString());
    return names.fold<double>(0, (sum, name) => sum + _namedItemTotal(record, name));
  }

  Future<void> _transferNamedItem(Map<String, dynamic> source, String name, void Function(void Function()) refresh) async {
    final targets = _namedLists.where((r) => !identical(r, source)).toList();
    if (targets.isEmpty) { _notice('Aktarılacak başka kayıtlı liste bulunmuyor.'); return; }
    final destination = await showDialog<Map<String, dynamic>>(context: context, builder: (ctx) => SimpleDialog(
      title: Text('“$name” hangi listeye aktarılsın?'),
      children: targets.map((r) => SimpleDialogOption(
        onPressed: () => Navigator.pop(ctx, r),
        child: Text(r['title']?.toString() ?? 'İsimsiz liste'))).toList(),
    ));
    if (destination == null || !mounted) return;
    final targetItems = (destination['items'] as List? ?? []).map((e) => e.toString()).toList();
    if (targetItems.any((e) => _normalizeName(e) == _normalizeName(name))) {
      _notice('Bu ürün hedef listede zaten bulunuyor.'); return;
    }
    final approved = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Ürünü aktar'),
      content: Text('“$name” hedef listeye taşınacak ve kaynak listeden kaldırılacak. Aktif alışveriş listesi değişmeyecek.'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Aktar'))],
    ));
    if (approved != true || !mounted) return;
    setState(() {
      targetItems.add(name);
      destination['items'] = targetItems;
      final sourceItems = (source['items'] as List? ?? []).map((e) => e.toString()).toList()..remove(name);
      source['items'] = sourceItems;
      for (final field in ['details', 'prices', 'actualPrices', 'quantities', 'unitPrices', 'productMeta', 'stockMeta']) {
        final from = source[field] is Map ? Map<String, dynamic>.from(source[field] as Map) : <String, dynamic>{};
        final to = destination[field] is Map ? Map<String, dynamic>.from(destination[field] as Map) : <String, dynamic>{};
        if (from.containsKey(name)) to[name] = from.remove(name);
        source[field] = from;
        destination[field] = to;
      }
      source['done'] = (source['done'] as List? ?? []).where((e) => e.toString() != name).toList();
      source['updated'] = DateTime.now().toIso8601String();
      destination['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
    _notice('Ürün aktarıldı.');
  }

  // Aşama 113–117: Kayıtlı listeler, aktif alışverişten bağımsızdır.
  Future<void> _editNamedItem(Map<String, dynamic> record,
      void Function(void Function()) refresh, {String? oldName}) async {
    final nameController = TextEditingController(text: oldName ?? '');
    final prices = record['prices'] is Map
        ? Map<String, dynamic>.from(record['prices'] as Map)
        : <String, dynamic>{};
    final priceController = TextEditingController(
        text: oldName == null ? '' : (prices[oldName]?.toString() ?? ''));
    final result = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: Text(oldName == null ? 'Kayıtlı listeye ürün ekle' : 'Ürünü düzenle'),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: nameController, autofocus: true,
          decoration: const InputDecoration(labelText: 'Ürün adı')),
        TextField(controller: priceController, keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(labelText: 'Tahmini toplam fiyat (TL, isteğe bağlı)')),
      ]),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Kaydet'))],
    ));
    final name = nameController.text.trim();
    final rawPrice = priceController.text.trim().replaceAll(',', '.');
    disposeAfterDialog(nameController);
    disposeAfterDialog(priceController);
    if (result != true || !mounted || name.isEmpty) return;
    final parsed = rawPrice.isEmpty ? null : double.tryParse(rawPrice);
    if (rawPrice.isNotEmpty && (parsed == null || !parsed.isFinite || parsed < 0)) {
      _notice('Geçerli bir fiyat gir.'); return;
    }
    final names = (record['items'] as List? ?? []).map((e) => e.toString()).toList();
    if (names.any((e) => _normalizeName(e) == _normalizeName(name) && e != oldName)) {
      _notice('Bu ürün listede zaten bulunuyor.'); return;
    }
    setState(() {
      if (oldName == null) {
        names.add(name);
      } else {
        final index = names.indexOf(oldName);
        if (index < 0) return;
        names[index] = name;
        for (final key in ['prices', 'actualPrices', 'details', 'quantities', 'unitPrices', 'productMeta', 'stockMeta']) {
          final values = record[key] is Map
              ? Map<String, dynamic>.from(record[key] as Map) : <String, dynamic>{};
          if (oldName != name && values.containsKey(oldName)) values[name] = values.remove(oldName);
          record[key] = values;
        }
        final imported = record['stockImportedDone'] is Map
            ? Map<String, dynamic>.from(record['stockImportedDone'] as Map)
            : <String, dynamic>{};
        if (oldName != name && imported.containsKey(oldName)) {
          imported[name] = imported.remove(oldName);
        }
        record['stockImportedDone'] = imported;
        final done = (record['done'] as List? ?? []).map((e) => e.toString()).toList();
        if (oldName != name && done.remove(oldName)) done.add(name);
        record['done'] = done;
      }
      final updatedPrices = record['prices'] is Map
          ? Map<String, dynamic>.from(record['prices'] as Map) : <String, dynamic>{};
      if (parsed != null) updatedPrices[name] = parsed;
      record['prices'] = updatedPrices;
      record['items'] = names;
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  Future<void> _removeNamedItem(Map<String, dynamic> record, String name,
      void Function(void Function()) refresh) async {
    final approved = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Ürünü listeden sil'),
      content: Text('“$name” yalnızca bu kayıtlı listeden silinecek. Devam edilsin mi?'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Sil'))],
    ));
    if (approved != true || !mounted) return;
    final before = Map<String, dynamic>.from(jsonDecode(jsonEncode(record)) as Map);
    setState(() {
      record['items'] = (record['items'] as List? ?? []).where((e) => e.toString() != name).toList();
      record['done'] = (record['done'] as List? ?? []).where((e) => e.toString() != name).toList();
      final imported = record['stockImportedDone'] is Map
          ? Map<String, dynamic>.from(record['stockImportedDone'] as Map)
          : <String, dynamic>{};
      imported.remove(name);
      record['stockImportedDone'] = imported;
      for (final key in ['prices', 'actualPrices', 'details', 'quantities', 'unitPrices', 'productMeta', 'stockMeta']) {
        final values = record[key] is Map
            ? Map<String, dynamic>.from(record[key] as Map) : <String, dynamic>{};
        values.remove(name);
        record[key] = values;
      }
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
    if (!mounted) return;
    ScaffoldMessenger.of(context).hideCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text('“$name” kayıtlı listeden silindi.'),
      duration: const Duration(seconds: 7),
      action: SnackBarAction(label: 'Geri al', onPressed: () async {
        if (!mounted || !_namedLists.contains(record)) return;
        setState(() { record..clear()..addAll(before); });
        refresh(() {});
        await _save();
      }),
    ));
  }

  Future<void> _toggleNamedDone(Map<String, dynamic> record, String name,
      bool checked, void Function(void Function()) refresh) async {
    setState(() {
      final done = (record['done'] as List? ?? []).map((e) => e.toString()).toSet();
      if (checked) { done.add(name); } else {
        done.remove(name);
        // İşaret kaldırılınca bir sonraki alışveriş döngüsüne izin ver.
        final marks = record['stockImportedDone'] is Map
            ? Map<String, dynamic>.from(record['stockImportedDone'] as Map)
            : <String, dynamic>{};
        marks.remove(name);
        record['stockImportedDone'] = marks;
      }
      record['done'] = done.toList();
      record['updated'] = DateTime.now().toIso8601String();
    });
    refresh(() {});
    await _save();
  }

  // Aşama 8148–8397: Birden çok üründe gerçek tüketim ve hedef stok ihtiyacı.
  // Yeni kalıcı anahtar oluşturulmaz; stok hareketleri mevcut listeye yazılır.
  void _showBulkStockConsumption(Map<String, dynamic> record) {
    final quantities = <String, String>{};
    String query = '';
    bool onlyLow = false;
    List<String> names() => (record['items'] as List? ?? const [])
        .map((e) => e.toString()).toSet().where((name) {
          final raw = _namedStock(record, name)['amount'] ?? '';
          final value = double.tryParse(raw.replaceAll(',', '.'));
          return value != null && value.isFinite && value >= 0;
        }).toList();
    double? entered(String name) {
      final raw = quantities[name]?.trim() ?? '';
      final value = double.tryParse(raw.replaceAll(',', '.'));
      return value != null && value.isFinite && value > 0 ? value : null;
    }
    double current(String name) => _stockNumber(_namedStock(record, name)['amount']);
    double needed(String name) {
      final target = _stockTarget(record, name);
      final min = _stockNumber(_namedStock(record, name)['minimum']);
      final threshold = target > 0 ? target : min;
      return (threshold - current(name)).clamp(0.0, double.infinity).toDouble();
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        final available = names();
        final visible = available.where((n) =>
            n.toLowerCase().contains(query.toLowerCase()) &&
            (!onlyLow || needed(n) > 0)).toList();
        final selected = available.where((n) {
          final amount = entered(n);
          return amount != null && amount <= current(n);
        }).toList();
        final invalid = available.where((n) => (quantities[n]?.trim().isNotEmpty ?? false) &&
            (entered(n) == null || entered(n)! > current(n))).length;
        final low = available.where((n) => needed(n) > 0).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Toplu stok tüketimi ve ihtiyaç planı', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            const Text('Kullanılan miktarları gir. Stoktan fazla tüketim kabul edilmez. '
              'İşlemler mevcut stok hareketi geçmişine kaydedilir.'),
            Text('Stok kaydı: ${available.length} • Tüketim seçimi: ${selected.length} '
              '• Geçersiz giriş: $invalid • Yenileme ihtiyacı: ${low.length}'),
            TextField(decoration: const InputDecoration(labelText: 'Ürün ara',
              prefixIcon: Icon(Icons.search)), onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca hedefin altında olanları göster'),
              value: onlyLow, onChanged: (v) => refresh(() => onlyLow = v)),
            if (visible.isEmpty) const ListTile(title: Text('Bu filtreye uygun stok bulunamadı.')),
            ...visible.map((name) {
              final stock = _namedStock(record, name);
              final unit = _namedQuantity(record, name)['unit'] ?? 'Adet';
              final value = entered(name);
              final invalidValue = (quantities[name]?.trim().isNotEmpty ?? false) &&
                  (value == null || value > current(name));
              return Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(name, style: const TextStyle(fontWeight: FontWeight.w600)),
                  Text('Stok: ${stock['amount']} $unit • Minimum: ${stock['minimum']} '
                    '• Hedef eksik: ${needed(name).toStringAsFixed(2)} $unit'),
                  TextFormField(initialValue: quantities[name] ?? '',
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: InputDecoration(labelText: 'Tüketilen miktar ($unit)',
                      errorText: invalidValue ? '0’dan büyük ve stoktan fazla olmayan miktar gir' : null),
                    onChanged: (v) => refresh(() => quantities[name] = v)),
                  if (value != null && value <= current(name))
                    Text('İşlem sonrası stok: ${(current(name) - value).toStringAsFixed(2)} $unit'),
                ])));
            }),
            FilledButton.icon(icon: const Icon(Icons.remove_circle_outline),
              label: Text('${selected.length} ürünün tüketimini kaydet'),
              onPressed: selected.isEmpty || invalid > 0 ? null : () async {
                final snapshot = selected.map((n) => MapEntry(n, entered(n)!)).toList();
                final confirmed = await showDialog<bool>(context: sheet,
                  builder: (dialog) => AlertDialog(
                    title: const Text('Toplu tüketimi onayla'),
                    content: Text('${snapshot.length} ürünün stoku azaltılacak ve her biri '
                      'için hareket kaydı oluşturulacak. Bu işlem alışveriş listesine dokunmaz.'),
                    actions: [TextButton(onPressed: () => Navigator.pop(dialog, false),
                      child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, true),
                        child: const Text('Tüketimi kaydet'))]));
                if (confirmed != true || !mounted) return;
                var count = 0;
                setState(() {
                  final meta = record['stockMeta'] is Map
                      ? Map<String, dynamic>.from(record['stockMeta'] as Map)
                      : <String, dynamic>{};
                  final now = DateTime.now().toIso8601String();
                  for (final entry in snapshot) {
                    final old = _namedStock(record, entry.key);
                    final raw = old['amount'] ?? '';
                    final before = double.tryParse(raw.replaceAll(',', '.'));
                    if (before == null || !before.isFinite || before < entry.value) continue;
                    final after = before - entry.value;
                    _recordStockMovement(record, entry.key, before, after, 'Toplu stok tüketimi');
                    meta[entry.key] = {...old, 'amount': after.toString(), 'updated': now};
                    count++;
                  }
                  record['stockMeta'] = meta;
                  record['updated'] = now;
                });
                await _save();
                if (sheet.mounted) refresh(() => quantities.clear());
                _notice('$count ürün için tüketim kaydedildi.');
              }),
            const Divider(),
            const Text('Akıllı yenileme önerileri', style: TextStyle(
              fontWeight: FontWeight.bold, fontSize: 17)),
            const Text('Hedef stok varsa hedefe, yoksa minimum seviyeye göre hesaplanır. '
              'Stok birimleri dönüştürülmez.'),
            if (low.isEmpty) const ListTile(title: Text('Şu anda hedef altı ürün yok.')),
            ...low.map((n) => ListTile(title: Text(n),
              subtitle: Text('Mevcut: ${current(n)} • Önerilen alım: ${needed(n).toStringAsFixed(2)} '
                '${_namedQuantity(record, n)['unit'] ?? 'Adet'}'))),
            OutlinedButton.icon(icon: const Icon(Icons.add_shopping_cart),
              label: Text('${low.length} ihtiyaç ürününü alışverişe ekle'),
              onPressed: low.isEmpty ? null : () async {
                final confirmed = await showDialog<bool>(context: sheet,
                  builder: (dialog) => AlertDialog(
                    title: const Text('Alışveriş listesine ekle'),
                    content: Text('${low.length} hedef altı ürün aktif alışveriş listesine '
                      'eklenecek. Zaten bulunan ürünler tekrar eklenmeyecek. '
                      'Önerilen miktarlar burada gösterilir; alışveriş miktarları değiştirilmez.'),
                    actions: [TextButton(onPressed: () => Navigator.pop(dialog, false),
                      child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, true),
                        child: const Text('Ekle'))]));
                if (confirmed != true || !mounted) return;
                var count = 0;
                setState(() {
                  for (final n in low) {
                    if (!_items.contains(n)) { _items.add(n); count++; }
                  }
                });
                await _save();
                if (sheet.mounted) refresh(() {});
                _notice('$count yeni ürün aktif alışveriş listesine eklendi.');
              }),
          ])));
      }));
  }

  // Aşama 8398–8647: Tüketim geçmişine dayalı alışveriş tahmini.
  // Tahmin yalnızca kayıtlı tüketim hareketlerinden hesaplanır; geçmiş
  // bulunmayan ürünlerde hedef/minimum stok kullanılır.
  void _showPredictiveShopping(Map<String, dynamic> record) {
    int horizon = 14;
    int safetyDays = 3;
    String query = '';
    bool onlyNeeded = true;
    final chosen = <String>{};
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        final now = DateTime.now();
        final names = (record['items'] as List? ?? const [])
            .map((e) => e.toString()).where((e) => e.trim().isNotEmpty)
            .toSet().toList();
        final rows = <Map<String, dynamic>>[];
        for (final name in names) {
          final rawStock = _namedStock(record, name)['amount'] ?? '';
          final parsed = double.tryParse(rawStock.replaceAll(',', '.'));
          if (parsed == null || !parsed.isFinite || parsed < 0) continue;
          final history = _stockMovements(record).where((m) =>
              m['product'] == name && _isConsumptionMovement(m) &&
              _movementDate(m) != null &&
              !_movementDate(m)!.isAfter(now)).toList();
          final oldest = history.isEmpty ? null : history.map((m) =>
              _movementDate(m)!).reduce((a, b) => a.isBefore(b) ? a : b);
          final span = oldest == null ? 0.0 :
              (now.difference(oldest).inMinutes / 1440.0).clamp(1.0, 36500.0);
          final used = history.fold<double>(0, (sum, m) =>
              sum - ((m['change'] as num?)?.toDouble() ?? 0));
          final rate = span > 0 ? used / span : 0.0;
          final minimum = _stockNumber(_namedStock(record, name)['minimum']);
          final target = _stockTarget(record, name);
          final demand = rate * (horizon + safetyDays);
          final desired = [minimum, target, demand].reduce((a, b) => a > b ? a : b);
          final deficit = (desired - parsed).clamp(0.0, double.infinity).toDouble();
          final unit = _namedQuantity(record, name)['unit']?.toString() ?? 'adet';
          final daysLeft = rate > 0 ? parsed / rate : null;
          final priority = parsed <= minimum && minimum > 0 ||
                  (daysLeft != null && daysLeft <= safetyDays) ? 0 :
              daysLeft != null && daysLeft <= horizon ? 1 : 2;
          rows.add({'name': name, 'stock': parsed, 'rate': rate,
            'days': daysLeft, 'deficit': deficit, 'unit': unit,
            'priority': priority, 'history': history.isNotEmpty});
        }
        rows.sort((a, b) {
          final cmp = (a['priority'] as int).compareTo(b['priority'] as int);
          return cmp != 0 ? cmp : (b['deficit'] as double)
              .compareTo(a['deficit'] as double);
        });
        final visible = rows.where((r) =>
            (r['name'] as String).toLowerCase().contains(query.toLowerCase()) &&
            (!onlyNeeded || (r['deficit'] as double) > 0)).toList();
        final selectable = rows.where((r) => (r['deficit'] as double) > 0)
            .map((r) => r['name'] as String).toSet();
        chosen.removeWhere((n) => !selectable.contains(n));
        final totalCost = rows.where((r) => chosen.contains(r['name']))
            .fold<double>(0, (sum, r) => sum +
                (r['deficit'] as double) * _stockUnitCost(record, r['name'] as String));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı alışveriş tahmini', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            const Text('Kayıtlı stok hareketlerine göre günlük tüketim ve kalan gün '
              'hesaplanır. Tahminler yaklaşık değerlerdir; birim dönüşümü yapılmaz.'),
            DropdownButtonFormField<int>(initialValue: horizon,
              decoration: const InputDecoration(labelText: 'Planlama süresi'),
              items: const [7, 14, 30, 60].map((d) => DropdownMenuItem(
                value: d, child: Text('$d gün'))).toList(),
              onChanged: (v) { if (v != null) refresh(() => horizon = v); }),
            DropdownButtonFormField<int>(initialValue: safetyDays,
              decoration: const InputDecoration(labelText: 'Güvenlik payı'),
              items: const [0, 3, 7, 14].map((d) => DropdownMenuItem(
                value: d, child: Text('$d gün'))).toList(),
              onChanged: (v) { if (v != null) refresh(() => safetyDays = v); }),
            TextField(decoration: const InputDecoration(labelText: 'Ürün ara',
              prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca alım gereken ürünler'),
              value: onlyNeeded, onChanged: (v) => refresh(() => onlyNeeded = v)),
            Text('Tahmin edilen ürün: ${rows.length} • İhtiyaç: ${selectable.length} '
              '• Seçili: ${chosen.length} • Yaklaşık maliyet: ${_money(totalCost)}'),
            TextButton(onPressed: () => refresh(() {
              if (chosen.length == selectable.length) { chosen.clear(); }
              else { chosen.addAll(selectable); }
            }), child: Text(chosen.length == selectable.length ?
              'Tüm seçimleri kaldır' : 'İhtiyaçların tamamını seç')),
            if (visible.isEmpty) const ListTile(title: Text('Uygun ürün bulunamadı.')),
            ...visible.map((r) {
              final name = r['name'] as String;
              final days = r['days'] as double?;
              final deficit = r['deficit'] as double;
              final priority = r['priority'] as int;
              return CheckboxListTile(
                value: chosen.contains(name),
                onChanged: deficit <= 0 ? null : (v) => refresh(() {
                  if (v == true) { chosen.add(name); } else { chosen.remove(name); }
                }),
                title: Text(name),
                subtitle: Text('Stok: ${(r['stock'] as double).toStringAsFixed(2)} ${r['unit']} '
                  '• Günlük tüketim: ${(r['rate'] as double).toStringAsFixed(2)}\n'
                  'Kalan süre: ${days == null ? 'Geçmiş yok' : '${days.toStringAsFixed(1)} gün'} '
                  '• Önerilen alım: ${deficit.toStringAsFixed(2)} ${r['unit']}\n'
                  'Öncelik: ${priority == 0 ? 'Acil' : priority == 1 ? 'Yakın' : 'Normal'}'),
              );
            }),
            FilledButton.icon(icon: const Icon(Icons.add_shopping_cart),
              label: Text('${chosen.length} ürünü alışveriş listesine aktar'),
              onPressed: chosen.isEmpty ? null : () async {
                final snapshot = rows.where((r) => chosen.contains(r['name']))
                    .map((r) => Map<String, dynamic>.from(r)).toList();
                final confirmed = await showDialog<bool>(context: sheet,
                  builder: (dialog) => AlertDialog(
                    title: const Text('Alışveriş önerilerini aktar'),
                    content: Text('${snapshot.length} ürünün önerilen miktarı aktif '
                      'alışveriş listesine kaydedilecek. Mevcut ürünlerin miktar '
                      've notları değiştirilmeyecek; yeni ürünlerin miktarı '
                      'alışveriş notuna eklenecek.'),
                    actions: [TextButton(onPressed: () => Navigator.pop(dialog, false),
                      child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, true),
                        child: const Text('Aktar'))]));
                if (confirmed != true || !mounted) return;
                var added = 0;
                var skipped = 0;
                setState(() {
                  final existing = _items.map(_normalizeName).toSet();
                  for (final r in snapshot) {
                    final name = r['name'] as String;
                    if (!existing.add(_normalizeName(name))) { skipped++; continue; }
                    _items.add(name);
                    _details[name] = {'category': _guess(name),
                      'note': 'Önerilen alım: ${(r['deficit'] as double).toStringAsFixed(2)} '
                          '${r['unit']} • ${horizon + safetyDays} günlük plan'};
                    added++;
                  }
                });
                await _save();
                if (sheet.mounted) refresh(() => chosen.clear());
                _notice('$added yeni ürün eklendi, $skipped mevcut ürün korundu.');
              }),
          ])));
      }));
  }

  // Aşama 7898–8147: Tamamlanan alışverişleri, çift giriş yapmadan stoğa aktar.
  // Aktarım bilgileri ilgili kayıtlı listenin içinde saklanır.
  void _showPurchasedToStock(Map<String, dynamic> record) {
    final chosen = <String>{};
    String search = '';
    bool onlyPending = true;
    List<String> completed() {
      final names = (record['items'] as List? ?? const []).map((e) => e.toString()).toSet();
      return (record['done'] as List? ?? const [])
          .map((e) => e.toString()).where(names.contains).toSet().toList();
    }
    Map<String, dynamic> imported() => record['stockImportedDone'] is Map
        ? Map<String, dynamic>.from(record['stockImportedDone'] as Map)
        : <String, dynamic>{};
    List<Map<String, dynamic>> history() => (record['stockImportHistory'] as List? ?? const [])
        .whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
    double? quantity(String name) {
      final raw = _namedQuantity(record, name)['amount'] ?? '';
      final parsed = double.tryParse(raw.replaceAll(',', '.'));
      return parsed != null && parsed.isFinite && parsed > 0 ? parsed : null;
    }
    bool eligible(String name) => !imported().containsKey(name) && quantity(name) != null &&
        (_namedStock(record, name)['amount'] ?? '').isNotEmpty &&
        double.tryParse((_namedStock(record, name)['amount'] ?? '').replaceAll(',', '.')) != null &&
        _stockNumber(_namedStock(record, name)['amount']) >= 0;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        final done = completed();
        final visible = done.where((n) => (!onlyPending || !imported().containsKey(n)) &&
            n.toLowerCase().contains(search.toLowerCase())).toList();
        final pending = chosen.where((n) => done.contains(n) && eligible(n)).toList();
        final log = history();
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Alışverişten stoğa aktarım', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            const Text('Yalnızca tamamlanan ürünler aktarılır. Her ürün, tamamlanma döngüsünde bir kez aktarılabilir. '
              'Yeni alışveriş için işareti kaldırıp tekrar tamamlandı yapabilirsin.'),
            Text('Tamamlanan: ${done.length} • Aktarılan: ${done.where((n) => imported().containsKey(n)).length} '
              '• Aktarılabilir: ${done.where(eligible).length}'),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün ara'), onChanged: (v) => refresh(() => search = v)),
            SwitchListTile(title: const Text('Yalnızca bekleyenleri göster'),
              value: onlyPending, onChanged: (v) => refresh(() => onlyPending = v)),
            if (visible.isEmpty) const ListTile(title: Text('Bu filtrede tamamlanan ürün bulunamadı.')),
            ...visible.map((name) {
              final old = _namedStock(record, name);
              final wasImported = imported().containsKey(name);
              final amount = quantity(name);
              final valid = eligible(name);
              final unit = _namedQuantity(record, name)['unit'] ?? 'Adet';
              return CheckboxListTile(
                value: chosen.contains(name),
                onChanged: valid ? (v) => refresh(() {
                  if (v == true) { chosen.add(name); } else { chosen.remove(name); }
                }) : null,
                title: Text(name),
                subtitle: Text(wasImported ? 'Bu alışveriş için stoğa aktarıldı' :
                  amount == null ? 'Geçerli alışveriş miktarı girilmeli' :
                  (old['amount'] ?? '').isEmpty ? 'Önce mevcut stok miktarını tanımla' :
                  'Alınan: $amount $unit • Stok: ${old['amount']} $unit'),
                secondary: Icon(wasImported ? Icons.check_circle :
                  valid ? Icons.inventory_2_outlined : Icons.warning_amber,
                  color: wasImported ? Colors.green : valid ? _purple : Colors.deepOrange),
              );
            }),
            FilledButton.icon(icon: const Icon(Icons.inventory_2),
              label: Text('${pending.length} ürünü stoğa aktar'),
              onPressed: pending.isEmpty ? null : () async {
                final toImport = chosen.where((n) => completed().contains(n) && eligible(n)).toList();
                if (toImport.isEmpty) { refresh(() {}); return; }
                final approved = await showDialog<bool>(context: sheet, builder: (dialog) => AlertDialog(
                  title: const Text('Stok girişini onayla'),
                  content: Text('${toImport.length} tamamlanan ürünün alışveriş miktarı mevcut stoğa eklenecek. '
                    'Her ürün için hareket kaydı ve mükerrer aktarım koruması oluşturulacak.'),
                  actions: [TextButton(onPressed: () => Navigator.pop(dialog, false),
                    child: const Text('Vazgeç')),
                    FilledButton(onPressed: () => Navigator.pop(dialog, true),
                      child: const Text('Aktar'))],
                ));
                if (approved != true || !mounted) return;
                var count = 0;
                setState(() {
                  final meta = record['stockMeta'] is Map
                      ? Map<String, dynamic>.from(record['stockMeta'] as Map) : <String, dynamic>{};
                  final marks = imported();
                  final entries = history();
                  final now = DateTime.now().toIso8601String();
                  for (final name in toImport) {
                    if (!eligible(name)) continue;
                    final old = _namedStock(record, name);
                    final before = _stockNumber(old['amount']);
                    final add = quantity(name)!;
                    final after = before + add;
                    if (!after.isFinite) continue;
                    _recordStockMovement(record, name, before, after, 'Alışverişten stoğa aktarım');
                    meta[name] = {...old, 'amount': after.toString(), 'updated': now};
                    marks[name] = now;
                    entries.insert(0, <String, dynamic>{'product': name, 'date': now,
                      'quantity': add, 'unit': _namedQuantity(record, name)['unit'] ?? 'Adet',
                      'before': before, 'after': after});
                    count++;
                  }
                  record['stockMeta'] = meta;
                  record['stockImportedDone'] = marks;
                  record['stockImportHistory'] = entries;
                  record['updated'] = now;
                });
                await _save();
                if (sheet.mounted) refresh(() => chosen.clear());
                _notice('$count ürün stoğa aktarıldı.');
              }),
            const Divider(),
            const Text('Aktarım geçmişi', style: TextStyle(fontWeight: FontWeight.bold)),
            if (log.isEmpty) const ListTile(title: Text('Henüz stok aktarımı yapılmadı.')),
            ...log.take(50).map((e) => ListTile(
              title: Text(e['product']?.toString() ?? ''),
              subtitle: Text('${e['date'] ?? ''} • ${e['before'] ?? ''} → ${e['after'] ?? ''}'),
              trailing: Text('+${e['quantity'] ?? ''} ${e['unit'] ?? ''}'))),
            if (log.length > 50) Text('İlk 50 kayıt gösteriliyor • Toplam ${log.length} aktarım.'),
            OutlinedButton.icon(icon: const Icon(Icons.copy),
              label: const Text('Aktarım geçmişini CSV kopyala'), onPressed: () async {
                final rows = <String>['Ürün,Tarih,Miktar,Birim,Önce,Sonra'];
                for (final e in log) {
                  rows.add([e['product'], e['date'], e['quantity'], e['unit'], e['before'], e['after']]
                    .map(_stockCsvCell).join(','));
                }
                await Clipboard.setData(ClipboardData(text: rows.join('\n')));
                _notice('Aktarım geçmişi panoya kopyalandı.');
              }),
          ])));
      }),
    );
  }

  double _namedBudget(Map<String, dynamic> record) =>
      (record['budget'] is num) ? (record['budget'] as num).toDouble() : 0;

  Future<void> _setNamedBudget(Map<String, dynamic> record,
      void Function(void Function()) refresh) async {
    final input = TextEditingController(text: _namedBudget(record) == 0
        ? '' : _namedBudget(record).toStringAsFixed(2));
    final result = await showDialog<String>(context: context, builder: (dialog) => AlertDialog(
      title: const Text('Liste bütçesi'),
      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Bütçe (TL)', hintText: '0 = bütçe yok')),
      actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(dialog, input.text), child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(input);
    if (result == null || !mounted) return;
    final value = double.tryParse(result.trim().replaceAll(',', '.'));
    if (value == null || !value.isFinite || value < 0) {
      _notice('Geçerli bir bütçe gir.'); return;
    }
    setState(() { record['budget'] = value; record['updated'] = DateTime.now().toIso8601String(); });
    refresh(() {});
    await _save();
  }

  Future<void> _bulkNamedAction(Map<String, dynamic> record,
      Set<String> selected, String action,
      void Function(void Function()) refresh) async {
    if (selected.isEmpty) { _notice('Önce ürün seç.'); return; }
    if (action == 'delete') {
      final approved = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
        title: const Text('Seçili ürünler silinsin mi?'),
        content: Text('${selected.length} ürün yalnızca bu kayıtlı listeden silinecek.'),
        actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Sil'))],
      ));
      if (approved != true || !mounted) return;
    }
    setState(() {
      final done = (record['done'] as List? ?? []).map((e) => e.toString()).toSet();
      if (action == 'done') done.addAll(selected);
      if (action == 'undone') done.removeAll(selected);
      if (action == 'delete') {
        record['items'] = (record['items'] as List? ?? []).where((e) => !selected.contains(e.toString())).toList();
        done.removeAll(selected);
        for (final key in ['prices', 'actualPrices', 'details', 'quantities', 'unitPrices', 'productMeta', 'stockMeta']) {
          final values = record[key] is Map ? Map<String, dynamic>.from(record[key] as Map) : <String, dynamic>{};
          for (final name in selected) { values.remove(name); }
          record[key] = values;
        }
      }
      record['done'] = done.toList();
      record['updated'] = DateTime.now().toIso8601String();
    });
    selected.clear();
    refresh(() {});
    await _save();
  }

  void _showNamedLists() {
    int archivePage = 0;
    String search = '';
    final selectedByList = <String, Set<String>>{};
    final hideCompletedByList = <String, bool>{};
    final groupByCategoryByList = <String, bool>{};
    final sortByList = <String, String>{};
    final storeFilterByList = <String, String>{};
    final storageFilterByList = <String, String>{};
    final lowStockOnlyByList = <String, bool>{};
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final filtered = _namedLists.where((record) {
          final title = record['title']?.toString().toLowerCase() ?? '';
          final items = (record['items'] as List? ?? []).map((e) => e.toString().toLowerCase());
          return title.contains(search.toLowerCase()) || items.any((e) => e.contains(search.toLowerCase()));
        }).toList();
        final totalItems = _namedLists.fold<int>(0, (sum, r) => sum + (r['items'] as List? ?? []).length);
        final totalPrice = _namedLists.fold<double>(0, (sum, r) => sum + _namedListTotal(r));
        return SafeArea(child: FractionallySizedBox(heightFactor: .85, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Kayıtlı alışveriş listelerim', style: TextStyle(
            fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
          const Text('Listeler ayrı kaydedilir. Aktif liste otomatik değiştirilmez.'),
          const SizedBox(height: 8),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Liste kontrol paneli', style: TextStyle(fontWeight: FontWeight.bold)),
            Text('Kayıtlı liste: ${_namedLists.length}  •  Toplam ürün kaydı: $totalItems'),
            Text('Listelerin tahmini toplamı: ${_money(totalPrice)}'),
            const Text('Toplam, listelerdeki fiyatı girilmiş ürünleri kapsar. Aynı ürün farklı listelerde tekrar sayılır.', style: TextStyle(fontSize: 11)),
          ]))),
          TextField(onChanged: (v) => refresh(() { search = v; archivePage = 0; }),
            decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Liste veya ürün ara')),
          _kitchenPageControls(filtered.length, archivePage, 15,
            (p) => refresh(() => archivePage = p)),
          if (_namedLists.isEmpty) const Padding(padding: EdgeInsets.all(20),
            child: Text('Henüz kayıtlı liste yok.')),
          if (_namedLists.isNotEmpty && filtered.isEmpty) const Padding(padding: EdgeInsets.all(20),
            child: Text('Aramanla eşleşen liste bulunamadı.')),
          ...filtered.skip(archivePage.clamp(0, filtered.isEmpty ? 0 : (filtered.length - 1) ~/ 15).toInt() * 15).take(15).map((record) {
            final names = ((record['items'] as List?) ?? []).map((e) => e.toString()).toList();
            final matching = search.trim().isEmpty ? names : names.where((e) =>
              e.toLowerCase().contains(search.toLowerCase()) ||
              (record['title']?.toString().toLowerCase().contains(search.toLowerCase()) ?? false)).toList();
            final doneNames = (record['done'] as List? ?? []).map((e) => e.toString()).toSet();
            final completed = names.where(doneNames.contains).length;
            final listId = record['id']?.toString() ?? record['title']?.toString() ?? '';
            final selected = selectedByList.putIfAbsent(listId, () => <String>{});
            final hideCompleted = hideCompletedByList[listId] ?? false;
            selected.removeWhere((name) => !names.contains(name));
            final stores = names.map((name) => _namedProductMeta(record, name)['store']!.trim())
                .where((store) => store.isNotEmpty).toSet().toList()..sort();
            final storageFilter = storageFilterByList[listId] ?? '';
            final rawSelectedStore = storeFilterByList[listId] ?? '';
            final selectedStore = stores.contains(rawSelectedStore) ? rawSelectedStore : '';
            final displayed = matching.where((name) =>
              (!hideCompleted || !doneNames.contains(name)) &&
              (selectedStore.isEmpty || _namedProductMeta(record, name)['store'] == selectedStore) &&
              (storageFilter.isEmpty || _namedStock(record, name)['storage'] == storageFilter) &&
              (!(lowStockOnlyByList[listId] ?? false) || _stockIsLow(record, name))).toList();
            final sortMode = sortByList[listId] ?? 'name';
            displayed.sort((a, b) {
              if (groupByCategoryByList[listId] ?? false) {
                final byCategory = _namedCategory(record, a).compareTo(_namedCategory(record, b));
                if (byCategory != 0) return byCategory;
              }
              if (sortMode == 'price') return _namedItemTotal(record, b).compareTo(_namedItemTotal(record, a));
              if (sortMode == 'status') {
                final byStatus = (doneNames.contains(a) ? 1 : 0).compareTo(doneNames.contains(b) ? 1 : 0);
                if (byStatus != 0) return byStatus;
              }
              return a.toLowerCase().compareTo(b.toLowerCase());
            });
            final listBudget = _namedBudget(record);
            final listTotal = _namedListTotal(record);
            return Card(child: ExpansionTile(
              title: Text(record['title']?.toString() ?? 'İsimsiz liste'),
              subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${names.length} ürün • Tahmini: ${_money(_namedListTotal(record))}'),
                Text('$completed/${names.length} ürün alındı'),
                LinearProgressIndicator(value: names.isEmpty ? 0 : completed / names.length,
                  backgroundColor: _pink, color: _purple),
                Text('Liste bütçesi: ${listBudget > 0 ? _money(listBudget) : 'Belirlenmedi'}'),
                if (listBudget > 0) ...[
                  Text('Tahmini bütçe farkı: ${_money(listBudget - listTotal)}',
                    style: TextStyle(color: listTotal > listBudget ? Colors.red : Colors.green.shade800)),
                  LinearProgressIndicator(value: (listTotal / listBudget).clamp(0.0, 1.0),
                    color: listTotal > listBudget ? Colors.red : _purple),
                  if (listTotal > listBudget) const Text('Tahmini maliyet liste bütçesini aşıyor!',
                    style: TextStyle(color: Colors.red)),
                ],
              ]),
              children: [
                SwitchListTile(dense: true, title: const Text('Alınan ürünleri gizle'),
                  value: hideCompleted,
                  onChanged: (value) => refresh(() => hideCompletedByList[listId] = value)),
                if (stores.isNotEmpty) Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  child: DropdownButtonFormField<String>(
                    key: ValueKey('store-$listId-$selectedStore'),
                    initialValue: stores.contains(selectedStore) ? selectedStore : '',
                    decoration: const InputDecoration(labelText: 'Markete göre filtrele'),
                    items: [const DropdownMenuItem(value: '', child: Text('Tüm marketler')),
                      ...stores.map((store) => DropdownMenuItem(value: store, child: Text(store)))],
                    onChanged: (v) => refresh(() => storeFilterByList[listId] = v ?? ''),
                  )),
                Padding(padding: const EdgeInsets.symmetric(horizontal: 16),
                  child: DropdownButtonFormField<String>(
                    key: ValueKey('storage-$listId-$storageFilter'),
                    initialValue: _storagePlaces.contains(storageFilter) ? storageFilter : '',
                    decoration: const InputDecoration(labelText: 'Saklama yerine göre filtrele'),
                    items: [const DropdownMenuItem(value: '', child: Text('Tüm saklama yerleri')),
                      ..._storagePlaces.map((place) => DropdownMenuItem(value: place, child: Text(place)))],
                    onChanged: (v) => refresh(() => storageFilterByList[listId] = v ?? ''),
                  )),
                SwitchListTile(dense: true, title: const Text('Yalnızca azalan stoklar'),
                  value: lowStockOnlyByList[listId] ?? false,
                  onChanged: (v) => refresh(() => lowStockOnlyByList[listId] = v)),
                SwitchListTile(dense: true, title: const Text('Kategoriye göre grupla'),
                  value: groupByCategoryByList[listId] ?? false,
                  onChanged: (v) => refresh(() => groupByCategoryByList[listId] = v)),
                Padding(padding: const EdgeInsets.symmetric(horizontal: 16),
                  child: DropdownButtonFormField<String>(
                    initialValue: sortByList[listId] ?? 'name',
                    decoration: const InputDecoration(labelText: 'Ürün sıralaması'),
                    items: const [
                      DropdownMenuItem(value: 'name', child: Text('Ürün adı (A–Z)')),
                      DropdownMenuItem(value: 'price', child: Text('Tahmini fiyat (yüksekten düşüğe)')),
                      DropdownMenuItem(value: 'status', child: Text('Alınmayanlar önce')),
                    ], onChanged: (v) { if (v != null) refresh(() => sortByList[listId] = v); })),
                if (names.isNotEmpty) Padding(padding: const EdgeInsets.symmetric(horizontal: 12),
                  child: Wrap(spacing: 6, runSpacing: 4, crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text('${selected.length} ürün seçili'),
                      TextButton(onPressed: () => refresh(() {
                        if (selected.length == displayed.length && displayed.isNotEmpty) {
                          selected.clear();
                        } else { selected.addAll(displayed); }
                      }), child: Text(selected.length == displayed.length && displayed.isNotEmpty
                          ? 'Seçimi kaldır' : 'Görünenleri seç')),
                      PopupMenuButton<String>(enabled: selected.isNotEmpty,
                        tooltip: 'Toplu işlemler',
                        onSelected: (action) => _bulkNamedAction(record, selected, action, refresh),
                        itemBuilder: (_) => const [
                          PopupMenuItem(value: 'done', child: Text('Seçilenleri alındı işaretle')),
                          PopupMenuItem(value: 'undone', child: Text('Seçilenleri alınmadı işaretle')),
                          PopupMenuItem(value: 'delete', child: Text('Seçilenleri sil')),
                        ], child: const Chip(label: Text('Toplu işlem'))),
                    ])),
                ...displayed.map((name) => CheckboxListTile(
                  dense: true, controlAffinity: ListTileControlAffinity.leading,
                  value: doneNames.contains(name), title: Text(name),
                  subtitle: Text('${(groupByCategoryByList[listId] ?? false) ? '${_namedCategory(record, name)} • ' : ''}${_namedQuantity(record, name)['amount']} ${_namedQuantity(record, name)['unit']} • ${_money(_namedItemTotal(record, name))} • ${_namedProductMeta(record, name)['brand']!.isEmpty ? 'Markasız' : _namedProductMeta(record, name)['brand']} • ${_namedProductMeta(record, name)['store']!.isEmpty ? 'Market yok' : _namedProductMeta(record, name)['store']} • ${_namedStock(record, name)['storage']} • ${_expiryLabel(record, name)} • Stok: ${_namedStock(record, name)['amount']!.isEmpty ? 'Belirtilmedi' : _namedStock(record, name)['amount']} ${_stockIsLow(record, name) ? '⚠ Azaldı' : ''}'),
                  onChanged: (checked) => _toggleNamedDone(record, name, checked ?? false, refresh),
                  secondary: Row(mainAxisSize: MainAxisSize.min, children: [
                    IconButton(tooltip: selected.contains(name) ? 'Seçimden çıkar' : 'Toplu işlem için seç',
                      icon: Icon(selected.contains(name) ? Icons.check_box : Icons.check_box_outline_blank,
                        color: _purple),
                      onPressed: () => refresh(() {
                        if (!selected.add(name)) selected.remove(name);
                      })),
                    PopupMenuButton<String>(tooltip: 'Ürün işlemleri',
                    onSelected: (action) {
                      if (action == 'edit') { _editNamedItem(record, refresh, oldName: name); }
                      if (action == 'quantity') { _editNamedQuantity(record, name, refresh); }
                      if (action == 'meta') { _editNamedProductMeta(record, name, refresh); }
                      if (action == 'stock') { _editNamedStock(record, name, refresh); }
                      if (action == 'stocklevel') { _editStockLevels(record, name, refresh); }
                      if (action == 'stockmanual') { _manualStockMovement(record, name, refresh); }
                      if (action == 'stocktarget') { _setStockTarget(record, name, refresh); }
                      if (action == 'stockplus') { _adjustStock(record, name, 1, refresh); }
                      if (action == 'stockminus') { _adjustStock(record, name, -1, refresh); }
                      if (action == 'delete') { _removeNamedItem(record, name, refresh); }
                      if (action == 'move') { _transferNamedItem(record, name, refresh); }
                    },
                    itemBuilder: (_) => const [
                      PopupMenuItem(value: 'edit', child: Text('Ürünü düzenle')),
                      PopupMenuItem(value: 'quantity', child: Text('Miktar / birim fiyat')),
                      PopupMenuItem(value: 'meta', child: Text('Marka / market bilgisi')),
                      PopupMenuItem(value: 'stock', child: Text('SKT / saklama yeri')),
                      PopupMenuItem(value: 'stocklevel', child: Text('Stok / minimum miktar')),
                      PopupMenuItem(value: 'stockmanual', child: Text('Miktarlı stok giriş / çıkış')),
                      PopupMenuItem(value: 'stocktarget', child: Text('Hedef stok miktarı')),
                      PopupMenuItem(value: 'stockplus', child: Text('Stok +1')),
                      PopupMenuItem(value: 'stockminus', child: Text('Stok -1')),
                      PopupMenuItem(value: 'move', child: Text('Başka listeye aktar')),
                      PopupMenuItem(value: 'delete', child: Text('Ürünü sil')),
                    ]),
                  ]),
                )),
                Wrap(spacing: 6, children: [
                  TextButton.icon(onPressed: () => _showConsumptionPlanning(record),
                    icon: const Icon(Icons.insights_outlined), label: const Text('Tüketim / satın alma planlama')),
                  TextButton.icon(onPressed: () => _showMovementCorrections(record),
                    icon: const Icon(Icons.history_toggle_off), label: const Text('Stok hareketlerini düzelt / geri al')),
                  TextButton.icon(onPressed: () => _showStockCountAnalytics(record),
                    icon: const Icon(Icons.analytics_outlined), label: const Text('Sayım analizleri / karşılaştırma')),
                  TextButton.icon(onPressed: () => _showStockCount(record),
                    icon: const Icon(Icons.fact_check_outlined), label: const Text('Stok sayımı / fark raporu')),
                  TextButton.icon(onPressed: () => _showPredictiveShopping(record),
                    icon: const Icon(Icons.auto_graph_outlined),
                    label: const Text('Akıllı alışveriş tahmini / öncelikler')),
                  TextButton.icon(onPressed: () => _showBulkStockConsumption(record),
                    icon: const Icon(Icons.restaurant_menu_outlined),
                    label: const Text('Toplu stok tüketimi / akıllı ihtiyaç planı')),
                  TextButton.icon(onPressed: () => _showPurchasedToStock(record),
                    icon: const Icon(Icons.shopping_cart_checkout),
                    label: const Text('Tamamlanan alışverişleri stoğa aktar')),
                  TextButton.icon(onPressed: () => _showBulkStockReplenishment(record),
                    icon: const Icon(Icons.playlist_add_check_circle_outlined),
                    label: const Text('Toplu stok yenileme / hedefe tamamlama')),
                  TextButton.icon(onPressed: () => _showStockTargets(record),
                    icon: const Icon(Icons.track_changes), label: const Text('Stok hedefleri / yenileme')),
                  TextButton.icon(onPressed: () => _showAdvancedStock(record),
                    icon: const Icon(Icons.analytics_outlined), label: const Text('Gelişmiş stok paneli / CSV')),
                  TextButton.icon(onPressed: () => _showStockMovements(record),
                    icon: const Icon(Icons.timeline), label: const Text('Stok hareketleri / analiz')),
                  TextButton.icon(onPressed: () => _showLowStockSummary(record),
                    icon: const Icon(Icons.inventory_2_outlined), label: const Text('Stok kontrol paneli')),
                  TextButton.icon(onPressed: () => _addLowStockToActive(record),
                    icon: const Icon(Icons.add_shopping_cart), label: const Text('Eksilenleri listeye ekle')),
                  TextButton.icon(onPressed: () => _showRecipeStockAssistant(record),
                    icon: const Icon(Icons.soup_kitchen_outlined),
                    label: const Text('Tarif / stok mutfak asistanı')),
                  TextButton.icon(onPressed: () => _showExpiryIntelligence(record),
                    icon: const Icon(Icons.event_busy_outlined),
                    label: const Text('Akıllı SKT / israf önleme paneli')),
                  TextButton.icon(onPressed: () => _showStockSummary(record),
                    icon: const Icon(Icons.kitchen_outlined), label: const Text('Gıda / stok özeti')),
                  TextButton.icon(onPressed: () => _showNamedSummary(record),
                    icon: const Icon(Icons.assessment_outlined), label: const Text('Detaylı özet')),
                  TextButton.icon(onPressed: () => _setNamedBudget(record, refresh),
                    icon: const Icon(Icons.account_balance_wallet_outlined), label: const Text('Liste bütçesi')),
                  TextButton.icon(onPressed: () => _editNamedItem(record, refresh),
                    icon: const Icon(Icons.add), label: const Text('Ürün ekle')),
                  TextButton.icon(onPressed: () async {
                    final title = await _askListName(initial: record['title']?.toString());
                    if (title == null || !mounted) return;
                    setState(() { record['title'] = title; record['updated'] = DateTime.now().toIso8601String(); });
                    refresh(() {}); await _save();
                  }, icon: const Icon(Icons.edit_outlined), label: const Text('Yeniden adlandır')),
                  TextButton.icon(onPressed: () async {
                    Navigator.pop(ctx); await _addNamedItems(record);
                  }, icon: const Icon(Icons.playlist_add), label: const Text('Aktife ekle')),
                  TextButton.icon(onPressed: () async {
                    final title = await _askListName(initial: '${record['title']} (Kopya)');
                    if (title == null || !mounted) return;
                    final copy = jsonDecode(jsonEncode(record)) as Map<String, dynamic>;
                    copy['id'] = DateTime.now().microsecondsSinceEpoch.toString();
                    copy['title'] = title;
                    copy['updated'] = DateTime.now().toIso8601String();
                    setState(() => _namedLists.insert(0, copy));
                    refresh(() {}); await _save();
                  }, icon: const Icon(Icons.copy), label: const Text('Kopyala')),
                  TextButton.icon(onPressed: () => _shareList(record),
                    icon: const Icon(Icons.share), label: const Text('Paylaş / kopyala')),
                  TextButton.icon(onPressed: () async {
                    final ok = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                      title: const Text('Kayıtlı liste silinsin mi?'),
                      content: const Text('Aktif alışveriş listesi etkilenmez.'),
                      actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Sil'))]));
                    if (ok != true || !mounted) return;
                    await _removeKitchenRecordWithUndo(_namedLists, record, 'Kayıtlı alışveriş listesi', refresh: refresh);
                  }, icon: const Icon(Icons.delete_outline), label: const Text('Sil')),
                ]),
              ],
            ));
          }),
        ])));
      }));
  }

  String _money(double n) => '${n.toStringAsFixed(2).replaceAll('.', ',')} TL';

  Future<void> _setMonthlyBudget() async {
    final month = _monthKey();
    final input = TextEditingController(text: _monthlyBudgets[month]?.toStringAsFixed(2) ?? '');
    final value = await showDialog<double>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$month aylık alışveriş bütçesi'),
      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Aylık bütçe (TL)', hintText: 'Örn. 6000')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final n = double.tryParse(input.text.trim().replaceAll(',', '.'));
          if (n != null && n >= 0 && n.isFinite) Navigator.pop(ctx, n);
        }, child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(input);
    if (value == null || !mounted) return;
    setState(() => _monthlyBudgets[month] = value);
    await _save();
  }

  Map<String, double> _categoryTotals({String? month}) {
    final totals = <String, double>{};
    for (final record in _history) {
      final date = record['date']?.toString() ?? '';
      if (month != null && !date.startsWith(month)) continue;
      for (final item in ((record['items'] as List?) ?? []).whereType<Map>()) {
        final price = (item['actual'] as num?)?.toDouble();
        if (price == null) continue;
        final category = item['category']?.toString() ?? _guess(item['name']?.toString() ?? '');
        totals[category] = (totals[category] ?? 0) + price;
      }
    }
    return Map.fromEntries(totals.entries.toList()..sort((a, b) => b.value.compareTo(a.value)));
  }

  void _showDashboard() {
    final month = _monthKey();
    final spent = _monthlyTotals()[month] ?? 0;
    final budget = _monthlyBudgets[month] ?? 0;
    final categories = _categoryTotals(month: month);
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .8,
        child: ListView(padding: const EdgeInsets.all(16), children: [
          const Text('Aylık harcama kontrol paneli', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
          const SizedBox(height: 12),
          Text('Dönem: $month'),
          Text('Aylık bütçe: ${budget > 0 ? _money(budget) : 'Belirlenmedi'}'),
          Text('Arşivlenen gerçek harcama: ${_money(spent)}'),
          if (budget > 0) ...[
            Text('Bütçede kalan: ${_money(budget - spent)}',
              style: TextStyle(fontWeight: FontWeight.bold, color: spent > budget ? Colors.red : Colors.green.shade800)),
            LinearProgressIndicator(value: (spent / budget).clamp(0.0, 1.0)),
            if (spent > budget) const Text('Aylık bütçe aşıldı!', style: TextStyle(color: Colors.red)),
          ],
          const SizedBox(height: 16),
          const Text('Kategori bazında gerçekleşen harcamalar', style: TextStyle(fontWeight: FontWeight.bold)),
          if (categories.isEmpty) const Text('Bu ay gerçek fiyatlı arşiv kaydı bulunmuyor.'),
          ...categories.entries.map((e) => ListTile(title: Text(e.key), trailing: Text(_money(e.value)))),
          const Divider(),
          const Text('Önceki aylar', style: TextStyle(fontWeight: FontWeight.bold)),
          ..._monthlyTotals().entries.map((e) => ListTile(
            title: Text(e.key), subtitle: Text('Bütçe: ${_monthlyBudgets[e.key] == null ? 'Belirlenmedi' : _money(_monthlyBudgets[e.key]!)}'),
            trailing: Text(_money(e.value)))),
          const Text('Rapor yalnızca arşivlenmiş ve gerçek fiyatı girilmiş ürünleri kapsar.', style: TextStyle(fontSize: 12)),
        ]))));
  }

  Future<void> _setBudget() async {
    final input = TextEditingController(text: _budget == 0 ? '' : _budget.toStringAsFixed(2));
    final value = await showDialog<double>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Alışveriş bütçesi'),
      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Bütçe (TL)', hintText: 'Örn. 1500')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final n = double.tryParse(input.text.trim().replaceAll(',', '.'));
          if (n != null && n >= 0 && n.isFinite) Navigator.pop(ctx, n);
        }, child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(input);
    if (value == null || !mounted) return;
    setState(() => _budget = value);
    await _save();
  }

  Future<void> _setPrice(String name) async {
    final input = TextEditingController(text: _prices[name]?.toStringAsFixed(2) ?? '');
    final value = await showDialog<double>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$name • Tahmini fiyat'),
      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Ürün toplam fiyatı (TL)', helperText: 'Birim fiyat değil, listedeki ürünün toplam fiyatı')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final n = double.tryParse(input.text.trim().replaceAll(',', '.'));
          if (n != null && n >= 0 && n.isFinite) Navigator.pop(ctx, n);
        }, child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(input);
    if (value == null || !mounted) return;
    setState(() => _prices[name] = value);
    await _save();
  }

  Future<void> _setActualPrice(String name) async {
    final input = TextEditingController(text: _actualPrices[name]?.toStringAsFixed(2) ?? '');
    final value = await showDialog<double>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$name • Gerçek satın alma fiyatı'),
      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
        decoration: const InputDecoration(labelText: 'Kasada ödenen tutar (TL)', helperText: 'Bu ürünün toplam gerçek fiyatını girin.')),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () {
          final n = double.tryParse(input.text.trim().replaceAll(',', '.'));
          if (n != null && n >= 0 && n.isFinite) Navigator.pop(ctx, n);
        }, child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(input);
    if (value == null || !mounted) return;
    setState(() => _actualPrices[name] = value);
    await _save();
  }

  Future<void> _archivePurchased() async {
    final purchasedNames = _items.where(_done.contains).toList();
    if (purchasedNames.isEmpty) { _notice('Arşivlenecek satın alınmış ürün yok.'); return; }
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Alışverişi geçmişe kaydet'),
      content: Text('${purchasedNames.length} satın alınmış ürün geçmişe kaydedilecek ve aktif listeden kaldırılacak. Diğer ürünler korunacak. Devam edilsin mi?'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Arşivle'))],
    ));
    if (confirmed != true || !mounted) return;
    final date = DateTime.now().toIso8601String();
    final entries = purchasedNames.map((name) => <String, dynamic>{
      'name': name, 'estimated': _prices[name], 'actual': _actualPrices[name],
      'note': _details[name]?['note'] ?? '',
      'category': _details[name]?['category'] ?? _guess(name),
    }).toList();
    setState(() {
      _history.insert(0, {'date': date, 'items': entries});
      for (final name in purchasedNames) {
        _items.remove(name); _done.remove(name); _details.remove(name);
        _prices.remove(name); _actualPrices.remove(name);
      }
    });
    await _save();
    _notice('Alışveriş geçmişe kaydedildi.');
  }

  void _showHistory() {
    int archivePage = 0;
    _historyQuery = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, update) {
        final matching = _history.where((record) {
          final query = _historyQuery.toLowerCase().trim();
          if (query.isEmpty) return true;
          final date = record['date']?.toString().toLowerCase() ?? '';
          final items = ((record['items'] as List?) ?? []).whereType<Map>();
          return date.contains(query) || items.any((item) => (item['name']?.toString().toLowerCase() ?? '').contains(query));
        }).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .85,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Alışveriş geçmişi ve aylık rapor', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            TextField(onChanged: (value) => update(() { _historyQuery = value; archivePage = 0; }),
              decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Tarih veya ürün ara')),
            if (_history.isEmpty) const Text('Henüz arşivlenmiş alışveriş bulunmuyor.'),
            ..._monthlyTotals().entries.map((entry) => ListTile(
              leading: const Icon(Icons.calendar_month), title: Text(entry.key),
              subtitle: Text('Aylık bütçe: ${_monthlyBudgets[entry.key] == null ? 'Belirlenmedi' : _money(_monthlyBudgets[entry.key]!)}'),
              trailing: Text(_money(entry.value)),
            )),
            const Divider(),
            if (matching.isEmpty && _history.isNotEmpty) const Text('Aramayla eşleşen alışveriş yok.'),
            _kitchenPageControls(matching.length, archivePage, 20,
              (p) => update(() => archivePage = p)),
            ...matching.skip(archivePage.clamp(0, matching.isEmpty ? 0 : (matching.length - 1) ~/ 20).toInt() * 20).take(20).map((record) {
              final date = record['date']?.toString() ?? '';
              final items = (record['items'] as List?) ?? [];
              final actual = items.whereType<Map>().fold<double>(0, (sum, item) => sum + ((item['actual'] as num?)?.toDouble() ?? 0));
              final estimate = items.whereType<Map>().fold<double>(0, (sum, item) => sum + ((item['estimated'] as num?)?.toDouble() ?? 0));
              return ExpansionTile(
                title: Text(date.length >= 10 ? date.substring(0, 10) : date),
                subtitle: Text('${items.length} ürün • Gerçek: ${_money(actual)} • Tahmini: ${_money(estimate)}'),
                children: [
                  ListTile(leading: const Icon(Icons.playlist_add), title: const Text('Bu alışverişi tekrar listeye ekle'),
                    onTap: () async {
                      Navigator.pop(ctx);
                      await _addFromHistory(items.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList());
                    }),
                  ...items.whereType<Map>().map((item) => ListTile(
                    title: Text(item['name']?.toString() ?? ''),
                    subtitle: Text('Tahmini: ${item['estimated'] == null ? 'Girilmedi' : _money((item['estimated'] as num).toDouble())}'),
                    trailing: IconButton(tooltip: 'Yeniden listeye ekle', icon: const Icon(Icons.add_shopping_cart),
                      onPressed: () async {
                        Navigator.pop(ctx);
                        await _addFromHistory([Map<String, dynamic>.from(item)]);
                      }),
                  )),
                ],
              );
            }),
          ])));
      }));
  }

  // Aşama 98–102: Arşiv kayıtları salt okunur kalır; geri ekleme yalnızca
  // mevcut alışveriş listesine yeni ürün ekler.
  List<Map<String, dynamic>> _historicalItems() {
    final result = <Map<String, dynamic>>[];
    for (final record in _history) {
      final date = record['date']?.toString() ?? '';
      for (final raw in ((record['items'] as List?) ?? []).whereType<Map>()) {
        final name = raw['name']?.toString().trim() ?? '';
        if (name.isEmpty) continue;
        result.add({...Map<String, dynamic>.from(raw), 'date': date});
      }
    }
    return result;
  }

  String _normalizeName(String name) => name.trim().toLowerCase();

  Map<String, List<Map<String, dynamic>>> _purchaseGroups() {
    final groups = <String, List<Map<String, dynamic>>>{};
    for (final item in _historicalItems()) {
      groups.putIfAbsent(_normalizeName(item['name'].toString()), () => []).add(item);
    }
    return groups;
  }

  Future<void> _addFromHistory(List<Map<String, dynamic>> entries) async {
    final unique = <String, Map<String, dynamic>>{};
    for (final item in entries) {
      final name = item['name']?.toString().trim() ?? '';
      if (name.isNotEmpty) unique.putIfAbsent(_normalizeName(name), () => item);
    }
    final existing = _items.map(_normalizeName).toSet();
    final additions = unique.entries.where((e) => !existing.contains(e.key)).map((e) => e.value).toList();
    if (additions.isEmpty) { _notice('Seçilen ürünlerin hepsi zaten alışveriş listesinde.'); return; }
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Ürünleri yeniden listeye ekle'),
      content: Text('${additions.length} ürün alışveriş listesine eklenecek. Mevcut ürünler ve fiyatları korunacak. Devam edilsin mi?'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Ekle'))],
    ));
    if (confirmed != true || !mounted) return;
    setState(() {
      for (final item in additions) {
        final name = item['name'].toString().trim();
        _items.add(name);
        final category = item['category']?.toString() ?? _guess(name);
        _details[name] = {'category': _categories.contains(category) ? category : _guess(name),
          'note': item['note']?.toString() ?? ''};
        final estimated = item['estimated'];
        if (estimated is num && estimated >= 0) _prices[name] = estimated.toDouble();
        // Eski gerçek fiyat, yeni satın alma için geçerli değildir.
      }
    });
    await _save();
    _notice('${additions.length} ürün alışveriş listesine eklendi.');
  }

  void _showShoppingInsights() {
    final groups = _purchaseGroups();
    final ordered = groups.entries.toList()..sort((a, b) {
      final count = b.value.length.compareTo(a.value.length);
      return count != 0 ? count : a.key.compareTo(b.key);
    });
    final history = _historicalItems();
    final priced = history.where((e) => e['actual'] is num).toList();
    final total = priced.fold<double>(0, (sum, e) => sum + (e['actual'] as num).toDouble());
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .86,
        child: ListView(padding: const EdgeInsets.all(16), children: [
          const Text('Alışveriş alışkanlıklarım', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
          const SizedBox(height: 8),
          Text('Arşivlenmiş alışveriş: ${_history.length} • Ürün kaydı: ${history.length}'),
          Text('Farklı ürün: ${groups.length} • Fiyatı girilen kayıt: ${priced.length}'),
          Text('Kayıtlı gerçek harcama: ${_money(total)}'),
          const SizedBox(height: 12),
          FilledButton.tonalIcon(onPressed: ordered.isEmpty ? null : () async {
            Navigator.pop(ctx);
            await _addFromHistory(ordered.take(10).map((e) => e.value.first).toList());
          }, icon: const Icon(Icons.playlist_add), label: const Text('En sık alınan 10 ürünü listeye ekle')),
          const SizedBox(height: 12),
          const Text('Sık satın alınan ürünler', style: TextStyle(fontWeight: FontWeight.bold)),
          if (ordered.isEmpty) const Text('Henüz alışveriş geçmişi yok.'),
          ...ordered.take(50).map((entry) {
            final records = entry.value;
            final last = records.first;
            final prices = records.where((e) => e['actual'] is num).map((e) => (e['actual'] as num).toDouble()).toList();
            final latest = prices.isEmpty ? 'Yok' : _money(prices.first);
            final oldest = prices.isEmpty ? 'Yok' : _money(prices.last);
            return ExpansionTile(
              title: Text(last['name']?.toString() ?? entry.key),
              subtitle: Text('${records.length} kez • Son fiyat: $latest'),
              children: [
                ListTile(title: const Text('İlk / son kayıtlı gerçek fiyat'), subtitle: Text('$oldest → $latest'),
                  trailing: IconButton(tooltip: 'Alışveriş listesine ekle', icon: const Icon(Icons.add_shopping_cart),
                    onPressed: () async { Navigator.pop(ctx); await _addFromHistory([last]); })),
                ...records.where((e) => e['actual'] is num).take(10).map((e) => ListTile(
                  dense: true, title: Text(e['date']?.toString().split('T').first ?? ''),
                  trailing: Text(_money((e['actual'] as num).toDouble())))),
              ],
            );
          }),
          const Text('Fiyatlar arşivlenen ürünün toplam tutarıdır; paket boyutu ve miktar farklılıkları düzeltilmez.',
            style: TextStyle(fontSize: 12)),
        ]))));
  }

  Map<String, double> _monthlyTotals() {
    final result = <String, double>{};
    for (final record in _history) {
      final date = record['date']?.toString() ?? '';
      if (date.length < 7) continue;
      final month = date.substring(0, 7);
      final items = (record['items'] as List?) ?? [];
      for (final item in items.whereType<Map>()) {
        final price = (item['actual'] as num?)?.toDouble();
        if (price != null) result[month] = (result[month] ?? 0) + price;
      }
    }
    return Map.fromEntries(result.entries.toList()..sort((a, b) => b.key.compareTo(a.key)));
  }

  // Silme işlemleri kayıtları ancak açık kullanıcı onayından sonra değiştirir.
  Future<bool> _confirmKitchenDelete(String recordType, String recordName) async {
    if (!mounted) return false;
    final result = await showDialog<bool>(
      context: context,
      builder: (dialog) => AlertDialog(
        title: const Text('Silme işlemini onayla'),
        content: Text('$recordType: "$recordName"\n\nBu kayıt silinecek. Desteklenen kayıt türlerinde kısa süreli geri alma sunulur. Devam edilsin mi?'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Kaydı sil')),
        ],
      ),
    );
    return mounted && result == true;
  }

  // Aşama 5648–5897: kayıtlar uygulama yeniden açıldığında da kurtarılabilir.
  String? _trashType(List<Map<String, dynamic>> records) {
    if (identical(records, _namedLists)) return 'lists';
    if (identical(records, _shoppingPlans)) return 'plans';
    if (identical(records, _customRecipes)) return 'recipes';
    if (identical(records, _savedMenuDrafts)) return 'drafts';
    if (identical(records, _kitchenMeals)) return 'meals';
    if (identical(records, _kitchenWaste)) return 'waste';
    return null;
  }

  List<Map<String, dynamic>>? _trashTarget(String type) {
    switch (type) {
      case 'lists': return _namedLists;
      case 'plans': return _shoppingPlans;
      case 'recipes': return _customRecipes;
      case 'drafts': return _savedMenuDrafts;
      case 'meals': return _kitchenMeals;
      case 'waste': return _kitchenWaste;
    }
    return null;
  }

  Map<String, dynamic>? _archiveDeleted(
      List<Map<String, dynamic>> records, Map<String, dynamic> record,
      int index, String label) {
    final type = _trashType(records);
    if (type == null) return null;
    final archived = <String, dynamic>{
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'type': type, 'label': label,
      'deletedAt': DateTime.now().toIso8601String(),
      'index': index,
      'record': jsonDecode(jsonEncode(record)),
    };
    _kitchenTrash.insert(0, archived);
    return archived;
  }

  // Aşama 6648–6897: silinmiş kayıtların kurtarılabilirlik denetimi.
  // Bu kontrol hiçbir kaydı değiştirmez; çakışan kayıtları ayrı raporlar.
  List<Map<String, String>> _trashRecoveryAudit(
      List<Map<String, dynamic>> entries) {
    final report = <Map<String, String>>[];
    final encountered = <String>{};
    for (final entry in entries) {
      final type = entry['type']?.toString() ?? '';
      final target = _trashTarget(type);
      final raw = entry['record'];
      var status = 'Kurtarılabilir';
      var explanation = 'İlgili kayıt listesine geri eklenebilir.';
      if (target == null || raw is! Map) {
        status = 'Geçersiz';
        explanation = 'Kayıt türü veya kayıt içeriği geçersiz.';
      } else {
        final record = Map<String, dynamic>.from(raw);
        final id = record['id']?.toString() ?? '';
        final fingerprint = id.isNotEmpty
            ? '$type:id:$id' : '$type:json:${jsonEncode(record)}';
        final alreadyExists = id.isNotEmpty
            ? target.any((item) => item['id']?.toString() == id)
            : target.any((item) => jsonEncode(item) == jsonEncode(record));
        if (alreadyExists) {
          status = 'Çakışma';
          explanation = 'Aynı kayıt aktif listede bulunuyor.';
        } else if (!encountered.add(fingerprint)) {
          status = 'Tekrar';
          explanation = 'Çöp kutusundaki başka bir kayıtla aynı.';
        }
      }
      report.add(<String, String>{
        'type': type,
        'label': entry['label']?.toString() ?? 'Kayıt',
        'deletedAt': entry['deletedAt']?.toString() ?? '',
        'status': status,
        'explanation': explanation,
      });
    }
    return report;
  }

  // Aşama 6148–6397: çöp kutusunda arama, tür filtresi ve dışa aktarım.
  Future<void> _showKitchenTrash() async {
    if (!mounted) return;
    var query = '';
    var selectedType = 'all';
    var trashPage = 0;
    const trashPageSize = 20;
    const typeNames = <String, String>{
      'all': 'Tüm kayıtlar', 'lists': 'Alışveriş listeleri',
      'plans': 'Alışveriş planları', 'recipes': 'Tarifler',
      'drafts': 'Menü taslakları', 'meals': 'Yemek planları',
      'waste': 'İsraf kayıtları',
    };
    await showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final filtered = _kitchenTrash.where((entry) {
          if (selectedType != 'all' && entry['type'] != selectedType) return false;
          final needle = query.trim().toLowerCase();
          if (needle.isEmpty) return true;
          return ('${entry['label'] ?? ''} ${entry['deletedAt'] ?? ''} '
                  '${typeNames[entry['type']] ?? ''}').toLowerCase().contains(needle);
        }).toList();
        final totalPages = filtered.isEmpty ? 1 : (filtered.length + trashPageSize - 1) ~/ trashPageSize;
        if (trashPage >= totalPages) trashPage = totalPages - 1;
        final pageRows = filtered.skip(trashPage * trashPageSize).take(trashPageSize).toList();
        return SafeArea(child: SizedBox(
          height: MediaQuery.of(ctx).size.height * .82,
          child: Padding(padding: const EdgeInsets.all(16), child: Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Mutfak • Kalıcı Çöp Kutusu',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
              const SizedBox(height: 6),
              Text('${_kitchenTrash.length} kayıt • ${filtered.length} gösteriliyor'),
              const SizedBox(height: 8),
              TextField(
                decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
                  labelText: 'Silinen kayıt ara', border: OutlineInputBorder()),
                onChanged: (v) => refresh(() { query = v; trashPage = 0; }),
              ),
              const SizedBox(height: 8),
              DropdownButtonFormField<String>(
                initialValue: selectedType,
                decoration: const InputDecoration(labelText: 'Kayıt türü',
                  border: OutlineInputBorder()),
                items: typeNames.entries.map((e) => DropdownMenuItem<String>(
                  value: e.key, child: Text(e.value))).toList(),
                onChanged: (v) { if (v != null) refresh(() { selectedType = v; trashPage = 0; }); },
              ),
              const SizedBox(height: 6),
              OutlinedButton.icon(
                icon: const Icon(Icons.copy_outlined),
                label: const Text('Görünen kayıtları CSV olarak kopyala'),
                onPressed: filtered.isEmpty ? null : () async {
                  final lines = <String>['Tür;Kayıt;Silinme tarihi;Kimlik'];
                  for (final entry in filtered) {
                    lines.add([
                      typeNames[entry['type']] ?? entry['type'] ?? '',
                      entry['label'] ?? '', entry['deletedAt'] ?? '',
                      entry['id'] ?? '',
                    ].map((v) => _planCsvCell(v)).join(';'));
                  }
                  await Clipboard.setData(ClipboardData(text: lines.join('\n')));
                  _notice('${filtered.length} çöp kutusu kaydı kopyalandı.');
                },
              ),
              // Çöp kutusunun tamamı JSON olarak ayrıca dışa aktarılabilir.
              // Bu işlem geri yükleme yapmaz ve mevcut kayıtları değiştirmez.
              Wrap(spacing: 8, runSpacing: 4, children: [
                OutlinedButton.icon(
                  icon: const Icon(Icons.data_object),
                  label: const Text('Filtrelenen kayıtları JSON kopyala'),
                  onPressed: filtered.isEmpty ? null : () async {
                    final payload = <String, dynamic>{
                      'format': 'anne_bebek_mutfak_cop_kutusu_export_v1',
                      'exportedAt': DateTime.now().toIso8601String(),
                      'count': filtered.length,
                      'records': filtered,
                    };
                    await Clipboard.setData(ClipboardData(
                      text: const JsonEncoder.withIndent('  ').convert(payload)));
                    _notice('${filtered.length} kayıt JSON olarak panoya kopyalandı.');
                  },
                ),
                OutlinedButton.icon(
                  icon: const Icon(Icons.fact_check_outlined),
                  label: const Text('Kurtarma uygunluğunu denetle'),
                  onPressed: filtered.isEmpty ? null : () async {
                    final audit = _trashRecoveryAudit(filtered);
                    final ready = audit.where((e) => e['status'] == 'Kurtarılabilir').length;
                    final conflicts = audit.where((e) => e['status'] == 'Çakışma').length;
                    final repeats = audit.where((e) => e['status'] == 'Tekrar').length;
                    final invalid = audit.where((e) => e['status'] == 'Geçersiz').length;
                    if (!mounted) return;
                    await showDialog<void>(context: context, builder: (dialog) => AlertDialog(
                      title: const Text('Çöp kutusu kurtarma denetimi'),
                      content: SizedBox(width: double.maxFinite, child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text('İncelenen: ${audit.length}'),
                          Text('Kurtarılabilir: $ready'),
                          Text('Aktif kayıtla çakışan: $conflicts'),
                          Text('Yinelenen: $repeats'),
                          Text('Geçersiz: $invalid'),
                          const SizedBox(height: 10),
                          const Text('Bu kontrol yalnızca rapor üretir; kayıtlar değişmez.'),
                        ],
                      )),
                      actions: [
                        TextButton(onPressed: () async {
                          final lines = <String>['Tür;Kayıt;Tarih;Durum;Açıklama'];
                          for (final row in audit) {
                            lines.add([
                              row['type'], row['label'], row['deletedAt'],
                              row['status'], row['explanation'],
                            ].map((v) => _planCsvCell(v ?? '')).join(';'));
                          }
                          await Clipboard.setData(ClipboardData(text: lines.join('\n')));
                          if (dialog.mounted) Navigator.pop(dialog);
                          _notice('Kurtarma denetimi CSV olarak kopyalandı.');
                        }, child: const Text('CSV kopyala')),
                        FilledButton(onPressed: () => Navigator.pop(dialog),
                          child: const Text('Kapat')),
                      ],
                    ));
                  },
                ),
              ]),
              // Çok sayıda silinmiş kayıt için sayfalama ve toplu kurtarma.
              if (filtered.isNotEmpty) Wrap(spacing: 8, runSpacing: 4, children: [
                OutlinedButton.icon(
                  icon: const Icon(Icons.restore_outlined),
                  label: Text('Bu sayfadaki uygun kayıtları kurtar (${pageRows.length})'),
                  onPressed: () async {
                    final candidates = <Map<String, dynamic>>[];
                    final occupied = <String, Set<String>>{};
                    for (final entry in pageRows) {
                      final type = entry['type']?.toString() ?? '';
                      final target = _trashTarget(type);
                      final raw = entry['record'];
                      if (target == null || raw is! Map) continue;
                      final restored = Map<String, dynamic>.from(raw);
                      final id = restored['id']?.toString() ?? '';
                      final signature = id.isNotEmpty ? 'id:$id' : 'data:${jsonEncode(restored)}';
                      final seen = occupied.putIfAbsent(type, () => <String>{});
                      final exists = id.isNotEmpty
                          ? target.any((r) => r['id']?.toString() == id)
                          : target.any((r) => jsonEncode(r) == jsonEncode(restored));
                      if (!exists && seen.add(signature)) candidates.add(entry);
                    }
                    if (candidates.isEmpty) {
                      _notice('Bu sayfada kurtarılabilecek benzersiz kayıt yok.');
                      return;
                    }
                    final approved = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
                      title: const Text('Toplu geri yükleme'),
                      content: Text('${candidates.length} kayıt ilgili listelerine geri eklenecek. '
                        'Mevcut aynı kimlikli kayıtlar ve yinelenen kayıtlar atlanır. Devam edilsin mi?'),
                      actions: [
                        TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Geri yükle')),
                      ],
                    ));
                    if (approved != true || !mounted) return;
                    setState(() {
                      for (final entry in candidates) {
                        final target = _trashTarget(entry['type']?.toString() ?? '');
                        final raw = entry['record'];
                        if (target == null || raw is! Map || !_kitchenTrash.contains(entry)) continue;
                        final restored = Map<String, dynamic>.from(raw);
                        final position = ((entry['index'] as num?)?.toInt() ?? 0).clamp(0, target.length);
                        target.insert(position, restored);
                        _kitchenTrash.remove(entry);
                      }
                    });
                    refresh(() {});
                    await _save();
                    if (mounted) _notice('${candidates.length} kayıt geri yüklendi.');
                  },
                ),
                TextButton.icon(
                  icon: const Icon(Icons.chevron_left), label: const Text('Önceki'),
                  onPressed: trashPage == 0 ? null : () => refresh(() => trashPage--),
                ),
                Text('${trashPage + 1} / $totalPages'),
                TextButton.icon(
                  icon: const Icon(Icons.chevron_right), label: const Text('Sonraki'),
                  onPressed: trashPage >= totalPages - 1 ? null : () => refresh(() => trashPage++),
                ),
              ]),
              const Divider(),
              Expanded(child: filtered.isEmpty
                ? const Center(child: Text('Bu filtrede silinmiş kayıt bulunmuyor.'))
                : ListView.builder(
                    itemCount: pageRows.length,
                    itemBuilder: (ctx, i) {
                      final entry = pageRows[i];
                      final label = entry['label']?.toString() ?? 'Kayıt';
                      return Card(child: Padding(padding: const EdgeInsets.all(8),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Text(label, style: const TextStyle(fontWeight: FontWeight.bold)),
                          Text('${typeNames[entry['type']] ?? 'Kayıt'} • ${entry['deletedAt'] ?? '-'}'),
                          Wrap(spacing: 8, children: [
                            TextButton.icon(icon: const Icon(Icons.restore),
                              label: const Text('Geri yükle'), onPressed: () async {
                                final target = _trashTarget(entry['type']?.toString() ?? '');
                                final raw = entry['record'];
                                if (target == null || raw is! Map || !mounted) {
                                  _notice('Bu kayıt geri yüklenemiyor.'); return;
                                }
                                final restored = Map<String, dynamic>.from(raw);
                                final id = restored['id']?.toString();
                                if (id != null && id.isNotEmpty &&
                                    target.any((r) => r['id']?.toString() == id)) {
                                  _notice('Aynı kimlikli kayıt zaten mevcut.'); return;
                                }
                                if ((id == null || id.isEmpty) &&
                                    target.any((r) => jsonEncode(r) == jsonEncode(restored))) {
                                  _notice('Bu kayıt zaten mevcut. Çöp kutusundaki kopya korundu.');
                                  return;
                                }
                                setState(() {
                                  final pos = ((entry['index'] as num?)?.toInt() ?? 0)
                                    .clamp(0, target.length);
                                  target.insert(pos, restored);
                                  _kitchenTrash.remove(entry);
                                });
                                refresh(() {});
                                await _save();
                                if (mounted) _notice('Kayıt geri yüklendi.');
                              }),
                            TextButton.icon(icon: const Icon(Icons.delete_forever_outlined),
                              label: const Text('Kalıcı sil'), onPressed: () async {
                                final ok = await showDialog<bool>(context: ctx,
                                  builder: (d) => AlertDialog(
                                    title: const Text('Kalıcı olarak silinsin mi?'),
                                    content: Text('“$label” çöp kutusundan silinecek. Bu işlem geri alınamaz.'),
                                    actions: [
                                      TextButton(onPressed: () => Navigator.pop(d, false),
                                        child: const Text('Vazgeç')),
                                      FilledButton(onPressed: () => Navigator.pop(d, true),
                                        child: const Text('Kalıcı sil')),
                                    ]));
                                if (ok != true || !mounted) return;
                                setState(() => _kitchenTrash.remove(entry));
                                refresh(() {});
                                await _save();
                              }),
                          ]),
                        ])));
                    })),
            ]))),
        );
      }),
    );
  }

  // Aşama 5398–5647: farklı arşivlerde silinen kayıtlar için ortak geri alma.
  Future<void> _removeKitchenRecordWithUndo(
    List<Map<String, dynamic>> records,
    Map<String, dynamic> record,
    String label, {
    void Function(void Function())? refresh,
  }) async {
    if (!mounted || !records.contains(record)) return;
    final index = records.indexOf(record);
    final archived = _archiveDeleted(records, record, index, label);
    setState(() => records.remove(record));
    refresh?.call(() {});
    await _save();
    if (!mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(SnackBar(
      content: Text('$label silindi.'),
      duration: const Duration(seconds: 7),
      action: SnackBarAction(label: 'Geri al', onPressed: () async {
        if (!mounted || records.contains(record)) return;
        setState(() {
          records.insert(index.clamp(0, records.length), record);
          if (archived != null) _kitchenTrash.remove(archived);
        });
        refresh?.call(() {});
        await _save();
      }),
    ));
  }

  void _notice(String message) {
    if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  String _guess(String name) {
    final n = name.toLowerCase();
    if (RegExp(r'domates|salatalık|biber|patates|soğan|elma|muz|havuç|kabak|ıspanak|limon|marul|patlıcan').hasMatch(n)) return 'Sebze & Meyve';
    if (RegExp(r'tavuk|kıyma|dana|balık|somon|hindi|köfte').hasMatch(n)) return 'Et & Balık';
    if (RegExp(r'süt|yoğurt|peynir|yumurta|tereyağ|labne').hasMatch(n)) return 'Süt & Kahvaltılık';
    if (RegExp(r'pirinç|bulgur|mercimek|nohut|fasulye|un|makarna|yulaf').hasMatch(n)) return 'Bakliyat & Tahıl';
    if (RegExp(r'tuz|karabiber|kimyon|salça|zeytinyağ|sos|kekik').hasMatch(n)) return 'Baharat & Sos';
    if (RegExp(r'deterjan|sabun|çamaşır|temizlik').hasMatch(n)) return 'Temizlik';
    if (RegExp(r'bebek|bez|mama|ıslak mendil').hasMatch(n)) return 'Bebek';
    return 'Diğer';
  }

  Future<void> _edit({String? original}) async {
    final name = TextEditingController(text: original ?? '');
    final note = TextEditingController(text: original == null ? '' : (_details[original]?['note'] ?? ''));
    var category = original == null ? 'Diğer' : (_details[original]?['category'] ?? _guess(original));
    if (!_categories.contains(category)) category = 'Diğer';
    final result = await showDialog<(String, String, String)?>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, update) => AlertDialog(
        title: Text(original == null ? 'Ürün ekle' : 'Ürünü düzenle'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(controller: name, decoration: const InputDecoration(labelText: 'Ürün / malzeme')),
          const SizedBox(height: 10),
          TextField(controller: note, decoration: const InputDecoration(labelText: 'Miktar / not (ör. 2 kg)')),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(initialValue: category,
            decoration: const InputDecoration(labelText: 'Kategori'),
            items: _categories.skip(1).map((c) => DropdownMenuItem(value: c, child: Text(c))).toList(),
            onChanged: (v) { if (v != null) update(() => category = v); }),
        ])),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
          FilledButton(onPressed: () {
            final n = name.text.trim();
            if (n.isNotEmpty) Navigator.pop(ctx, (n, note.text.trim(), category));
          }, child: const Text('Kaydet')),
        ],
      )),
    );
    disposeAfterDialog(name); disposeAfterDialog(note);
    if (result == null || !mounted) return;
    final (newName, newNote, newCategory) = result;
    setState(() {
      if (original != null && original != newName) {
        _items.remove(original);
        _details.remove(original);
        if (_prices.containsKey(original)) _prices[newName] = _prices.remove(original)!;
        if (_actualPrices.containsKey(original)) _actualPrices[newName] = _actualPrices.remove(original)!;
        if (_done.remove(original)) _done.add(newName);
      }
      if (!_items.contains(newName)) _items.add(newName);
      _details[newName] = {'note': newNote, 'category': newCategory};
    });
    await _save();
  }

  // Aşamalar 198–247: yerel alışveriş planları ve plan analitiği.
  // Planlar bağımsızdır; 'alisveris' ancak kullanıcı aktarımı onaylarsa değişir.
  double _planNum(Object? value) => value is num ? value.toDouble() : double.tryParse('$value'.replaceAll(',', '.')) ?? 0;
  List<Map<String, dynamic>> _planLines(Map<String, dynamic> plan) =>
      (plan['lines'] as List? ?? []).whereType<Map>().map((v) => Map<String, dynamic>.from(v)).toList();
  double _planTotal(Map<String, dynamic> plan) => _planLines(plan).fold<double>(0,
      (a, line) => a + _planNum(line['qty']) * _planNum(line['unitPrice']));
  double _planActual(Map<String, dynamic> plan) => _planLines(plan).fold<double>(0,
      (a, line) => a + _planNum(line['actual']));
  int _planDone(Map<String, dynamic> plan) => _planLines(plan).where((e) => e['done'] == true).length;
  String _planPeriod(Map<String, dynamic> plan) => plan['period']?.toString() ?? 'Haftalık';
  String _planDate(Map<String, dynamic> plan) => plan['created']?.toString().split('T').first ?? '';
  double _planNeed(Map<String, dynamic> plan) => _planLines(plan).fold<double>(0, (a,e) => a + _planNum(e['qty']));
  Map<String, double> _planCategoryTotals(Map<String, dynamic> plan) {
    final result = <String, double>{};
    for (final line in _planLines(plan)) {
      final key = line['category']?.toString() ?? 'Diğer';
      result[key] = (result[key] ?? 0) + _planNum(line['qty']) * _planNum(line['unitPrice']);
    }
    return result;
  }
  Map<String, double> _planStoreTotals(Map<String, dynamic> plan) {
    final result = <String, double>{};
    for (final line in _planLines(plan)) {
      final key = (line['store']?.toString().trim().isNotEmpty ?? false) ? line['store'].toString() : 'Belirtilmedi';
      result[key] = (result[key] ?? 0) + _planNum(line['qty']) * _planNum(line['unitPrice']);
    }
    return result;
  }
  String _planNumberText(num value) => value.toStringAsFixed(value == value.roundToDouble() ? 0 : 2);

  Future<String?> _planText(String title, String initial, {bool numeric = false}) async {
    final controller = TextEditingController(text: initial);
    final result = await showDialog<String>(context: context, builder: (ctx) => AlertDialog(
      title: Text(title), content: TextField(controller: controller, autofocus: true,
        keyboardType: numeric ? const TextInputType.numberWithOptions(decimal: true) : TextInputType.text),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, controller.text.trim()), child: const Text('Kaydet'))]));
    disposeAfterDialog(controller);
    return result;
  }
  Future<void> _newShoppingPlan() async {
    final title = await _planText('Plan adı', 'Yeni alışveriş planı');
    if (!mounted || title == null || title.isEmpty) return;
    String period = 'Haftalık';
    final chosen = await showDialog<String>(context: context, builder: (ctx) => SimpleDialog(
      title: const Text('Plan dönemi'), children: ['Haftalık', 'Aylık'].map((v) =>
      SimpleDialogOption(onPressed: () => Navigator.pop(ctx,v), child: Text(v))).toList()));
    if (!mounted || chosen == null) return;
    period = chosen;
    setState(() => _shoppingPlans.insert(0, {
      'id': DateTime.now().microsecondsSinceEpoch.toString(), 'title': title,
      'period': period, 'created': DateTime.now().toIso8601String(),
      'budget': 0.0, 'note': '', 'lines': <Map<String, dynamic>>[], 'status': 'Taslak',
    }));
    await _save();
  }
  Future<void> _editPlanLine(Map<String, dynamic> plan, {int? index}) async {
    final lines = _planLines(plan);
    final old = index == null ? <String, dynamic>{} : lines[index];
    final name = await _planText('Ürün adı', old['name']?.toString() ?? '');
    if (!mounted || name == null || name.isEmpty) return;
    final qtyText = await _planText('Miktar', '${old['qty'] ?? 1}', numeric: true);
    if (!mounted || qtyText == null) return;
    final qty = _planNum(qtyText);
    if (qty <= 0) { _notice('Miktar sıfırdan büyük olmalı.'); return; }
    final priceText = await _planText('Birim fiyat (TL)', '${old['unitPrice'] ?? 0}', numeric: true);
    if (!mounted || priceText == null) return;
    final price = _planNum(priceText);
    if (price < 0) { _notice('Fiyat negatif olamaz.'); return; }
    final store = await _planText('Market (isteğe bağlı)', old['store']?.toString() ?? '');
    if (!mounted || store == null) return;
    final line = <String, dynamic>{...old, 'name': name, 'qty': qty,
      'unitPrice': price, 'store': store, 'category': old['category'] ?? _guess(name),
      'done': old['done'] ?? false, 'actual': old['actual'] ?? 0.0,
      'priority': old['priority'] ?? 'Normal', 'unit': old['unit'] ?? 'adet'};
    setState(() { if (index == null) { lines.add(line); } else { lines[index] = line; } plan['lines'] = lines; });
    await _save();
  }
  Future<void> _editPlanField(Map<String, dynamic> plan, String key, String title, {bool numeric = false}) async {
    final value = await _planText(title, '${plan[key] ?? ''}', numeric: numeric);
    if (!mounted || value == null) return;
    if (numeric && _planNum(value) < 0) { _notice('Negatif tutar girilemez.'); return; }
    setState(() => plan[key] = numeric ? _planNum(value) : value);
    await _save();
  }
  Future<void> _planImport(Map<String, dynamic> plan) async {
    final candidates = _planLines(plan).map((e) => e['name']?.toString() ?? '').where((e) => e.isNotEmpty && !_items.contains(e)).toList();
    if (candidates.isEmpty) { _notice('Aktarılacak yeni ürün yok.'); return; }
    final yes = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Aktif listeye aktar'), content: Text('${candidates.length} yeni ürün aktif alışveriş listesine eklensin mi?'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Aktar'))]));
    if (!mounted || yes != true) return;
    setState(() { for (final name in candidates) { _items.add(name); } });
    await _save();
    _notice('${candidates.length} ürün aktarıldı.');
  }
  Future<void> _planFromLowStock() async {
    final title = await _planText('Stoklardan plan oluştur', 'Stok yenileme planı');
    if (!mounted || title == null || title.isEmpty) return;
    final lines = <Map<String, dynamic>>[];
    final seen = <String>{};
    for (final record in _namedLists) {
      for (final name in (record['items'] as List? ?? []).map((e) => e.toString())) {
        if (seen.contains(name.toLowerCase()) || !_stockIsLow(record, name)) continue;
        seen.add(name.toLowerCase());
        final stock = _namedStock(record, name);
        final current = _stockNumber(stock['amount']);
        final target = _stockTarget(record, name);
        final min = _stockNumber(stock['minimum']);
        final qty = ((target > min ? target : min) - current).clamp(0.0, 1000000.0);
        if (qty <= 0) continue;
        lines.add({'name': name, 'qty': qty, 'unit': 'adet', 'unitPrice': _stockUnitCost(record, name),
          'store': _namedProductMeta(record, name)['store'] ?? '', 'category': _namedCategory(record,name),
          'done': false, 'actual': 0.0, 'priority': current <= 0 ? 'Acil' : 'Yüksek'});
      }
    }
    if (lines.isEmpty) { _notice('Kritik stoklu ürün bulunamadı.'); return; }
    setState(() => _shoppingPlans.insert(0, {'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': title, 'period': 'Haftalık', 'created': DateTime.now().toIso8601String(),
      'budget': 0.0, 'note': 'Kritik stoklardan oluşturuldu', 'status': 'Taslak', 'lines': lines}));
    await _save();
  }
  Future<void> _planFromActive() async {
    final title = await _planText('Aktif listeden plan', 'Aktif listemden plan');
    if (!mounted || title == null || title.isEmpty) return;
    setState(() => _shoppingPlans.insert(0, {'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': title, 'period': 'Haftalık', 'created': DateTime.now().toIso8601String(),
      'budget': _budget, 'note': '', 'status': 'Taslak', 'lines': _items.map((name) => {
        'name': name, 'qty': 1.0, 'unit': 'adet', 'unitPrice': _prices[name] ?? 0.0,
        'category': _details[name]?['category'] ?? _guess(name), 'store': '',
        'done': _done.contains(name), 'actual': _actualPrices[name] ?? 0.0,
        'priority': 'Normal'}).toList()}));
    await _save();
  }
