  void _showPlanDetails(Map<String, dynamic> plan) {
    bool onlyPending = false;
    String search = '';
    String category = 'Tümü';
    String sort = 'Öncelik';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final lines = _planLines(plan);
        final categories = <String>['Tümü', ...lines.map((e) => e['category']?.toString() ?? 'Diğer').toSet()];
        final displayed = lines.asMap().entries.where((e) {
          final v = e.value;
          return (!onlyPending || v['done'] != true) &&
            (category == 'Tümü' || v['category'] == category) &&
            (v['name']?.toString().toLowerCase().contains(search.toLowerCase()) ?? false);
        }).toList();
        const order = {'Acil': 0, 'Yüksek': 1, 'Normal': 2, 'Düşük': 3};
        displayed.sort((a,b) { if (sort == 'Fiyat') return (_planNum(b.value['qty']) * _planNum(b.value['unitPrice'])).compareTo(_planNum(a.value['qty']) * _planNum(a.value['unitPrice']));
          if (sort == 'Ad') return '${a.value['name']}'.compareTo('${b.value['name']}');
          return (order['${a.value['priority']}'] ?? 2).compareTo(order['${b.value['priority']}'] ?? 2); });
        final total = _planTotal(plan), budget = _planNum(plan['budget']);
        return SafeArea(child: FractionallySizedBox(heightFactor: .93, child: ListView(padding: const EdgeInsets.all(14), children: [
          Text('${plan['title']}', style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
          Text('${_planPeriod(plan)} • ${_planDate(plan)} • ${plan['status'] ?? 'Taslak'}'),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Tahmini toplam: ${_money(total)}'), Text('Gerçekleşen (girilen): ${_money(_planActual(plan))}'),
            Text('Bütçe: ${budget > 0 ? _money(budget) : 'Belirlenmedi'}'),
            if (budget > 0) ...[Text('Bütçe farkı: ${_money(budget-total)}', style: TextStyle(color: total > budget ? Colors.red : Colors.green)),
              LinearProgressIndicator(value: (total / budget).clamp(0.0,1.0))],
            Text('Tamamlanan: ${_planDone(plan)}/${lines.length}'),
            LinearProgressIndicator(value: lines.isEmpty ? 0 : _planDone(plan)/lines.length),
            Text('Toplam planlanan miktar (farklı birimler): ${_planNeed(plan).toStringAsFixed(1)}'),
            Text('Not: ${plan['note'] ?? ''}'),
          ]))),
          Wrap(spacing: 6, runSpacing: 4, children: [
            OutlinedButton(onPressed: () async { await _editPlanField(plan,'title','Plan adı'); refresh(() {}); }, child: const Text('Adlandır')),
            OutlinedButton(onPressed: () async { await _editPlanField(plan,'budget','Plan bütçesi',numeric:true); refresh(() {}); }, child: const Text('Bütçe')),
            OutlinedButton(onPressed: () async { await _editPlanField(plan,'note','Plan notu'); refresh(() {}); }, child: const Text('Not')),
            OutlinedButton(onPressed: () async { final v = await showDialog<String>(context: context, builder:(c)=>SimpleDialog(title:const Text('Plan dönemi'),children:['Haftalık','Aylık'].map((v)=>SimpleDialogOption(onPressed:()=>Navigator.pop(c,v),child:Text(v))).toList())); if(v!=null&&mounted){setState(()=>plan['period']=v);await _save();refresh((){});} }, child: const Text('Dönem')),
            OutlinedButton(onPressed: () async { await _editPlanField(plan,'status','Durum (Taslak / Aktif / Tamamlandı)'); refresh(() {}); }, child: const Text('Durum')),
            FilledButton.tonal(onPressed: () async { await _editPlanLine(plan); refresh(() {}); }, child: const Text('Ürün ekle')),
            OutlinedButton(onPressed: () async { await _planImport(plan); refresh(() {}); }, child: const Text('Aktif listeye aktar')),
          ]),
          TextField(decoration: const InputDecoration(labelText: 'Plan içinde ürün ara', prefixIcon: Icon(Icons.search)),
            onChanged: (v) => refresh(() => search = v)),
          SwitchListTile(title: const Text('Tamamlananları gizle'), value: onlyPending,
            onChanged: (v) => refresh(() => onlyPending = v)),
          Row(children: [Expanded(child: DropdownButton<String>(isExpanded: true, value: categories.contains(category) ? category : 'Tümü',
            items: categories.map((v) => DropdownMenuItem(value: v,child: Text(v, overflow: TextOverflow.ellipsis))).toList(),
            onChanged: (v) => refresh(() => category = v ?? 'Tümü'))),
            const SizedBox(width: 8), Expanded(child: DropdownButton<String>(isExpanded: true,value: sort,
              items: ['Öncelik','Fiyat','Ad'].map((v) => DropdownMenuItem(value: v,child: Text(v))).toList(),
              onChanged: (v) => refresh(() => sort = v ?? 'Öncelik')))]),
          ...displayed.map((entry) { final line = entry.value;
            return Card(child: Column(children: [CheckboxListTile(
