              subtitle: Text('${line['qty']} ${line['unit']} × ${_money(_planNum(line['unitPrice']))} = ${_money(_planNum(line['qty'])*_planNum(line['unitPrice']))}\n${line['category']} • ${line['store']} • Gerçek: ${_money(_planNum(line['actual']))}'),
              value: line['done'] == true, onChanged: (v) async {
                final updated = _planLines(plan); updated[entry.key]['done'] = v == true;
                setState(() => plan['lines'] = updated); refresh(() {}); await _save(); }),
              Wrap(spacing: 4, children: [
                TextButton(onPressed: () async { await _editPlanLine(plan,index:entry.key); refresh(() {}); },child: const Text('Düzenle')),
                TextButton(onPressed: () async { final v = await _planText('Gerçek tutar (TL)','${line['actual'] ?? 0}',numeric:true);
                  if (v == null || !mounted || _planNum(v)<0) return; final updated = _planLines(plan);
                  updated[entry.key]['actual'] = _planNum(v); setState(() => plan['lines'] = updated); refresh(() {}); await _save(); }, child: const Text('Gerçek fiyat')),
