  // Aşama 298–347: Stok ve tüketim verilerinden açıklanabilir öneriler.
  // Öneriler otomatik satın alma yapmaz; kullanıcı onayıyla yeni plan oluşturur.
  List<Map<String, dynamic>> _automationSuggestions(int horizonDays) {
    final now = DateTime.now();
    final result = <Map<String, dynamic>>[];
    final seen = <String>{};
    for (final record in _namedLists) {
      for (final name in (record['items'] as List? ?? const []).map((e) => e.toString())) {
        final key = name.trim().toLowerCase();
        if (key.isEmpty || !seen.add(key)) continue;
        final stock = _namedStock(record, name);
        final hasStock = (stock['amount']?.toString() ?? '').trim().isNotEmpty;
        if (!hasStock) continue;
        final current = _stockNumber(stock['amount']);
        final minimum = _stockNumber(stock['minimum']);
        final target = _stockTarget(record, name);
        final movements = _stockMovements(record).where((m) =>
          m['product']?.toString() == name && _isConsumptionMovement(m) &&
          _movementDate(m) != null && !_movementDate(m)!.isAfter(now)).toList();
        final oldest = movements.isEmpty ? null : movements
          .map((m) => _movementDate(m)!).reduce((a,b) => a.isBefore(b) ? a : b);
        final elapsed = oldest == null ? 0.0 :
          (now.difference(oldest).inMinutes / 1440).clamp(1.0, 365.0).toDouble();
        final consumed = movements.fold<double>(0, (sum,m) =>
          sum + ((m['change'] as num?)?.toDouble() ?? 0).abs());
        final rate = elapsed > 0 ? consumed / elapsed : 0.0;
        final demand = rate * horizonDays;
        final desired = [minimum, target, demand].reduce((a,b) => a > b ? a : b);
        final buy = (desired - current).clamp(0.0, 1000000.0).toDouble();
        final unitCost = _stockUnitCost(record, name);
        final daysLeft = rate > 0 ? current / rate : null;
        final critical = current <= 0 || (minimum > 0 && current <= minimum);
        final priority = current <= 0 ? 'Acil' : critical ? 'Yüksek' :
          (daysLeft != null && daysLeft <= horizonDays ? 'Orta' : 'Normal');
        result.add(<String, dynamic>{
          'name': name, 'current': current, 'minimum': minimum,
          'target': target, 'rate': rate, 'daysLeft': daysLeft,
          'demand': demand, 'buy': buy, 'unitCost': unitCost,
          'cost': buy * unitCost, 'priority': priority,
          'category': _namedCategory(record, name),
          'store': _namedProductMeta(record, name)['store'] ?? '',
          'unit': _namedQuantity(record, name)['unit'] ?? 'adet',
          'history': movements.length, 'hasPrice': unitCost > 0,
        });
      }
    }
    result.sort((a,b) {
      const rank = {'Acil': 0, 'Yüksek': 1, 'Orta': 2, 'Normal': 3};
      final r = (rank[a['priority']] ?? 4).compareTo(rank[b['priority']] ?? 4);
      return r != 0 ? r : (b['cost'] as double).compareTo(a['cost'] as double);
    });
    return result;
  }

  Future<void> _createAutomationPlan(List<Map<String, dynamic>> suggestions,
      int days, double limit, bool withinBudget) async {
    final eligible = suggestions.where((r) => (r['buy'] as double) > 0).toList();
    if (eligible.isEmpty) { _notice('Plan oluşturmak için stok ihtiyacı bulunamadı.'); return; }
    final selected = <Map<String, dynamic>>[];
    var running = 0.0;
    for (final row in eligible) {
      final cost = row['cost'] as double;
      if (withinBudget && limit > 0 &&
          (cost <= 0 || running + cost > limit)) { continue ; }
      selected.add(row);
      running += cost;
    }
    if (selected.isEmpty) { _notice('Bütçeye uygun fiyatlı ürün bulunamadı.'); return; }
    final yes = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Önerilerden plan oluştur'),
      content: Text('${selected.length} ürün, ${_money(running)} tahmini tutarla yeni bir '
        '$days günlük plana eklensin mi? Mevcut listeler değişmeyecek.'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Plan oluştur'))],
    ));
    if (yes != true || !mounted) return;
    final lines = selected.map((r) => <String, dynamic>{
      'name': r['name'], 'qty': r['buy'], 'unit': r['unit'],
      'unitPrice': r['unitCost'], 'category': r['category'], 'store': r['store'],
      'priority': r['priority'], 'done': false, 'actual': 0.0,
    }).toList();
    setState(() => _shoppingPlans.insert(0, <String, dynamic>{
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': '$days günlük akıllı alışveriş',
      'period': days <= 7 ? 'Haftalık' : 'Aylık',
      'created': DateTime.now().toIso8601String(), 'budget': limit,
      'note': 'Stok hedefi ve kayıtlı tüketimden önerildi. Tahminler kontrol edilmelidir.',
      'status': 'Taslak', 'lines': lines,
    }));
    await _save();
    _notice('${selected.length} ürünle yeni plan oluşturuldu.');
  }

  void _showAutomationDashboard() {
    int days = 7;
    double budget = 0;
    bool withinBudget = false;
    String filter = 'Tümü';
    String query = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final all = _automationSuggestions(days);
