        final unpriced = needed.where((r) => !(r['hasPrice'] as bool)).length;
        final withoutHistory = all.where((r) => (r['history'] as int) == 0).length;
        final critical = all.where((r) => r['priority'] == 'Acil' || r['priority'] == 'Yüksek').length;
        final categories = <String, double>{};
        for (final r in needed) {
          final c = r['category'].toString();
          categories[c] = (categories[c] ?? 0) + (r['cost'] as double);
        }
        final categoryRows = categories.entries.toList()..sort((a,b) => b.value.compareTo(a.value));
        return SafeArea(child: FractionallySizedBox(heightFactor: .91,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı alışveriş otomasyonu', style: TextStyle(
              fontSize: 21, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Öneriler yalnızca kayıtlı stok ve tüketim verilerine dayanır.'),
            const SizedBox(height: 12),
            Wrap(spacing: 8, children: [7, 14, 30].map((d) => ChoiceChip(
              label: Text('$d gün'), selected: days == d,
              onSelected: (_) => refresh(() => days = d))).toList()),
            Text('Takip edilen ürün: ${all.length} • Yenileme ihtiyacı: ${needed.length}'),
            Text('Kritik ürün: $critical • Tahmini ihtiyaç: ${_money(total)}',
