  // Aşamalar 348–447: Mutfak asistanı. Kaynak veriler yalnızca kayıtlı
  // listeler ve stok bilgileridir; dış servis veya otomatik sipariş kullanılmaz.
  static const _kitchenRecipes = <String, List<String>>{
    'Menemen': ['Domates', 'Yumurta', 'Biber'],
    'Peynirli omlet': ['Yumurta', 'Peynir', 'Süt'],
    'Mercimek çorbası': ['Mercimek', 'Soğan', 'Havuç'],
    'Sebze çorbası': ['Patates', 'Havuç', 'Kabak'],
    'Yoğurtlu makarna': ['Makarna', 'Yoğurt', 'Sarımsak'],
    'Domatesli makarna': ['Makarna', 'Domates', 'Soğan'],
    'Patatesli yumurta': ['Patates', 'Yumurta', 'Soğan'],
    'Pirinç pilavı': ['Pirinç', 'Tereyağı'],
    'Bulgur pilavı': ['Bulgur', 'Domates', 'Soğan'],
    'Sebzeli bulgur': ['Bulgur', 'Kabak', 'Havuç'],
    'Yoğurtlu salatalık': ['Yoğurt', 'Salatalık'],
    'Peynirli tost': ['Ekmek', 'Peynir'],
  };

  Map<String, List<String>> _allKitchenRecipes() {
    final result = Map<String, List<String>>.from(_kitchenRecipes);
    for (final recipe in _customRecipes) {
      final name = recipe['name']?.toString() ?? '';
      if (name.isEmpty) continue;
      final parts = (recipe['ingredients'] as List? ?? []);
      result[name] = parts.whereType<Map>().map((e) => e['name']?.toString() ?? '')
        .where((e) => e.isNotEmpty).toList();
    }
    return result;
  }

  Map<String, Map<String, double>> _allPortionGuides() {
    final result = Map<String, Map<String, double>>.from(_portionIngredientGuide);
    for (final recipe in _customRecipes) {
      final name = recipe['name']?.toString() ?? '';
      if (name.isEmpty) continue;
      final parts = (recipe['ingredients'] as List? ?? []);
      result[name] = {
        for (final e in parts.whereType<Map>())
          if ((e['name']?.toString() ?? '').isNotEmpty)
            e['name'].toString(): _planNum(e['quantity']),
      };
    }
    return result;
  }

  Future<void> _createCustomRecipe({Map<String, dynamic>? existing}) async {
    final title = TextEditingController(text: existing?['name']?.toString() ?? '');
    final baseValue = _planNum(existing?['basePortions'] ?? 2).toInt().clamp(1, 30);
    final ingredients = TextEditingController(text: existing == null ? '' :
      (existing['ingredients'] as List? ?? []).whereType<Map>().map((part) =>
        '${part['name']};${(_planNum(part['quantity']) * baseValue).toStringAsFixed(2)};${part['unit']}').join('\n'));
    final portions = TextEditingController(text: '$baseValue');
    final result = await showDialog<Map<String, dynamic>>(context: context,
      builder: (ctx) => AlertDialog(
        title: Text(existing == null ? 'Kendi tarifimi oluştur' : 'Tarifi düzenle'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(controller: title, maxLength: 60,
            decoration: const InputDecoration(labelText: 'Tarif adı')),
          TextField(controller: portions, keyboardType: TextInputType.number,
            decoration: const InputDecoration(labelText: 'Temel porsiyon sayısı')),
          TextField(controller: ingredients, minLines: 4, maxLines: 9,
            decoration: const InputDecoration(labelText: 'Her satıra: Malzeme;Miktar;Birim',
              hintText: 'Süt;0.5;L\nYumurta;2;adet')),
          const Text('Miktarlar temel tarifin tamamı içindir. Birimler: adet, g, kg, ml, L.',
            style: TextStyle(fontSize: 12)),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
          FilledButton(onPressed: () {
            final name = title.text.trim();
            final base = int.tryParse(portions.text.trim()) ?? 0;
            if (name.isEmpty || base < 1 || base > 30 ||
                (name != existing?['name'] && _allKitchenRecipes().containsKey(name))) { return ; }
            final parts = <Map<String, dynamic>>[];
            for (final line in ingredients.text.split('\n')) {
              if (line.trim().isEmpty) continue;
              final fields = line.split(';').map((e) => e.trim()).toList();
              if (fields.length != 3) return;
              final qty = double.tryParse(fields[1].replaceAll(',', '.'));
              if (fields[0].isEmpty || qty == null || qty <= 0 ||
                  !['adet', 'g', 'kg', 'ml', 'L'].contains(fields[2])) { return ; }
              parts.add({'name': fields[0], 'quantity': qty / base, 'unit': fields[2]});
            }
            if (parts.isEmpty) return;
            Navigator.pop(ctx, {'name': name, 'basePortions': base, 'ingredients': parts});
          }, child: const Text('Tarifi kaydet'))],
      ));
    disposeAfterDialog(title); disposeAfterDialog(ingredients); disposeAfterDialog(portions);
    if (result == null || !mounted) return;
    setState(() {
      if (existing == null) {
        _customRecipes.add(result);
      } else {
        final index = _customRecipes.indexOf(existing);
        if (index >= 0) _customRecipes[index] = result;
        // Existing meal records refer to the recipe by name.
        if (existing['name'] != result['name']) {
          for (final meal in _kitchenMeals) {
            if (meal['recipe'] == existing['name']) meal['recipe'] = result['name'];
          }
        }
      }
    });
    await _save();
    _notice(existing == null ? 'Yeni tarif kaydedildi.' : 'Tarif güncellendi.');
  }

  void _showCustomRecipes() {
    int page = 0;
    String query = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) => SafeArea(
        child: FractionallySizedBox(heightFactor: .8, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Kendi tariflerim', style: TextStyle(fontSize: 20,
            color: _purple, fontWeight: FontWeight.bold)),
          FilledButton.tonalIcon(onPressed: () async {
            await _createCustomRecipe(); refresh(() {});
          }, icon: const Icon(Icons.add), label: const Text('Tarif ekle')),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Tarif veya malzeme ara'),
            onChanged: (v) => refresh(() { query = v.trim().toLowerCase(); page = 0; })),
          if (_customRecipes.isEmpty) const Text('Henüz kişisel tarif oluşturulmadı.'),
          Builder(builder: (_) {
            final matches = _customRecipes.where((r) =>
              '${r['name']} ${(r['ingredients'] as List? ?? []).whereType<Map>().map((i) => i['name']).join(' ')}'
                .toLowerCase().contains(query)).toList();
            final pages = matches.isEmpty ? 1 : (matches.length + 19) ~/ 20;
            final safe = page.clamp(0, pages - 1).toInt();
            return Column(children: [
              _kitchenPageControls(matches.length, safe, 20,
                (p) => refresh(() => page = p)),
              if (matches.isEmpty && _customRecipes.isNotEmpty)
                const ListTile(title: Text('Aramayla eşleşen tarif yok.')),
              ...matches.skip(safe * 20).take(20).map((recipe) => Card(child: Column(children: [
            ListTile(title: Text(recipe['name']?.toString() ?? ''),
              subtitle: Text((recipe['ingredients'] as List? ?? []).whereType<Map>()
                .map((e) => '${e['name']}: ${e['quantity']} ${e['unit']} / porsiyon').join(' • '))),
            Wrap(spacing: 8, children: [
              TextButton(onPressed: () async {
                await _createCustomRecipe(existing: recipe); refresh(() {});
              }, child: const Text('Düzenle')),
              TextButton(onPressed: () async {
                final copy = Map<String, dynamic>.from(recipe);
                final names = _allKitchenRecipes().keys.toSet();
                var name = '${recipe['name']} (kopya)';
                var suffix = 2;
                while (names.contains(name)) { name = '${recipe['name']} (kopya $suffix)'; suffix++; }
                copy['name'] = name;
                setState(() => _customRecipes.add(copy));
                await _save(); refresh(() {});
              }, child: const Text('Kopyala')),
              TextButton(onPressed: () => _kitchenAddMeal(recipe['name'].toString()),
                child: const Text('Yemek planına ekle')),
              TextButton(onPressed: () async {
                final confirm = await showDialog<bool>(context: context,
                  builder: (c) => AlertDialog(title: const Text('Tarif silinsin mi?'),
                    content: const Text('Mevcut yemek planı kayıtları korunur.'),
                    actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(c, true), child: const Text('Sil'))]));
                if (confirm != true || !mounted) return;
                await _removeKitchenRecordWithUndo(_customRecipes, recipe, 'Kişisel tarif', refresh: refresh);
              }, child: const Text('Sil')),
            ]),
          ]))),
            ]);
          }),
        ])))));
  }

  List<Map<String, dynamic>> _scaledMealIngredients(int days) {
    final guides = _allPortionGuides();
    final start = DateTime.now();
    final dayStart = DateTime(start.year, start.month, start.day);
    final end = dayStart.add(Duration(days: days));
    final totals = <String, Map<String, dynamic>>{};
    for (final meal in _kitchenMeals) {
      if (meal['done'] == true) continue;
      final date = DateTime.tryParse(meal['date']?.toString() ?? '');
      if (date == null || date.isBefore(dayStart) || !date.isBefore(end)) continue;
      final recipeName = meal['recipe']?.toString() ?? '';
      final guide = guides[recipeName];
      if (guide == null) continue;
      final custom = _customRecipes.where((e) => e['name'] == recipeName);
      final portions = _planNum(meal['portions'] ?? 2).clamp(1, 30);
      for (final part in guide.entries) {
        String unit = _portionUnit(part.key);
        if (custom.isNotEmpty) {
          for (final ingredient in (custom.first['ingredients'] as List? ?? []).whereType<Map>()) {
            if (ingredient['name'] == part.key) unit = ingredient['unit']?.toString() ?? unit;
          }
        }
        final key = '${_normalizeName(part.key)}|$unit';
        totals.putIfAbsent(key, () => {'name': part.key, 'unit': unit, 'quantity': 0.0});
        totals[key]!['quantity'] = _planNum(totals[key]!['quantity']) + part.value * portions;
      }
    }
    return totals.values.toList();
  }

  // Convert mass and volume to canonical units for safe like-for-like totals.
  // Never convert between count, mass and volume without a density/package size.
  Map<String, dynamic> _canonicalKitchenQuantity(double quantity, String unit) {
    if (unit == 'kg') return {'quantity': quantity * 1000, 'unit': 'g'};
    if (unit == 'L') return {'quantity': quantity * 1000, 'unit': 'ml'};
    return {'quantity': quantity, 'unit': unit};
  }

  // Aşama 848–947: unit-safe shopping requirement report.
  // Counts, mass and volume are never mixed without a product conversion factor.
  List<Map<String, dynamic>> _normalizedKitchenNeeds(int days) {
    final totals = <String, Map<String, dynamic>>{};
    for (final item in _scaledMealIngredients(days)) {
      final name = item['name']?.toString() ?? '';
      final converted = _canonicalKitchenQuantity(
        _planNum(item['quantity']), item['unit']?.toString() ?? 'adet');
      final unit = converted['unit'].toString();
      final key = '${_normalizeName(name)}|$unit';
      totals.putIfAbsent(key, () => {
        'name': name, 'unit': unit, 'quantity': 0.0,
      });
      totals[key]!['quantity'] = _planNum(totals[key]!['quantity']) +
        _planNum(converted['quantity']);
    }
    final result = totals.values.toList();
    result.sort((a, b) => a['name'].toString().compareTo(b['name'].toString()));
    return result;
  }

  // Aşamalar 948–1047: Quantity-aware kitchen reconciliation.
  // Stock unit is inferred from saved list quantity metadata, never guessed
  // from product names. Unknown units are excluded from subtraction.
  List<Map<String, dynamic>> _kitchenQuantityReconciliation(int days) {
    final stockByKey = <String, double>{};
    final unknown = <String>{};
    final sources = <String, Set<String>>{};
    for (final record in _namedLists) {
      final names = (record['items'] as List? ?? []).map((e) => e.toString());
      for (final name in names) {
        final keyName = _normalizeName(name);
        final stockMeta = _namedStock(record, name);
        final amountText = stockMeta['amount']?.trim() ?? '';
        if (amountText.isEmpty) continue;
        final amount = double.tryParse(amountText.replaceAll(',', '.'));
        if (amount == null || !amount.isFinite || amount < 0) continue;
        final rawQuantities = record['quantities'] is Map ? record['quantities'] as Map : null;
        final quantityMeta = rawQuantities?[name];
        final unit = quantityMeta is Map ? quantityMeta['unit']?.toString() : null;
        if (unit == null || !_units.contains(unit)) {
          unknown.add(keyName);
          continue;
        }
        final converted = _canonicalKitchenQuantity(amount, unit);
        final key = '$keyName|${converted['unit']}';
        // Multiple named lists can represent the same physical stock.
        // Choose the largest recorded value rather than summing duplicates.
        final value = _planNum(converted['quantity']);
        if (value > (stockByKey[key] ?? 0)) stockByKey[key] = value;
        sources.putIfAbsent(key, () => <String>{}).add(record['title']?.toString() ?? 'Liste');
      }
    }
    return _normalizedKitchenNeeds(days).map((item) {
      final name = item['name'].toString();
      final unit = item['unit'].toString();
      final key = '${_normalizeName(name)}|$unit';
      final required = _planNum(item['quantity']);
      final available = stockByKey[key];
      final deficit = available == null ? required :
        (required - available).clamp(0.0, double.infinity).toDouble();
      return <String, dynamic>{...item, 'required': required,
        'available': available, 'deficit': deficit,
        'unknownUnit': available == null && unknown.contains(_normalizeName(name)),
        'sources': sources[key]?.join(', ') ?? ''};
    }).toList();
  }

  Future<void> _createKitchenDeficitPlan(int days,
      List<Map<String, dynamic>> rows) async {
    final needed = rows.where((r) => _planNum(r['deficit']) > 0).toList();
    if (needed.isEmpty) { _notice('Bu dönem için eksik miktar bulunamadı.'); return; }
    final title = await _planText('Yeni mutfak planı adı',
      '$days günlük eksik mutfak malzemeleri');
    if (!mounted || title == null || title.isEmpty) return;
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Alışveriş planı oluşturulsun mu?'),
      content: Text('${needed.length} ürün yeni bir taslak plana kaydedilecek. '
        'Mevcut aktif alışveriş listesi değişmeyecek. Stok birimi bilinmeyen '
        'ürünler için ihtiyaç miktarının tamamı önerilir.'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false),
          child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true),
          child: const Text('Plan oluştur'))]));
    if (!mounted || confirmed != true) return;
    final lines = needed.map((r) => <String, dynamic>{
      'name': r['name'], 'qty': r['deficit'], 'unit': r['unit'],
      'unitPrice': 0.0, 'category': _guess(r['name'].toString()),
      'store': '', 'done': false, 'actual': 0.0,
      'priority': r['unknownUnit'] == true ? 'Yüksek' : 'Normal',
    }).toList();
    setState(() => _shoppingPlans.insert(0, <String, dynamic>{
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': title, 'period': days == 30 ? 'Aylık' : 'Haftalık',
      'created': DateTime.now().toIso8601String(), 'budget': 0.0,
      'note': 'Mutfak miktar analizi ($days gün). Stok ve birim bilgilerini kontrol edin.',
      'lines': lines, 'status': 'Taslak',
    }));
    await _save();
    _notice('${needed.length} ürün içeren taslak alışveriş planı kaydedildi.');
  }

  void _showKitchenQuantityBalance() {
    int days = 7;
    bool onlyDeficit = true;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final all = _kitchenQuantityReconciliation(days);
        final rows = onlyDeficit ? all.where((r) =>
          _planNum(r['deficit']) > 0).toList() : all;
        final unknown = all.where((r) => r['available'] == null).length;
        final unresolved = all.where((r) => r['unknownUnit'] == true).length;
        return SafeArea(child: FractionallySizedBox(heightFactor: .90,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Mutfak stok yeterlilik analizi', style: TextStyle(
              fontSize: 21, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Miktarlar yalnızca aynı ürün ve uyumlu birimlerde karşılaştırılır.'),
            const SizedBox(height: 8),
            Wrap(spacing: 8, children: [7, 14, 30].map((d) => ChoiceChip(
              label: Text('$d gün'), selected: days == d,
              onSelected: (_) => refresh(() => days = d))).toList()),
            SwitchListTile(title: const Text('Yalnızca eksik miktarlar'),
              value: onlyDeficit,
              onChanged: (v) => refresh(() => onlyDeficit = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Malzeme: ${all.length} • Eksik: ${all.where((r) => _planNum(r['deficit']) > 0).length}'),
                Text('Karşılaştırılamayan stok: $unknown • Birimi belirsiz: $unresolved'),
                const Text('Birden fazla listede aynı stok varsa en yüksek değer alınır; stoklar toplanmaz.',
                  style: TextStyle(fontSize: 12)),
              ]))),
            ...rows.map((r) => Card(child: ListTile(
              title: Text(r['name'].toString()),
              subtitle: Text('İhtiyaç: ${_planNum(r['required']).toStringAsFixed(2)} ${r['unit']}\n'
                'Stok: ${r['available'] == null ? 'Birim uyumlu kayıt yok' : '${_planNum(r['available']).toStringAsFixed(2)} ${r['unit']}'}\n'
                'Eksik: ${_planNum(r['deficit']).toStringAsFixed(2)} ${r['unit']}'
                '${r['unknownUnit'] == true ? ' • Stok birimini doğrula' : ''}'),
              trailing: Icon(_planNum(r['deficit']) > 0 ?
                Icons.warning_amber : Icons.check_circle_outline,
                color: _planNum(r['deficit']) > 0 ? Colors.deepOrange : Colors.green),
            ))),
            if (rows.isEmpty) const Text('Bu dönem için gösterilecek malzeme yok.'),
            FilledButton.tonalIcon(onPressed: () async {
              await _createKitchenDeficitPlan(days, all);
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.playlist_add),
              label: const Text('Eksik miktarlardan taslak plan oluştur')),
            OutlinedButton.icon(onPressed: () async {
              final csv = <String>['Malzeme;İhtiyaç;Birim;Stok;Eksik;Birim belirsiz'];
