          return <String, dynamic>{...row, 'hasStock': hasStock};
        }).toList();
        final visible = onlyMissing ? rows.where((r) => r['hasStock'] != true).toList() : rows;
        final missing = rows.where((r) => r['hasStock'] != true).length;
        return SafeArea(child: FractionallySizedBox(heightFactor: .86,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Mutfak • birim uyumlu ihtiyaç raporu',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            const Text('kg → g, L → ml dönüştürülür. Adet, gram ve mililitre birbirine çevrilmez. Stok birimleri doğrulanamadığı için stoktan otomatik miktar düşülmez.',
              style: TextStyle(fontSize: 12)),
            Wrap(spacing: 8, children: [7, 14, 30].map((n) => ChoiceChip(
              label: Text('$n gün'), selected: days == n,
              onSelected: (_) => refresh(() => days = n))).toList()),
            SwitchListTile(contentPadding: EdgeInsets.zero,
              title: const Text('Yalnızca stok kaydı bulunmayanlar'),
              value: onlyMissing,
              onChanged: (value) => refresh(() => onlyMissing = value)),
            Text('Toplam ${rows.length} malzeme/birim • Stok kaydı olmayan $missing'),
            if (visible.isEmpty) const Padding(padding: EdgeInsets.all(16),
              child: Text('Gösterilecek ihtiyaç bulunmuyor.')),
            ...visible.map((row) => Card(child: ListTile(
              title: Text(row['name'].toString()),
              subtitle: Text('İhtiyaç: ${_planNum(row['quantity']).toStringAsFixed(2)} ${row['unit']}'),
              trailing: Icon(row['hasStock'] == true ? Icons.inventory_2_outlined :
                Icons.warning_amber_rounded, color: row['hasStock'] == true ?
                Colors.green : Colors.deepOrange)))),
            FilledButton.tonalIcon(onPressed: rows.isEmpty ? null : () async {
              final buffer = StringBuffer('Malzeme;Miktar;Birim;Stok kaydı\n');
              for (final row in rows) {
                final name = row['name'].toString().replaceAll(';', ',').replaceAll('\n', ' ');
                buffer.writeln('$name;${_planNum(row['quantity']).toStringAsFixed(2)};${row['unit']};${row['hasStock'] == true ? 'Var' : 'Yok'}');
              }
              await Clipboard.setData(ClipboardData(text: buffer.toString()));
              if (mounted) _notice('İhtiyaç raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
            FilledButton.tonalIcon(onPressed: missing == 0 ? null : () async {
              await _kitchenAddMissing(rows.where((r) => r['hasStock'] != true)
                .map((r) => r['name'].toString()).toList());
            }, icon: const Icon(Icons.add_shopping_cart),
              label: const Text('Stok kaydı olmayanları listeye ekle')),
          ])));
      }));
  }

  // Aşama 1048–1147: Kullanıcı tarafından tanımlanmış birim fiyatlar.
  // Alışveriş toplam fiyatları burada kullanılmaz; yanlış maliyet üretmez.
  String _ingredientPriceKey(String name, String unit) {
    final canonical = _canonicalKitchenQuantity(1, unit)['unit'].toString();
    return '${_normalizeName(name)}|$canonical';
  }

  Future<void> _editIngredientUnitPrice(String name, String unit) async {
    final key = _ingredientPriceKey(name, unit);
    final previous = _ingredientUnitPrices[key];
    final controller = TextEditingController(text: previous?.toString() ?? '');
    final result = await showDialog<double>(context: context, builder: (ctx) => AlertDialog(
      title: Text('$name • birim fiyat'),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        Text('1 $unit için TL tutarı. Örnek: 1 kg = 100 TL ise 1 g = 0,10 TL.'),
        TextField(controller: controller, keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: InputDecoration(labelText: 'TL / $unit')),
      ]),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx,
          double.tryParse(controller.text.trim().replaceAll(',', '.')) ?? -1),
          child: const Text('Kaydet'))],
    ));
    disposeAfterDialog(controller);
    if (result == null || !mounted) return;
    if (!result.isFinite || result < 0) { _notice('Geçerli ve negatif olmayan fiyat girin.'); return; }
    setState(() => _ingredientUnitPrices[key] = result);
    await _save();
  }

  void _showKitchenUnitCosts() {
    int days = 7;
    bool onlyMissingPrice = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final rows = _normalizedKitchenNeeds(days);
        double estimated = 0;
        int priced = 0;
        for (final row in rows) {
          final key = _ingredientPriceKey(row['name'].toString(), row['unit'].toString());
          final price = _ingredientUnitPrices[key];
          if (price != null) { priced++; estimated += price * _planNum(row['quantity']); }
        }
        final visible = rows.where((r) => !onlyMissingPrice ||
          !_ingredientUnitPrices.containsKey(_ingredientPriceKey(r['name'].toString(), r['unit'].toString()))).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Mutfak birim fiyatları ve tahmini maliyet', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Fiyatları 1 g / 1 ml / 1 adet başına TL olarak kaydedin. '
              'Paket fiyatı veya farklı birimdeki fiyatı doğrudan girmeyin.',
              style: TextStyle(fontSize: 12)),
            Wrap(spacing: 8, children: [7, 14, 30].map((d) => ChoiceChip(
              label: Text('$d gün'), selected: days == d,
              onSelected: (_) => refresh(() => days = d))).toList()),
            SwitchListTile(title: const Text('Yalnızca fiyatı eksik malzemeler'),
              value: onlyMissingPrice, onChanged: (v) => refresh(() => onlyMissingPrice = v)),
            Card(color: const Color(0xFFF3E8FF), child: Padding(
              padding: const EdgeInsets.all(12), child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Bilinen maliyet: ${_money(estimated)}',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
                Text('Fiyatı tanımlı: $priced / ${rows.length} malzeme'),
                if (priced < rows.length) const Text('Toplam maliyet eksiktir; fiyatı olmayan ürünler sıfır maliyetli kabul edilmez.'),
              ]))),
            ...visible.map((r) {
              final name = r['name'].toString();
              final unit = r['unit'].toString();
              final price = _ingredientUnitPrices[_ingredientPriceKey(name, unit)];
              return Card(child: ListTile(title: Text(name),
                subtitle: Text('İhtiyaç: ${_planNum(r['quantity']).toStringAsFixed(2)} $unit\n'
                  'Birim fiyat: ${price == null ? 'Girilmeli' : '${price.toStringAsFixed(4)} TL/$unit'}'),
                trailing: Text(price == null ? '—' : _money(price * _planNum(r['quantity']))),
                onTap: () async { await _editIngredientUnitPrice(name, unit); if (ctx.mounted) refresh(() {}); },
              ));
            }),
            OutlinedButton.icon(onPressed: rows.isEmpty ? null : () async {
              final csv = <String>['Malzeme;Miktar;Birim;Birim fiyat TL;Tahmini tutar TL'];
              for (final r in rows) {
                final name = r['name'].toString().replaceAll(';', ',').replaceAll('\n', ' ');
                final unit = r['unit'].toString();
                final price = _ingredientUnitPrices[_ingredientPriceKey(name, unit)];
                csv.add('$name;${r['quantity']};$unit;${price ?? ''};${price == null ? '' : price * _planNum(r['quantity'])}');
              }
              await Clipboard.setData(ClipboardData(text: csv.join('\n')));
              if (mounted) _notice('Maliyet raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Maliyet CSV kopyala')),
          ])));
      }));
  }


  // Aşama 1148–1247: canonical-unit recipe pricing, no package-price guesses.
  Map<String, dynamic> _customRecipeCost(Map<String, dynamic> recipe, int portions) {
    final base = _planNum(recipe['basePortions']).clamp(1, 30).toDouble();
    double known = 0;
    final missing = <String>[];
    final breakdown = <Map<String, dynamic>>[];
    for (final ingredient in (recipe['ingredients'] as List? ?? []).whereType<Map>()) {
      final name = ingredient['name']?.toString().trim() ?? '';
      if (name.isEmpty) continue;
      final rawUnit = ingredient['unit']?.toString() ?? 'adet';
      final converted = _canonicalKitchenQuantity(
        _planNum(ingredient['quantity']) * portions / base, rawUnit);
      final unit = converted['unit'].toString();
      final qty = _planNum(converted['quantity']);
      final price = _ingredientUnitPrices[_ingredientPriceKey(name, unit)];
      if (price == null) { missing.add('$name ($unit)'); }
      else { known += qty * price; }
      breakdown.add({'name': name, 'quantity': qty, 'unit': unit,
        'price': price, 'total': price == null ? null : qty * price});
    }
    return {'known': known, 'missing': missing, 'rows': breakdown};
  }

