            OutlinedButton.icon(onPressed: rows.isEmpty ? null : () async {
              final csv = <String>['Tarif;Porsiyon;Malzeme;Miktar;Birim;Birim fiyat TL;Tutar TL'];
              String safe(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
              for (final item in rows) {
                final recipe = item['recipe'] as Map<String, dynamic>;
                final cost = item['cost'] as Map<String, dynamic>;
                for (final r in cost['rows'] as List<Map<String, dynamic>>) {
                  csv.add([recipe['name'], portions, r['name'], r['quantity'],
                    r['unit'], r['price'], r['total']].map(safe).join(';'));
                }
              }
              await Clipboard.setData(ClipboardData(text: csv.join('\n')));
              if (mounted) _notice('Tarif maliyet raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Tarif maliyet CSV kopyala')),
          ])));
      }));
  }

  Future<void> _saveCurrentWeekTemplate() async {
    final now = DateTime.now();
    final monday = DateTime(now.year, now.month, now.day)
      .subtract(Duration(days: now.weekday - 1));
    final end = monday.add(const Duration(days: 7));
    final meals = _kitchenMeals.where((m) {
      final date = DateTime.tryParse(m['date']?.toString() ?? '');
      return date != null && !date.isBefore(monday) && date.isBefore(end);
    }).map((m) {
      final date = DateTime.parse(m['date'].toString());
      return {...m, 'weekday': date.weekday, 'done': false};
    }).toList();
    if (meals.isEmpty) { _notice('Bu hafta şablona kaydedilecek öğün yok.'); return; }
    final name = await _planText('Haftalık şablon adı', 'Aile haftalık menüsü');
    if (name == null || name.trim().isEmpty || !mounted) return;
    setState(() => _mealTemplates.add({
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'name': name.trim(), 'meals': meals,
    }));
    await _save();
    _notice('${meals.length} öğün şablona kaydedildi.');
  }

  void _showMealTemplates() {
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        return SafeArea(child: FractionallySizedBox(heightFactor: .8,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Haftalık yemek planı şablonları', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            FilledButton.tonalIcon(onPressed: () async {
              await _saveCurrentWeekTemplate();
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.save), label: const Text('Bu haftayı şablon olarak kaydet')),
            if (_mealTemplates.isEmpty) const Text('Henüz kayıtlı şablon yok.'),
            ..._mealTemplates.map((template) => Card(child: ListTile(
              title: Text(template['name']?.toString() ?? 'Şablon'),
              subtitle: Text('${(template['meals'] as List? ?? []).length} öğün'),
              trailing: IconButton(tooltip: 'Şablonu sil', icon: const Icon(Icons.delete_outline),
                onPressed: () async {
                  final yes = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
                    title: const Text('Şablonu sil?'),
                    content: Text('“${template['name'] ?? 'Şablon'}” silinecek. Mevcut yemek planları korunur.'),
                    actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Sil'))]));
                  if (yes != true) return;
                  setState(() => _mealTemplates.remove(template));
                  await _save();
                  if (ctx.mounted) refresh(() {});
                }),
              onTap: () async {
                final today = DateTime.now();
                final monday = DateTime(today.year, today.month, today.day)
                  .subtract(Duration(days: today.weekday - 1));
                final yes = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
                  title: const Text('Şablonu bu haftaya uygula'),
                  content: const Text('Mevcut öğünler korunur; aynı öğünler tekrar eklenmez.'),
                  actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                    FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Uygula'))]));
                if (yes != true) return;
                var added = 0;
                setState(() {
                  for (final raw in (template['meals'] as List? ?? []).whereType<Map>()) {
                    final meal = Map<String, dynamic>.from(raw);
                    final day = _planNum(meal['weekday']).toInt();
                    if (day < 1 || day > 7) continue;
                    final date = monday.add(Duration(days: day - 1)).toIso8601String().split('T').first;
                    if (_kitchenMeals.any((m) => m['date'] == date &&
                      m['recipe'] == meal['recipe'] && m['mealType'] == meal['mealType'] &&
                      m['family'] == meal['family'])) { continue ; }
                    meal.remove('weekday');
                    _kitchenMeals.add({...meal, 'date': date, 'done': false});
                    added++;
                  }
                });
                if (added > 0) await _save();
                if (ctx.mounted) refresh(() {});
                _notice('$added öğün bu haftaya eklendi.');
              },
            ))),
          ])));
      }));
  }

  Future<void> _copyLastWeekMeals() async {
    final now = DateTime.now();
    final monday = DateTime(now.year, now.month, now.day).subtract(Duration(days: now.weekday - 1));
    final lastMonday = monday.subtract(const Duration(days: 7));
    final previous = _kitchenMeals.where((m) {
      final date = DateTime.tryParse(m['date']?.toString() ?? '');
      return date != null && !date.isBefore(lastMonday) && date.isBefore(monday);
    }).toList();
    if (previous.isEmpty) { _notice('Önceki haftaya ait yemek planı bulunamadı.'); return; }
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Önceki haftayı kopyala'),
      content: Text('${previous.length} öğün bu haftaya kopyalansın mı? Mevcut öğünler silinmez.'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Kopyala'))],
    ));
    if (confirmed != true || !mounted) return;
    int added = 0;
    setState(() {
      for (final meal in previous) {
        final old = DateTime.tryParse(meal['date']?.toString() ?? '');
        if (old == null) continue;
        final next = old.add(const Duration(days: 7)).toIso8601String().split('T').first;
        final duplicate = _kitchenMeals.any((m) => m['date'] == next &&
          m['recipe'] == meal['recipe'] && m['mealType'] == meal['mealType'] &&
          m['family'] == meal['family']);
        if (duplicate) continue;
        _kitchenMeals.add({...Map<String, dynamic>.from(meal), 'date': next, 'done': false});
        added++;
      }
    });
    if (added > 0) await _save();
    _notice('$added öğün bu haftaya eklendi.');
  }

  void _showRecipeCostAnalysis() {
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final rows = <Map<String, dynamic>>[];
        for (final recipe in _customRecipes) {
          double total = 0;
          int priced = 0;
          final ingredients = (recipe['ingredients'] as List? ?? []).whereType<Map>();
          for (final part in ingredients) {
            final name = part['name']?.toString() ?? '';
            final match = _prices.entries.where((e) =>
              _normalizeName(e.key) == _normalizeName(name));
            if (match.isNotEmpty) {
              // Price is a shopping-list total, not necessarily a unit price.
              // Show it as a reference only; do not multiply by ingredient quantity.
              total += match.first.value;
              priced++;
            }
          }
          rows.add({'name': recipe['name'], 'count': ingredients.length,
            'priced': priced, 'reference': total});
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .75,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Kişisel tarifler • fiyat referansları', style: TextStyle(
              fontSize: 20, color: _purple, fontWeight: FontWeight.bold)),
            const Text('Alışveriş fiyatları paket/toplam tutar olabilir. Bu ekran gerçek tarif maliyeti veya porsiyon maliyeti hesaplamaz; yalnızca eşleşen fiyat referanslarını gösterir.',
              style: TextStyle(fontSize: 12)),
            if (rows.isEmpty) const Text('Önce kişisel tarif ekleyin.'),
            ...rows.map((row) => Card(child: ListTile(
              title: Text(row['name']?.toString() ?? ''),
              subtitle: Text('Fiyat eşleşmesi: ${row['priced']}/${row['count']} malzeme'),
              trailing: Text(_money(_planNum(row['reference']))),
            ))),
          ])));
      }));
  }

  void _showPreciseKitchenNeeds() {
