    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final rows = _scaledMealIngredients(days);
        final stocks = _kitchenStockRows();
        return SafeArea(child: FractionallySizedBox(heightFactor: .85,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Porsiyon ve miktar bazında ihtiyaçlar',
              style: TextStyle(fontSize: 20, color: _purple, fontWeight: FontWeight.bold)),
            const Text('Kişisel tariflerin birimleri korunur. Stoklar farklı birimlerde tutulabileceği için eksik miktar otomatik düşülmez.',
              style: TextStyle(fontSize: 12)),
            Wrap(spacing: 8, children: [7, 14, 30].map((n) => ChoiceChip(
              label: Text('$n gün'), selected: days == n,
              onSelected: (_) => refresh(() => days = n))).toList()),
            if (rows.isEmpty) const Text('Seçilen dönemde planlanan malzeme yok.'),
            ...rows.map((r) {
              final found = stocks.any((s) => _normalizeName(s['name'].toString()) ==
                _normalizeName(r['name'].toString()) && _planNum(s['stock']) > 0);
              return ListTile(title: Text(r['name'].toString()),
                subtitle: Text('${_planNum(r['quantity']).toStringAsFixed(2)} ${r['unit']}'),
                trailing: Icon(found ? Icons.inventory_2_outlined : Icons.warning_amber_outlined,
                  color: found ? Colors.green : Colors.deepOrange));
            }),
            FilledButton.tonalIcon(onPressed: () async {
              final missing = rows.where((r) => !stocks.any((s) =>
                _normalizeName(s['name'].toString()) == _normalizeName(r['name'].toString()) &&
                _planNum(s['stock']) > 0)).map((r) => r['name'].toString()).toList();
              await _kitchenAddMissing(missing);
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.add_shopping_cart),
              label: const Text('Stok kaydı olmayanları alışverişe ekle')),
            OutlinedButton.icon(onPressed: () {
              final csv = <String>['Malzeme;Miktar;Birim'];
              for (final r in rows) {
                csv.add('"${r['name'].toString().replaceAll('"', '""')}";${r['quantity']};${r['unit']}');
              }
              Clipboard.setData(ClipboardData(text: csv.join('\n')));
              _notice('Malzeme miktarları panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
          ])));
      }));
  }

  List<Map<String, dynamic>> _kitchenStockRows() {
    final result = <Map<String, dynamic>>[];
    final seen = <String>{};
    for (final record in _namedLists) {
      final names = (record['items'] as List? ?? []).map((e) => e.toString());
      for (final name in names) {
        final key = _normalizeName(name);
        if (seen.contains(key)) continue;
        seen.add(key);
        final info = _namedStock(record, name);
        final stock = _planNum(info['amount']);
        final expiry = info['expiry'] ?? '';
        final price = _stockUnitCost(record, name);
        final category = _namedCategory(record, name);
        result.add({'name': name, 'stock': stock, 'expiry': expiry,
          'price': price, 'category': category, 'source': record['title'] ?? ''});
      }
    }
    return result;
  }

  int? _kitchenDaysUntil(String raw) {
    if (raw.isEmpty) return null;
    final date = DateTime.tryParse(raw);
    if (date == null) return null;
    final now = DateTime.now();
    return DateTime(date.year, date.month, date.day)
      .difference(DateTime(now.year, now.month, now.day)).inDays;
  }

  List<Map<String, dynamic>> _kitchenSuggestions() {
    final stock = _kitchenStockRows();
    final result = <Map<String, dynamic>>[];
    for (final entry in _allKitchenRecipes().entries) {
      final missing = <String>[];
      final available = <String>[];
      var urgency = 0;
      for (final ingredient in entry.value) {
        Map<String, dynamic>? match;
        for (final row in stock) {
          if (_normalizeName(row['name'].toString()) == _normalizeName(ingredient)) {
            match = row; break;
          }
        }
        if (match == null || (match['stock'] as double) <= 0) {
          missing.add(ingredient);
        } else {
          available.add(ingredient);
          final days = _kitchenDaysUntil(match['expiry'].toString());
          if (days != null && days >= 0 && days <= 3) urgency++;
        }
      }
      result.add({'title': entry.key, 'available': available, 'missing': missing,
        'urgency': urgency, 'match': available.length / entry.value.length});
    }
    result.sort((a,b) {
      final urgent = (b['urgency'] as int).compareTo(a['urgency'] as int);
      if (urgent != 0) return urgent;
      return (b['match'] as double).compareTo(a['match'] as double);
    });
    return result;
  }

  Future<void> _kitchenAddMissing(List<String> missing) async {
    final newNames = missing.where((name) => !_items.any((e) =>
      _normalizeName(e) == _normalizeName(name))).toList();
    if (newNames.isEmpty) { _notice('Eksik malzemeler zaten alışveriş listesinde.'); return; }
    if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Eksik malzemeleri ekle'),
      content: Text('${newNames.join(', ')} aktif alışveriş listesine eklensin mi?'),
      actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Ekle'))]));
    if (confirmed != true || !mounted) return;
    setState(() { for (final name in newNames) {
      _items.add(name);
      _details.putIfAbsent(name, () => {'category': _guess(name), 'note': 'Mutfak önerisi'});
    }});
    await _save();
    _notice('${newNames.length} malzeme eklendi.');
  }

