  Map<String, int> _mealMissingIngredients(Iterable<Map<String, dynamic>> meals) {
    final result = <String, int>{};
    final stock = _kitchenStockRows();
    for (final meal in meals) {
      if (meal['done'] == true) continue;
      final recipe = meal['recipe']?.toString() ?? '';
      final ingredients = _allKitchenRecipes()[recipe];
      if (ingredients == null) continue;
      final portions = _planNum(meal['portions'] ?? 2).clamp(1, 30).toInt();
      for (final ingredient in ingredients) {
        final available = stock.any((row) =>
          _normalizeName(row['name'].toString()) == _normalizeName(ingredient) &&
          _planNum(row['stock']) > 0 &&
          ((_kitchenDaysUntil(row['expiry']?.toString() ?? '') ?? 1) >= 0));
        if (!available) result[ingredient] = (result[ingredient] ?? 0) + portions;
      }
    }
    return result;
  }

