        List<T> slice<T>(List<T> rows, int page) {
          final maxPage = rows.isEmpty ? 0 : (rows.length - 1) ~/ pageSize;
          final start = page.clamp(0, maxPage) * pageSize;
          return rows.skip(start).take(pageSize).toList();
