              TextButton.icon(onPressed: () {
                final lines = _kitchenMeals.map((m) =>
                  '${m['date']}: ${m['recipe']}${m['done'] == true ? ' ✓' : ''}').join('\n');
                Clipboard.setData(ClipboardData(text: lines));
                _notice('Yemek planı panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('Planı kopyala')),
            ],
            if (tab == 'İsraf raporu') ...[
              Text('Toplam kayıp: ${_money(loss)} • Bu ay: ${_money(monthlyLoss)}',
                style: const TextStyle(fontWeight: FontWeight.bold)),
              Text('İsraf kaydı: ${_kitchenWaste.length}'),
              FilledButton.tonalIcon(onPressed: () async {
                await _kitchenRecordWaste(); refresh(() {});
              }, icon: const Icon(Icons.add), label: const Text('İsraf kaydı ekle')),
              const Text('Neden bazında tahmini kayıp',
                style: TextStyle(fontWeight: FontWeight.bold)),
              ...reasons.entries.map((r) => ListTile(title: Text(r.key),
                trailing: Text(_money(r.value)))),
              TextField(decoration: const InputDecoration(
                prefixIcon: Icon(Icons.search), labelText: 'İsraf kaydı ara (ürün / neden / tarih)'),
                onChanged: (v) => refresh(() { wasteQuery = v; wastePage = 0; })),
              pageControls(filteredWaste.length, wastePage, (v) => wastePage = v),
              ...slice(filteredWaste, wastePage).map((r) => ListTile(
                title: Text(r['name']?.toString() ?? ''),
                subtitle: Text('${r['date'].toString().split('T').first} • '
                  '${r['reason']} • Miktar: ${r['quantity']} • '
                  '${_money(_planNum(r['cost']))}'),
                trailing: IconButton(
                  tooltip: 'İsraf kaydını sil',
                  icon: const Icon(Icons.delete_outline),
                  onPressed: () async {
                    final label = '${r['name'] ?? 'Ürün'} • ${r['date'] ?? ''}';
                    if (!await _confirmKitchenDelete('İsraf kaydı', label)) return;
                    if (!mounted || !_kitchenWaste.contains(r)) return;
                    final previousIndex = _kitchenWaste.indexOf(r);
                    final archived = _archiveDeleted(_kitchenWaste, r, previousIndex, label);
                    setState(() => _kitchenWaste.remove(r));
                    if (ctx.mounted) refresh(() {});
                    await _save();
                    if (!mounted) return;
                    ScaffoldMessenger.of(context).hideCurrentSnackBar();
                    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
                      content: const Text('İsraf kaydı silindi.'),
                      duration: const Duration(seconds: 7),
                      action: SnackBarAction(label: 'Geri al', onPressed: () async {
                        if (!mounted || _kitchenWaste.contains(r)) return;
                        setState(() => _kitchenWaste.insert(
                          previousIndex.clamp(0, _kitchenWaste.length), r));
                        if (archived != null) _kitchenTrash.remove(archived);
                        if (ctx.mounted) refresh(() {});
                        await _save();
                      }),
                    ));
                  },
                ),
              )),
              TextButton.icon(onPressed: () {
                final rows = <String>['Tarih;Ürün;Miktar;Neden;Kayıp TL'];
                for (final r in _kitchenWaste) {
                  rows.add([r['date'].toString().split('T').first, r['name'],
                    r['quantity'], r['reason'], r['cost']]
                    .map((e) => '"${e.toString().replaceAll('"', '""')}"').join(';'));
                }
                Clipboard.setData(ClipboardData(text: rows.join('\n')));
                _notice('İsraf raporu CSV biçiminde panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('CSV raporu kopyala')),
            ],
          ])));
      }));
  }


  // Aşamalar 548–647: yemek planı ihtiyaçları ve mutfak bütçe görünümü.
  // Miktarlar örnek planlama katsayılarıdır, beslenme reçetesi değildir.
  static const Map<String, Map<String, double>> _portionIngredientGuide = {
    'Menemen': {'Domates': 1, 'Yumurta': 1, 'Biber': 0.5},
    'Peynirli omlet': {'Yumurta': 2, 'Peynir': 0.05, 'Süt': 0.1},
    'Mercimek çorbası': {'Mercimek': 0.08, 'Soğan': 0.25, 'Havuç': 0.25},
    'Sebze çorbası': {'Patates': 0.5, 'Havuç': 0.5, 'Kabak': 0.5},
    'Yoğurtlu makarna': {'Makarna': 0.1, 'Yoğurt': 0.15, 'Sarımsak': 0.5},
    'Domatesli makarna': {'Makarna': 0.1, 'Domates': 1, 'Soğan': 0.25},
    'Patatesli yumurta': {'Patates': 1, 'Yumurta': 1, 'Soğan': 0.25},
    'Pirinç pilavı': {'Pirinç': 0.08, 'Tereyağı': 0.02},
    'Bulgur pilavı': {'Bulgur': 0.08, 'Domates': 0.5, 'Soğan': 0.25},
    'Sebzeli bulgur': {'Bulgur': 0.08, 'Kabak': 0.5, 'Havuç': 0.5},
    'Yoğurtlu salatalık': {'Yoğurt': 0.15, 'Salatalık': 0.5},
    'Peynirli tost': {'Ekmek': 2, 'Peynir': 0.05},
  };

  String _portionUnit(String name) {
    const kg = {'Peynir', 'Mercimek', 'Makarna', 'Yoğurt', 'Pirinç',
      'Tereyağı', 'Bulgur'};
    return kg.contains(name) ? 'kg' : name == 'Süt' ? 'L' : 'adet';
  }

  Map<String, double> _plannedIngredients(int days) {
    final today = DateTime.now();
    final start = DateTime(today.year, today.month, today.day);
    final end = start.add(Duration(days: days));
    final totals = <String, double>{};
    for (final meal in _kitchenMeals) {
      if (meal['done'] == true) continue;
      final date = DateTime.tryParse(meal['date']?.toString() ?? '');
      if (date == null || date.isBefore(start) || !date.isBefore(end)) continue;
      final guide = _allPortionGuides()[meal['recipe']?.toString() ?? ''];
      if (guide == null) continue;
      final portions = _planNum(meal['portions'] ?? 2).clamp(1, 30);
      for (final ingredient in guide.entries) {
        totals.update(ingredient.key, (v) => v + ingredient.value * portions,
          ifAbsent: () => ingredient.value * portions);
      }
    }
    return totals;
  }

  void _showKitchenPurchaseNeeds() {
    int days = 7;
    String search = '';
    bool onlyMissing = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final needs = _plannedIngredients(days);
        final stock = _kitchenStockRows();
        final rows = <Map<String, dynamic>>[];
        for (final entry in needs.entries) {
          final matching = stock.where((r) =>
            _normalizeName(r['name'].toString()) == _normalizeName(entry.key) &&
            (_kitchenDaysUntil(r['expiry']?.toString() ?? '') ?? 1) >= 0).toList();
          // Farklı birimlerde stok tutulabileceği için stok otomatik düşülmez.
          final available = matching.isNotEmpty;
          final unitPrice = matching.isEmpty ? 0.0 : _planNum(matching.first['price']);
          rows.add({'name': entry.key, 'qty': entry.value,
            'unit': _portionUnit(entry.key), 'available': available,
            'price': unitPrice, 'estimate': entry.value * unitPrice});
        }
        rows.sort((a, b) => (a['name'] as String).compareTo(b['name'] as String));
        final filtered = rows.where((r) =>
          (!onlyMissing || r['available'] == false) &&
          r['name'].toString().toLowerCase().contains(search.toLowerCase())).toList();
        final total = rows.fold<double>(0, (sum, r) => sum + (r['estimate'] as double));
        final unknown = rows.where((r) => (r['price'] as double) <= 0).length;
        return SafeArea(child: FractionallySizedBox(heightFactor: .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Porsiyon ve mutfak ihtiyaç planı', style: TextStyle(
              color: _purple, fontWeight: FontWeight.bold, fontSize: 20)),
            const SizedBox(height: 8),
            const Text('Miktarlar yaklaşık tarif katsayılarıdır. Stok birimleri eşitlenmediğinden stoktan otomatik düşüm yapılmaz. Bebek beslenmesinde yaş ve alerjen uygunluğunu ayrıca kontrol edin.',
              style: TextStyle(fontSize: 12)),
            Wrap(spacing: 8, children: [7, 14, 30].map((n) => ChoiceChip(
              label: Text('$n gün'), selected: days == n,
              onSelected: (_) => refresh(() => days = n))).toList()),
            TextField(decoration: const InputDecoration(
              labelText: 'Malzeme ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => search = v)),
            SwitchListTile(title: const Text('Stokta görünmeyenleri göster'),
              value: onlyMissing, onChanged: (v) => refresh(() => onlyMissing = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${needs.length} malzeme çeşidi • ${rows.where((r) => r['available'] == false).length} stokta görünmüyor'),
                Text('Bilinen fiyatlarla yaklaşık ihtiyaç maliyeti: ${_money(total)}'),
                if (unknown > 0) Text('$unknown malzemenin birim fiyatı bilinmiyor; toplam eksik olabilir.',
                  style: const TextStyle(color: Colors.deepOrange)),
              ]))),
            if (filtered.isEmpty) const Padding(padding: EdgeInsets.all(12),
              child: Text('Seçilen dönem ve filtre için malzeme bulunamadı.')),
            ...filtered.map((r) => ListTile(
              title: Text(r['name'].toString()),
              subtitle: Text('${(r['qty'] as double).toStringAsFixed(2)} ${r['unit']} • '
                '${r['available'] == true ? 'Stok kaydı var' : 'Stokta görünmüyor'}'),
              trailing: Text((r['price'] as double) > 0
                ? _money(r['estimate'] as double) : 'Fiyat yok'))),
            FilledButton.tonalIcon(onPressed: () async {
              await _kitchenAddMissing(rows.where((r) => r['available'] == false)
                .map((r) => r['name'].toString()).toList());
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.add_shopping_cart),
              label: const Text('Stokta görünmeyenleri listeye ekle')),
            OutlinedButton.icon(onPressed: () {
              final lines = <String>['Malzeme;Yaklaşık miktar;Birim;Stok kaydı;Tahmini tutar'];
              for (final r in rows) {
                lines.add('${r['name']};${r['qty']};${r['unit']};${r['available']};${r['estimate']}');
              }
              Clipboard.setData(ClipboardData(text: lines.join('\n')));
              _notice('İhtiyaç tablosu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('İhtiyaç raporunu kopyala')),
          ])));
      }));
  }


  // Aşama 1248–1347: Haftalık bütçe ve bilinen fiyatlarla karşılaştırma.
  DateTime _kitchenWeekStart(DateTime date) =>
      DateTime(date.year, date.month, date.day).subtract(Duration(days: date.weekday - 1));

  String _kitchenWeekKey(DateTime date) =>
      _kitchenWeekStart(date).toIso8601String().split('T').first;

  Map<String, dynamic> _kitchenWeekCost(DateTime monday) {
    final end = monday.add(const Duration(days: 7));
    double total = 0;
    var missing = 0;
    var meals = 0;
    for (final meal in _kitchenMeals) {
      final date = DateTime.tryParse(meal['date']?.toString() ?? '');
      if (date == null || date.isBefore(monday) || !date.isBefore(end)) continue;
      meals++;
      final recipeName = meal['recipe']?.toString() ?? '';
      Map<String, dynamic>? recipe;
      for (final item in _customRecipes) {
        if (item['name']?.toString() == recipeName) { recipe = item; break; }
      }
      if (recipe == null) { missing++; continue; }
      final portions = _planNum(meal['portions']).toInt().clamp(1, 100);
      final cost = _customRecipeCost(recipe, portions);
      total += _planNum(cost['known']);
      missing += (cost['missing'] as List).length;
    }
    return {'total': total, 'missing': missing, 'meals': meals};
  }

  Future<void> _setKitchenWeekBudget(DateTime monday) async {
    final key = _kitchenWeekKey(monday);
    final input = await _planText('Haftalık mutfak bütçesi (TL)',
        '${_kitchenWeeklyBudgets[key] ?? 0}', numeric: true);
    if (input == null || !mounted) return;
    final value = double.tryParse(input.replaceAll(',', '.'));
    if (value == null || !value.isFinite || value < 0) {
      _notice('Geçerli bir bütçe girin.'); return;
    }
    setState(() => _kitchenWeeklyBudgets[key] = value);
    await _save();
  }

  void _showKitchenBudgetComparison() {
    var offset = 0;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final current = _kitchenWeekStart(DateTime.now()).add(Duration(days: 7 * offset));
        final previous = current.subtract(const Duration(days: 7));
        final currentCost = _kitchenWeekCost(current);
        final previousCost = _kitchenWeekCost(previous);
        final budget = _kitchenWeeklyBudgets[_kitchenWeekKey(current)] ?? 0;
        final total = _planNum(currentCost['total']);
        final previousTotal = _planNum(previousCost['total']);
        final delta = total - previousTotal;
        final missing = _planNum(currentCost['missing']).toInt();
        return SafeArea(child: FractionallySizedBox(heightFactor: .83,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Haftalık mutfak bütçesi ve maliyet karşılaştırması',
              style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            Row(children: [
              IconButton(onPressed: () => refresh(() => offset--), icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('Hafta başlangıcı: ${_kitchenWeekKey(current)}', textAlign: TextAlign.center)),
              IconButton(onPressed: () => refresh(() => offset++), icon: const Icon(Icons.chevron_right)),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(14),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Bu hafta: ${_money(total)} (${currentCost['meals']} öğün)'),
                Text('Önceki hafta: ${_money(previousTotal)} (${previousCost['meals']} öğün)'),
                Text('Haftalık fark: ${_money(delta)}'),
                Text(budget > 0 ? 'Haftalık bütçe: ${_money(budget)}' : 'Haftalık bütçe tanımlanmadı.'),
                if (budget > 0) ...[
                  Text('Bütçeden kalan: ${_money(budget - total)}'),
                  LinearProgressIndicator(value: (total / budget).clamp(0.0, 1.0)),
                  if (total > budget) const Text('Bilinen maliyetler bütçeyi aşıyor.',
                    style: TextStyle(color: Colors.red)),
                ],
                if (missing > 0) Text('$missing öğün veya malzemede tarif/fiyat eksik. '
                    'Gösterilen maliyet kesin toplam değildir.',
                    style: const TextStyle(color: Colors.deepOrange)),
              ]))),
            FilledButton.tonalIcon(onPressed: () async {
              await _setKitchenWeekBudget(current);
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.edit), label: const Text('Haftalık bütçeyi düzenle')),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Hafta;Öğün;Bilinen maliyet TL;Eksik veri;Bütçe TL'];
              for (var i = -7; i <= 0; i++) {
                final week = current.add(Duration(days: i * 7));
                final cost = _kitchenWeekCost(week);
                lines.add('${_kitchenWeekKey(week)};${cost['meals']};${cost['total']};'
                  '${cost['missing']};${_kitchenWeeklyBudgets[_kitchenWeekKey(week)] ?? 0}');
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('8 haftalık maliyet raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('8 haftalık CSV raporunu kopyala')),
            const SizedBox(height: 10),
            const Text('Maliyetler yalnızca kişisel tariflerde tanımlanan malzemelerin '
              'kayıtlı kanonik birim fiyatlarından hesaplanır. Fiyatı bilinmeyen '
              'malzemeler veya tarif eşleşmeyen öğünler toplamı eksik gösterebilir.'),
          ])));
      }));
  }

  void _showKitchenDeficitCosts() {
    var days = 7;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final rows = _kitchenQuantityReconciliation(days).where((r) =>
          _planNum(r['deficit']) > 0).map((r) {
            final name = r['name'].toString();
            final unit = r['unit'].toString();
            final price = _ingredientUnitPrices[_ingredientPriceKey(name, unit)];
            return <String, dynamic>{...r, 'price': price,
              'cost': price == null ? null : _planNum(r['deficit']) * price};
          }).toList();
        final known = rows.fold<double>(0, (sum, r) => sum + _planNum(r['cost']));
        final unpriced = rows.where((r) => r['price'] == null).length;
        return SafeArea(child: FractionallySizedBox(heightFactor: .88,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Eksik malzemelerin satın alma maliyeti',
              style: TextStyle(fontSize: 19, color: _purple, fontWeight: FontWeight.bold)),
            Wrap(spacing: 8, children: [7,14,30].map((n) => ChoiceChip(
              label: Text('$n gün'), selected: days == n,
              onSelected: (_) => refresh(() => days = n))).toList()),
            Text('Bilinen maliyet: ${_money(known)} • ${rows.length} eksik ürün'),
            if (unpriced > 0) Text('$unpriced ürünün birim fiyatı eksik; toplam kısmi maliyettir.',
              style: const TextStyle(color: Colors.deepOrange)),
            if (rows.isEmpty) const Text('Bu dönemde eksik malzeme görünmüyor.'),
            ...rows.map((r) => Card(child: ListTile(
              title: Text(r['name'].toString()),
              subtitle: Text('Eksik: ${r['deficit']} ${r['unit']} • '
                '${r['price'] == null ? 'Birim fiyat yok' : '${_money(_planNum(r['price']))}/${r['unit']}'}'),
              trailing: Text(r['cost'] == null ? '—' : _money(_planNum(r['cost']))),
              onTap: () async {
                await _editIngredientUnitPrice(r['name'].toString(), r['unit'].toString());
                if (ctx.mounted) refresh(() {});
              },
            ))),
            FilledButton.tonalIcon(onPressed: rows.isEmpty ? null : () async {
              await _createKitchenDeficitPlan(days, rows);
              if (ctx.mounted) refresh(() {});
            }, icon: const Icon(Icons.add_shopping_cart),
              label: const Text('Eksik ürünlerden alışveriş planı oluştur')),
            FilledButton.tonalIcon(onPressed: rows.isEmpty ? null : () async {
              final lines = <String>['Malzeme;Eksik miktar;Birim;Birim fiyat TL;Bilinen maliyet TL'];
              for (final r in rows) {
                final name = r['name'].toString().replaceAll(';', ',').replaceAll('\n', ' ');
                lines.add('$name;${r['deficit']};${r['unit']};${r['price'] ?? ''};${r['cost'] ?? ''}');
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('Eksik ürün maliyet raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
          ])));
      }));
  }


  // Aşama 1348–1447: Salt-okunur ekonomik tarif ve SKT önerileri.
  void _showEconomicalKitchenRecipes() {
    var portions = 2;
    var onlyComplete = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final stocks = _kitchenStockRows();
        final expiring = stocks.where((row) {
          final days = _kitchenDaysUntil(row['expiry']?.toString() ?? '');
          return days != null && days >= 0 && days <= 5 && _planNum(row['stock']) > 0;
        }).toList();
        final rows = _customRecipes.map((recipe) {
          final cost = _customRecipeCost(recipe, portions);
          final ingredients = (recipe['ingredients'] as List? ?? []).whereType<Map>().toList();
          final matched = <String>[];
          for (final ingredient in ingredients) {
            final name = ingredient['name']?.toString() ?? '';
            if (expiring.any((stock) => _normalizeName(stock['name'].toString()) ==
                _normalizeName(name))) {
              matched.add(name);
            }
          }
          return {'recipe': recipe, 'cost': cost, 'expiring': matched};
        }).where((row) => !onlyComplete ||
          ((row['cost'] as Map)['missing'] as List).isEmpty).toList();
        rows.sort((a,b) {
          final aMissing = ((a['cost'] as Map)['missing'] as List).isNotEmpty;
          final bMissing = ((b['cost'] as Map)['missing'] as List).isNotEmpty;
          if (aMissing != bMissing) return aMissing ? 1 : -1;
          return _planNum((a['cost'] as Map)['known'])
              .compareTo(_planNum((b['cost'] as Map)['known']));
        });
        return SafeArea(child: FractionallySizedBox(heightFactor: .88,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Ekonomik tarifler ve SKT önceliği',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Yalnızca kayıtlı kişisel tarifler ve birim fiyatlar kullanılır. '
              'Eksik fiyatlı tariflerin maliyeti tam değildir.', style: TextStyle(fontSize: 12)),
            Wrap(spacing: 8, children: [1, 2, 4, 6].map((v) => ChoiceChip(
              label: Text('$v porsiyon'), selected: portions == v,
              onSelected: (_) => refresh(() => portions = v))).toList()),
            SwitchListTile(title: const Text('Yalnızca tüm fiyatları bilinen tarifler'),
              value: onlyComplete, onChanged: (v) => refresh(() => onlyComplete = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Text('5 gün içinde SKT yaklaşan stok çeşidi: ${expiring.length} • '
                'Değerlendirilen tarif: ${rows.length}'))),
            if (rows.isEmpty) const ListTile(title: Text('Uygun kişisel tarif bulunamadı.')),
            ...rows.map((row) {
              final recipe = row['recipe'] as Map<String, dynamic>;
              final cost = row['cost'] as Map<String, dynamic>;
              final expiringNames = row['expiring'] as List<String>;
              final missing = cost['missing'] as List;
              return Card(child: Padding(padding: const EdgeInsets.all(12),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(recipe['name']?.toString() ?? 'Tarif',
                    style: const TextStyle(fontWeight: FontWeight.bold)),
                  Text('$portions porsiyon bilinen maliyet: ${_money(_planNum(cost['known']))}'),
                  Text('Porsiyon başına: ${_money(_planNum(cost['known']) / portions)}'),
                  if (missing.isNotEmpty) Text('${missing.length} malzemenin fiyatı eksik',
                    style: const TextStyle(color: Colors.deepOrange)),
                  if (expiringNames.isNotEmpty) Text('Öncelikli tüketim: ${expiringNames.join(', ')}',
                    style: const TextStyle(color: Colors.green)),
                ])));
            }),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Tarif;Porsiyon;Bilinen maliyet TL;Eksik fiyat sayısı;SKT öncelikli malzemeler'];
              for (final row in rows) {
                final recipe = row['recipe'] as Map<String, dynamic>;
                final cost = row['cost'] as Map<String, dynamic>;
                lines.add('${_planCsvCell(recipe['name'])};$portions;${cost['known']};'
                  '${(cost['missing'] as List).length};${_planCsvCell((row['expiring'] as List).join(', '))}');
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('Ekonomik tarif raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Tarif karşılaştırmasını CSV kopyala')),
          ])));
      }));
  }

  // Aşama 1448–1547: Ekonomik haftalık menü taslağı.
  // Önizleme herhangi bir kayıt değiştirmez; yalnızca onay sonrası öğün eklenir.
  void _showEconomicalWeeklyMenu() {
    int portions = 2;
    int mealsPerDay = 1;
    bool preferExpiry = true;
    bool completePricesOnly = true;
    int weekShift = 0;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheetContext) => StatefulBuilder(builder: (ctx, refresh) {
        final today = DateTime.now();
        final monday = DateTime(today.year, today.month, today.day)
          .subtract(Duration(days: today.weekday - 1))
          .add(Duration(days: weekShift * 7));
        final weekKey = '${monday.year}-${monday.month.toString().padLeft(2, '0')}-${monday.day.toString().padLeft(2, '0')}';
        final budget = _kitchenWeeklyBudgets[weekKey] ?? 0.0;
        final expiring = _kitchenStockRows().where((stock) {
          final remaining = _kitchenDaysUntil(stock['expiry']?.toString() ?? '');
          return remaining != null && remaining >= 0 && remaining <= 5 &&
            _planNum(stock['stock']) > 0;
        }).map((e) => _normalizeName(e['name']?.toString() ?? '')).toSet();
        final options = <Map<String, dynamic>>[];
        for (final recipe in _customRecipes) {
          final name = recipe['name']?.toString().trim() ?? '';
          if (name.isEmpty) continue;
          final cost = _customRecipeCost(recipe, portions);
          final missing = (cost['missing'] as List).length;
          if (completePricesOnly && missing > 0) continue;
          final expiryHits = (recipe['ingredients'] as List? ?? []).whereType<Map>()
            .where((ingredient) => expiring.contains(_normalizeName(ingredient['name']?.toString() ?? ''))).length;
          options.add({'name': name, 'known': _planNum(cost['known']),
            'missing': missing, 'expiry': expiryHits});
        }
        options.sort((a, b) {
          if (preferExpiry) {
            final expiryOrder = (b['expiry'] as int).compareTo(a['expiry'] as int);
            if (expiryOrder != 0) return expiryOrder;
          }
          final missingOrder = (a['missing'] as int).compareTo(b['missing'] as int);
          if (missingOrder != 0) return missingOrder;
          return _planNum(a['known']).compareTo(_planNum(b['known']));
        });
        final proposed = <Map<String, dynamic>>[];
        if (options.isNotEmpty) {
          for (int day = 0; day < 7; day++) {
            for (int slot = 0; slot < mealsPerDay; slot++) {
              final recipe = options[(day * mealsPerDay + slot) % options.length];
              final date = monday.add(Duration(days: day)).toIso8601String().split('T').first;
              proposed.add({'date': date, 'recipe': recipe['name'],
                'mealType': mealsPerDay == 1 ? 'Akşam' : (slot == 0 ? 'Öğle' : 'Akşam'),
                'family': 'Aile', 'portions': portions, 'done': false,
                'cost': recipe['known'], 'missing': recipe['missing'],
                'expiry': recipe['expiry']});
            }
          }
        }
        final total = proposed.fold<double>(0, (sum, row) => sum + _planNum(row['cost']));
        final missingCount = proposed.fold<int>(0, (sum, row) => sum + (row['missing'] as int));
        final overBudget = budget > 0 && total > budget;
        return SafeArea(child: FractionallySizedBox(heightFactor: .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Ekonomik haftalık menü taslağı', style: TextStyle(
              fontSize: 20, color: _purple, fontWeight: FontWeight.bold)),
            const SizedBox(height: 6),
            const Text('Kişisel tariflerin kayıtlı birim fiyatlarından yaklaşık menü önerisi. '
              'Önizleme stokları ve mevcut öğünleri değiştirmez.',
              style: TextStyle(fontSize: 12)),
            Row(children: [
              IconButton(onPressed: () => refresh(() => weekShift--), icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('Hafta başlangıcı: $weekKey', textAlign: TextAlign.center)),
              IconButton(onPressed: () => refresh(() => weekShift++), icon: const Icon(Icons.chevron_right)),
            ]),
            Wrap(spacing: 8, children: [1, 2, 4, 6].map((v) => ChoiceChip(
              label: Text('$v porsiyon'), selected: portions == v,
              onSelected: (_) => refresh(() => portions = v))).toList()),
            Wrap(spacing: 8, children: [1, 2].map((v) => ChoiceChip(
              label: Text('Günde $v öğün'), selected: mealsPerDay == v,
              onSelected: (_) => refresh(() => mealsPerDay = v))).toList()),
            SwitchListTile(contentPadding: EdgeInsets.zero,
              title: const Text('SKT yaklaşan malzemeleri öncele'), value: preferExpiry,
              onChanged: (v) => refresh(() => preferExpiry = v)),
            SwitchListTile(contentPadding: EdgeInsets.zero,
              title: const Text('Yalnızca tüm fiyatları bilinen tarifler'),
              value: completePricesOnly,
              onChanged: (v) => refresh(() => completePricesOnly = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Önerilen öğün: ${proposed.length} • Kullanılabilir tarif: ${options.length}'),
                Text('Bilinen toplam maliyet: ${_money(total)}'),
                Text('Haftalık bütçe: ${budget > 0 ? _money(budget) : 'Tanımlanmadı'}'),
                if (budget > 0) Text('Bütçe farkı: ${_money(budget - total)}',
                  style: TextStyle(color: overBudget ? Colors.red : Colors.green.shade800)),
                if (overBudget) const Text('Taslak bilinen maliyetleri bütçeyi aşıyor.',
                  style: TextStyle(color: Colors.red)),
                if (missingCount > 0) Text('$missingCount öğün-malzeme fiyatı eksik; '
                  'gerçek maliyet daha yüksek olabilir.', style: const TextStyle(color: Colors.deepOrange)),
                if (options.length < mealsPerDay * 7 && options.isNotEmpty)
                  const Text('Tarif sayısı az olduğundan bazı yemekler tekrar ediyor.'),
              ]))),
            if (options.isEmpty) const ListTile(title: Text('Uygun tarif bulunamadı.'),
              subtitle: Text('Kişisel tarif ekleyin veya eksik fiyat filtresini kapatın.')),
            ...proposed.map((meal) => Card(child: ListTile(
              title: Text('${meal['date']} • ${meal['mealType']}'),
              subtitle: Text('${meal['recipe']} • $portions porsiyon'
                '${(meal['expiry'] as int) > 0 ? ' • SKT öncelikli' : ''}'),
              trailing: Text(_money(_planNum(meal['cost']))),
            ))),
            if (proposed.isNotEmpty) ...[
              FilledButton.tonalIcon(onPressed: () async {
                final csv = <String>['Tarih;Öğün;Tarif;Porsiyon;Bilinen maliyet TL;Eksik fiyat sayısı'];
                for (final meal in proposed) {
                  csv.add('${meal['date']};${_planCsvCell(meal['mealType'])};'
                    '${_planCsvCell(meal['recipe'])};$portions;${meal['cost']};${meal['missing']}');
                }
                await Clipboard.setData(ClipboardData(text: csv.join('\n')));
                if (mounted) _notice('Ekonomik menü taslağı CSV olarak panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('Menü taslağını CSV kopyala')),
              FilledButton.icon(onPressed: () async {
                final confirmed = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                  title: const Text('Ekonomik menüyü kaydet'),
                  content: Text('${proposed.length} öğün eklensin mi? Mevcut öğünler silinmez; '
                    'aynı tarih/tarif/öğün/aile kayıtları atlanır.'),
                  actions: [TextButton(onPressed: () => Navigator.pop(dialog, false),
                    child: const Text('Vazgeç')),
                    FilledButton(onPressed: () => Navigator.pop(dialog, true),
                      child: const Text('Kaydet'))]));
                if (confirmed != true || !mounted) return;
                int added = 0;
                setState(() {
                  for (final meal in proposed) {
                    final duplicate = _kitchenMeals.any((existing) =>
                      existing['date'] == meal['date'] && existing['recipe'] == meal['recipe'] &&
                      existing['mealType'] == meal['mealType'] && existing['family'] == meal['family']);
                    if (duplicate) continue;
                    _kitchenMeals.add({'date': meal['date'], 'recipe': meal['recipe'],
                      'mealType': meal['mealType'], 'family': meal['family'],
                      'portions': portions, 'done': false});
                    added++;
                  }
                });
                if (added > 0) await _save();
                if (sheetContext.mounted) Navigator.pop(sheetContext);
                if (mounted) _notice('$added öğün kaydedildi; mevcut öğünler korundu.');
              }, icon: const Icon(Icons.calendar_month), label: const Text('Öğünleri onayla ve kaydet')),
            ],
          ])));
      }));
  }

  // Aşama 1548–1647: maliyet, çeşitlilik ve SKT arasında şeffaf taslak seçimi.
  void _showOptimizedWeeklyMenu() {
    int portions = 2;
    int mealsPerDay = 1;
    int weekShift = 0;
    bool expiryFirst = true;
    bool excludeUnknownPrices = true;
    bool preferVariety = true;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheetContext) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final monday = DateTime(now.year, now.month, now.day)
          .subtract(Duration(days: now.weekday - 1))
          .add(Duration(days: weekShift * 7));
        final key = monday.toIso8601String().split('T').first;
        final budget = _kitchenWeeklyBudgets[key] ?? 0.0;
        final expiring = _kitchenStockRows().where((stock) {
          final d = _kitchenDaysUntil(stock['expiry']?.toString() ?? '');
          return d != null && d >= 0 && d <= 5 && _planNum(stock['stock']) > 0;
        }).map((stock) => _normalizeName(stock['name']?.toString() ?? '')).toSet();
        final options = <Map<String, dynamic>>[];
        for (final recipe in _customRecipes) {
          final name = recipe['name']?.toString().trim() ?? '';
          if (name.isEmpty) continue;
          final result = _customRecipeCost(recipe, portions);
          final missing = (result['missing'] as List).length;
          if (excludeUnknownPrices && missing > 0) continue;
          final hits = (recipe['ingredients'] as List? ?? []).whereType<Map>()
            .where((item) => expiring.contains(_normalizeName(item['name']?.toString() ?? ''))).length;
          options.add({'name': name, 'cost': _planNum(result['known']),
            'missing': missing, 'expiry': hits});
        }
        final totalSlots = 7 * mealsPerDay;
        List<Map<String, dynamic>> generate({required bool cheapest}) {
          final usage = <String, int>{};
          final selected = <Map<String, dynamic>>[];
          double running = 0;
          for (int slot = 0; slot < totalSlots && options.isNotEmpty; slot++) {
            final ranked = options.toList()..sort((a, b) {
              double score(Map<String, dynamic> row) {
                final cost = _planNum(row['cost']);
                final repeat = usage[row['name']] ?? 0;
                final expiryBonus = (!cheapest && expiryFirst) ? (row['expiry'] as int) * 12.0 : 0.0;
                final repeatPenalty = (!cheapest && preferVariety) ? repeat * 25.0 : 0.0;
                final unknownPenalty = (row['missing'] as int) * 100000.0;
                final over = budget > 0 && running + cost > budget ? 1000000.0 : 0.0;
                return cost + repeatPenalty + unknownPenalty + over - expiryBonus;
              }
              return score(a).compareTo(score(b));
            });
            final chosen = ranked.first;
            running += _planNum(chosen['cost']);
            usage[chosen['name'].toString()] = (usage[chosen['name'].toString()] ?? 0) + 1;
            final date = monday.add(Duration(days: slot ~/ mealsPerDay)).toIso8601String().split('T').first;
            selected.add({...chosen, 'date': date,
              'mealType': mealsPerDay == 1 ? 'Akşam' : (slot % mealsPerDay == 0 ? 'Öğle' : 'Akşam'),
              'family': 'Aile', 'portions': portions, 'done': false});
          }
          return selected;
        }
        final balanced = generate(cheapest: false);
        final cheapest = generate(cheapest: true);
        double total(List<Map<String, dynamic>> rows) => rows.fold<double>(0,
          (sum, row) => sum + _planNum(row['cost']));
        int distinct(List<Map<String, dynamic>> rows) => rows.map((row) => row['name']).toSet().length;
        int hits(List<Map<String, dynamic>> rows) => rows.fold<int>(0,
          (sum, row) => sum + (row['expiry'] as int));
        int missing(List<Map<String, dynamic>> rows) => rows.fold<int>(0,
          (sum, row) => sum + (row['missing'] as int));
        Future<void> saveMenu(List<Map<String, dynamic>> rows) async {
          if (rows.isEmpty) return;
          final yes = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
            title: const Text('Menüyü kaydet'),
            content: Text('${rows.length} öğün eklensin mi? Mevcut yemek planı ve stoklar korunur.'),
            actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Kaydet'))]));
          if (yes != true || !mounted) return;
          int count = 0;
          setState(() {
            for (final meal in rows) {
              final duplicate = _kitchenMeals.any((old) => old['date'] == meal['date'] &&
                old['recipe'] == meal['name'] && old['mealType'] == meal['mealType'] &&
                old['family'] == meal['family']);
              if (duplicate) continue;
              _kitchenMeals.add({'date': meal['date'], 'recipe': meal['name'],
                'mealType': meal['mealType'], 'family': meal['family'],
                'portions': portions, 'done': false});
              count++;
            }
          });
          if (count > 0) await _save();
          if (sheetContext.mounted) Navigator.pop(sheetContext);
          if (mounted) _notice('$count yeni öğün eklendi; mevcut kayıtlar korunuyor.');
        }
        Widget section(String title, List<Map<String, dynamic>> rows) => Card(
          color: _pink, child: Padding(padding: const EdgeInsets.all(12),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(title, style: const TextStyle(fontSize: 17, fontWeight: FontWeight.bold, color: _purple)),
              Text('Bilinen maliyet: ${_money(total(rows))} • Farklı tarif: ${distinct(rows)} • SKT eşleşmesi: ${hits(rows)}'),
              if (budget > 0) Text('Bütçe farkı: ${_money(budget - total(rows))}',
                style: TextStyle(color: total(rows) > budget ? Colors.red : Colors.green.shade800)),
              if (missing(rows) > 0) Text('${missing(rows)} eksik malzeme fiyatı: toplam eksik olabilir.',
                style: const TextStyle(color: Colors.deepOrange)),
              ...rows.map((row) => ListTile(dense: true,
                title: Text('${row['date']} • ${row['mealType']} • ${row['name']}'),
                subtitle: Text('${row['portions']} porsiyon${(row['expiry'] as int) > 0 ? ' • SKT öncelikli' : ''}'),
                trailing: Text(_money(_planNum(row['cost']))))),
              if (rows.isNotEmpty) Wrap(spacing: 8, children: [
                OutlinedButton.icon(onPressed: () async {
                  final csv = <String>['Tarih;Öğün;Tarif;Porsiyon;Bilinen maliyet TL;Eksik fiyat'];
                  for (final row in rows) {
                    csv.add('${row['date']};${_planCsvCell(row['mealType'])};${_planCsvCell(row['name'])};'
                      '${row['portions']};${row['cost']};${row['missing']}');
                  }
                  await Clipboard.setData(ClipboardData(text: csv.join('\n')));
                  if (mounted) _notice('Menü karşılaştırması panoya kopyalandı.');
                }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
                OutlinedButton.icon(onPressed: () => _saveMenuDraftSnapshot(rows, title),
                  icon: const Icon(Icons.bookmark_add_outlined), label: const Text('Taslak kaydet')),
                OutlinedButton.icon(onPressed: _showSavedMenuDrafts,
                  icon: const Icon(Icons.folder_open), label: const Text('Kayıtlı taslaklar')),
                OutlinedButton.icon(onPressed: () => _showEditableMenuDraft(rows, title),
                  icon: const Icon(Icons.edit_calendar), label: const Text('Menüyü düzenle / alternatif tarif')),
                OutlinedButton.icon(onPressed: () => _showMenuPurchasePreview(rows, title),
                  icon: const Icon(Icons.shopping_cart_checkout), label: const Text('Eksik malzeme / satın alma')),
                FilledButton.icon(onPressed: () => saveMenu(rows),
                  icon: const Icon(Icons.save), label: const Text('Bu menüyü kaydet')),
              ]),
            ])));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            OutlinedButton.icon(onPressed: _showSavedMenuDrafts,
              icon: const Icon(Icons.folder_open), label: const Text('Kaydedilen menü taslakları')),
            const Text('Bütçeye göre haftalık menü karşılaştırması',
              style: TextStyle(fontSize: 20, color: _purple, fontWeight: FontWeight.bold)),
            const Text('İki taslak karşılaştırılır. Maliyetler kayıtlı birim fiyatlara dayanır; '
              'beslenme dengesi veya sağlık uygunluğu değerlendirilmez.', style: TextStyle(fontSize: 12)),
            Row(children: [
              IconButton(onPressed: () => refresh(() => weekShift--), icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('Hafta: $key', textAlign: TextAlign.center)),
              IconButton(onPressed: () => refresh(() => weekShift++), icon: const Icon(Icons.chevron_right)),
            ]),
            Text('Haftalık bütçe: ${budget > 0 ? _money(budget) : 'Tanımlanmadı'}'),
            Wrap(spacing: 8, children: [1, 2, 4, 6].map((n) => ChoiceChip(
              label: Text('$n porsiyon'), selected: portions == n,
              onSelected: (_) => refresh(() => portions = n))).toList()),
            Wrap(spacing: 8, children: [1, 2].map((n) => ChoiceChip(
              label: Text('Günde $n öğün'), selected: mealsPerDay == n,
              onSelected: (_) => refresh(() => mealsPerDay = n))).toList()),
            SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('SKT yaklaşan ürünleri öne çıkar'),
              value: expiryFirst, onChanged: (v) => refresh(() => expiryFirst = v)),
            SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('Tarif çeşitliliğine öncelik ver'),
              value: preferVariety, onChanged: (v) => refresh(() => preferVariety = v)),
            SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('Eksik fiyatlı tarifleri hariç tut'),
              value: excludeUnknownPrices, onChanged: (v) => refresh(() => excludeUnknownPrices = v)),
            if (options.isEmpty) const ListTile(title: Text('Uygun kişisel tarif bulunamadı.'),
              subtitle: Text('Tarif ve birim fiyat ekleyin veya fiyat filtresini kapatın.')),
            if (budget <= 0) const Text('Bütçe tanımlı değil; maliyetler karşılaştırılır ancak bütçe garantisi verilmez.'),
            if (options.isNotEmpty) ...[
              section('Ekonomik seçenek', cheapest),
              section('Çeşitlilik / SKT odaklı seçenek', balanced),
              if (budget > 0 && total(cheapest) > budget)
                const Text('En düşük bilinen maliyetli seçenek bile bütçeyi aşıyor. '
                  'Porsiyon veya öğün sayısını azaltmayı değerlendirin.',
                  style: TextStyle(color: Colors.deepOrange)),
              const Text('Stok varlığı satın alma maliyetinden otomatik düşülmez. '
                'Tarif önerileri tahminidir; mevcut yemek planı yalnızca onayla değişir.',
                style: TextStyle(fontSize: 12)),
            ],
          ])));
      }));
  }

  // Aşama 2048–2147: Kayıtlı menü taslaklarını stok ve maliyet açısından karşılaştır.
  List<Map<String, dynamic>> _savedDraftMeals(Map<String, dynamic> record) =>
      (record['meals'] as List? ?? []).whereType<Map>()
          .map((row) => Map<String, dynamic>.from(row)).toList();

  Map<String, dynamic> _draftMetrics(Map<String, dynamic> record) {
    final meals = _savedDraftMeals(record);
    final purchases = _menuPurchaseRows(meals);
    final mealCost = meals.fold<double>(0, (sum, r) => sum + _planNum(r['cost']));
    final purchaseCost = purchases.fold<double>(0, (sum, r) =>
        sum + _planNum(r['cost']));
    final missing = purchases.where((r) => _planNum(r['missing']) > 0).length;
    final unknown = purchases.where((r) =>
        _planNum(r['missing']) > 0 && _planNum(r['unitPrice']) <= 0).length;
    return <String, dynamic>{
      'meals': meals.length,
      'distinct': meals.map((r) => r['name']?.toString() ?? '').toSet().length,
      'mealCost': mealCost,
      'purchaseCost': purchaseCost,
      'missing': missing,
      'unknown': unknown,
      'ingredients': purchases.length,
    };
  }

  void _showSavedDraftComparison() {
    if (_savedMenuDrafts.length < 2) {
      _notice('Karşılaştırma için en az iki kayıtlı menü taslağı gerekli.');
      return;
    }
    var left = 0;
    var right = 1;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final a = _savedMenuDrafts[left];
        final b = _savedMenuDrafts[right];
        final ma = _draftMetrics(a);
        final mb = _draftMetrics(b);
        Widget selector(String title, int value, ValueChanged<int> changed) =>
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(title, style: const TextStyle(fontWeight: FontWeight.bold)),
              DropdownButton<int>(isExpanded: true, value: value,
                items: List.generate(_savedMenuDrafts.length, (i) => DropdownMenuItem(
                  value: i, child: Text(_savedMenuDrafts[i]['title']?.toString() ?? 'Taslak ${i + 1}',
                    overflow: TextOverflow.ellipsis))),
                onChanged: (v) { if (v != null) refresh(() => changed(v)); }),
            ]);
        Widget metric(String label, String key, {bool money = false}) =>
            Padding(padding: const EdgeInsets.symmetric(vertical: 5), child: Row(children: [
              Expanded(flex: 3, child: Text(label)),
              Expanded(flex: 2, child: Text(money ? _money(_planNum(ma[key])) : '${ma[key]}',
                textAlign: TextAlign.right)),
              Expanded(flex: 2, child: Text(money ? _money(_planNum(mb[key])) : '${mb[key]}',
                textAlign: TextAlign.right)),
            ]));
        return SafeArea(child: FractionallySizedBox(heightFactor: .85,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Menü taslakları karşılaştırması', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 10),
            selector('Birinci taslak', left, (v) => left = v),
            selector('İkinci taslak', right, (v) => right = v),
            if (left == right) const Text('Farkları görmek için iki ayrı taslak seç.',
              style: TextStyle(color: Colors.deepOrange)),
            const Divider(),
            metric('Öğün sayısı', 'meals'),
            metric('Farklı tarif', 'distinct'),
            metric('Bilinen yemek maliyeti', 'mealCost', money: true),
            metric('Tahmini satın alma', 'purchaseCost', money: true),
            metric('Eksik malzeme çeşidi', 'missing'),
            metric('Fiyatı belirsiz eksik', 'unknown'),
            metric('Toplam malzeme çeşidi', 'ingredients'),
            const Divider(),
            Text('Satın alma maliyeti farkı: ${_money(_planNum(ma['purchaseCost']) - _planNum(mb['purchaseCost']))}',
              style: const TextStyle(fontWeight: FontWeight.bold, color: _purple)),
            const Text('Maliyetler kayıtlı fiyatlara dayanır. Fiyatı eksik ürünler nedeniyle toplamlar eksik olabilir.',
              style: TextStyle(fontSize: 12)),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 6, children: [
              OutlinedButton.icon(onPressed: () => _showMenuPurchasePreview(
                  _savedDraftMeals(a), a['title']?.toString() ?? 'Birinci taslak'),
                icon: const Icon(Icons.shopping_basket_outlined), label: const Text('1. taslak alışverişi')),
              OutlinedButton.icon(onPressed: () => _showMenuPurchasePreview(
                  _savedDraftMeals(b), b['title']?.toString() ?? 'İkinci taslak'),
                icon: const Icon(Icons.shopping_basket_outlined), label: const Text('2. taslak alışverişi')),
              OutlinedButton.icon(onPressed: () async {
                final lines = <String>[
                  'Gösterge;${a['title']};${b['title']}',
                  for (final key in ['meals', 'distinct', 'mealCost', 'purchaseCost',
                      'missing', 'unknown', 'ingredients'])
                    '$key;${ma[key]};${mb[key]}',
                ];
                await Clipboard.setData(ClipboardData(text: lines.join('\n')));
                if (mounted) _notice('Karşılaştırma raporu panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
            ]),
          ])));
      }));
  }

  // Aşama 1948–2047: Taslaklar bağımsız saklanır; yemek planına otomatik yazılmaz.
  Future<void> _saveMenuDraftSnapshot(List<Map<String, dynamic>> menu, String fallback) async {
    if (menu.isEmpty) { _notice('Boş menü taslağı kaydedilemez.'); return; }
    final name = await _planText('Menü taslağının adı', fallback);
    if (name == null || name.trim().isEmpty || !mounted) return;
    final record = <String, dynamic>{
      'id': DateTime.now().microsecondsSinceEpoch.toString(),
      'title': name.trim(),
      'created': DateTime.now().toIso8601String(),
      'meals': menu.map((e) => Map<String, dynamic>.from(e)).toList(),
    };
    setState(() => _savedMenuDrafts.insert(0, record));
    await _save();
    if (mounted) _notice('Menü taslağı kaydedildi. Aktif yemek planı değişmedi.');
  }

  // Büyük arşivlerde yalnızca seçili sayfanın kartlarını oluştur.
  Widget _kitchenPageControls(int total, int page, int size,
      ValueChanged<int> change) {
    final pages = total == 0 ? 1 : (total + size - 1) ~/ size;
    final safe = page.clamp(0, pages - 1).toInt();
    final first = total == 0 ? 0 : safe * size + 1;
    final last = (safe * size + size).clamp(0, total).toInt();
    return Padding(padding: const EdgeInsets.symmetric(vertical: 6),
      child: Wrap(alignment: WrapAlignment.center, crossAxisAlignment: WrapCrossAlignment.center,
        spacing: 8, children: [
          Text('$first–$last / $total • Sayfa ${safe + 1}/$pages',
            style: const TextStyle(fontSize: 12, color: _purple)),
          TextButton.icon(onPressed: safe > 0 ? () => change(safe - 1) : null,
            icon: const Icon(Icons.chevron_left), label: const Text('Önceki')),
          TextButton.icon(onPressed: safe + 1 < pages ? () => change(safe + 1) : null,
            icon: const Icon(Icons.chevron_right), label: const Text('Sonraki')),
        ]));
  }

  void _showSavedMenuDrafts() {
    int page = 0;
    String query = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) => SafeArea(
        child: FractionallySizedBox(heightFactor: .85, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Kaydedilen menü taslakları', style: TextStyle(
            fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
          const Text('Taslaklar aktif yemek planından bağımsızdır. Düzenleme yeni bir taslak olarak kaydedilebilir.'),
          OutlinedButton.icon(onPressed: _showSavedDraftComparison,
            icon: const Icon(Icons.compare_arrows), label: const Text('Taslakları karşılaştır')),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Menü taslağı ara'),
            onChanged: (v) => refresh(() { query = v.trim().toLowerCase(); page = 0; })),
          if (_savedMenuDrafts.isEmpty) const ListTile(title: Text('Henüz taslak kaydedilmedi.')),
          Builder(builder: (_) {
            final matches = _savedMenuDrafts.where((r) =>
              (r['title']?.toString().toLowerCase() ?? '').contains(query)).toList();
            final count = matches.isEmpty ? 1 : (matches.length + 19) ~/ 20;
            final safe = page.clamp(0, count - 1).toInt();
            return Column(children: [
              _kitchenPageControls(matches.length, safe, 20,
                (p) => refresh(() => page = p)),
              if (matches.isEmpty && _savedMenuDrafts.isNotEmpty)
                const ListTile(title: Text('Aramayla eşleşen taslak yok.')),
              ...matches.skip(safe * 20).take(20).map((record) {
            final meals = (record['meals'] as List? ?? []).whereType<Map>()
                .map((r) => Map<String, dynamic>.from(r)).toList();
            final cost = meals.fold<double>(0, (sum, row) => sum + _planNum(row['cost']));
            return Card(color: _pink, child: Padding(padding: const EdgeInsets.all(8),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(record['title']?.toString() ?? 'Menü', style: const TextStyle(
                  fontWeight: FontWeight.bold, color: _purple)),
                Text('${meals.length} öğün • Bilinen yemek maliyeti: ${_money(cost)}'),
                Wrap(spacing: 6, children: [
                  TextButton.icon(onPressed: meals.isEmpty ? null : () => _showEditableMenuDraft(
                    meals, record['title']?.toString() ?? 'Taslak'),
                    icon: const Icon(Icons.edit), label: const Text('Düzenle')),
                  TextButton.icon(onPressed: meals.isEmpty ? null : () => _showMenuPurchasePreview(
                    meals, record['title']?.toString() ?? 'Taslak'),
                    icon: const Icon(Icons.shopping_cart), label: const Text('Alışveriş')),
                  TextButton.icon(onPressed: () async {
                    final ok = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
                      title: const Text('Taslağı sil'),
                      content: const Text('Yalnızca bu taslak silinir; yemek planı etkilenmez.'),
                      actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Sil'))]));
                    if (ok != true || !mounted) return;
                    await _removeKitchenRecordWithUndo(_savedMenuDrafts, record, 'Menü taslağı', refresh: refresh);
                  }, icon: const Icon(Icons.delete_outline), label: const Text('Sil')),
                ]),
              ])));
              }),
            ]);
          }),
        ])))));
  }

  // Aşama 1848–1947: tek öğün için alternatifleri toplam satın alma
  // ihtiyacı üzerinden karşılaştır; seçim sadece geçici menü taslağını değiştirir.
  void _showMenuAlternatives(
    List<Map<String, dynamic>> draft,
    Map<String, dynamic> selected,
    VoidCallback onApply,
  ) {
    if (_customRecipes.isEmpty) {
      _notice('Önce kişisel tarif ekleyin.');
      return;
    }
    final beforeRows = _menuPurchaseRows(draft);
    double buyCost(List<Map<String, dynamic>> rows) => rows.fold<double>(
      0, (sum, row) => sum + _planNum(row['deficit']) *
          (row['price'] == null ? 0 : _planNum(row['price'])));
    int unknownPrices(List<Map<String, dynamic>> rows) => rows.where(
      (r) => _planNum(r['deficit']) > 0 && r['price'] == null).length;
    final beforeBuy = buyCost(beforeRows);
    final beforeUnknown = unknownPrices(beforeRows);
    final beforeMeal = draft.fold<double>(0, (sum, row) => sum + _planNum(row['cost']));
    final expiryNames = _kitchenStockRows().where((r) {
      final days = _kitchenDaysUntil(r['expiry']?.toString() ?? '');
      return days != null && days >= 0 && days <= 5 && _planNum(r['stock']) > 0;
    }).map((r) => _normalizeName(r['name']?.toString() ?? '')).toSet();
    final options = <Map<String, dynamic>>[];
    final portion = _planNum(selected['portions']).clamp(1, 30).toInt();
    for (final recipe in _customRecipes) {
      final name = recipe['name']?.toString().trim() ?? '';
      if (name.isEmpty) continue;
      final cost = _customRecipeCost(recipe, portion);
      final next = draft.map((row) => Map<String, dynamic>.from(row)).toList();
      final idx = draft.indexOf(selected);
      if (idx < 0) return;
      next[idx]['name'] = name;
      next[idx]['cost'] = _planNum(cost['known']);
      next[idx]['missing'] = (cost['missing'] as List).length;
      final rows = _menuPurchaseRows(next);
      final totalBuy = buyCost(rows);
      final totalMeal = next.fold<double>(0, (sum, row) => sum + _planNum(row['cost']));
      final parts = (recipe['ingredients'] as List? ?? []).whereType<Map>().toList();
      final expiring = parts.where((r) => expiryNames.contains(
        _normalizeName(r['name']?.toString() ?? ''))).length;
      final stocked = rows.where((r) => _planNum(r['available']) > 0).length;
      options.add({
        'expiryHits': expiring, 'stocked': stocked,
        'name': name, 'buy': totalBuy, 'meal': totalMeal,
        'unknown': unknownPrices(rows),
        'missingRecipe': (cost['missing'] as List).length,
        'saving': beforeBuy - totalBuy,
        'mealSaving': beforeMeal - totalMeal,
      });
    }
    options.sort((a, b) {
      final uncertain = (a['unknown'] as int).compareTo(b['unknown'] as int);
      if (uncertain != 0) return uncertain;
      return _planNum(a['buy']).compareTo(_planNum(b['buy']));
    });
    bool onlyCheaper = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) => SafeArea(
        child: FractionallySizedBox(heightFactor: .87, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Alternatif tarif / satın alma karşılaştırması',
            style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
          Text('Seçili: ${selected['name']} • $portion porsiyon'),
          Text('Mevcut menü satın alma tahmini: ${_money(beforeBuy)}'),
          Text('Mevcut menü yemek maliyeti: ${_money(beforeMeal)}'),
          if (beforeUnknown > 0) Text('$beforeUnknown satın alma fiyatı bilinmiyor.',
            style: const TextStyle(color: Colors.deepOrange)),
          const Text('Satın alma tahmini yalnızca eksik miktarları ve kayıtlı birim fiyatları kullanır. '
            'Eksik fiyatlar toplamı düşük gösterebilir.', style: TextStyle(fontSize: 12)),
          SwitchListTile(title: const Text('Yalnızca daha düşük satın alma tahmini'),
            value: onlyCheaper, onChanged: (v) => refresh(() => onlyCheaper = v)),
          ...options.where((o) => !onlyCheaper || _planNum(o['saving']) > 0).map((o) =>
            Card(color: _pink, child: ListTile(
              title: Text(o['name'].toString()),
              subtitle: Text('Menü satın alma: ${_money(_planNum(o['buy']))} '
                '• Fark: ${_money(_planNum(o['saving']))}\n'
                'Menü yemek maliyeti: ${_money(_planNum(o['meal']))} '
                '• Fark: ${_money(_planNum(o['mealSaving']))}\n'
                'Stok bulunan malzeme: ${o['stocked']} • SKT yakın eşleşme: ${o['expiryHits']}\n'
                'Eksik fiyat: ${o['unknown']} satın alma / ${o['missingRecipe']} tarif'),
              isThreeLine: true,
              trailing: FilledButton(onPressed: () {
                final name = o['name'].toString();
                final recipe = _customRecipes.firstWhere((r) => r['name'] == name);
                final cost = _customRecipeCost(recipe, portion);
                selected['name'] = name;
                selected['cost'] = _planNum(cost['known']);
                selected['missing'] = (cost['missing'] as List).length;
                onApply();
                Navigator.pop(sheet);
              }, child: const Text('Seç')),
            ))),
        ])))));
  }

  // Aşama 1748–1847: Menü taslağını kaydetmeden önce öğün bazında düzenleme.
  // Mevcut yemek planı ve stoklar yalnızca açık kullanıcı onayıyla değişir.
  void _showEditableMenuDraft(List<Map<String, dynamic>> original, String label) {
    final draft = original.map((r) => Map<String, dynamic>.from(r)).toList();
    final names = _customRecipes.map((r) => r['name']?.toString() ?? '')
        .where((n) => n.isNotEmpty).toSet().toList()..sort();
    bool onlyNeeds = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheetContext) => StatefulBuilder(builder: (ctx, refresh) {
        void recalculate(Map<String, dynamic> row) {
          final matching = _customRecipes.where((r) => r['name'] == row['name']);
          if (matching.isEmpty) { row['cost'] = 0.0; row['missing'] = 1; row['expiry'] = 0; return; }
          final result = _customRecipeCost(matching.first, _planNum(row['portions']).toInt());
          row['cost'] = _planNum(result['known']);
          row['missing'] = (result['missing'] as List).length;
          final expiring = _kitchenStockRows().where((stock) {
            final days = _kitchenDaysUntil(stock['expiry']?.toString() ?? '');
            return days != null && days >= 0 && days <= 5 && _planNum(stock['stock']) > 0;
          }).map((stock) => _normalizeName(stock['name']?.toString() ?? '')).toSet();
          row['expiry'] = (matching.first['ingredients'] as List? ?? []).whereType<Map>()
              .where((ingredient) => expiring.contains(_normalizeName(ingredient['name']?.toString() ?? ''))).length;
        }
        final total = draft.fold<double>(0, (sum, r) => sum + _planNum(r['cost']));
        final purchase = _menuPurchaseRows(draft);
        final needed = purchase.where((r) => _planNum(r['deficit']) > 0).toList();
        final purchaseCost = needed.fold<double>(0, (sum, r) => sum + _planNum(r['cost']));
        final unknown = draft.fold<int>(0, (sum, r) => sum + (_planNum(r['missing']).toInt()));
        final unknownPurchase = needed.where((r) => r['price'] == null).length;
        Future<void> save() async {
          if (draft.isEmpty) { _notice('Kaydedilecek öğün bulunamadı.'); return; }
          final ok = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
            title: const Text('Düzenlenmiş menüyü kaydet'),
            content: Text('${draft.length} öğün kontrol edilecek. Mevcut öğünler silinmeyecek, '
              'aynı tarih/tarif/öğün/aile kayıtları atlanacak.'),
            actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Kaydet'))]));
          if (ok != true || !mounted) return;
          int added = 0;
          setState(() {
            for (final row in draft) {
              final exists = _kitchenMeals.any((old) => old['date'] == row['date'] &&
                old['recipe'] == row['name'] && old['mealType'] == row['mealType'] &&
                old['family'] == row['family']);
              if (exists) continue;
              _kitchenMeals.add({'date': row['date'], 'recipe': row['name'],
                'mealType': row['mealType'], 'family': row['family'],
                'portions': row['portions'], 'done': false});
              added++;
            }
          });
          if (added > 0) await _save();
          if (sheetContext.mounted) Navigator.pop(sheetContext);
          if (mounted) _notice('$added yeni öğün eklendi. Eski kayıtlar korundu.');
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            Text('$label • Menü düzenleme', style: const TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 8),
            Text('${draft.length} öğün • ${draft.map((r) => r['name']).toSet().length} farklı tarif'),
            Text('Bilinen yemek maliyeti: ${_money(total)}'),
            Text('Eksik malzeme satın alma maliyeti: ${_money(purchaseCost)}'),
            if (unknown > 0 || unknownPurchase > 0)
              Text('$unknown tarif fiyatı ve $unknown satın alma fiyatı eksik olabilir.',
                style: const TextStyle(color: Colors.deepOrange)),
            const Text('Yemek maliyeti ve satın alma maliyeti farklı göstergelerdir. '
              'Stoklar ve mevcut plan bu ekranda değiştirilmez.',
              style: TextStyle(fontSize: 12)),
            SwitchListTile(title: const Text('Yalnızca alışveriş gerektiren menüyü göster'),
              subtitle: const Text('Bu filtre öğünleri silmez.'),
              value: onlyNeeds, onChanged: (v) => refresh(() => onlyNeeds = v)),
            ...draft.asMap().entries.where((entry) {
              if (!onlyNeeds) return true;
              final one = _menuPurchaseRows([entry.value]);
              return one.any((r) => _planNum(r['deficit']) > 0);
            }).map((entry) {
              final row = entry.value;
              final currentName = row['name']?.toString() ?? '';
              return Card(color: _pink, child: Padding(padding: const EdgeInsets.all(8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('${row['date']} • ${row['mealType']}',
                    style: const TextStyle(fontWeight: FontWeight.bold, color: _purple)),
                  DropdownButtonFormField<String>(
                    initialValue: names.contains(currentName) ? currentName : null,
                    isExpanded: true, decoration: const InputDecoration(labelText: 'Tarif seç'),
                    items: names.map((name) => DropdownMenuItem(value: name,
                      child: Text(name, overflow: TextOverflow.ellipsis))).toList(),
                    onChanged: (value) { if (value != null) {
                      refresh(() {
                      row['name'] = value; recalculate(row);
                    });
                    } }),
                  Wrap(spacing: 6, children: [1, 2, 4, 6, 8].map((n) => ChoiceChip(
                    label: Text('$n porsiyon'), selected: _planNum(row['portions']) == n,
                    onSelected: (_) => refresh(() { row['portions'] = n; recalculate(row); }),
                  )).toList()),
                  OutlinedButton.icon(
                    onPressed: () => _showMenuAlternatives(draft, row, () => refresh(() {})),
                    icon: const Icon(Icons.compare_arrows),
                    label: const Text('Alternatifleri maliyete göre karşılaştır')),
                  Row(children: [
                    Expanded(child: Text('Bilinen maliyet: ${_money(_planNum(row['cost']))}')),
                    IconButton(tooltip: 'Bu öğünü taslaktan çıkar',
                      onPressed: () => refresh(() => draft.remove(row)),
                      icon: const Icon(Icons.remove_circle_outline)),
                  ]),
                ])));
            }),
            const SizedBox(height: 8),
            Wrap(spacing: 8, runSpacing: 8, children: [
              OutlinedButton.icon(onPressed: draft.isEmpty ? null : () => _showMenuPurchasePreview(draft, '$label - düzenlenmiş'),
                icon: const Icon(Icons.shopping_cart_checkout), label: const Text('Eksik malzeme / alışveriş')),
              OutlinedButton.icon(onPressed: draft.isEmpty ? null : () async {
                final csv = <String>['Tarih;Öğün;Tarif;Porsiyon;Bilinen maliyet TL'];
                for (final row in draft) {
                  csv.add('${row['date']};${_planCsvCell(row['mealType'])};'
                    '${_planCsvCell(row['name'])};${row['portions']};${row['cost']}');
                }
                await Clipboard.setData(ClipboardData(text: csv.join('\n')));
                if (mounted) _notice('Düzenlenmiş menü CSV panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
              OutlinedButton.icon(onPressed: draft.isEmpty ? null : () => _saveMenuDraftSnapshot(draft, '$label - düzenlenmiş'),
                icon: const Icon(Icons.bookmark_add_outlined), label: const Text('Taslak olarak sakla')),
              FilledButton.icon(onPressed: draft.isEmpty ? null : save,
                icon: const Icon(Icons.save), label: const Text('Düzenlenmiş menüyü kaydet')),
            ]),
          ])));
      }));
  }

  // Aşama 1648–1747: Seçili menü için stok-birim uyumlu satın alma taslağı.
  // Bu hesap yalnızca kişisel tariflerin kayıtlı miktarlarını kullanır.
  List<Map<String, dynamic>> _menuPurchaseRows(List<Map<String, dynamic>> meals) {
    final totals = <String, Map<String, dynamic>>{};
    for (final meal in meals) {
      final name = meal['name']?.toString() ?? '';
      final matches = _customRecipes.where((r) => r['name'] == name);
      if (matches.isEmpty) continue;
      final portions = _planNum(meal['portions']).clamp(1, 30).toInt();
      final breakdown = _customRecipeCost(matches.first, portions);
      for (final part in (breakdown['rows'] as List).whereType<Map>()) {
        final ingredient = part['name']?.toString() ?? '';
        final unit = part['unit']?.toString() ?? 'adet';
        final key = _ingredientPriceKey(ingredient, unit);
        totals.putIfAbsent(key, () => <String, dynamic>{
          'name': ingredient, 'unit': unit, 'required': 0.0,
        });
        totals[key]!['required'] = _planNum(totals[key]!['required']) +
            _planNum(part['quantity']);
      }
    }
    final stocks = <String, double>{};
    final uncertain = <String>{};
    for (final record in _namedLists) {
      for (final value in (record['items'] as List? ?? [])) {
        final name = value.toString();
        final amount = double.tryParse((_namedStock(record, name)['amount'] ?? '')
            .replaceAll(',', '.'));
        if (amount == null || !amount.isFinite || amount < 0) continue;
        final raw = record['quantities'];
        final metadata = raw is Map ? raw[name] : null;
        final unit = metadata is Map ? metadata['unit']?.toString() : null;
        if (unit == null || !_units.contains(unit)) {
          uncertain.add(_normalizeName(name));
          continue;
        }
        final converted = _canonicalKitchenQuantity(amount, unit);
        final key = _ingredientPriceKey(name, converted['unit'].toString());
        // Aynı fiziksel stok birden fazla listede yer alabilir.
        // Çifte sayımı önlemek için en yüksek tek kayıt kullanılır.
        final qty = _planNum(converted['quantity']);
        if (qty > (stocks[key] ?? 0)) stocks[key] = qty;
      }
    }
    final rows = <Map<String, dynamic>>[];
    for (final entry in totals.entries) {
      final row = entry.value;
      final required = _planNum(row['required']);
      final available = stocks[entry.key];
      final deficit = (required - (available ?? 0)).clamp(0.0, double.infinity).toDouble();
      final price = _ingredientUnitPrices[entry.key];
      rows.add({...row, 'available': available, 'deficit': deficit,
        'price': price, 'cost': price == null ? null : deficit * price,
        'uncertain': available == null && uncertain.contains(_normalizeName(row['name'].toString()))});
    }
    rows.sort((a, b) => a['name'].toString().compareTo(b['name'].toString()));
    return rows;
  }

  void _showMenuPurchasePreview(List<Map<String, dynamic>> menu, String label) {
    bool onlyMissing = true;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheetContext) => StatefulBuilder(builder: (ctx, refresh) {
        final all = _menuPurchaseRows(menu);
        final visible = all.where((r) => !onlyMissing || _planNum(r['deficit']) > 0).toList();
        final missingPrice = all.where((r) => _planNum(r['deficit']) > 0 && r['price'] == null).length;
        final uncertain = all.where((r) => r['uncertain'] == true).length;
        final total = all.fold<double>(0, (sum, r) => sum + _planNum(r['cost']));
        Future<void> createPlan() async {
          final needed = all.where((r) => _planNum(r['deficit']) > 0).toList();
          if (needed.isEmpty) { _notice('Eksik malzeme bulunamadı.'); return; }
          final title = await _planText('Alışveriş planı adı', '$label - eksik malzemeler');
          if (title == null || title.trim().isEmpty || !mounted) return;
          final ok = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
            title: const Text('Taslak alışveriş planı'),
            content: Text('${needed.length} malzeme kaydedilecek. Mevcut liste, stoklar ve yemek planı değişmeyecek.'),
            actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Oluştur'))]));
          if (ok != true || !mounted) return;
          setState(() => _shoppingPlans.insert(0, <String, dynamic>{
            'id': DateTime.now().microsecondsSinceEpoch.toString(),
            'title': title, 'period': 'Haftalık',
            'created': DateTime.now().toIso8601String(), 'budget': total,
            'note': 'Seçilen menünün eksik malzemeleri. Bilinmeyen fiyat ve stok birimlerini doğrulayın.',
            'status': 'Taslak',
            'lines': needed.map((r) => <String, dynamic>{
              'name': r['name'], 'qty': r['deficit'], 'unit': r['unit'],
              'unitPrice': r['price'] ?? 0.0, 'actual': 0.0, 'done': false,
              'category': _guess(r['name'].toString()), 'store': '',
              'priority': r['uncertain'] == true ? 'Yüksek' : 'Normal',
            }).toList(),
          }));
          await _save();
          if (sheetContext.mounted) Navigator.pop(sheetContext);
          if (mounted) _notice('${needed.length} malzemelik taslak plan kaydedildi.');
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            Text('$label • Alışveriş ihtiyacı', style: const TextStyle(
              color: _purple, fontSize: 20, fontWeight: FontWeight.bold)),
            Text('Menü: ${menu.length} öğün • Malzeme: ${all.length} • Bilinen satın alma tutarı: ${_money(total)}'),
            if (missingPrice > 0) Text('$missingPrice eksik ürünün fiyatı bilinmiyor; toplam eksik olabilir.',
              style: const TextStyle(color: Colors.deepOrange)),
            if (uncertain > 0) Text('$uncertain üründe stok birimi belirsiz; stoktan düşülmedi.',
              style: const TextStyle(color: Colors.deepOrange)),
            const Text('Stok kayıtları aynı ürünü farklı listelerde içeriyorsa en yüksek tek kayıt kullanılır. '
              'Stokların güncel olduğunu kontrol edin.', style: TextStyle(fontSize: 12)),
            SwitchListTile(title: const Text('Yalnızca eksik malzemeler'), value: onlyMissing,
              onChanged: (v) => refresh(() => onlyMissing = v)),
            if (all.isEmpty) const ListTile(title: Text('Malzeme bulunamadı'),
              subtitle: Text('Kişisel tariflere miktar ve birim ekleyin.')),
            ...visible.map((r) => Card(color: _pink, child: ListTile(
              title: Text('${r['name']} • ${r['unit']}'),
              subtitle: Text('İhtiyaç: ${_planNum(r['required']).toStringAsFixed(2)} • '
                'Stok: ${r['available'] == null ? 'Bilinmiyor' : _planNum(r['available']).toStringAsFixed(2)} • '
                'Eksik: ${_planNum(r['deficit']).toStringAsFixed(2)}'
                '${r['uncertain'] == true ? ' • Birim kontrolü gerekli' : ''}'),
              trailing: Text(r['cost'] == null ? 'Fiyat yok' : _money(_planNum(r['cost']))),
            ))),
            Wrap(spacing: 8, runSpacing: 8, children: [
              OutlinedButton.icon(onPressed: () async {
                final lines = <String>['Malzeme;Birim;İhtiyaç;Stok;Eksik;Birim fiyat TL;Eksik maliyeti TL'];
                for (final r in all) {
                  lines.add('${_planCsvCell(r['name'])};${_planCsvCell(r['unit'])};'
                    '${r['required']};${r['available'] ?? ''};${r['deficit']};'
                    '${r['price'] ?? ''};${r['cost'] ?? ''}');
                }
                await Clipboard.setData(ClipboardData(text: lines.join('\n')));
                if (mounted) _notice('Menü alışveriş raporu panoya kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
              FilledButton.icon(onPressed: createPlan, icon: const Icon(Icons.playlist_add),
                label: const Text('Eksiklerden taslak plan oluştur')),
            ]),
          ])));
      }));
  }

  // Aşama 9648–9897: Öğün ve stok tüketimini tek onaylı işlemde bağlar.
  // Öğün üzerindeki stockDeductedAt işareti mükerrer tüketimi önler.
  void _showMealStockIntegration() {
    String query = '';
    bool onlyPending = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final meals = _kitchenMeals.where((m) {
          final name = (m['recipe'] ?? m['name'] ?? '').toString();
          if (!name.toLowerCase().contains(query.toLowerCase())) return false;
          return !onlyPending || m['stockDeductedAt'] == null;
        }).toList();
        final linked = _kitchenMeals.where((m) => m['stockDeductedAt'] != null).length;
        final spent = _kitchenMeals.where((m) => m['stockDeductedAt'] != null)
          .fold<double>(0, (sum, m) => sum + _planNum(m['stockDeductedCost']));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Yemek / stok / maliyet entegrasyonu', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Text('Stok işlemi bağlanan öğün: $linked • Bilinen toplam maliyet: ${_money(spent)}'),
            const Text('Her öğün için stok yalnızca bir kez düşülür. Önceden başka ekranda stok tükettiyseniz burada tekrar işlem yapmayın.'),
            TextField(decoration: const InputDecoration(labelText: 'Yemek ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca stok işlemi bekleyenler'), value: onlyPending,
              onChanged: (v) => refresh(() => onlyPending = v)),
            if (meals.isEmpty) const ListTile(title: Text('Eşleşen öğün bulunamadı.')),
            ...meals.map((meal) {
              final name = (meal['recipe'] ?? meal['name'] ?? '').toString();
              final recipes = _customRecipes.where((r) =>
                _normalizeName(r['name']?.toString() ?? '') == _normalizeName(name)).toList();
              final done = meal['stockDeductedAt'] != null;
              final portions = (_planNum(meal['preparedPortions']) > 0
                ? _planNum(meal['preparedPortions']) :
                _planNum(meal['portions']) > 0 ? _planNum(meal['portions']) : 2).toInt();
              return Card(child: Padding(padding: const EdgeInsets.all(8), child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                ListTile(title: Text(name), subtitle: Text('${meal['date'] ?? ''} • $portions porsiyon • '
                  '${done ? 'Stok işlendi' : 'Stok bekliyor'}'),
                  trailing: Icon(done ? Icons.verified : Icons.inventory_2_outlined,
                    color: done ? Colors.green : _purple)),
                if (done) Text('İşlem: ${meal['stockDeductedAt']} • Liste: ${meal['stockDeductedList'] ?? ''} • '
                  'Maliyet: ${_money(_planNum(meal['stockDeductedCost']))}'),
                if (recipes.isEmpty) const Text('Kişisel tarif eşleşmesi bulunamadı.'),
                if (!done && recipes.isNotEmpty)
                  FilledButton.tonalIcon(icon: const Icon(Icons.restaurant),
                    label: const Text('Stoktan tüket ve öğünü hazırla'),
                    onPressed: () async {
                      if (_namedLists.isEmpty) { _notice('Önce kayıtlı stok listesi oluşturun.'); return; }
                      Map<String, dynamic>? chosen;
                      final picked = await showDialog<Map<String, dynamic>>(context: context,
                        builder: (d) => SimpleDialog(title: const Text('Stok listesini seç'),
                          children: _namedLists.map((list) => SimpleDialogOption(
                            onPressed: () => Navigator.pop(d, list),
                            child: Text(list['title']?.toString() ?? 'Liste'))).toList()));
                      if (picked == null || !mounted) return;
                      chosen = picked;
                      final recipe = recipes.first;
                      final requirements = <String, double>{};
                      final issues = <String>[];
                      final units = <String, String>{};
                      final ingredients = (recipe['ingredients'] as List? ?? []).whereType<Map>().toList();
                      for (final ingredient in ingredients) {
                        final ingredientName = ingredient['name']?.toString().trim() ?? '';
                        final unit = ingredient['unit']?.toString() ?? '';
                        final required = _planNum(ingredient['quantity']) * portions;
                        if (ingredientName.isEmpty || required <= 0) { issues.add('Geçersiz tarif malzemesi'); continue; }
                        final names = (chosen['items'] as List? ?? []).map((e) => e.toString())
                          .where((n) => _normalizeName(n) == _normalizeName(ingredientName)).toList();
                        if (names.length != 1) { issues.add('$ingredientName: stok eşleşmesi yok veya belirsiz'); continue; }
                        final product = names.first;
                        final stock = _namedStock(chosen, product);
                        final stockUnit = _namedQuantity(chosen, product)['unit']?.toString() ?? '';
                        final amount = double.tryParse((stock['amount'] ?? '').replaceAll(',', '.'));
                        if (amount == null || !amount.isFinite || amount < 0 || stockUnit.isEmpty) {
                          issues.add('$product: geçerli stok miktarı/birimi yok'); continue;
                        }
                        if ((_expiryDays(chosen, product) ?? 0) < 0) {
                          issues.add('$product: SKT geçmiş'); continue;
                        }
                        final need = _canonicalKitchenQuantity(required, unit);
                        final stockOne = _canonicalKitchenQuantity(1, stockUnit);
                        if (need['unit'] != stockOne['unit'] || _planNum(stockOne['quantity']) <= 0) {
                          issues.add('$product: birim uyuşmazlığı'); continue;
                        }
                        requirements[product] = (requirements[product] ?? 0) +
                          _planNum(need['quantity']) / _planNum(stockOne['quantity']);
                        units[product] = stockUnit;
                      }
                      if (ingredients.isEmpty) issues.add('Tarif malzemesi bulunamadı');
                      for (final entry in requirements.entries) {
                        if (_stockNumber(_namedStock(chosen, entry.key)['amount']) + 0.000001 < entry.value) {
                          issues.add('${entry.key}: yetersiz stok');
                        }
                      }
                      if (issues.isNotEmpty) {
                        if (!mounted) return;
                        await showDialog<void>(context: context, builder: (d) => AlertDialog(
                          title: const Text('Stok işlemi yapılamıyor'),
                          content: SingleChildScrollView(child: Text(issues.join('\n'))),
                          actions: [TextButton(onPressed: () => Navigator.pop(d), child: const Text('Tamam'))]));
                        return;
                      }
                      final cost = _customRecipeCost(recipe, portions);
                      final ok = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
                        title: const Text('Yemek ve stok işlemini onayla'),
                        content: SingleChildScrollView(child: Text('$name • $portions porsiyon\n'
                          'Liste: ${chosen?['title'] ?? ''}\n'
                          '${requirements.entries.map((e) => '${e.key}: ${e.value.toStringAsFixed(2)} ${units[e.key]}').join('\n')}\n'
                          'Bilinen maliyet: ${_money(_planNum(cost['known']))}\n'
                          'Stok düşümü ve öğün kaydı birlikte yapılacaktır.')),
                        actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
                          FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Onayla'))]));
                      if (ok != true || !mounted || meal['stockDeductedAt'] != null) return;
                      // Onay sonrası son kontrol; aynı ürünün birden fazla malzemede kullanımı toplandı.
                      for (final entry in requirements.entries) {
                        if (_stockNumber(_namedStock(chosen, entry.key)['amount']) + 0.000001 < entry.value ||
                            (_expiryDays(chosen, entry.key) ?? 0) < 0) {
                          _notice('Stok değişmiş; işlem iptal edildi.'); return;
                        }
                      }
                      final now = DateTime.now().toIso8601String();
                      setState(() {
                        final meta = chosen!['stockMeta'] is Map
                          ? Map<String, dynamic>.from(chosen['stockMeta'] as Map) : <String, dynamic>{};
                        for (final entry in requirements.entries) {
                          final previous = _namedStock(chosen, entry.key);
                          final before = _stockNumber(previous['amount']);
                          final after = (before - entry.value).clamp(0.0, double.infinity).toDouble();
                          _recordStockMovement(chosen, entry.key, before, after,
                            'Öğün tüketimi: $name • ${meal['date'] ?? ''} • $portions porsiyon');
                          meta[entry.key] = {...previous, 'amount': after.toString(), 'updated': now};
                        }
                        chosen['stockMeta'] = meta;
                        chosen['updated'] = now;
                        meal['done'] = true;
                        meal['prepared'] = true;
                        meal['preparedAt'] ??= now;
                        meal['preparedPortions'] = portions;
                        meal['preparedCostEstimate'] = _planNum(cost['known']);
                        meal['preparedCostIncomplete'] = (cost['missing'] as List).isNotEmpty;
                        meal['stockDeductedAt'] = now;
                        meal['stockDeductedList'] = chosen['title']?.toString() ?? '';
                        meal['stockDeductedCost'] = _planNum(cost['known']);
                        meal['stockDeductedItems'] = requirements.map((k, v) =>
                          MapEntry(k, {'quantity': v, 'unit': units[k]}));
                      });
                      await _save();
                      if (sheet.mounted) refresh(() {});
                      _notice('Öğün ve stok tüketimi kaydedildi.');
                    }),
              ])));
            }),
            OutlinedButton.icon(onPressed: () async {
              final lines = <String>['Tarih;Yemek;Porsiyon;Stok işlem zamanı;Liste;Bilinen maliyet'];
              for (final meal in _kitchenMeals.where((m) => m['stockDeductedAt'] != null)) {
                lines.add([meal['date'], meal['recipe'] ?? meal['name'], meal['preparedPortions'],
                  meal['stockDeductedAt'], meal['stockDeductedList'], meal['stockDeductedCost']]
                  .map(_planCsvCell).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('Öğün / stok tüketim raporu kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Tüketim raporu CSV')),
          ])));
      }));
  }

  // Aşama 9398–9647: Planlanan öğünlerin gerçekleşme ve maliyet günlüğü.
  // Mevcut öğün şeması genişletilir; stoktan otomatik düşülmez.
  void _showMealPreparationJournal() {
    String query = '';
    String status = 'Tümü';
    DateTime selectedWeek = DateTime.now();
    selectedWeek = DateTime(selectedWeek.year, selectedWeek.month,
      selectedWeek.day).subtract(Duration(days: selectedWeek.weekday - 1));
    bool allDates = false;
    int page = 0;
    const pageSize = 15;

    String dateText(DateTime d) =>
      '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';

    Future<void> changeMeal(Map<String, dynamic> meal, bool complete,
        void Function(void Function()) refresh) async {
      final recipeName = (meal['recipe'] ?? meal['name'] ?? '').toString();
      if (complete) {
        final confirm = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
          title: const Text('Yemek hazırlandı mı?'),
          content: Text('$recipeName için hazırlama kaydı oluşturulacak. '
            'Bu işlem stoktan malzeme düşmez; stok tüketimi ayrıca yapılmalıdır.'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
            FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Hazırlandı')),
          ]));
        if (confirm != true || !mounted) return;
      } else {
        if (meal['stockDeductedAt'] != null) {
          _notice('Bu öğünün stok tüketimi kaydedildi; hazırlama durumu geri alınamaz.');
          return;
        }
        final confirm = await showDialog<bool>(context: context, builder: (d) => AlertDialog(
          title: const Text('Hazırlanma kaydını geri al'),
          content: const Text('Öğün yeniden planlandı olarak işaretlenecek. Stok hareketleri değişmez.'),
          actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
            FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Geri al'))]));
        if (confirm != true || !mounted) return;
      }
      refresh(() {
        meal['done'] = complete;
        meal['prepared'] = complete;
        if (complete) {
          meal['preparedAt'] = DateTime.now().toIso8601String();
          meal['preparedPortions'] = (_planNum(meal['portions']) > 0
            ? _planNum(meal['portions']) : 2).toInt();
          final matches = _customRecipes.where((r) =>
            r['name']?.toString() == recipeName);
          if (matches.isNotEmpty) {
            final cost = _customRecipeCost(matches.first,
              (meal['preparedPortions'] as int));
            meal['preparedCostEstimate'] = _planNum(cost['known']);
            meal['preparedCostIncomplete'] = (cost['missing'] as List).isNotEmpty;
          }
        } else {
          meal.remove('preparedAt');
          meal.remove('preparedPortions');
          meal.remove('preparedCostEstimate');
          meal.remove('preparedCostIncomplete');
        }
      });
      await _save();
      if (mounted) _notice(complete ? 'Öğün hazırlandı olarak kaydedildi.' : 'Öğün yeniden planlandı.');
    }

    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final weekEnd = selectedWeek.add(const Duration(days: 7));
        final rows = _kitchenMeals.where((m) {
          final date = DateTime.tryParse(m['date']?.toString() ?? '');
          if (!allDates && (date == null || date.isBefore(selectedWeek) || !date.isBefore(weekEnd))) return false;
          final done = m['done'] == true || m['prepared'] == true;
          if (status == 'Hazırlanan' && !done) return false;
          if (status == 'Planlanan' && done) return false;
          return '${m['recipe'] ?? m['name'] ?? ''} ${m['date'] ?? ''}'
            .toLowerCase().contains(query.toLowerCase());
        }).toList()..sort((a, b) => (b['date'] ?? '').toString()
          .compareTo((a['date'] ?? '').toString()));
        final doneCount = rows.where((m) => m['done'] == true || m['prepared'] == true).length;
        final totalCost = rows.where((m) => m['done'] == true || m['prepared'] == true)
          .fold<double>(0, (v, m) => v + _planNum(m['preparedCostEstimate']));
        final pages = rows.isEmpty ? 1 : (rows.length + pageSize - 1) ~/ pageSize;
        final current = page.clamp(0, pages - 1).toInt();
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Yemek hazırlama ve gerçekleşme günlüğü',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Planlanan ve hazırlanan öğünleri izleyin. Stoktan düşüm bu ekranda yapılmaz.'),
            SwitchListTile(title: const Text('Tüm tarihler'), value: allDates,
              onChanged: (v) => refresh(() {allDates = v; page = 0;})),
            if (!allDates) Row(children: [
              IconButton(onPressed: () => refresh(() {selectedWeek = selectedWeek.subtract(const Duration(days: 7)); page = 0;}),
                icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('${dateText(selectedWeek)} – ${dateText(weekEnd.subtract(const Duration(days: 1)))}',
                textAlign: TextAlign.center)),
              IconButton(onPressed: () => refresh(() {selectedWeek = selectedWeek.add(const Duration(days: 7)); page = 0;}),
                icon: const Icon(Icons.chevron_right)),
            ]),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Yemek veya tarih ara'),
              onChanged: (v) => refresh(() {query = v.trim(); page = 0;})),
            Wrap(spacing: 8, children: ['Tümü', 'Planlanan', 'Hazırlanan'].map((v) =>
              ChoiceChip(label: Text(v), selected: status == v,
                onSelected: (_) => refresh(() {status = v; page = 0;}))).toList()),
            Text('Toplam ${rows.length} öğün • Hazırlanan $doneCount • Bekleyen ${rows.length - doneCount}'),
            Text('Kayıtlı hazırlama maliyeti tahmini: ${_money(totalCost)}'),
            if (rows.isEmpty) const ListTile(title: Text('Bu filtrede öğün bulunamadı.')),
            ...rows.skip(current * pageSize).take(pageSize).map((meal) {
              final name = (meal['recipe'] ?? meal['name'] ?? 'Öğün').toString();
              final done = meal['done'] == true || meal['prepared'] == true;
              final matches = _customRecipes.where((r) => r['name']?.toString() == name);
              final portions = (_planNum(meal['portions']) > 0 ? _planNum(meal['portions']) : 2).toInt();
              final estimate = matches.isEmpty ? null : _customRecipeCost(matches.first, portions);
              return Card(child: Column(children: [
                ListTile(title: Text(name),
                  subtitle: Text('${meal['date'] ?? 'Tarih yok'} • $portions porsiyon • '
                    '${done ? 'Hazırlandı' : 'Planlandı'}'
                    '${meal['preparedAt'] == null ? '' : ' • ${meal['preparedAt'].toString().split('T').first}'}'),
                  trailing: Icon(done ? Icons.check_circle : Icons.schedule,
                    color: done ? Colors.green : _purple)),
                if (estimate != null) Text('Güncel tahmini tarif maliyeti: ${_money(_planNum(estimate['known']))}'),
                if (done && meal['preparedCostEstimate'] != null)
                  Text('Hazırlama anındaki bilinen maliyet: ${_money(_planNum(meal['preparedCostEstimate']))}'
                    '${meal['preparedCostIncomplete'] == true ? ' • Eksik fiyat var' : ''}'),
                TextButton.icon(onPressed: () => changeMeal(meal, !done, refresh),
                  icon: Icon(done ? Icons.undo : Icons.restaurant),
                  label: Text(done ? 'Hazırlanmayı geri al' : 'Hazırlandı olarak işaretle')),
              ]));
            }),
            if (pages > 1) Row(children: [
              IconButton(onPressed: current > 0 ? () => refresh(() => page = current - 1) : null,
                icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('${current + 1} / $pages', textAlign: TextAlign.center)),
              IconButton(onPressed: current + 1 < pages ? () => refresh(() => page = current + 1) : null,
                icon: const Icon(Icons.chevron_right)),
            ]),
            OutlinedButton.icon(onPressed: rows.isEmpty ? null : () async {
              String cell(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')} "'.trimRight();
              final lines = <String>['Tarih;Yemek;Porsiyon;Durum;Hazırlama zamanı;Maliyet tahmini'];
              for (final m in rows) {
                lines.add([m['date'], m['recipe'] ?? m['name'], m['preparedPortions'] ?? m['portions'],
                  m['done'] == true || m['prepared'] == true ? 'Hazırlandı' : 'Planlandı',
                  m['preparedAt'], m['preparedCostEstimate']].map(cell).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('Yemek hazırlama günlüğü CSV olarak kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Günlüğü CSV kopyala')),
          ])));
      }));
  }

  // Aşama 9148–9397: Haftalık menü için sanal stok rezervasyonu.
  // Rezervasyon yalnızca hesaplamadır; fiziksel stok veya yemek kaydı değişmez.
  void _showWeeklyStockReservation() {
    final now = DateTime.now();
    DateTime weekStart = now.subtract(Duration(days: now.weekday - 1));
    weekStart = DateTime(weekStart.year, weekStart.month, weekStart.day);
    String source = 'Takvim';
    int draftIndex = 0;
    String query = '';
    String filter = 'Tümü';
    bool onlyMissing = false;
    bool showDetails = true;
    bool includePrepared = false;
    int extraGuests = 0;

    List<Map<String, dynamic>> selectedMeals() {
      if (source == 'Taslak') {
        if (_savedMenuDrafts.isEmpty) return [];
        final draft = _savedMenuDrafts[draftIndex.clamp(0, _savedMenuDrafts.length - 1)];
        final raw = draft['meals'];
        if (raw is! List) return [];
        return raw.whereType<Map>().map((m) => Map<String, dynamic>.from(m)).toList();
      }
      final end = weekStart.add(const Duration(days: 7));
      final rows = <Map<String, dynamic>>[];
      for (final meal in _kitchenMeals) {
        final date = DateTime.tryParse(meal['date']?.toString() ?? '');
        if (date == null || date.isBefore(weekStart) || !date.isBefore(end)) continue;
        if (!includePrepared && (meal['done'] == true || meal['prepared'] == true)) continue;
        final recipeName = (meal['recipe'] ?? meal['name'] ?? '').toString();
        if (recipeName.trim().isEmpty) continue;
        rows.add(<String, dynamic>{
          'date': meal['date'], 'name': recipeName,
          'portions': (_planNum(meal['portions']) + extraGuests).clamp(1, 30).toInt(),
        });
      }
      rows.sort((a, b) => a['date'].toString().compareTo(b['date'].toString()));
      return rows;
    }

    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final meals = selectedMeals();
        final recognized = meals.where((m) => _customRecipes.any((r) =>
          r['name']?.toString() == m['name']?.toString())).toList();
        final unknownMeals = meals.length - recognized.length;
        final rows = _menuPurchaseRows(recognized);
        final filtered = rows.where((r) {
          if (query.isNotEmpty && !r['name'].toString().toLowerCase().contains(query.toLowerCase())) return false;
          if (onlyMissing && _planNum(r['deficit']) <= 0) return false;
          if (filter == 'Eksik' && _planNum(r['deficit']) <= 0) return false;
          if (filter == 'Yeterli' && (r['available'] == null || _planNum(r['deficit']) > 0)) return false;
          if (filter == 'Belirsiz' && r['available'] != null && r['uncertain'] != true) return false;
          return true;
        }).toList();
        final totalRequired = rows.fold<double>(0, (v, r) => v + _planNum(r['required']));
        final missing = rows.where((r) => _planNum(r['deficit']) > 0).length;
        final unknownStock = rows.where((r) => r['available'] == null).length;
        final unknownPrice = rows.where((r) => _planNum(r['deficit']) > 0 && r['price'] == null).length;
        final estimatedCost = rows.fold<double>(0, (v, r) => v + _planNum(r['cost']));
        final fullyReady = rows.where((r) => r['available'] != null && _planNum(r['deficit']) <= 0).length;
        final endDate = weekStart.add(const Duration(days: 6));
        String dateLabel(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Haftalık menü / sanal stok rezervasyonu', style: TextStyle(
            fontSize: 20, color: _purple, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          const Text('Aynı malzemeyi kullanan öğünlerin ihtiyaçları birleştirilir. '
            'Bu ekran stok düşmez, yalnızca planlanan tüketimi hesaplar.',
            style: TextStyle(fontSize: 12)),
          const SizedBox(height: 12),
          SegmentedButton<String>(segments: const [
            ButtonSegment(value: 'Takvim', label: Text('Yemek takvimi')),
            ButtonSegment(value: 'Taslak', label: Text('Menü taslağı')),
          ], selected: {source}, onSelectionChanged: (v) => refresh(() => source = v.first)),
          if (source == 'Takvim') SwitchListTile(
            title: const Text('Hazırlanmış öğünleri de dahil et'), value: includePrepared,
            onChanged: (v) => refresh(() => includePrepared = v)),
          if (source == 'Takvim') Row(children: [
            IconButton(onPressed: () => refresh(() => weekStart = weekStart.subtract(const Duration(days: 7))),
              icon: const Icon(Icons.chevron_left)),
            Expanded(child: Text('${dateLabel(weekStart)} – ${dateLabel(endDate)}', textAlign: TextAlign.center)),
            IconButton(onPressed: () => refresh(() => weekStart = weekStart.add(const Duration(days: 7))),
              icon: const Icon(Icons.chevron_right)),
            TextButton(onPressed: () => refresh(() {
              final today = DateTime.now();
              weekStart = DateTime(today.year, today.month, today.day).subtract(Duration(days: today.weekday - 1));
            }), child: const Text('Bu hafta')),
          ]),
          if (source == 'Taslak' && _savedMenuDrafts.isEmpty)
            const ListTile(title: Text('Kayıtlı menü taslağı bulunmuyor.')),
          if (source == 'Taslak' && _savedMenuDrafts.isNotEmpty)
            DropdownButtonFormField<int>(initialValue: draftIndex.clamp(0, _savedMenuDrafts.length - 1),
              decoration: const InputDecoration(labelText: 'Menü taslağı'),
              items: List.generate(_savedMenuDrafts.length, (i) => DropdownMenuItem(
                value: i, child: Text(_savedMenuDrafts[i]['title']?.toString() ?? 'Taslak ${i + 1}',
                  overflow: TextOverflow.ellipsis))),
              onChanged: (v) { if (v != null) refresh(() => draftIndex = v); }),
          if (source == 'Takvim') SwitchListTile(
            title: const Text('Hazırlanmış öğünleri de dahil et'), value: includePrepared,
            onChanged: (v) => refresh(() => includePrepared = v)),
          if (source == 'Takvim') Row(children: [
            const Expanded(child: Text('Öğün başına ilave kişi')),
            IconButton(onPressed: extraGuests == 0 ? null : () => refresh(() => extraGuests--),
              icon: const Icon(Icons.remove_circle_outline)),
            Text('$extraGuests'),
            IconButton(onPressed: extraGuests >= 10 ? null : () => refresh(() => extraGuests++),
              icon: const Icon(Icons.add_circle_outline)),
          ]),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Öğün: ${meals.length} • Eşleşen tarif: ${recognized.length} • Tarif bulunamayan: $unknownMeals'),
            Text('Malzeme türü: ${rows.length} • Yeterli: $fullyReady • Eksik: $missing'),
            Text('Stoku belirsiz: $unknownStock • Fiyatı belirsiz: $unknownPrice'),
            Text('Toplam hesaplanan miktar (farklı birimler dahil): ${totalRequired.toStringAsFixed(2)}'),
            Text('Bilinen eksiklerin tahmini maliyeti: ${_money(estimatedCost)}'),
          ]))),
          if (unknownMeals > 0) const ListTile(leading: Icon(Icons.warning_amber, color: Colors.deepOrange),
            title: Text('Bazı öğünler kişisel tariflerle eşleşmedi.'),
            subtitle: Text('Bu öğünlerin malzemeleri toplam ihtiyaca dahil edilemedi.')),
          if (unknownStock > 0 || unknownPrice > 0) const Text(
            'Bilinmeyen stok veya fiyat bilgileri nedeniyle sonuçlar eksik olabilir.',
            style: TextStyle(color: Colors.deepOrange)),
          SwitchListTile(title: const Text('Yalnızca eksikleri göster'), value: onlyMissing,
            onChanged: (v) => refresh(() => onlyMissing = v)),
          SwitchListTile(title: const Text('Öğünleri göster'), value: showDetails,
            onChanged: (v) => refresh(() => showDetails = v)),
          if (showDetails) ...meals.map((m) => ListTile(dense: true,
            leading: const Icon(Icons.restaurant_outlined),
            title: Text(m['name']?.toString() ?? ''),
            subtitle: Text('${m['date'] ?? 'Taslak'} • ${m['portions'] ?? 1} porsiyon'),
            trailing: _customRecipes.any((r) => r['name'] == m['name'])
              ? const Icon(Icons.check_circle_outline, color: Colors.green)
              : const Icon(Icons.warning_amber, color: Colors.deepOrange))),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
            labelText: 'Malzeme ara'), onChanged: (v) => refresh(() => query = v)),
          DropdownButtonFormField<String>(initialValue: filter,
            decoration: const InputDecoration(labelText: 'Stok durumu'),
            items: ['Tümü', 'Eksik', 'Yeterli', 'Belirsiz'].map((v) => DropdownMenuItem(
              value: v, child: Text(v))).toList(),
            onChanged: (v) { if (v != null) refresh(() => filter = v); }),
          if (rows.isEmpty) const ListTile(title: Text('Bu seçim için hesaplanabilir tarif malzemesi yok.')),
          ...filtered.map((r) => Card(color: _pink, child: ListTile(
            title: Text('${r['name']} (${r['unit']})'),
            subtitle: Text('Toplam ihtiyaç: ${_planNum(r['required']).toStringAsFixed(2)} • '
              'Mevcut: ${r['available'] == null ? 'Belirsiz' : _planNum(r['available']).toStringAsFixed(2)} • '
              'Alınacak: ${_planNum(r['deficit']).toStringAsFixed(2)}'),
            trailing: Text(r['cost'] == null ? 'Fiyat yok' : _money(_planNum(r['cost']))),
          ))),
          const SizedBox(height: 12),
          Wrap(spacing: 8, runSpacing: 8, children: [
            OutlinedButton.icon(onPressed: rows.isEmpty ? null : () async {
              final csv = <String>['Malzeme;Birim;Toplam ihtiyaç;Stok;Eksik;Birim fiyat;Eksik maliyeti'];
              for (final r in filtered) {
                csv.add('${_planCsvCell(r['name'])};${_planCsvCell(r['unit'])};'
                  '${r['required']};${r['available'] ?? ''};${r['deficit']};'
                  '${r['price'] ?? ''};${r['cost'] ?? ''}');
              }
              await Clipboard.setData(ClipboardData(text: csv.join('\n')));
              if (mounted) _notice('Haftalık stok planı CSV panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
            FilledButton.icon(onPressed: recognized.isEmpty ? null : () => _showMenuPurchasePreview(
              recognized, source == 'Takvim' ? 'Hafta ${dateLabel(weekStart)}' : 'Menü taslağı'),
              icon: const Icon(Icons.shopping_cart_outlined), label: const Text('Eksiklerden alışveriş planı')),
          ]),
          const SizedBox(height: 12),
          const Text('Not: Sanal rezervasyon stok kayıtlarını kilitlemez. Aynı ürünün farklı '
            'listelerdeki miktarları toplanmaz; çift sayımı önlemek için en yüksek tek stok kaydı '
            'esas alınır. Tarif hazırlama sırasında stok düşme işlemi ayrıca yapılır.',
            style: TextStyle(fontSize: 12)),
        ])));
      }));
  }

  // Aylık bütçe, yemek maliyeti ve israfı tek ekranda karşılaştırır.
  // Aşama 9898–10147: kayıtlı hareket ve öğünlerden tüketim analitiği.
  // Salt okunur: stok, öğün ve alışveriş kayıtlarını değiştirmez.

  // Aşama 10148–10397: Hareket bazlı talep, satın alma ve bütçe simülasyonu.
  // Salt okunur; tahminler stok ve alışveriş kayıtlarını değiştirmez.

  // Aşama 10398–10647: Kayıtlı liste fiyatlarından market karşılaştırması.
  // Çevrimiçi fiyat iddiası yoktur; kaynak yalnızca kullanıcının kayıtlarıdır.

  // Aşama 10648–10897: kayıtlı miktarlara göre gerçek sepet senaryoları.
  // Salt okunur: fiyatlar ve stoklar değiştirilmez; market ziyaret maliyeti
  // ayrı gösterilir, geçmiş fiyatlar canlı teklif olarak yorumlanmaz.
  void _showKitchenBasketPlanner() {
    var selectedList = -1;
    var budget = 2000.0;
    var visitCost = 0.0;
    var query = '';
    var onlyMissing = false;
    var sort = 'Öncelik';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final sources = <String, List<Map<String, dynamic>>>{};
        for (final list in _namedLists) {
          for (final raw in (list['items'] as List? ?? const [])) {
            final name = raw.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final amount = _planNum(q['amount']);
            final total = _namedItemTotal(list, name);
            final store = (_namedProductMeta(list, name)['store'] ?? '').trim();
            if (amount <= 0 || !amount.isFinite || total <= 0 || !total.isFinite || store.isEmpty) continue;
            final key = '${name.toLowerCase()}|$unit';
            sources.putIfAbsent(key, () => <Map<String, dynamic>>[]).add({
              'store': store, 'price': total / amount, 'name': name, 'unit': unit,
              'source': (list['title'] ?? 'Adsız liste').toString(),
            });
          }
        }
        if (selectedList >= _namedLists.length) selectedList = -1;
        final demand = <String, Map<String, dynamic>>{};
        if (selectedList < 0) {
          for (final name in _items) {
            if (_done.contains(name)) continue;
            final detail = _details[name] ?? <String, String>{};
            final unit = (detail['unit'] ?? 'adet').trim().toLowerCase();
            final rawAmount = double.tryParse((detail['amount'] ?? '1').replaceAll(',', '.'));
            final amount = rawAmount != null && rawAmount.isFinite && rawAmount > 0 ? rawAmount : 1.0;
            final key = '${name.trim().toLowerCase()}|$unit';
            if (name.trim().isEmpty) continue;
            final row = demand.putIfAbsent(key, () => {'name': name, 'unit': unit, 'amount': 0.0});
            row['amount'] = (row['amount'] as double) + amount;
          }
        } else {
          final list = _namedLists[selectedList];
          for (final raw in (list['items'] as List? ?? const [])) {
            final name = raw.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final amount = _planNum(q['amount']);
            final key = '${name.toLowerCase()}|$unit';
            final row = demand.putIfAbsent(key, () => {'name': name, 'unit': unit, 'amount': 0.0});
            row['amount'] = (row['amount'] as double) + (amount.isFinite && amount > 0 ? amount : 1.0);
          }
        }
        final rows = <Map<String, dynamic>>[];
        final storeTotals = <String, double>{};
        final storeCovered = <String, int>{};
        var splitCost = 0.0;
        var unknown = 0;
        var knownCount = 0;
        for (final entry in demand.entries) {
          final item = entry.value;
          final options = sources[entry.key] ?? <Map<String, dynamic>>[];
          final byStore = <String, Map<String, dynamic>>{};
          for (final offer in options) {
            final store = offer['store'] as String;
            final existing = byStore[store];
            if (existing == null || (offer['price'] as double) < (existing['price'] as double)) {
              byStore[store] = offer;
            }
          }
          final ranked = byStore.values.toList()
            ..sort((a, b) => (a['price'] as double).compareTo(b['price'] as double));
          final amount = item['amount'] as double;
          final best = ranked.isEmpty ? null : ranked.first;
          if (best == null) { unknown++; } else {
            knownCount++;
            splitCost += (best['price'] as double) * amount;
          }
          for (final offer in ranked) {
            final store = offer['store'] as String;
            storeTotals[store] = (storeTotals[store] ?? 0) + (offer['price'] as double) * amount;
            storeCovered[store] = (storeCovered[store] ?? 0) + 1;
          }
          rows.add({'name': item['name'], 'unit': item['unit'], 'amount': amount,
            'best': best, 'options': ranked, 'cost': best == null ? null : (best['price'] as double) * amount});
        }
        final stores = storeTotals.keys.toList()..sort((a,b) {
          final coverage = (storeCovered[b] ?? 0).compareTo(storeCovered[a] ?? 0);
          return coverage != 0 ? coverage : (storeTotals[a] ?? 0).compareTo(storeTotals[b] ?? 0);
        });
        final splitStores = rows.where((r) => r['best'] != null)
          .map((r) => (r['best'] as Map<String, dynamic>)['store'] as String).toSet();
        final splitWithTravel = splitCost + splitStores.length * visitCost;
        final completeStores = stores.where((store) => storeCovered[store] == demand.length).toList()
          ..sort((a,b) => (storeTotals[a] ?? 0).compareTo(storeTotals[b] ?? 0));
        final singleStore = completeStores.isEmpty ? null : completeStores.first;
        final singleCost = singleStore == null ? null : (storeTotals[singleStore] ?? 0) + visitCost;
        final cheapestScenario = singleCost != null && singleCost <= splitWithTravel ? 'Tek market' : 'Çoklu market';
        final visible = rows.where((r) =>
          ('${r['name']} ${r['unit']}'.toLowerCase().contains(query.toLowerCase())) &&
          (!onlyMissing || r['best'] == null)).toList();
        if (sort == 'Maliyet') {
          visible.sort((a,b) => _planNum(b['cost']).compareTo(_planNum(a['cost'])));
        } else if (sort == 'Ürün') {
          visible.sort((a,b) => a['name'].toString().compareTo(b['name'].toString()));
        } else {
          visible.sort((a,b) => (a['best'] == null ? -1 : 0).compareTo(b['best'] == null ? -1 : 0));
        }
        var remaining = budget;
        var affordableCount = 0;
        for (final row in rows.where((r) => r['cost'] != null)
          .toList()..sort((a,b) => _planNum(a['cost']).compareTo(_planNum(b['cost'])))) {
          final cost = row['cost'] as double;
          if (cost <= remaining) { remaining -= cost; affordableCount++; }
        }
        String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Gerçek miktarlı market sepeti', style: TextStyle(fontSize: 20,
              fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı fiyatlara dayalı simülasyondur. Canlı fiyat, stok veya teslimat uygunluğu garantisi vermez.'),
            DropdownButtonFormField<int>(initialValue: selectedList,
              decoration: const InputDecoration(labelText: 'Alışveriş ihtiyacı kaynağı'),
              isExpanded: true,
              items: [const DropdownMenuItem(value: -1, child: Text('Aktif alışveriş listesi (tamamlanmayanlar)')),
                ...List.generate(_namedLists.length, (i) => DropdownMenuItem(
                  value: i, child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis)))],
              onChanged: (v) {if (v != null) refresh(() => selectedList = v);}),
            Row(children: [const Text('Bütçe'), Expanded(child: Slider(value: budget, min: 0, max: 20000,
              divisions: 200, onChanged: (v) => refresh(() => budget = v))), Text(_money(budget))]),
            Row(children: [const Text('Market başı ulaşım'), Expanded(child: Slider(value: visitCost,
              min: 0, max: 500, divisions: 100, onChanged: (v) => refresh(() => visitCost = v))), Text(_money(visitCost))]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('Ürün: ${rows.length} • Fiyatı bulunan: $knownCount • Fiyatı eksik: $unknown'),
              Text('En ucuz ürünlerden sepet: ${_money(splitCost)}'),
              Text('Çoklu market (${splitStores.length} market + ulaşım): ${_money(splitWithTravel)}'),
              Text(singleCost == null ? 'Tüm ürünleri fiyatlandıran tek market bulunamadı.' :
                'Tek market ($singleStore + ulaşım): ${_money(singleCost)}'),
              if (unknown == 0 && rows.isNotEmpty)
                Text('Maliyet açısından önerilen senaryo: $cheapestScenario',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
              if (unknown > 0) const Text('Eksik fiyatlar nedeniyle sepet toplamı tam değildir.',
                style: TextStyle(color: Colors.deepOrange)),
              Text('Bütçeye sığan (en düşük fiyatlı ürünlerden): $affordableCount / $knownCount'),
              Text('Bütçede kalan (ulaşım hariç): ${_money(remaining)}'),
            ]))),
            const Text('Market bazlı senaryolar', style: TextStyle(fontWeight: FontWeight.bold)),
            if (stores.isEmpty) const Text('Kayıtlı market fiyatı bulunamadı.'),
            ...stores.map((store) => ListTile(dense: true,
              title: Text(store), subtitle: Text('${storeCovered[store]} / ${rows.length} ürün fiyatı mevcut'),
              trailing: Text('${_money((storeTotals[store] ?? 0) + visitCost)}*'))),
            const Text('* Kısmi market sepeti fiyatıdır; eksik ürünlerin maliyeti dahil değildir.',
              style: TextStyle(fontSize: 12)),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Ürün ara'),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca fiyatı bulunamayanlar'), value: onlyMissing,
              onChanged: (v) => refresh(() => onlyMissing = v)),
            DropdownButton<String>(value: sort,
              items: ['Öncelik', 'Maliyet', 'Ürün'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) {if(v != null) refresh(() => sort = v);}),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Ürün;Miktar;Birim;En uygun market;Birim fiyat;Toplam;Alternatif market sayısı'];
              for (final row in visible) {
                final best = row['best'] as Map<String, dynamic>?;
                lines.add([row['name'], row['amount'], row['unit'], best?['store'], best?['price'],
                  row['cost'], (row['options'] as List).length].map(csv).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
              _notice('Miktarlı sepet raporu kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Sepet raporunu CSV kopyala')),
            ...visible.map((row) {
              final best = row['best'] as Map<String, dynamic>?;
              final options = row['options'] as List<Map<String, dynamic>>;
              return Card(child: ExpansionTile(
                title: Text('${row['name']} • ${row['amount']} ${row['unit']}'),
                subtitle: Text(best == null ? 'Fiyat bulunamadı' :
                  '${best['store']} • ${_money(row['cost'] as double)}'),
                children: options.map((o) => ListTile(dense: true,
                  title: Text('${o['store']} • ${_money(o['price'] as double)} / ${row['unit']}'),
                  subtitle: Text('Toplam: ${_money((o['price'] as double) * (row['amount'] as double))} • Kaynak: ${o['source']}'))).toList(),
              ));
            }),
          ])));
      }),
    );
  }

  // Aşama 10898–11147: Ziyaret sayısı sınırlı market dağılımı.
  // Kayıtlı birim fiyatları kullanır; stok ve alışveriş kayıtlarına dokunmaz.
  void _showKitchenStoreRoutePlanner() {
    var selectedList = -1;
    var maxVisits = 2;
    var visitFee = 30.0;
    var budget = 2000.0;
    var query = '';
    var showOnlyMissing = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final prices = <String, Map<String, double>>{};
        for (final list in _namedLists) {
          for (final item in (list['items'] as List? ?? const [])) {
            final name = item.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final amount = _planNum(q['amount']);
            final total = _namedItemTotal(list, name);
            final store = (_namedProductMeta(list, name)['store'] ?? '').trim();
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            if (store.isEmpty || amount <= 0 || !amount.isFinite || total <= 0 || !total.isFinite) continue;
            final key = '${name.toLowerCase()}|$unit';
            final offers = prices.putIfAbsent(key, () => <String, double>{});
            final rate = total / amount;
            if (!offers.containsKey(store) || rate < offers[store]!) offers[store] = rate;
          }
        }
        if (selectedList >= _namedLists.length) selectedList = -1;
        final demand = <String, Map<String, dynamic>>{};
        if (selectedList < 0) {
          for (final name in _items) {
            if (_done.contains(name) || name.trim().isEmpty) continue;
            final detail = _details[name] ?? <String, String>{};
            final unit = (detail['unit'] ?? 'adet').trim().toLowerCase();
            final amount = double.tryParse((detail['amount'] ?? '1').replaceAll(',', '.'));
            final key = '${name.trim().toLowerCase()}|$unit';
            final row = demand.putIfAbsent(key, () => {'name': name, 'unit': unit, 'amount': 0.0});
            row['amount'] = (row['amount'] as double) + (amount != null && amount.isFinite && amount > 0 ? amount : 1.0);
          }
        } else {
          final list = _namedLists[selectedList];
          for (final item in (list['items'] as List? ?? const [])) {
            final name = item.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final amount = _planNum(q['amount']);
            final key = '${name.toLowerCase()}|$unit';
            final row = demand.putIfAbsent(key, () => {'name': name, 'unit': unit, 'amount': 0.0});
            row['amount'] = (row['amount'] as double) + (amount.isFinite && amount > 0 ? amount : 1.0);
          }
        }
        final allStores = <String>{};
        for (final key in demand.keys) { allStores.addAll((prices[key] ?? {}).keys); }
        final rankedStores = allStores.toList()..sort((a,b) {
          final ac = demand.keys.where((key) => (prices[key] ?? {}).containsKey(a)).length;
          final bc = demand.keys.where((key) => (prices[key] ?? {}).containsKey(b)).length;
          return bc.compareTo(ac);
        });
        // Kombinasyon patlamasını engellemek için en çok ürün kapsayan 12 market.
        final candidates = rankedStores.take(12).toList();
        final maxMask = 1 << candidates.length;
        var bestCoverage = -1;
        var bestTotal = double.infinity;
        var bestStores = <String>[];
        var bestAssignments = <Map<String, dynamic>>[];
        for (var mask = 1; mask < maxMask; mask++) {
          final chosen = <String>[];
          for (var i = 0; i < candidates.length; i++) {
            if ((mask & (1 << i)) != 0) chosen.add(candidates[i]);
          }
          if (chosen.length > maxVisits) continue;
          var total = chosen.length * visitFee;
          var coverage = 0;
          final assigned = <Map<String, dynamic>>[];
          for (final entry in demand.entries) {
            String? winner;
            var cheapest = double.infinity;
            for (final store in chosen) {
              final rate = prices[entry.key]?[store];
              if (rate != null && rate < cheapest) { cheapest = rate; winner = store; }
            }
            if (winner != null) {
              coverage++;
              final cost = cheapest * (entry.value['amount'] as double);
              total += cost;
              assigned.add({...entry.value, 'store': winner, 'rate': cheapest, 'cost': cost});
            }
          }
          if (coverage > bestCoverage || (coverage == bestCoverage && total < bestTotal)) {
            bestCoverage = coverage;
            bestTotal = total;
            bestStores = chosen;
            bestAssignments = assigned;
          }
        }
        final missing = demand.entries.where((entry) =>
          !bestAssignments.any((r) => '${r['name'].toString().toLowerCase()}|${r['unit']}' == entry.key)).toList();
        final allPriced = demand.keys.where((key) => (prices[key] ?? {}).isNotEmpty).length;
        final assignmentsByStore = <String, List<Map<String, dynamic>>>{};
        for (final row in bestAssignments) {
          assignmentsByStore.putIfAbsent(row['store'] as String, () => []).add(row);
        }
        String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
        final filtered = bestAssignments.where((r) =>
          !showOnlyMissing && '${r['name']} ${r['store']}'.toLowerCase().contains(query.toLowerCase())).toList();
        final filteredMissing = missing.where((e) =>
          e.value['name'].toString().toLowerCase().contains(query.toLowerCase())).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı market dağılımı ve ziyaret planı',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı fiyatlarla hesaplanır; gerçek rota mesafesi, canlı fiyat ve market stokları bilinmez.'),
            DropdownButtonFormField<int>(initialValue: selectedList, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Alışveriş listesi'),
              items: [const DropdownMenuItem(value: -1, child: Text('Aktif alışveriş listesi')),
                ...List.generate(_namedLists.length, (i) => DropdownMenuItem(value: i,
                  child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis)))],
              onChanged: (v) {if (v != null) refresh(() => selectedList = v);}),
            Row(children: [Text('En fazla $maxVisits market'), Expanded(child: Slider(
              value: maxVisits.toDouble(), min: 1, max: 5, divisions: 4,
              onChanged: (v) => refresh(() => maxVisits = v.round())))]),
            Row(children: [const Text('Ziyaret maliyeti'), Expanded(child: Slider(
              value: visitFee, min: 0, max: 250, divisions: 50,
              onChanged: (v) => refresh(() => visitFee = v))), Text(_money(visitFee))]),
            Row(children: [const Text('Bütçe'), Expanded(child: Slider(
              value: budget, min: 0, max: 20000, divisions: 200,
              onChanged: (v) => refresh(() => budget = v))), Text(_money(budget))]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('İhtiyaç: ${demand.length} • Fiyatı bulunan: $allPriced • Planlanan: ${bestAssignments.length}'),
              Text('Seçilen marketler: ${bestStores.isEmpty ? 'Yok' : bestStores.join(', ')}'),
              Text('Ürün toplamı: ${_money(bestAssignments.fold<double>(0, (sum, r) => sum + (r['cost'] as double)))}'),
              Text('Ziyaret maliyeti: ${_money(bestStores.length * visitFee)}'),
              Text('Toplam: ${bestTotal.isFinite ? _money(bestTotal) : 'Hesaplanamadı'}'),
              Text('Bütçe farkı: ${bestTotal.isFinite ? _money(budget - bestTotal) : 'Bilinmiyor'}'),
              if (missing.isNotEmpty) Text('${missing.length} ürün bu market kombinasyonunda fiyatlandırılamadı.',
                style: const TextStyle(color: Colors.deepOrange)),
              if (rankedStores.length > 12) const Text('Hesaplama en fazla 12 market üzerinden yapılır; diğer marketler değerlendirme dışındadır.'),
              const Text('Öncelik: Önce en fazla ürün kapsamı, ardından en düşük maliyet.'),
            ]))),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Ürün veya market ara'),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca karşılanamayan ürünler'), value: showOnlyMissing,
              onChanged: (v) => refresh(() => showOnlyMissing = v)),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Market;Ürün;Miktar;Birim;Birim fiyat;Toplam'];
              for (final r in filtered) {
                lines.add([r['store'], r['name'], r['amount'], r['unit'], r['rate'], r['cost']].map(csv).join(';'));
              }
              for (final e in filteredMissing) {
                lines.add(['FİYAT EKSİK', e.value['name'], e.value['amount'], e.value['unit'], '', ''].map(csv).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
              _notice('Market dağılım raporu kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Market bazlı listeyi CSV kopyala')),
            if (!showOnlyMissing) ...assignmentsByStore.entries.map((entry) => Card(child: ExpansionTile(
              initiallyExpanded: true,
              title: Text('${entry.key} • ${entry.value.length} ürün'),
              subtitle: Text(_money(entry.value.fold<double>(0, (sum, r) => sum + (r['cost'] as double)) + visitFee)),
              children: entry.value.where((r) => filtered.contains(r)).map((r) => ListTile(dense: true,
                title: Text('${r['name']} • ${r['amount']} ${r['unit']}'),
                trailing: Text(_money(r['cost'] as double)))).toList(),
            ))),
            if (filteredMissing.isNotEmpty) const Text('Fiyatı bulunamayan / seçili marketlerde olmayan ürünler',
              style: TextStyle(fontWeight: FontWeight.bold)),
            ...filteredMissing.map((e) => ListTile(dense: true,
              leading: const Icon(Icons.warning_amber_outlined),
              title: Text(e.value['name'].toString()),
              subtitle: Text('${e.value['amount']} ${e.value['unit']}'))),
          ])));
      }),
    );
  }


  // Aşama 11148–11397: Market bazlı satın alma gerçekleşme takibi.
  // Oturumlar ilgili kayıtlı listenin içinde saklanır; eski şema korunur.
  void _showKitchenMarketPurchaseTracker() {
    if (_namedLists.isEmpty) {
      _notice('Önce Kayıtlı Listeler bölümünde bir alışveriş listesi oluşturun.');
      return;
    }
    var listIndex = 0;
    var query = '';
    var onlyPending = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final record = _namedLists[listIndex];
        final names = (record['items'] as List? ?? const []).map((e) => e.toString()).toList();
        final raw = record['marketPurchases'];
        final purchases = raw is Map ? Map<String, dynamic>.from(raw) : <String, dynamic>{};
        final visible = names.where((name) =>
          name.toLowerCase().contains(query.toLowerCase()) &&
          (!onlyPending || !purchases.containsKey(name))).toList();
        var planned = 0.0;
        var actual = 0.0;
        var paidCount = 0;
        final byStore = <String, double>{};
        for (final name in names) {
          planned += _namedItemTotal(record, name);
          final purchase = purchases[name];
          if (purchase is! Map) continue;
          paidCount++;
          final cost = _planNum(purchase['total']);
          if (cost.isFinite && cost >= 0) {
            actual += cost;
            final store = (purchase['store'] ?? 'Market belirtilmedi').toString();
            byStore[store] = (byStore[store] ?? 0) + cost;
          }
        }
        String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Market bazlı satın alma takibi', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Satın alınan miktar, gerçek tutar ve market bilgisi kaydedilir. Stoklar otomatik değiştirilmez.'),
            DropdownButtonFormField<int>(initialValue: listIndex, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Kayıtlı alışveriş listesi'),
              items: List.generate(_namedLists.length, (i) => DropdownMenuItem(
                value: i, child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(),
                  overflow: TextOverflow.ellipsis))),
              onChanged: (v) { if (v != null) refresh(() { listIndex = v; query = ''; }); }),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Satın alınan: $paidCount / ${names.length} ürün'),
                LinearProgressIndicator(value: names.isEmpty ? 0 : paidCount / names.length),
                Text('Planlanan liste maliyeti: ${_money(planned)}'),
                Text('Gerçekleşen (alınan ürünler): ${_money(actual)}'),
                Text('Kalan ürün: ${names.length - paidCount}'),
                const Text('Not: Planlanan toplam tüm listeye, gerçekleşen tutar yalnızca alınan ürünlere aittir.'),
              ]))),
            if (byStore.isNotEmpty) ...[
              const Text('Marketlere göre gerçekleşen harcama', style: TextStyle(fontWeight: FontWeight.bold)),
              ...byStore.entries.map((e) => ListTile(dense: true,
                title: Text(e.key), trailing: Text(_money(e.value)))),
            ],
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün ara'), onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca alınmayanlar'), value: onlyPending,
              onChanged: (v) => refresh(() => onlyPending = v)),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Ürün;Planlanan miktar;Birim;Planlanan tutar;Durum;Alınan miktar;Market;Gerçek tutar;Tarih'];
              for (final name in visible) {
                final q = _namedQuantity(record, name);
                final p = purchases[name];
                final purchase = p is Map ? p : <String, dynamic>{};
                lines.add([name, q['amount'], q['unit'], _namedItemTotal(record, name),
                  p is Map ? 'Alındı' : 'Bekliyor', purchase['quantity'], purchase['store'],
                  purchase['total'], purchase['at']].map(csv).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
              _notice('Satın alma raporu CSV olarak kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Görünen kayıtları CSV kopyala')),
            ...visible.map((name) {
              final q = _namedQuantity(record, name);
              final p = purchases[name];
              final purchased = p is Map;
              return Card(child: ListTile(
                leading: Icon(purchased ? Icons.check_circle : Icons.shopping_basket_outlined,
                  color: purchased ? Colors.green : _purple),
                title: Text(name),
                subtitle: Text(purchased
                  ? '${p['quantity']} ${q['unit']} • ${p['store']} • ${_money(_planNum(p['total']))}\n${p['at']}'
                  : 'Plan: ${q['amount']} ${q['unit']} • ${_money(_namedItemTotal(record, name))}'),
                trailing: const Icon(Icons.edit_outlined),
                onTap: () async {
                  final current = purchases[name];
                  final old = current is Map ? current : <String, dynamic>{};
                  if (old['stockTransferred'] == true) {
                    _notice('Stoğa aktarılmış satın alma kaydı değiştirilemez. Stok düzeltmesi için hareket geçmişini kullanın.');
                    return;
                  }
                  final amountController = TextEditingController(text:
                    (old['quantity'] ?? q['amount'] ?? 1).toString());
                  final storeController = TextEditingController(text:
                    (old['store'] ?? _namedProductMeta(record, name)['store'] ?? '').toString());
                  final costController = TextEditingController(text:
                    (old['total'] ?? _namedItemTotal(record, name)).toString());
                  final action = await showDialog<String>(context: ctx, builder: (dialog) => AlertDialog(
                    title: Text('$name • Satın alma'),
                    content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
                      TextField(controller: amountController, keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        decoration: InputDecoration(labelText: 'Alınan miktar (${q['unit']})')),
                      TextField(controller: storeController, maxLength: 80,
                        decoration: const InputDecoration(labelText: 'Market')),
                      TextField(controller: costController, keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        decoration: const InputDecoration(labelText: 'Gerçek toplam tutar (TL)')),
                    ])),
                    actions: [
                      TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Vazgeç')),
                      if (purchased) TextButton(onPressed: () => Navigator.pop(dialog, 'remove'),
                        child: const Text('Alındı işaretini kaldır')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, 'save'), child: const Text('Kaydet')),
                    ],
                  ));
                  if (!ctx.mounted) { disposeAfterDialog(amountController); disposeAfterDialog(storeController); disposeAfterDialog(costController); return; }
                  if (action == 'remove') {
                    final confirmed = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                      title: const Text('Satın alma kaydını kaldır'),
                      content: Text('$name için gerçekleşen alışveriş bilgisi silinecek. Stok etkilenmez.'),
                      actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Kaldır'))]));
                    if (confirmed == true && mounted) {
                      refresh(() { purchases.remove(name); record['marketPurchases'] = purchases; });
                      await _save();
                    }
                  } else if (action == 'save') {
                    final amount = double.tryParse(amountController.text.trim().replaceAll(',', '.'));
                    final cost = double.tryParse(costController.text.trim().replaceAll(',', '.'));
                    final store = storeController.text.trim();
                    if (amount == null || !amount.isFinite || amount <= 0 ||
                        cost == null || !cost.isFinite || cost < 0 || store.isEmpty) {
                      _notice('Geçerli miktar, market ve negatif olmayan tutar girin.');
                    } else {
                      refresh(() {
                        purchases[name] = <String, dynamic>{'quantity': amount, 'store': store,
                          'total': cost, 'at': DateTime.now().toIso8601String()};
                        record['marketPurchases'] = purchases;
                      });
                      await _save();
                      _notice('$name satın alma kaydı güncellendi.');
                    }
                  }
                  disposeAfterDialog(amountController); disposeAfterDialog(storeController); disposeAfterDialog(costController);
                },
              ));
            }),
          ])));
      }),
    );
  }

  // Aşama 11398–11647: Gerçek satın almayı stoğa kontrollü aktarma.
  // İşlem işareti satın alma kaydında tutulur; tekrar aktarım engellenir.
  void _showKitchenActualPurchaseStockTransfer() {
    if (_namedLists.isEmpty) { _notice('Önce kayıtlı bir liste oluşturun.'); return; }
    var sourceIndex = 0;
    var targetIndex = 0;
    var onlyReady = false;
    var query = '';
    final selected = <String>{};
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final source = _namedLists[sourceIndex];
        final target = _namedLists[targetIndex];
        final sourceNames = (source['items'] as List? ?? const []).map((e) => e.toString()).toList();
        final targetNames = (target['items'] as List? ?? const []).map((e) => e.toString()).toSet();
        final raw = source['marketPurchases'];
        final purchases = raw is Map ? Map<String, dynamic>.from(raw) : <String, dynamic>{};
        String? issue(String name) {
          final p = purchases[name];
          if (p is! Map) return 'Satın alma kaydı yok';
          if (p['stockTransferred'] == true) return 'Daha önce stoğa aktarıldı';
          if (!targetNames.contains(name)) return 'Hedef stok listesinde ürün yok';
          final quantity = _planNum(p['quantity']);
          if (!quantity.isFinite || quantity <= 0) return 'Geçersiz alınan miktar';
          final unit = _namedQuantity(source, name)['unit']?.toString().toLowerCase().trim() ?? '';
          final targetUnit = _namedQuantity(target, name)['unit']?.toString().toLowerCase().trim() ?? '';
          if (unit != targetUnit) return 'Birim uyuşmuyor ($unit / $targetUnit)';
          final stock = _namedStock(target, name);
          if (stock['amount']!.trim().isEmpty) return 'Hedef stok miktarı tanımsız';
          final before = double.tryParse(stock['amount']!.replaceAll(',', '.'));
          if (before == null || !before.isFinite || before < 0) return 'Hedef stok geçersiz';
          if (!(before + quantity).isFinite) return 'Stok miktarı çok büyük';
          return null;
        }
        final eligible = sourceNames.where((name) => issue(name) == null).toList();
        final visible = sourceNames.where((name) =>
          name.toLowerCase().contains(query.toLowerCase()) && (!onlyReady || issue(name) == null)).toList();
        final selectedReady = eligible.where(selected.contains).toList();
        final purchased = sourceNames.where((n) => purchases[n] is Map).toList();
        final transferred = purchased.where((n) => (purchases[n] as Map)['stockTransferred'] == true).toList();
        final totalPaid = purchased.fold<double>(0, (v, n) => v + _planNum((purchases[n] as Map)['total']));
        final transferredPaid = transferred.fold<double>(0, (v, n) => v + _planNum((purchases[n] as Map)['total']));
        String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: ListView(
          padding: const EdgeInsets.all(16), children: [
          const Text('Gerçek alışveriş → stok aktarımı', style: TextStyle(fontSize: 20,
            fontWeight: FontWeight.bold, color: _purple)),
          const Text('Satın alınan gerçek miktar kullanılır. Aktarılan kayıt tekrar aktarılamaz.'),
          DropdownButtonFormField<int>(initialValue: sourceIndex, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Satın alma listesi'),
            items: List.generate(_namedLists.length, (i) => DropdownMenuItem(value: i,
              child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis))),
            onChanged: (v) { if (v != null) refresh(() { sourceIndex = v; selected.clear(); }); }),
          DropdownButtonFormField<int>(initialValue: targetIndex, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Hedef stok listesi'),
            items: List.generate(_namedLists.length, (i) => DropdownMenuItem(value: i,
              child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis))),
            onChanged: (v) { if (v != null) refresh(() { targetIndex = v; selected.clear(); }); }),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('Satın alınan: ${purchased.length} • Aktarılan: ${transferred.length} • Aktarılabilir: ${eligible.length}'),
              Text('Gerçek harcama: ${_money(totalPaid)} • Stoğa aktarılan alımlar: ${_money(transferredPaid)}'),
              Text('Seçili aktarılabilir ürün: ${selectedReady.length}'),
            ]))),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
            labelText: 'Ürün ara'), onChanged: (v) => refresh(() => query = v)),
          SwitchListTile(title: const Text('Yalnızca aktarılabilir ürünler'), value: onlyReady,
            onChanged: (v) => refresh(() => onlyReady = v)),
          Wrap(spacing: 8, children: [
            OutlinedButton(onPressed: () => refresh(() => selected.addAll(visible.where((n) => issue(n) == null))),
              child: const Text('Uygunları seç')),
            OutlinedButton(onPressed: () => refresh(selected.clear), child: const Text('Seçimi temizle')),
            OutlinedButton.icon(icon: const Icon(Icons.copy), label: const Text('CSV kopyala'), onPressed: () async {
              final lines = <String>['Ürün;Alınan miktar;Birim;Market;Gerçek tutar;Durum;Aktarım tarihi;Hedef liste'];
              for (final n in visible) {
                final p = purchases[n];
                final m = p is Map ? p : <String, dynamic>{};
                lines.add([n, m['quantity'], _namedQuantity(source, n)['unit'], m['store'],
                  m['total'], issue(n) ?? 'Aktarılabilir', m['stockTransferredAt'],
                  m['stockTargetList']].map(csv).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
              _notice('Stok aktarım raporu kopyalandı.');
            }),
          ]),
          ...visible.map((name) {
            final p = purchases[name];
            final m = p is Map ? p : <String, dynamic>{};
            final problem = issue(name);
            return CheckboxListTile(value: selected.contains(name) && problem == null,
              onChanged: problem == null ? (v) => refresh(() {
                if (v == true) { selected.add(name); } else { selected.remove(name); }
              }) : null,
              title: Text(name),
              subtitle: Text(p is Map
                ? '${m['quantity']} ${_namedQuantity(source, name)['unit']} • ${m['store']} • ${_money(_planNum(m['total']))}\n${problem ?? 'Aktarıma hazır'}'
                : problem ?? 'Kayıt yok'),
              secondary: Icon(problem == null ? Icons.inventory_2_outlined : Icons.info_outline,
                color: problem == null ? Colors.green : Colors.orange));
          }),
          FilledButton.icon(icon: const Icon(Icons.move_to_inbox_outlined),
            label: Text('Seçilen ${selectedReady.length} ürünü stoğa aktar'),
            onPressed: selectedReady.isEmpty ? null : () async {
              final names = selectedReady.toList();
              final ok = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                title: const Text('Gerçek satın almaları stoğa aktar'),
                content: Text('${names.length} ürünün alınan miktarı hedef stoklara eklenecek. '
                  'Stok hareketi ve aktarım bilgisi kaydedilecek. İşlem tekrar uygulanamaz.'),
                actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
                  FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Aktar'))]));
              if (ok != true || !mounted || !ctx.mounted) return;
              // Onaydan sonra her satır yeniden doğrulanır.
              final safe = names.where((n) => issue(n) == null).toList();
              if (safe.length != names.length) { _notice('Bazı kayıtlar değişti. Tekrar seçim yapın.'); refresh(() {}); return; }
              final now = DateTime.now().toIso8601String();
              setState(() {
                for (final name in safe) {
                  final p = Map<String, dynamic>.from(purchases[name] as Map);
                  final quantity = _planNum(p['quantity']);
                  final stock = _namedStock(target, name);
                  final before = double.parse(stock['amount']!.replaceAll(',', '.'));
                  final after = before + quantity;
                  final meta = target['stockMeta'] is Map
                    ? Map<String, dynamic>.from(target['stockMeta'] as Map) : <String, dynamic>{};
                  meta[name] = {...stock, 'amount': after.toString(), 'updated': now};
                  target['stockMeta'] = meta;
                  _recordStockMovement(target, name, before, after, 'Gerçek satın alma aktarımı: ${p['store']}');
                  p['stockTransferred'] = true;
                  p['stockTransferredAt'] = now;
                  p['stockTargetList'] = (target['title'] ?? 'Adsız liste').toString();
                  p['stockTransferredQuantity'] = quantity;
                  purchases[name] = p;
                }
                source['marketPurchases'] = purchases;
                source['updated'] = now;
                target['updated'] = now;
              });
              refresh(() => selected.clear());
              await _save();
              _notice('${safe.length} ürün stoğa aktarıldı.');
            }),
        ])));
      }));
  }


  // Aşama 11648–11897: Gerçekleşen alışverişlerden harcama analitiği.
  // Salt okunur: var olan marketPurchases kayıtları ve anahtarları korunur.

  // Aylık satın alma bütçesi: yalnızca kayıtlı gerçek alımlar ve mevcut
  // aylık bütçe anahtarı kullanılır; geçmiş kayıtları değiştirmez.

  // Kayıtlı fiyatlarla çalışan, veri değiştirmeyen tasarruf planlayıcısı.
  void _showKitchenSavingsAssistant() {
    var selectedList = -1;
    var budget = _monthlyBudgets[_monthKey()] ?? 1500.0;
    var reserve = 0.0;
    var onlySavings = false;
    var onlyAffordable = false;
    var search = '';
    var sort = 'Öncelik';
    final deferred = <String>{};
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final names = selectedList < 0 ? _items.toList() :
          (_namedLists[selectedList]['items'] as List? ?? const []).map((e) => e.toString()).toList();
        final source = selectedList < 0 ? null : _namedLists[selectedList];
        final offers = <String, List<Map<String, dynamic>>>{};
        for (final list in _namedLists) {
          final marketName = (list['title'] ?? 'Kayıtlı liste').toString();
          for (final raw in (list['items'] as List? ?? const [])) {
            final name = raw.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final qty = _planNum(q['amount']);
            final cost = _namedItemTotal(list, name);
            final store = (_namedProductMeta(list, name)['store'] ?? '').toString().trim();
            if (store.isEmpty || qty <= 0 || !qty.isFinite || cost <= 0 || !cost.isFinite) continue;
            final key = '${name.toLowerCase()}|$unit';
            offers.putIfAbsent(key, () => []).add({
              'store': store, 'price': cost / qty, 'source': marketName,
            });
          }
        }
        final rows = <Map<String, dynamic>>[];
        for (final name in names.toSet()) {
          if (name.trim().isEmpty) continue;
          final q = source == null ? <String, dynamic>{'amount': 1, 'unit': 'adet'} : _namedQuantity(source, name);
          final qty = _planNum(q['amount']);
          final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
          final matches = offers['${name.toLowerCase()}|$unit'] ?? const <Map<String, dynamic>>[];
          final prices = matches.where((m) => (m['price'] as double).isFinite && (m['price'] as double) > 0).toList()
            ..sort((a,b) => (a['price'] as double).compareTo(b['price'] as double));
          final best = prices.isEmpty ? 0.0 : prices.first['price'] as double;
          final current = source == null ? 0.0 : _namedItemTotal(source, name);
          final estimated = qty > 0 && best > 0 ? qty * best : 0.0;
          final saving = current > estimated && estimated > 0 ? current - estimated : 0.0;
          rows.add({'name': name, 'qty': qty, 'unit': unit, 'best': estimated,
            'current': current, 'saving': saving, 'store': prices.isEmpty ? 'Fiyat yok' : prices.first['store'],
            'alternatives': prices.length, 'priced': estimated > 0,
            'deferred': deferred.contains(name)});
        }
        final priced = rows.where((r) => r['priced'] == true && r['deferred'] != true).toList();
        final unpriced = rows.where((r) => r['priced'] != true && r['deferred'] != true).length;
        final baseline = priced.fold<double>(0, (a,r) => a + ((r['current'] as double) > 0 ? r['current'] as double : r['best'] as double));
        final cheapest = priced.fold<double>(0, (a,r) => a + (r['best'] as double));
        final savingTotal = priced.fold<double>(0, (a,r) => a + (r['saving'] as double));
        final available = (budget - reserve).clamp(0.0, double.infinity).toDouble();
        final ranked = priced.toList()..sort((a,b) {
          if (sort == 'Fiyat') return (a['best'] as double).compareTo(b['best'] as double);
          if (sort == 'Tasarruf') return (b['saving'] as double).compareTo(a['saving'] as double);
          return (a['name'] as String).compareTo(b['name'] as String);
        });
        var used = 0.0;
        final affordable = <String>{};
        for (final r in ranked) {
          final cost = r['best'] as double;
          if (used + cost <= available + 0.00001) {
            used += cost;
            affordable.add(r['name'] as String);
          }
        }
        final filtered = rows.where((r) =>
          (r['name'] as String).toLowerCase().contains(search.toLowerCase()) &&
          (!onlySavings || (r['saving'] as double) > 0) &&
          (!onlyAffordable || affordable.contains(r['name']))).toList();
        filtered.sort((a,b) {
          if (sort == 'Fiyat') return (a['best'] as double).compareTo(b['best'] as double);
          if (sort == 'Tasarruf') return (b['saving'] as double).compareTo(a['saving'] as double);
          return (a['name'] as String).compareTo(b['name'] as String);
        });
        String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı tasarruf ve bütçe asistanı', style: TextStyle(fontSize: 20,
              fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı fiyatlardan senaryo üretir; stokları, fiyatları ve alışveriş kayıtlarını değiştirmez.'),
            DropdownButtonFormField<int>(initialValue: selectedList, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Planlanacak alışveriş listesi'),
              items: [const DropdownMenuItem(value: -1, child: Text('Aktif alışveriş listesi')),
                ...List.generate(_namedLists.length, (i) => DropdownMenuItem(value: i,
                  child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis)))],
              onChanged: (v) { if (v != null) refresh(() { selectedList = v; deferred.clear(); }); }),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(child: OutlinedButton.icon(icon: const Icon(Icons.payments_outlined),
                label: Text('Bütçe: ${_money(budget)}'), onPressed: () async {
                  final value = await _planText('Alışveriş bütçesi (TL)', budget.toStringAsFixed(2));
                  if (value == null) return;
                  final parsed = double.tryParse(value.replaceAll(',', '.'));
                  if (parsed == null || !parsed.isFinite || parsed < 0) { _notice('Geçerli bir bütçe girin.'); return; }
                  refresh(() => budget = parsed);
                })),
              const SizedBox(width: 8),
              Expanded(child: OutlinedButton.icon(icon: const Icon(Icons.savings_outlined),
                label: Text('Ayrılan pay: ${_money(reserve)}'), onPressed: () async {
                  final value = await _planText('Dokunulmayacak bütçe payı (TL)', reserve.toStringAsFixed(2));
                  if (value == null) return;
                  final parsed = double.tryParse(value.replaceAll(',', '.'));
                  if (parsed == null || !parsed.isFinite || parsed < 0) { _notice('Geçerli bir tutar girin.'); return; }
                  refresh(() => reserve = parsed);
                })),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Kullanılabilir bütçe: ${_money(available)}'),
                Text('Kayıtlı fiyatlarla en düşük sepet: ${_money(cheapest)}'),
                Text('Referans sepet: ${_money(baseline)}'),
                Text('Mevcut kayıtlı fiyata göre potansiyel tasarruf: ${_money(savingTotal)}'),
                Text('Bütçe farkı: ${_money(available - cheapest)}'),
                Text('Bütçeye sığan ürün: ${affordable.length} / ${priced.length}'),
                Text('Fiyatı bilinmeyen: $unpriced • Ertelenen: ${deferred.length}'),
                if (cheapest > available) const Text('Bütçe yetersiz: fiyatlı ürünlerin tamamı karşılanamıyor.'),
                if (unpriced > 0) const Text('Uyarı: fiyatı bilinmeyen ürünler toplama dahil değildir.'),
                const Text('Market ulaşımı, paket boyutu ve canlı fiyatlar hesaplamaya dahil değildir.'),
              ]))),
            TextField(decoration: const InputDecoration(labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => search = v)),
            DropdownButtonFormField<String>(initialValue: sort,
              decoration: const InputDecoration(labelText: 'Sıralama'),
              items: ['Öncelik','Fiyat','Tasarruf'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) { if (v != null) refresh(() => sort = v); }),
            SwitchListTile(title: const Text('Yalnızca tasarruf fırsatları'), value: onlySavings,
              onChanged: (v) => refresh(() => onlySavings = v)),
            SwitchListTile(title: const Text('Yalnızca bütçeye sığan ürünler'), value: onlyAffordable,
              onChanged: (v) => refresh(() => onlyAffordable = v)),
            Wrap(spacing: 8, children: [
              OutlinedButton.icon(icon: const Icon(Icons.copy_outlined), label: const Text('Planı CSV kopyala'),
                onPressed: () {
                  final lines = <String>['Ürün,Miktar,Birim,Referans TL,En düşük TL,Tasarruf TL,Market,Fiyat sayısı,Karar'];
                  for (final r in filtered) {
                    lines.add([r['name'],r['qty'],r['unit'],r['current'],r['best'],r['saving'],
                      r['store'],r['alternatives'],r['deferred'] == true ? 'Ertelendi' :
                      affordable.contains(r['name']) ? 'Bütçede' : 'Bütçe dışı'].map(csv).join(','));
                  }
                  Clipboard.setData(ClipboardData(text: lines.join('\n')));
                  _notice('Tasarruf planı CSV olarak kopyalandı.');
                }),
              TextButton(onPressed: () => refresh(() => deferred.clear()),
                child: const Text('Ertelemeleri temizle')),
            ]),
            ...filtered.map((r) => Card(child: ListTile(
              title: Text(r['name'] as String),
              subtitle: Text('${r['qty']} ${r['unit']} • En uygun kayıt: ${r['store']}\n'
                'En düşük: ${_money(r['best'] as double)} • Tasarruf: ${_money(r['saving'] as double)}\n'
                '${r['alternatives']} fiyat referansı • ${r['deferred'] == true ? 'Ertelendi' : affordable.contains(r['name']) ? 'Bütçede' : 'Bütçe dışında / fiyat yok'}'),
              isThreeLine: true,
              trailing: IconButton(tooltip: r['deferred'] == true ? 'Ertelemeyi kaldır' : 'Bu ürünü ertele',
                icon: Icon(r['deferred'] == true ? Icons.undo : Icons.schedule_outlined),
                onPressed: () => refresh(() { if (!deferred.add(r['name'] as String)) deferred.remove(r['name']); })),
            ))),
            if (filtered.isEmpty) const Text('Bu filtrelerde ürün bulunamadı.'),
          ])));
      }));
  }

  // Tasarruf senaryolari: ayri bir tercih kaydinda saklanir; kaynak listeler salt okunurdur.
  Future<void> _showKitchenSavingsScenarios() async {
    const storageKey = 'kitchen_savings_scenarios_v1';
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    final saved = <Map<String, dynamic>>[];
    try {
      final decoded = jsonDecode(prefs.getString(storageKey) ?? '[]');
      if (decoded is List) {
        saved.addAll(decoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
      }
    } catch (_) { _notice('Kayıtlı tasarruf senaryoları okunamadı.'); }
    var selected = -1;
    var budget = _monthlyBudgets[_monthKey()] ?? 1500.0;
    var reserve = 0.0;
    var search = '';
    var view = 'Tümü';
    final priorities = <String, String>{};
    final excluded = <String>{};
    final scenarioBudgets = <double>[.8, 1.0, 1.2];
    String keyFor(String name, String unit) => '${name.trim().toLowerCase()}|${unit.trim().toLowerCase()}';
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    Future<void> persist() async {
      final ok = await prefs.setString(storageKey, jsonEncode(saved));
      _notice(ok ? 'Tasarruf senaryoları kaydedildi.' : 'Senaryolar kaydedilemedi.');
    }
    if (!mounted) return;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final source = selected < 0 ? null : _namedLists[selected];
        final names = source == null ? _items.toList() :
          (source['items'] as List? ?? const []).map((e) => e.toString()).toList();
        final offers = <String, List<Map<String, dynamic>>>{};
        for (final list in _namedLists) {
          for (final raw in (list['items'] as List? ?? const [])) {
            final name = raw.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final qty = _planNum(q['amount']);
            final unit = (q['unit'] ?? 'adet').toString();
            final price = _namedItemTotal(list, name);
            final store = (_namedProductMeta(list, name)['store'] ?? '').toString().trim();
            if (store.isEmpty || qty <= 0 || !qty.isFinite || price <= 0 || !price.isFinite) continue;
            offers.putIfAbsent(keyFor(name, unit), () => []).add({
              'store': store, 'unitPrice': price / qty,
            });
          }
        }
        final rows = <Map<String, dynamic>>[];
        final seen = <String>{};
        for (final name in names) {
          final q = source == null ? (_details[name] ?? <String, dynamic>{}) : _namedQuantity(source, name);
          final qty = _planNum(q['amount']) > 0 ? _planNum(q['amount']) : 1.0;
          final unit = (q['unit'] ?? 'adet').toString();
          final id = keyFor(name, unit);
          if (!seen.add(id)) continue;
          final candidates = (offers[id] ?? <Map<String, dynamic>>[]).toList()
            ..sort((a, b) => (a['unitPrice'] as double).compareTo(b['unitPrice'] as double));
          final cheapest = candidates.isEmpty ? 0.0 : (candidates.first['unitPrice'] as double) * qty;
          rows.add({'id': id, 'name': name, 'qty': qty, 'unit': unit,
            'cost': cheapest, 'store': candidates.isEmpty ? 'Fiyat bulunamadı' : candidates.first['store'],
            'offers': candidates.length, 'priority': priorities[id] ?? 'Normal',
            'excluded': excluded.contains(id)});
        }
        final active = rows.where((r) => r['excluded'] != true).toList();
        final known = active.where((r) => (r['cost'] as double) > 0).toList();
        final unknown = active.length - known.length;
        final total = known.fold<double>(0, (a, r) => a + (r['cost'] as double));
        final available = (budget - reserve).clamp(0.0, double.infinity).toDouble();
        final ranked = known.toList()..sort((a,b) {
          const ranks = {'Zorunlu': 0, 'Normal': 1, 'Ertelenebilir': 2};
          final c = (ranks[a['priority']] ?? 1).compareTo(ranks[b['priority']] ?? 1);
          if (c != 0) return c;
          return (a['cost'] as double).compareTo(b['cost'] as double);
        });
        List<String> fit(double limit) {
          var used = 0.0;
          final selectedIds = <String>[];
          for (final r in ranked) {
            final cost = r['cost'] as double;
            if (used + cost <= limit + .00001) { used += cost; selectedIds.add(r['id'] as String); }
          }
          return selectedIds;
        }
        final fitted = fit(available).toSet();
        final visible = rows.where((r) =>
          (r['name'] as String).toLowerCase().contains(search.toLowerCase()) &&
          (view == 'Tümü' || (view == 'Bütçede' && fitted.contains(r['id'])) ||
           (view == 'Bütçe dışında' && !fitted.contains(r['id'])) ||
           (view == 'Fiyatı bilinmeyen' && (r['cost'] as double) <= 0) ||
           (view == 'Ertelenen' && r['excluded'] == true))).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Tasarruf senaryoları ve alışveriş öncelikleri',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı market fiyatlarına dayalı planlama. Kaynak alışveriş ve stok kayıtları değiştirilmez.'),
            DropdownButtonFormField<int>(initialValue: selected, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Alışveriş listesi'),
              items: [const DropdownMenuItem(value: -1, child: Text('Aktif liste')),
                ...List.generate(_namedLists.length, (i) => DropdownMenuItem(value: i,
                  child: Text((_namedLists[i]['title'] ?? 'Adsız liste').toString(), overflow: TextOverflow.ellipsis)))],
              onChanged: (v) { if (v != null) refresh(() { selected = v; priorities.clear(); excluded.clear(); }); }),
            Wrap(spacing: 8, children: [
              OutlinedButton(onPressed: () async {
                final v = await _planText('Alışveriş bütçesi (TL)', budget.toStringAsFixed(2));
                final n = double.tryParse((v ?? '').replaceAll(',', '.'));
                if (n == null || !n.isFinite || n < 0) { if (v != null) _notice('Geçerli bütçe girin.'); return; }
                refresh(() => budget = n);
              }, child: Text('Bütçe: ${_money(budget)}')),
              OutlinedButton(onPressed: () async {
                final v = await _planText('Ayrılacak bütçe (TL)', reserve.toStringAsFixed(2));
                final n = double.tryParse((v ?? '').replaceAll(',', '.'));
                if (n == null || !n.isFinite || n < 0) { if (v != null) _notice('Geçerli tutar girin.'); return; }
                refresh(() => reserve = n);
              }, child: Text('Korunan pay: ${_money(reserve)}')),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Kullanılabilir: ${_money(available)} • En düşük fiyatlı sepet: ${_money(total)}'),
                Text('Bütçe farkı: ${_money(available - total)}'),
                Text('Bütçeye sığan: ${fitted.length}/${known.length} • Fiyatı bilinmeyen: $unknown'),
                Text('Ertelenen: ${excluded.length} • Zorunlu: ${active.where((r) => r['priority'] == 'Zorunlu').length}'),
                if (unknown > 0) const Text('Fiyatı bilinmeyen ürünler maliyet ve bütçe hesabına dahil değildir.'),
                if (total > available) const Text('Uyarı: tüm fiyatlı ürünler bütçeye sığmıyor.'),
              ]))),
            const Text('Bütçe senaryoları', style: TextStyle(fontWeight: FontWeight.bold)),
            ...scenarioBudgets.map((factor) {
              final limit = available * factor;
              final selectedIds = fit(limit);
              final spend = known.where((r) => selectedIds.contains(r['id']))
                .fold<double>(0, (a,r) => a + (r['cost'] as double));
              return ListTile(dense: true, title: Text('Bütçenin %${(factor * 100).round()} kadarı'),
                subtitle: Text('${selectedIds.length} ürün • Harcama ${_money(spend)} • Kalan ${_money(limit - spend)}'));
            }),
            Wrap(spacing: 8, children: [
              FilledButton.tonalIcon(icon: const Icon(Icons.save_outlined),
                label: const Text('Senaryoyu kaydet'), onPressed: () async {
                  final title = await _planText('Senaryo adı', 'Tasarruf planım');
                  if (title == null || title.trim().isEmpty) return;
                  final record = <String, dynamic>{
                    'id': DateTime.now().microsecondsSinceEpoch.toString(),
                    'title': title.trim(), 'createdAt': DateTime.now().toIso8601String(),
                    'source': selected < 0 ? 'Aktif liste' : (_namedLists[selected]['title'] ?? 'Adsız liste').toString(),
                    'budget': budget, 'reserve': reserve,
                    'priorities': Map<String, String>.from(priorities), 'excluded': excluded.toList(),
                    'items': rows.map((r) => {'name': r['name'], 'unit': r['unit'], 'qty': r['qty'],
                      'cost': r['cost'], 'store': r['store'], 'priority': r['priority'],
                      'excluded': r['excluded']}).toList(),
                  };
                  refresh(() => saved.insert(0, record));
                  await persist();
                }),
              OutlinedButton.icon(icon: const Icon(Icons.copy_outlined),
                label: const Text('CSV kopyala'), onPressed: () {
                  final lines = <String>['Ürün,Miktar,Birim,Öncelik,En düşük TL,Market,Karar'];
                  for (final r in visible) {
                    lines.add([r['name'], r['qty'], r['unit'], r['priority'], r['cost'], r['store'],
                      r['excluded'] == true ? 'Ertelendi' : fitted.contains(r['id']) ? 'Bütçede' : 'Bütçe dışında']
                      .map(csv).join(','));
                  }
                  Clipboard.setData(ClipboardData(text: lines.join('\n')));
                  _notice('Senaryo CSV kopyalandı.');
                }),
            ]),
            const Text('Kaydedilen senaryolar', style: TextStyle(fontWeight: FontWeight.bold)),
            ...saved.map((record) => Card(child: ListTile(
              title: Text((record['title'] ?? 'Senaryo').toString()),
              subtitle: Text('${record['source'] ?? ''} • ${_money(_planNum(record['budget']))} • ${record['createdAt'] ?? ''}'),
              onTap: () {
                final sourceName = (record['source'] ?? '').toString();
                final idx = _namedLists.indexWhere((e) => (e['title'] ?? '').toString() == sourceName);
                final p = record['priorities'];
                refresh(() {
                  selected = sourceName == 'Aktif liste' ? -1 : idx;
                  budget = _planNum(record['budget']);
                  reserve = _planNum(record['reserve']);
                  priorities.clear();
                  if (p is Map) { for (final entry in p.entries) { priorities[entry.key.toString()] = entry.value.toString(); } }
                  excluded..clear()..addAll((record['excluded'] as List? ?? const []).map((e) => e.toString()));
                });
                _notice('Senaryo ayarları yüklendi. Fiyatlar güncel kayıtlarla yeniden hesaplandı.');
              },
              trailing: IconButton(tooltip: 'Senaryoyu sil', icon: const Icon(Icons.delete_outline),
                onPressed: () async {
                  final yes = await showDialog<bool>(context: ctx, builder: (dialogCtx) => AlertDialog(
                    title: const Text('Senaryo silinsin mi?'),
                    content: Text((record['title'] ?? '').toString()), actions: [
                      TextButton(onPressed: () => Navigator.pop(dialogCtx, false), child: const Text('Vazgeç')),
                      TextButton(onPressed: () => Navigator.pop(dialogCtx, true), child: const Text('Sil')),
                    ]));
                  if (yes == true) { refresh(() => saved.remove(record)); await persist(); }
                }),
            ))),
            TextField(decoration: const InputDecoration(labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => search = v)),
            DropdownButtonFormField<String>(initialValue: view,
              decoration: const InputDecoration(labelText: 'Görünüm'),
              items: ['Tümü', 'Bütçede', 'Bütçe dışında', 'Fiyatı bilinmeyen', 'Ertelenen']
                .map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) { if (v != null) refresh(() => view = v); }),
            ...visible.map((r) => Card(child: Column(children: [
              ListTile(title: Text(r['name'] as String),
                subtitle: Text('${r['qty']} ${r['unit']} • ${_money(r['cost'] as double)} • ${r['store']}\n'
                  '${r['excluded'] == true ? 'Ertelendi' : fitted.contains(r['id']) ? 'Bütçede' : 'Bütçe dışında'}'),
                trailing: IconButton(tooltip: 'Ertele / geri al',
                  icon: Icon(r['excluded'] == true ? Icons.undo : Icons.schedule),
                  onPressed: () => refresh(() {
                    final id = r['id'] as String;
                    if (!excluded.add(id)) excluded.remove(id);
                  }))),
              Padding(padding: const EdgeInsets.symmetric(horizontal: 16), child: DropdownButtonFormField<String>(
                initialValue: r['priority'] as String,
                decoration: const InputDecoration(labelText: 'Alışveriş önceliği'),
                items: ['Zorunlu','Normal','Ertelenebilir']
                  .map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) { if (v != null) refresh(() => priorities[r['id'] as String] = v); },
              )),
            ]))),
            if (visible.isEmpty) const Text('Bu görünümde ürün yok.'),
            const Text('Not: Fiyatlar geçmiş kayıtlı referanslardır; canlı fiyat değildir. '
              'Bütçe dağıtımı öncelik ve düşük fiyat sırasıyla yapılır, matematiksel optimum garanti edilmez.'),
          ])));
      }));
  }


  Future<void> _showKitchenRecurringShoppingCalendar() async {
    const key = 'kitchen_recurring_shopping_calendar_v1';
    const scenarioKey = 'kitchen_savings_scenarios_v1';
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    final schedules = <Map<String, dynamic>>[];
    final scenarios = <Map<String, dynamic>>[];
    try {
      final data = jsonDecode(prefs.getString(key) ?? '[]');
      if (data is List) schedules.addAll(data.whereType<Map>().map((v) => Map<String, dynamic>.from(v)));
    } catch (_) { _notice('Takvim kayıtları okunamadı.'); }
    try {
      final data = jsonDecode(prefs.getString(scenarioKey) ?? '[]');
      if (data is List) scenarios.addAll(data.whereType<Map>().map((v) => Map<String, dynamic>.from(v)));
    } catch (_) { _notice('Tasarruf planları okunamadı.'); }
    var filter = 'Tümü';
    var query = '';
    var horizon = 30;
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime parseDay(Object? v) => day(DateTime.tryParse((v ?? '').toString()) ?? DateTime.now());
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    DateTime addMonths(DateTime d, int months) {
      final index = d.year * 12 + d.month - 1 + months;
      final year = index ~/ 12;
      final month = index % 12 + 1;
      final last = DateTime(year, month + 1, 0).day;
      return DateTime(year, month, d.day > last ? last : d.day);
    }
    DateTime advance(DateTime d, String period) => period == 'Haftalık'
      ? d.add(const Duration(days: 7)) : period == 'İki haftada bir'
      ? d.add(const Duration(days: 14)) : addMonths(d, 1);
    DateTime nextDate(Map<String, dynamic> rec, DateTime today) {
      var next = parseDay(rec['nextDate']);
      final period = (rec['period'] ?? 'Haftalık').toString();
      var guard = 0;
      while (next.isBefore(today) && guard++ < 2000) {
        final later = advance(next, period);
        if (!later.isAfter(next)) break;
        next = later;
      }
      return next;
    }
    Future<bool> persist() async {
      final ok = await prefs.setString(key, jsonEncode(schedules));
      if (!ok) _notice('Takvim kaydı yazılamadı.');
      return ok;
    }
    Future<void> addSchedule(void Function(void Function()) refresh) async {
      if (scenarios.isEmpty && _namedLists.isEmpty) {
        _notice('Önce bir tasarruf senaryosu veya alışveriş listesi kaydedin.'); return;
      }
      final sources = <Map<String, String>>[
        ...scenarios.map((v) => {'type': 'scenario', 'id': (v['id'] ?? '').toString(), 'title': (v['title'] ?? 'Senaryo').toString()}),
        ..._namedLists.map((v) => {'type': 'list', 'id': (v['id'] ?? '').toString(), 'title': (v['title'] ?? 'Liste').toString()}),
      ];
      var chosen = 0;
      var period = 'Haftalık';
      var date = day(DateTime.now());
      var amount = 0.0;
      final titleCtrl = TextEditingController(text: 'Tekrarlayan alışveriş');
      final saved = await showDialog<bool>(context: context, builder: (dialog) => StatefulBuilder(builder: (ctx, update) => AlertDialog(
        title: const Text('Alışveriş takvimi oluştur'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(controller: titleCtrl, maxLength: 60, decoration: const InputDecoration(labelText: 'Takvim adı')),
          DropdownButtonFormField<int>(initialValue: chosen, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Kaynak plan / liste'),
            items: [for (var i = 0; i < sources.length; i++) DropdownMenuItem(value: i,
              child: Text('${sources[i]['type'] == 'scenario' ? 'Plan' : 'Liste'}: ${sources[i]['title']}', overflow: TextOverflow.ellipsis))],
            onChanged: (v) { if (v != null) update(() => chosen = v); }),
          DropdownButtonFormField<String>(initialValue: period, decoration: const InputDecoration(labelText: 'Tekrar'),
            items: ['Haftalık', 'İki haftada bir', 'Aylık'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
            onChanged: (v) { if (v != null) update(() => period = v); }),
          ListTile(title: const Text('İlk alışveriş günü'), subtitle: Text(fmt(date)),
            trailing: const Icon(Icons.calendar_month), onTap: () async {
              final picked = await showDatePicker(context: ctx, initialDate: date,
                firstDate: DateTime(2020), lastDate: DateTime(2100));
              if (picked != null) update(() => date = picked);
            }),
          TextFormField(initialValue: '0', keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Her alışveriş için bütçe (TL, 0 = sınır yok)'),
            onChanged: (v) => amount = double.tryParse(v.replaceAll(',', '.')) ?? -1),
        ])),
        actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () {
            if (titleCtrl.text.trim().isEmpty || amount < 0 || !amount.isFinite) {
              _notice('Ad ve bütçe bilgilerini kontrol edin.'); return;
            }
            Navigator.pop(ctx, true);
          }, child: const Text('Oluştur'))],
      )));
      final title = titleCtrl.text.trim();
      disposeAfterDialog(titleCtrl);
      if (saved != true || !mounted) return;
      final source = sources[chosen];
      final record = <String, dynamic>{
        'id': DateTime.now().microsecondsSinceEpoch.toString(), 'title': title,
        'sourceType': source['type'], 'sourceId': source['id'], 'sourceTitle': source['title'],
        'period': period, 'nextDate': date.toIso8601String(), 'budget': amount,
        'paused': false, 'createdAt': DateTime.now().toIso8601String(),
        'completedDates': <String>[], 'generatedDates': <String>[],
      };
      refresh(() => schedules.insert(0, record));
      await persist();
    }
    Future<void> generate(Map<String, dynamic> rec, void Function(void Function()) refresh) async {
      final type = (rec['sourceType'] ?? '').toString();
      final sourceId = (rec['sourceId'] ?? '').toString();
      final source = type == 'scenario'
        ? scenarios.where((v) => (v['id'] ?? '').toString() == sourceId).toList()
        : _namedLists.where((v) => (v['id'] ?? '').toString() == sourceId).toList();
      if (source.isEmpty) { _notice('Kaynak plan veya liste bulunamadı.'); return; }
      final targetDate = nextDate(rec, day(DateTime.now()));
      final stamp = targetDate.toIso8601String().substring(0, 10);
      final generated = (rec['generatedDates'] as List? ?? const []).map((e) => e.toString()).toSet();
      if (generated.contains(stamp)) { _notice('Bu tarih için liste zaten oluşturuldu.'); return; }
      final raw = source.first;
      final items = <String>[];
      final details = <String, dynamic>{};
      final prices = <String, dynamic>{};
      if (type == 'scenario') {
        final excluded = (raw['excluded'] as List? ?? const []).map((e) => e.toString()).toSet();
        for (final value in (raw['items'] as List? ?? const [])) {
          if (value is! Map) continue;
          final name = (value['name'] ?? '').toString().trim();
          final unit = (value['unit'] ?? 'adet').toString();
          final id = '${name.toLowerCase()}|${unit.toLowerCase()}';
          if (name.isEmpty || value['excluded'] == true || excluded.contains(id) || items.contains(name)) continue;
          items.add(name);
          details[name] = {'amount': (value['qty'] ?? 1).toString(), 'unit': unit};
          final cost = _planNum(value['cost']);
          if (cost.isFinite && cost > 0) prices[name] = cost;
        }
      } else {
        for (final value in (raw['items'] as List? ?? const [])) {
          final name = value.toString().trim();
          if (name.isNotEmpty && !items.contains(name)) items.add(name);
        }
        if (raw['details'] is Map) details.addAll(Map<String, dynamic>.from(raw['details'] as Map));
        if (raw['prices'] is Map) prices.addAll(Map<String, dynamic>.from(raw['prices'] as Map));
      }
      if (items.isEmpty) { _notice('Kaynakta aktarılabilir ürün bulunamadı.'); return; }
      final ok = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
        title: const Text('Alışveriş listesi oluşturulsun mu?'),
        content: Text('${fmt(targetDate)} için ${items.length} ürünle bağımsız bir liste oluşturulacak. Mevcut listeler korunacak.'),
        actions: [TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Oluştur'))]));
      if (ok != true || !mounted) return;
      final record = <String, dynamic>{
        'id': DateTime.now().microsecondsSinceEpoch.toString(),
        'title': '${rec['title']} • ${fmt(targetDate)}', 'updated': DateTime.now().toIso8601String(),
        'items': items, 'done': <String>[], 'details': details,
        'prices': prices, 'actualPrices': <String, dynamic>{},
        'recurringSourceId': rec['id'], 'scheduledDate': stamp,
        if (_planNum(rec['budget']) > 0) 'budget': _planNum(rec['budget']),
      };
      setState(() => _namedLists.insert(0, record));
      refresh(() => rec['generatedDates'] = [...generated, stamp]);
      await _save();
      await persist();
      _notice('${items.length} ürünle yeni alışveriş listesi oluşturuldu.');
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final today = day(DateTime.now());
        final until = today.add(Duration(days: horizon));
        final visible = schedules.where((r) {
          if (!(r['title'] ?? '').toString().toLowerCase().contains(query.toLowerCase()) &&
              !(r['sourceTitle'] ?? '').toString().toLowerCase().contains(query.toLowerCase())) { return false; }
          final paused = r['paused'] == true;
          if (filter == 'Aktif' && paused) return false;
          if (filter == 'Duraklatılmış' && !paused) return false;
          if (filter == 'Yaklaşan' && (paused || nextDate(r, today).isAfter(until))) return false;
          return true;
        }).toList()..sort((a,b) => nextDate(a, today).compareTo(nextDate(b, today)));
        final upcoming = schedules.where((r) => r['paused'] != true && !nextDate(r, today).isAfter(until)).toList();
        final projected = upcoming.fold<double>(0, (sum,r) {
          var date = nextDate(r, today);
          var count = 0;
          while (!date.isAfter(until) && count++ < 110) {
            sum += _planNum(r['budget']);
            date = advance(date, (r['period'] ?? 'Haftalık').toString());
          }
          return sum;
        });
        return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
          child: SizedBox(height: MediaQuery.of(ctx).size.height * .88,
            child: ListView(padding: const EdgeInsets.all(16), children: [
              const Text('Tekrarlayan Alışveriş Takvimi', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
              const Text('Kayıtlı listeler ve tasarruf senaryolarıyla haftalık / aylık alışveriş planlayın. Hatırlatmalar uygulama içindedir; telefon bildirimi gönderilmez.'),
              Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('Takvim: ${schedules.length} • Aktif: ${schedules.where((r) => r['paused'] != true).length}'),
                  Text('Önümüzdeki $horizon gün: ${upcoming.length} aktif plan'),
                  Text('Tahmini toplam bütçe: ${_money(projected)}'),
                  const Text('Bütçesi 0 olan planlar tahmini tutara eklenmez.'),
                ]))),
              Wrap(spacing: 8, children: [
                FilledButton.tonalIcon(onPressed: () => addSchedule(refresh),
                  icon: const Icon(Icons.add_circle_outline), label: const Text('Takvim oluştur')),
                OutlinedButton.icon(onPressed: () {
                  final lines = <String>['Takvim,Kaynak,Tekrar,Sonraki tarih,Bütçe,Durum,Oluşturulan liste'];
                  for (final r in visible) {
                    lines.add([r['title'],r['sourceTitle'],r['period'],fmt(nextDate(r,today)),
                      r['budget'],r['paused'] == true ? 'Duraklatıldı' : 'Aktif',
                      (r['generatedDates'] as List? ?? const []).length].map(csv).join(','));
                  }
                  Clipboard.setData(ClipboardData(text: lines.join('\n')));
                  _notice('Alışveriş takvimi CSV olarak kopyalandı.');
                }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
              ]),
              DropdownButtonFormField<int>(initialValue: horizon,
                decoration: const InputDecoration(labelText: 'Yaklaşan alışveriş aralığı'),
                items: [7, 14, 30, 60, 90].map((v) => DropdownMenuItem(value: v, child: Text('$v gün'))).toList(),
                onChanged: (v) { if (v != null) refresh(() => horizon = v); }),
              TextField(decoration: const InputDecoration(labelText: 'Takvim veya kaynak ara', prefixIcon: Icon(Icons.search)),
                onChanged: (v) => refresh(() => query = v)),
              DropdownButtonFormField<String>(initialValue: filter, decoration: const InputDecoration(labelText: 'Durum'),
                items: ['Tümü','Aktif','Duraklatılmış','Yaklaşan'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) { if (v != null) refresh(() => filter = v); }),
              ...visible.map((r) {
                final next = nextDate(r, today);
                final completed = (r['completedDates'] as List? ?? const []).map((v) => v.toString()).toSet();
                final stamp = next.toIso8601String().substring(0,10);
                final generated = (r['generatedDates'] as List? ?? const []).map((v) => v.toString()).toSet();
                return Card(child: Padding(padding: const EdgeInsets.all(8), child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start, children: [
                    ListTile(title: Text((r['title'] ?? '').toString()),
                      subtitle: Text('${r['sourceTitle']} • ${r['period']}\nSonraki: ${fmt(next)} • ${_money(_planNum(r['budget']))}\n'
                        '${r['paused'] == true ? 'Duraklatıldı' : 'Aktif'} • ${generated.length} liste oluşturuldu'),
                      trailing: IconButton(tooltip: 'Takvimi sil', icon: const Icon(Icons.delete_outline),
                        onPressed: () async {
                          final yes = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
                            title: const Text('Takvim silinsin mi?'),
                            content: const Text('Oluşturulmuş alışveriş listeleri silinmez.'),
                            actions: [TextButton(onPressed: () => Navigator.pop(dialog,false), child: const Text('Vazgeç')),
                              TextButton(onPressed: () => Navigator.pop(dialog,true), child: const Text('Sil'))]));
                          if (yes == true) { refresh(() => schedules.remove(r)); await persist(); }
                        })),
                    Wrap(spacing: 8, children: [
                      OutlinedButton.icon(icon: Icon(r['paused'] == true ? Icons.play_arrow : Icons.pause),
                        label: Text(r['paused'] == true ? 'Sürdür' : 'Duraklat'), onPressed: () async {
                          refresh(() => r['paused'] = r['paused'] != true); await persist();
                        }),
                      OutlinedButton.icon(icon: const Icon(Icons.event_repeat), label: const Text('Tarihi değiştir'),
                        onPressed: () async {
                          final picked = await showDatePicker(context: ctx, initialDate: next,
                            firstDate: DateTime(2020), lastDate: DateTime(2100));
                          if (picked == null) return;
                          refresh(() => r['nextDate'] = picked.toIso8601String()); await persist();
                        }),
                      OutlinedButton.icon(icon: const Icon(Icons.payments_outlined), label: const Text('Bütçe'),
                        onPressed: () async {
                          final raw = await _planText('Her alışveriş için bütçe (TL)', '${r['budget']}');
                          final amount = double.tryParse((raw ?? '').replaceAll(',', '.'));
                          if (raw == null) return;
                          if (amount == null || !amount.isFinite || amount < 0) { _notice('Geçerli bütçe girin.'); return; }
                          refresh(() => r['budget'] = amount); await persist();
                        }),
                      FilledButton.tonalIcon(icon: const Icon(Icons.playlist_add), label: const Text('Liste oluştur'),
                        onPressed: r['paused'] == true || generated.contains(stamp) ? null : () => generate(r, refresh)),
                      OutlinedButton.icon(icon: Icon(completed.contains(stamp) ? Icons.undo : Icons.check_circle_outline),
                        label: Text(completed.contains(stamp) ? 'Tamamlamayı geri al' : 'Tamamlandı'),
                        onPressed: () async {
                          refresh(() {
                            if (!completed.add(stamp)) completed.remove(stamp);
                            r['completedDates'] = completed.toList();
                          });
                          await persist();
                        }),
                    ]),
                  ])));
              }),
              if (visible.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('Bu filtrede kayıtlı takvim bulunamadı.')),
              const Text('Tekrarlar geçmiş tarihlerden sonraki uygun güne ilerletilir. Aylık planlarda ay sonu günü gerektiğinde kısaltılır. ' 
                'Takvim planları ayrı yerel kayıtta saklanır; genel yedeklemeye henüz dahil değildir.'),
            ]))));
      }));
  }

  Future<void> _showKitchenCalendarStockNeeds() async {
    const key = 'kitchen_recurring_shopping_calendar_v1';
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    final schedules = <Map<String, dynamic>>[];
    try {
      final raw = jsonDecode(prefs.getString(key) ?? '[]');
      if (raw is List) schedules.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
    } catch (_) { _notice('Alışveriş takvimi okunamadı.'); }
    if (schedules.isEmpty) { _notice('Önce tekrarlayan alışveriş takvimi oluşturun.'); return; }
    final scenarios = <Map<String, dynamic>>[];
    try {
      final raw = jsonDecode(prefs.getString('kitchen_savings_scenarios_v1') ?? '[]');
      if (raw is List) scenarios.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
    } catch (_) { /* Eski senaryo kayıtları isteğe bağlıdır. */ }
    var chosen = 0;
    var horizon = 30;
    var onlyShortage = true;
    var includePaused = false;
    var search = '';
    var safety = 0.0;
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    DateTime? parse(Object? v) => DateTime.tryParse((v ?? '').toString());
    DateTime addMonth(DateTime d) {
      final month = d.month == 12 ? 1 : d.month + 1;
      final year = d.month == 12 ? d.year + 1 : d.year;
      final last = DateTime(year, month + 1, 0).day;
      return DateTime(year, month, d.day.clamp(1, last).toInt());
    }
    DateTime advance(DateTime d, String period) => period == 'Haftalık'
      ? d.add(const Duration(days: 7)) : period == 'İki haftada bir'
      ? d.add(const Duration(days: 14)) : addMonth(d);
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final visibleSchedules = schedules.where((e) => includePaused || e['paused'] != true).toList();
        if (visibleSchedules.isEmpty) {
          return SafeArea(child: Padding(padding: const EdgeInsets.all(24), child:
          Column(mainAxisSize: MainAxisSize.min, children: [const Text('Etkin alışveriş takvimi bulunamadı.'),
            TextButton(onPressed: () => refresh(() => includePaused = true), child: const Text('Duraklatılmış planları göster'))])));
        }
        if (chosen >= visibleSchedules.length) chosen = 0;
        final rec = visibleSchedules[chosen];
        final sourceType = (rec['sourceType'] ?? '').toString();
        final sourceId = (rec['sourceId'] ?? '').toString();
        final matches = sourceType == 'scenario'
          ? scenarios.where((e) => (e['id'] ?? '').toString() == sourceId).toList()
          : _namedLists.where((e) => (e['id'] ?? '').toString() == sourceId).toList();
        final source = matches.isEmpty ? null : matches.first;
        final rows = <Map<String, dynamic>>[];
        var unknownPrice = 0;
        var incompatible = 0;
        var missingStock = 0;
        if (source != null) {
          final entries = sourceType == 'scenario' ? (source['items'] as List? ?? const []) : (source['items'] as List? ?? const []);
          final excluded = (source['excluded'] as List? ?? const []).map((e) => e.toString()).toSet();
          for (final item in entries) {
            String name;
            String unit;
            double needed;
            double price;
            if (sourceType == 'scenario') {
              if (item is! Map) continue;
              name = (item['name'] ?? '').toString().trim();
              unit = (item['unit'] ?? 'adet').toString();
              if (item['excluded'] == true || excluded.contains('${name.toLowerCase()}|${unit.toLowerCase()}')) continue;
              needed = _planNum(item['qty']);
              price = _planNum(item['cost']);
            } else {
              name = item.toString().trim();
              final qty = _namedQuantity(source, name);
              unit = (qty['unit'] ?? 'adet').toString();
              needed = _planNum(qty['amount']);
              price = _namedItemTotal(source, name);
            }
            if (name.isEmpty || !needed.isFinite || needed <= 0) continue;
            Map<String, dynamic>? stockSource;
            var stock = 0.0;
            var found = false;
            var mismatch = false;
            for (final candidate in _namedLists) {
              final names = (candidate['items'] as List? ?? const []).map((e) => e.toString());
              if (!names.contains(name)) continue;
              final stockUnit = (_namedQuantity(candidate, name)['unit'] ?? '').toString().toLowerCase().trim();
              if (stockUnit != unit.toLowerCase().trim()) { mismatch = true; continue; }
              final available = _planNum(_namedStock(candidate, name)['amount']);
              if (available.isFinite && available >= 0) {
                found = true;
                if (stockSource == null || available > stock) { stock = available; stockSource = candidate; }
              }
            }
            // Farklı listelerdeki stoklar birleştirilmez: aynı fiziksel stok iki kez sayılabilir.
            if (!found) { missingStock++; if (mismatch) incompatible++; }
            final shortage = found ? (needed + safety - stock).clamp(0.0, double.infinity).toDouble() : needed + safety;
            final unitCost = price > 0 && price.isFinite ? price / needed : 0.0;
            if (unitCost <= 0) unknownPrice++;
            rows.add({'name': name, 'unit': unit, 'need': needed, 'stock': stock,
              'known': found, 'mismatch': mismatch && !found, 'shortage': shortage,
              'unitCost': unitCost, 'cost': unitCost * shortage,
              'stockList': stockSource == null ? '' : (stockSource['title'] ?? '').toString()});
          }
        }
        final filtered = rows.where((r) => (!onlyShortage || (r['shortage'] as double) > 0) &&
          (r['name'] as String).toLowerCase().contains(search.toLowerCase())).toList()
          ..sort((a,b) => (b['shortage'] as double).compareTo(a['shortage'] as double));
        final shortageCount = rows.where((r) => (r['shortage'] as double) > 0).length;
        final estimated = rows.fold<double>(0, (sum,r) => sum + (r['cost'] as double));
        final budget = _planNum(rec['budget']);
        var next = parse(rec['nextDate']) ?? today;
        next = DateTime(next.year, next.month, next.day);
        var guard = 0;
        while (next.isBefore(today) && guard++ < 2000) { next = advance(next, (rec['period'] ?? 'Haftalık').toString()); }
        final until = today.add(Duration(days: horizon));
        final occurrences = <DateTime>[];
        guard = 0;
        var cursor = next;
        while (!cursor.isAfter(until) && guard++ < 110) {
          occurrences.add(cursor);
          cursor = advance(cursor, (rec['period'] ?? 'Haftalık').toString());
        }
        final lines = <String>['Takvim,Alışveriş tarihi,Ürün,Birim,İhtiyaç,Stok,Önerilen alım,Birim fiyat,Tahmini tutar,Stok kaynağı'];
        for (final r in filtered) {
          lines.add([rec['title'], fmt(next), r['name'], r['unit'], r['need'],
            r['known'] == true ? r['stock'] : 'Bilinmiyor', r['shortage'], r['unitCost'],
            r['cost'], r['stockList']].map(csv).join(','));
        }
        return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
          child: SizedBox(height: MediaQuery.of(ctx).size.height * .90,
            child: ListView(padding: const EdgeInsets.all(16), children: [
              const Text('Takvim / Stok İhtiyacı / Bütçe', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
              const SizedBox(height: 12),
              DropdownButtonFormField<int>(initialValue: chosen, isExpanded: true,
                decoration: const InputDecoration(labelText: 'Alışveriş takvimi'),
                items: [for (var i = 0; i < visibleSchedules.length; i++) DropdownMenuItem(value: i,
                  child: Text((visibleSchedules[i]['title'] ?? 'Takvim').toString(), overflow: TextOverflow.ellipsis))],
                onChanged: (v) => refresh(() => chosen = v ?? 0)),
              SwitchListTile(title: const Text('Duraklatılmış takvimleri de göster'), value: includePaused,
                onChanged: (v) => refresh(() { includePaused = v; chosen = 0; })),
              Wrap(spacing: 8, runSpacing: 8, children: [
                ChoiceChip(label: const Text('7 gün'), selected: horizon == 7, onSelected: (_) => refresh(() => horizon = 7)),
                ChoiceChip(label: const Text('30 gün'), selected: horizon == 30, onSelected: (_) => refresh(() => horizon = 30)),
                ChoiceChip(label: const Text('60 gün'), selected: horizon == 60, onSelected: (_) => refresh(() => horizon = 60)),
                ChoiceChip(label: const Text('90 gün'), selected: horizon == 90, onSelected: (_) => refresh(() => horizon = 90)),
              ]),
              Text('Sonraki alışveriş: ${fmt(next)} • Dönem içi tekrar: ${occurrences.length}'),
              Text('Dönem takvim bütçesi: ${_money(budget * occurrences.length)}'),
              Text('İlk alışveriş tahmini eksik maliyeti: ${_money(estimated)}'),
              if (budget > 0) Text('İlk alışveriş bütçe farkı: ${_money(budget - estimated)}'),
              Text('Eksik ürün: $shortageCount/${rows.length} • Fiyatı bilinmeyen: $unknownPrice'),
              Text('Stok bulunamayan: $missingStock • Birimi uyuşmayan: $incompatible'),
              if (source == null) const Text('Kaynak senaryo veya liste bulunamadı. Kaynak silinmiş olabilir.'),
              const SizedBox(height: 10),
              TextFormField(initialValue: '0', keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Ürün başına güvenlik stoğu (aynı birim)'),
                onChanged: (v) => refresh(() { final n = double.tryParse(v.replaceAll(',', '.')); if (n != null && n.isFinite && n >= 0) safety = n; })),
              SwitchListTile(title: const Text('Yalnızca eksik ürünleri göster'), value: onlyShortage,
                onChanged: (v) => refresh(() => onlyShortage = v)),
              TextField(decoration: const InputDecoration(labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
                onChanged: (v) => refresh(() => search = v)),
              OutlinedButton.icon(onPressed: () async {
                await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
                if (mounted) _notice('Stok ihtiyaç raporu CSV olarak kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('İhtiyaç raporunu CSV kopyala')),
              ...filtered.map((r) => Card(child: ListTile(
                title: Text(r['name'] as String),
                subtitle: Text('İhtiyaç: ${r['need']} ${r['unit']} • Stok: ${r['known'] == true ? r['stock'] : 'bilinmiyor'}\n'
                  'Alınacak: ${r['shortage']} ${r['unit']} • Tahmini: ${_money(r['cost'] as double)}'
                  '${r['mismatch'] == true ? '\nBirim uyuşmazlığı var' : ''}'
                  '${(r['stockList'] as String).isNotEmpty ? '\nStok listesi: ${r['stockList']}' : ''}'),
                isThreeLine: true, trailing: (r['shortage'] as double) > 0
                  ? const Icon(Icons.shopping_cart_outlined, color: _purple) : const Icon(Icons.check_circle_outline),
              ))),
              const SizedBox(height: 12),
              const Text('Bu ekran yalnızca analiz yapar; stokları, takvimi veya alışveriş listelerini değiştirmez. '
                'Stok bilinmiyorsa ihtiyacın tamamı önerilir. Fiyatı bilinmeyen ürünler tahmini toplamda 0 TL görünür; '
                'bu nedenle toplam eksik hesaplanabilir. Birden fazla listedeki stoklar çifte sayımı önlemek için toplanmaz. '
                'Gelecek tekrarlar için stok düşümü simüle edilmez.'),
            ]))));
      }));
  }


  Future<void> _showKitchenShortageToShoppingList() async {
    const calendarKey = 'kitchen_recurring_shopping_calendar_v1';
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    final schedules = <Map<String, dynamic>>[];
    final scenarios = <Map<String, dynamic>>[];
    try {
      final value = jsonDecode(prefs.getString(calendarKey) ?? '[]');
      if (value is List) schedules.addAll(value.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
    } catch (_) { _notice('Alışveriş takvimleri okunamadı.'); }
    try {
      final value = jsonDecode(prefs.getString('kitchen_savings_scenarios_v1') ?? '[]');
      if (value is List) scenarios.addAll(value.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
    } catch (_) { _notice('Tasarruf senaryoları okunamadı.'); }
    if (schedules.isEmpty) { _notice('Önce tekrarlayan alışveriş takvimi oluşturun.'); return; }
    var selected = 0;
    var safety = 0.0;
    var budgetOverride = -1.0;
    var search = '';
    var filter = 'Tümü';
    var order = 'Öncelik';
    var includeUnknown = false;
    final priority = <String, String>{};
    final omitted = <String>{};
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    DateTime advance(DateTime d, String period) {
      if (period == 'Haftalık') return d.add(const Duration(days: 7));
      if (period == 'İki haftada bir') return d.add(const Duration(days: 14));
      final month = d.month == 12 ? 1 : d.month + 1;
      final year = d.month == 12 ? d.year + 1 : d.year;
      return DateTime(year, month, d.day.clamp(1, DateTime(year, month + 1, 0).day).toInt());
    }
    await showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final schedule = schedules[selected];
        final sourceType = (schedule['sourceType'] ?? '').toString();
        final sourceId = (schedule['sourceId'] ?? '').toString();
        final matches = sourceType == 'scenario'
          ? scenarios.where((e) => (e['id'] ?? '').toString() == sourceId).toList()
          : _namedLists.where((e) => (e['id'] ?? '').toString() == sourceId).toList();
        final source = matches.isEmpty ? null : matches.first;
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        var date = DateTime.tryParse((schedule['nextDate'] ?? '').toString()) ?? today;
        date = DateTime(date.year, date.month, date.day);
        for (var i = 0; date.isBefore(today) && i < 2000; i++) {
          date = advance(date, (schedule['period'] ?? 'Haftalık').toString());
        }
        final rows = <Map<String, dynamic>>[];
        if (source != null) {
          final excluded = (source['excluded'] as List? ?? const []).map((e) => e.toString()).toSet();
          final seen = <String>{};
          for (final entry in (source['items'] as List? ?? const [])) {
            String name;
            String unit;
            double need;
            double cost;
            if (sourceType == 'scenario') {
              if (entry is! Map) continue;
              name = (entry['name'] ?? '').toString().trim();
              unit = (entry['unit'] ?? 'adet').toString().trim();
              if (entry['excluded'] == true || excluded.contains('${name.toLowerCase()}|${unit.toLowerCase()}')) continue;
              need = _planNum(entry['qty']);
              cost = _planNum(entry['cost']);
            } else {
              name = entry.toString().trim();
              final q = _namedQuantity(source, name);
              unit = (q['unit'] ?? 'adet').toString().trim();
              need = _planNum(q['amount']);
              cost = _namedItemTotal(source, name);
            }
            final id = '${name.toLowerCase()}|${unit.toLowerCase()}';
            if (name.isEmpty || unit.isEmpty || !seen.add(id) || !need.isFinite || need <= 0) continue;
            var available = 0.0;
            var known = false;
            var mismatch = false;
            String stockSource = '';
            for (final list in _namedLists) {
              if (!(list['items'] as List? ?? const []).any((v) => v.toString() == name)) continue;
              if ((_namedQuantity(list, name)['unit'] ?? '').toString().trim().toLowerCase() != unit.toLowerCase()) {
                mismatch = true; continue;
              }
              final qty = _planNum(_namedStock(list, name)['amount']);
              if (!qty.isFinite || qty < 0) continue;
              if (!known || qty > available) {
                known = true;
                available = qty;
                stockSource = (list['title'] ?? '').toString();
              }
            }
            final shortage = (need + safety - (known ? available : 0.0)).clamp(0.0, double.infinity).toDouble();
            if (shortage <= 0) continue;
            final unitCost = cost.isFinite && cost > 0 ? cost / need : 0.0;
            rows.add({'id': id, 'name': name, 'unit': unit, 'need': need, 'stock': available,
              'known': known, 'mismatch': mismatch && !known, 'qty': shortage,
              'unitCost': unitCost, 'cost': unitCost * shortage, 'stockSource': stockSource});
          }
        }
        int rank(String p) => p == 'Zorunlu' ? 0 : p == 'Normal' ? 1 : 2;
        rows.sort((a,b) {
          if (order == 'Maliyet') return (b['cost'] as double).compareTo(a['cost'] as double);
          if (order == 'Ürün adı') return (a['name'] as String).compareTo(b['name'] as String);
          final v = rank(priority[a['id']] ?? 'Normal').compareTo(rank(priority[b['id']] ?? 'Normal'));
          return v != 0 ? v : (a['cost'] as double).compareTo(b['cost'] as double);
        });
        final budget = budgetOverride >= 0 ? budgetOverride : _planNum(schedule['budget']);
        final available = <Map<String, dynamic>>[];
        final deferred = <Map<String, dynamic>>[];
        var spent = 0.0;
        for (final r in rows) {
          final id = r['id'] as String;
          final cost = r['cost'] as double;
          if (omitted.contains(id) || (cost <= 0 && !includeUnknown) ||
              (budget > 0 && cost > budget - spent + 0.000001)) {
            deferred.add(r);
          } else {
            available.add(r);
            spent += cost;
          }
        }
        final visible = rows.where((r) {
          final name = (r['name'] as String).toLowerCase();
          if (!name.contains(search.toLowerCase())) return false;
          if (filter == 'Seçilenler') return available.contains(r);
          if (filter == 'Ertelenenler') return deferred.contains(r);
          if (filter == 'Zorunlu') return (priority[r['id']] ?? 'Normal') == 'Zorunlu';
          if (filter == 'Fiyat bilinmiyor') return (r['unitCost'] as double) <= 0;
          return true;
        }).toList();
        final lines = <String>['Ürün,Birim,İhtiyaç,Stok,Alınacak,Birim fiyat,Tahmini maliyet,Öncelik,Karar,Stok kaynağı'];
        for (final r in rows) {
          lines.add([r['name'],r['unit'],r['need'],r['known'] == true ? r['stock'] : 'Bilinmiyor',
            r['qty'],r['unitCost'],r['cost'],priority[r['id']] ?? 'Normal',
            available.contains(r) ? 'Alınacak' : 'Ertelendi',r['stockSource']].map(csv).join(','));
        }
        Future<void> createList() async {
          if (available.isEmpty) { _notice('Listeye aktarılacak ürün bulunamadı.'); return; }
          final stamp = '${date.year}-${date.month.toString().padLeft(2,'0')}-${date.day.toString().padLeft(2,'0')}';
          final proposed = '${schedule['title'] ?? 'Alışveriş'} • Stok eksikleri • ${fmt(date)}';
          final title = await _askListName(initial: proposed);
          if (title == null || !mounted) return;
          final ok = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(
            title: const Text('Bağımsız alışveriş listesi oluştur'),
            content: Text('${available.length} ürün eklenecek. Tahmini maliyet: ${_money(spent)}. '
              'Mevcut alışveriş listeleri ve stoklar değiştirilmeyecek.'),
            actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Oluştur'))]));
          if (ok != true || !mounted) return;
          final names = <String>[];
          final details = <String, dynamic>{};
          final prices = <String, dynamic>{};
          final priorities = <String, dynamic>{};
          for (final r in available) {
            final name = r['name'] as String;
            if (names.contains(name)) continue;
            names.add(name);
            details[name] = {'amount': (r['qty'] as double).toString(), 'unit': r['unit']};
            if ((r['cost'] as double) > 0) prices[name] = r['cost'];
            priorities[name] = priority[r['id']] ?? 'Normal';
          }
          final record = <String, dynamic>{
            'id': DateTime.now().microsecondsSinceEpoch.toString(), 'title': title,
            'updated': DateTime.now().toIso8601String(), 'items': names, 'done': <String>[],
            'details': details, 'prices': prices, 'actualPrices': <String, dynamic>{},
            'budget': budget, 'calendarSourceId': schedule['id'], 'scheduledDate': stamp,
            'shortagePriorities': priorities, 'shortagePlanEstimate': spent,
          };
          setState(() => _namedLists.insert(0, record));
          await _save();
          if (mounted) _notice('${names.length} ürün içeren “$title” listesi oluşturuldu.');
        }
        return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
          child: SizedBox(height: MediaQuery.of(ctx).size.height * .92,
            child: ListView(padding: const EdgeInsets.all(16), children: [
              const Text('Stok Eksiklerinden Alışveriş Listesi',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
              const SizedBox(height: 10),
              DropdownButtonFormField<int>(initialValue: selected, isExpanded: true,
                decoration: const InputDecoration(labelText: 'Alışveriş takvimi'),
                items: [for (var i = 0; i < schedules.length; i++) DropdownMenuItem(value: i,
                  child: Text((schedules[i]['title'] ?? 'Takvim').toString(), overflow: TextOverflow.ellipsis))],
                onChanged: (v) => refresh(() { selected = v ?? 0; priority.clear(); omitted.clear(); budgetOverride = -1; })),
              if (source == null) const Text('Takvim kaynağı bulunamadı; liste silinmiş olabilir.'),
              Text('Alışveriş tarihi: ${fmt(date)} • Eksik ürün: ${rows.length}'),
              Text('Takvim bütçesi: ${_money(_planNum(schedule['budget']))}'),
              Text('Seçilen: ${available.length} ürün • Ertelenen: ${deferred.length} ürün'),
              Text('Tahmini harcama: ${_money(spent)} • ${budget > 0 ? 'Kalan: ${_money(budget - spent)}' : 'Bütçe sınırı yok'}'),
              if (rows.any((r) => (r['unitCost'] as double) <= 0))
                const Text('Fiyatı bilinmeyen ürünler için tahmini toplam eksik olabilir.'),
              TextFormField(initialValue: '0', keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Ürün başına güvenlik stoğu'),
                onChanged: (v) { final n = double.tryParse(v.replaceAll(',', '.')); if (n != null && n.isFinite && n >= 0) refresh(() => safety = n); }),
              TextFormField(key: ValueKey('budget_$selected'),
                initialValue: budgetOverride < 0 ? _planNum(schedule['budget']).toString() : budgetOverride.toString(),
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Bu plan için bütçe (0 = sınırsız)'),
                onChanged: (v) { final n = double.tryParse(v.replaceAll(',', '.')); if (n != null && n.isFinite && n >= 0) refresh(() => budgetOverride = n); }),
              SwitchListTile(title: const Text('Fiyatı bilinmeyen ürünleri de dahil et'),
                value: includeUnknown, onChanged: (v) => refresh(() => includeUnknown = v)),
              Wrap(spacing: 8, runSpacing: 8, children: [
                for (final v in ['Tümü','Seçilenler','Ertelenenler','Zorunlu','Fiyat bilinmiyor'])
                  ChoiceChip(label: Text(v), selected: filter == v, onSelected: (_) => refresh(() => filter = v)),
              ]),
              DropdownButtonFormField<String>(initialValue: order, decoration: const InputDecoration(labelText: 'Sıralama'),
                items: ['Öncelik','Maliyet','Ürün adı'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) => refresh(() => order = v ?? 'Öncelik')),
              TextField(decoration: const InputDecoration(labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
                onChanged: (v) => refresh(() => search = v)),
              FilledButton.icon(onPressed: available.isEmpty ? null : createList,
                icon: const Icon(Icons.playlist_add), label: const Text('Seçilenlerden alışveriş listesi oluştur')),
              OutlinedButton.icon(onPressed: () async {
                await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
                if (mounted) _notice('Stok eksikleri ve bütçe kararları CSV olarak kopyalandı.');
              }, icon: const Icon(Icons.copy), label: const Text('Karar raporunu CSV kopyala')),
              ...visible.map((r) {
                final id = r['id'] as String;
                final p = priority[id] ?? 'Normal';
                return Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(r['name'] as String, style: const TextStyle(fontWeight: FontWeight.bold)),
                    Text('Alınacak: ${r['qty']} ${r['unit']} • Tahmini: ${_money(r['cost'] as double)}'),
                    Text('Stok: ${r['known'] == true ? r['stock'] : 'bilinmiyor'} • '
                      '${available.contains(r) ? 'Plana dahil' : 'Ertelendi'}'),
                    if (r['mismatch'] == true) const Text('Ölçü birimi uyuşmazlığı var'),
                    Row(children: [
                      Expanded(child: DropdownButton<String>(value: p, isExpanded: true,
                        items: ['Zorunlu','Normal','Ertelenebilir'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                        onChanged: (v) => refresh(() => priority[id] = v ?? 'Normal'))),
                      const SizedBox(width: 8),
                      TextButton(onPressed: () => refresh(() {
                        if (!omitted.add(id)) omitted.remove(id);
                      }), child: Text(omitted.contains(id) ? 'Geri al' : 'Ertele')),
                    ]),
                  ])));
              }),
              const Text('Öncelik ve erteleme seçimleri bu ekran için geçerlidir. '
                'Bütçe dağıtımı seçilen sıralamaya göre yapılır; en iyi kombinasyonu garanti etmez. '
                'Stok bilinmiyorsa ihtiyaç miktarı tam alınacak kabul edilir. '
                'Oluşturulan liste bağımsızdır; mevcut stoklar ve alışverişler değişmez.'),
            ]))));
      }));
  }

  void _showKitchenPriceBudgetCenter() {
    var month = _monthKey();
    var store = 'Tümü';
    var search = '';
    var alertOnly = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final purchases = <Map<String, dynamic>>[];
        for (final list in _namedLists) {
          final raw = list['marketPurchases'];
          if (raw is! Map) continue;
          final names = (list['items'] as List? ?? const []).map((e) => e.toString()).toSet();
          for (final entry in raw.entries) {
            final name = entry.key.toString();
            if (!names.contains(name) || entry.value is! Map) continue;
            final p = entry.value as Map;
            final date = DateTime.tryParse((p['at'] ?? '').toString());
            final total = double.tryParse((p['total'] ?? '').toString().replaceAll(',', '.'));
            final qty = double.tryParse((p['quantity'] ?? '').toString().replaceAll(',', '.'));
            if (date == null || total == null || !total.isFinite || total < 0) continue;
            purchases.add({'name': name, 'month': _monthKey(date), 'date': date,
              'store': (p['store'] ?? 'Belirtilmedi').toString().trim(),
              'total': total, 'qty': qty,
              'unit': (_namedQuantity(list, name)['unit'] ?? '').toString()});
          }
        }
        final monthOptions = <String>{month, _monthKey(), ..._monthlyBudgets.keys,
          ...purchases.map((p) => p['month'].toString())}.toList()..sort((a,b) => b.compareTo(a));
        final storeOptions = purchases.where((p) => p['month'] == month)
          .map((p) => p['store'].toString()).toSet().toList()..sort();
        if (store != 'Tümü' && !storeOptions.contains(store)) store = 'Tümü';
        final allMonth = purchases.where((p) => p['month'] == month).toList();
        final spent = allMonth.fold<double>(0, (a,p) => a + (p['total'] as double));
        final budget = _monthlyBudgets[month] ?? 0;
        final now = DateTime.now();
        final parts = month.split('-');
        final year = int.tryParse(parts.first) ?? now.year;
        final mo = parts.length > 1 ? (int.tryParse(parts[1]) ?? now.month) : now.month;
        final daysInMonth = DateTime(year, mo + 1, 0).day;
        final isCurrent = month == _monthKey();
        final elapsed = isCurrent ? now.day : daysInMonth;
        final daily = elapsed > 0 ? spent / elapsed : 0.0;
        final projection = isCurrent ? daily * daysInMonth : spent;
        final previous = _monthKey(DateTime(year, mo - 1, 1));
        final previousSpent = purchases.where((p) => p['month'] == previous)
          .fold<double>(0, (a,p) => a + (p['total'] as double));
        final productHistory = <String, List<Map<String, dynamic>>>{};
        for (final p in purchases) {
          final qty = p['qty'];
          if (qty is! double || !qty.isFinite || qty <= 0) continue;
          final key = '${p['name'].toString().trim().toLowerCase()}|${p['unit']}';
          productHistory.putIfAbsent(key, () => []).add(p);
        }
        final trends = <Map<String, dynamic>>[];
        for (final group in productHistory.values) {
          group.sort((a,b) => (a['date'] as DateTime).compareTo(b['date'] as DateTime));
          if (group.length < 2) continue;
          final first = group.first;
          final last = group.last;
          final firstPrice = (first['total'] as double) / (first['qty'] as double);
          final lastPrice = (last['total'] as double) / (last['qty'] as double);
          if (firstPrice <= 0 || !firstPrice.isFinite || !lastPrice.isFinite) continue;
          trends.add({'name': last['name'], 'unit': last['unit'], 'first': firstPrice,
            'last': lastPrice, 'change': (lastPrice / firstPrice - 1) * 100,
            'store': last['store'], 'date': last['date']});
        }
        trends.sort((a,b) => (b['change'] as double).compareTo(a['change'] as double));
        final visible = trends.where((p) => (store == 'Tümü' || p['store'] == store) &&
          p['name'].toString().toLowerCase().contains(search.toLowerCase()) &&
          (!alertOnly || (p['change'] as double) >= 10)).toList();
        final storeTotals = <String, double>{};
        for (final p in allMonth) {
          final key = p['store'] as String;
          storeTotals[key] = (storeTotals[key] ?? 0) + (p['total'] as double);
        }
        final storeRank = storeTotals.entries.toList()..sort((a,b) => b.value.compareTo(a.value));
        String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Aylık bütçe ve fiyat artış merkezi', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı gerçek alımları kullanır. Aynı ürün ve birim için ilk/son fiyat karşılaştırılır.'),
            DropdownButtonFormField<String>(initialValue: month, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Bütçe ayı'),
              items: monthOptions.map((m) => DropdownMenuItem(value: m, child: Text(m))).toList(),
              onChanged: (v) { if (v != null) refresh(() => month = v); }),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Aylık hedef: ${budget > 0 ? _money(budget) : 'Tanımlanmadı'}'),
                Text('Kayıtlı gerçekleşen: ${_money(spent)} • ${allMonth.length} alım'),
                if (budget > 0) ...[
                  Text('Bütçe farkı: ${_money(budget - spent)}',
                    style: TextStyle(color: spent > budget ? Colors.red : Colors.green.shade800)),
                  LinearProgressIndicator(value: (spent / budget).clamp(0.0, 1.0)),
                  if (spent > budget) const Text('Bütçe aşıldı', style: TextStyle(color: Colors.red)),
                ],
                if (isCurrent) Text('Ay sonu doğrusal tahmin: ${_money(projection)} (günlük ${_money(daily)})'),
                if (isCurrent && budget > 0 && projection > budget)
                  const Text('Uyarı: Mevcut harcama hızıyla ay sonunda hedef aşılabilir.',
                    style: TextStyle(color: Colors.red)),
                Text('Önceki ay ($previous): ${_money(previousSpent)}'),
                if (previousSpent > 0) Text('Önceki aya göre: %${((spent / previousSpent - 1) * 100).toStringAsFixed(1)}'),
                TextButton.icon(icon: const Icon(Icons.edit_outlined),
                  label: const Text('Bu ayın bütçesini düzenle'), onPressed: () async {
                    final input = TextEditingController(text: budget > 0 ? budget.toStringAsFixed(2) : '');
                    final value = await showDialog<String>(context: ctx, builder: (d) => AlertDialog(
                      title: Text('$month bütçe hedefi (TL)'),
                      content: TextField(controller: input, keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        decoration: const InputDecoration(hintText: 'Örn. 5000; sıfır = hedef yok')),
                      actions: [TextButton(onPressed: () => Navigator.pop(d), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(d, input.text), child: const Text('Kaydet'))]));
                    disposeAfterDialog(input);
                    if (value == null || !mounted) return;
                    final parsed = double.tryParse(value.trim().replaceAll(',', '.'));
                    if (parsed == null || !parsed.isFinite || parsed < 0) {
                      _notice('Geçerli, negatif olmayan bir bütçe girin.'); return;
                    }
                    setState(() => _monthlyBudgets[month] = parsed);
                    await _save();
                    if (ctx.mounted) refresh(() {});
                  }),
              ]))),
            const Text('Market harcamaları', style: TextStyle(fontWeight: FontWeight.bold)),
            ...storeRank.map((e) => ListTile(dense: true, title: Text(e.key),
              subtitle: Text(spent > 0 ? '%${(100 * e.value / spent).toStringAsFixed(1)} pay' : 'Kayıt yok'),
              trailing: Text(_money(e.value)))),
            const Divider(),
            const Text('Ürün fiyat değişimleri (tüm kayıtlı dönem)',
              style: TextStyle(fontWeight: FontWeight.bold)),
            const Text('Fiyatlar aynı ürün ve ölçü birimindeki ilk ve son satın alma kaydından hesaplanır.'),
            DropdownButtonFormField<String>(initialValue: store, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Son alım marketi'),
              items: ['Tümü', ...storeOptions].map((v) => DropdownMenuItem(value: v,
                child: Text(v, overflow: TextOverflow.ellipsis))).toList(),
              onChanged: (v) { if (v != null) refresh(() => store = v); }),
            TextField(decoration: const InputDecoration(labelText: 'Ürün ara', prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => search = v)),
            SwitchListTile(title: const Text('Yalnızca %10 ve üzeri artışlar'), value: alertOnly,
              onChanged: (v) => refresh(() => alertOnly = v)),
            Text('${visible.length} ürün • %10+ artış: ${trends.where((p) => (p['change'] as double) >= 10).length}'),
            FilledButton.tonalIcon(icon: const Icon(Icons.copy_outlined),
              label: const Text('Bütçe ve fiyat değişim raporunu CSV kopyala'),
              onPressed: () async {
                final lines = <String>['Bölüm;Ay/Ürün;Market;İlk fiyat;Son fiyat;Değişim %;Tutar TL',
                  ['Bütçe', month, '', budget, '', '', spent].map(csv).join(';')];
                for (final e in storeRank) {
                  lines.add(['Market', month, e.key, '', '', '', e.value].map(csv).join(';'));
                }
                for (final p in visible) {
                  lines.add(['Fiyat', p['name'], p['store'], p['first'], p['last'],
                    (p['change'] as double).toStringAsFixed(2), ''].map(csv).join(';'));
                }
                await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
                _notice('Bütçe ve fiyat raporu kopyalandı.');
              }),
            if (visible.isEmpty) const Text('Bu filtre için karşılaştırılabilir ürün bulunamadı.'),
            ...visible.take(100).map((p) => Card(child: ListTile(
              title: Text('${p['name']} (${p['unit']})'),
              subtitle: Text('${_money(p['first'] as double)} → ${_money(p['last'] as double)} • ${p['store']}'),
              trailing: Text('%${(p['change'] as double).toStringAsFixed(1)}',
                style: TextStyle(color: (p['change'] as double) > 0 ? Colors.red : Colors.green.shade800)),
            ))),
            if (visible.length > 100) Text('İlk 100 kayıt gösteriliyor; CSV tüm ${visible.length} kaydı içerir.'),
          ])));
      }));
  }

  void _showKitchenPurchaseAnalytics() {
    var period = 90;
    var storeFilter = 'Tümü';
    var query = '';
    var onlyTransferred = false;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final cutoff = DateTime(now.year, now.month, now.day).subtract(Duration(days: period - 1));
        final all = <Map<String, dynamic>>[];
        var invalidDate = 0;
        var invalidCost = 0;
        for (final list in _namedLists) {
          final purchases = list['marketPurchases'];
          if (purchases is! Map) continue;
          final names = (list['items'] as List? ?? const []).map((e) => e.toString()).toSet();
          for (final entry in purchases.entries) {
            final name = entry.key.toString();
            if (!names.contains(name) || entry.value is! Map) continue;
            final p = Map<String, dynamic>.from(entry.value as Map);
            final date = DateTime.tryParse((p['at'] ?? '').toString());
            if (date == null) { invalidDate++; continue; }
            final amount = double.tryParse((p['total'] ?? '').toString().replaceAll(',', '.'));
            if (amount == null || !amount.isFinite || amount < 0) { invalidCost++; continue; }
            final quantity = double.tryParse((p['quantity'] ?? '').toString().replaceAll(',', '.'));
            final unit = (_namedQuantity(list, name)['unit'] ?? '').toString();
            all.add(<String, dynamic>{'name': name, 'list': (list['title'] ?? 'Adsız liste').toString(),
              'store': (p['store'] ?? 'Market belirtilmedi').toString().trim(),
              'date': date, 'cost': amount, 'quantity': quantity,
              'unit': unit, 'transferred': p['stockTransferred'] == true,
              'planned': _namedItemTotal(list, name)});
          }
        }
        final stores = all.map((e) => e['store'].toString()).toSet().toList()..sort();
        if (storeFilter != 'Tümü' && !stores.contains(storeFilter)) storeFilter = 'Tümü';
        final rows = all.where((e) {
          final date = e['date'] as DateTime;
          return !date.isBefore(cutoff) && !date.isAfter(now) &&
            (storeFilter == 'Tümü' || e['store'] == storeFilter) &&
            (!onlyTransferred || e['transferred'] == true) &&
            ('${e['name']} ${e['list']} ${e['store']}'.toLowerCase().contains(query.toLowerCase()));
        }).toList()..sort((a,b) => (b['date'] as DateTime).compareTo(a['date'] as DateTime));
        final byStore = <String, double>{};
        final byMonth = <String, double>{};
        final byProduct = <String, Map<String, dynamic>>{};
        var actual = 0.0;
        var planned = 0.0;
        var transferredCount = 0;
        var missingQuantity = 0;
        for (final row in rows) {
          final cost = row['cost'] as double;
          actual += cost;
          planned += row['planned'] as double;
          if (row['transferred'] == true) transferredCount++;
          if (row['quantity'] == null || !(row['quantity'] as double).isFinite || (row['quantity'] as double) <= 0) missingQuantity++;
          final store = row['store'] as String;
          byStore[store] = (byStore[store] ?? 0) + cost;
          final date = row['date'] as DateTime;
          final month = '${date.year}-${date.month.toString().padLeft(2,'0')}';
          byMonth[month] = (byMonth[month] ?? 0) + cost;
          final key = '${row['name']}|${row['unit']}';
          final product = byProduct.putIfAbsent(key, () => <String, dynamic>{
            'name': row['name'], 'unit': row['unit'], 'cost': 0.0, 'quantity': 0.0, 'count': 0,
            'firstPrice': null, 'lastPrice': null, 'firstDate': null, 'lastDate': null});
          product['cost'] = (product['cost'] as double) + cost;
          product['count'] = (product['count'] as int) + 1;
          final q = row['quantity'];
          if (q is double && q.isFinite && q > 0) {
            product['quantity'] = (product['quantity'] as double) + q;
            final price = cost / q;
            if (product['firstDate'] == null || date.isBefore(product['firstDate'] as DateTime)) {
              product['firstDate'] = date; product['firstPrice'] = price;
            }
            if (product['lastDate'] == null || date.isAfter(product['lastDate'] as DateTime)) {
              product['lastDate'] = date; product['lastPrice'] = price;
            }
          }
        }
        final rankedStores = byStore.entries.toList()..sort((a,b) => b.value.compareTo(a.value));
        final rankedProducts = byProduct.values.toList()..sort((a,b) =>
          (b['cost'] as double).compareTo(a['cost'] as double));
        final months = byMonth.keys.toList()..sort((a,b) => b.compareTo(a));
        String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Alışveriş geçmişi ve market performansı', style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Kayıtlı gerçek satın almalardan hesaplanır; stok ve alışveriş verileri değişmez.'),
            DropdownButtonFormField<int>(initialValue: period,
              decoration: const InputDecoration(labelText: 'Analiz dönemi'),
              items: const [7, 30, 90, 180, 365, 730].map((n) => DropdownMenuItem(
                value: n, child: Text('Son $n gün'))).toList(),
              onChanged: (v) { if (v != null) refresh(() => period = v); }),
            DropdownButtonFormField<String>(initialValue: storeFilter, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Market'),
              items: ['Tümü', ...stores].map((v) => DropdownMenuItem(value: v,
                child: Text(v, overflow: TextOverflow.ellipsis))).toList(),
              onChanged: (v) { if (v != null) refresh(() => storeFilter = v); }),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün, liste veya market ara'),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca stoğa aktarılan alımlar'),
              value: onlyTransferred, onChanged: (v) => refresh(() => onlyTransferred = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Satın alma kaydı: ${rows.length} • Market: ${byStore.length}'),
                Text('Gerçek harcama: ${_money(actual)}'),
                Text('Aynı ürünlerin kayıtlı plan tutarı: ${_money(planned)}'),
                Text('Plan / gerçek farkı: ${_money(planned - actual)}'),
                Text('Stoğa aktarılan kayıt: $transferredCount • Bekleyen: ${rows.length - transferredCount}'),
                if (invalidDate > 0 || invalidCost > 0 || missingQuantity > 0)
                  Text('Veri uyarıları: Tarihsiz $invalidDate, tutarsız $invalidCost, miktarsız $missingQuantity'),
                const Text('Fark yalnızca kayıtlı satın almalar için hesaplanır; fiyatı veya tarihi eksik kayıtlar toplama girmez.'),
              ]))),
            FilledButton.tonalIcon(icon: const Icon(Icons.copy),
              label: const Text('Filtrelenen satın alma geçmişini CSV kopyala'),
              onPressed: rows.isEmpty ? null : () async {
                final lines = <String>['Tarih;Ürün;Liste;Market;Miktar;Birim;Planlanan TL;Gerçek TL;Stoğa aktarıldı'];
                for (final row in rows) {
                  lines.add([(row['date'] as DateTime).toIso8601String(), row['name'],
                    row['list'], row['store'], row['quantity'], row['unit'], row['planned'],
                    row['cost'], row['transferred'] == true ? 'Evet' : 'Hayır'].map(csv).join(';'));
                }
                await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
                _notice('Alışveriş geçmişi CSV olarak kopyalandı.');
              }),
            const SizedBox(height: 12),
            const Text('Aylık harcamalar', style: TextStyle(fontWeight: FontWeight.bold)),
            if (months.isEmpty) const Text('Bu dönemde kayıtlı satın alma yok.'),
            ...months.map((m) => ListTile(dense: true, title: Text(m), trailing: Text(_money(byMonth[m]!)))),
            const Divider(),
            const Text('Market bazlı harcama', style: TextStyle(fontWeight: FontWeight.bold)),
            ...rankedStores.map((e) => ListTile(dense: true, title: Text(e.key),
              subtitle: Text('Toplamın %${actual > 0 ? (100 * e.value / actual).toStringAsFixed(1) : '0'}'),
              trailing: Text(_money(e.value)))),
            const Divider(),
            const Text('En yüksek harcama yapılan ürünler', style: TextStyle(fontWeight: FontWeight.bold)),
            ...rankedProducts.take(30).map((p) {
              final first = p['firstPrice']; final last = p['lastPrice'];
              final trend = first is double && last is double && first > 0
                ? ' • İlk/son birim fiyat: ${_money(first)} → ${_money(last)}'
                : '';
              return ListTile(dense: true, title: Text(p['name'].toString()),
                subtitle: Text('${p['count']} alım • ${p['quantity']} ${p['unit']}$trend'),
                trailing: Text(_money(p['cost'] as double)));
            }),
            const Divider(),
            const Text('Son satın almalar', style: TextStyle(fontWeight: FontWeight.bold)),
            ...rows.take(40).map((r) => ListTile(dense: true,
              title: Text('${r['name']} • ${r['store']}'),
              subtitle: Text('${(r['date'] as DateTime).day}.${(r['date'] as DateTime).month}.${(r['date'] as DateTime).year} • ${r['list']} • ${r['quantity'] ?? '?'} ${r['unit']}'),
              trailing: Text(_money(r['cost'] as double)))),
          ])));
      }));
  }

  void _showKitchenMarketOptimizer() {
    var query = '';
    var onlyAlternatives = false;
    var budget = 1500.0;
    var sort = 'Tasarruf';
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final offers = <String, List<Map<String, dynamic>>>{};
        for (final list in _namedLists) {
          final listName = (list['title'] ?? 'Adsız liste').toString();
          for (final raw in (list['items'] as List? ?? const [])) {
            final name = raw.toString().trim();
            if (name.isEmpty) continue;
            final q = _namedQuantity(list, name);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final amount = _planNum(q['amount']);
            if (!amount.isFinite || amount <= 0) continue;
            final total = _namedItemTotal(list, name);
            if (!total.isFinite || total <= 0) continue;
            final store = (_namedProductMeta(list, name)['store'] ?? '').trim();
            if (store.isEmpty) continue;
            final key = '${name.toLowerCase()}|$unit';
            offers.putIfAbsent(key, () => []).add({
              'name': name, 'unit': unit, 'store': store, 'list': listName,
              'price': total / amount, 'amount': amount,
            });
          }
        }
        final rows = <Map<String, dynamic>>[];
        for (final group in offers.values) {
          // Aynı marketin farklı listelerdeki fiyatları ayrı referanslardır.
          group.sort((a, b) => (a['price'] as double).compareTo(b['price'] as double));
          final cheapest = group.first;
          final highest = group.last;
          final saving = (highest['price'] as double) - (cheapest['price'] as double);
          if (query.isNotEmpty && !('${cheapest['name']} ${cheapest['store']}').toLowerCase().contains(query.toLowerCase())) continue;
          if (onlyAlternatives && group.length < 2) continue;
          rows.add({'best': cheapest, 'offers': group, 'saving': saving});
        }
        rows.sort((a, b) {
          if (sort == 'Ürün') return (a['best']['name'] as String).compareTo(b['best']['name'] as String);
          if (sort == 'En düşük fiyat') return (a['best']['price'] as double).compareTo(b['best']['price'] as double);
          return (b['saving'] as double).compareTo(a['saving'] as double);
        });
        final bestTotal = rows.fold<double>(0, (sum, r) => sum + (r['best']['price'] as double));
        final maxTotal = rows.fold<double>(0, (sum, r) => sum + ((r['offers'] as List).last['price'] as double));
        var running = 0.0;
        var fitCount = 0;
        for (final r in rows) {
          final price = r['best']['price'] as double;
          if (running + price <= budget) {running += price; fitCount++;}
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .93,
          child: Padding(padding: const EdgeInsets.all(16), child: Column(children: [
            const Text('Market fiyat karşılaştırması ve sepet optimizasyonu',
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const Text('Fiyatlar kayıtlı listelerden alınır. Ürün ve ölçü birimi eşleşmeden karşılaştırma yapılmaz. Fiyatlar güncel market fiyatı değildir.'),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Ürün veya market ara'),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca birden fazla fiyat kaydı olanlar'),
              value: onlyAlternatives, onChanged: (v) => refresh(() => onlyAlternatives = v)),
            Row(children: [const Text('Sırala: '), Expanded(child: DropdownButton<String>(
              isExpanded: true, value: sort,
              items: ['Tasarruf', 'Ürün', 'En düşük fiyat'].map((e) => DropdownMenuItem(value: e, child: Text(e))).toList(),
              onChanged: (v) {if (v != null) refresh(() => sort = v);},
            ))]),
            Row(children: [const Text('Bütçe (TL): '), Expanded(child: Slider(
              value: budget, min: 0, max: 10000, divisions: 100,
              label: budget.toStringAsFixed(0), onChanged: (v) => refresh(() => budget = v),
            )), Text(_money(budget))]),
            Text('Ürün/birim eşleşmesi: ${rows.length} • En düşük fiyat toplamı (her üründen 1 birim): ${_money(bestTotal)}'),
            Text('Referans en yüksek fiyat toplamı: ${_money(maxTotal)} • Fark: ${_money(maxTotal - bestTotal)}'),
            Text('Bütçeye sırayla sığan: $fitCount ürün • ${_money(running)} (ürün başına 1 birim)'),
            TextButton.icon(onPressed: () async {
              String cell(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
              final lines = <String>['Ürün;Birim;Market;Liste;Birim fiyat;Alternatif sayısı;Fiyat farkı'];
              for (final row in rows) {
                final b = row['best'] as Map<String, dynamic>;
                lines.add([b['name'], b['unit'], b['store'], b['list'],
                  (b['price'] as double).toStringAsFixed(2),
                  (row['offers'] as List).length, (row['saving'] as double).toStringAsFixed(2)].map(cell).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
              _notice('Market karşılaştırma raporu kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Karşılaştırmayı CSV kopyala')),
            Expanded(child: rows.isEmpty
              ? const Center(child: Text('Karşılaştırılabilecek market fiyatı bulunamadı. Ürünlerde market ve fiyat bilgisi tanımlayın.'))
              : ListView.builder(itemCount: rows.length, itemBuilder: (ctx, index) {
                  final row = rows[index];
                  final best = row['best'] as Map<String, dynamic>;
                  final options = row['offers'] as List<Map<String, dynamic>>;
                  return Card(child: ExpansionTile(
                    title: Text('${best['name']} • ${_money(best['price'] as double)} / ${best['unit']}'),
                    subtitle: Text('En uygun kayıt: ${best['store']} • ${options.length} fiyat referansı • Birim farkı: ${_money(row['saving'] as double)}'),
                    children: options.map((o) => ListTile(dense: true,
                      title: Text('${o['store']} — ${_money(o['price'] as double)} / ${o['unit']}'),
                      subtitle: Text('Kaynak liste: ${o['list']} • Kayıtlı miktar: ${o['amount']}'),
                    )).toList(),
                  ));
                })),
          ]))));
      }),
    );
  }


  void _showKitchenSmartReplenishment() {
    var lookback = 60;
    var horizon = 14;
    var safetyDays = 3;
    var leadDays = 2;
    var budget = 2000.0;
    var selectedList = 0;
    var filter = 'Tümü';
    var sort = 'Aciliyet';
    var search = '';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    String day(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final start = now.subtract(Duration(days: lookback));
        final chosen = selectedList == 0 ? _namedLists : [_namedLists[selectedList - 1]];
        final rows = <Map<String, dynamic>>[];
        var missingHistory = 0;
        var unknownPrices = 0;
        var expiredCount = 0;
        for (final list in chosen) {
          final listTitle = (list['title'] ?? 'Adsız liste').toString();
          for (final item in (list['items'] as List? ?? const [])) {
            final name = item.toString();
            final unit = (_namedQuantity(list, name)['unit'] ?? 'Adet').toString();
            final stock = _namedStock(list, name);
            final onHand = _planNum(stock['amount']).clamp(0.0, double.infinity).toDouble();
            final expiry = _kitchenDaysUntil((stock['expiry'] ?? '').toString());
            final usable = expiry != null && expiry < 0 ? 0.0 : onHand;
            if (expiry != null && expiry < 0 && onHand > 0) expiredCount++;
            var consumed = 0.0;
            var movementCount = 0;
            DateTime? oldest;
            for (final movement in _stockMovements(list)) {
              if (movement['product']?.toString() != name || movement['reversed'] == true || !_isConsumptionMovement(movement)) continue;
              final date = _movementDate(movement);
              if (date == null || date.isBefore(start) || date.isAfter(now)) continue;
              final delta = _planNum(movement['change']);
              if (!delta.isFinite || delta >= 0) continue;
              consumed -= delta;
              movementCount++;
              if (oldest == null || date.isBefore(oldest)) oldest = date;
            }
            final observed = oldest == null ? 0.0 :
              (now.difference(oldest).inMinutes / 1440.0).clamp(1.0, lookback.toDouble());
            final daily = observed > 0 ? consumed / observed : 0.0;
            if (movementCount == 0) missingHistory++;
            final coverage = daily > 0 ? usable / daily : null;
            final minimum = _planNum(stock['minimum']).clamp(0.0, double.infinity).toDouble();
            final target = _planNum(stock['target']).clamp(0.0, double.infinity).toDouble();
            final forecastNeed = daily * (horizon + safetyDays + leadDays);
            final desired = [forecastNeed, minimum, target].reduce((a,b) => a > b ? a : b);
            final deficit = (desired - usable).clamp(0.0, double.infinity).toDouble();
            final costUnit = _stockUnitCost(list, name);
            final price = costUnit.isFinite && costUnit > 0 ? costUnit : null;
            if (deficit > 0 && price == null) unknownPrices++;
            final cost = price == null ? null : price * deficit;
            final reorderIn = coverage == null ? null : coverage - safetyDays - leadDays;
            final urgent = usable <= 0 || (reorderIn != null && reorderIn <= 0) || (expiry != null && expiry < 0);
            final reorderDate = reorderIn == null ? null : now.add(Duration(days: reorderIn.floor().clamp(0, 3650)));
            rows.add({'name':name,'list':listTitle,'unit':unit,'onHand':onHand,'usable':usable,
              'expiry':expiry,'daily':daily,'consumed':consumed,'movements':movementCount,
              'coverage':coverage,'deficit':deficit,'cost':cost,'price':price,
              'urgent':urgent,'reorderDate':reorderDate,'reorderIn':reorderIn});
          }
        }
        final filtered = rows.where((r) {
          if (!('${r['name']} ${r['list']}'.toLowerCase().contains(search.toLowerCase()))) return false;
          if (filter == 'Eksikler' && _planNum(r['deficit']) <= 0) return false;
          if (filter == 'Acil' && r['urgent'] != true) return false;
          if (filter == 'Geçmiş yok' && r['movements'] != 0) return false;
          if (filter == 'Fiyat yok' && (r['cost'] != null || _planNum(r['deficit']) <= 0)) return false;
          if (filter == 'Son kullanma' && r['expiry'] == null) { return false; }
          return true;
        }).toList();
        if (sort == 'Maliyet') filtered.sort((a,b) => _planNum(b['cost']).compareTo(_planNum(a['cost'])));
        if (sort == 'Stok günü') filtered.sort((a,b) => _planNum(a['coverage'] ?? 999999).compareTo(_planNum(b['coverage'] ?? 999999)));
        if (sort == 'Ürün') filtered.sort((a,b) => a['name'].toString().compareTo(b['name'].toString()));
        if (sort == 'Aciliyet') {
          filtered.sort((a,b) {
          final urgent = (b['urgent'] == true ? 1 : 0).compareTo(a['urgent'] == true ? 1 : 0);
          return urgent != 0 ? urgent : _planNum(a['coverage'] ?? 999999).compareTo(_planNum(b['coverage'] ?? 999999));
        });
        }
        final needed = rows.where((r) => _planNum(r['deficit']) > 0).toList();
        final pricedTotal = needed.fold<double>(0, (sum,r) => sum + _planNum(r['cost']));
        final urgentCount = rows.where((r) => r['urgent'] == true).length;
        final budgetGap = budget - pricedTotal;
        final visibleTotal = filtered.fold<double>(0, (sum,r) => sum + _planNum(r['cost']));
        return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
          child: SizedBox(height: MediaQuery.of(ctx).size.height * .91,
            child: ListView(padding: const EdgeInsets.all(16), children: [
              const Text('Akıllı stok yenileme / tüketim tahmini', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
              const SizedBox(height: 6),
              const Text('Gerçek stok tüketim hareketleri üzerinden tahmini ihtiyaç. Kayıtlar değiştirilmez.', style: TextStyle(fontSize: 12)),
              DropdownButtonFormField<int>(initialValue: selectedList,
                decoration: const InputDecoration(labelText: 'Stok listesi'),
                items: [const DropdownMenuItem(value: 0, child: Text('Tüm listeler')),
                  for (var i = 0; i < _namedLists.length; i++) DropdownMenuItem(value: i+1,
                    child: Text((_namedLists[i]['title'] ?? 'Adsız').toString(), overflow: TextOverflow.ellipsis))],
                onChanged: (v) => refresh(() => selectedList = v ?? 0)),
              Wrap(spacing: 8, runSpacing: 6, children: [
                for (final d in [30,60,90,180]) ChoiceChip(label: Text('$d gün geçmiş'), selected: lookback == d,
                  onSelected: (_) => refresh(() => lookback = d)),
                for (final d in [7,14,30]) ChoiceChip(label: Text('$d gün plan'), selected: horizon == d,
                  onSelected: (_) => refresh(() => horizon = d)),
              ]),
              Row(children: [const Expanded(child: Text('Güvenlik günü')),
                IconButton(onPressed: safetyDays == 0 ? null : () => refresh(() => safetyDays--), icon: const Icon(Icons.remove_circle_outline)),
                Text('$safetyDays'), IconButton(onPressed: () => refresh(() => safetyDays = (safetyDays+1).clamp(0,30)), icon: const Icon(Icons.add_circle_outline))]),
              Row(children: [const Expanded(child: Text('Tedarik süresi (gün)')),
                IconButton(onPressed: leadDays == 0 ? null : () => refresh(() => leadDays--), icon: const Icon(Icons.remove_circle_outline)),
                Text('$leadDays'), IconButton(onPressed: () => refresh(() => leadDays = (leadDays+1).clamp(0,30)), icon: const Icon(Icons.add_circle_outline))]),
              Row(children: [Expanded(child: Text('Bütçe: ${_money(budget)}')),
                IconButton(onPressed: () async {
                  final c = TextEditingController(text: budget.toStringAsFixed(0));
                  final v = await showDialog<double>(context: ctx, builder: (dialog) => AlertDialog(
                    title: const Text('Yenileme bütçesi'), content: TextField(controller: c,
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(labelText: 'TL')),
                    actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Vazgeç')),
                      TextButton(onPressed: () => Navigator.pop(dialog, double.tryParse(c.text.replaceAll(',', '.'))), child: const Text('Uygula'))]));
                  disposeAfterDialog(c);
                  if (v != null && v.isFinite && v >= 0) refresh(() => budget = v);
                }, icon: const Icon(Icons.edit_outlined))]),
              Card(color: const Color(0xFFF3E8FF), child: Padding(padding: const EdgeInsets.all(12),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('Ürün: ${rows.length}  •  Eksik: ${needed.length}  •  Acil: $urgentCount'),
                  Text('Fiyatı bilinen ihtiyaç: ${_money(pricedTotal)}', style: const TextStyle(fontWeight: FontWeight.bold)),
                  Text('Bütçe farkı: ${_money(budgetGap)}'),
                  if (budget > 0) LinearProgressIndicator(value: (pricedTotal/budget).clamp(0.0,1.0)),
                  Text('Tüketim geçmişi olmayan: $missingHistory  •  Fiyatı olmayan eksik: $unknownPrices'),
                  Text('Süresi geçmiş stok: $expiredCount'),
                  if (unknownPrices > 0) const Text('Fiyatı bilinmeyen ürünler toplam maliyete dahil değildir.', style: TextStyle(fontSize: 12)),
                ]))),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Ürün veya liste ara'),
                onChanged: (v) => refresh(() => search = v)),
              Wrap(spacing: 8, children: [
                DropdownButton<String>(value: filter, items: ['Tümü','Eksikler','Acil','Geçmiş yok','Fiyat yok','Son kullanma']
                  .map((v) => DropdownMenuItem(value:v,child:Text(v))).toList(), onChanged:(v)=>refresh(()=>filter=v??'Tümü')),
                DropdownButton<String>(value: sort, items: ['Aciliyet','Stok günü','Maliyet','Ürün']
                  .map((v) => DropdownMenuItem(value:v,child:Text(v))).toList(), onChanged:(v)=>refresh(()=>sort=v??'Aciliyet')),
              ]),
              Text('Görüntülenen: ${filtered.length}  •  Bilinen ihtiyaç maliyeti: ${_money(visibleTotal)}'),
              for (final r in filtered) Card(child: ListTile(
                leading: Icon(r['urgent'] == true ? Icons.warning_amber_outlined : Icons.inventory_2_outlined,
                  color: r['urgent'] == true ? Colors.deepOrange : _purple),
                title: Text('${r['name']} • ${r['list']}'),
                subtitle: Text('Stok: ${_planNumberText(_planNum(r['usable']))} ${r['unit']}  •  Tüketim/gün: ${_planNumberText(_planNum(r['daily']))}\n'
                  'Yeteceği gün: ${r['coverage'] == null ? 'Veri yok' : _planNumberText(_planNum(r['coverage']))}  •  Alınacak: ${_planNumberText(_planNum(r['deficit']))} ${r['unit']}\n'
                  'Sipariş tarihi: ${r['reorderDate'] == null ? 'Hesaplanamadı' : day(r['reorderDate'] as DateTime)}  •  Tahmini maliyet: ${r['cost'] == null ? 'Fiyat yok' : _money(_planNum(r['cost']))}\n'
                  'Tüketim kaydı: ${r['movements']}  •  SKT: ${r['expiry'] == null ? 'Bilinmiyor' : '${r['expiry']} gün'}'),
                isThreeLine: true,
              )),
              FilledButton.icon(icon: const Icon(Icons.copy_all_outlined), label: const Text('Yenileme raporunu CSV kopyala'),
                onPressed: () async {
                  final lines = <String>['Liste;Ürün;Birim;Stok;Kullanılabilir;Günlük tüketim;Stok günü;Önerilen miktar;Sipariş tarihi;Birim fiyat;Tahmini maliyet;Acil;Tüketim kaydı'];
                  for (final r in filtered) {
                    lines.add([r['list'],r['name'],r['unit'],r['onHand'],r['usable'],r['daily'],r['coverage'] ?? '',r['deficit'],
                      r['reorderDate'] == null ? '' : day(r['reorderDate'] as DateTime),r['price'] ?? '',r['cost'] ?? '',r['urgent'],r['movements']]
                      .map(csv).join(';'));
                  }
                  await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
                  _notice('Stok yenileme raporu kopyalandı.');
                }),
              const SizedBox(height: 8),
              const Text('Tahmin, seçilen dönemdeki kayıtlı tüketim hareketlerine dayanır. Tüketim kaydı yoksa hız sıfır varsayılır; gerçek talep farklı olabilir. Stok listeleri birbirinden bağımsız değerlendirilir.',
                style: TextStyle(fontSize: 12)),
            ]))));
      }));
  }


  void _showKitchenReplenishmentToList() {
    var listIndex = 0;
    var historyDays = 60;
    var horizon = 14;
    var safetyDays = 3;
    var leadDays = 2;
    var budget = 2500.0;
    var includeUnknown = false;
    var filter = 'Tümü';
    var sort = 'Aciliyet';
    var search = '';
    final excluded = <String>{};
    final priorities = <String, String>{};
    final selected = <String>{};
    var initialized = false;
    String fmt(DateTime d) => '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final from = now.subtract(Duration(days: historyDays));
        if (listIndex > _namedLists.length) listIndex = 0;
        final lists = listIndex == 0 ? _namedLists : [_namedLists[listIndex-1]];
        final rows = <Map<String,dynamic>>[];
        for (final list in lists) {
          final listName = (list['title'] ?? 'Adsız').toString();
          final listId = (list['id'] ?? listName).toString();
          for (final item in (list['items'] as List? ?? const [])) {
            final name = item.toString();
            final id = '$listId::$name';
            final unit = (_namedQuantity(list,name)['unit'] ?? 'adet').toString();
            final stock = _namedStock(list,name);
            final rawStock = _planNum(stock['amount']);
            final expiry = _kitchenDaysUntil((stock['expiry'] ?? '').toString());
            final usable = expiry != null && expiry < 0 ? 0.0 : rawStock.clamp(0.0,double.infinity).toDouble();
            var consumed = 0.0;
            var movements = 0;
            DateTime? first;
            for (final movement in _stockMovements(list)) {
              if (movement['product']?.toString() != name || movement['reversed'] == true || !_isConsumptionMovement(movement)) continue;
              final date = _movementDate(movement);
              if (date == null || date.isBefore(from) || date.isAfter(now)) continue;
              final delta = _planNum(movement['change']);
              if (!delta.isFinite || delta >= 0) continue;
              consumed -= delta;
              movements++;
              if (first == null || date.isBefore(first)) first = date;
            }
            final days = first == null ? 0.0 :
              (now.difference(first).inMinutes / 1440).clamp(1.0,historyDays.toDouble()).toDouble();
            final daily = days > 0 ? consumed/days : 0.0;
            final coverage = daily > 0 ? usable/daily : null;
            final minimum = _planNum(stock['minimum']).clamp(0.0,double.infinity).toDouble();
            final target = _planNum(stock['target']).clamp(0.0,double.infinity).toDouble();
            final predicted = daily * (horizon+safetyDays+leadDays);
            final desired = [predicted,minimum,target].reduce((a,b) => a > b ? a : b);
            final quantity = (desired-usable).clamp(0.0,double.infinity).toDouble();
            if (quantity <= 0 || !quantity.isFinite) continue;
            final unitCost = _stockUnitCost(list,name);
            final known = unitCost.isFinite && unitCost > 0;
            final cost = known ? quantity*unitCost : 0.0;
            final daysToOrder = coverage == null ? null : coverage-safetyDays-leadDays;
            final urgent = usable <= 0 || (daysToOrder != null && daysToOrder <= 0) || (expiry != null && expiry < 0);
            final date = daysToOrder == null ? null : now.add(Duration(days: daysToOrder.floor().clamp(0,3650)));
            rows.add({'id':id,'name':name,'list':listName,'unit':unit,'qty':quantity,
              'stock':usable,'daily':daily,'coverage':coverage,'date':date,'urgent':urgent,
              'known':known,'unitCost':known?unitCost:0.0,'cost':cost,'movements':movements,
              'expired':expiry != null && expiry < 0,'sourceId':listId});
          }
        }
        if (!initialized) {
          selected.addAll(rows.map((r)=>r['id'] as String));
          initialized = true;
        }
        final validIds = rows.map((r)=>r['id'] as String).toSet();
        selected.removeWhere((id)=>!validIds.contains(id));
        int rank(Map<String,dynamic> r) {
          final p = priorities[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal');
          return p=='Zorunlu'?0:p=='Normal'?1:2;
        }
        rows.sort((a,b) {
          final p=rank(a).compareTo(rank(b));
          if (p!=0) return p;
          if (sort=='Maliyet') return _planNum(b['cost']).compareTo(_planNum(a['cost']));
          if (sort=='Ürün') return a['name'].toString().compareTo(b['name'].toString());
          if (sort=='Sipariş tarihi') return (a['date'] as DateTime? ?? DateTime(9999)).compareTo(b['date'] as DateTime? ?? DateTime(9999));
          return (b['urgent']==true?1:0).compareTo(a['urgent']==true?1:0);
        });
        final eligible = rows.where((r)=>selected.contains(r['id']) && !excluded.contains(r['id']) && (includeUnknown || r['known']==true)).toList();
        final accepted = <Map<String,dynamic>>[];
        final deferred = <Map<String,dynamic>>[];
        var spent=0.0;
        for (final r in eligible) {
          final cost=_planNum(r['cost']);
          if (budget<=0 || spent+cost<=budget+0.00001) {
            accepted.add(r);
            spent+=cost;
          } else { deferred.add(r); }
        }
        final acceptedIds = accepted.map((r)=>r['id']).toSet();
        final visible=rows.where((r) {
          if (!'${r['name']} ${r['list']}'.toLowerCase().contains(search.toLowerCase())) return false;
          if (filter=='Seçilenler' && !acceptedIds.contains(r['id'])) return false;
          if (filter=='Ertelenenler' && acceptedIds.contains(r['id'])) return false;
          if (filter=='Acil' && r['urgent']!=true) return false;
          if (filter=='Fiyat yok' && r['known']==true) return false;
          return true;
        }).toList();
        final unknown=accepted.where((r)=>r['known']!=true).length;
        Future<void> create() async {
          if (accepted.isEmpty) { _notice('Listeye aktarılacak ürün bulunamadı.'); return; }
          final titleInput=TextEditingController(text:'Stok yenileme ${fmt(now)}');
          final title=await showDialog<String>(context:ctx,builder:(d)=>AlertDialog(
            title:const Text('Yenileme alışveriş listesi'),
            content:TextField(controller:titleInput,decoration:const InputDecoration(labelText:'Liste adı')),
            actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(d,titleInput.text.trim()),child:const Text('Oluştur'))]));
          disposeAfterDialog(titleInput);
          if (title==null || title.isEmpty || !mounted) return;
          final names=<String>[];
          final details=<String,dynamic>{};
          final prices=<String,dynamic>{};
          final priorityMeta=<String,dynamic>{};
          final origin=<String,dynamic>{};
          for (final r in accepted) {
            var name=r['name'] as String;
            if (names.contains(name)) name='$name (${r['list']})';
            if (names.contains(name)) { _notice('Tekrarlanan ürün adı: $name'); return; }
            names.add(name);
            details[name]={'amount':_planNumberText(_planNum(r['qty'])),'unit':r['unit']};
            if (r['known']==true) prices[name]=r['cost'];
            priorityMeta[name]=priorities[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal');
            origin[name]=r['sourceId'];
          }
          final record=<String,dynamic>{
            'id':DateTime.now().microsecondsSinceEpoch.toString(),
            'title':title,'updated':DateTime.now().toIso8601String(),
            'items':names,'done':<String>[], 'details':details,'prices':prices,
            'actualPrices':<String,dynamic>{},'budget':budget,
            'replenishmentPriorities':priorityMeta,'replenishmentSources':origin,
            'replenishmentEstimate':spent,'replenishmentHorizonDays':horizon,
            'replenishmentHistoryDays':historyDays,
            'replenishmentCreated':now.toIso8601String(),
          };
          setState(()=>_namedLists.insert(0,record));
          await _save();
          if (mounted) _notice('${names.length} ürün içeren “$title” oluşturuldu.');
          if (ctx.mounted) Navigator.pop(ctx);
        }
        final csvLines=<String>['Liste;Ürün;Birim;Miktar;Stok;Günlük tüketim;Sipariş tarihi;Öncelik;Birim fiyat;Tahmini maliyet;Durum'];
        for (final r in rows) {
          csvLines.add([r['list'],r['name'],r['unit'],r['qty'],r['stock'],r['daily'],
            r['date']==null?'':fmt(r['date'] as DateTime),
            priorities[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal'),
            r['known']==true?r['unitCost']:'',r['known']==true?r['cost']:'',
            acceptedIds.contains(r['id'])?'Seçildi':'Ertelendi'].map(csv).join(';'));
        }
        return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),
          child:SizedBox(height:MediaQuery.of(ctx).size.height*.94,child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Stok yenilemeden alışveriş listesi',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple)),
            const Text('Tüketim hareketlerine göre hesaplanan eksikleri bütçe ve önceliklerle listeye dönüştür. Stoklar değişmez.'),
            DropdownButtonFormField<int>(initialValue:listIndex,isExpanded:true,decoration:const InputDecoration(labelText:'Stok kaynağı'),
              items:[const DropdownMenuItem(value:0,child:Text('Tüm stok listeleri')),
                for(var i=0;i<_namedLists.length;i++) DropdownMenuItem(value:i+1,child:Text((_namedLists[i]['title']??'Adsız').toString(),overflow:TextOverflow.ellipsis))],
              onChanged:(v)=>refresh((){listIndex=v??0;initialized=false;selected.clear();excluded.clear();priorities.clear();})),
            Wrap(spacing:6,runSpacing:6,children:[
              for(final d in [30,60,90,180]) ChoiceChip(label:Text('$d gün geçmiş'),selected:historyDays==d,onSelected:(_)=>refresh(()=>historyDays=d)),
              for(final d in [7,14,30]) ChoiceChip(label:Text('$d gün ihtiyaç'),selected:horizon==d,onSelected:(_)=>refresh(()=>horizon=d)),
            ]),
            Row(children:[const Expanded(child:Text('Güvenlik günü')),
              IconButton(onPressed:safetyDays==0?null:()=>refresh(()=>safetyDays--),icon:const Icon(Icons.remove_circle_outline)),
              Text('$safetyDays'),IconButton(onPressed:()=>refresh(()=>safetyDays=(safetyDays+1).clamp(0,30)),icon:const Icon(Icons.add_circle_outline))]),
            Row(children:[const Expanded(child:Text('Tedarik süresi')),
              IconButton(onPressed:leadDays==0?null:()=>refresh(()=>leadDays--),icon:const Icon(Icons.remove_circle_outline)),
              Text('$leadDays'),IconButton(onPressed:()=>refresh(()=>leadDays=(leadDays+1).clamp(0,30)),icon:const Icon(Icons.add_circle_outline))]),
            TextFormField(initialValue:budget.toStringAsFixed(0),keyboardType:const TextInputType.numberWithOptions(decimal:true),
              decoration:const InputDecoration(labelText:'Bütçe (TL, 0 = sınırsız)'),
              onChanged:(v){final n=double.tryParse(v.replaceAll(',','.'));if(n!=null&&n.isFinite&&n>=0)refresh(()=>budget=n);}),
            SwitchListTile(title:const Text('Fiyatı bilinmeyen ürünleri dahil et'),value:includeUnknown,
              onChanged:(v)=>refresh(()=>includeUnknown=v)),
            Card(color:const Color(0xFFF3E8FF),child:Padding(padding:const EdgeInsets.all(12),child:Column(
              crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text('İhtiyaç: ${rows.length} • Seçilen: ${accepted.length} • Bütçeye sığmayan: ${deferred.length}'),
                Text('Tahmini maliyet: ${_money(spent)} • ${budget>0?'Kalan: ${_money(budget-spent)}':'Bütçe sınırı yok'}'),
                if(budget>0) LinearProgressIndicator(value:(spent/budget).clamp(0.0,1.0)),
                if(unknown>0) Text('$unknown ürünün fiyatı bilinmiyor; gerçek toplam daha yüksek olabilir.'),
                Text('Acil ihtiyaç: ${rows.where((r)=>r['urgent']==true).length} • Tüketim kaydı olmayan: ${rows.where((r)=>r['movements']==0).length}'),
              ]))),
            TextField(decoration:const InputDecoration(labelText:'Ürün veya liste ara',prefixIcon:Icon(Icons.search)),
              onChanged:(v)=>refresh(()=>search=v)),
            Wrap(spacing:8,children:[
              DropdownButton<String>(value:filter,items:['Tümü','Seçilenler','Ertelenenler','Acil','Fiyat yok'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),
                onChanged:(v)=>refresh(()=>filter=v??'Tümü')),
              DropdownButton<String>(value:sort,items:['Aciliyet','Maliyet','Ürün','Sipariş tarihi'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),
                onChanged:(v)=>refresh(()=>sort=v??'Aciliyet')),
            ]),
            Wrap(spacing:8,children:[
              OutlinedButton(onPressed:()=>refresh((){selected.addAll(rows.map((r)=>r['id'] as String));excluded.clear();}),child:const Text('Tümünü seç')),
              OutlinedButton(onPressed:()=>refresh(()=>selected.clear()),child:const Text('Seçimi kaldır')),
            ]),
            FilledButton.icon(onPressed:accepted.isEmpty?null:create,icon:const Icon(Icons.playlist_add),
              label:Text('${accepted.length} ürünle alışveriş listesi oluştur')),
            OutlinedButton.icon(onPressed:()async{
              await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));
              if(mounted)_notice('Yenileme planı CSV olarak kopyalandı.');
            },icon:const Icon(Icons.copy_outlined),label:const Text('Yenileme kararlarını CSV kopyala')),
            for(final r in visible) Card(child:Padding(padding:const EdgeInsets.all(8),child:Column(
              crossAxisAlignment:CrossAxisAlignment.start,children:[
                CheckboxListTile(contentPadding:EdgeInsets.zero,value:selected.contains(r['id'])&&!excluded.contains(r['id']),
                  onChanged:(v)=>refresh((){if(v==true){selected.add(r['id'] as String);excluded.remove(r['id']);}
                    else {selected.remove(r['id']);}}),
                  title:Text('${r['name']} • ${r['list']}'),
                  subtitle:Text('Alınacak: ${_planNumberText(_planNum(r['qty']))} ${r['unit']} • ${r['known']==true?_money(_planNum(r['cost'])):'Fiyat bilinmiyor'}\n'
                    'Stok: ${_planNumberText(_planNum(r['stock']))} • Tüketim/gün: ${_planNumberText(_planNum(r['daily']))}\n'
                    'Sipariş: ${r['date']==null?'Veri yok':fmt(r['date'] as DateTime)} • ${r['urgent']==true?'Acil':'Planlı'} • ${acceptedIds.contains(r['id'])?'Bütçede':'Ertelendi'}')),
                Row(children:[Expanded(child:DropdownButton<String>(isExpanded:true,
                  value:priorities[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal'),
                  items:['Zorunlu','Normal','Ertelenebilir'].map((p)=>DropdownMenuItem(value:p,child:Text(p))).toList(),
                  onChanged:(v)=>refresh(()=>priorities[r['id'] as String]=v??'Normal'))),
                  TextButton(onPressed:()=>refresh((){if(!excluded.add(r['id'] as String))excluded.remove(r['id']);}),
                    child:Text(excluded.contains(r['id'])?'Geri al':'Ertele'))]),
              ]))),
            const Text('Öneriler geçmiş stok hareketlerine dayanır. Fiyatı bilinmeyen ürünlerin maliyeti sıfır sayılır; stok ve tüketim kayıtları değiştirilmez.',style:TextStyle(fontSize:12)),
          ]))));
      }));
  }



  // Aşama 14398–14647: planlı stok siparişlerinin gerçekleşme ve gecikme takibi.
  // Yalnızca mevcut alışveriş listeleri ve marketPurchases verileri okunur.

  // Paket 14648–14897: kısmi alım ve geciken siparişler için aksiyon merkezi.
  // Sipariş kararları ilgili liste içinde saklanır; stok ve satın alma değişmez.


  // Aşama 15148–15397: satın alma performansından salt-okunur iyileştirme önerileri.
  void _showKitchenPurchaseImprovementAdvisor() {
    var period = 90;
    var category = 'Tümü';
    var severity = 'Tümü';
    var search = '';
    var onlyCritical = false;
    var minimumDelay = 2;
    var increaseThreshold = 15.0;
    var budget = 0.0;
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final cutoff = today.subtract(Duration(days: period));
        final issues = <Map<String, dynamic>>[];
        final repeated = <String, int>{};
        final priced = <String, List<double>>{};
        final records = <Map<String, dynamic>>[];
        var analyzed = 0;
        var purchased = 0;
        var totalExpected = 0.0;
        var totalPaid = 0.0;
        var knownRemaining = 0.0;
        var unknownRemaining = 0;
        void add(String type, String level, String list, String name, String detail, String advice, double impact, String date) {
          issues.add({'type':type,'level':level,'list':list,'name':name,'detail':detail,
            'advice':advice,'impact':impact,'date':date});
        }
        for (final record in _namedLists) {
          final rawDate = DateTime.tryParse((record['replenishmentOrderDate'] ?? '').toString());
          if (rawDate == null) continue;
          final due = DateTime(rawDate.year, rawDate.month, rawDate.day);
          if (due.isBefore(cutoff)) continue;
          final title = (record['title'] ?? 'Adsız liste').toString();
          final purchases = record['marketPurchases'] is Map ? record['marketPurchases'] as Map : <String,dynamic>{};
          final priorities = record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : <String,dynamic>{};
          final actions = record['replenishmentActions'] is Map ? record['replenishmentActions'] as Map : <String,dynamic>{};
          for (final rawName in (record['items'] as List? ?? const [])) {
            final name = rawName.toString();
            final q = _namedQuantity(record, name);
            final planned = _planNum(q['amount']);
            final unit = (q['unit'] ?? 'adet').toString().trim().toLowerCase();
            final purchase = purchases[name] is Map ? purchases[name] as Map : <String,dynamic>{};
            final bought = _planNum(purchase['quantity']).clamp(0.0, double.infinity).toDouble();
            final left = (planned - bought).clamp(0.0, double.infinity).toDouble();
            final paid = _planNum(purchase['total']);
            final expected = _namedItemTotal(record, name);
            final action = actions[name] is Map ? actions[name] as Map : <String,dynamic>{};
            final priority = (action['priority'] ?? priorities[name] ?? 'Normal').toString();
            final next = DateTime.tryParse((action['nextDate'] ?? '').toString());
            final target = next == null ? due : DateTime(next.year, next.month, next.day);
            final late = left > 0 && target.isBefore(today) ? today.difference(target).inDays : 0;
            final dateText = '${target.day.toString().padLeft(2,'0')}.${target.month.toString().padLeft(2,'0')}.${target.year}';
            final key = '${name.toLowerCase().trim()}|$unit';
            analyzed++;
            if (bought > 0) purchased++;
            if (expected > 0) totalExpected += expected;
            if (purchase.isNotEmpty) totalPaid += paid;
            if (left > 0) {
              repeated[key] = (repeated[key] ?? 0) + 1;
              if (expected > 0 && planned > 0) {
                knownRemaining += expected * left / planned;
              } else { unknownRemaining++; }
            }
            records.add({'key':key,'name':name,'unit':unit,'list':title,'priority':priority,
              'left':left,'late':late,'bought':bought,'planned':planned,'expected':expected,
              'paid':paid,'date':dateText,'store':(purchase['store'] ?? '').toString()});
            if (left > 0 && late >= minimumDelay) {
              add('Gecikme', priority == 'Zorunlu' ? 'Kritik' : 'Yüksek', title, name,
                '$late gün gecikme • kalan ${left.toStringAsFixed(1)} $unit',
                'Alışveriş tarihini güncelleyin; zorunlu ürünleri ilk sıraya alın.',
                expected > 0 && planned > 0 ? expected * left / planned : 0, dateText);
            }
            if (bought > 0 && left > 0) {
              add('Kısmi alım', priority == 'Zorunlu' ? 'Yüksek' : 'Orta', title, name,
                'Alınan ${bought.toStringAsFixed(1)} / plan ${planned.toStringAsFixed(1)} $unit',
                'Kalan miktar için bağımsız takip listesi oluşturun.',
                expected > 0 && planned > 0 ? expected * left / planned : 0, dateText);
            }
            if (priority == 'Zorunlu' && left > 0 && late < minimumDelay) {
              add('Kritik stok', 'Kritik', title, name, 'Zorunlu ürün • kalan ${left.toStringAsFixed(1)} $unit',
                'Yaklaşan alışverişte öncelik verin ve stok yeterliliğini kontrol edin.',
                expected > 0 && planned > 0 ? expected * left / planned : 0, dateText);
            }
            if (expected <= 0 && left > 0) {
              add('Eksik fiyat', 'Orta', title, name, 'Kalan miktar için tahmini fiyat bulunmuyor.',
                'Market fiyatını kaydederek bütçe tahminini tamamlayın.', 0, dateText);
            }
            if (planned > 0 && bought > 0 && expected > 0 && paid > 0) {
              final plannedPart = expected * bought.clamp(0.0, planned) / planned;
              final increase = plannedPart > 0 ? (paid / plannedPart - 1) * 100 : 0.0;
              if (increase >= increaseThreshold) {
                add('Fiyat sapması', increase >= increaseThreshold * 2 ? 'Yüksek' : 'Orta', title, name,
                  'Alınan miktarın plan fiyatına göre +%${increase.toStringAsFixed(1)}',
                  'Aynı birimde alternatif market fiyatlarını karşılaştırın.', paid - plannedPart, dateText);
              }
            }
            if (bought > 0 && paid > 0 && unit.isNotEmpty) {
              priced.putIfAbsent(key, () => <double>[]).add(paid / bought);
            }
          }
        }
        for (final row in records) {
          final key = row['key'].toString();
          if (_planNum(row['left']) > 0 && (repeated[key] ?? 0) >= 2) {
            add('Tekrarlayan eksik', row['priority'] == 'Zorunlu' ? 'Kritik' : 'Yüksek',
              row['list'].toString(), row['name'].toString(),
              'Son $period günde ${repeated[key]} ayrı listede açık ihtiyaç.',
              'Güvenlik stoğu, tüketim hızı ve alışveriş sıklığını gözden geçirin.',
              0, row['date'].toString());
          }
          final prices = priced[key] ?? const <double>[];
          if (prices.length >= 2 && _planNum(row['left']) > 0) {
            final low = prices.reduce((a,b) => a < b ? a : b);
            final high = prices.reduce((a,b) => a > b ? a : b);
            if (low > 0 && high > low * (1 + increaseThreshold / 100)) {
              add('Fiyat fırsatı', 'Orta', row['list'].toString(), row['name'].toString(),
                'Kayıtlı birim fiyat aralığı: ${_money(low)} – ${_money(high)} / ${row['unit']}',
                'Güncelliği doğrulayarak düşük fiyatlı marketi değerlendirin.',
                (high - low) * _planNum(row['left']), row['date'].toString());
            }
          }
        }
        if (budget > 0 && knownRemaining > budget) {
          add('Bütçe', 'Kritik', 'Tüm listeler', 'Açık ihtiyaç bütçesi',
            'Bilinen açık ihtiyaç ${_money(knownRemaining)} • bütçe ${_money(budget)}',
            'Zorunlu ürünleri önceleyin; ertelenebilir ürünleri ayrı değerlendirin.',
            knownRemaining - budget, '');
        }
        final visible = issues.where((r) =>
          (category == 'Tümü' || r['type'] == category) &&
          (severity == 'Tümü' || r['level'] == severity) &&
          (!onlyCritical || r['level'] == 'Kritik') &&
          '${r['name']} ${r['list']} ${r['detail']} ${r['advice']}'.toLowerCase().contains(search.toLowerCase())).toList();
        const levels = {'Kritik':0,'Yüksek':1,'Orta':2};
        visible.sort((a,b) {
          final byLevel = (levels[a['level']] ?? 9).compareTo(levels[b['level']] ?? 9);
          return byLevel != 0 ? byLevel : _planNum(b['impact']).compareTo(_planNum(a['impact']));
        });
        final types = issues.map((r) => r['type'].toString()).toSet().toList()..sort();
        final csvLines = <String>[
          ['Kategori','Önem','Liste','Ürün','Durum','Öneri','Tahmini etki TL','Hedef tarih'].map(csv).join(','),
          for (final r in visible) [r['type'],r['level'],r['list'],r['name'],r['detail'],r['advice'],r['impact'],r['date']].map(csv).join(',')
        ];
        return SafeArea(child: FractionallySizedBox(heightFactor:.94,child:Padding(
          padding:const EdgeInsets.all(14),child:ListView(children:[
            Row(children:[Expanded(child:Text('Satın alma iyileştirme asistanı',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
            const Text('Gecikme, kısmi alım, tekrarlayan eksik, fiyat sapması ve bütçe risklerini kayıtlı satın almalardan değerlendirir. Öneriler otomatik işlem yapmaz.',style:TextStyle(fontSize:12)),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<int>(value:period,items:[30,60,90,180,365].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>period=v??90)),
              DropdownButton<int>(value:minimumDelay,items:[1,2,3,7,14].map((v)=>DropdownMenuItem(value:v,child:Text('Gecikme ≥ $v gün'))).toList(),onChanged:(v)=>refresh(()=>minimumDelay=v??2)),
              DropdownButton<double>(value:increaseThreshold,items:[5.0,10.0,15.0,20.0,30.0].map((v)=>DropdownMenuItem(value:v,child:Text('Fiyat sapması ≥ %${v.toInt()}'))).toList(),onChanged:(v)=>refresh(()=>increaseThreshold=v??15)),
              FilterChip(label:const Text('Yalnız kritik'),selected:onlyCritical,onSelected:(v)=>refresh(()=>onlyCritical=v)),
            ]),
            TextFormField(initialValue:budget==0?'':budget.toStringAsFixed(0),keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Açık ihtiyaçlar için bütçe (TL, isteğe bağlı)'),onChanged:(v)=>refresh(()=>budget=_planNum(v))),
            Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('İncelenen $analyzed kalem • Alım yapılan $purchased',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('İyileştirme bulgusu: ${issues.length} • Kritik: ${issues.where((r)=>r['level']=='Kritik').length}'),
              Text('Bilinen açık ihtiyaç maliyeti: ${_money(knownRemaining)}'),
              Text('Fiyatı eksik açık ihtiyaç: $unknownRemaining'),
              Text('Bilinen plan tutarı: ${_money(totalExpected)} • Kaydedilen ödeme: ${_money(totalPaid)}'),
              if(budget>0) Text('Açık ihtiyaç bütçe farkı: ${_money(budget-knownRemaining)}'),
            ]))),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<String>(value:category,items:['Tümü',...types].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>category=v??'Tümü')),
              DropdownButton<String>(value:severity,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text('Önem: $v'))).toList(),onChanged:(v)=>refresh(()=>severity=v??'Tümü')),
            ]),
            TextField(decoration:const InputDecoration(labelText:'Ürün, liste veya öneri ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
            Text('Gösterilen ${visible.length} / ${issues.length} bulgu',style:const TextStyle(fontWeight:FontWeight.bold)),
            if(visible.isEmpty) const Padding(padding:EdgeInsets.all(12),child:Text('Seçilen filtrelerde bulgu bulunamadı.')),
            for(final r in visible) Card(child:ListTile(
              leading:Icon(r['level']=='Kritik'?Icons.priority_high:Icons.lightbulb_outline,color:r['level']=='Kritik'?Colors.red:_purple),
              title:Text('${r['name']} • ${r['type']}',style:const TextStyle(fontWeight:FontWeight.bold)),
              subtitle:Text('${r['list']} • ${r['level']}\n${r['detail']}\nÖneri: ${r['advice']}${_planNum(r['impact'])>0?'\nGösterge: ${_money(_planNum(r['impact']))}':''}'),
              isThreeLine:true,
            )),
            FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));if(mounted)_notice('${visible.length} öneri CSV olarak kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Filtrelenmiş önerileri CSV kopyala')),
            const Text('Not: Tahmini etkiler birbirinden bağımsız fırsat/risk göstergeleridir; toplanarak garanti tasarruf sayılmaz. Kayıtlı fiyatların güncel olması garanti değildir. Bu ekran hiçbir liste, satın alma veya stok kaydını değiştirmez.',style:TextStyle(fontSize:12)),
          ]))));
      }));
  }


  // Aşama 15398–15647: iyileştirme bulgularından kalıcı, kullanıcı onaylı aksiyonlar.
  void _showKitchenImprovementActionPlans() {
    const storageKey = 'paket39_purchase_improvement_actions_v1';
    final plans = <Map<String, dynamic>>[];
    var ready = false;
    var query = '';
    var statusFilter = 'Tümü';
    var levelFilter = 'Tümü';
    var sort = 'Hedef tarih';
    var includeCompleted = true;
    String day(DateTime? d) => d == null ? '—' : '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    Future<void> persist() async {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(storageKey, jsonEncode(plans));
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder: (_) =>
      StatefulBuilder(builder:(ctx,refresh) {
        if (!ready) {
          ready = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final decoded = jsonDecode(prefs.getString(storageKey) ?? '[]');
              if (decoded is List) {
                plans..clear()..addAll(decoded.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
              }
            } catch (_) { if(mounted) _notice('Aksiyon kayıtları okunamadı; veriler değiştirilmedi.'); }
            if(ctx.mounted) refresh((){});
          });
        }
        final now=DateTime.now();
        final today=DateTime(now.year,now.month,now.day);
        final visible=plans.where((p) {
          final status=(p['status']??'Açık').toString();
          if (!includeCompleted && status=='Tamamlandı') return false;
          if(statusFilter!='Tümü' && statusFilter!=status) return false;
          if(levelFilter!='Tümü' && levelFilter!=p['level']) return false;
          return '${p['title']} ${p['product']} ${p['source']} ${p['note']} ${p['owner']}'
              .toLowerCase().contains(query.toLowerCase());
        }).toList();
        int rank(String value) => value=='Kritik'?0:value=='Yüksek'?1:2;
        visible.sort((a,b) {
          if(sort=='Önem') return rank(a['level'].toString()).compareTo(rank(b['level'].toString()));
          if(sort=='Oluşturma') return (b['created']??'').toString().compareTo((a['created']??'').toString());
          if(sort=='Başlık') return (a['title']??'').toString().compareTo((b['title']??'').toString());
          return (a['due']??'9999').toString().compareTo((b['due']??'9999').toString());
        });
        final open=plans.where((p)=>p['status']!='Tamamlandı').length;
        final done=plans.length-open;
        final overdue=plans.where((p) {
          final d=DateTime.tryParse((p['due']??'').toString());
          return p['status']!='Tamamlandı' && d!=null && DateTime(d.year,d.month,d.day).isBefore(today);
        }).length;
        final csvRows=<String>[
          ['Başlık','Ürün','Kaynak','Önem','Durum','Sorumlu','Hedef','Oluşturma','Tamamlanma','Not'].map(csv).join(','),
          for(final p in visible) [p['title'],p['product'],p['source'],p['level'],p['status'],p['owner'],p['due'],p['created'],p['completed'],p['note']].map(csv).join(',')
        ];
        Future<void> edit({Map<String,dynamic>? existing}) async {
          final title=TextEditingController(text:(existing?['title']??'').toString());
          final product=TextEditingController(text:(existing?['product']??'').toString());
          final source=TextEditingController(text:(existing?['source']??'').toString());
          final owner=TextEditingController(text:(existing?['owner']??'').toString());
          final note=TextEditingController(text:(existing?['note']??'').toString());
          var level=(existing?['level']??'Orta').toString();
          if(!['Kritik','Yüksek','Orta'].contains(level)) level='Orta';
          var status=(existing?['status']??'Açık').toString();
          if(!['Açık','Devam ediyor','Beklemede','Tamamlandı'].contains(status)) status='Açık';
          var due=DateTime.tryParse((existing?['due']??'').toString()) ?? today.add(const Duration(days:7));
          final accepted=await showDialog<bool>(context:ctx,builder:(dialogCtx)=>StatefulBuilder(builder:(dialogCtx,update)=>AlertDialog(
            title:Text(existing==null?'Yeni iyileştirme aksiyonu':'Aksiyonu düzenle'),
            content:SizedBox(width:440,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
              TextField(controller:title,maxLength:120,decoration:const InputDecoration(labelText:'Aksiyon başlığı *')),
              TextField(controller:product,decoration:const InputDecoration(labelText:'Ürün / konu')),
              TextField(controller:source,decoration:const InputDecoration(labelText:'Kaynak liste / bulgu')),
              TextField(controller:owner,decoration:const InputDecoration(labelText:'Sorumlu (isteğe bağlı)')),
              DropdownButtonFormField<String>(initialValue:level,decoration:const InputDecoration(labelText:'Önem'),items:['Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>level=v??level)),
              DropdownButtonFormField<String>(initialValue:status,decoration:const InputDecoration(labelText:'Durum'),items:['Açık','Devam ediyor','Beklemede','Tamamlandı'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>status=v??status)),
              ListTile(contentPadding:EdgeInsets.zero,title:Text('Hedef tarih: ${day(due)}'),trailing:const Icon(Icons.event),onTap:()async {
                final picked=await showDatePicker(context:dialogCtx,initialDate:due,firstDate:DateTime(2020),lastDate:DateTime(2100));
                if(picked!=null) update(()=>due=picked);
              }),
              TextField(controller:note,maxLines:3,decoration:const InputDecoration(labelText:'Aksiyon notu / karar')),
            ]))),actions:[TextButton(onPressed:()=>Navigator.pop(dialogCtx,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(dialogCtx,title.text.trim().isNotEmpty),child:const Text('Kaydet'))])));
          if(accepted==true && ctx.mounted) {
            final previous=existing?['status']?.toString();
            final entry=<String,dynamic>{
              'id':existing?['id']??DateTime.now().microsecondsSinceEpoch.toString(),
              'title':title.text.trim(),'product':product.text.trim(),'source':source.text.trim(),
              'owner':owner.text.trim(),'note':note.text.trim(),'level':level,'status':status,
              'due':'${due.year}-${due.month.toString().padLeft(2,'0')}-${due.day.toString().padLeft(2,'0')}',
              'created':existing?['created']??DateTime.now().toIso8601String(),
              'completed': status == 'Tamamlandı' ? (previous == 'Tamamlandı' ? (existing?['completed'] ?? DateTime.now().toIso8601String()) : DateTime.now().toIso8601String()) : '',
            };
            refresh(() { if(existing==null) {plans.insert(0,entry);} else {final i=plans.indexOf(existing);if(i>=0)plans[i]=entry;} });
            await persist();
            if(mounted) _notice('İyileştirme aksiyonu kaydedildi.');
          }
          disposeAfterDialog(title);disposeAfterDialog(product);disposeAfterDialog(source);disposeAfterDialog(owner);disposeAfterDialog(note);
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:Padding(padding:const EdgeInsets.all(14),child:ListView(children:[
          Row(children:[Expanded(child:Text('İyileştirme aksiyon planları',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Satın alma risk analizindeki önerilerden bağımsız, kullanıcı onaylı aksiyonlar oluşturun. Kayıtlı satın alma ve stoklar değişmez.',style:TextStyle(fontSize:12)),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Toplam ${plans.length} • Açık $open • Tamamlanan $done • Geciken $overdue',style:const TextStyle(fontWeight:FontWeight.bold)),
            LinearProgressIndicator(value:plans.isEmpty?0:done/plans.length,color:_purple),
            Text('Tamamlanma: ${plans.isEmpty?0:(100*done/plans.length).round()}%'),
          ]))),
          FilledButton.icon(onPressed:()=>edit(),icon:const Icon(Icons.add_task),label:const Text('Yeni aksiyon oluştur')),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Aksiyon, ürün, sorumlu veya kaynak ara'),onChanged:(v)=>refresh(()=>query=v)),
          Wrap(spacing:8,runSpacing:8,children:[
            DropdownButton<String>(value:statusFilter,items:['Tümü','Açık','Devam ediyor','Beklemede','Tamamlandı'].map((v)=>DropdownMenuItem(value:v,child:Text('Durum: $v'))).toList(),onChanged:(v)=>refresh(()=>statusFilter=v??'Tümü')),
            DropdownButton<String>(value:levelFilter,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text('Önem: $v'))).toList(),onChanged:(v)=>refresh(()=>levelFilter=v??'Tümü')),
            DropdownButton<String>(value:sort,items:['Hedef tarih','Önem','Oluşturma','Başlık'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'Hedef tarih')),
            FilterChip(label:const Text('Tamamlananları göster'),selected:includeCompleted,onSelected:(v)=>refresh(()=>includeCompleted=v)),
          ]),
          if(visible.isEmpty) const Padding(padding:EdgeInsets.all(12),child:Text('Henüz bu filtreye uygun aksiyon yok. Yeni aksiyon ekleyebilirsiniz.')),
          for(final p in visible) Card(child:Column(children:[ListTile(
            leading:Icon(p['status']=='Tamamlandı'?Icons.check_circle:Icons.assignment_outlined,color:p['status']=='Tamamlandı'?Colors.green:_purple),
            title:Text((p['title']??'').toString(),style:const TextStyle(fontWeight:FontWeight.bold)),
            subtitle:Text('${p['product']} • ${p['level']} • ${p['status']}\nHedef: ${p['due']} • Sorumlu: ${p['owner']}\n${p['note']}',maxLines:5),
            isThreeLine:true,onTap:()=>edit(existing:p),
          ),Wrap(spacing:6,children:[
            TextButton.icon(onPressed:()=>edit(existing:p),icon:const Icon(Icons.edit_outlined),label:const Text('Düzenle')),
            TextButton.icon(onPressed:()async {
              final next=Map<String,dynamic>.from(p);
              final complete=p['status']!='Tamamlandı';
              next['status']=complete?'Tamamlandı':'Açık';
              next['completed']=complete?DateTime.now().toIso8601String():'';
              refresh(() {final i=plans.indexOf(p);if(i>=0)plans[i]=next;});
              await persist();
            },icon:Icon(p['status']=='Tamamlandı'?Icons.undo:Icons.check),label:Text(p['status']=='Tamamlandı'?'Yeniden aç':'Tamamla')),
            TextButton.icon(onPressed:()async {
              final confirmed=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Aksiyon silinsin mi?'),content:Text((p['title']??'').toString()),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),TextButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Sil'))]));
              if(confirmed==true){refresh(()=>plans.remove(p));await persist();}
            },icon:const Icon(Icons.delete_outline),label:const Text('Sil')),
          ])])),
          FilledButton.tonalIcon(onPressed:()async {await Clipboard.setData(ClipboardData(text:'\uFEFF${csvRows.join('\r\n')}'));if(mounted)_notice('${visible.length} aksiyon CSV olarak kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Filtrelenmiş aksiyonları CSV kopyala')),
          const Text('Not: Bu aksiyonlar cihazdaki ayrı yerel kayıt alanında saklanır. Genel JSON yedeklemesine henüz dahil değildir; CSV kopyası ayrıca alınabilir.',style:TextStyle(fontSize:12)),
        ]))));
      }));
  }

  void _showKitchenPurchaseCompletionPerformance() {
    var period = 90;
    var search = '';
    var statusFilter = 'Tümü';
    var priorityFilter = 'Tümü';
    var sourceFilter = 'Tümü';
    var sort = 'Gecikme';
    var group = 'Liste';
    var includeUndated = false;
    var onlyWithPurchases = false;
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    String day(DateTime? d) => d == null ? '—' : '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final cutoff = today.subtract(Duration(days: period));
        final rows = <Map<String, dynamic>>[];
        final sources = <String>{};
        for (final record in _namedLists) {
          final rawDate = DateTime.tryParse((record['replenishmentOrderDate'] ?? '').toString());
          if (rawDate == null && !includeUndated) continue;
          final due = rawDate == null ? null : DateTime(rawDate.year, rawDate.month, rawDate.day);
          if (due != null && due.isBefore(cutoff)) continue;
          final title = (record['title'] ?? 'Adsız liste').toString();
          sources.add(title);
          final purchases = record['marketPurchases'] is Map ? record['marketPurchases'] as Map : <String, dynamic>{};
          final priorities = record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : <String, dynamic>{};
          final actions = record['replenishmentActions'] is Map ? record['replenishmentActions'] as Map : <String, dynamic>{};
          for (final rawName in (record['items'] as List? ?? const [])) {
            final name = rawName.toString();
            final quantity = _namedQuantity(record, name);
            final planned = _planNum(quantity['amount']).clamp(0.0, double.infinity).toDouble();
            final unit = (quantity['unit'] ?? 'Adet').toString();
            final rawPurchase = purchases[name];
            final purchase = rawPurchase is Map ? rawPurchase : <String, dynamic>{};
            final bought = _planNum(purchase['quantity']).clamp(0.0, double.infinity).toDouble();
            final effectiveBought = planned > 0 ? bought.clamp(0.0, planned).toDouble() : 0.0;
            final left = (planned - effectiveBought).clamp(0.0, double.infinity).toDouble();
            final progress = planned > 0 ? effectiveBought / planned : 0.0;
            final paid = _planNum(purchase['total']).clamp(0.0, double.infinity).toDouble();
            final expected = _namedItemTotal(record, name);
            final action = actions[name] is Map ? actions[name] as Map : <String, dynamic>{};
            final rescheduled = DateTime.tryParse((action['nextDate'] ?? '').toString());
            final target = rescheduled == null ? due : DateTime(rescheduled.year, rescheduled.month, rescheduled.day);
            final lateDays = target != null && left > 0 && target.isBefore(today) ? today.difference(target).inDays : 0;
            final status = planned <= 0 ? 'Miktar eksik' : left <= 0 ? 'Tamamlandı' : bought > 0 ? 'Kısmi' : lateDays > 0 ? 'Gecikti' : 'Bekliyor';
            final priority = (action['priority'] ?? priorities[name] ?? 'Normal').toString();
            final store = (purchase['store'] ?? '').toString().trim();
            rows.add({'name':name,'list':title,'due':due,'target':target,'late':lateDays,
              'planned':planned,'bought':bought,'effectiveBought':effectiveBought,'left':left,
              'unit':unit,'progress':progress,'paid':paid,'expected':expected,
              'priority':priority,'status':status,'store':store.isEmpty ? 'Market belirtilmedi' : store,
              'purchased':rawPurchase is Map,'transferred':purchase['stockTransferred']==true,
              'rescheduled':rescheduled!=null,'note':(action['note'] ?? '').toString()});
          }
        }
        final selected = rows.where((r) =>
          (sourceFilter == 'Tümü' || r['list'] == sourceFilter) &&
          (priorityFilter == 'Tümü' || r['priority'] == priorityFilter) &&
          (!onlyWithPurchases || r['purchased'] == true)).toList();
        final completed = selected.where((r) => r['status'] == 'Tamamlandı').length;
        final partial = selected.where((r) => r['status'] == 'Kısmi').length;
        final delayed = selected.where((r) => (r['late'] as int) > 0).length;
        final criticalPending = selected.where((r) => r['priority'] == 'Zorunlu' && _planNum(r['left']) > 0).length;
        final totalPlannedUnits = selected.fold<double>(0, (sum, r) => sum + _planNum(r['planned']));
        final totalBoughtUnits = selected.fold<double>(0, (sum, r) => sum + _planNum(r['effectiveBought']));
        final knownExpected = selected.where((r) => _planNum(r['expected']) > 0).fold<double>(0, (sum, r) => sum + _planNum(r['expected']));
        final unknownPrices = selected.where((r) => _planNum(r['expected']) <= 0).length;
        final paidTotal = selected.fold<double>(0, (sum, r) => sum + _planNum(r['paid']));
        final comparableExpected = selected.where((r) => r['purchased'] == true && _planNum(r['planned']) > 0 && _planNum(r['expected']) > 0)
          .fold<double>(0, (sum, r) => sum + _planNum(r['expected']) * _planNum(r['effectiveBought']) / _planNum(r['planned']));
        final comparablePaid = selected.where((r) => r['purchased'] == true && _planNum(r['planned']) > 0 && _planNum(r['expected']) > 0)
          .fold<double>(0, (sum, r) => sum + _planNum(r['paid']));
        final storeTotals = <String, Map<String, double>>{};
        for (final r in selected.where((r) => r['purchased'] == true)) {
          final name = r['store'].toString();
          final metrics = storeTotals.putIfAbsent(name, () => {'paid':0.0,'lines':0.0,'completed':0.0,'quantity':0.0});
          metrics['paid'] = metrics['paid']! + _planNum(r['paid']);
          metrics['lines'] = metrics['lines']! + 1;
          metrics['quantity'] = metrics['quantity']! + _planNum(r['effectiveBought']);
          if (r['status'] == 'Tamamlandı') metrics['completed'] = metrics['completed']! + 1;
        }
        final storeRank = storeTotals.entries.toList()..sort((a,b) => b.value['paid']!.compareTo(a.value['paid']!));
        final visible = selected.where((r) =>
          (statusFilter == 'Tümü' || r['status'] == statusFilter ||
            (statusFilter == 'Gecikenler' && (r['late'] as int) > 0) ||
            (statusFilter == 'Kritik eksik' && r['priority'] == 'Zorunlu' && _planNum(r['left']) > 0)) &&
          '${r['name']} ${r['list']} ${r['store']} ${r['note']}'.toLowerCase().contains(search.toLowerCase())).toList();
        visible.sort((a,b) {
          if (sort == 'Tamamlanma') return _planNum(a['progress']).compareTo(_planNum(b['progress']));
          if (sort == 'Harcama') return _planNum(b['paid']).compareTo(_planNum(a['paid']));
          if (sort == 'Ürün') return a['name'].toString().compareTo(b['name'].toString());
          if (sort == 'Hedef tarih') return (a['target'] as DateTime? ?? DateTime(2100)).compareTo(b['target'] as DateTime? ?? DateTime(2100));
          return (b['late'] as int).compareTo(a['late'] as int);
        });
        final grouped = <String, List<Map<String,dynamic>>>{};
        for (final r in visible) {
          final key = group == 'Market' ? r['store'].toString() : group == 'Öncelik' ? r['priority'].toString() : r['list'].toString();
          grouped.putIfAbsent(key, () => <Map<String,dynamic>>[]).add(r);
        }
        final csvLines = <String>[
          ['Liste','Ürün','Birim','Planlanan','Alınan','Kalan','Tamamlanma %','Durum','Öncelik','Orijinal tarih','Hedef tarih','Gecikme gün','Market','Planlanan TL','Ödenen TL','Stoğa aktarıldı'].map(csv).join(','),
          for (final r in visible) [r['list'],r['name'],r['unit'],r['planned'],r['bought'],r['left'],(_planNum(r['progress'])*100).toStringAsFixed(1),r['status'],r['priority'],day(r['due'] as DateTime?),day(r['target'] as DateTime?),r['late'],r['store'],r['expected'],r['paid'],r['transferred'] == true ? 'Evet' : 'Hayır'].map(csv).join(',')
        ];
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Padding(
          padding: const EdgeInsets.all(14), child: ListView(children: [
            Row(children:[Expanded(child:Text('Satın alma tamamlama performansı',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
            const Text('Stok yenileme listelerindeki planlanan miktarlar, gerçek alımlar, gecikmeler ve market performansı. Analiz yalnızca kayıtlı verileri okur.',style:TextStyle(fontSize:12)),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<int>(value:period,items:[30,60,90,180,365,730].map((d)=>DropdownMenuItem(value:d,child:Text('Son $d gün'))).toList(),onChanged:(v)=>refresh(()=>period=v??90)),
              FilterChip(label:const Text('Tarihsiz listeler'),selected:includeUndated,onSelected:(v)=>refresh(()=>includeUndated=v)),
              FilterChip(label:const Text('Yalnız satın alınanlar'),selected:onlyWithPurchases,onSelected:(v)=>refresh(()=>onlyWithPurchases=v)),
            ]),
            DropdownButtonFormField<String>(initialValue:sourceFilter,isExpanded:true,decoration:const InputDecoration(labelText:'Alışveriş listesi'),items:[const DropdownMenuItem(value:'Tümü',child:Text('Tüm listeler')),...(sources.toList()..sort()).map((v)=>DropdownMenuItem(value:v,child:Text(v,overflow:TextOverflow.ellipsis)))],onChanged:(v)=>refresh(()=>sourceFilter=v??'Tümü')),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<String>(value:priorityFilter,items:['Tümü','Zorunlu','Normal','Ertelenebilir'].map((v)=>DropdownMenuItem(value:v,child:Text('Öncelik: $v'))).toList(),onChanged:(v)=>refresh(()=>priorityFilter=v??'Tümü')),
              DropdownButton<String>(value:statusFilter,items:['Tümü','Tamamlandı','Kısmi','Gecikti','Bekliyor','Miktar eksik','Gecikenler','Kritik eksik'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>statusFilter=v??'Tümü')),
            ]),
            Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Sipariş kalemi: ${selected.length} • Tamamlanan: $completed • Kısmi: $partial',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Tamamlama oranı: ${selected.isEmpty ? '—' : '${(completed*100/selected.length).toStringAsFixed(1)}%'}'),
              LinearProgressIndicator(value:selected.isEmpty?0:completed/selected.length),
              const SizedBox(height:8),
              Text('Geciken kalem: $delayed • Kritik eksik: $criticalPending'),
              Text('Planlanan miktar toplamı: ${totalPlannedUnits.toStringAsFixed(1)} • Alınan: ${totalBoughtUnits.toStringAsFixed(1)} (farklı birimler karışık olabilir)'),
              Text('Planlanan maliyet (bilinen): ${_money(knownExpected)} • Gerçek ödeme: ${_money(paidTotal)}'),
              Text('Karşılaştırılabilir alınan miktarın plan maliyeti: ${_money(comparableExpected)}'),
              Text('Karşılaştırılabilir gerçekleşen ödeme: ${_money(comparablePaid)}'),
              Text('Fark (plan − gerçek): ${_money(comparableExpected-comparablePaid)}'),
              Text('Fiyatı bilinmeyen: $unknownPrices • Stoğa aktarılan: ${selected.where((r)=>r['transferred']==true).length}'),
            ]))),
            const SizedBox(height:8),
            Text('Market performansı',style:TextStyle(fontWeight:FontWeight.bold,color:_purple)),
            if(storeRank.isEmpty) const Text('Henüz kayıtlı satın alma yok.'),
            for (final entry in storeRank.take(15)) ListTile(dense:true,title:Text(entry.key),subtitle:Text('${entry.value['lines']!.toInt()} satın alma kalemi • ${entry.value['completed']!.toInt()} tamamlandı'),trailing:Text(_money(entry.value['paid']!))),
            const Divider(),
            TextField(decoration:const InputDecoration(labelText:'Ürün, liste, market veya not ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
            Wrap(spacing:8,children:[
              DropdownButton<String>(value:sort,items:['Gecikme','Tamamlanma','Harcama','Ürün','Hedef tarih'].map((v)=>DropdownMenuItem(value:v,child:Text('Sırala: $v'))).toList(),onChanged:(v)=>refresh(()=>sort=v??'Gecikme')),
              DropdownButton<String>(value:group,items:['Liste','Market','Öncelik'].map((v)=>DropdownMenuItem(value:v,child:Text('Grupla: $v'))).toList(),onChanged:(v)=>refresh(()=>group=v??'Liste')),
            ]),
            Text('Görüntülenen ${visible.length} / ${selected.length}',style:const TextStyle(fontWeight:FontWeight.bold)),
            for(final entry in grouped.entries) ...[
              Padding(padding:const EdgeInsets.only(top:10,bottom:4),child:Text('${entry.key} (${entry.value.length})',style:TextStyle(fontWeight:FontWeight.bold,color:_purple))),
              for(final r in entry.value) Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Row(children:[Expanded(child:Text(r['name'].toString(),style:const TextStyle(fontWeight:FontWeight.bold))),Text(r['status'].toString())]),
                Text('Plan ${_planNumberText(_planNum(r['planned']))} ${r['unit']} • Alınan ${_planNumberText(_planNum(r['bought']))} • Kalan ${_planNumberText(_planNum(r['left']))}'),
                LinearProgressIndicator(value:_planNum(r['progress']).clamp(0.0,1.0).toDouble()),
                Text('Hedef: ${day(r['target'] as DateTime?)} • Gecikme: ${r['late']} gün • ${r['priority']}'),
                Text('${r['store']} • Plan: ${_money(_planNum(r['expected']))} • Ödenen: ${_money(_planNum(r['paid']))}'),
                if(r['rescheduled']==true) const Text('Yeniden planlandı',style:TextStyle(fontSize:12)),
              ]))),
            ],
            FilledButton.tonalIcon(onPressed:() async {await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));if(mounted)_notice('${visible.length} satırlık CSV kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Filtrelenmiş performansı CSV kopyala')),
            const Text('Not: Gecikme, açık kalan miktar ve güncel hedef tarih üzerinden hesaplanır. Market bazında teslimat hızı ölçülmez; yalnız satın alma kalemi, tamamlanma ve harcama gösterilir. Farklı ölçü birimlerindeki miktarlar karşılaştırılmamalıdır.',style:TextStyle(fontSize:12)),
          ]))));
      }));
  }


  // Aşama 15648–15897: satın alma bulgularından onaylı aksiyon üretimi ve performans.
  void _showKitchenImprovementActionBridge() {
    const key = 'paket39_purchase_improvement_actions_v1';
    final actions = <Map<String,dynamic>>[];
    var loading = true;
    var period = 90;
    var minDelay = 2;
    var threshold = 15.0;
    var filter = 'Tümü';
    var search = '';
    var onlyNew = false;
    var includeClosed = false;
    var selected = <String>{};
    String quote(Object? x) => '"${(x ?? '').toString().replaceAll('"','""')}"';
    String signature(String type,String list,String product) =>
      '${type.trim().toLowerCase()}|${list.trim().toLowerCase()}|${product.trim().toLowerCase()}';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>
      StatefulBuilder(builder:(ctx,refresh) {
        if(loading) {
          loading=false;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final decoded=jsonDecode(prefs.getString(key)??'[]');
              if(decoded is List) {
                actions..clear()..addAll(decoded.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
              }
            } catch (_) { if(mounted) _notice('Aksiyon kayıtları okunamadı. Yeni kayıt oluşturulmadı.'); }
            if(ctx.mounted) refresh((){});
          });
        }
        final now=DateTime.now();
        final today=DateTime(now.year,now.month,now.day);
        final cutoff=today.subtract(Duration(days:period));
        final findings=<Map<String,dynamic>>[];
        void add(String type,String level,String list,String product,String detail,String advice,double impact) {
          final id=signature(type,list,product);
          if(findings.any((r)=>r['id']==id)) return;
          findings.add({'id':id,'type':type,'level':level,'list':list,'product':product,
            'detail':detail,'advice':advice,'impact':impact});
        }
        final frequency=<String,int>{};
        final openRows=<Map<String,dynamic>>[];
        for(final record in _namedLists) {
          final date=DateTime.tryParse((record['replenishmentOrderDate']??'').toString());
          if(date==null || date.isBefore(cutoff)) continue;
          final list=(record['title']??'Adsız liste').toString();
          final purchases=record['marketPurchases'] is Map ? record['marketPurchases'] as Map : <String,dynamic>{};
          final priorities=record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : <String,dynamic>{};
          final reschedules=record['replenishmentActions'] is Map ? record['replenishmentActions'] as Map : <String,dynamic>{};
          for(final raw in (record['items'] as List? ?? const [])) {
            final product=raw.toString();
            final planned=_planNum(_namedQuantity(record,product)['amount']);
            if(planned<=0) continue;
            final purchase=purchases[product] is Map ? purchases[product] as Map : <String,dynamic>{};
            final bought=_planNum(purchase['quantity']).clamp(0.0,planned).toDouble();
            final remaining=(planned-bought).clamp(0.0,double.infinity).toDouble();
            final adjustment=reschedules[product] is Map ? reschedules[product] as Map : <String,dynamic>{};
            final due=DateTime.tryParse((adjustment['nextDate']??'').toString())??date;
            final delay=remaining>0 && due.isBefore(today) ? today.difference(DateTime(due.year,due.month,due.day)).inDays : 0;
            final priority=(adjustment['priority']??priorities[product]??'Normal').toString();
            final expected=_namedItemTotal(record,product);
            final paid=_planNum(purchase['total']);
            final unit=(_namedQuantity(record,product)['unit']??'adet').toString();
            if(remaining>0) {
              final frequencyKey='${product.trim().toLowerCase()}|${unit.trim().toLowerCase()}';
              frequency[frequencyKey]=(frequency[frequencyKey]??0)+1;
              openRows.add({'list':list,'product':product,'unit':unit,'priority':priority,
                'remaining':remaining,'frequencyKey':frequencyKey});
              if(delay>=minDelay) {
                add('Gecikme',priority=='Zorunlu'?'Kritik':'Yüksek',list,product,
                '$delay gün gecikme; kalan ${remaining.toStringAsFixed(1)} $unit',
                'Satın alma tarihini güncelle ve açık miktarı takip et.',expected>0?expected*remaining/planned:0);
              }
              if(bought>0) {
                add('Kısmi alım',priority=='Zorunlu'?'Yüksek':'Orta',list,product,
                '${bought.toStringAsFixed(1)} / ${planned.toStringAsFixed(1)} $unit alındı',
                'Kalan ${remaining.toStringAsFixed(1)} $unit için alışveriş planı oluştur.',expected>0?expected*remaining/planned:0);
              }
              if(priority=='Zorunlu') {
                add('Kritik ihtiyaç','Kritik',list,product,
                'Zorunlu ihtiyaç; ${remaining.toStringAsFixed(1)} $unit açık',
                'Öncelikli satın alma ve stok güvenlik seviyesini değerlendir.',0);
              }
              if(expected<=0) {
                add('Fiyat eksik','Orta',list,product,
                'Planlanan maliyet kaydı yok', 'Market fiyatını güncelle.',0);
              }
            }
            if(bought>0 && paid>0 && expected>0) {
              final comparable=expected*bought/planned;
              if(comparable>0 && paid>comparable*(1+threshold/100)) {
                add('Fiyat sapması','Yüksek',list,product,
                  'Planlanan ${_money(comparable)}; ödenen ${_money(paid)}',
                  'Alternatif market fiyatlarını karşılaştır.',paid-comparable);
              }
            }
          }
        }
        for(final r in openRows) {
          final count=frequency[r['frequencyKey']]??0;
          if(count>=2) {
            add('Tekrarlayan eksik',r['priority']=='Zorunlu'?'Kritik':'Yüksek',
            r['list'].toString(),r['product'].toString(),
            '$period günde $count ayrı listede açık ihtiyaç',
            'Güvenlik stoğunu ve satın alma sıklığını gözden geçir.',0);
          }
        }
        String actionSignature(Map<String,dynamic> a) {
          final stored=(a['findingKey']??'').toString();
          if(stored.isNotEmpty) return stored;
          return signature((a['findingType']??'').toString(),
            (a['source']??'').toString(),(a['product']??'').toString());
        }
        final matched=<String,Map<String,dynamic>>{};
        for(final a in actions) {
          final sig=actionSignature(a);
          if(sig.isNotEmpty && (a['findingKey']!=null || a['findingType']!=null)) matched[sig]=a;
        }
        final visible=findings.where((r) {
          if(filter!='Tümü' && r['level']!=filter && r['type']!=filter) return false;
          if(onlyNew && matched.containsKey(r['id'])) return false;
          if(!includeClosed && matched[r['id']]?['status']=='Tamamlandı') return false;
          return '${r['type']} ${r['list']} ${r['product']} ${r['detail']}'.toLowerCase().contains(search.toLowerCase());
        }).toList()..sort((a,b) {
          const rank={'Kritik':0,'Yüksek':1,'Orta':2};
          final n=(rank[a['level']]??3).compareTo(rank[b['level']]??3);
          return n!=0?n:_planNum(b['impact']).compareTo(_planNum(a['impact']));
        });
        final linked=actions.where((a)=>a['findingKey']!=null).toList();
        final completed=linked.where((a)=>a['status']=='Tamamlandı').toList();
        final overdue=linked.where((a) {
          final d=DateTime.tryParse((a['due']??'').toString());
          return a['status']!='Tamamlandı' && d!=null && d.isBefore(today);
        }).length;
        final durationDays=<int>[];
        for(final a in completed) {
          final start=DateTime.tryParse((a['created']??'').toString());
          final end=DateTime.tryParse((a['completed']??'').toString());
          if(start!=null && end!=null && !end.isBefore(start)) durationDays.add(end.difference(start).inDays);
        }
        final avg=durationDays.isEmpty?null:durationDays.reduce((a,b)=>a+b)/durationDays.length;
        final csvLines=<String>[
          ['Tür','Önem','Liste','Ürün','Bulgu','Öneri','Etki TL','Aksiyon durumu'].map(quote).join(','),
          for(final r in visible) [r['type'],r['level'],r['list'],r['product'],r['detail'],r['advice'],r['impact'],matched[r['id']]?['status']??'Aktarılmadı'].map(quote).join(',')
        ];
        Future<void> createSelected() async {
          final candidates=findings.where((r)=>selected.contains(r['id']) && !matched.containsKey(r['id'])).toList();
          if(candidates.isEmpty) { _notice('Aktarılabilecek yeni öneri seçilmedi.');return; }
          final confirmed=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(
            title:const Text('Aksiyon planına aktar'),
            content:Text('${candidates.length} öneri yeni aksiyon olarak kaydedilecek. Mevcut aksiyonlar korunacak.'),
            actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla'))]));
          if(confirmed!=true) return;
          final stamp=DateTime.now().toIso8601String();
          final fresh=<Map<String,dynamic>>[];
          for(final r in candidates) {
            if(actions.any((a)=>actionSignature(a)==r['id'])) continue;
            final due=today.add(Duration(days:r['level']=='Kritik'?1:r['level']=='Yüksek'?3:7));
            fresh.add({'id':'auto_${DateTime.now().microsecondsSinceEpoch}_${fresh.length}',
              'title':'${r['type']}: ${r['product']}','product':r['product'],
              'source':r['list'],'owner':'','level':r['level'],'status':'Açık',
              'due':due.toIso8601String().substring(0,10),'created':stamp,
              'completed':'','note':'${r['detail']}\nÖneri: ${r['advice']}',
              'findingKey':r['id'],'findingType':r['type']});
          }
          if(fresh.isEmpty) return;
          try {
            final prefs=await SharedPreferences.getInstance();
            final latest=jsonDecode(prefs.getString(key)??'[]');
            if(latest is! List) throw const FormatException('Geçersiz aksiyon kaydı');
            final merged=latest.whereType<Map>().map((a)=>Map<String,dynamic>.from(a)).toList();
            for(final a in fresh) {
              if(!merged.any((old)=>actionSignature(old)==a['findingKey'])) merged.add(a);
            }
            await prefs.setString(key,jsonEncode(merged));
            actions..clear()..addAll(merged);
            selected.clear();
            if(ctx.mounted) refresh((){});
            if(mounted) _notice('${fresh.length} öneri aksiyon planına aktarıldı.');
          } catch (_) { if(mounted) _notice('Aktarım kaydedilemedi; mevcut aksiyonlar korunuyor.'); }
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:Padding(
          padding:const EdgeInsets.all(14),child:ListView(children:[
            Row(children:[Expanded(child:Text('Öneriden aksiyona / performans',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),
              IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
            const Text('Kayıtlı siparişlerden kurallı bulgular üretir. Seçilenleri onayla aksiyona dönüştürür; aynı bulgu için ikinci aksiyon oluşturmaz.',style:TextStyle(fontSize:12)),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<int>(value:period,items:[30,60,90,180,365].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>period=v??90)),
              DropdownButton<int>(value:minDelay,items:[1,2,3,7,14].map((v)=>DropdownMenuItem(value:v,child:Text('Gecikme ≥ $v'))).toList(),onChanged:(v)=>refresh(()=>minDelay=v??2)),
              DropdownButton<double>(value:threshold,items:[5.0,10.0,15.0,20.0,30.0].map((v)=>DropdownMenuItem(value:v,child:Text('Fiyat ≥ %${v.toInt()}'))).toList(),onChanged:(v)=>refresh(()=>threshold=v??15)),
            ]),
            Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Bulgu: ${findings.length} • Aksiyona bağlı: ${findings.where((r)=>matched.containsKey(r['id'])).length}',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Aktarılan toplam: ${linked.length} • Tamamlanan: ${completed.length} • Açık: ${linked.length-completed.length}'),
              LinearProgressIndicator(value:linked.isEmpty?0:completed.length/linked.length),
              Text('Geciken aksiyon: $overdue • Tamamlanma oranı: ${linked.isEmpty?'—':'%${(completed.length*100/linked.length).toStringAsFixed(1)}'}'),
              Text('Ortalama tamamlanma: ${avg==null?'Veri yok':'${avg.toStringAsFixed(1)} gün'}'),
              Text('Süre ölçümü yapılabilen tamamlanmış aksiyon: ${durationDays.length}'),
            ]))),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<String>(value:filter,items:['Tümü','Kritik','Yüksek','Orta','Gecikme','Kısmi alım','Kritik ihtiyaç','Fiyat eksik','Fiyat sapması','Tekrarlayan eksik'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>filter=v??'Tümü')),
              FilterChip(label:const Text('Yalnız aktarılmayan'),selected:onlyNew,onSelected:(v)=>refresh(()=>onlyNew=v)),
              FilterChip(label:const Text('Tamamlananları göster'),selected:includeClosed,onSelected:(v)=>refresh(()=>includeClosed=v)),
            ]),
            TextField(decoration:const InputDecoration(labelText:'Ürün, liste veya bulgu ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
            Row(children:[Text('Gösterilen: ${visible.length}',style:const TextStyle(fontWeight:FontWeight.bold)),const Spacer(),
              TextButton(onPressed:()=>refresh((){selected={...selected,...visible.where((r)=>!matched.containsKey(r['id'])).map((r)=>r['id'].toString())};}),child:const Text('Yeni olanları seç')),
              TextButton(onPressed:()=>refresh(()=>selected.clear()),child:const Text('Temizle'))]),
            if(visible.isEmpty) const Text('Bu filtrelerde bulgu bulunamadı.'),
            for(final r in visible) Card(child:CheckboxListTile(
              value:selected.contains(r['id']),
              onChanged:matched.containsKey(r['id'])?null:(v)=>refresh((){if(v==true){selected.add(r['id'].toString());}else{selected.remove(r['id']);}}),
              title:Text('${r['product']} • ${r['type']}',style:const TextStyle(fontWeight:FontWeight.bold)),
              subtitle:Text('${r['list']} • ${r['level']}\n${r['detail']}\n${r['advice']}\nAksiyon: ${matched[r['id']]?['status']??'Henüz aktarılmadı'}'),
              secondary:Icon(matched.containsKey(r['id'])?Icons.check_circle_outline:Icons.add_task,color:_purple),
              controlAffinity:ListTileControlAffinity.leading,isThreeLine:true)),
            FilledButton.icon(onPressed:createSelected,icon:const Icon(Icons.playlist_add_check),label:Text('Seçilenleri aksiyon planına aktar (${selected.where((id)=>!matched.containsKey(id)).length})')),
            FilledButton.tonalIcon(onPressed:() {Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt),label:const Text('Aksiyon planlarını aç / düzenle')),
            FilledButton.tonalIcon(onPressed:()async {await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));if(mounted)_notice('Bulgular CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Bulguları CSV kopyala')),
            const Text('Not: Analiz yalnızca kayıtlı alışverişlere dayanır. Aksiyonlar onayla oluşturulur; stok ve satın alma kayıtları değişmez. Tamamlanma süreleri oluşturma ve tamamlama tarihlerine dayanır.',style:TextStyle(fontSize:12)),
          ]))));
      }));
  }



  // Birleşik operasyon paneli: kayıtları yalnızca okur; mevcut veriyi değiştirmez.

  // Birleşik risk öncelik merkezi: mevcut kayıtları yalnızca okur.
  void _showKitchenCriticalRiskCenter() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const historyKey = 'kitchen_risk_tracking_v1';
    final tracking = <String, Map<String,dynamic>>{};
    var trackingError = false;
    var statusFilter = 'Aktif';
    var onlyUnlinked = false;
    final actions = <Map<String, dynamic>>[];
    var loaded = false;
    var search = '';
    var category = 'Tümü';
    var severity = 'Tümü';
    var showResolved = false;
    var horizon = 14;
    var sort = 'Öncelik';
    String quote(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!loaded) {
          loaded = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final saved=jsonDecode(prefs.getString(historyKey)??'{}');
              if(saved is Map) {
                for(final e in saved.entries) {
                  if(e.value is Map) tracking[e.key.toString()]=Map<String,dynamic>.from(e.value as Map);
                }
              }
            } catch (_) { trackingError=true; }
            try {
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (raw is List) {
                actions..clear()..addAll(raw.whereType<Map>().map((a) => Map<String, dynamic>.from(a)));
              }
            } catch (_) {
              if (mounted) _notice('Aksiyon kayıtları okunamadı.');
            }
            if (ctx.mounted) refresh(() {});
          });
        }
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final month = _monthKey();
        final risks = <Map<String, dynamic>>[];
        void add(String type, String level, String title, String detail,
            String recommendation, {String source = '', int days = 0, double cost = 0, bool resolved = false}) {
          risks.add({'type':type,'level':level,'title':title,'detail':detail,
            'recommendation':recommendation,'source':source,'days':days,
            'cost':cost,'resolved':resolved});
        }
        for (final record in _namedLists) {
          final listTitle = (record['title'] ?? 'Adsız liste').toString();
          final due = DateTime.tryParse((record['replenishmentOrderDate'] ?? '').toString());
          final dueDay = due == null ? null : DateTime(due.year, due.month, due.day);
          final purchases = record['marketPurchases'] is Map ? record['marketPurchases'] as Map : const <String, dynamic>{};
          final priorities = record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : const <String, dynamic>{};
          for (final item in (record['items'] as List? ?? const [])) {
            final name = item.toString();
            final planned = _planNum(_namedQuantity(record, name)['amount']);
            final purchase = purchases[name] is Map ? purchases[name] as Map : const <String, dynamic>{};
            final bought = _planNum(purchase['quantity']);
            final remaining = (planned - bought).clamp(0.0, double.infinity).toDouble();
            final unit = (_namedQuantity(record, name)['unit'] ?? 'adet').toString();
            final priority = (priorities[name] ?? 'Normal').toString();
            final dayDiff = dueDay?.difference(today).inDays;
            if (remaining > 0 && dayDiff != null && dayDiff < 0) {
              add('Geciken satın alma',priority=='Zorunlu'?'Kritik':'Yüksek',name,
                '${-dayDiff} gün gecikti • Kalan ${remaining.toStringAsFixed(2)} $unit',
                'Kalan miktarı yeniden planla ve satın alma aksiyonu oluştur.',
                source:listTitle,days:-dayDiff,cost:_namedItemTotal(record,name));
            } else if (remaining > 0 && dayDiff != null && dayDiff <= horizon) {
              add('Yaklaşan satın alma',priority=='Zorunlu'?'Yüksek':'Orta',name,
                dayDiff==0?'Bugün planlandı • Kalan ${remaining.toStringAsFixed(2)} $unit':'$dayDiff gün kaldı • Kalan ${remaining.toStringAsFixed(2)} $unit',
                'Alışveriş planını ve mevcut stok miktarını kontrol et.',
                source:listTitle,days:dayDiff,cost:_namedItemTotal(record,name));
            }
            if (bought > 0 && remaining > 0) {
              add('Kısmi satın alma',priority=='Zorunlu'?'Yüksek':'Orta',name,
                'Alınan ${bought.toStringAsFixed(2)} / ${planned.toStringAsFixed(2)} $unit',
                'Kalan miktarı takip listesine ekle.',source:listTitle,
                cost:_namedItemTotal(record,name));
            }
            final stock = _namedStock(record,name);
            final available = _planNum(stock['amount']);
            final expiryDays = _kitchenDaysUntil((stock['expiry'] ?? '').toString());
            if (expiryDays != null && available > 0 && expiryDays < 0) {
              add('Son kullanma tarihi','Kritik',name,
                '${-expiryDays} gün önce süresi doldu • ${available.toStringAsFixed(2)} $unit',
                'Ürünü tüketmeden önce güvenlik açısından kontrol et; stok kaydını gözden geçir.',
                source:listTitle,days:-expiryDays);
            } else if (expiryDays != null && available > 0 && expiryDays <= horizon) {
              add('Son kullanma tarihi',expiryDays<=2?'Yüksek':'Orta',name,
                expiryDays==0?'Son kullanım günü bugün':'$expiryDays gün içinde son kullanım',
                'Tüketim planını ve saklama koşullarını kontrol et.',source:listTitle,days:expiryDays);
            }
            if (priority=='Zorunlu' && remaining>0 && dueDay==null) {
              add('Tarihsiz kritik ihtiyaç','Yüksek',name,
                '${remaining.toStringAsFixed(2)} $unit eksik • Sipariş tarihi yok',
                'Kritik ürün için hedef satın alma tarihi belirle.',source:listTitle);
            }
            if (remaining>0 && _namedItemTotal(record,name)<=0) {
              add('Eksik fiyat','Orta',name,'Açık ihtiyaç için tahmini fiyat bulunamadı.',
                'Market fiyatı ekleyerek bütçe tahminini tamamla.',source:listTitle);
            }
          }
        }
        final budget = _monthlyBudgets[month] ?? 0;
        final spent = _monthlyTotals()[month] ?? 0;
        if (budget>0 && spent>budget) {
          add('Bütçe','Kritik','Aylık alışveriş bütçesi',
            'Bütçe ${_money(budget)} • Harcama ${_money(spent)} • Aşım ${_money(spent-budget)}',
            'Ertelenebilir alışverişleri gözden geçir ve kalan planları yeniden bütçele.',
            source:month,cost:spent-budget);
        } else if (budget>0 && spent>=budget*.85) {
          add('Bütçe','Yüksek','Aylık bütçe kullanım uyarısı',
            'Kullanım %${(100*spent/budget).toStringAsFixed(1)} • Kalan ${_money(budget-spent)}',
            'Yaklaşan alışverişleri kalan bütçeye göre önceliklendir.',source:month);
        }
        for (final action in actions) {
          final title = (action['title'] ?? 'Başlıksız aksiyon').toString();
          final status = (action['status'] ?? 'Açık').toString();
          final done = status=='Tamamlandı';
          final due = DateTime.tryParse((action['due'] ?? '').toString());
          final dueDay = due==null?null:DateTime(due.year,due.month,due.day);
          final delta = dueDay?.difference(today).inDays;
          if (done) {
            add('İyileştirme aksiyonu','Orta',title,'Tamamlandı',
              'Tamamlanan aksiyon kaydı.',source:(action['owner']??'').toString(),resolved:true);
          } else if (delta!=null && delta<0) {
            add('İyileştirme aksiyonu',(action['level']??'Orta')=='Kritik'?'Kritik':'Yüksek',title,
              '${-delta} gün gecikti • $status',
              'Hedef tarihi, sorumluyu ve aksiyon durumunu gözden geçir.',
              source:(action['owner']??'').toString(),days:-delta);
          } else if (delta!=null && delta<=horizon) {
            add('İyileştirme aksiyonu',(action['level']??'Orta').toString(),title,
              delta==0?'Hedef tarih bugün • $status':'Hedefe $delta gün • $status',
              'Hedef tarih öncesinde ilerlemeyi kontrol et.',
              source:(action['owner']??'').toString(),days:delta);
          }
        }
        String riskId(Map<String,dynamic> r) => jsonEncode([r['type'],r['title'],r['source']]);
        String stateOf(Map<String,dynamic> r) {
          final t=tracking[riskId(r)];
          if(t==null) return 'Yeni';
          if(t['status']=='Çözüldü') return 'Çözüldü';
          final until=DateTime.tryParse((t['snoozeUntil']??'').toString());
          if(until!=null && until.isAfter(DateTime.now())) return 'Ertelendi';
          return 'Aktif';
        }
        Future<bool> saveTracking() async {
          try {
            final prefs=await SharedPreferences.getInstance();
            final ok=await prefs.setString(historyKey,jsonEncode(tracking));
            if(!ok) throw const FormatException('Kayıt başarısız');
            return true;
          } catch (_) { if(mounted) _notice('Uyarı geçmişi kaydedilemedi.'); return false; }
        }
        Future<void> changeRisk(Map<String,dynamic> r,String state,{int snooze=0}) async {
          if(trackingError) { if(mounted) _notice('Uyarı geçmişi okunamadı; kayıt yapılmadı.'); return; }
          final id=riskId(r);
          final old=tracking[id]==null?null:Map<String,dynamic>.from(tracking[id]!);
          final entry=tracking.putIfAbsent(id,()=>{'firstSeen':DateTime.now().toIso8601String(),'events':<dynamic>[]});
          entry['status']=state;
          entry['lastUpdated']=DateTime.now().toIso8601String();
          entry['snoozeUntil']=snooze>0?DateTime.now().add(Duration(days:snooze)).toIso8601String():'';
          entry['title']=r['title']; entry['type']=r['type']; entry['source']=r['source'];
          entry['events']=[...(entry['events'] is List?entry['events'] as List:const []),{'at':DateTime.now().toIso8601String(),'event':snooze>0?'$snooze gün ertelendi':state}];
          if(!await saveTracking()) {if(old==null){tracking.remove(id);}else{tracking[id]=old;}return;}
          if(ctx.mounted) refresh((){});
        }
        Future<void> makeAction(Map<String,dynamic> r) async {
          final id=riskId(r);
          if(trackingError) {if(mounted)_notice('Uyarı geçmişi okunamadı.');return;}
          try {
            final prefs=await SharedPreferences.getInstance();
            final raw=jsonDecode(prefs.getString(actionKey)??'[]');
            if(raw is! List) throw const FormatException('Aksiyon listesi hatalı');
            final latest=raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
            if(latest.any((a)=>a['riskKey']==id)) {if(mounted)_notice('Bu uyarı için aksiyon zaten var.');return;}
            final now=DateTime.now();
            final due=now.add(Duration(days:r['level']=='Kritik'?1:r['level']=='Yüksek'?3:7));
            latest.add({'id':'risk_${now.microsecondsSinceEpoch}','title':'${r['type']}: ${r['title']}',
              'product':r['title'],'source':r['source'],'owner':'','level':r['level'],
              'status':'Açık','due':due.toIso8601String().substring(0,10),
              'created':now.toIso8601String(),'completed':'',
              'note':'${r['detail']}\nÖneri: ${r['recommendation']}', 'riskKey':id});
            if(!await prefs.setString(actionKey,jsonEncode(latest))) throw const FormatException('Kaydedilemedi');
            actions..clear()..addAll(latest);
            final old=tracking[id]==null?null:Map<String,dynamic>.from(tracking[id]!);
            final t=tracking.putIfAbsent(id,()=>{'firstSeen':now.toIso8601String(),'events':<dynamic>[]});
            t['actionCreated']=now.toIso8601String();
            t['events']=[...(t['events'] is List?t['events'] as List:const []),{'at':now.toIso8601String(),'event':'Aksiyon oluşturuldu'}];
            if(!await saveTracking()) {if(old==null){tracking.remove(id);}else{tracking[id]=old;}}
            if(ctx.mounted) refresh((){});
            if(mounted) _notice('Uyarı aksiyon planına aktarıldı.');
          } catch (_) {if(mounted)_notice('Aksiyon oluşturulamadı; kayıtları kontrol edin.');}
        }
        int rank(String level) => level=='Kritik'?0:level=='Yüksek'?1:2;
        final filtered = risks.where((r) {
          if (!showResolved && r['resolved']==true) return false;
          final st=stateOf(r);
          if(statusFilter=='Aktif' && (st=='Çözüldü'||st=='Ertelendi')) return false;
          if(statusFilter=='Ertelendi' && st!='Ertelendi') return false;
          if(statusFilter=='Çözüldü' && st!='Çözüldü') return false;
          if(onlyUnlinked && actions.any((a)=>a['riskKey']==riskId(r))) return false;
          if (category!='Tümü' && r['type']!=category) return false;
          if (severity!='Tümü' && r['level']!=severity) return false;
          return '${r['title']} ${r['detail']} ${r['source']} ${r['recommendation']}'
            .toLowerCase().contains(search.toLowerCase());
        }).toList();
        filtered.sort((a,b) {
          if (sort=='Başlık') return (a['title'] as String).compareTo(b['title'] as String);
          if (sort=='Kategori') return (a['type'] as String).compareTo(b['type'] as String);
          if (sort=='Maliyet') return (b['cost'] as double).compareTo(a['cost'] as double);
          final n=rank(a['level'] as String).compareTo(rank(b['level'] as String));
          return n!=0?n:(a['title'] as String).compareTo(b['title'] as String);
        });
        final openRisks = risks.where((r)=>r['resolved']!=true).toList();
        final critical = openRisks.where((r)=>r['level']=='Kritik').length;
        final high = openRisks.where((r)=>r['level']=='Yüksek').length;
        final overdue = openRisks.where((r)=>r['type']=='Geciken satın alma' ||
          (r['type']=='İyileştirme aksiyonu' && (r['detail'] as String).contains('gecikti'))).length;
        final types = <String>{for(final r in risks) r['type'] as String}.toList()..sort();
        final csvLines = <String>[
          ['Kategori','Önem','Başlık','Kaynak','Durum','Detay','Öneri','Gün','Tahmini tutar','Aksiyon bağlı','İlk görülme','Son güncelleme'].map(quote).join(','),
          for(final r in filtered) [r['type'],r['level'],r['title'],r['source'],
            stateOf(r),r['detail'],r['recommendation'],r['days'],r['cost'],actions.any((a)=>a['riskKey']==riskId(r))?'Evet':'Hayır',tracking[riskId(r)]?['firstSeen'],tracking[riskId(r)]?['lastUpdated']].map(quote).join(','),
        ];
        Widget summary(String label, String value, IconData icon) => Card(color:_pink,
          child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Icon(icon,color:_purple),
            const SizedBox(width:8),Expanded(child:Text(label)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold))])));
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(
          padding:const EdgeInsets.all(16),children:[
          const Text('Kritik Uyarılar ve Operasyonel Öncelikler',
            style:TextStyle(fontSize:20,fontWeight:FontWeight.bold,color:_purple)),
          const SizedBox(height:6),
          const Text('Alışveriş, stok tarihi, bütçe ve aksiyon risklerini tek yerde incele. Veriler yalnızca okunur.'),
          Wrap(spacing:6,children:[for(final d in [3,7,14,30]) ChoiceChip(
            label:Text('$d gün'),selected:horizon==d,onSelected:(_)=>refresh(()=>horizon=d))]),
          summary('Açık uyarı', '${openRisks.length}', Icons.notifications_active_outlined),
          summary('Kritik / yüksek', '$critical / $high', Icons.priority_high),
          summary('Geciken satın alma / aksiyon', '$overdue', Icons.schedule),
          summary('Bu ay harcama / bütçe','${_money(spent)} / ${budget>0?_money(budget):'Tanımsız'}',Icons.account_balance_wallet_outlined),
          if(openRisks.isNotEmpty) LinearProgressIndicator(
            value:critical/openRisks.length,color:_purple),
          const SizedBox(height:8),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),
            labelText:'Ürün, aksiyon, liste veya öneri ara'),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<String>(value:category,items:['Tümü',...types].map((v)=>
              DropdownMenuItem(value:v,child:Text(v))).toList(),
              onChanged:(v)=>refresh(()=>category=v??'Tümü')),
            DropdownButton<String>(value:severity,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>
              DropdownMenuItem(value:v,child:Text(v))).toList(),
              onChanged:(v)=>refresh(()=>severity=v??'Tümü')),
            DropdownButton<String>(value:sort,items:['Öncelik','Maliyet','Kategori','Başlık'].map((v)=>
              DropdownMenuItem(value:v,child:Text(v))).toList(),
              onChanged:(v)=>refresh(()=>sort=v??'Öncelik')),
          ]),
          DropdownButton<String>(value:statusFilter,items:['Aktif','Tümü','Ertelendi','Çözüldü'].map((v)=>DropdownMenuItem(value:v,child:Text('Uyarı durumu: $v'))).toList(),onChanged:(v)=>refresh(()=>statusFilter=v??'Aktif')),
          SwitchListTile(title:const Text('Yalnız aksiyona bağlanmamış uyarılar'),value:onlyUnlinked,onChanged:(v)=>refresh(()=>onlyUnlinked=v)),
          SwitchListTile(title:const Text('Tamamlanan aksiyonları da göster'),
            value:showResolved,onChanged:(v)=>refresh(()=>showResolved=v)),
          Text('Takip geçmişi: ${tracking.length} • Çözülen: ${tracking.values.where((t)=>t['status']=='Çözüldü').length} • Ertelenen: ${risks.where((r)=>stateOf(r)=='Ertelendi').length} • Aksiyona bağlı: ${risks.where((r)=>actions.any((a)=>a['riskKey']==riskId(r))).length}'),
          if(trackingError) const Text('Uyarı geçmişi okunamadı; kayıt işlemleri kapalı.',style:TextStyle(color:Colors.red)),
          Text('${filtered.length} uyarı gösteriliyor',style:const TextStyle(fontWeight:FontWeight.bold)),
          if(filtered.isEmpty) const Padding(padding:EdgeInsets.all(12),
            child:Text('Seçilen filtrelerde uyarı bulunamadı.')),
          for(final r in filtered) Card(child:ExpansionTile(
            leading:Icon(r['level']=='Kritik'?Icons.error_outline:
              r['level']=='Yüksek'?Icons.warning_amber_outlined:Icons.info_outline,
              color:r['level']=='Kritik'?Colors.redAccent:_purple),
            title:Text((r['title']??'').toString()),
            subtitle:Text('${r['type']} • ${r['level']} • ${r['source']}'),
            children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,12),
              child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text((r['detail']??'').toString()),const SizedBox(height:5),
                Text('Öneri: ${r['recommendation']}',style:const TextStyle(fontWeight:FontWeight.w500)),
                if((r['cost'] as double)>0) Text('İlgili tahmini tutar: ${_money(r['cost'] as double)}'),
                Text('Takip: ${stateOf(r)} • Aksiyon: ${actions.any((a)=>a['riskKey']==riskId(r))?'Bağlı':'Yok'}'),
                if(tracking[riskId(r)]!=null) Text('İlk görülme: ${tracking[riskId(r)]?['firstSeen']??'—'} • İşlem sayısı: ${(tracking[riskId(r)]?['events'] as List?)?.length??0}',style:const TextStyle(fontSize:12)),
                Wrap(spacing:6,runSpacing:4,children:[
                  OutlinedButton.icon(onPressed:()=>makeAction(r),icon:const Icon(Icons.add_task),label:const Text('Aksiyon oluştur')),
                  OutlinedButton(onPressed:()=>changeRisk(r,'Aktif',snooze:1),child:const Text('1 gün ertele')),
                  OutlinedButton(onPressed:()=>changeRisk(r,'Aktif',snooze:7),child:const Text('7 gün ertele')),
                  OutlinedButton(onPressed:()=>changeRisk(r,'Çözüldü'),child:const Text('Çözüldü')),
                  OutlinedButton(onPressed:()=>changeRisk(r,'Aktif'),child:const Text('Yeniden aç')),
                ]),
              ]))])),
          FilledButton.tonalIcon(onPressed:()async {
            await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));
            if(mounted) _notice('${filtered.length} uyarı CSV olarak kopyalandı.');
          },icon:const Icon(Icons.copy),label:const Text('Filtrelenmiş riskleri CSV kopyala')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenOperationsCenter();},
            icon:const Icon(Icons.dashboard_outlined),label:const Text('Birleşik operasyon paneli')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenReplenishmentActions();},
            icon:const Icon(Icons.shopping_cart_outlined),label:const Text('Geciken sipariş aksiyonları')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},
            icon:const Icon(Icons.task_alt_outlined),label:const Text('İyileştirme aksiyon planları')),
          const Text('Uyarılar mevcut kayıtların anlık analizidir; otomatik bildirim veya otomatik satın alma yapılmaz. '
            'Kayıtlı stok miktarı sıfırsa son kullanım tarihi uyarısı gösterilmez. '
            'Aynı ürün farklı listelerde ayrı uyarı üretebilir.',style:TextStyle(fontSize:12)),
        ])));
      }));
  }


  // Risk eğilimleri yalnızca kaydedilmiş uyarı işlem geçmişinden hesaplanır.


  void _showKitchenCorrectiveOutcomeDashboard() {
    const goalKey = 'kitchen_risk_reduction_goals_v1';
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const riskKey = 'kitchen_risk_tracking_v1';
    var loading = true;
    var loadError = '';
    var search = '';
    var category = 'Tümü';
    var status = 'Tümü';
    var priority = 'Tümü';
    var owner = 'Tümü';
    var view = 'Genel özet';
    var order = 'Hedef tarihi';
    var horizon = 30;
    var includeCompleted = true;
    var linkedOnly = false;
    var overdueOnly = false;
    var onlyEnded = false;
    var onlyAttention = false;
    final goals = <Map<String, dynamic>>[];
    final actions = <Map<String, dynamic>>[];
    final risks = <Map<String, dynamic>>[];
    DateTime? date(Object? v) => DateTime.tryParse((v ?? '').toString());
    int number(Object? v) => v is num ? v.toInt() : int.tryParse('$v') ?? 0;
    String labelDate(DateTime? d) => d == null ? '—' : '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    int eventCount(String type, DateTime from, DateTime until) {
      var count = 0;
      for (final risk in risks) {
        if (type != 'Tüm riskler' && risk['type'].toString() != type) { continue; }
        final events = risk['events'];
        if (events is! List) continue;
        for (final event in events.whereType<Map>()) {
          final at = date(event['at']);
          if (at != null && !at.isBefore(from) && at.isBefore(until) &&
              (event['event'] == 'Aktif' || event['event'] == 'Çözüldü')) {
            count++;
          }
        }
      }
      return count;
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, update) {
        if (loading) {
          loading = false;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final g = jsonDecode(prefs.getString(goalKey) ?? '[]');
              final a = jsonDecode(prefs.getString(actionKey) ?? '[]');
              final r = jsonDecode(prefs.getString(riskKey) ?? '{}');
              if (g is! List || a is! List || r is! Map) throw const FormatException('Geçersiz yerel veri');
              goals.addAll(g.whereType<Map>().map((v) => Map<String,dynamic>.from(v)));
              actions.addAll(a.whereType<Map>().map((v) => Map<String,dynamic>.from(v)));
              for (final entry in r.entries) {
                if (entry.value is Map) risks.add(Map<String,dynamic>.from(entry.value as Map));
              }
            } catch (_) { loadError = 'Risk hedefleri, aksiyonlar veya uyarı geçmişi okunamadı. Kayıtlar değiştirilmedi.'; }
            if (ctx.mounted) update(() {});
          }).catchError((Object _) { if (ctx.mounted) update(() => loadError = 'Yerel veriler açılamadı.'); });
        }
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final types = <String>{'Tümü', ...goals.map((g) => (g['type'] ?? 'Diğer').toString()),
          ...actions.map((a) => (a['product'] ?? 'Diğer').toString())}.toList()..sort();
        final owners = <String>{'Tümü', ...actions.map((a) => (a['owner'] ?? '').toString().trim()).where((v) => v.isNotEmpty)}.toList()..sort();
        final safeType = types.contains(category) ? category : 'Tümü';
        final safeOwner = owners.contains(owner) ? owner : 'Tümü';
        final goalRows = <Map<String,dynamic>>[];
        for (final g in goals) {
          final start = date(g['createdAt']);
          if (start == null) continue;
          final length = number(g['days']) > 0 ? number(g['days']) : 30;
          final due = start.add(Duration(days:length));
          final ended = !now.isBefore(due);
          final baseline = number(g['baseline']);
          final target = number(g['target']);
          final measured = eventCount((g['type'] ?? 'Tüm riskler').toString(), start, due);
          final evaluable = ended && baseline > 0;
          final met = evaluable && measured <= target;
          final linked = actions.where((a) => (a['riskGoalId'] ?? '').toString() == (g['id'] ?? '').toString() && (g['id'] ?? '').toString().isNotEmpty).toList();
          goalRows.add({'data':g,'due':due,'ended':ended,'baseline':baseline,'target':target,
            'measured':measured,'evaluable':evaluable,'met':met,'linked':linked,
            'difference':measured-baseline,'remaining':target-measured});
        }
        final actionRows = <Map<String,dynamic>>[];
        for (final a in actions) {
          final due = date(a['due']);
          final created = date(a['created']);
          final completed = date(a['completed']);
          final done = a['status'] == 'Tamamlandı';
          final overdue = !done && due != null && due.isBefore(today);
          final lateCompletion = done && completed != null && due != null && completed.isAfter(due.add(const Duration(days:1)).subtract(const Duration(microseconds:1)));
          final daysToDue = due?.difference(today).inDays;
          final cycle = completed == null || created == null ? null : completed.difference(created).inHours / 24;
          actionRows.add({'data':a,'due':due,'created':created,'completed':completed,'done':done,
            'overdue':overdue,'lateCompletion':lateCompletion,'daysToDue':daysToDue,'cycle':cycle,
            'linked':(a['riskGoalId'] ?? '').toString().isNotEmpty});
        }
        final filteredGoals = goalRows.where((r) {
          final g = r['data'] as Map<String,dynamic>;
          if (safeType != 'Tümü' && g['type'] != safeType) return false;
          if (onlyEnded && r['ended'] != true) return false;
          if (linkedOnly && (r['linked'] as List).isEmpty) return false;
          if (onlyAttention && (r['met'] == true || r['evaluable'] != true)) return false;
          if (status == 'Başarılı' && r['met'] != true) return false;
          if (status == 'Hedef tutmadı' && !(r['evaluable'] == true && r['met'] != true)) return false;
          if (status == 'Ölçüm sürüyor' && r['ended'] == true) return false;
          if (status == 'Veri eksik' && !(r['ended'] == true && r['baseline'] == 0)) return false;
          return '${g['title']} ${g['type']} ${g['note']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        final filteredActions = actionRows.where((r) {
          final a = r['data'] as Map<String,dynamic>;
          if (safeType != 'Tümü' && a['product'] != safeType) return false;
          if (safeOwner != 'Tümü' && a['owner'] != safeOwner) return false;
          if (priority != 'Tümü' && a['level'] != priority) return false;
          if (!includeCompleted && r['done'] == true) return false;
          if (linkedOnly && r['linked'] != true) return false;
          if (overdueOnly && r['overdue'] != true) return false;
          if (onlyAttention && r['overdue'] != true && !(r['lateCompletion'] == true)) return false;
          if (status == 'Tamamlandı' && r['done'] != true) return false;
          if (status == 'Açık' && r['done'] == true) return false;
          if (status == 'Gecikti' && r['overdue'] != true) return false;
          if (status == 'Yaklaşıyor' && !(r['done'] != true && r['daysToDue'] != null && (r['daysToDue'] as int) >= 0 && (r['daysToDue'] as int) <= horizon)) return false;
          return '${a['title']} ${a['product']} ${a['owner']} ${a['note']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        filteredActions.sort((x,y) {
          final a=x['data'] as Map<String,dynamic>;
          final b=y['data'] as Map<String,dynamic>;
          if(order=='Öncelik'){
            const rank={'Kritik':0,'Yüksek':1,'Orta':2};
            return (rank[a['level']]??3).compareTo(rank[b['level']]??3);
          }
          if(order=='En yeni')return (b['created'] as DateTime? ?? DateTime(1900)).compareTo(x['created'] as DateTime? ?? DateTime(1900));
          if(order=='Tamamlanma süresi')return (y['cycle'] as double? ?? -1).compareTo(x['cycle'] as double? ?? -1);
          return (x['due'] as DateTime? ?? DateTime(2100)).compareTo(y['due'] as DateTime? ?? DateTime(2100));
        });
        final done = filteredActions.where((r)=>r['done']==true).length;
        final open = filteredActions.length-done;
        final overdue = filteredActions.where((r)=>r['overdue']==true).length;
        final dueSoon = filteredActions.where((r)=>r['done']!=true && r['daysToDue']!=null && (r['daysToDue'] as int)>=0 && (r['daysToDue'] as int)<=horizon).length;
        final completedLate = filteredActions.where((r)=>r['lateCompletion']==true).length;
        final measurableCycles = filteredActions.where((r)=>r['cycle']!=null && (r['cycle'] as double)>=0).toList();
        final averageDays = measurableCycles.isEmpty ? null : measurableCycles.fold<double>(0,(sum,r)=>sum+(r['cycle'] as double))/measurableCycles.length;
        final evaluable = filteredGoals.where((r)=>r['evaluable']==true).length;
        final met = filteredGoals.where((r)=>r['met']==true).length;
        final unmet = evaluable-met;
        final noBaseline = filteredGoals.where((r)=>r['ended']==true && r['baseline']==0).length;
        final inProgress = filteredGoals.where((r)=>r['ended']!=true).length;
        final linkedGoals = filteredGoals.where((r)=>(r['linked'] as List).isNotEmpty).length;
        final criticalOpen = filteredActions.where((r)=>r['done']!=true && (r['data'] as Map)['level']=='Kritik').length;
        final highOpen = filteredActions.where((r)=>r['done']!=true && (r['data'] as Map)['level']=='Yüksek').length;
        final withoutDue = filteredActions.where((r)=>r['done']!=true && r['due']==null).length;
        final withoutOwner = filteredActions.where((r)=>r['done']!=true && ((r['data'] as Map)['owner']??'').toString().trim().isEmpty).length;
        final successRate = evaluable==0 ? null : met*100/evaluable;
        final completionRate = filteredActions.isEmpty ? null : done*100/filteredActions.length;
        final onTime = filteredActions.where((r)=>r['done']==true && r['completed']!=null && r['due']!=null && r['lateCompletion']!=true).length;
        final measurableCompletion = filteredActions.where((r)=>r['done']==true && r['completed']!=null && r['due']!=null).length;
        final onTimeRate = measurableCompletion==0 ? null : onTime*100/measurableCompletion;
        final csvLines = <String>[
          ['Tür','Başlık','Kategori','Durum','Öncelik','Sorumlu','Hedef tarih','Başlangıç','Hedef','Gerçekleşen','Bağlantı','Gecikme gün','Tamamlanma gün'].map(csv).join(';'),
          for(final r in filteredGoals) ['Risk hedefi',(r['data'] as Map)['title'],(r['data'] as Map)['type'],r['evaluable']==true?(r['met']==true?'Başarılı':'Hedef tutmadı'):(r['ended']==true?'Veri eksik':'Ölçüm sürüyor'),'','',labelDate(r['due'] as DateTime),r['baseline'],r['target'],r['measured'],(r['linked'] as List).length,'',''].map(csv).join(';'),
          for(final r in filteredActions) ['Aksiyon',(r['data'] as Map)['title'],(r['data'] as Map)['product'],(r['data'] as Map)['status'],(r['data'] as Map)['level'],(r['data'] as Map)['owner'],labelDate(r['due'] as DateTime?),'','','',r['linked']==true?'Evet':'Hayır',r['overdue']==true?-(r['daysToDue'] as int):0,r['cycle']==null?'':(r['cycle'] as double).toStringAsFixed(1)].map(csv).join(';')
        ];
        Widget metric(String name,String value) => Card(color:_pink,child:Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(name,style:const TextStyle(fontSize:12)),const SizedBox(height:4),Text(value,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17))])));
        final statusOptions = view=='Risk hedefleri' ? ['Tümü','Başarılı','Hedef tutmadı','Ölçüm sürüyor','Veri eksik'] : ['Tümü','Açık','Tamamlandı','Gecikti','Yaklaşıyor'];
        final safeStatus = statusOptions.contains(status)?status:'Tümü';
        return SafeArea(child:FractionallySizedBox(heightFactor:.96,child:ListView(padding:const EdgeInsets.all(14),children:[
          Row(children:[const Expanded(child:Text('Düzeltici Aksiyonlar / Entegre Başarı Analizi',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Risk hedefleri ve aksiyon kayıtları tek raporda. Veriler yalnızca okunur; hedef başarısı ölçüm dönemi bitince ve başlangıç verisi varsa değerlendirilir.',style:TextStyle(fontSize:12)),
          if(loadError.isNotEmpty)Text(loadError,style:const TextStyle(color:Colors.red)),
          const SizedBox(height:8),
          Wrap(spacing:8,runSpacing:5,children:['Genel özet','Aksiyonlar','Risk hedefleri','Dikkat gerektirenler'].map((v)=>ChoiceChip(label:Text(v),selected:view==v,onSelected:(_)=>update((){view=v;status='Tümü';}))).toList()),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Hedef, ürün, sorumlu veya aksiyon ara'),onChanged:(v)=>update(()=>search=v)),
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<String>(value:safeType,items:types.map((v)=>DropdownMenuItem(value:v,child:Text(v.length>24?'${v.substring(0,24)}…':v))).toList(),onChanged:(v){if(v!=null)update(()=>category=v);}),
            DropdownButton<String>(value:safeStatus,items:statusOptions.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)update(()=>status=v);}),
            DropdownButton<String>(value:priority,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)update(()=>priority=v);}),
            DropdownButton<String>(value:safeOwner,items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v.length>18?'${v.substring(0,18)}…':v))).toList(),onChanged:(v){if(v!=null)update(()=>owner=v);}),
            DropdownButton<int>(value:horizon,items:[7,14,30,60,90].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v){if(v!=null)update(()=>horizon=v);}),
            DropdownButton<String>(value:order,items:['Hedef tarihi','Öncelik','En yeni','Tamamlanma süresi'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)update(()=>order=v);}),
          ]),
          SwitchListTile(dense:true,title:const Text('Tamamlanan aksiyonları dahil et'),value:includeCompleted,onChanged:(v)=>update(()=>includeCompleted=v)),
          SwitchListTile(dense:true,title:const Text('Yalnız hedefle bağlantılı kayıtlar'),value:linkedOnly,onChanged:(v)=>update(()=>linkedOnly=v)),
          SwitchListTile(dense:true,title:const Text('Yalnız geciken açık aksiyonlar'),value:overdueOnly,onChanged:(v)=>update(()=>overdueOnly=v)),
          SwitchListTile(dense:true,title:const Text('Yalnız ölçüm dönemi biten hedefler'),value:onlyEnded,onChanged:(v)=>update(()=>onlyEnded=v)),
          SwitchListTile(dense:true,title:const Text('Yalnız dikkat gerektiren sonuçlar'),value:onlyAttention,onChanged:(v)=>update(()=>onlyAttention=v)),
          if(view=='Genel özet'||view=='Dikkat gerektirenler')...[
            Wrap(spacing:6,runSpacing:6,children:[
              metric('Aksiyon sayısı','${filteredActions.length}'),metric('Tamamlanan','$done'),metric('Açık','$open'),
              metric('Tamamlanma oranı',completionRate==null?'Veri yok':'%${completionRate.toStringAsFixed(1)}'),
              metric('Geciken açık','$overdue'),metric('Yaklaşan ($horizon gün)','$dueSoon'),
              metric('Kritik açık','$criticalOpen'),metric('Yüksek açık','$highOpen'),
              metric('Sorumlusu eksik','$withoutOwner'),metric('Hedef tarihi eksik','$withoutDue'),
              metric('Geç tamamlanan','$completedLate'),metric('Zamanında tamamlanma',onTimeRate==null?'Veri yok':'%${onTimeRate.toStringAsFixed(1)}'),
              metric('Ortalama tamamlanma',averageDays==null?'Veri yok':'${averageDays.toStringAsFixed(1)} gün'),
              metric('Risk hedefi','${filteredGoals.length}'),metric('Değerlendirilebilir','$evaluable'),
              metric('Başarılı','$met'),metric('Başarısız','$unmet'),
              metric('Hedef başarı oranı',successRate==null?'Veri yok':'%${successRate.toStringAsFixed(1)}'),
              metric('Ölçüm sürüyor','$inProgress'),metric('Başlangıç verisi yok','$noBaseline'),
              metric('Aksiyon bağlı hedef','$linkedGoals'),
            ]),
            if(filteredActions.isNotEmpty)LinearProgressIndicator(value:done/filteredActions.length,minHeight:7),
            const SizedBox(height:8),
            if(evaluable>0)LinearProgressIndicator(value:met/evaluable,minHeight:7),
            const SizedBox(height:8),
            Text('Yorum: ${overdue>0?'Geciken açık aksiyonları önceliklendir. ':'Geciken açık aksiyon bulunmuyor. '}${unmet>0?'Hedefi tutmayan $unmet risk hedefinin nedenlerini incele. ':'Değerlendirilebilir hedeflerde başarısızlık görünmüyor. '}${noBaseline>0?'$noBaseline hedefte başlangıç verisi yetersiz.':''}'),
          ],
          if(view=='Genel özet'||view=='Aksiyonlar'||view=='Dikkat gerektirenler')...[
            const SizedBox(height:10),Text('Aksiyon detayları (${filteredActions.length})',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),
            if(filteredActions.isEmpty)const Text('Seçili filtrelerde aksiyon bulunamadı.'),
            for(final r in filteredActions.take(150))Card(child:ExpansionTile(
              leading:Icon(r['overdue']==true?Icons.warning_amber_rounded:r['done']==true?Icons.check_circle_outline:Icons.pending_actions,color:r['overdue']==true?Colors.deepOrange:_purple),
              title:Text(((r['data'] as Map)['title']??'Aksiyon').toString()),
              subtitle:Text('${(r['data'] as Map)['level']??'Orta'} • ${(r['data'] as Map)['status']??'Açık'} • ${labelDate(r['due'] as DateTime?)}'),
              children:[ListTile(title:Text('Sorumlu: ${((r['data'] as Map)['owner']??'').toString().trim().isEmpty?'Atanmamış':(r['data'] as Map)['owner']}'),subtitle:Text('Kaynak: ${(r['data'] as Map)['source']??'—'}\nBağlı risk hedefi: ${r['linked']==true?'Var':'Yok'}\nOluşturulma: ${labelDate(r['created'] as DateTime?)} • Tamamlanma: ${labelDate(r['completed'] as DateTime?)}\n${r['overdue']==true?'Gecikme: ${-(r['daysToDue'] as int)} gün':r['daysToDue']==null?'Hedef tarihi yok':'Hedefe kalan: ${r['daysToDue']} gün'}\n${r['cycle']==null?'Tamamlanma süresi ölçülemiyor':'Tamamlanma süresi: ${(r['cycle'] as double).toStringAsFixed(1)} gün'}\nNot: ${(r['data'] as Map)['note']??''}'))]
            )),
            if(filteredActions.length>150)Text('İlk 150 aksiyon gösteriliyor; CSV raporu filtreye uyan tüm kayıtları içerir.'),
          ],
          if(view=='Genel özet'||view=='Risk hedefleri'||view=='Dikkat gerektirenler')...[
            const SizedBox(height:10),Text('Risk hedefleri (${filteredGoals.length})',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),
            if(filteredGoals.isEmpty)const Text('Seçili filtrelerde risk hedefi bulunamadı.'),
            for(final r in filteredGoals.take(150))Card(child:ExpansionTile(
              leading:Icon(r['met']==true?Icons.verified_outlined:r['evaluable']==true?Icons.report_problem_outlined:Icons.timelapse_outlined,color:r['evaluable']==true&&r['met']!=true?Colors.deepOrange:_purple),
              title:Text(((r['data'] as Map)['title']??'Risk hedefi').toString()),
              subtitle:Text('${(r['data'] as Map)['type']??'Diğer'} • ${r['met']==true?'Başarılı':r['evaluable']==true?'Hedef tutmadı':r['ended']==true?'Veri eksik':'Ölçüm sürüyor'}'),
              children:[ListTile(title:Text('Başlangıç: ${r['baseline']} • Hedef: ${r['target']} • Ölçülen: ${r['measured']}'),subtitle:Text('Bitiş: ${labelDate(r['due'] as DateTime)} • Bağlı aksiyon: ${(r['linked'] as List).length}\n${r['evaluable']==true?'Hedefe göre fark: ${r['remaining']}':'Başarı henüz kesin değerlendirilemiyor.'}\n${(r['data'] as Map)['note']??''}'))]
            )),
            if(filteredGoals.length>150)Text('İlk 150 hedef gösteriliyor; CSV raporu filtreye uyan tüm kayıtları içerir.'),
          ],
          const SizedBox(height:10),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));if(mounted)_notice('Entegre performans raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy_all_outlined),label:const Text('Filtrelenmiş hedef ve aksiyon CSV raporu')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenRiskCorrectiveCalendar();},icon:const Icon(Icons.event_note_outlined),label:const Text('Düzeltici aksiyon takvimini aç')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt_outlined),label:const Text('Aksiyon durumlarını yönet')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenRiskGoalsExecutiveSummary();},icon:const Icon(Icons.assessment_outlined),label:const Text('Risk hedefleri yönetim özetini aç')),
          const Text('Not: Tamamlanma oranları yalnızca kayıtlı aksiyon durumlarına dayanır. Risk hedefi başarısı, aynı kategoriye ait kaydedilmiş Aktif/Çözüldü olaylarının sayısıyla değerlendirilir. Aksiyonun riski doğrudan azalttığı kanıtlanmaz. Bu ekran veri değiştirmez.',style:TextStyle(fontSize:11)),
        ])));
      }));
  }

  void _showKitchenRiskCorrectiveCalendar() {
    const goalsKey='kitchen_risk_reduction_goals_v1';
    const actionKey='paket39_purchase_improvement_actions_v1';
    var loading=true;
    var error='';
    var search='';
    var filter='Tümü';
    var horizon=30;
    var onlyWithoutAction=false;
    final goals=<Map<String,dynamic>>[];
    final actions=<Map<String,dynamic>>[];
    DateTime? parse(Object? v)=>DateTime.tryParse((v??'').toString());
    int asInt(Object? v)=>v is num?v.toInt():int.tryParse('$v')??0;
    String day(DateTime? d)=>d==null?'—':'${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String quote(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    String goalId(Map<String,dynamic> g)=>(g['id']??'').toString();
    bool linked(Map<String,dynamic> g)=>actions.any((a)=>a['riskGoalId']==goalId(g));
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(loading){
        loading=false;
        SharedPreferences.getInstance().then((prefs){
          try {
            final g=jsonDecode(prefs.getString(goalsKey)??'[]');
            final a=jsonDecode(prefs.getString(actionKey)??'[]');
            if(g is! List||a is! List)throw const FormatException('Geçersiz kayıt');
            goals.addAll(g.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
            actions.addAll(a.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
          } catch(_){error='Hedef veya aksiyon verileri okunamadı. Kayıt işlemleri kapalı.';}
          if(ctx.mounted)refresh((){});
        }).catchError((Object _){if(ctx.mounted)refresh(()=>error='Yerel kayıtlar açılamadı.');});
      }
      final now=DateTime.now();
      final today=DateTime(now.year,now.month,now.day);
      final goalRows=<Map<String,dynamic>>[];
      for(final g in goals){
        final start=parse(g['createdAt']);
        if(start==null)continue;
        final due=start.add(Duration(days:asInt(g['days'])>0?asInt(g['days']):30));
        final isEnded=!now.isBefore(due);
        final baseline=asInt(g['baseline']);
        final target=asInt(g['target']);
        // This screen uses the stored executive summary's target and baseline;
        // it never infers a goal's actual outcome from manual completion status.
        goalRows.add({'goal':g,'due':due,'ended':isEnded,'baseline':baseline,'target':target,'linked':linked(g)});
      }
      final visibleGoals=goalRows.where((r){
        final g=r['goal'] as Map<String,dynamic>;
        if(filter=='Aksiyon yok'&&r['linked']==true)return false;
        if(filter=='Dönemi biten'&&r['ended']!=true)return false;
        if(filter=='Dönemi süren'&&r['ended']==true)return false;
        if(onlyWithoutAction&&r['linked']==true)return false;
        return '${g['title']} ${g['type']} ${g['note']}'.toLowerCase().contains(search.toLowerCase());
      }).toList()..sort((a,b)=>(a['due'] as DateTime).compareTo(b['due'] as DateTime));
      final openActions=actions.where((a)=>a['status']!='Tamamlandı').toList();
      final upcoming=openActions.where((a){final d=parse(a['due']);return d!=null&&!d.isBefore(today)&&!d.isAfter(today.add(Duration(days:horizon)));}).toList()
        ..sort((a,b)=>(a['due']??'').toString().compareTo((b['due']??'').toString()));
      final overdue=openActions.where((a){final d=parse(a['due']);return d!=null&&d.isBefore(today);}).toList()
        ..sort((a,b)=>(a['due']??'').toString().compareTo((b['due']??'').toString()));
      Future<void> create(Map<String,dynamic> g) async {
        if(error.isNotEmpty)return;
        if(goalId(g).isEmpty){_notice('Hedef kimliği bulunamadı.');return;}
        if(linked(g)){_notice('Bu hedefe bağlı aksiyon zaten mevcut.');return;}
        final title=TextEditingController(text:'Risk hedefi: ${g['title']??'İyileştirme'}');
        final owner=TextEditingController();
        final note=TextEditingController(text:'Hedef: ${g['title']}\nKategori: ${g['type']}\nBaşlangıç: ${g['baseline']} • Hedef: ${g['target']}\n${g['note']??''}');
        var level='Yüksek';
        var due=today.add(const Duration(days:7));
        final ok=await showDialog<bool>(context:ctx,builder:(dctx)=>StatefulBuilder(builder:(dctx,update)=>AlertDialog(
          title:const Text('Düzeltici aksiyon oluştur'),
          content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
            TextField(controller:title,maxLength:120,decoration:const InputDecoration(labelText:'Aksiyon başlığı')),
            TextField(controller:owner,decoration:const InputDecoration(labelText:'Sorumlu (isteğe bağlı)')),
            DropdownButtonFormField<String>(initialValue:level,decoration:const InputDecoration(labelText:'Öncelik'),items:['Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)update(()=>level=v);}),
            ListTile(title:Text('Hedef tarih: ${day(due)}'),trailing:const Icon(Icons.event),onTap:()async{
              final d=await showDatePicker(context:dctx,initialDate:due,firstDate:DateTime(2020),lastDate:DateTime(2100));
              if(d!=null)update(()=>due=d);
            }),
            TextField(controller:note,maxLines:4,decoration:const InputDecoration(labelText:'Düzeltici işlem / not')),
          ])),actions:[TextButton(onPressed:()=>Navigator.pop(dctx,false),child:const Text('Vazgeç')),
            FilledButton(onPressed:()=>Navigator.pop(dctx,title.text.trim().isNotEmpty),child:const Text('Aksiyon oluştur'))])));
        if(ok==true&&ctx.mounted){
          try{
            final prefs=await SharedPreferences.getInstance();
            final raw=jsonDecode(prefs.getString(actionKey)??'[]');
            if(raw is! List)throw const FormatException('Aksiyon verisi geçersiz');
            final latest=raw.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)).toList();
            if(latest.any((a)=>a['riskGoalId']==goalId(g))){_notice('Başka bir kayıtta bu hedef için aksiyon zaten var.');}
            else{
              final created=DateTime.now();
              latest.insert(0,{'id':'goal_${created.microsecondsSinceEpoch}','riskGoalId':goalId(g),
                'title':title.text.trim(),'product':(g['type']??'').toString(),'source':'Risk azaltma hedefi',
                'owner':owner.text.trim(),'note':note.text.trim(),'level':level,'status':'Açık',
                'due':due.toIso8601String().substring(0,10),'created':created.toIso8601String(),'completed':''});
              if(!await prefs.setString(actionKey,jsonEncode(latest)))throw const FormatException('Kaydedilemedi');
              if(ctx.mounted)refresh((){actions..clear()..addAll(latest);});
              _notice('Düzeltici aksiyon kaydedildi.');
            }
          }catch(_){_notice('Aksiyon kaydedilemedi; mevcut kayıtlar korundu.');}
        }
        disposeAfterDialog(title);disposeAfterDialog(owner);disposeAfterDialog(note);
      }
      final csvRows=<String>[
        ['Kayıt','Başlık','Kategori','Durum','Öncelik','Hedef tarih','Sorumlu','Bağlı hedef','Başlangıç','Hedef'].map(quote).join(';'),
        for(final r in visibleGoals) ['Risk hedefi',(r['goal'] as Map)['title'],(r['goal'] as Map)['type'],(r['goal'] as Map)['status'],'',day(r['due'] as DateTime),'',r['linked']==true?'Evet':'Hayır',r['baseline'],r['target']].map(quote).join(';'),
        for(final a in [...overdue,...upcoming]) ['Aksiyon',a['title'],a['product'],a['status'],a['level'],a['due'],a['owner'],a['riskGoalId'],'',''].map(quote).join(';'),
      ];
      return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Risk Hedefleri / Düzeltici Aksiyon ve Takvim',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Hedefleri aksiyona bağla, sorumlu ve tarih ata; açık aksiyonların takvimini izle. Risk sonuçları bu ekranda otomatik doğrulanmaz.',style:TextStyle(fontSize:12)),
        if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.red)),
        Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Text('Hedef: ${goals.length} • Aksiyona bağlı: ${goalRows.where((r)=>r['linked']==true).length} • Açık aksiyon: ${openActions.length} • Geciken: ${overdue.length} • Yaklaşan ($horizon gün): ${upcoming.length}',style:const TextStyle(fontWeight:FontWeight.bold)))),
        TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Hedef adı, kategori veya açıklama ara'),onChanged:(v)=>refresh(()=>search=v)),
        Wrap(spacing:8,runSpacing:4,children:[
          DropdownButton<String>(value:filter,items:['Tümü','Aksiyon yok','Dönemi biten','Dönemi süren'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)refresh(()=>filter=v);}),
          DropdownButton<int>(value:horizon,items:[7,14,30,60,90].map((v)=>DropdownMenuItem(value:v,child:Text('$v günlük takvim'))).toList(),onChanged:(v){if(v!=null)refresh(()=>horizon=v);}),
        ]),
        SwitchListTile(title:const Text('Yalnız aksiyona bağlanmamış hedefler'),value:onlyWithoutAction,onChanged:(v)=>refresh(()=>onlyWithoutAction=v)),
        Text('Risk hedefleri (${visibleGoals.length})',style:const TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
        if(visibleGoals.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('Bu filtrede risk hedefi bulunamadı.')),
        for(final r in visibleGoals) Card(child:ListTile(
          title:Text(((r['goal'] as Map)['title']??'Risk hedefi').toString()),
          subtitle:Text('${(r['goal'] as Map)['type']} • ${r['ended']==true?'Ölçüm dönemi bitti':'Ölçüm sürüyor'} • ${day(r['due'] as DateTime)}\nBaşlangıç: ${r['baseline']} • Hedef: ${r['target']} • ${r['linked']==true?'Aksiyon bağlı':'Aksiyon yok'}'),
          isThreeLine:true,
          trailing:r['linked']==true?const Icon(Icons.check_circle_outline,color:_purple):IconButton(icon:const Icon(Icons.add_task),tooltip:'Düzeltici aksiyon oluştur',onPressed:error.isNotEmpty?null:()=>create(r['goal'] as Map<String,dynamic>)),
        )),
        const SizedBox(height:8),
        Text('Geciken aksiyonlar (${overdue.length})',style:const TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
        for(final a in overdue)ListTile(leading:const Icon(Icons.warning_amber_outlined,color:Colors.deepOrange),title:Text((a['title']??'').toString()),subtitle:Text('${a['owner']??'Sorumlu yok'} • ${a['level']??'Orta'} • ${a['status']??'Açık'}'),trailing:Text(day(parse(a['due'])))),
        const SizedBox(height:8),
        Text('Yaklaşan aksiyonlar (${upcoming.length})',style:const TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
        for(final a in upcoming)ListTile(leading:const Icon(Icons.event_available_outlined,color:_purple),title:Text((a['title']??'').toString()),subtitle:Text('${a['owner']??'Sorumlu yok'} • ${a['level']??'Orta'} • ${a['status']??'Açık'}'),trailing:Text(day(parse(a['due'])))),
        FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${csvRows.join('\r\n')}'));if(mounted)_notice('Takvim raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Hedef ve takvim CSV kopyala')),
        FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt_outlined),label:const Text('Aksiyonları aç / durum güncelle')),
        FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenRiskGoalsExecutiveSummary();},icon:const Icon(Icons.assessment_outlined),label:const Text('Risk hedefleri yönetim özetini aç')),
        const Text('Not: Gecikme hesaplaması hedef tarihine ve kayıtlı aksiyon durumuna dayanır. Hedefin başarı/başarısızlığı bu ekranda varsayılmaz. Otomatik bildirim gönderilmez.',style:TextStyle(fontSize:11)),
      ])));
    }));
  }

  void _showKitchenRiskGoalsExecutiveSummary() {
    const goalsKey = 'kitchen_risk_reduction_goals_v1';
    const historyKey = 'kitchen_risk_tracking_v1';
    var loading = true;
    var error = '';
    var period = 90;
    var status = 'Tümü';
    var category = 'Tümü';
    var search = '';
    var onlyAttention = false;
    final goals = <Map<String,dynamic>>[];
    final events = <Map<String,dynamic>>[];
    DateTime? date(Object? v) => DateTime.tryParse((v ?? '').toString());
    int number(Object? v) => v is num ? v.toInt() : int.tryParse('$v') ?? 0;
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    int count(String type, DateTime start, DateTime end) => events.where((e) {
      final d = date(e['at']);
      return d != null && !d.isBefore(start) && d.isBefore(end) &&
        (type == 'Tüm riskler' || e['type'] == type) &&
        (e['event'] == 'Aktif' || e['event'] == 'Çözüldü');
    }).length;
    showModalBottomSheet<void>(context:context,isScrollControlled:true,
      builder:(_) => StatefulBuilder(builder:(ctx,refresh) {
        if(loading) {
          loading=false;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final stored=jsonDecode(prefs.getString(goalsKey) ?? '[]');
              if(stored is List) goals.addAll(stored.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
              final raw=jsonDecode(prefs.getString(historyKey) ?? '{}');
              if(raw is Map) {
                for(final record in raw.values.whereType<Map>()) {
                  final changes=record['events'];
                  if(changes is List) {
                    for(final change in changes.whereType<Map>()) {
                      events.add({...Map<String,dynamic>.from(change),'type':(record['type']??'Diğer').toString()});
                    }
                  }
                }
              }
            } catch (_) {error='Kayıtların bir kısmı okunamadı. Verileri kontrol edin.';}
            if(ctx.mounted) refresh((){});
          }).catchError((Object _) {if(ctx.mounted) refresh(()=>error='Yerel veriler açılamadı.');});
        }
        final now=DateTime.now();
        final kinds=<String>{'Tümü',...goals.map((g)=>(g['type']??'Diğer').toString())}.toList()..sort();
        final safeCategory=kinds.contains(category)?category:'Tümü';
        final results=<Map<String,dynamic>>[];
        for(final g in goals) {
          final start=date(g['createdAt']);
          if(start==null) continue;
          final days=number(g['days'])>0?number(g['days']):30;
          final end=start.add(Duration(days:days));
          final finished=!now.isBefore(end);
          final baseline=number(g['baseline']);
          final target=number(g['target']);
          final measured=count((g['type']??'Tüm riskler').toString(),start,finished?end:now);
          final reduction=baseline>0?(baseline-measured)*100/baseline:null;
          final met=finished && measured<=target;
          final hasBaseline=baseline>0;
          final label=!hasBaseline?'Başlangıç verisi yok':!finished?'Ölçüm sürüyor':met?'Hedef karşılandı':'Hedef karşılanmadı';
          final needsAttention=!hasBaseline || (finished && !met) ||
            (g['status']=='Aktif' && finished && !met);
          final advice=!hasBaseline?'Önceki dönem için yeterli olay kaydı yok; hedefi veri biriktikten sonra yeniden değerlendirin.' :
            !finished?'Dönem devam ediyor; kalan günlerde tekrar eden uyarıları izleyin.' :
            met?'Başarılı uygulamayı sürdürün; sonraki dönemde aynı göstergeyi yeniden ölçün.' :
            measured>baseline?'Risk olayları başlangıca göre arttı; gecikme, stok ve bütçe nedenlerini inceleyin.' :
            'Hedeflenen azalmaya ulaşılamadı; hedefi ve ilgili aksiyonların son durumunu gözden geçirin.';
          results.add({'goal':g,'start':start,'end':end,'baseline':baseline,'target':target,'measured':measured,
            'reduction':reduction,'met':met,'finished':finished,'label':label,'attention':needsAttention,'advice':advice});
        }
        final visible=results.where((r) {
          final g=r['goal'] as Map<String,dynamic>;
          final start=r['start'] as DateTime;
          return !start.isBefore(now.subtract(Duration(days:period))) &&
            (status=='Tümü'||g['status']==status) && (safeCategory=='Tümü'||g['type']==safeCategory) &&
            (!onlyAttention||r['attention']==true) &&
            '${g['title']} ${g['type']} ${g['note']}'.toLowerCase().contains(search.toLowerCase());
        }).toList()..sort((a,b) {
          final priority=(b['attention']==true?1:0).compareTo(a['attention']==true?1:0);
          return priority!=0?priority:(b['start'] as DateTime).compareTo(a['start'] as DateTime);
        });
        final finished=visible.where((r)=>r['finished']==true && r['baseline']>0).toList();
        final met=finished.where((r)=>r['met']==true).length;
        final pending=visible.where((r)=>r['finished']==false).length;
        final noData=visible.where((r)=>r['baseline']==0).length;
        final failed=finished.length-met;
        final rate=finished.isEmpty?null:met*100/finished.length;
        return SafeArea(child:Padding(padding:EdgeInsets.fromLTRB(16,12,16,MediaQuery.of(ctx).viewInsets.bottom+12),
          child:SizedBox(height:MediaQuery.of(ctx).size.height*.9,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Row(children:[const Expanded(child:Text('Risk Hedefleri / Yönetim Özeti ve Öneriler',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
            if(error.isNotEmpty) Text(error,style:const TextStyle(color:Colors.red)),
            Text('Hedef: ${visible.length} • Değerlendirilen: ${finished.length} • Başarılı: $met • Başarısız: $failed'),
            Text('Devam eden: $pending • Başlangıç verisi eksik: $noData • Başarı: ${rate==null?'Hesaplanamıyor':'%${rate.toStringAsFixed(1)}'}'),
            const SizedBox(height:8),
            Wrap(spacing:8,runSpacing:4,children:[
              DropdownButton<int>(value:period,items:[30,60,90,180,365].map((v)=>DropdownMenuItem(value:v,child:Text('Son $v gün'))).toList(),onChanged:(v){if(v!=null)refresh(()=>period=v);}),
              DropdownButton<String>(value:status,items:['Tümü','Aktif','Durduruldu','Tamamlandı'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)refresh(()=>status=v);}),
              DropdownButton<String>(value:safeCategory,items:kinds.map((v)=>DropdownMenuItem(value:v,child:Text(v,overflow:TextOverflow.ellipsis))).toList(),onChanged:(v){if(v!=null)refresh(()=>category=v);}),
              FilterChip(label:const Text('İlgilenilmesi gerekenler'),selected:onlyAttention,onSelected:(v)=>refresh(()=>onlyAttention=v)),
              OutlinedButton.icon(icon:const Icon(Icons.copy_outlined),label:const Text('CSV'),onPressed:()async {
                final lines=<String>['Hedef;Risk;Durum;Başlangıç;Hedeflenen;Ölçülen;Sonuç;Öneri'];
                for(final r in visible) {final g=r['goal'] as Map<String,dynamic>;
                  lines.add([g['title'],g['type'],g['status'],r['baseline'],r['target'],r['measured'],r['label'],r['advice']].map(csv).join(';'));
                }
                await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
                if(ctx.mounted) ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('Yönetim özeti CSV panoya kopyalandı.')));
              }),
            ]),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Hedef, risk veya açıklama ara'),onChanged:(v)=>refresh(()=>search=v)),
            const SizedBox(height:8),
            Expanded(child:visible.isEmpty?const Center(child:Text('Seçilen filtrelerde hedef bulunamadı.')):ListView.builder(itemCount:visible.length,itemBuilder:(context,i) {
              final r=visible[i];final g=r['goal'] as Map<String,dynamic>;
              final reduction=r['reduction'] as double?;
              return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text((g['title']??'Hedef').toString(),style:const TextStyle(fontWeight:FontWeight.bold)),
                Text('${g['type']} • ${g['status']} • ${r['label']}'),
                Text('Önceki dönem: ${r['baseline']} • Hedef: en fazla ${r['target']} • Gerçekleşen: ${r['measured']}'),
                Text('Değişim: ${reduction==null?'Veri yok':'%${reduction.toStringAsFixed(1)}'} • Hedef dönem: ${g['days']} gün'),
                Text('Öneri: ${r['advice']}'),
                if(r['attention']==true) const Text('Takip öneriliyor',style:TextStyle(fontWeight:FontWeight.w600)),
              ])));
            })),
            Wrap(spacing:8,children:[
              TextButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenRiskReductionGoals();},icon:const Icon(Icons.flag_outlined),label:const Text('Hedefleri yönet')),
              TextButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenRiskTrendAnalysis();},icon:const Icon(Icons.show_chart_outlined),label:const Text('Risk eğilimleri')),
              TextButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt_outlined),label:const Text('Aksiyonlar')),
            ]),
            const Text('Analiz kayıtlı uyarı işlemlerini kullanır; ölçüm dönemi bitmeden başarı kesinleşmez. Öneriler otomatik işlem yapmaz.',style:TextStyle(fontSize:11)),
          ]))));
      }));
  }

  void _showKitchenRiskReductionGoals() {
    const historyKey = 'kitchen_risk_tracking_v1';
    const goalsKey = 'kitchen_risk_reduction_goals_v1';
    var loading = true;
    var error = '';
    var days = 30;
    var filter = 'Tümü';
    var search = '';
    final history = <Map<String, dynamic>>[];
    final goals = <Map<String, dynamic>>[];
    DateTime? parse(Object? v) => DateTime.tryParse((v ?? '').toString());
    String quote(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    int countEvents(String kind, DateTime from, DateTime until) {
      var n = 0;
      for (final record in history) {
        if (kind != 'Tüm riskler' && record['type'].toString() != kind) { continue; }
        final events = record['events'];
        if (events is! List) continue;
        for (final event in events.whereType<Map>()) {
          final d = parse(event['at']);
          if (d != null && !d.isBefore(from) && d.isBefore(until) &&
              (event['event'] == 'Aktif' || event['event'] == 'Çözüldü')) {
            n++;
          }
        }
      }
      return n;
    }
    Future<void> persist() async {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(goalsKey, jsonEncode(goals));
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (loading) {
          loading = false;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(historyKey) ?? '{}');
              if (raw is Map) {
                for (final entry in raw.entries) {
                  if (entry.value is Map) history.add({...Map<String, dynamic>.from(entry.value as Map), 'riskKey': entry.key.toString()});
                }
              }
              final saved = jsonDecode(prefs.getString(goalsKey) ?? '[]');
              if (saved is List) goals.addAll(saved.whereType<Map>().map((e) => Map<String,dynamic>.from(e)));
            } catch (_) { error = 'Risk veya hedef kayıtları okunamadı.'; }
            if (ctx.mounted) refresh(() {});
          }).catchError((Object _) { if (ctx.mounted) refresh(() => error='Yerel kayıtlar açılamadı.'); });
        }
        final now = DateTime.now();
        final kinds = <String>{'Tüm riskler', ...history.map((r) => (r['type'] ?? 'Diğer').toString())}.toList()..sort();
        final shown = goals.where((g) => (filter == 'Tümü' || g['status'] == filter) &&
            '${g['title']} ${g['type']} ${g['note']}'.toLowerCase().contains(search.toLowerCase())).toList();
        final achieved = shown.where((g) {
          final start = parse(g['createdAt']);
          if (start == null) return false;
          final elapsed = now.difference(start).inDays;
          if (elapsed < (g['days'] as int? ?? 30)) return false;
          final current = countEvents(g['type'].toString(), start, start.add(Duration(days:g['days'] as int? ?? 30)));
          return current <= (g['target'] as int? ?? 0);
        }).length;
        return SafeArea(child: Padding(padding: EdgeInsets.only(left:16,right:16,top:12,bottom:MediaQuery.of(ctx).viewInsets.bottom+12),
          child: SizedBox(height:MediaQuery.of(ctx).size.height*.88,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Row(children:[const Expanded(child:Text('Risk Azaltma Hedefleri / Başarı Takibi',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
            if(error.isNotEmpty) Text(error,style:const TextStyle(color:Colors.red)),
            Text('Hedef: ${goals.length}  •  Görüntülenen: ${shown.length}  •  Ölçüm dönemi tamamlanıp hedefi karşılayan: $achieved'),
            const SizedBox(height:8),
            Wrap(spacing:8,runSpacing:8,children:[
              DropdownButton<int>(value:days,items:[7,14,30,60,90].map((d)=>DropdownMenuItem(value:d,child:Text('$d gün'))).toList(),onChanged:(v){if(v!=null)refresh(()=>days=v);}),
              DropdownButton<String>(value:filter,items:['Tümü','Aktif','Durduruldu','Tamamlandı'].map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null)refresh(()=>filter=v);}),
              FilledButton.tonalIcon(icon:const Icon(Icons.add_task),label:const Text('Yeni hedef'),onPressed:()async{
                var type='Tüm riskler';var title='';var note='';var reduction=25;
                final result=await showDialog<Map<String,dynamic>>(context:ctx,builder:(dialogCtx)=>StatefulBuilder(builder:(dctx,setDialog)=>AlertDialog(
                  title:const Text('Risk azaltma hedefi oluştur'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
                    TextField(decoration:const InputDecoration(labelText:'Hedef adı'),onChanged:(v)=>title=v),
                    DropdownButtonFormField<String>(initialValue:type,isExpanded:true,items:kinds.map((v)=>DropdownMenuItem(value:v,child:Text(v,overflow:TextOverflow.ellipsis))).toList(),onChanged:(v){if(v!=null)setDialog(()=>type=v);}),
                    DropdownButtonFormField<int>(initialValue:reduction,decoration:const InputDecoration(labelText:'Azalma hedefi (%)'),items:[10,20,25,30,40,50,60,75,90,100].map((v)=>DropdownMenuItem(value:v,child:Text('%$v'))).toList(),onChanged:(v){if(v!=null)setDialog(()=>reduction=v);}),
                    TextField(decoration:const InputDecoration(labelText:'Açıklama (isteğe bağlı)'),onChanged:(v)=>note=v),
                    const SizedBox(height:8),Text('Hedef dönemi: $days gün. Başlangıç karşılaştırması, önceki $days günlük kayıtlardır.'),
                  ])),actions:[TextButton(onPressed:()=>Navigator.pop(dctx),child:const Text('Vazgeç')),
                    FilledButton(onPressed:()=>Navigator.pop(dctx,{'type':type,'title':title.trim().isEmpty?'$type azaltma hedefi':title.trim(),'note':note,'reduction':reduction}),child:const Text('Oluştur'))])));
                if(result==null || !ctx.mounted)return;
                final start=DateTime.now();
                final baseline=countEvents(result['type'].toString(),start.subtract(Duration(days:days)),start);
                final target=(baseline*(100-(result['reduction'] as int))/100).floor();
                refresh(()=>goals.add({...result,'id':start.microsecondsSinceEpoch.toString(),'days':days,'baseline':baseline,'target':target,'createdAt':start.toIso8601String(),'status':'Aktif','updatedAt':start.toIso8601String(),'history':[{'at':start.toIso8601String(),'event':'Oluşturuldu'}]}));
                try {await persist();}catch(_){if(ctx.mounted)ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('Hedef kaydedilemedi.')));}
              }),
              OutlinedButton.icon(icon:const Icon(Icons.copy_all_outlined),label:const Text('CSV kopyala'),onPressed:()async{
                final lines=<String>['Hedef;Kategori;Durum;Başlangıç;Hedef;Güncel;Dönem;Hedef azalma (%)'];
                for(final g in shown){final start=parse(g['createdAt'])??now;final current=countEvents(g['type'].toString(),start,now);
                  lines.add([g['title'],g['type'],g['status'],g['baseline'],g['target'],current,g['days'],g['reduction']].map(quote).join(';'));}
                await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
                if(ctx.mounted)ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('CSV panoya kopyalandı.')));
              }),
            ]),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Hedef, risk türü veya not ara'),onChanged:(v)=>refresh(()=>search=v)),
            const SizedBox(height:8),
            Expanded(child:shown.isEmpty?const Center(child:Text('Bu filtrede kayıtlı hedef yok.')):ListView.builder(itemCount:shown.length,itemBuilder:(context,i){
              final g=shown[i];final start=parse(g['createdAt'])??now;final duration=g['days'] as int? ?? 30;
              final deadline=start.add(Duration(days:duration));final ended=!now.isBefore(deadline);
              final measured=countEvents(g['type'].toString(),start,ended?deadline:now);
              final baseline=g['baseline'] as int? ?? 0;final target=g['target'] as int? ?? 0;
              final progress=baseline==0?null:(100*(baseline-measured)/baseline);
              final met=ended && measured<=target;
              final events=(g['history'] is List ? g['history'] as List : const []).whereType<Map>().toList();
              return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text(g['title'].toString(),style:const TextStyle(fontWeight:FontWeight.bold)),
                Text('${g['type']} • ${g['status']} • $duration gün • ${deadline.day}.${deadline.month}.${deadline.year}'),
                Text('Başlangıç: $baseline • Hedef: en fazla $target • Ölçülen: $measured'),
                Text(progress==null?'Başlangıç dönemi veri içermiyor.':'Başlangıca göre değişim: %${progress.toStringAsFixed(1)}'),
                Text(ended?(met?'Hedef karşılandı':'Hedef karşılanmadı'):'Ölçüm dönemi sürüyor; sonuç kesinleşmedi.'),
                if(g['note'].toString().isNotEmpty)Text(g['note'].toString()),
                Wrap(spacing:6,children:[
                  if(g['status']=='Aktif')TextButton(onPressed:()async{refresh((){g['status']='Durduruldu';g['updatedAt']=DateTime.now().toIso8601String();(g['history'] as List).add({'at':g['updatedAt'],'event':'Durduruldu'});});await persist();},child:const Text('Durdur')),
                  if(g['status']=='Durduruldu')TextButton(onPressed:()async{refresh((){g['status']='Aktif';g['updatedAt']=DateTime.now().toIso8601String();(g['history'] as List).add({'at':g['updatedAt'],'event':'Yeniden açıldı'});});await persist();},child:const Text('Yeniden aç')),
                  if(g['status']!='Tamamlandı')TextButton(onPressed:()async{refresh((){g['status']='Tamamlandı';g['updatedAt']=DateTime.now().toIso8601String();(g['history'] as List).add({'at':g['updatedAt'],'event':'Kullanıcı tamamladı'});});await persist();},child:const Text('Tamamlandı işaretle')),
                  TextButton(onPressed:()=>showDialog<void>(context:ctx,builder:(dctx)=>AlertDialog(title:const Text('Hedef geçmişi'),content:SizedBox(width:300,child:ListView(shrinkWrap:true,children:events.map((e)=>ListTile(title:Text(e['event'].toString()),subtitle:Text(e['at'].toString()))).toList())),actions:[TextButton(onPressed:()=>Navigator.pop(dctx),child:const Text('Kapat'))])),child:Text('Geçmiş (${events.length})')),
                  TextButton(onPressed:()async{final yes=await showDialog<bool>(context:ctx,builder:(dctx)=>AlertDialog(title:const Text('Hedef silinsin mi?'),content:const Text('Bu hedef ve işlem geçmişi silinecek. Risk kayıtları korunur.'),actions:[TextButton(onPressed:()=>Navigator.pop(dctx,false),child:const Text('Vazgeç')),TextButton(onPressed:()=>Navigator.pop(dctx,true),child:const Text('Sil'))]));if(yes==true){refresh(()=>goals.remove(g));await persist();}},child:const Text('Sil')),
                ]),
              ])));
            })),
            const Text('Not: Bu ölçüm kayıtlı açılma/çözülme işlemlerini sayar; gerçek stok riski veya nedensel etki ölçümü değildir.',style:TextStyle(fontSize:11)),
          ]))));
      }));
  }

  void _showKitchenRiskTrendAnalysis() {
    const historyKey = 'kitchen_risk_tracking_v1';
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    var loading = true;
    var loadError = '';
    var window = 90;
    var category = 'Tümü';
    var status = 'Tümü';
    var query = '';
    var order = 'Son işlem';
    var onlyRepeated = false;
    final records = <Map<String, dynamic>>[];
    final actions = <Map<String, dynamic>>[];
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    DateTime? date(Object? value) => DateTime.tryParse((value ?? '').toString());
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (loading) {
          loading = false;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(historyKey) ?? '{}');
              if (raw is! Map) throw const FormatException('Uyarı verisi beklenen biçimde değil');
              for (final item in raw.entries) {
                if (item.value is! Map) continue;
                final row = Map<String, dynamic>.from(item.value as Map);
                row['riskKey'] = item.key.toString();
                records.add(row);
              }
              final actionRaw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (actionRaw is List) {
                actions.addAll(actionRaw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
              }
            } catch (_) { loadError = 'Kayıtlı risk geçmişi okunamadı.'; }
            if (ctx.mounted) refresh(() {});
          }).catchError((Object _) {if(ctx.mounted) refresh(() => loadError='Yerel depolama okunamadı.');});
        }
        final now = DateTime.now();
        final start = now.subtract(Duration(days:window));
        final types = <String>{'Tümü', ...records.map((r) => (r['type'] ?? 'Diğer').toString())}.toList()..sort();
        final chosenCategory = types.contains(category) ? category : 'Tümü';
        final rows = <Map<String, dynamic>>[];
        for (final r in records) {
          final events = (r['events'] is List ? r['events'] as List : const [])
              .whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          events.sort((a,b) => (date(a['at']) ?? DateTime(1970)).compareTo(date(b['at']) ?? DateTime(1970)));
          final recent = events.where((e) {final d=date(e['at']);return d!=null && !d.isBefore(start) && !d.isAfter(now);}).toList();
          final resolved = recent.where((e) => e['event']=='Çözüldü').toList();
          final reopened = recent.where((e) => e['event']=='Aktif').toList();
          final snoozed = recent.where((e) => e['event'].toString().contains('ertelendi')).toList();
          final first = date(r['firstSeen']);
          final last = date(r['lastUpdated']);
          final cycles = <int>[];
          DateTime? activeSince = first;
          for (final e in events) {
            final d = date(e['at']);
            if (d == null) continue;
            if (e['event']=='Çözüldü') {
              if (activeSince!=null && !d.isBefore(activeSince)) cycles.add(d.difference(activeSince).inHours);
              activeSince=null;
            } else if (e['event']=='Aktif' && activeSince==null) {activeSince=d;}
          }
          final linked = actions.where((a) => a['riskKey'] == r['riskKey']).toList();
          final currentStatus = (r['status'] ?? 'Aktif').toString();
          final age = first==null ? null : now.difference(first).inDays;
          final summary = <String,dynamic>{...r,'recent':recent.length,'resolved':resolved.length,
            'reopened':reopened.length,'snoozed':snoozed.length,'cycles':cycles,
            'linked':linked.length,'first':first,'last':last,'age':age,'currentStatus':currentStatus};
          if (recent.isEmpty && (last==null || last.isBefore(start))) continue;
          if (chosenCategory!='Tümü' && r['type']!=chosenCategory) continue;
          if (status!='Tümü' && currentStatus!=status) continue;
          if (onlyRepeated && reopened.isEmpty && resolved.length<2) continue;
          if (query.isNotEmpty && !'${r['title']} ${r['type']} ${r['source']}'.toLowerCase().contains(query.toLowerCase())) continue;
          rows.add(summary);
        }
        rows.sort((a,b) {
          if(order=='Tekrar') return (b['reopened'] as int).compareTo(a['reopened'] as int);
          if(order=='Çözüm') return (b['resolved'] as int).compareTo(a['resolved'] as int);
          if(order=='Yaş') return ((b['age'] as int?)??0).compareTo((a['age'] as int?)??0);
          return ((b['last'] as DateTime?)??DateTime(1970)).compareTo((a['last'] as DateTime?)??DateTime(1970));
        });
        final eventCount = rows.fold<int>(0,(n,r)=>n+(r['recent'] as int));
        final reopenCount = rows.fold<int>(0,(n,r)=>n+(r['reopened'] as int));
        final solvedCount = rows.fold<int>(0,(n,r)=>n+(r['resolved'] as int));
        final snoozeCount = rows.fold<int>(0,(n,r)=>n+(r['snoozed'] as int));
        final linkedCount = rows.where((r)=>(r['linked'] as int)>0).length;
        final allHours = rows.expand<int>((r)=>r['cycles'] as List<int>).toList();
        final averageHours = allHours.isEmpty ? null : allHours.reduce((a,b)=>a+b)/allHours.length;
        final csvRows = <String>['Risk;Tür;Kaynak;Durum;İlk görülme;Son işlem;İşlem;Çözüm;Yeniden açma;Erteleme;Aksiyon;Yaş (gün)',
          ...rows.map((r)=>[r['title'],r['type'],r['source'],r['currentStatus'],r['firstSeen'],r['lastUpdated'],r['recent'],r['resolved'],r['reopened'],r['snoozed'],r['linked'],r['age']].map(csv).join(';'))];
        Widget metric(String name,String value) => Card(color:_pink,child:Padding(padding:const EdgeInsets.all(10),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(name,style:const TextStyle(fontSize:12)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))])));
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
          Row(children:[const Expanded(child:Text('Tekrarlayan Uyarılar / Risk Eğilimleri',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Analiz yalnızca daha önce işlem yapılmış ve kaydedilmiş uyarılara dayanır. İşlem yapılmamış riskler ve geçmişteki anlık risk sayıları bilinmez.',style:TextStyle(fontSize:12)),
          if(loadError.isNotEmpty) Text(loadError,style:const TextStyle(color:Colors.red)),
          Wrap(spacing:6,runSpacing:6,children:[for(final d in [30,60,90,180,365]) ChoiceChip(label:Text('$d gün'),selected:window==d,onSelected:(_)=>refresh(()=>window=d))]),
          Wrap(spacing:6,runSpacing:6,children:[
            DropdownButton<String>(value:chosenCategory,items:types.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>category=v??'Tümü')),
            DropdownButton<String>(value:status,items:['Tümü','Aktif','Çözüldü'].map((v)=>DropdownMenuItem(value:v,child:Text('Durum: $v'))).toList(),onChanged:(v)=>refresh(()=>status=v??'Tümü')),
            DropdownButton<String>(value:order,items:['Son işlem','Tekrar','Çözüm','Yaş'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>order=v??'Son işlem')),
            FilterChip(label:const Text('Tekrarlayanlar'),selected:onlyRepeated,onSelected:(v)=>refresh(()=>onlyRepeated=v)),
          ]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Uyarı, kategori veya kaynak ara'),onChanged:(v)=>refresh(()=>query=v)),
          Wrap(spacing:6,runSpacing:6,children:[metric('Kayıtlı risk','${rows.length}'),metric('İşlem','$eventCount'),metric('Çözüm','$solvedCount'),metric('Yeniden açma','$reopenCount'),metric('Erteleme','$snoozeCount'),metric('Aksiyona bağlı','$linkedCount')]),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Ölçülebilen çözüm döngüsü: ${allHours.length}',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('Ortalama ilk görülme / yeniden açılmadan çözüme süre: ${averageHours==null?'Veri yok':'${(averageHours/24).toStringAsFixed(1)} gün'}'),
            const Text('Çözüm süresi kullanıcı işlemleri arasındaki farktır; sorunun gerçek başlangıç ve bitiş zamanını kesin olarak göstermez.',style:TextStyle(fontSize:12)),
          ]))),
          if(rows.isEmpty) const Padding(padding:EdgeInsets.all(16),child:Text('Seçilen dönemde kayıtlı uyarı işlemi bulunamadı.')),
          for(final r in rows) Card(child:ExpansionTile(
            title:Text((r['title']??'Uyarı').toString(),style:const TextStyle(fontWeight:FontWeight.w600)),
            subtitle:Text('${r['type']??'Diğer'} • ${r['currentStatus']} • ${r['recent']} işlem • ${r['reopened']} yeniden açma'),
            children:[Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Kaynak: ${r['source']??'—'}'),Text('İlk görülme: ${r['firstSeen']??'—'}'),Text('Son işlem: ${r['lastUpdated']??'—'}'),
              Text('Çözüm: ${r['resolved']} • Erteleme: ${r['snoozed']} • Bağlı aksiyon: ${r['linked']}'),
              const Divider(),const Text('İşlem geçmişi',style:TextStyle(fontWeight:FontWeight.bold)),
              for(final e in ((r['events'] is List?r['events'] as List:const []).whereType<Map>()))
                Text('• ${e['at']??'—'} — ${e['event']??'—'}',style:const TextStyle(fontSize:12)),
            ]))],
          )),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${csvRows.join('\r\n')}'));if(mounted)_notice('Risk eğilim raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Filtrelenmiş eğilim raporunu CSV kopyala')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenCriticalRiskCenter();},icon:const Icon(Icons.notification_important_outlined),label:const Text('Kritik uyarılar merkezine git')),
        ])));
      }));
  }













  // Aşama 21398–21647: güvenli, seçmeli plan geri alma simülasyonu.




  // Aşama 23648–23897: önleyici performans karnesi ve hedef iyileştirme.






  void _showKitchenDistributionTrendCenter() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const versionKey = 'paket40_optimization_plan_versions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final actions = <Map<String, dynamic>>[];
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    var started = false, loading = true, weeks = 8, query = '', ownerFilter = 'Tümü';
    var onlyRisk = false, onlyChanges = false, order = 'En yeni';
    DateTime anchor = DateTime.now();
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime monday(DateTime d) => day(d).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map a) { final n = '${a['owner'] ?? ''}'.trim(); return n.isEmpty ? 'Atanmamış' : n; }
    bool active(Map a) => !['Tamamlandı', 'İptal'].contains('${a['status'] ?? 'Açık'}');
    int duration(Map a) { final n = int.tryParse('${a['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    List<Map<String, dynamic>> rows(Object? v) => v is List ? v.whereType<Map>().map((a) => Map<String, dynamic>.from(a)).toList() : <Map<String, dynamic>>[];
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    Map<String, int> loads(List<Map<String, dynamic>> tasks) {
      final result = <String, int>{};
      for (final a in tasks) {
        if (!active(a)) continue;
        final d = parse(a['targetDate'] ?? a['due'] ?? a['nextDate']);
        if (d == null) continue;
        final k = '${who(a)}|${iso(d)}';
        result[k] = (result[k] ?? 0) + duration(a);
      }
      return result;
    }
    int excess(Map<String, int> values) => values.entries.fold<int>(0, (sum, e) {
      final name = e.key.split('|').first;
      return sum + (e.value > (capacities[name] ?? 120) ? e.value - (capacities[name] ?? 120) : 0);
    });
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            actions.addAll(rows(jsonDecode(prefs.getString(actionKey) ?? '[]')));
            versions.addAll(rows(jsonDecode(prefs.getString(versionKey) ?? '[]')));
            final cap = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (cap is Map) {
              for (final e in cap.entries) {
                final n = int.tryParse('${e.value}');
                if (n != null && n >= 15 && n <= 1440) capacities['${e.key}'] = n;
              }
            }
          } catch (_) { if (mounted) _notice('Bazı plan kayıtları okunamadı.'); }
          if (ctx.mounted) refresh(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final owners = <String>{'Tümü', ...actions.map(who)}.toList()..sort();
      final selected = owners.contains(ownerFilter) ? ownerFilter : 'Tümü';
      final items = <Map<String, dynamic>>[];
      for (final v in versions) {
        final at = parse(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        final before = rows(v['before']), after = rows(v['after']);
        if (before.isEmpty || after.isEmpty) continue;
        final beforeBy = <String, Map<String, dynamic>>{};
        for (final a in before) { final id = '${a['id'] ?? ''}'; if (id.isNotEmpty) beforeBy[id] = a; }
        var moved = 0, reassigned = 0, postponed = 0;
        final affected = <String>{};
        for (var i = 0; i < after.length; i++) {
          final a = after[i];
          final id = '${a['id'] ?? ''}';
          final b = id.isNotEmpty ? beforeBy[id] : (i < before.length ? before[i] : null);
          if (b == null) continue;
          final oldDate = '${b['targetDate'] ?? b['due'] ?? b['nextDate'] ?? ''}';
          final newDate = '${a['targetDate'] ?? a['due'] ?? a['nextDate'] ?? ''}';
          final ownerChanged = who(b) != who(a), dateChanged = oldDate != newDate;
          if (ownerChanged || dateChanged) { moved++; affected.add(who(b)); affected.add(who(a)); }
          if (ownerChanged) reassigned++;
          final od = parse(oldDate), nd = parse(newDate);
          if (od != null && nd != null && day(nd).isAfter(day(od))) postponed++;
        }
        if (selected != 'Tümü' && !affected.contains(selected)) continue;
        final reduction = excess(loads(before)) - excess(loads(after));
        final name = '${v['name'] ?? ''}', note = '${v['note'] ?? ''}', type = '${v['type'] ?? ''}';
        if (!'$name $note $type ${affected.join(' ')}'.toLowerCase().contains(query.toLowerCase())) continue;
        if (onlyRisk && reduction >= 0) continue;
        if (onlyChanges && moved == 0) continue;
        items.add({'version': v, 'at': at, 'week': monday(at), 'moved': moved, 'reassigned': reassigned, 'postponed': postponed, 'reduction': reduction, 'affected': affected.length, 'partial': before.length != after.length});
      }
      items.sort((a, b) {
        if (order == 'En fazla iyileşme') return (b['reduction'] as int).compareTo(a['reduction'] as int);
        if (order == 'En çok değişiklik') return (b['moved'] as int).compareTo(a['moved'] as int);
        if (order == 'En fazla kötüleşme') return (a['reduction'] as int).compareTo(b['reduction'] as int);
        return (b['at'] as DateTime).compareTo(a['at'] as DateTime);
      });
      final grouped = <DateTime, List<Map<String, dynamic>>>{};
      for (final e in items) { grouped.putIfAbsent(e['week'] as DateTime, () => []).add(e); }
      final weekly = grouped.entries.toList()..sort((a, b) => b.key.compareTo(a.key));
      final improved = items.where((e) => (e['reduction'] as int) > 0).length;
      final worsened = items.where((e) => (e['reduction'] as int) < 0).length;
      final unchanged = items.length - improved - worsened;
      final totalReduction = items.fold<int>(0, (sum, e) => sum + (e['reduction'] as int));
      final activeTasks = actions.where(active).toList();
      final current = loads(activeTasks);
      final ownerRisk = <String, int>{};
      for (final e in current.entries) {
        final name = e.key.split('|').first;
        final date = parse(e.key.split('|').last);
        if (date == null || date.isBefore(start) || !date.isBefore(end)) continue;
        if (selected != 'Tümü' && selected != name) continue;
        final over = e.value - (capacities[name] ?? 120);
        if (over > 0) ownerRisk[name] = (ownerRisk[name] ?? 0) + over;
      }
      final risks = ownerRisk.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
      final suggestions = <String>[];
      if (worsened > 0) suggestions.add('$worsened kayıtlı plan sürümünde kapasite aşımı arttı. Bu sürümlerde taşınan görevleri gözden geçir.');
      if (risks.isNotEmpty) suggestions.add('${risks.first.key} için seçili dönemde ${risks.first.value} dk planlanan kapasite aşımı var. Önceliği düşük görevleri daha sakin günlere dağıtmayı değerlendir.');
      if (items.isNotEmpty && improved * 2 < items.length) suggestions.add('İyileşme gösteren sürüm oranı %50 altında. Görev sürelerini ve günlük kapasite hedeflerini yeniden kontrol et.');
      if (items.any((e) => e['partial'] == true)) suggestions.add('Bazı sürümler farklı sayıda görev içeriyor; kapasite farkları tüm planı temsil etmeyebilir.');
      if (suggestions.isEmpty) suggestions.add('Bu filtrelerde belirgin kötüleşme yok. Yeni planları uygulamadan önce simülasyonla kontrol etmeyi sürdür.');
      final report = <String>['Hafta,Sürüm,Tür,Tarih,Taşınan görev,Sorumlu değişimi,Ertelenen görev,Kapasite aşımı azalma dk,Kısmi kayıt'];
      for (final e in items) {
        final v = e['version'] as Map;
        report.add([iso(e['week'] as DateTime), v['name'], v['type'], v['at'], e['moved'], e['reassigned'], e['postponed'], e['reduction'], e['partial']].map(csv).join(','));
      }
      return SafeArea(child:FractionallySizedBox(heightFactor: .94, child: ListView(padding: const EdgeInsets.all(16), children: [
        Row(children: [Expanded(child: Text('Görev dağılımı trendleri / kapasite iyileştirme', style: Theme.of(ctx).textTheme.titleLarge)), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        const Text('Kayıtlı plan sürümleri karşılaştırılır. Geçmiş gerçekleşen çalışma süresi değil, planlanan kapasite aşımı ölçülür. Kısmi sürümlerde sonuçlar yaklaşık olabilir.'),
        if (loading) const LinearProgressIndicator() else ...[
          Wrap(spacing: 10, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
            DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (n) => refresh(() => weeks = n ?? 8)),
            DropdownButton<String>(value: selected, items: owners.map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(), onChanged: (n) => refresh(() => ownerFilter = n ?? 'Tümü')),
            DropdownButton<String>(value: order, items: ['En yeni', 'En fazla iyileşme', 'En fazla kötüleşme', 'En çok değişiklik'].map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(), onChanged: (n) => refresh(() => order = n ?? 'En yeni')),
            IconButton(tooltip: 'Önceki dönem', onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)),
            Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
            IconButton(tooltip: 'Sonraki dönem', onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)),
            TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün')),
          ]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sürüm / açıklama / sorumlu ara'), onChanged: (v) => refresh(() => query = v)),
          SwitchListTile(title: const Text('Yalnızca kapasite aşımı artan sürümler'), value: onlyRisk, onChanged: (v) => refresh(() => onlyRisk = v)),
          SwitchListTile(title: const Text('Yalnızca görev değişikliği olan sürümler'), value: onlyChanges, onChanged: (v) => refresh(() => onlyChanges = v)),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('İncelenen sürüm: ${items.length} • İyileşen: $improved • Kötüleşen: $worsened • Sabit: $unchanged'),
            Text('Net planlanan kapasite aşımı azalması: $totalReduction dk'),
            Text('Taşınan görev hareketi: ${items.fold<int>(0, (n, e) => n + (e['moved'] as int))}'),
            Text('İyileşme oranı: %${items.isEmpty ? '0.0' : (improved / items.length * 100).toStringAsFixed(1)}'),
            LinearProgressIndicator(value: items.isEmpty ? 0 : improved / items.length),
          ]))),
          Card(child: ExpansionTile(title: Text('Güncel plan • sorumlu bazında risk (${risks.length})'), subtitle: const Text('Filtrelenen dönem için tüm açık görevlerden hesaplanır.'), children: risks.isEmpty ? [const ListTile(title: Text('Bu dönemde kapasite aşımı bulunamadı.'))] : risks.map((e) => ListTile(title: Text(e.key), subtitle: Text('${e.value} dk kapasite aşımı • günlük hedef ${capacities[e.key] ?? 120} dk'))).toList())),
          Card(child: ExpansionTile(initiallyExpanded: true, title: const Text('Kural tabanlı iyileştirme önerileri'), children: suggestions.map((s) => ListTile(leading: const Icon(Icons.tips_and_updates_outlined), title: Text(s))).toList())),
          ...weekly.map((week) {
            final net = week.value.fold<int>(0, (n, e) => n + (e['reduction'] as int));
            final good = week.value.where((e) => (e['reduction'] as int) > 0).length;
            return Card(child: ExpansionTile(title: Text('${iso(week.key)} haftası • ${week.value.length} sürüm'), subtitle: Text('Net aşım azalması: $net dk • İyileşen: $good'), children: [
              LinearProgressIndicator(value: week.value.isEmpty ? 0 : good / week.value.length),
              ...week.value.map((e) { final v = e['version'] as Map; return ListTile(title: Text('${v['name'] ?? 'Plan sürümü'}'), subtitle: Text('Aşım farkı: ${e['reduction']} dk • Görev: ${e['moved']} • Sorumlu değişimi: ${e['reassigned']} • Erteleme: ${e['postponed']}${e['partial'] == true ? ' • Kısmi kayıt' : ''}')); }),
            ]));
          }),
          if (items.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('Seçili dönemde uygun plan sürümü bulunamadı.')),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${report.join('\r\n')}')); if (mounted) _notice('Trend raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenSelectiveOptimizationResults(); }, icon: const Icon(Icons.analytics_outlined), label: const Text('Seçimli optimizasyon sonuçlarına geç')),
        ],
      ])));
    }));
  }

  void _showKitchenSelectiveOptimizationResults() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, onlyImproved = false, onlySelective = true;
    int weeks = 8;
    String query = '', order = 'En yeni';
    String t(Object? v) => '${v ?? ''}';
    int duration(Object? v) { final n = int.tryParse(t(v)); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    DateTime? parse(Object? v) => DateTime.tryParse(t(v));
    String owner(Map<String,dynamic> r) => t(r['owner']).trim().isEmpty ? 'Atanmamış' : t(r['owner']).trim();
    String csv(Object? v) => '"${t(v).replaceAll('"', '""')}"';
    List<Map<String,dynamic>> rows(Object? v) => v is List ? v.whereType<Map>().map((e) => Map<String,dynamic>.from(e)).toList() : <Map<String,dynamic>>[];
    Map<String,int> load(List<Map<String,dynamic>> data) {
      final result = <String,int>{};
      for(final r in data) {
        if(['Tamamlandı','İptal'].contains(t(r['status']))) continue;
        final date = parse(r['targetDate']);
        if(date == null) continue;
        final key = '${owner(r)}|${date.year}-${date.month}-${date.day}';
        result[key] = (result[key] ?? 0) + duration(r['estimatedMinutes']);
      }
      return result;
    }
    int overflow(Map<String,int> usage) {
      var total = 0;
      for(final e in usage.entries) {
        final who = e.key.split('|').first;
        final limit = capacities[who] ?? 120;
        if(e.value > limit) total += e.value - limit;
      }
      return total;
    }
    int overloaded(Map<String,int> usage) => usage.entries.where((e) => e.value > (capacities[e.key.split('|').first] ?? 120)).length;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if(!started) {
        started = true;
        () async {
          try {
            final prefs = await SharedPreferences.getInstance();
            final decoded = jsonDecode(prefs.getString(versionsKey) ?? '[]');
            final rawCaps = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if(decoded is List) versions.addAll(rows(decoded));
            if(rawCaps is Map) { for(final e in rawCaps.entries) {
              final n = int.tryParse(t(e.value));
              if(n != null && n > 0) capacities[t(e.key)] = n;
            } }
          } catch (_) { if(mounted) _notice('Optimizasyon geçmişi okunamadı.'); }
          if(ctx.mounted) refresh(() => loading = false);
        }();
      }
      final cutoff = DateTime.now().subtract(Duration(days: weeks * 7));
      final records = versions.where((v) {
        final at = parse(v['at']);
        if(at == null || at.isBefore(cutoff)) return false;
        if(onlySelective && !'${v['name']} ${v['type']} ${v['note']}'.toLowerCase().contains('seçimli')) return false;
        return '${v['name']} ${v['type']} ${v['note']}'.toLowerCase().contains(query.toLowerCase());
      }).map((v) {
        final before = rows(v['before']), after = rows(v['after']);
        final oldLoad = load(before), newLoad = load(after);
        final oldExcess = overflow(oldLoad), newExcess = overflow(newLoad);
        final oldById = <String,Map<String,dynamic>>{};
        for(final r in before) { final id = t(r['id']); if(id.isNotEmpty) oldById[id] = r; }
        var moved = 0, ownerMoves = 0, dateMoves = 0;
        final impacted = <String>{};
        for(final r in after) {
          final prior = oldById[t(r['id'])];
          if(prior == null) continue;
          final changedOwner = t(prior['owner']) != t(r['owner']);
          final changedDate = t(prior['targetDate']) != t(r['targetDate']);
          if(changedOwner || changedDate) {
            moved++;
            if(changedOwner) ownerMoves++;
            if(changedDate) dateMoves++;
            impacted.add(owner(prior)); impacted.add(owner(r));
          }
        }
        return <String,dynamic>{'record':v,'old':oldExcess,'new':newExcess,'gain':oldExcess-newExcess,
          'oldDays':overloaded(oldLoad),'newDays':overloaded(newLoad),'moved':moved,
          'ownerMoves':ownerMoves,'dateMoves':dateMoves,'people':impacted.length,
          'partial':before.isEmpty || after.isEmpty || before.length != after.length};
      }).where((r) => !onlyImproved || (r['gain'] as int) > 0).toList();
      records.sort((a,b) {
        if(order == 'En fazla iyileşme') return (b['gain'] as int).compareTo(a['gain'] as int);
        if(order == 'En fazla değişiklik') return (b['moved'] as int).compareTo(a['moved'] as int);
        final aa = t((a['record'] as Map)['at']), bb = t((b['record'] as Map)['at']);
        return order == 'En eski' ? aa.compareTo(bb) : bb.compareTo(aa);
      });
      final improved = records.where((r)=>(r['gain'] as int)>0).length;
      final worsened = records.where((r)=>(r['gain'] as int)<0).length;
      final totalGain = records.fold<int>(0,(sum,r)=>sum+(r['gain'] as int));
      final totalMoved = records.fold<int>(0,(sum,r)=>sum+(r['moved'] as int));
      final report = <String>['Sürüm;Tarih;Tür;Önce aşım dk;Sonra aşım dk;Fark dk;Önce riskli gün;Sonra riskli gün;Değişen görev;Sorumlu değişimi;Tarih değişimi;Etkilenen sorumlu;Kısmi kayıt'];
      for(final r in records) {
        final v = r['record'] as Map;
        report.add([v['name'],v['at'],v['type'],r['old'],r['new'],r['gain'],r['oldDays'],r['newDays'],r['moved'],r['ownerMoves'],r['dateMoves'],r['people'],r['partial']].map(csv).join(';'));
      }
      return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
        child: SizedBox(height: MediaQuery.of(ctx).size.height * .91,
          child: ListView(padding: const EdgeInsets.all(16), children: [
          Row(children: [const Expanded(child: Text('Seçimli optimizasyon • sonuç ve başarı analizi',
            style: TextStyle(fontSize: 19,fontWeight: FontWeight.bold))),
            IconButton(onPressed: ()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Kayıtlı plan sürümlerinin öncesi–sonrası karşılaştırması. Kısmi sürümlerde kapasite sonucu eksik olabilir.'),
          if(loading) const LinearProgressIndicator() else ...[
            Wrap(spacing: 8,runSpacing: 8,children: [
              DropdownButton<int>(value:weeks,items:[4,8,12,26,52].map((n)=>DropdownMenuItem(value:n,child:Text('$n hafta'))).toList(),onChanged:(n){if(n!=null)refresh(()=>weeks=n);}),
              DropdownButton<String>(value:order,items:['En yeni','En eski','En fazla iyileşme','En fazla değişiklik'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x){if(x!=null)refresh(()=>order=x);}),
            ]),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sürüm adı / tür / not ara'),onChanged:(x)=>refresh(()=>query=x)),
            SwitchListTile(title:const Text('Yalnızca seçimli optimizasyon sürümleri'),value:onlySelective,onChanged:(x)=>refresh(()=>onlySelective=x)),
            SwitchListTile(title:const Text('Yalnızca kapasite iyileşmesi olanlar'),value:onlyImproved,onChanged:(x)=>refresh(()=>onlyImproved=x)),
            Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('${records.length} sürüm • $totalMoved görev hareketi',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('İyileşen: $improved • Kötüleşen: $worsened • Değişmeyen: ${records.length-improved-worsened}'),
              Text('Kayıtlardaki net kapasite aşımı farkı: $totalGain dk'),
              LinearProgressIndicator(value:records.isEmpty?0:improved/records.length),
              Text('İyileşen sürüm oranı: ${records.isEmpty?0:(improved*100/records.length).round()}%'),
            ]))),
            if(records.isEmpty) const Card(child:ListTile(title:Text('Seçilen filtrelerde plan sürümü bulunamadı.'),subtitle:Text('Önce seçimli optimizasyon uygulayıp plan sürümü oluşturabilirsin.'))),
            for(final r in records) Card(child:ExpansionTile(
              title:Text(t((r['record'] as Map)['name'])),
              subtitle:Text('${t((r['record'] as Map)['at'])} • ${r['gain']} dk kapasite farkı'),
              children:[ListTile(title:Text('Önce ${r['old']} dk → Sonra ${r['new']} dk'),subtitle:Text('Riskli sorumlu-gün: ${r['oldDays']} → ${r['newDays']}')),
                ListTile(title:Text('${r['moved']} değişen görev • ${r['people']} etkilenen sorumlu'),subtitle:Text('${r['ownerMoves']} sorumlu ve ${r['dateMoves']} tarih değişimi')),
                if(r['partial']==true)const ListTile(leading:Icon(Icons.warning_amber_outlined),title:Text('Kısmi sürüm: kapasite karşılaştırması eksik olabilir.')),
              ])),
            const SizedBox(height:8),
            OutlinedButton.icon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('Optimizasyon sonuçları CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Sonuç raporunu CSV kopyala')),
            OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationVersions();},icon:const Icon(Icons.history),label:const Text('Plan sürümleri ve geri alma')),
            OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenSelectiveDistributionApply();},icon:const Icon(Icons.tune),label:const Text('Yeni seçimli optimizasyon')),
            const Text('Not: Bu rapor planlanan kapasite aşımını ölçer; gerçekleşen çalışma süresi veya görev tamamlama başarısı değildir.'),
          ],
        ]))));
    }));
  }

  void _showKitchenSelectiveDistributionApply() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capKey = 'paket39_daily_available_minutes_v1';
    const versionKey = 'paket40_optimization_plan_versions_v1';
    final tasks = <Map<String, dynamic>>[];
    final caps = <String, int>{};
    var loaded = false, busy = true, saving = false;
    var horizon = 14, maxMoves = 15, scenario = 2;
    var query = '', protectHigh = true, weekends = true, onlySelected = false;
    DateTime anchor = DateTime.now();
    final selected = <int>{};
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String owner(Map<String, dynamic> t) { final v = '${t['owner'] ?? ''}'.trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    bool high(Map<String, dynamic> t) => ['Kritik', 'Yüksek'].contains('${t['priority'] ?? t['level'] ?? ''}');
    int minutes(Map<String, dynamic> t) { final n = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    String identity(Map<String, dynamic> t) => '${t['createdAt'] ?? t['created'] ?? ''}|${t['title'] ?? ''}|${t['sourceProduct'] ?? ''}';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!loaded) {
        loaded = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final a = jsonDecode(prefs.getString(taskKey) ?? '[]');
            final c = jsonDecode(prefs.getString(capKey) ?? '{}');
            if (a is List) tasks.addAll(a.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            if (c is Map) for (final e in c.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) caps['${e.key}'] = n; }
          } catch (_) { if (ctx.mounted) _notice('Görev veya kapasite kayıtları okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final start = day(anchor), end = start.add(Duration(days: horizon));
      final people = <String>{...tasks.map(owner), ...caps.keys}.where((e) => e != 'Atanmamış').toList()..sort();
      String key(String person, DateTime date) => '$person|${iso(date)}';
      int capacity(String person) => caps[person] ?? 120;
      final eligible = <int>[];
      final baseLoad = <String, int>{};
      for (var i = 0; i < tasks.length; i++) {
        final t = tasks[i], d = parse(t['targetDate'] ?? t['due']);
        if (!active(t) || d == null || day(d).isBefore(start) || !day(d).isBefore(end)) continue;
        eligible.add(i);
        final k = key(owner(t), day(d));
        baseLoad[k] = (baseLoad[k] ?? 0) + minutes(t);
      }
      int excess(Map<String, int> loads) => loads.entries.fold<int>(0, (sum, e) {
        final diff = e.value - capacity(e.key.split('|').first);
        return sum + (diff > 0 ? diff : 0);
      });
      int riskyDays(Map<String, int> loads) => loads.entries.where((e) => e.value > capacity(e.key.split('|').first)).length;
      final candidates = eligible.where((i) => !protectHigh || !high(tasks[i])).toList();
      candidates.sort((a, b) {
        final ta = tasks[a], tb = tasks[b];
        final da = day(parse(ta['targetDate'] ?? ta['due'])!), db = day(parse(tb['targetDate'] ?? tb['due'])!);
        final aa = (baseLoad[key(owner(ta), da)] ?? 0) - capacity(owner(ta));
        final bb = (baseLoad[key(owner(tb), db)] ?? 0) - capacity(owner(tb));
        return bb.compareTo(aa);
      });
      final plans = <List<Map<String, dynamic>>>[];
      for (var kind = 0; kind < 3; kind++) {
        final load = Map<String, int>.from(baseLoad);
        final moves = <Map<String, dynamic>>[];
        for (final i in candidates) {
          if (moves.length >= maxMoves) break;
          final t = tasks[i], oldOwner = owner(t), oldDate = day(parse(t['targetDate'] ?? t['due'])!), duration = minutes(t);
          final oldKey = key(oldOwner, oldDate);
          if ((load[oldKey] ?? 0) <= capacity(oldOwner)) continue;
          Map<String, dynamic>? best;
          for (var offset = 0; offset < horizon; offset++) {
            final newDate = start.add(Duration(days: offset));
            if (!weekends && newDate.weekday >= 6) continue;
            if (kind == 0 && newDate == oldDate) continue;
            if (kind == 1 && newDate != oldDate) continue;
            for (final person in kind == 0 ? [oldOwner] : people) {
              if (kind == 1 && person == oldOwner) continue;
              if (person == oldOwner && newDate == oldDate) continue;
              final dest = key(person, newDate);
              if (capacity(person) - (load[dest] ?? 0) < duration) continue;
              final oldExcess = ((load[oldKey] ?? 0) - capacity(oldOwner)).clamp(0, 100000).toInt();
              final newExcess = ((load[oldKey] ?? 0) - duration - capacity(oldOwner)).clamp(0, 100000).toInt();
              final gain = oldExcess - newExcess;
              if (gain <= 0) continue;
              final score = gain * 10 - newDate.difference(oldDate).inDays.abs() * 2 - (person == oldOwner ? 0 : 5);
              if (best == null || score > (best['score'] as int)) best = {'index': i, 'toOwner': person, 'toDate': newDate, 'score': score, 'gain': gain};
            }
          }
          if (best == null) continue;
          final dest = key(best['toOwner'] as String, best['toDate'] as DateTime);
          load[oldKey] = (load[oldKey] ?? 0) - duration;
          load[dest] = (load[dest] ?? 0) + duration;
          moves.add(best);
        }
        plans.add(moves);
      }
      final proposals = plans[scenario];
      final validIds = proposals.map((m) => m['index'] as int).toSet();
      selected.removeWhere((i) => !validIds.contains(i));
      // Recalculate selected-only load from the full task population, not filtered rows.
      final simulated = Map<String, int>.from(baseLoad);
      for (final m in proposals.where((m) => selected.contains(m['index']))) {
        final t = tasks[m['index'] as int], d = day(parse(t['targetDate'] ?? t['due'])!), mins = minutes(t);
        final from = key(owner(t), d), to = key(m['toOwner'] as String, m['toDate'] as DateTime);
        simulated[from] = (simulated[from] ?? 0) - mins;
        simulated[to] = (simulated[to] ?? 0) + mins;
      }
      final shown = proposals.where((m) {
        if (onlySelected && !selected.contains(m['index'])) return false;
        final t = tasks[m['index'] as int];
        return '${t['title']} ${owner(t)} ${m['toOwner']}'.toLowerCase().contains(query.trim().toLowerCase());
      }).toList();
      Future<void> apply() async {
        if (selected.isEmpty || saving) { _notice('Önce en az bir görev seç.'); return; }
        final picked = proposals.where((m) => selected.contains(m['index'])).toList();
        final proceed = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
          title: const Text('Seçilen planı uygula?'),
          content: Text('${picked.length} açık görevin sorumlusu veya tarihi değişecek.\n'
            'Kapasite aşımı: ${excess(baseLoad)} → ${excess(simulated)} dk.\n'
            'İşlem öncesi ve sonrası plan sürümü saklanacak. Bu hesap gerçek müsaitliği doğrulamaz.'),
          actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
            FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Onayla ve kaydet'))]));
        if (proceed != true || !ctx.mounted) return;
        refresh(() => saving = true);
        try {
          final prefs = await SharedPreferences.getInstance();
          final oldRaw = prefs.getString(taskKey) ?? '[]';
          final decoded = jsonDecode(oldRaw);
          if (decoded is! List) throw StateError('Görev kaydı geçersiz');
          final fresh = decoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          if (fresh.length != tasks.length || jsonEncode(fresh) != jsonEncode(tasks)) {
            throw StateError('Görevler bu ekran açıldıktan sonra değişmiş. Ekranı kapatıp yeniden aç.');
          }
          final allIds = <String, int>{};
          for (final t in fresh) { final id = identity(t); allIds[id] = (allIds[id] ?? 0) + 1; }
          for (final m in picked) {
            final i = m['index'] as int, t = fresh[i];
            if (!active(t) || (allIds[identity(t)] ?? 0) != 1) throw StateError('Kapalı veya kimliği belirsiz görev var.');
          }
          final oldVersionRaw = prefs.getString(versionKey);
          final versionsDecoded = jsonDecode(oldVersionRaw ?? '[]');
          if (versionsDecoded is! List) throw StateError('Plan sürüm geçmişi geçersiz');
          final versions = versionsDecoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          final before = <Map<String, dynamic>>[], after = <Map<String, dynamic>>[];
          final stamp = DateTime.now().toIso8601String();
          for (final m in picked) {
            final i = m['index'] as int, t = fresh[i];
            before.add({'identity': identity(t), 'title': t['title'], 'owner': t['owner'], 'targetDate': t['targetDate'], 'estimatedMinutes': t['estimatedMinutes']});
            final previousOwner = owner(t), previousDate = '${t['targetDate'] ?? ''}';
            t['owner'] = m['toOwner'];
            t['targetDate'] = iso(m['toDate'] as DateTime);
            t['updated'] = stamp;
            final history = t['history'] is List ? List<dynamic>.from(t['history'] as List) : <dynamic>[];
            history.add({'at': stamp, 'action': 'Seçimli görev dağılımı', 'note': '$previousOwner / $previousDate → ${m['toOwner']} / ${t['targetDate']}'});
            t['history'] = history;
            after.add({'identity': identity(t), 'title': t['title'], 'owner': t['owner'], 'targetDate': t['targetDate'], 'estimatedMinutes': t['estimatedMinutes']});
          }
          final record = <String, dynamic>{'at': stamp, 'name': 'Seçimli dağılım • ${['Tarih', 'Sorumlu', 'Karma'][scenario]}',
            'note': '${picked.length} görev • ${excess(baseLoad)} → ${excess(simulated)} dk kapasite aşımı',
            'type': 'selective_distribution', 'before': before, 'after': after};
          versions.insert(0, record);
          if (!await prefs.setString(taskKey, jsonEncode(fresh))) throw StateError('Görevler kaydedilemedi');
          if (!await prefs.setString(versionKey, jsonEncode(versions.take(100).toList()))) {
            await prefs.setString(taskKey, oldRaw);
            if (oldVersionRaw != null) await prefs.setString(versionKey, oldVersionRaw);
            throw StateError('Sürüm kaydı başarısız; görev geri yükleme denendi');
          }
          tasks..clear()..addAll(fresh);
          selected.clear();
          if (ctx.mounted) { refresh(() {}); _notice('${picked.length} görev güncellendi ve plan sürümü kaydedildi.'); }
        } catch (e) { if (ctx.mounted) _notice('İşlem uygulanamadı: $e'); }
        finally { if (ctx.mounted) refresh(() => saving = false); }
      }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: Padding(padding: const EdgeInsets.all(14), child: Column(children: [
        Row(children: [const Expanded(child: Text('Seçimli görev dağılımı / optimizasyon uygulama', style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold))),
          IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (busy) const Expanded(child: Center(child: CircularProgressIndicator())) else Expanded(child: ListView(children: [
          const Text('Üç senaryodan birini seç, görevleri işaretle, yalnızca seçtiklerinin kapasite etkisini gör ve onayla. Kritik görevler varsayılan olarak korunur.'),
          Wrap(spacing: 10, runSpacing: 5, children: [
            DropdownButton<int>(value: horizon, items: [7, 14, 21, 28].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(),
              onChanged: (v) => refresh(() { horizon = v ?? 14; selected.clear(); })),
            DropdownButton<int>(value: maxMoves, items: [5, 10, 15, 25, 40].map((n) => DropdownMenuItem(value: n, child: Text('En çok $n öneri'))).toList(),
              onChanged: (v) => refresh(() { maxMoves = v ?? 15; selected.clear(); })),
            IconButton(tooltip: 'Önceki dönem', onPressed: () => refresh(() { anchor = anchor.subtract(Duration(days: horizon)); selected.clear(); }), icon: const Icon(Icons.chevron_left)),
            Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
            IconButton(tooltip: 'Sonraki dönem', onPressed: () => refresh(() { anchor = anchor.add(Duration(days: horizon)); selected.clear(); }), icon: const Icon(Icons.chevron_right)),
            TextButton(onPressed: () => refresh(() { anchor = DateTime.now(); selected.clear(); }), child: const Text('Bugün')),
          ]),
          SwitchListTile(dense: true, title: const Text('Kritik / yüksek öncelikli görevleri koru'), value: protectHigh,
            onChanged: (v) => refresh(() { protectHigh = v; selected.clear(); })),
          SwitchListTile(dense: true, title: const Text('Hafta sonuna öneri yapılabilsin'), value: weekends,
            onChanged: (v) => refresh(() { weekends = v; selected.clear(); })),
          const Divider(),
          for (var i = 0; i < plans.length; i++) Card(child: ListTile(
            selected: scenario == i, leading: Icon(scenario == i ? Icons.radio_button_checked : Icons.radio_button_unchecked),
            title: Text(['Tarih odaklı', 'Sorumlu odaklı', 'Karma dağılım'][i]),
            subtitle: Text('${plans[i].length} öneri • ${plans[i].fold<int>(0, (s, m) => s + (m['gain'] as int))} dk tahmini aşım azalması'),
            onTap: () => refresh(() { scenario = i; selected.clear(); }))),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Seçili görev: ${selected.length} / ${proposals.length}', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('Kapasite aşımı: ${excess(baseLoad)} → ${excess(simulated)} dk'),
            Text('Aşırı yüklü sorumlu-gün: ${riskyDays(baseLoad)} → ${riskyDays(simulated)}'),
            LinearProgressIndicator(value: excess(baseLoad) == 0 ? 1 : (1 - excess(simulated) / excess(baseLoad)).clamp(0.0, 1.0).toDouble()),
            const Text('Kapasite hesapları seçili görevler ve dönemdeki tüm açık görevler üzerinden yapılır.', style: TextStyle(fontSize: 12)),
          ]))),
          Wrap(spacing: 8, children: [
            TextButton.icon(onPressed: () => refresh(() => selected.addAll(proposals.map((m) => m['index'] as int))), icon: const Icon(Icons.select_all), label: const Text('Tümünü seç')),
            TextButton.icon(onPressed: () => refresh(selected.clear), icon: const Icon(Icons.clear_all), label: const Text('Seçimi temizle')),
          ]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Görev / sorumlu ara'), onChanged: (v) => refresh(() => query = v)),
          CheckboxListTile(dense: true, title: const Text('Yalnızca seçilenleri göster'), value: onlySelected, onChanged: (v) => refresh(() => onlySelected = v ?? false)),
          if (shown.isEmpty) const Padding(padding: EdgeInsets.all(12), child: Text('Bu koşullarda gösterilecek öneri bulunamadı.')),
          for (final m in shown) CheckboxListTile(
            value: selected.contains(m['index']),
            onChanged: saving ? null : (v) => refresh(() { if (v == true) { selected.add(m['index'] as int); } else { selected.remove(m['index']); } }),
            title: Text('${tasks[m['index'] as int]['title'] ?? 'Görev'} • ${minutes(tasks[m['index'] as int])} dk'),
            subtitle: Text('${owner(tasks[m['index'] as int])} / ${iso(day(parse(tasks[m['index'] as int]['targetDate'] ?? tasks[m['index'] as int]['due'])!))} → ${m['toOwner']} / ${iso(m['toDate'] as DateTime)}')),
          const SizedBox(height: 10),
          FilledButton.icon(onPressed: selected.isEmpty || saving ? null : apply, icon: const Icon(Icons.check_circle_outline),
            label: Text(saving ? 'Kaydediliyor…' : '${selected.length} seçili görevi onayla ve uygula')),
          FilledButton.tonalIcon(onPressed: () async {
            final rows = <String>['Senaryo,Görev,Önceki sorumlu,Yeni sorumlu,Önceki tarih,Yeni tarih,Dakika,Seçildi'];
            for (final m in shown) {
              final t = tasks[m['index'] as int];
              rows.add([['Tarih', 'Sorumlu', 'Karma'][scenario], t['title'], owner(t), m['toOwner'],
                iso(day(parse(t['targetDate'] ?? t['due'])!)), iso(m['toDate'] as DateTime), minutes(t), selected.contains(m['index']) ? 'Evet' : 'Hayır'].map(csv).join(','));
            }
            await Clipboard.setData(ClipboardData(text: '\uFEFF${rows.join('\r\n')}'));
            if (ctx.mounted) _notice('${shown.length} öneri CSV olarak kopyalandı.');
          }, icon: const Icon(Icons.copy), label: const Text('Önerileri CSV kopyala')),
          const SizedBox(height: 10),
          const Text('Not: Tahminler kural tabanlıdır. Kişilerin gerçek müsaitliği ve görev yetkinliği kontrol edilmez. Kaydetmeden önce görev kayıtları yeniden doğrulanır.', style: TextStyle(fontSize: 12)),
        ]))
      ]))));
    }));
  }

  void _showKitchenDistributionSimulationCenter() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capKey = 'paket39_daily_available_minutes_v1';
    final tasks = <Map<String, dynamic>>[];
    final caps = <String, int>{};
    var started = false, loading = true, horizon = 14, maxMoves = 15;
    var mode = 0, ownerFilter = 'Tümü', query = '', weekends = true;
    var onlyChanges = false, protectHigh = true;
    DateTime anchor = DateTime.now();
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map<String, dynamic> t) { final v = '${t['owner'] ?? ''}'.trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    bool high(Map<String, dynamic> t) => ['Kritik', 'Yüksek'].contains('${t['priority'] ?? t['level'] ?? ''}');
    int mins(Map<String, dynamic> t) { final n = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, update) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final decoded = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (decoded is List) tasks.addAll(decoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            final raw = jsonDecode(prefs.getString(capKey) ?? '{}');
            if (raw is Map) for (final e in raw.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) caps['${e.key}'] = n; }
          } catch (_) { if (ctx.mounted) _notice('Görev veya kapasite kayıtları okunamadı.'); }
          if (ctx.mounted) update(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
      }
      final start = day(anchor), end = start.add(Duration(days: horizon));
      final owners = {...tasks.map(who), ...caps.keys}.where((v) => v != 'Atanmamış').toList()..sort();
      final selectedOwner = ownerFilter == 'Tümü' || owners.contains(ownerFilter) ? ownerFilter : 'Tümü';
      final eligible = tasks.where((t) {
        final d = parse(t['targetDate'] ?? t['due']);
        return active(t) && d != null && !day(d).isBefore(start) && day(d).isBefore(end);
      }).toList();
      String key(String person, DateTime d) => '$person|${iso(d)}';
      int capacity(String person) => caps[person] ?? 120;
      final baseLoad = <String, int>{};
      for (final t in eligible) {
        final k = key(who(t), day(parse(t['targetDate'] ?? t['due'])!));
        baseLoad[k] = (baseLoad[k] ?? 0) + mins(t);
      }
      int over(Map<String, int> loads) {
        var total = 0;
        for (final e in loads.entries) {
          final person = e.key.split('|').first;
          if (e.value > capacity(person)) total += e.value - capacity(person);
        }
        return total;
      }
      int overDays(Map<String, int> loads) => loads.entries.where((e) => e.value > capacity(e.key.split('|').first)).length;
      final baseOver = over(baseLoad);
      final plans = <Map<String, dynamic>>[];
      for (var scenario = 0; scenario < 3; scenario++) {
        final load = Map<String, int>.from(baseLoad);
        final moves = <Map<String, dynamic>>[];
        final candidates = eligible.where((t) => !protectHigh || !high(t)).toList()
          ..sort((a, b) {
            final da = day(parse(a['targetDate'] ?? a['due'])!);
            final db = day(parse(b['targetDate'] ?? b['due'])!);
            final ao = (baseLoad[key(who(a), da)] ?? 0) - capacity(who(a));
            final bo = (baseLoad[key(who(b), db)] ?? 0) - capacity(who(b));
            return bo.compareTo(ao);
          });
        for (final t in candidates) {
          if (moves.length >= maxMoves) break;
          final oldOwner = who(t), oldDay = day(parse(t['targetDate'] ?? t['due'])!);
          final oldKey = key(oldOwner, oldDay), duration = mins(t);
          if ((load[oldKey] ?? 0) <= capacity(oldOwner)) continue;
          if (selectedOwner != 'Tümü' && oldOwner != selectedOwner) continue;
          final choices = <Map<String, dynamic>>[];
          for (var offset = 0; offset < horizon; offset++) {
            final candidateDay = start.add(Duration(days: offset));
            if (!weekends && candidateDay.weekday >= 6) continue;
            if (scenario == 1 && candidateDay != oldDay) continue;
            if (scenario == 0 && candidateDay == oldDay) continue;
            for (final person in scenario == 0 ? [oldOwner] : owners) {
              if (person == 'Atanmamış') continue;
              if (scenario == 1 && person == oldOwner) continue;
              if (scenario == 2 && person == oldOwner && candidateDay == oldDay) continue;
              final newKey = key(person, candidateDay);
              if (newKey == oldKey) continue;
              final available = capacity(person) - (load[newKey] ?? 0);
              if (available < duration) continue;
              final originalOver = (load[oldKey]! - capacity(oldOwner)).clamp(0, 100000).toInt();
              final remainingOver = (load[oldKey]! - duration - capacity(oldOwner)).clamp(0, 100000).toInt();
              final gain = originalOver - remainingOver;
              if (gain <= 0) continue;
              final shift = candidateDay.difference(oldDay).inDays.abs();
              final penalty = shift * 2 + (person == oldOwner ? 0 : 5);
              choices.add({'owner': person, 'date': candidateDay, 'gain': gain, 'score': gain * 10 - penalty, 'shift': shift});
            }
          }
          if (choices.isEmpty) continue;
          choices.sort((a, b) => (b['score'] as int).compareTo(a['score'] as int));
          final best = choices.first, newOwner = best['owner'] as String, newDay = best['date'] as DateTime;
          load[oldKey] = load[oldKey]! - duration;
          final newKey = key(newOwner, newDay);
          load[newKey] = (load[newKey] ?? 0) + duration;
          moves.add({'title': '${t['title'] ?? 'Görev'}', 'fromOwner': oldOwner, 'toOwner': newOwner,
            'fromDate': oldDay, 'toDate': newDay, 'minutes': duration, 'gain': best['gain']});
        }
        plans.add({'name': ['Tarih odaklı', 'Sorumlu odaklı', 'Karma dengeleme'][scenario],
          'moves': moves, 'over': over(load), 'days': overDays(load), 'improvement': baseOver - over(load)});
      }
      final ranking = [...plans]..sort((a, b) {
        final c = (a['over'] as int).compareTo(b['over'] as int);
        return c != 0 ? c : (a['moves'] as List).length.compareTo((b['moves'] as List).length);
      });
      final current = plans[mode], moves = current['moves'] as List<Map<String, dynamic>>;
      final visible = moves.where((m) {
        if (onlyChanges && m['fromOwner'] == m['toOwner'] && m['fromDate'] == m['toDate']) return false;
        final q = query.toLowerCase().trim();
        return q.isEmpty || '${m['title']} ${m['fromOwner']} ${m['toOwner']}'.toLowerCase().contains(q);
      }).toList();
      Widget metric(String title, String value) => Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(children: [Text(title, textAlign: TextAlign.center), const SizedBox(height: 5), Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 17))])));
      return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Padding(padding: const EdgeInsets.all(14), child: Column(children: [
        Row(children: [const Expanded(child: Text('Görev dağılımı simülasyonu / kapasite optimizasyonu', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 17))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (loading) const Expanded(child: Center(child: CircularProgressIndicator())) else Expanded(child: ListView(children: [
          const Text('Kayıtlı görevler üzerinden üç farklı senaryo hesaplanır. Bu ekran yalnızca simülasyon yapar; görev veya kapasite kayıtlarını değiştirmez.'),
          Wrap(spacing: 8, runSpacing: 5, children: [
            DropdownButton<int>(value: horizon, items: [7,14,21,28].map((n) => DropdownMenuItem(value:n, child:Text('$n gün'))).toList(), onChanged:(v)=>update(()=>horizon=v??14)),
            DropdownButton<int>(value: maxMoves, items: [5,10,15,25,40].map((n)=>DropdownMenuItem(value:n,child:Text('En çok $n taşıma'))).toList(),onChanged:(v)=>update(()=>maxMoves=v??15)),
            DropdownButton<String>(value:selectedOwner, items:['Tümü',...owners].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>ownerFilter=v??'Tümü')),
            IconButton(tooltip:'Önceki dönem',onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:horizon))),icon:const Icon(Icons.chevron_left)),
            Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
            IconButton(tooltip:'Sonraki dönem',onPressed:()=>update(()=>anchor=anchor.add(Duration(days:horizon))),icon:const Icon(Icons.chevron_right)),
            TextButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),
          ]),
          SwitchListTile(dense:true,title:const Text('Hafta sonuna görev öner'),value:weekends,onChanged:(v)=>update(()=>weekends=v)),
          SwitchListTile(dense:true,title:const Text('Kritik / yüksek öncelikli görevleri koru'),value:protectHigh,onChanged:(v)=>update(()=>protectHigh=v)),
          Wrap(spacing:5,children:[metric('Görev', '${eligible.length}'),metric('Mevcut aşım', '$baseOver dk'),metric('Riskli gün', '${overDays(baseLoad)}')]),
          const Divider(),
          for (var i=0;i<plans.length;i++) Card(child: ListTile(
            selected:mode==i,leading:Icon(mode==i?Icons.radio_button_checked:Icons.radio_button_unchecked),
            title:Text('${plans[i]['name']}${identical(ranking.first,plans[i])?' • En düşük aşım':''}'),
            subtitle:Text('Aşım: ${plans[i]['over']} dk • İyileşme: ${plans[i]['improvement']} dk • Taşıma: ${(plans[i]['moves'] as List).length} • Riskli gün: ${plans[i]['days']}'),
            onTap:()=>update(()=>mode=i))),
          const SizedBox(height:8),
          Text('Seçilen senaryo: ${current['name']}',style:const TextStyle(fontWeight:FontWeight.bold)),
          Text('Kapasite aşımı: $baseOver → ${current['over']} dk. Bu sonuç gerçek müsaitlik veya görev yetkinliğini doğrulamaz.'),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Önerilerde ara'),onChanged:(v)=>update(()=>query=v)),
          CheckboxListTile(title:const Text('Yalnızca değişiklikleri göster'),value:onlyChanges,onChanged:(v)=>update(()=>onlyChanges=v??false)),
          if (visible.isEmpty) const Padding(padding:EdgeInsets.all(16),child:Text('Bu koşullarda uygun görev taşıma önerisi bulunamadı.')),
          for (final m in visible) Card(child:ListTile(
            title:Text('${m['title']} • ${m['minutes']} dk'),
            subtitle:Text('${m['fromOwner']} / ${iso(m['fromDate'] as DateTime)} → ${m['toOwner']} / ${iso(m['toDate'] as DateTime)}\nTahmini aşım azalması: ${m['gain']} dk'))),
          FilledButton.tonalIcon(onPressed:(){
            final lines=<String>['Senaryo,Görev,Önceki sorumlu,Yeni sorumlu,Önceki tarih,Yeni tarih,Dakika,Aşım azalması'];
            for(final m in visible) { lines.add([current['name'],m['title'],m['fromOwner'],m['toOwner'],iso(m['fromDate'] as DateTime),iso(m['toDate'] as DateTime),m['minutes'],m['gain']].map(csv).join(',')); }
            Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
            _notice('${visible.length} öneri CSV olarak panoya kopyalandı.');
          },icon:const Icon(Icons.copy),label:const Text('Önerileri CSV olarak kopyala')),
          const Text('Not: Senaryolar önizlemedir. Uygulamak için mevcut onaylı planlama ekranından yeniden değerlendirme yapın.'),
        ]))
      ]))));
    }));
  }

  void _showKitchenCapacityPerformanceRecommendations() {
    const actionsKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    var started = false, loading = true, horizon = 14, bonus = 0;
    var ownerFilter = 'Tümü', search = '', riskOnly = false, includeWeekends = true;
    var threshold = 85, sortMode = 0;
    DateTime anchor = DateTime.now();
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map<String, dynamic> t) { final v = '${t['owner'] ?? ''}'.trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    int mins(Map<String, dynamic> t) { final n = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool critical(Map<String, dynamic> t) => ['Kritik', 'Yüksek'].contains('${t['priority'] ?? t['level'] ?? ''}');
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, update) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(actionsKey) ?? '[]');
            if (raw is List) { tasks..clear()..addAll(raw.whereType<Map>().map((v) => Map<String, dynamic>.from(v))); }
            final saved = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (saved is Map) { for (final e in saved.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) capacities['${e.key}'] = n; } }
          } catch (_) { if (ctx.mounted) _notice('Görev veya kapasite verileri kısmen okunamadı.'); }
          if (ctx.mounted) update(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
      }
      final start = day(anchor), end = start.add(Duration(days: horizon));
      final people = {...tasks.map(who), ...capacities.keys}.toList()..sort();
      final selected = ownerFilter == 'Tümü' || people.contains(ownerFilter) ? ownerFilter : 'Tümü';
      final scheduled = tasks.where((t) {
        final d = parse(t['targetDate'] ?? t['due']);
        return active(t) && d != null && !day(d).isBefore(start) && day(d).isBefore(end);
      }).toList();
      final days = <Map<String, dynamic>>[];
      final owners = <String, Map<String, int>>{};
      final groups = <String, List<Map<String, dynamic>>>{};
      for (final t in scheduled) {
        final d = parse(t['targetDate'] ?? t['due'])!;
        final k = '${who(t)}|${iso(d)}';
        groups.putIfAbsent(k, () => []).add(t);
      }
      for (final entry in groups.entries) {
        final list = entry.value, person = who(list.first);
        final date = day(parse(list.first['targetDate'] ?? list.first['due'])!);
        final capacity = ((capacities[person] ?? 120) + bonus).clamp(15, 1440).toInt();
        final load = list.fold<int>(0, (v, t) => v + mins(t));
        final criticalCount = list.where(critical).length;
        final over = (load - capacity).clamp(0, 100000).toInt();
        final utilization = load * 100 / capacity;
        final record = <String, dynamic>{'owner': person, 'date': date, 'tasks': list, 'load': load, 'capacity': capacity, 'over': over, 'utilization': utilization, 'critical': criticalCount};
        days.add(record);
        final stats = owners.putIfAbsent(person, () => {'tasks': 0, 'load': 0, 'capacity': 0, 'over': 0, 'riskDays': 0, 'critical': 0});
        stats['tasks'] = stats['tasks']! + list.length;
        stats['load'] = stats['load']! + load;
        stats['capacity'] = stats['capacity']! + capacity;
        stats['over'] = stats['over']! + over;
        stats['riskDays'] = stats['riskDays']! + (utilization >= threshold ? 1 : 0);
        stats['critical'] = stats['critical']! + criticalCount;
      }
      final visible = days.where((r) {
        if (selected != 'Tümü' && r['owner'] != selected) return false;
        if (!includeWeekends && (r['date'] as DateTime).weekday >= 6) return false;
        if (riskOnly && (r['utilization'] as double) < threshold) return false;
        final needle = search.trim().toLowerCase();
        if (needle.isEmpty) return true;
        return '${r['owner']} ${iso(r['date'] as DateTime)} ${(r['tasks'] as List<Map<String, dynamic>>).map((t) => t['title']).join(' ')}'.toLowerCase().contains(needle);
      }).toList();
      visible.sort((a, b) {
        if (sortMode == 1) return (b['over'] as int).compareTo(a['over'] as int);
        if (sortMode == 2) return (b['utilization'] as double).compareTo(a['utilization'] as double);
        if (sortMode == 3) return (b['critical'] as int).compareTo(a['critical'] as int);
        return (a['date'] as DateTime).compareTo(b['date'] as DateTime);
      });
      final totalLoad = scheduled.fold<int>(0, (v, t) => v + mins(t));
      final totalOver = days.fold<int>(0, (v, r) => v + r['over'] as int);
      final atRisk = days.where((r) => (r['utilization'] as double) >= threshold).length;
      final capacityCases = <Map<String, int>>[];
      for (final extra in [0, 30, 60]) {
        var over = 0, risk = 0;
        for (final r in days) {
          final cap = ((r['capacity'] as int) + extra).clamp(15, 1440).toInt();
          final load = r['load'] as int;
          over += (load - cap).clamp(0, 100000).toInt();
          if (load * 100 / cap >= threshold) risk++;
        }
        capacityCases.add({'extra': extra, 'over': over, 'risk': risk});
      }
      final suggestions = <String>[];
      if (totalOver > 0) suggestions.add('Kapasite aşımı $totalOver dk: kritik olmayan görevlerin tarihini veya sorumlusunu yeniden değerlendirin.');
      if (atRisk > 0) suggestions.add('$atRisk sorumlu-gün, %$threshold doluluk eşiğine ulaşıyor. Yoğun günleri erken gözden geçirin.');
      final rankedOwners = owners.entries.toList()..sort((a, b) => b.value['over']!.compareTo(a.value['over']!));
      if (rankedOwners.isNotEmpty && rankedOwners.first.value['over']! > 0) suggestions.add('${rankedOwners.first.key} için ${rankedOwners.first.value['over']} dk kapasite aşımı var; görev dağılımını dengeleyin.');
      if (scheduled.any((t) => who(t) == 'Atanmamış')) suggestions.add('Atanmamış görevler var; sorumlu ataması yaparak kapasite görünürlüğünü artırın.');
      if (scheduled.any((t) => int.tryParse('${t['estimatedMinutes'] ?? ''}') == null)) suggestions.add('Süre tahmini olmayan görevler 30 dk varsayılıyor; gerçek tahminleri kaydedin.');
      if (suggestions.isEmpty) suggestions.add('Seçili dönemde belirgin kapasite aşımı bulunamadı. Kritik görevlerin tarihlerini düzenli izleyin.');
      final export = <String>['Tarih,Sorumlu,Görev sayısı,Kritik görev,Planlanan dakika,Kapasite dakika,Aşım dakika,Doluluk yüzde'];
      for (final r in visible) { export.add([iso(r['date'] as DateTime), r['owner'], (r['tasks'] as List).length, r['critical'], r['load'], r['capacity'], r['over'], (r['utilization'] as double).toStringAsFixed(1)].map(csv).join(',')); }
      return SafeArea(child: Padding(padding: const EdgeInsets.all(16), child: ListView(children: [
        Row(children: [const Expanded(child: Text('Kapasite performansı / görev dağılımı önerileri', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (loading) const LinearProgressIndicator() else ...[
          const Text('Açık görevlerin planlanan iş yükünü değerlendirir. Kapasite +30/+60 dk senaryoları yalnızca varsayımsaldır; görevleri veya kayıtlı kapasiteyi değiştirmez.'),
          Wrap(spacing: 10, runSpacing: 6, children: [
            DropdownButton<int>(value: horizon, items: [7, 14, 21, 28].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(), onChanged: (n) => update(() => horizon = n ?? 14)),
            DropdownButton<int>(value: bonus, items: [0, 15, 30, 60].map((n) => DropdownMenuItem(value: n, child: Text('Temel kapasite +$n dk'))).toList(), onChanged: (n) => update(() => bonus = n ?? 0)),
            DropdownButton<int>(value: threshold, items: [70, 80, 85, 90, 100].map((n) => DropdownMenuItem(value: n, child: Text('Risk ≥%$n'))).toList(), onChanged: (n) => update(() => threshold = n ?? 85)),
          ]),
          Row(children: [IconButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: horizon))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: horizon))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('${scheduled.length} açık görev • $totalLoad dk planlanan yük', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('$totalOver dk kapasite aşımı • $atRisk riskli sorumlu-gün • ${owners.length} sorumlu'),
            Text('Süre eksikse 30 dk, kapasite eksikse günlük 120 dk varsayılır.'),
          ]))),
          const Text('Kapasite senaryoları', style: TextStyle(fontWeight: FontWeight.bold)),
          ...capacityCases.map((r) => ListTile(leading: const Icon(Icons.tune, color: _purple), title: Text('Temel kapasiteye +${r['extra']} dk'), subtitle: Text('${r['over']} dk aşım • ${r['risk']} riskli sorumlu-gün'), trailing: Text('−${totalOver - r['over']!} dk'))),
          const Divider(),
          const Text('Sorumlu bazında performans', style: TextStyle(fontWeight: FontWeight.bold)),
          if (rankedOwners.isEmpty) const ListTile(title: Text('Seçilen dönemde açık ve tarihli görev yok.')),
          ...rankedOwners.map((e) => Card(child: ListTile(title: Text(e.key), subtitle: Text('${e.value['tasks']} görev • ${e.value['critical']} kritik/yüksek • ${e.value['load']} dk planlanan • ${e.value['over']} dk aşım'), trailing: Text('${e.value['riskDays']} riskli gün')))),
          const Divider(),
          const Text('Kural tabanlı iyileştirme önerileri', style: TextStyle(fontWeight: FontWeight.bold)),
          ...suggestions.map((s) => ListTile(leading: const Icon(Icons.lightbulb_outline, color: _purple), title: Text(s))),
          const Divider(),
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<String>(value: selected, items: ['Tümü', ...people].map((p) => DropdownMenuItem(value: p, child: Text(p))).toList(), onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
            DropdownButton<int>(value: sortMode, items: const [DropdownMenuItem(value: 0, child: Text('Tarihe göre')), DropdownMenuItem(value: 1, child: Text('Aşım miktarı')), DropdownMenuItem(value: 2, child: Text('Doluluk oranı')), DropdownMenuItem(value: 3, child: Text('Kritik görev sayısı'))], onChanged: (v) => update(() => sortMode = v ?? 0)),
            FilterChip(label: const Text('Yalnızca riskliler'), selected: riskOnly, onSelected: (v) => update(() => riskOnly = v)),
            FilterChip(label: const Text('Hafta sonlarını göster'), selected: includeWeekends, onSelected: (v) => update(() => includeWeekends = v)),
          ]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Görev, tarih veya sorumlu ara'), onChanged: (v) => update(() => search = v)),
          Text('${visible.length} sorumlu-gün görüntüleniyor', style: const TextStyle(fontWeight: FontWeight.bold)),
          if (visible.isEmpty) const ListTile(title: Text('Seçili filtrelerde kayıt bulunamadı.')),
          ...visible.take(80).map((r) => Card(child: ExpansionTile(
            leading: Icon((r['over'] as int) > 0 ? Icons.warning_amber_rounded : Icons.event_available_outlined, color: _purple),
            title: Text('${iso(r['date'] as DateTime)} • ${r['owner']}'),
            subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('${r['load']}/${r['capacity']} dk • %${(r['utilization'] as double).toStringAsFixed(0)} doluluk • ${r['over']} dk aşım'), LinearProgressIndicator(value: ((r['utilization'] as double) / 100).clamp(0.0, 1.0))]),
            children: (r['tasks'] as List<Map<String, dynamic>>).map((t) => ListTile(dense: true, title: Text('${t['title'] ?? 'Görev'}'), subtitle: Text('${t['priority'] ?? t['level'] ?? 'Normal'} • ${mins(t)} dk'))).toList(),
          ))),
          if (visible.length > 80) Text('${visible.length - 80} ek sorumlu-gün CSV raporunda.'),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${export.join('\r\n')}')); if (mounted) _notice('Kapasite performans raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Kapasite performans CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenCapacityScenarioDecision(); }, icon: const Icon(Icons.compare_arrows_outlined), label: const Text('Kapasite senaryoları karar merkezine geç')),
          const Text('Not: Bu ekran planlanan iş yükünü analiz eder; gerçek müsaitliği, tamamlanma süresini veya görev yetkinliğini doğrulamaz.'),
        ],
      ])));
    }));
  }

  void _showKitchenCapacityScenarioDecision() {
    const actionsKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    var started = false, loading = true, horizon = 14, margin = 0;
    var owner = 'Tümü', query = '', onlyChanges = false, allowWeekends = false;
    var maxMoves = 15, strategy = 0;
    DateTime anchor = DateTime.now();
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map<String, dynamic> t) { final v = '${t['owner'] ?? ''}'.trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    int mins(Map<String, dynamic> t) { final n = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool critical(Map<String, dynamic> t) => ['Kritik', 'Yüksek'].contains('${t['priority'] ?? t['level'] ?? ''}');
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, update) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(actionsKey) ?? '[]');
            if (raw is List) { tasks..clear()..addAll(raw.whereType<Map>().map((v) => Map<String, dynamic>.from(v))); }
            final saved = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (saved is Map) { for (final e in saved.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) capacities['${e.key}'] = n; } }
          } catch (_) { if (mounted) _notice('Görev veya kapasite kayıtları tam okunamadı.'); }
          if (ctx.mounted) update(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
      }
      final start = day(anchor), end = start.add(Duration(days: horizon));
      final people = {...tasks.map(who), ...capacities.keys}.toList()..sort();
      final selected = owner == 'Tümü' || people.contains(owner) ? owner : 'Tümü';
      final eligible = tasks.where((t) { final d = parse(t['targetDate'] ?? t['due']); return active(t) && d != null && !day(d).isBefore(start) && day(d).isBefore(end); }).toList();
      final base = <String, int>{};
      String key(String person, DateTime d) => '$person|${iso(day(d))}';
      for (final t in eligible) { final k = key(who(t), parse(t['targetDate'] ?? t['due'])!); base[k] = (base[k] ?? 0) + mins(t); }
      int cap(String person, int bonus) => ((capacities[person] ?? 120) + bonus).clamp(15, 1440).toInt();
      int overload(Map<String, int> load, int bonus) => load.entries.fold<int>(0, (v, e) { final parts = e.key.split('|'); return v + (e.value - cap(parts.first, bonus)).clamp(0, 100000).toInt(); });
      int riskDays(Map<String, int> load, int bonus) => load.entries.where((e) => e.value > cap(e.key.split('|').first, bonus)).length;
      final scenarioBonuses = <int>[0, 30, 60];
      final results = <Map<String, dynamic>>[];
      for (var mode = 0; mode < 3; mode++) {
        final bonus = scenarioBonuses[mode] + margin;
        final loads = Map<String, int>.from(base);
        final moves = <Map<String, dynamic>>[];
        final candidates = eligible.where((t) => !critical(t) && who(t) != 'Atanmamış').toList()
          ..sort((a, b) { final da = parse(a['targetDate'] ?? a['due'])!, db = parse(b['targetDate'] ?? b['due'])!; final order = da.compareTo(db); return order != 0 ? order : mins(b).compareTo(mins(a)); });
        for (final task in candidates) {
          if (moves.length >= maxMoves) break;
          final original = parse(task['targetDate'] ?? task['due'])!;
          final person = who(task), from = key(person, original), duration = mins(task);
          if ((loads[from] ?? 0) <= cap(person, bonus)) continue;
          String? destination; String? newPerson; DateTime? newDay;
          var bestPenalty = 1000000;
          final candidatesPeople = mode == 0 ? <String>[person] : (mode == 1 || mode == 2 ? people.where((p) => p != 'Atanmamış').toList() : <String>[person]);
          for (final p in candidatesPeople) {
            if (mode == 1 && p == person) continue;
            for (var offset = 0; offset < horizon; offset++) {
              final d = start.add(Duration(days: offset));
              if (d.isBefore(day(DateTime.now())) || (!allowWeekends && d.weekday >= 6)) continue;
              if (mode == 1 && iso(d) != iso(original)) continue;
              if (mode == 0 && p != person) continue;
              if (mode == 2 && d.isBefore(day(original))) continue;
              final target = key(p, d);
              if (target == from || (loads[target] ?? 0) + duration > cap(p, bonus)) continue;
              final delay = d.difference(day(original)).inDays.abs();
              final penalty = delay * 5 + (p == person ? 0 : 8) + ((loads[target] ?? 0) * 10 ~/ cap(p, bonus));
              if (penalty < bestPenalty) { bestPenalty = penalty; destination = target; newPerson = p; newDay = d; }
            }
          }
          if (destination == null || newPerson == null || newDay == null) continue;
          loads[from] = (loads[from] ?? 0) - duration;
          loads[destination] = (loads[destination] ?? 0) + duration;
          moves.add({'title': '${task['title'] ?? 'Görev'}', 'from': from, 'to': destination, 'minutes': duration, 'delay': day(newDay).difference(day(original)).inDays, 'reassigned': newPerson != person, 'priority': '${task['priority'] ?? task['level'] ?? 'Normal'}'});
        }
        final before = overload(base, bonus), after = overload(loads, bonus);
        final delay = moves.fold<int>(0, (v, m) => v + ((m['delay'] as int) > 0 ? m['delay'] as int : 0));
        final reassignments = moves.where((m) => m['reassigned'] == true).length;
        final score = (100 - after * 0.12 - delay * 1.8 - reassignments * 2.5).clamp(0.0, 100.0).toDouble();
        results.add({'mode': mode, 'bonus': bonus, 'before': before, 'after': after, 'beforeDays': riskDays(base, bonus), 'afterDays': riskDays(loads, bonus), 'moves': moves, 'delay': delay, 'reassignments': reassignments, 'score': score});
      }
      final chosen = results[strategy];
      final allMoves = chosen['moves'] as List<Map<String, dynamic>>;
      final visible = allMoves.where((m) => (!onlyChanges || m['from'] != m['to']) && (selected == 'Tümü' || (m['from'] as String).startsWith('$selected|') || (m['to'] as String).startsWith('$selected|')) && (query.trim().isEmpty || '${m['title']} ${m['from']} ${m['to']}'.toLowerCase().contains(query.toLowerCase().trim()))).toList();
      final export = <String>['Senaryo,Görev,Önceki plan,Önerilen plan,Dakika,Erteleme günü,Sorumlu değişimi'];
      for (final m in visible) { export.add([strategy + 1, m['title'], m['from'], m['to'], m['minutes'], m['delay'], m['reassigned']].map(csv).join(',')); }
      return SafeArea(child: Padding(padding: const EdgeInsets.all(16), child: ListView(children: [
        Row(children: [const Expanded(child: Text('Kapasite senaryoları / karar merkezi', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (loading) const LinearProgressIndicator() else ...[
          const Text('Üç senaryo: mevcut kapasite, günlük +30 dk ve günlük +60 dk. Ek kapasite yalnızca simülasyon içindir; kaydedilmez.'),
          Wrap(spacing: 10, runSpacing: 6, children: [
            DropdownButton<int>(value: horizon, items: [7, 14, 21, 28].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(), onChanged: (n) => update(() => horizon = n ?? 14)),
            DropdownButton<int>(value: margin, items: [0, 15, 30, 45].map((n) => DropdownMenuItem(value: n, child: Text('Ek hedef +$n dk'))).toList(), onChanged: (n) => update(() => margin = n ?? 0)),
            DropdownButton<int>(value: maxMoves, items: [5, 10, 15, 25, 40].map((n) => DropdownMenuItem(value: n, child: Text('En çok $n taşıma'))).toList(), onChanged: (n) => update(() => maxMoves = n ?? 15)),
            FilterChip(label: const Text('Hafta sonuna öner'), selected: allowWeekends, onSelected: (v) => update(() => allowWeekends = v)),
          ]),
          Row(children: [IconButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: horizon))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: horizon))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
          Text('${eligible.length} açık ve tarihli görev • ${people.length} sorumlu • Mevcut plan aşımı: ${overload(base, 0)} dk', style: const TextStyle(fontWeight: FontWeight.bold)),
          ...results.map((r) { final n = r['mode'] as int; return Card(color: n == strategy ? _pink : null, child: ListTile(
            leading: Icon(n == strategy ? Icons.radio_button_checked : Icons.radio_button_unchecked, color: _purple),
            title: Text('Senaryo ${n + 1} • Günlük kapasite +${r['bonus']} dk'),
            subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Aşım: ${r['before']} → ${r['after']} dk • Riskli gün: ${r['beforeDays']} → ${r['afterDays']}'), Text('${(r['moves'] as List).length} taşıma • ${r['delay']} erteleme günü • ${r['reassignments']} sorumlu değişimi'), LinearProgressIndicator(value: (r['score'] as double) / 100)]),
            trailing: Text('${(r['score'] as double).toStringAsFixed(0)}/100'), onTap: () => update(() => strategy = n))); }),
          const SizedBox(height: 8),
          const Text('Puanlar kural tabanlıdır; farklı kapasite varsayımları içeren senaryolar doğrudan eşdeğer değildir. Gerçek müsaitlik ve yetkinlik doğrulanmaz.'),
          const Divider(),
          Wrap(spacing: 8, children: [DropdownButton<String>(value: selected, items: ['Tümü', ...people].map((p) => DropdownMenuItem(value: p, child: Text(p))).toList(), onChanged: (v) => update(() => owner = v ?? 'Tümü')), FilterChip(label: const Text('Yalnızca değişenler'), selected: onlyChanges, onSelected: (v) => update(() => onlyChanges = v))]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Görev veya sorumlu ara'), onChanged: (v) => update(() => query = v)),
          Text('Seçili senaryo: ${visible.length} görünür öneri', style: const TextStyle(fontWeight: FontWeight.bold)),
          if (visible.isEmpty) const ListTile(title: Text('Bu filtrelerde öneri bulunamadı.')),
          ...visible.take(60).map((m) => Card(child: ListTile(leading: const Icon(Icons.swap_horiz, color: _purple), title: Text('${m['title']}'), subtitle: Text('${m['from']} → ${m['to']}\n${m['minutes']} dk • ${m['delay']} gün kayma • Sorumlu değişimi: ${m['reassigned'] == true ? 'Evet' : 'Hayır'}')))),
          if (visible.length > 60) Text('${visible.length - 60} ek öneri CSV raporunda.'),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${export.join('\r\n')}')); if (mounted) _notice('Senaryo raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Senaryo CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenPreventiveDecisionCenter(); }, icon: const Icon(Icons.verified_outlined), label: const Text('Onaylı plan uygulama ekranına geç')),
          const Text('Bu karar merkezi yalnızca simülasyon üretir. Görev veya kapasite kayıtlarını değiştirmez.'),
        ],
      ])));
    }));
  }




  void _showKitchenForwardCapacityRiskCenter() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    var started = false, busy = true, weeks = 4, offset = 0;
    var threshold = 85, extra = 0, weekend = true, onlyRisk = false;
    var onlyUnassigned = false, includeUndated = false, sort = 'Risk';
    var ownerFilter = 'Tümü', query = '';
    String str(Object? v) => '${v ?? ''}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime date(DateTime v) => DateTime(v.year, v.month, v.day);
    DateTime monday(DateTime v) => date(v).subtract(Duration(days: v.weekday - 1));
    String key(DateTime v) => '${v.year}-${v.month.toString().padLeft(2, '0')}-${v.day.toString().padLeft(2, '0')}';
    String label(DateTime v) => '${v.day.toString().padLeft(2, '0')}.${v.month.toString().padLeft(2, '0')}.${v.year}';
    String who(Map<String, dynamic> t) => str(t['owner']).trim().isEmpty ? 'Atanmamış' : str(t['owner']).trim();
    int minutes(Map<String, dynamic> t) { final v = int.tryParse(str(t['estimatedMinutes'])); return v != null && v >= 5 && v <= 1440 ? v : 30; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(str(t['status']));
    bool urgent(Map<String, dynamic> t) { final p = str(t['priority'] ?? t['level']).toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high'); }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    Map<String, int> decodeIntMap(Object? raw) { final result = <String, int>{}; if (raw is Map) for (final e in raw.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 0 && n <= 1440) result[str(e.key)] = n; } return result; }
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final decoded = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (decoded is List) tasks.addAll(decoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            capacities.addAll(decodeIntMap(jsonDecode(prefs.getString(capacityKey) ?? '{}')));
            goals.addAll(decodeIntMap(jsonDecode(prefs.getString(goalKey) ?? '{}')));
          } catch (_) { if (ctx.mounted) _notice('Kapasite verilerinin bir bölümü okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final start = monday(DateTime.now()).add(Duration(days: offset * 7));
      final end = start.add(Duration(days: weeks * 7));
      final owners = <String>{'Tümü'};
      for (final t in tasks.where(active)) { owners.add(who(t)); }
      owners.addAll(capacities.keys);
      final ownerNames = owners.toList()..sort();
      if (!owners.contains(ownerFilter)) ownerFilter = 'Tümü';
      final grouped = <String, List<Map<String, dynamic>>>{};
      final unknown = <Map<String, dynamic>>[];
      var missingDuration = 0, missingOwner = 0, stale = 0, urgentCount = 0;
      for (final t in tasks.where(active)) {
        final d = parse(t['targetDate'] ?? t['due']);
        if (int.tryParse(str(t['estimatedMinutes'])) == null) missingDuration++;
        if (who(t) == 'Atanmamış') missingOwner++;
        if (urgent(t)) urgentCount++;
        if (d == null) { unknown.add(t); continue; }
        if (date(d).isBefore(date(DateTime.now()))) stale++;
        if (date(d).isBefore(start) || !date(d).isBefore(end)) continue;
        if (!weekend && d.weekday >= 6) continue;
        final k = '${who(t)}|${key(d)}';
        grouped.putIfAbsent(k, () => <Map<String, dynamic>>[]).add(t);
      }
      final rows = <Map<String, dynamic>>[];
      for (final e in grouped.entries) {
        final parts = e.key.split('|'), owner = parts.first, d = parse(parts.last)!;
        final mins = e.value.fold<int>(0, (sum, t) => sum + minutes(t));
        final cap = (capacities[owner] ?? 120) + extra;
        final overflow = (mins - cap).clamp(0, 1000000).toInt();
        final goal = goals[owner] ?? 0;
        final gap = (overflow - goal).clamp(0, 1000000).toInt();
        final percent = cap > 0 ? mins * 100 / cap : 0.0;
        final critical = e.value.where(urgent).length;
        final score = (percent >= threshold ? 2 : 0) + (overflow > 0 ? 2 : 0) + (gap > 0 ? 2 : 0) + (critical > 0 ? 1 : 0);
        rows.add({'owner':owner, 'date':d, 'tasks':e.value, 'minutes':mins, 'capacity':cap, 'overflow':overflow, 'gap':gap, 'percent':percent, 'critical':critical, 'score':score});
      }
      final visible = rows.where((r) {
        if (ownerFilter != 'Tümü' && r['owner'] != ownerFilter) return false;
        if (onlyRisk && (r['score'] as int) < 2) return false;
        if (onlyUnassigned && r['owner'] != 'Atanmamış') return false;
        if (query.trim().isEmpty) return true;
        final q = query.toLowerCase().trim();
        return str(r['owner']).toLowerCase().contains(q) || label(r['date'] as DateTime).contains(q) || (r['tasks'] as List).any((t) => str(t['title']).toLowerCase().contains(q));
      }).toList();
      visible.sort((a, b) {
        if (sort == 'Tarih') return (a['date'] as DateTime).compareTo(b['date'] as DateTime);
        if (sort == 'Sorumlu') return str(a['owner']).compareTo(str(b['owner']));
        if (sort == 'Aşım') return (b['overflow'] as int).compareTo(a['overflow'] as int);
        if (sort == 'Kritik') return (b['critical'] as int).compareTo(a['critical'] as int);
        return (b['score'] as int).compareTo(a['score'] as int);
      });
      final risk = visible.where((r) => (r['score'] as int) >= 2).length;
      final overflowTotal = visible.fold<int>(0, (sum, r) => sum + (r['overflow'] as int));
      final deviationTotal = visible.fold<int>(0, (sum, r) => sum + (r['gap'] as int));
      final ownerStats = <String, Map<String, int>>{};
      for (final r in visible) {
        final name = str(r['owner']);
        final stat = ownerStats.putIfAbsent(name, () => {'minutes':0,'over':0,'risk':0,'gap':0,'days':0});
        stat['minutes'] = stat['minutes']! + (r['minutes'] as int);
        stat['over'] = stat['over']! + (r['overflow'] as int);
        stat['gap'] = stat['gap']! + (r['gap'] as int);
        stat['risk'] = stat['risk']! + ((r['score'] as int) >= 2 ? 1 : 0);
        stat['days'] = stat['days']! + 1;
      }
      final rankings = ownerStats.entries.toList()..sort((a,b) => b.value['gap']!.compareTo(a.value['gap']!));
      final byWeek = <String, Map<String, int>>{};
      for (final r in visible) {
        final wk = key(monday(r['date'] as DateTime));
        final s = byWeek.putIfAbsent(wk, () => {'minutes':0,'over':0,'gap':0,'risk':0});
        s['minutes'] = s['minutes']! + (r['minutes'] as int);
        s['over'] = s['over']! + (r['overflow'] as int);
        s['gap'] = s['gap']! + (r['gap'] as int);
        s['risk'] = s['risk']! + ((r['score'] as int) >= 2 ? 1 : 0);
      }
      final weekly = byWeek.entries.toList()..sort((a,b) => a.key.compareTo(b.key));
      final lines = <String>['Sorumlu,Tarih,Görev,Dakika,Kapasite,Doluluk %,Aşım,Hedef sapması,Kritik görev,Risk puanı'];
      for (final r in visible) { lines.add([r['owner'],label(r['date'] as DateTime),(r['tasks'] as List).length,r['minutes'],r['capacity'],(r['percent'] as double).toStringAsFixed(1),r['overflow'],r['gap'],r['critical'],r['score']].map(csv).join(',')); }
      Widget metric(String name, String value) => Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(children: [Text(value, style: const TextStyle(fontSize: 18,fontWeight: FontWeight.bold,color: _purple)), Text(name, textAlign: TextAlign.center, style: const TextStyle(fontSize: 11))])));
      return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Padding(padding: const EdgeInsets.all(14), child: Column(children: [
        Row(children: [const Expanded(child: Text('Gelecek haftalar / önleyici kapasite risk merkezi', style: TextStyle(fontSize: 17,fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (busy) const LinearProgressIndicator(),
        Expanded(child: ListView(children: [
          const Text('Gelecek dönem görevleri, kayıtlı günlük kapasite ve hedefler üzerinden incelenir. Tahmin, kayıtlı planın risk projeksiyonudur; otomatik görev değişikliği yapılmaz.', style: TextStyle(fontSize: 12)),
          const SizedBox(height: 8),
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<int>(value: weeks, items: [1,2,4,6,8,12].map((v) => DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(), onChanged: (v) { if(v!=null) refresh(() => weeks=v); }),
            DropdownButton<int>(value: threshold, items: [70,80,85,90,100].map((v) => DropdownMenuItem(value:v,child:Text('Risk ≥ %$v'))).toList(), onChanged: (v) { if(v!=null) refresh(() => threshold=v); }),
            DropdownButton<int>(value: extra, items: [0,15,30,45,60].map((v) => DropdownMenuItem(value:v,child:Text('Ek kapasite +$v dk'))).toList(), onChanged: (v) { if(v!=null) refresh(() => extra=v); }),
            DropdownButton<String>(value: sort, items: ['Risk','Tarih','Sorumlu','Aşım','Kritik'].map((v) => DropdownMenuItem(value:v,child:Text(v))).toList(), onChanged: (v) { if(v!=null) refresh(() => sort=v); }),
            DropdownButton<String>(value: ownerFilter, items: ownerNames.map((v) => DropdownMenuItem(value:v,child:Text(v))).toList(), onChanged: (v) { if(v!=null) refresh(() => ownerFilter=v); }),
          ]),
          Row(children: [IconButton(onPressed: () => refresh(() => offset -= weeks), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${label(start)} – ${label(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() => offset += weeks), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() => offset=0), child: const Text('Bugün'))]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),hintText: 'Görev, tarih veya sorumlu ara'), onChanged: (v) => refresh(() => query=v)),
          Wrap(spacing: 6, children: [FilterChip(label: const Text('Hafta sonu'), selected: weekend, onSelected: (v) => refresh(() => weekend=v)),FilterChip(label: const Text('Yalnız riskli'), selected: onlyRisk, onSelected: (v) => refresh(() => onlyRisk=v)),FilterChip(label: const Text('Atanmamış'), selected: onlyUnassigned, onSelected: (v) => refresh(() => onlyUnassigned=v)),FilterChip(label: const Text('Tarihsiz görevler'), selected: includeUndated, onSelected: (v) => refresh(() => includeUndated=v))]),
          Wrap(spacing: 5, children: [metric('Sorumlu-gün', '${visible.length}'),metric('Riskli gün', '$risk'),metric('Aşım', '$overflowTotal dk'),metric('Hedef sapması', '$deviationTotal dk')]),
          Card(color: const Color(0xFFFFF1F7),child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Veri kalitesi / önleyici kontrol', style: TextStyle(fontWeight: FontWeight.bold)),Text('Sorumlusuz: $missingOwner • Süresi eksik: $missingDuration • Tarihi geçmiş: $stale • Öncelikli: $urgentCount • Tarihsiz: ${unknown.length}'),if (includeUndated) ...unknown.take(20).map((t) => Text('• ${str(t['title']).isEmpty ? 'Adsız görev' : str(t['title'])} (${who(t)})',style: const TextStyle(fontSize: 12)))]))),
          const SizedBox(height: 8),
          const Text('Haftalık risk görünümü',style: TextStyle(fontWeight: FontWeight.bold)),
          ...weekly.map((e) => ListTile(dense:true,title: Text('Hafta: ${e.key}'),subtitle: Text('Yük ${e.value['minutes']} dk • Aşım ${e.value['over']} dk • Sapma ${e.value['gap']} dk • Risk ${e.value['risk']} gün'))),
          const Divider(),
          const Text('Sorumlu bazında öncelikler',style: TextStyle(fontWeight: FontWeight.bold)),
          ...rankings.map((e) => Card(child: ListTile(title: Text(e.key),subtitle: Text('Toplam ${e.value['minutes']} dk • Aşım ${e.value['over']} dk • Sapma ${e.value['gap']} dk • Riskli ${e.value['risk']} gün'),trailing: (e.value['gap'] ?? 0) > 0 ? const Icon(Icons.warning_amber_rounded,color:Colors.deepOrange) : const Icon(Icons.check_circle_outline,color:Colors.green)))),
          const Divider(),
          const Text('Günlük kapasite ve görev detayları',style: TextStyle(fontWeight: FontWeight.bold)),
          if (visible.isEmpty) const Padding(padding: EdgeInsets.all(14),child:Text('Bu filtrelerde planlı görev bulunamadı.')),
          ...visible.take(150).map((r) => Card(child: ExpansionTile(title: Text('${r['owner']} • ${label(r['date'] as DateTime)}'),subtitle: Text('${r['minutes']}/${r['capacity']} dk • %${(r['percent'] as double).toStringAsFixed(0)} • Aşım ${r['overflow']} dk • Sapma ${r['gap']} dk'),leading: Icon((r['score'] as int)>=2 ? Icons.warning_amber_rounded : Icons.check_circle_outline,color:(r['score'] as int)>=2 ? Colors.deepOrange : Colors.green),children: [(r['tasks'] as List<Map<String,dynamic>>).isEmpty ? const SizedBox.shrink() : Column(children:(r['tasks'] as List<Map<String,dynamic>>).map((t) => ListTile(dense:true,title:Text(str(t['title']).isEmpty?'Adsız görev':str(t['title'])),subtitle:Text('${minutes(t)} dk • ${str(t['priority'] ?? t['level'])} • ${str(t['status'])}'))).toList()),if ((r['gap'] as int)>0) const Padding(padding:EdgeInsets.all(8),child:Text('Öneri: Kritik olmayan görevleri alternatif gün/sorumlu için seçimli optimizasyon ekranında değerlendirin.',style:TextStyle(fontSize:12)))]))),
          if (visible.length > 150) Text('${visible.length-150} satır performans için gizlendi; CSV raporunda tamamı yer alır.'),
          const SizedBox(height: 12),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}')); if(mounted) _notice('Kapasite risk raporu CSV olarak kopyalandı.'); },icon: const Icon(Icons.copy),label: const Text('Risk raporunu CSV kopyala')),
          FilledButton.tonalIcon(onPressed: () { Navigator.pop(ctx); _showKitchenGoalDeviationRedistribution(); },icon: const Icon(Icons.swap_horiz),label: const Text('Hedef sapması / seçimli yeniden dağıtım')),
          const SizedBox(height: 20),
        ]))
      ]))));
    }));
  }

  void _showKitchenFullPlanWeeklyScorecard() {
    const historyKey = 'paket40_optimization_plan_versions_v1';
    final history = <Map<String, dynamic>>[];
    var loaded = false, busy = true, weeks = 12, onlyRisk = false, onlyImproved = false;
    var query = '', selectedOwner = 'Tümü';
    DateTime anchor = DateTime.now();
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String dayLabel(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    String dayKey(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String person(Map<String, dynamic> t) => str(t['owner']).trim().isEmpty ? 'Atanmamış' : str(t['owner']).trim();
    List<Map<String, dynamic>> rows(Object? x) => x is List ? x.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> intMap(Object? x) {
      final out = <String, int>{};
      if (x is Map) { for (final e in x.entries) {
        final n = int.tryParse(str(e.value));
        if (n != null && n >= 0 && n <= 1440) out[str(e.key)] = n;
      } }
      return out;
    }
    int duration(Map<String, dynamic> t) {
      final n = int.tryParse(str(t['estimatedMinutes']));
      return n != null && n >= 5 && n <= 1440 ? n : 30;
    }
    Map<String, dynamic> metrics(List<Map<String, dynamic>> plan, Map<String, int> capacity, Map<String, int> goals) {
      final load = <String, int>{};
      final ownerMinutes = <String, int>{};
      for (final task in plan) {
        if (['Tamamlandı', 'İptal'].contains(str(task['status']))) continue;
        final date = parse(task['targetDate'] ?? task['due']);
        if (date == null) continue;
        final who = person(task), mins = duration(task);
        final key = '$who|${dayKey(date)}';
        load[key] = (load[key] ?? 0) + mins;
        ownerMinutes[who] = (ownerMinutes[who] ?? 0) + mins;
      }
      var over = 0, deviation = 0, riskDays = 0;
      final ownerDeviation = <String, int>{}, ownerRisk = <String, int>{};
      for (final entry in load.entries) {
        final who = entry.key.split('|').first;
        final overflow = entry.value - (capacity[who] ?? 120);
        if (overflow > 0) { over += overflow; riskDays++; ownerRisk[who] = (ownerRisk[who] ?? 0) + 1; }
        final gap = overflow - (goals[who] ?? 0);
        if (gap > 0) { deviation += gap; ownerDeviation[who] = (ownerDeviation[who] ?? 0) + gap; }
      }
      return {'over': over, 'deviation': deviation, 'risk': riskDays,
        'ownerMinutes': ownerMinutes, 'ownerDeviation': ownerDeviation, 'ownerRisk': ownerRisk};
    }
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!loaded) {
        loaded = true;
        SharedPreferences.getInstance().then((prefs) {
          try { history.addAll(rows(jsonDecode(prefs.getString(historyKey) ?? '[]'))); }
          catch (_) { if (ctx.mounted) _notice('Optimizasyon geçmişi okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final snapshots = <Map<String, dynamic>>[];
      final owners = <String>{'Tümü'};
      var legacy = 0, invalid = 0;
      for (final v in history) {
        if (str(v['type']) != 'goal_deviation_distribution') continue;
        final at = parse(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        if (v['snapshotVersion'] != 1 || v['fullPlanBefore'] is! List || v['fullPlanAfter'] is! List || v['capacitySnapshot'] is! Map || v['goalSnapshot'] is! Map) { legacy++; continue; }
        final before = rows(v['fullPlanBefore']), after = rows(v['fullPlanAfter']);
        if (before.isEmpty || after.isEmpty) { invalid++; continue; }
        final cap = intMap(v['capacitySnapshot']), goals = intMap(v['goalSnapshot']);
        final b = metrics(before, cap, goals), a = metrics(after, cap, goals);
        owners.addAll((b['ownerMinutes'] as Map<String, int>).keys);
        owners.addAll((a['ownerMinutes'] as Map<String, int>).keys);
        snapshots.add({'at': at, 'name': str(v['name']), 'before': b, 'after': a, 'moves': rows(v['after']).length});
      }
      final ownerNames = owners.toList()..sort();
      final selected = snapshots.where((r) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        final gain = (b['deviation'] as int) - (a['deviation'] as int);
        if (onlyImproved && gain <= 0) return false;
        if (onlyRisk && (a['risk'] as int) == 0) return false;
        if (selectedOwner != 'Tümü' && !(b['ownerMinutes'] as Map).containsKey(selectedOwner) && !(a['ownerMinutes'] as Map).containsKey(selectedOwner)) return false;
        return query.isEmpty || str(r['name']).toLowerCase().contains(query.toLowerCase()) || dayLabel(r['at'] as DateTime).contains(query);
      }).toList();
      final buckets = <DateTime, List<Map<String, dynamic>>>{};
      for (final r in selected) {
        final week = monday(r['at'] as DateTime);
        buckets.putIfAbsent(week, () => <Map<String, dynamic>>[]).add(r);
      }
      final weeksSorted = buckets.keys.toList()..sort((a, b) => b.compareTo(a));
      var gains = 0, positive = 0, negative = 0, neutral = 0, moved = 0;
      final ownerGains = <String, int>{}, ownerRiskCount = <String, int>{};
      for (final r in selected) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        final gain = (b['deviation'] as int) - (a['deviation'] as int);
        gains += gain; moved += r['moves'] as int;
        if (gain > 0) { positive++; } else if (gain < 0) { negative++; } else { neutral++; }
        final bd = b['ownerDeviation'] as Map<String, int>, ad = a['ownerDeviation'] as Map<String, int>;
        for (final who in <String>{...bd.keys, ...ad.keys}) { ownerGains[who] = (ownerGains[who] ?? 0) + (bd[who] ?? 0) - (ad[who] ?? 0); }
        final ar = a['ownerRisk'] as Map<String, int>;
        for (final e in ar.entries) { ownerRiskCount[e.key] = (ownerRiskCount[e.key] ?? 0) + e.value; }
      }
      final ranked = ownerGains.keys.toList()..sort((a, b) => (ownerRiskCount[b] ?? 0).compareTo(ownerRiskCount[a] ?? 0));
      final csvLines = <String>['Hafta;Tarih;Sürüm;Önce Hedef Sapması;Sonra Hedef Sapması;Net İyileşme;Önce Kapasite Aşımı;Sonra Kapasite Aşımı;Önce Riskli Gün;Sonra Riskli Gün;Görev Hareketi'];
      for (final r in selected) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        csvLines.add([dayLabel(monday(r['at'] as DateTime)), dayLabel(r['at'] as DateTime), r['name'], b['deviation'], a['deviation'], (b['deviation'] as int) - (a['deviation'] as int), b['over'], a['over'], b['risk'], a['risk'], r['moves']].map(csv).join(';'));
      }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Tam plan haftalık kapasite başarı karnesi', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (busy) const LinearProgressIndicator() else ...[
          const Card(color: _pink, child: Padding(padding: EdgeInsets.all(12), child: Text('Yalnızca işlem anında tam plan, kapasite ve hedef anlık görüntüsü saklanmış optimizasyonlar değerlendirilir. Haftalık toplamlar işlem bazlıdır: aynı görev farklı sürümlerde tekrar sayılabilir. Bunlar gerçekleşen süre veya bağımsız zaman tasarrufu değildir.'))),
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<int>(value: weeks, items: [4,8,12,26,52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (v) => refresh(() => weeks = v ?? 12)),
            DropdownButton<String>(value: ownerNames.contains(selectedOwner) ? selectedOwner : 'Tümü', items: ownerNames.map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(), onChanged: (v) => refresh(() => selectedOwner = v ?? 'Tümü')),
            FilterChip(label: const Text('Yalnızca iyileşen'), selected: onlyImproved, onSelected: (v) => refresh(() => onlyImproved = v)),
            FilterChip(label: const Text('Sonrasında risk kalan'), selected: onlyRisk, onSelected: (v) => refresh(() => onlyRisk = v)),
          ]),
          Row(children: [IconButton(onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${dayLabel(start)} – ${dayLabel(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
          TextField(decoration: const InputDecoration(labelText: 'Sürüm adı veya tarihte ara', prefixIcon: Icon(Icons.search)), onChanged: (v) => refresh(() => query = v.trim())),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('${selected.length} işlem • $positive iyileşen • $negative kötüleşen • $neutral değişmeyen', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('İşlem bazlı net hedef sapması farkı: $gains dk • Görev hareketi: $moved'),
            Text('Eski/kısmi kayıt: $legacy • Geçersiz tam plan: $invalid'),
            if (selected.isNotEmpty) Text('İyileşme gösteren işlem oranı: %${(positive * 100 / selected.length).toStringAsFixed(1)}'),
          ]))),
          const Padding(padding: EdgeInsets.symmetric(vertical: 8), child: Text('Haftalık performans', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16))),
          if (weeksSorted.isEmpty) const ListTile(title: Text('Seçilen dönemde uygun tam plan optimizasyonu bulunamadı.')),
          ...weeksSorted.map((w) {
            final group = buckets[w]!;
            final weekGain = group.fold<int>(0, (sum, r) => sum + ((r['before'] as Map)['deviation'] as int) - ((r['after'] as Map)['deviation'] as int));
            final weekRisk = group.fold<int>(0, (sum, r) => sum + ((r['after'] as Map)['risk'] as int));
            return Card(child: ExpansionTile(title: Text('${dayLabel(w)} haftası • ${group.length} işlem'), subtitle: Text('Net sapma farkı: $weekGain dk • İşlem sonrası riskli sorumlu-gün toplamı: $weekRisk'), children: [
              for (final r in group) ListTile(dense: true, title: Text(str(r['name'])), subtitle: Text('${dayLabel(r['at'] as DateTime)} • Sapma ${(r['before'] as Map)['deviation']} → ${(r['after'] as Map)['deviation']} dk • Risk ${(r['before'] as Map)['risk']} → ${(r['after'] as Map)['risk']}')),
            ]));
          }),
          const Padding(padding: EdgeInsets.symmetric(vertical: 8), child: Text('Sorumlu bazında tekrarlayan riskler', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16))),
          if (ranked.isEmpty) const ListTile(title: Text('Sorumlu analizi için kayıt bulunamadı.')),
          ...ranked.take(25).map((who) => Card(child: ListTile(title: Text(who), subtitle: Text('İşlem sonrası riskli gün toplamı: ${ownerRiskCount[who] ?? 0} • İşlem bazlı sapma farkı: ${ownerGains[who] ?? 0} dk'), trailing: Icon((ownerRiskCount[who] ?? 0) > 0 ? Icons.warning_amber_outlined : Icons.check_circle_outline)))),
          if (ranked.any((who) => (ownerRiskCount[who] ?? 0) >= 3)) const Card(color: _pink, child: Padding(padding: EdgeInsets.all(12), child: Text('Öneri: Birden fazla optimizasyonda riskli kalan sorumluların günlük kapasite hedeflerini ve görev süre tahminlerini gözden geçirin. Risk sayısı aynı günün farklı sürümlerde tekrar sayılmasını içerebilir.'))),
          if (negative > positive) const Card(color: _pink, child: Padding(padding: EdgeInsets.all(12), child: Text('Öneri: Seçilen dönemde kötüleşen işlem sayısı daha yüksek. Yeni görev değişikliklerinden önce seçimli optimizasyon önizlemesini kontrol edin.'))),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${csvLines.join('\r\n')}')); if (mounted) _notice('Haftalık kapasite başarı raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Haftalık performans CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenFullPlanOptimizationAudit(); }, icon: const Icon(Icons.fact_check_outlined), label: const Text('Tam plan optimizasyon geçmişine geç')),
          const Text('Bu ekran salt okunurdur. Eksik geçmiş kayıtları için varsayımsal değer oluşturulmaz.'),
        ],
      ])));
    }));
  }

  void _showKitchenFullPlanOptimizationAudit() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    final versions = <Map<String, dynamic>>[];
    var loaded = false, busy = true, weeks = 12, onlyImproved = false;
    var search = '', selectedOwner = 'Tümü';
    DateTime anchor = DateTime.now();
    String val(Object? x) => '${x ?? ''}';
    DateTime? date(Object? x) => DateTime.tryParse(val(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    String owner(Map<String, dynamic> t) => val(t['owner']).trim().isEmpty ? 'Atanmamış' : val(t['owner']).trim();
    int minutes(Map<String, dynamic> t) { final n = int.tryParse(val(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(val(t['status']));
    List<Map<String, dynamic>> tasks(Object? x) => x is List ? x.whereType<Map>().map((t) => Map<String, dynamic>.from(t)).toList() : <Map<String, dynamic>>[];
    Map<String, int> numbers(Object? x) { final out = <String, int>{}; if (x is Map) for (final e in x.entries) { final n = int.tryParse(val(e.value)); if (n != null && n >= 0 && n <= 1440) out[val(e.key)] = n; } return out; }
    String csv(Object? x) => '"${val(x).replaceAll('"', '""')}"';
    Map<String, dynamic> evaluate(List<Map<String, dynamic>> plan, Map<String, int> capacity, Map<String, int> goals) {
      final loads = <String, int>{}, owners = <String, int>{};
      for (final t in plan) {
        if (!active(t)) continue;
        final d = date(t['targetDate'] ?? t['due']);
        if (d == null) continue;
        final who = owner(t), key = '$who|${d.year}-${d.month}-${d.day}';
        loads[key] = (loads[key] ?? 0) + minutes(t);
        owners[who] = (owners[who] ?? 0) + minutes(t);
      }
      var excess = 0, deviation = 0, risk = 0;
      final ownerDeviation = <String, int>{};
      for (final e in loads.entries) {
        final who = e.key.split('|').first;
        final over = e.value - (capacity[who] ?? 120);
        if (over > 0) { excess += over; risk++; }
        final targetOver = over - (goals[who] ?? 0);
        if (targetOver > 0) { deviation += targetOver; ownerDeviation[who] = (ownerDeviation[who] ?? 0) + targetOver; }
      }
      return {'excess': excess, 'deviation': deviation, 'risk': risk, 'owners': owners, 'ownerDeviation': ownerDeviation};
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!loaded) {
        loaded = true;
        SharedPreferences.getInstance().then((prefs) {
          try { versions.addAll(tasks(jsonDecode(prefs.getString(versionsKey) ?? '[]'))); }
          catch (_) { if (ctx.mounted) _notice('Plan geçmişi okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final results = <Map<String, dynamic>>[];
      final owners = <String>{'Tümü'};
      var legacy = 0, invalid = 0;
      for (final v in versions) {
        if (val(v['type']) != 'goal_deviation_distribution') continue;
        final at = date(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        if (v['snapshotVersion'] != 1 || v['fullPlanBefore'] is! List || v['fullPlanAfter'] is! List || v['capacitySnapshot'] is! Map || v['goalSnapshot'] is! Map) { legacy++; continue; }
        final before = tasks(v['fullPlanBefore']), after = tasks(v['fullPlanAfter']);
        if (before.isEmpty || after.isEmpty) { invalid++; continue; }
        final capacity = numbers(v['capacitySnapshot']), goals = numbers(v['goalSnapshot']);
        final b = evaluate(before, capacity, goals), a = evaluate(after, capacity, goals);
        final bOwners = b['owners'] as Map<String, int>, aOwners = a['owners'] as Map<String, int>;
        owners.addAll(bOwners.keys); owners.addAll(aOwners.keys);
        results.add({'at': at, 'name': val(v['name']), 'before': b, 'after': a,
          'countBefore': before.length, 'countAfter': after.length, 'moves': tasks(v['after']).length,
          'capacity': capacity, 'goals': goals});
      }
      final names = owners.toList()..sort();
      final filtered = results.where((r) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        if (onlyImproved && (b['deviation'] as int) <= (a['deviation'] as int)) return false;
        if (selectedOwner != 'Tümü' && !(b['owners'] as Map).containsKey(selectedOwner) && !(a['owners'] as Map).containsKey(selectedOwner)) return false;
        return search.trim().isEmpty || val(r['name']).toLowerCase().contains(search.trim().toLowerCase());
      }).toList()..sort((a, b) => (b['at'] as DateTime).compareTo(a['at'] as DateTime));
      final gain = filtered.fold<int>(0, (sum, r) => sum + ((r['before'] as Map)['deviation'] as int) - ((r['after'] as Map)['deviation'] as int));
      final improved = filtered.where((r) => ((r['before'] as Map)['deviation'] as int) > ((r['after'] as Map)['deviation'] as int)).length;
      final lines = <String>['Tarih;Sürüm;Tam Plan Önce Görev;Tam Plan Sonra Görev;Önce Sapma dk;Sonra Sapma dk;Net İyileşme dk;Önce Aşım dk;Sonra Aşım dk;Önce Riskli Gün;Sonra Riskli Gün;Taşınan Görev'];
      for (final r in filtered) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        lines.add([fmt(r['at'] as DateTime),r['name'],r['countBefore'],r['countAfter'],b['deviation'],a['deviation'],(b['deviation'] as int)-(a['deviation'] as int),b['excess'],a['excess'],b['risk'],a['risk'],r['moves']].map(csv).join(';'));
      }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Tam plan optimizasyon geçmişi', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (busy) const LinearProgressIndicator() else ...[
          const Card(color: _pink, child: Padding(padding: EdgeInsets.all(12), child: Text('Bu panel yalnızca yeni tam-plan anlık görüntüsü içeren optimizasyonları karşılaştırır. Geçmişte yalnızca değişen görevleri saklayan kayıtlar yeniden oluşturulamaz; ayrı sayılır. Kapasite ve hedef eşikleri işlem anında saklanan değerlerden okunur.'))),
          Wrap(spacing: 8, children: [
            DropdownButton<int>(value: weeks, items: [4,8,12,26,52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (v) => refresh(() => weeks = v ?? 12)),
            DropdownButton<String>(value: names.contains(selectedOwner) ? selectedOwner : 'Tümü', items: names.map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(), onChanged: (v) => refresh(() => selectedOwner = v ?? 'Tümü')),
            FilterChip(label: const Text('Yalnızca iyileşen'), selected: onlyImproved, onSelected: (v) => refresh(() => onlyImproved = v)),
          ]),
          Row(children: [IconButton(onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${fmt(start)} – ${fmt(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
          TextField(decoration: const InputDecoration(labelText: 'Plan sürümünde ara', prefixIcon: Icon(Icons.search)), onChanged: (v) => refresh(() => search = v)),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('${filtered.length} tam plan kaydı • $improved iyileşen • net $gain dk sapma azalması', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('Eski/kısmi geçmiş: $legacy • Geçersiz tam görüntü: $invalid'),
            const Text('Net toplam, birbirini izleyen plan sürümlerinin işlem bazlı kazanımlarının toplamıdır; bağımsız zaman tasarrufu değildir.'),
          ]))),
          if (filtered.isEmpty) const ListTile(title: Text('Bu dönemde tam plan görüntüsü içeren kayıt yok. Yeni optimizasyon uygulandığında kayıtlar burada görünür.')),
          ...filtered.take(60).map((r) {
            final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
            final people = <String>{...(b['owners'] as Map<String, int>).keys, ...(a['owners'] as Map<String, int>).keys}.toList()..sort();
            return Card(child: ExpansionTile(title: Text(val(r['name'])), subtitle: Text('${fmt(r['at'] as DateTime)} • Tam plan ${r['countBefore']} → ${r['countAfter']} görev • Hedef sapması ${b['deviation']} → ${a['deviation']} dk'), children: [
              ListTile(title: Text('Kapasite aşımı: ${b['excess']} → ${a['excess']} dk'), subtitle: Text('Riskli sorumlu-gün: ${b['risk']} → ${a['risk']} • Değişen görev: ${r['moves']}')),
              for (final p in people) ListTile(dense: true, title: Text(p), subtitle: Text('Planlanan süre: ${(b['owners'] as Map<String, int>)[p] ?? 0} → ${(a['owners'] as Map<String, int>)[p] ?? 0} dk • Hedef sapması: ${(b['ownerDeviation'] as Map<String, int>)[p] ?? 0} → ${(a['ownerDeviation'] as Map<String, int>)[p] ?? 0} dk'), trailing: Text('Hedef ${(r['goals'] as Map<String, int>)[p] ?? 0} dk')),
            ]));
          }),
          if (filtered.length > 60) Text('${filtered.length - 60} ek kayıt CSV raporunda.'),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}')); if (mounted) _notice('Tam plan raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Tam plan CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenGoalDeviationRedistribution(); }, icon: const Icon(Icons.swap_calls_outlined), label: const Text('Hedef sapması optimizasyonuna geç')),
          const Text('Bu analiz kayıtları değiştirmez. Gerçekleşen süreler yerine görevlerin tahmini süreleri kullanılır.'),
        ],
      ])));
    }));
  }

  void _showKitchenGoalDeviationResults() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final versions = <Map<String, dynamic>>[];
    final goals = <String, int>{}, capacities = <String, int>{};
    var initialized = false, loading = true, weeks = 12, onlyImproved = false;
    var ownerFilter = 'Tümü', search = '';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    String who(Map<String, dynamic> t) { final x = str(t['owner']).trim(); return x.isEmpty ? 'Atanmamış' : x; }
    int duration(Map<String, dynamic> t) { final n = int.tryParse(str(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    List<Map<String, dynamic>> rows(Object? raw) => raw is List ? raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    Map<String, int> load(List<Map<String, dynamic>> tasks) {
      final result = <String, int>{};
      for (final t in tasks) {
        final d = parse(t['targetDate'] ?? t['due']);
        if (d == null) continue;
        final key = '${who(t)}|${d.year}-${d.month}-${d.day}';
        result[key] = (result[key] ?? 0) + duration(t);
      }
      return result;
    }
    int deviation(Map<String, int> values) {
      var total = 0;
      for (final e in values.entries) {
        final p = e.key.split('|').first;
        final excess = e.value - (capacities[p] ?? 120) - (goals[p] ?? 0);
        if (excess > 0) total += excess;
      }
      return total;
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!initialized) {
        initialized = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            versions.addAll(rows(jsonDecode(prefs.getString(versionsKey) ?? '[]')));
            final c = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (c is Map) for (final e in c.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 15 && n <= 1440) capacities[str(e.key)] = n; }
            final g = jsonDecode(prefs.getString(goalKey) ?? '{}');
            if (g is Map) for (final e in g.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 0 && n <= 1440) goals[str(e.key)] = n; }
          } catch (_) { if (ctx.mounted) _notice('Plan geçmişinin bir bölümü okunamadı.'); }
          if (ctx.mounted) refresh(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final all = <Map<String, dynamic>>[];
      final owners = <String>{'Tümü'};
      var incomplete = 0;
      for (final v in versions) {
        if (str(v['type']) != 'goal_deviation_distribution') continue;
        final at = parse(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        final before = rows(v['before']), after = rows(v['after']);
        if (before.isEmpty || after.isEmpty) { incomplete++; continue; }
        final b = load(before), a = load(after);
        final beforeOwners = <String, int>{}, afterOwners = <String, int>{};
        for (final t in before) { final p = who(t); beforeOwners[p] = (beforeOwners[p] ?? 0) + duration(t); owners.add(p); }
        for (final t in after) { final p = who(t); afterOwners[p] = (afterOwners[p] ?? 0) + duration(t); owners.add(p); }
        var moved = 0, reassigned = 0, postponed = 0;
        for (var i = 0; i < after.length && i < before.length; i++) {
          final old = before[i], now = after[i];
          final pChanged = who(old) != who(now);
          final d0 = parse(old['targetDate']), d1 = parse(now['targetDate']);
          final dChanged = str(old['targetDate']) != str(now['targetDate']);
          if (pChanged || dChanged) moved++;
          if (pChanged) reassigned++;
          if (d0 != null && d1 != null && d1.isAfter(d0)) postponed++;
        }
        all.add({'at': at, 'name': str(v['name']), 'before': deviation(b), 'after': deviation(a),
          'moved': moved, 'reassigned': reassigned, 'postponed': postponed,
          'beforeOwners': beforeOwners, 'afterOwners': afterOwners,
          'partial': true, 'count': before.length});
      }
      final names = owners.toList()..sort();
      final filtered = all.where((r) {
        if (onlyImproved && (r['before'] as int) <= (r['after'] as int)) return false;
        if (ownerFilter != 'Tümü' && !(r['beforeOwners'] as Map).containsKey(ownerFilter) && !(r['afterOwners'] as Map).containsKey(ownerFilter)) return false;
        return search.trim().isEmpty || str(r['name']).toLowerCase().contains(search.toLowerCase().trim());
      }).toList()..sort((a, b) => (b['at'] as DateTime).compareTo(a['at'] as DateTime));
      final improved = filtered.where((r) => (r['before'] as int) > (r['after'] as int)).length;
      final worsened = filtered.where((r) => (r['before'] as int) < (r['after'] as int)).length;
      final unchanged = filtered.length - improved - worsened;
      final movedTotal = filtered.fold<int>(0, (sum, r) => sum + (r['moved'] as int));
      final csvRows = <String>['Tarih;Sürüm;Önceki Kısmi Sapma;Sonraki Kısmi Sapma;Fark dk;Görev Hareketi;Sorumlu Değişimi;Erteleme;Kapsam'];
      for (final r in filtered) {
        csvRows.add([fmt(r['at'] as DateTime), r['name'], r['before'], r['after'], (r['before'] as int) - (r['after'] as int), r['moved'], r['reassigned'], r['postponed'], 'Yalnızca değişen görevler'].map(csv).join(';'));
      }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Hedef sapması optimizasyon sonuçları', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (loading) const LinearProgressIndicator() else ...[
          const Card(color: _pink, child: Padding(padding: EdgeInsets.all(12), child: Text('Önemli: Bu işlem geçmişinde yalnızca değiştirilen görevlerin önce/sonra görüntüsü saklanır. Bu nedenle sapma hesapları TAM planı temsil etmez; tüm günlerin gerçek iyileşmesi olarak yorumlanmamalıdır. Mevcut kapasite/hedef değerleri kullanılır, geçmiş değerler saklanmamıştır.'))),
          Wrap(spacing: 10, runSpacing: 5, children: [
            DropdownButton<int>(value: weeks, items: [4,8,12,26,52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (v) => refresh(() => weeks = v ?? 12)),
            DropdownButton<String>(value: names.contains(ownerFilter) ? ownerFilter : 'Tümü', items: names.map((n) => DropdownMenuItem(value: n, child: Text(n))).toList(), onChanged: (v) => refresh(() => ownerFilter = v ?? 'Tümü')),
            FilterChip(label: const Text('Yalnızca iyileşen kısmi kayıtlar'), selected: onlyImproved, onSelected: (v) => refresh(() => onlyImproved = v)),
          ]),
          Row(children: [IconButton(onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${fmt(start)} – ${fmt(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sürüm adına göre ara'), onChanged: (v) => refresh(() => search = v)),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('${filtered.length} kayıt • $movedTotal görev hareketi', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('Kısmi hesapta azalan: $improved • artan: $worsened • değişmeyen: $unchanged'),
            Text('Eksik önce/sonra kaydı: $incomplete'),
          ]))),
          if (filtered.isEmpty) const ListTile(title: Text('Seçilen dönemde uygun hedef sapması optimizasyon kaydı bulunamadı.')),
          ...filtered.take(60).map((r) {
            final delta = (r['before'] as int) - (r['after'] as int);
            final b = r['beforeOwners'] as Map<String, int>, a = r['afterOwners'] as Map<String, int>;
            final people = <String>{...b.keys, ...a.keys}.toList()..sort();
            return Card(child: ExpansionTile(
              leading: Icon(delta > 0 ? Icons.trending_down : delta < 0 ? Icons.trending_up : Icons.drag_handle, color: _purple),
              title: Text(str(r['name'])),
              subtitle: Text('${fmt(r['at'] as DateTime)} • ${r['moved']} hareket • Kısmi sapma ${r['before']} → ${r['after']} dk'),
              children: [
                ListTile(title: Text('Kısmi sapma farkı: $delta dk'), subtitle: Text('${r['reassigned']} sorumlu değişimi • ${r['postponed']} ileri tarih • ${r['count']} kayıtlı görev')),
                ...people.map((p) => ListTile(dense: true, title: Text(p), subtitle: Text('Kayıtlı görev dakikası: ${b[p] ?? 0} → ${a[p] ?? 0}'))),
              ],
            ));
          }),
          if (filtered.length > 60) Text('${filtered.length - 60} ek kayıt CSV raporunda.'),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '﻿${csvRows.join('\n')}')); if (mounted) _notice('Kısmi optimizasyon sonuçları CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Sonuç CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenGoalDeviationRedistribution(); }, icon: const Icon(Icons.swap_calls_outlined), label: const Text('Hedef sapması yeniden dağıtımına geç')),
          const Text('Bu ekran kayıtlı geçmişi okur; görevleri, hedefleri veya plan sürümlerini değiştirmez.'),
        ],
      ])));
    }));
  }

  void _showKitchenGoalDeviationRedistribution() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    var started = false, busy = true, saving = false, horizon = 14, maxMoves = 15;
    var strategy = 2, allowWeekends = true, anchor = DateTime.now(), search = '';
    final chosen = <int>{};
    DateTime date(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String owner(Map<String, dynamic> t) { final x = '${t['owner'] ?? ''}'.trim(); return x.isEmpty ? 'Atanmamış' : x; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    int duration(Map<String, dynamic> t) { final x = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return x != null && x >= 5 && x <= 1440 ? x : 30; }
    bool protected(Map<String, dynamic> t) { final p = '${t['priority'] ?? t['level'] ?? ''}'.toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('high') || p.contains('critical'); }
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final a = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (a is List) tasks.addAll(a.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            final c = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (c is Map) for (final e in c.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) capacities['${e.key}'] = n; }
            final g = jsonDecode(prefs.getString(goalKey) ?? '{}');
            if (g is Map) for (final e in g.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 0 && n <= 1440) goals['${e.key}'] = n; }
          } catch (_) { if (ctx.mounted) _notice('Görev, kapasite veya hedef verileri tam okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final start = date(anchor), end = start.add(Duration(days: horizon));
      final people = <String>{...tasks.map(owner), ...capacities.keys, ...goals.keys}.where((x) => x != 'Atanmamış').toList()..sort();
      final entries = <Map<String, dynamic>>[];
      final loads = <String, int>{};
      String key(String p, DateTime d) => '$p|${iso(d)}';
      for (var i = 0; i < tasks.length; i++) {
        final t = tasks[i], d = parse(t['targetDate'] ?? t['due']);
        if (!active(t) || d == null || date(d).isBefore(start) || !date(d).isBefore(end)) continue;
        final p = owner(t), m = duration(t);
        loads[key(p, date(d))] = (loads[key(p, date(d))] ?? 0) + m;
        entries.add({'index': i, 'task': t, 'owner': p, 'date': date(d), 'minutes': m});
      }
      int cap(String p) => capacities[p] ?? 120;
      int goal(String p) => goals[p] ?? 0;
      int deviation(Map<String, int> l) {
        var sum = 0;
        for (final e in l.entries) {
          final p = e.key.split('|').first;
          final over = e.value - cap(p) - goal(p);
          if (over > 0) sum += over;
        }
        return sum;
      }
      int risky(Map<String, int> l) => l.entries.where((e) => e.value > cap(e.key.split('|').first) + goal(e.key.split('|').first)).length;
      final proposals = <Map<String, dynamic>>[];
      final simulated = Map<String, int>.from(loads);
      final movable = entries.where((e) => !protected(e['task'] as Map<String, dynamic>)).toList()
        ..sort((a, b) => (b['minutes'] as int).compareTo(a['minutes'] as int));
      for (final e in movable) {
        if (proposals.length >= maxMoves) break;
        final fromOwner = e['owner'] as String, fromDate = e['date'] as DateTime, m = e['minutes'] as int;
        final fromKey = key(fromOwner, fromDate);
        if ((simulated[fromKey] ?? 0) <= cap(fromOwner) + goal(fromOwner)) continue;
        String? bestOwner;
        DateTime? bestDate;
        var bestGain = 0;
        for (final p in people) {
          if (strategy == 0 && p != fromOwner) continue;
          for (var offset = 0; offset < horizon; offset++) {
            final d = start.add(Duration(days: offset));
            if (strategy == 1 && d != fromDate) continue;
            if (d.isBefore(fromDate) || (p == fromOwner && d == fromDate)) continue;
            if (!allowWeekends && d.weekday >= 6) continue;
            final toKey = key(p, d);
            final oldFrom = (simulated[fromKey] ?? 0) - cap(fromOwner) - goal(fromOwner);
            final oldTo = (simulated[toKey] ?? 0) - cap(p) - goal(p);
            final newFrom = oldFrom - m, newTo = oldTo + m;
            int positive(int x) => x > 0 ? x : 0;
            final gain = positive(oldFrom) + positive(oldTo) - positive(newFrom) - positive(newTo);
            if (gain > bestGain) { bestGain = gain; bestOwner = p; bestDate = d; }
          }
        }
        if (bestOwner == null || bestDate == null || bestGain <= 0) continue;
        simulated[fromKey] = (simulated[fromKey] ?? 0) - m;
        final toKey = key(bestOwner, bestDate);
        simulated[toKey] = (simulated[toKey] ?? 0) + m;
        proposals.add({'index': e['index'], 'title': '${(e['task'] as Map)['title'] ?? 'Görev'}',
          'fromOwner': fromOwner, 'fromDate': fromDate, 'toOwner': bestOwner, 'toDate': bestDate,
          'minutes': m, 'gain': bestGain});
      }
      final selectedMoves = proposals.where((m) => chosen.contains(m['index'])).toList();
      final selectedLoads = Map<String, int>.from(loads);
      for (final m in selectedMoves) {
        final a = key(m['fromOwner'] as String, m['fromDate'] as DateTime), b = key(m['toOwner'] as String, m['toDate'] as DateTime);
        selectedLoads[a] = (selectedLoads[a] ?? 0) - (m['minutes'] as int);
        selectedLoads[b] = (selectedLoads[b] ?? 0) + (m['minutes'] as int);
      }
      Future<void> apply() async {
        if (selectedMoves.isEmpty || saving) return;
        final ok = await showDialog<bool>(context: ctx, builder: (d) => AlertDialog(
          title: const Text('Seçilen görevleri uygula?'),
          content: Text('${selectedMoves.length} görev değişecek. Hedef sapması ${deviation(loads)} → ${deviation(selectedLoads)} dk. İşlem plan geçmişine kaydedilecek.'),
          actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
            FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Onayla ve kaydet'))]));
        if (ok != true || !ctx.mounted) return;
        refresh(() => saving = true);
        try {
          final prefs = await SharedPreferences.getInstance();
          final original = prefs.getString(taskKey) ?? '[]';
          final raw = jsonDecode(original);
          if (raw is! List) throw StateError('Görev verisi geçersiz.');
          final fresh = raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          if (jsonEncode(fresh) != jsonEncode(tasks)) throw StateError('Görevler değişmiş. Ekranı yeniden açın.');
          final versionsKey = 'paket40_optimization_plan_versions_v1';
          // Plan geçmişi için uygulamanın mevcut anahtarını kullan.
          final oldVersions = prefs.getString(versionsKey);
          final decodedVersions = jsonDecode(oldVersions ?? '[]');
          if (decodedVersions is! List) throw StateError('Plan geçmişi geçersiz.');
          final versions = decodedVersions.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          final before = <Map<String, dynamic>>[], after = <Map<String, dynamic>>[];
          // Tam plan ve karar anındaki eşikler saklanır.
          final fullPlanBefore = fresh.map((t) => Map<String, dynamic>.from(t)).toList();
          final savedCapacities = Map<String, int>.from(capacities);
          final savedGoals = Map<String, int>.from(goals);
          final stamp = DateTime.now().toIso8601String();
          for (final m in selectedMoves) {
            final i = m['index'] as int, t = fresh[i];
            if (!active(t) || protected(t)) throw StateError('Korunan veya tamamlanan görev değiştirilemez.');
            final oldDate = parse(t['targetDate'] ?? t['due']);
            if (oldDate == null || iso(date(oldDate)) != iso(m['fromDate'] as DateTime) || owner(t) != m['fromOwner']) throw StateError('Görev bilgileri değişmiş.');
            before.add({'title': t['title'], 'owner': t['owner'], 'targetDate': t['targetDate'], 'estimatedMinutes': t['estimatedMinutes']});
            t['owner'] = m['toOwner'];
            t['targetDate'] = iso(m['toDate'] as DateTime);
            t['updated'] = stamp;
            final history = t['history'] is List ? List<dynamic>.from(t['history'] as List) : <dynamic>[];
            history.add({'at': stamp, 'action': 'Hedef sapması optimizasyonu', 'note': '${m['fromOwner']} / ${iso(m['fromDate'] as DateTime)} → ${m['toOwner']} / ${t['targetDate']}'});
            t['history'] = history;
            after.add({'title': t['title'], 'owner': t['owner'], 'targetDate': t['targetDate'], 'estimatedMinutes': t['estimatedMinutes']});
          }
          versions.insert(0, {'at': stamp, 'name': 'Hedef sapması • ${selectedMoves.length} görev', 'type': 'goal_deviation_distribution',
            'note': '${deviation(loads)} → ${deviation(selectedLoads)} dk', 'before': before, 'after': after,
            'fullPlanBefore': fullPlanBefore, 'fullPlanAfter': fresh.map((t) => Map<String, dynamic>.from(t)).toList(),
            'capacitySnapshot': savedCapacities, 'goalSnapshot': savedGoals, 'snapshotVersion': 1});
          if (!await prefs.setString(taskKey, jsonEncode(fresh))) throw StateError('Görevler kaydedilemedi.');
          if (!await prefs.setString(versionsKey, jsonEncode(versions.take(100).toList()))) {
            await prefs.setString(taskKey, original);
            throw StateError('Plan geçmişi kaydedilemedi; görevler geri alındı.');
          }
          tasks..clear()..addAll(fresh);
          chosen.clear();
          if (ctx.mounted) { refresh(() {}); _notice('${selectedMoves.length} görev güncellendi.'); }
        } catch (e) { if (ctx.mounted) _notice('Uygulama başarısız: $e'); }
        finally { if (ctx.mounted) refresh(() => saving = false); }
      }
      final visible = proposals.where((m) => search.trim().isEmpty || '${m['title']} ${m['fromOwner']} ${m['toOwner']}'.toLowerCase().contains(search.toLowerCase().trim())).toList();
      final report = <String>['Görev;Önceki sorumlu;Önceki tarih;Yeni sorumlu;Yeni tarih;Süre dk;Hedef sapması kazancı dk;Seçili'];
      for (final m in visible) { report.add([m['title'], m['fromOwner'], iso(m['fromDate'] as DateTime), m['toOwner'], iso(m['toDate'] as DateTime), m['minutes'], m['gain'], chosen.contains(m['index'])].map(csv).join(';')); }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Hedef sapması / akıllı yeniden dağıtım', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        if (busy) const LinearProgressIndicator() else ...[
          const Text('Kayıtlı sorumlu hedeflerine göre tarih, sorumlu veya karma öneriler. Kritik/yüksek öncelikli görevler korunur. Öneriler gerçek müsaitlik doğrulaması yapmaz.'),
          Wrap(spacing: 8, runSpacing: 5, children: [
            DropdownButton<int>(value: horizon, items: [7,14,21,28].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(), onChanged: (n) => refresh(() { horizon = n ?? 14; chosen.clear(); })),
            DropdownButton<int>(value: maxMoves, items: [5,10,15,25,40].map((n) => DropdownMenuItem(value: n, child: Text('En fazla $n'))).toList(), onChanged: (n) => refresh(() { maxMoves = n ?? 15; chosen.clear(); })),
            DropdownButton<int>(value: strategy, items: const [DropdownMenuItem(value: 0, child: Text('Tarih')), DropdownMenuItem(value: 1, child: Text('Sorumlu')), DropdownMenuItem(value: 2, child: Text('Karma'))], onChanged: (n) => refresh(() { strategy = n ?? 2; chosen.clear(); })),
            FilterChip(label: const Text('Hafta sonu'), selected: allowWeekends, onSelected: (v) => refresh(() { allowWeekends = v; chosen.clear(); })),
          ]),
          Row(children: [IconButton(onPressed: () => refresh(() { anchor = anchor.subtract(Duration(days: horizon)); chosen.clear(); }), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() { anchor = anchor.add(Duration(days: horizon)); chosen.clear(); }), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() { anchor = DateTime.now(); chosen.clear(); }), child: const Text('Bugün'))]),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('${entries.length} açık görev • ${proposals.length} öneri • ${selectedMoves.length} seçili', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('Hedef sapması: ${deviation(loads)} → ${deviation(selectedLoads)} dk (seçili plan)'),
            Text('Hedefi aşan sorumlu-gün: ${risky(loads)} → ${risky(selectedLoads)}'),
            Text('Tüm öneriler uygulanırsa tahmini sapma: ${deviation(simulated)} dk'),
          ]))),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Görev veya sorumlu ara'), onChanged: (v) => refresh(() => search = v)),
          Wrap(spacing: 8, children: [TextButton(onPressed: () => refresh(() => chosen.addAll(proposals.map((e) => e['index'] as int))), child: const Text('Tümünü seç')), TextButton(onPressed: () => refresh(chosen.clear), child: const Text('Seçimi temizle'))]),
          if (visible.isEmpty) const ListTile(title: Text('Bu dönemde hedef sapmasını azaltan uygun öneri bulunamadı.')),
          ...visible.map((m) => CheckboxListTile(value: chosen.contains(m['index']), onChanged: saving ? null : (v) => refresh(() { if (v == true) { chosen.add(m['index'] as int); } else { chosen.remove(m['index']); } }),
            title: Text('${m['title']} • ${m['minutes']} dk'),
            subtitle: Text('${m['fromOwner']} / ${iso(m['fromDate'] as DateTime)} → ${m['toOwner']} / ${iso(m['toDate'] as DateTime)}\nTahmini hedef sapması azalması: ${m['gain']} dk'))),
          FilledButton.icon(onPressed: saving || selectedMoves.isEmpty ? null : apply, icon: const Icon(Icons.verified_outlined), label: Text(saving ? 'Kaydediliyor...' : 'Seçilen ${selectedMoves.length} görevi onayla ve uygula')),
          OutlinedButton.icon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${report.join('\r\n')}')); if (mounted) _notice('Öneriler CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('Önerileri CSV kopyala')),
          OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenOwnerCapacityDecisionGoals(); }, icon: const Icon(Icons.track_changes), label: const Text('Kapasite hedeflerine dön')),
          const Text('Varsayılan kapasite 120 dk, eksik görev süresi 30 dk kabul edilir. Öneriler yalnızca hedef sapması azalırsa oluşturulur.'),
        ],
      ])));
    }));
  }

  void _showKitchenOwnerCapacityDecisionGoals() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalsKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    var started = false, loading = true, days = 14, limit = 90;
    var owner = 'Tümü', query = '', riskOnly = false, includeWeekends = true;
    var anchor = DateTime.now();
    DateTime day(DateTime d) => DateTime(d.year, d.month, d.day);
    DateTime? parse(Object? v) => DateTime.tryParse('${v ?? ''}');
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String person(Map<String, dynamic> t) { final v = '${t['owner'] ?? ''}'.trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains('${t['status'] ?? 'Açık'}');
    int minutes(Map<String, dynamic> t) { final n = int.tryParse('${t['estimatedMinutes'] ?? ''}'); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (raw is List) tasks..clear()..addAll(raw.whereType<Map>().map((v) => Map<String, dynamic>.from(v)));
              final cap = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (cap is Map) for (final e in cap.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 15 && n <= 1440) capacities['${e.key}'] = n; }
              final saved = jsonDecode(prefs.getString(goalsKey) ?? '{}');
              if (saved is Map) for (final e in saved.entries) { final n = int.tryParse('${e.value}'); if (n != null && n >= 0 && n <= 1440) goals['${e.key}'] = n; }
            } catch (_) { if (mounted) _notice('Hedef veya görev verileri kısmen okunamadı; mevcut kayıtlar korunuyor.'); }
            if (ctx.mounted) refresh(() => loading = false);
          }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
        }
        final start = day(anchor), end = start.add(Duration(days: days));
        final owners = {...tasks.map(person), ...capacities.keys, ...goals.keys}.toList()..sort();
        final selected = owner == 'Tümü' || owners.contains(owner) ? owner : 'Tümü';
        final load = <String, int>{};
        final grouped = <String, List<Map<String, dynamic>>>{};
        for (final t in tasks) {
          if (!active(t)) continue;
          final date = parse(t['targetDate'] ?? t['due']);
          if (date == null || day(date).isBefore(start) || !day(date).isBefore(end)) continue;
          final key = '${person(t)}|${iso(day(date))}';
          load[key] = (load[key] ?? 0) + minutes(t);
          grouped.putIfAbsent(key, () => []).add(t);
        }
        final rows = <Map<String, dynamic>>[];
        for (final who in owners) {
          if (selected != 'Tümü' && selected != who) continue;
          for (var i = 0; i < days; i++) {
            final d = start.add(Duration(days: i));
            if (!includeWeekends && d.weekday >= 6) continue;
            final key = '$who|${iso(d)}';
            final actual = load[key] ?? 0;
            final cap = capacities[who] ?? 120;
            final target = goals[who] ?? 0;
            final excess = (actual - cap).clamp(0, 1000000).toInt();
            final goalExcess = (excess - target).clamp(0, 1000000).toInt();
            final rate = actual * 100 / cap;
            if (riskOnly && rate < limit && goalExcess == 0) continue;
            if (query.trim().isNotEmpty && !('$who ${iso(d)} ${grouped[key]?.map((t) => t['title']).join(' ') ?? ''}'.toLowerCase().contains(query.toLowerCase()))) continue;
            rows.add({'who': who, 'date': d, 'load': actual, 'cap': cap, 'target': target, 'excess': excess, 'gap': goalExcess, 'rate': rate, 'tasks': grouped[key] ?? <Map<String, dynamic>>[]});
          }
        }
        rows.sort((a, b) => (b['gap'] as int).compareTo(a['gap'] as int));
        final totalGap = rows.fold<int>(0, (v, r) => v + (r['gap'] as int));
        final totalExcess = rows.fold<int>(0, (v, r) => v + (r['excess'] as int));
        final atRisk = rows.where((r) => (r['gap'] as int) > 0).length;
        final variants = <Map<String, dynamic>>[];
        for (final extra in [0, 15, 30, 60]) {
          var over = 0, gap = 0, risk = 0;
          for (final r in rows) {
            final e = ((r['load'] as int) - (r['cap'] as int) - extra).clamp(0, 1000000).toInt();
            final g = (e - (r['target'] as int)).clamp(0, 1000000).toInt();
            over += e; gap += g; if (g > 0) risk++;
          }
          variants.add({'extra': extra, 'over': over, 'gap': gap, 'risk': risk});
        }
        Future<void> editGoal(String who) async {
          final controller = TextEditingController(text: '${goals[who] ?? 0}');
          final value = await showDialog<int>(context: ctx, builder: (dialog) => AlertDialog(
            title: Text('$who • kabul edilen günlük aşım'),
            content: TextField(controller: controller, keyboardType: TextInputType.number,
              decoration: const InputDecoration(labelText: 'Dakika', helperText: '0–1440 dakika; 0 = aşım kabul edilmez')),
            actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(dialog, int.tryParse(controller.text.trim())), child: const Text('Kaydet'))]));
          disposeAfterDialog(controller);
          if (value == null) return;
          if (value < 0 || value > 1440) { if (mounted) _notice('Hedef 0–1440 dakika arasında olmalı.'); return; }
          final old = goals[who];
          goals[who] = value;
          try {
            final prefs = await SharedPreferences.getInstance();
            if (!await prefs.setString(goalsKey, jsonEncode(goals))) throw StateError('Kayıt yapılamadı');
            if (ctx.mounted) refresh(() {});
          } catch (_) {
            if (old == null) { goals.remove(who); } else { goals[who] = old; }
            if (mounted) _notice('Hedef kaydedilemedi; önceki değer korundu.');
          }
        }
        final export = <String>['Sorumlu,Tarih,Planlanan Dakika,Kapasite Dakika,Kabul Edilen Aşım,Aşım Dakika,Hedef Sapması,Doluluk Yüzdesi,Görev Sayısı'];
        for (final r in rows) { export.add([r['who'], iso(r['date'] as DateTime), r['load'], r['cap'], r['target'], r['excess'], r['gap'], (r['rate'] as double).toStringAsFixed(1), (r['tasks'] as List).length].map(csv).join(',')); }
        return SafeArea(child: Padding(padding: const EdgeInsets.all(16), child: ListView(children: [
          Row(children: [const Expanded(child: Text('Kapasite iyileştirme hedefleri / haftalık karar merkezi', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
          if (loading) const LinearProgressIndicator() else ...[
            const Text('Her sorumlu için kabul edilebilir günlük kapasite aşımını belirle. Plan ve senaryolar kayıtları değiştirmeden hesaplanır.'),
            Wrap(spacing: 8, runSpacing: 8, children: [
              DropdownButton<int>(value: days, items: [7, 14, 21, 28].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(), onChanged: (v) => refresh(() => days = v ?? 14)),
              DropdownButton<String>(value: selected, items: ['Tümü', ...owners].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => refresh(() => owner = v ?? 'Tümü')),
              DropdownButton<int>(value: limit, items: [70, 80, 90, 100].map((n) => DropdownMenuItem(value: n, child: Text('Risk %$n'))).toList(), onChanged: (v) => refresh(() => limit = v ?? 90)),
              FilterChip(label: const Text('Yalnızca riskli'), selected: riskOnly, onSelected: (v) => refresh(() => riskOnly = v)),
              FilterChip(label: const Text('Hafta sonu dahil'), selected: includeWeekends, onSelected: (v) => refresh(() => includeWeekends = v)),
            ]),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Sorumlu, görev veya tarih ara'), onChanged: (v) => refresh(() => query = v)),
            Row(children: [IconButton(onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: days))), icon: const Icon(Icons.chevron_left)), Expanded(child: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}', textAlign: TextAlign.center)), IconButton(onPressed: () => refresh(() => anchor = anchor.add(Duration(days: days))), icon: const Icon(Icons.chevron_right)), TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün'))]),
            Card(color: const Color(0xFFF3E8FF), child: Padding(padding: const EdgeInsets.all(12), child: Text('Görüntülenen aşım: $totalExcess dk • Hedef üstü: $totalGap dk • Hedefi aşan sorumlu-gün: $atRisk\nÖzetler arama ve filtrelerden etkilenir.'))),
            const Text('Sorumlu bazında hedefler', style: TextStyle(fontWeight: FontWeight.bold)),
            ...owners.where((w) => selected == 'Tümü' || w == selected).map((w) => ListTile(title: Text(w), subtitle: Text('Günlük kapasite: ${capacities[w] ?? 120} dk • Kabul edilen aşım: ${goals[w] ?? 0} dk'), trailing: IconButton(onPressed: () => editGoal(w), icon: const Icon(Icons.edit_outlined)))),
            const Divider(), const Text('Kapasite varsayımı senaryoları (yalnızca simülasyon)', style: TextStyle(fontWeight: FontWeight.bold)),
            ...variants.map((v) => Card(child: ListTile(title: Text((v['extra'] as int) == 0 ? 'Mevcut kapasite' : 'Günlük +${v['extra']} dk varsayımı'), subtitle: Text('Aşım: ${v['over']} dk • Hedef sapması: ${v['gap']} dk • Riskli gün: ${v['risk']}'), trailing: Text('−${totalGap - (v['gap'] as int)} dk')))),
            const Text('Ek kapasite senaryoları gerçek kapasite hedeflerini veya görevleri değiştirmez. Alternatif kapasitenin gerçekten sağlanabilirliği ayrıca değerlendirilmelidir.'),
            const Divider(), const Text('Günlük hedef sapmaları', style: TextStyle(fontWeight: FontWeight.bold)),
            ...rows.take(80).map((r) => Card(child: ExpansionTile(title: Text('${r['who']} • ${iso(r['date'] as DateTime)}'), subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('${r['load']}/${r['cap']} dk • Aşım ${r['excess']} dk • Hedef sapması ${r['gap']} dk'), LinearProgressIndicator(value: ((r['rate'] as double) / 100).clamp(0.0, 1.0))]), children: (r['tasks'] as List<Map<String, dynamic>>).map((t) => ListTile(title: Text('${t['title'] ?? 'Görev'}'), subtitle: Text('${minutes(t)} dk • ${t['priority'] ?? t['level'] ?? 'Normal'}'))).toList()))),
            if (rows.length > 80) Text('${rows.length - 80} ek satır CSV raporunda yer alıyor.'),
            if (atRisk > 0) const Card(child: ListTile(leading: Icon(Icons.tips_and_updates_outlined), title: Text('İyileştirme önerisi'), subtitle: Text('Hedefi aşan günlerde kritik olmayan görevlerin tarihini veya sorumlusunu mevcut seçimli optimizasyon ekranında değerlendirin.'))),
            FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: '\uFEFF${export.join('\r\n')}')); if (mounted) _notice('Kapasite hedef raporu CSV olarak kopyalandı.'); }, icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
            OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenSelectiveDistributionApply(); }, icon: const Icon(Icons.tune_outlined), label: const Text('Seçimli optimizasyon ekranına geç')),
          ],
        ])));
      }));
  }

  void _showKitchenCapacityGoalsBalance() {
    const actionsKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final tasks=<Map<String,dynamic>>[];
    final capacities=<String,int>{};
    var started=false,loading=true,days=7,threshold=90,onlyRisk=false,query='',owner='Tümü',weekends=true;
    var anchor=DateTime.now();
    DateTime day(DateTime d)=>DateTime(d.year,d.month,d.day);
    DateTime? date(Object? v)=>DateTime.tryParse('${v??''}');
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String person(Map<String,dynamic> t){final v='${t['owner']??''}'.trim();return v.isEmpty?'Atanmamış':v;}
    bool active(Map<String,dynamic> t)=>!['Tamamlandı','İptal'].contains('${t['status']??'Açık'}');
    int duration(Map<String,dynamic> t){final n=int.tryParse('${t['estimatedMinutes']??''}');return n!=null&&n>=5&&n<=1440?n:30;}
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((prefs){
        try{final raw=jsonDecode(prefs.getString(actionsKey)??'[]');if(raw is List){tasks..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}
          final saved=jsonDecode(prefs.getString(capacityKey)??'{}');if(saved is Map){for(final e in saved.entries){final n=int.tryParse('${e.value}');if(n!=null&&n>=15&&n<=1440)capacities['${e.key}']=n;}}}
        catch(_){if(mounted)_notice('Bazı görev veya kapasite kayıtları okunamadı.');}
        if(ctx.mounted)refresh(()=>loading=false);
      }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:days));
      final owners={...tasks.map(person),...capacities.keys}.toList()..sort();
      final selected=owner=='Tümü'||owners.contains(owner)?owner:'Tümü';
      final planned=<String,int>{};final counts=<String,int>{};final grouped=<String,List<Map<String,dynamic>>>{};
      for(final t in tasks){if(!active(t))continue;final d=date(t['targetDate']??t['due']);if(d==null||day(d).isBefore(start)||!day(d).isBefore(end))continue;
        final key='${person(t)}|${iso(day(d))}';planned[key]=(planned[key]??0)+duration(t);counts[key]=(counts[key]??0)+1;grouped.putIfAbsent(key,()=>[]).add(t);}
      final rows=<Map<String,dynamic>>[];
      for(final who in owners){if(selected!='Tümü'&&who!=selected)continue;
        for(var i=0;i<days;i++){final d=start.add(Duration(days:i)),key='$who|${iso(d)}';final load=planned[key]??0,cap=capacities[who]??120;
          final rate=load/cap*100,excess=load>cap?load-cap:0;
          if(onlyRisk&&rate<threshold)continue;
          if(query.isNotEmpty&&!('$who ${iso(d)} ${grouped[key]?.map((e)=>e['title']).join(' ')??''}'.toLowerCase().contains(query.toLowerCase())))continue;
          rows.add({'who':who,'date':d,'load':load,'cap':cap,'rate':rate,'excess':excess,'tasks':grouped[key]??<Map<String,dynamic>>[]});}}
      rows.sort((a,b)=>(b['rate'] as double).compareTo(a['rate'] as double));
      final total=rows.fold<int>(0,(v,r)=>v+(r['load'] as int));
      final excess=rows.fold<int>(0,(v,r)=>v+(r['excess'] as int));
      final overloaded=rows.where((r)=>(r['excess'] as int)>0).length;
      Future<void> edit(String who)async{final input=TextEditingController(text:'${capacities[who]??120}');final n=await showDialog<int>(context:ctx,builder:(dialog)=>AlertDialog(title:Text('$who günlük kapasite (dakika)'),content:TextField(controller:input,keyboardType:TextInputType.number,decoration:const InputDecoration(helperText:'15–1440 dakika')),actions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(dialog,int.tryParse(input.text)),child:const Text('Kaydet'))]));disposeAfterDialog(input);if(n==null)return;if(n<15||n>1440){if(mounted)_notice('Kapasite 15–1440 dakika arasında olmalı.');return;}final old=capacities[who];capacities[who]=n;try{final prefs=await SharedPreferences.getInstance();final ok=await prefs.setString(capacityKey,jsonEncode(capacities));if(!ok)throw StateError('Kayıt başarısız');if(ctx.mounted)refresh((){});}catch(_){if(old==null){capacities.remove(who);}else{capacities[who]=old;}if(mounted)_notice('Kapasite kaydedilemedi.');}}
      final proposals=<Map<String,dynamic>>[];
      final simulated=Map<String,int>.from(planned);
      for(final entry in grouped.entries.toList()..sort((a,b)=>(planned[b.key]??0).compareTo(planned[a.key]??0))){
        final parts=entry.key.split('|'),who=parts.first,original=date(parts.last);if(original==null)continue;
        if((simulated[entry.key]??0)<=(capacities[who]??120))continue;
        final eligible=entry.value.where((t)=>!['Kritik','Yüksek'].contains('${t['priority']??t['level']??''}')).toList()..sort((a,b)=>duration(b).compareTo(duration(a)));
        for(final task in eligible){if((simulated[entry.key]??0)<=(capacities[who]??120))break;
          final mins=duration(task);DateTime? best;String? bestWho;int bestFree=-1;
          for(final candidate in owners){if(candidate=='Atanmamış')continue;
            for(var j=0;j<days;j++){final d=start.add(Duration(days:j));if(!weekends&&d.weekday>=6)continue;if(d.isBefore(day(DateTime.now())))continue;
              if(candidate==who&&iso(d)==iso(original))continue;
              final key='$candidate|${iso(d)}',free=(capacities[candidate]??120)-(simulated[key]??0);
              if(free>=mins&&free>bestFree){best=d;bestWho=candidate;bestFree=free;}}}
          if(best==null||bestWho==null)continue;
          final targetKey='$bestWho|${iso(best)}';simulated[entry.key]=(simulated[entry.key]??0)-mins;simulated[targetKey]=(simulated[targetKey]??0)+mins;
          proposals.add({'task':task,'from':entry.key,'to':targetKey,'minutes':mins});if(proposals.length>=40)break;
        }if(proposals.length>=40)break;
      }
      final before=planned.entries.fold<int>(0,(v,e)=>v+(e.value-(capacities[e.key.split('|').first]??120)).clamp(0,1000000).toInt());
      final after=simulated.entries.fold<int>(0,(v,e)=>v+(e.value-(capacities[e.key.split('|').first]??120)).clamp(0,1000000).toInt());
      final export=<String>['Sorumlu,Tarih,Görev Sayısı,Planlanan Dakika,Kapasite Dakika,Doluluk Yüzdesi,Aşım Dakika'];
      for(final r in rows){export.add([r['who'],iso(r['date'] as DateTime),(r['tasks'] as List).length,r['load'],r['cap'],(r['rate'] as double).toStringAsFixed(1),r['excess']].map(csv).join(','));}
      return SafeArea(child:Padding(padding:const EdgeInsets.all(16),child:ListView(children:[
        Row(children:[const Expanded(child:Text('Kapasite hedefleri / haftalık iş yükü dengeleme',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        if(loading)const LinearProgressIndicator()else ...[
          Wrap(spacing:8,runSpacing:8,children:[DropdownButton<int>(value:days,items:[7,14,21,28].map((n)=>DropdownMenuItem(value:n,child:Text('$n gün'))).toList(),onChanged:(n)=>refresh(()=>days=n??7)),DropdownButton<String>(value:selected,items:['Tümü',...owners].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>owner=v??'Tümü')),DropdownButton<int>(value:threshold,items:[70,80,90,100].map((n)=>DropdownMenuItem(value:n,child:Text('Risk %$n'))).toList(),onChanged:(v)=>refresh(()=>threshold=v??90)),FilterChip(label:const Text('Yalnızca riskli'),selected:onlyRisk,onSelected:(v)=>refresh(()=>onlyRisk=v)),FilterChip(label:const Text('Hafta sonu öner'),selected:weekends,onSelected:(v)=>refresh(()=>weekends=v))]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Görev, sorumlu veya tarih ara'),onChanged:(v)=>refresh(()=>query=v)),
          Row(children:[IconButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:days))),icon:const Icon(Icons.chevron_left)),Expanded(child:Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}',textAlign:TextAlign.center)),IconButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:days))),icon:const Icon(Icons.chevron_right)),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün'))]),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('Görüntülenen plan: $total dk • Aşım: $excess dk • Aşırı yüklü sorumlu-gün: $overloaded\nKapasite hesabı yalnızca açık ve plan tarihli görevleri kapsar. Filtreler görünür özetleri etkiler.'))),
          const Text('Sorumlu bazında günlük hedefler',style:TextStyle(fontWeight:FontWeight.bold)),
          ...owners.where((w)=>selected=='Tümü'||selected==w).map((w)=>ListTile(title:Text(w),subtitle:Text('Günlük ${capacities[w]??120} dakika'),trailing:IconButton(icon:const Icon(Icons.edit_outlined),onPressed:()=>edit(w)))),
          const Text('Günlük kapasite haritası',style:TextStyle(fontWeight:FontWeight.bold)),
          ...rows.take(80).map((r)=>Card(child:ExpansionTile(title:Text('${r['who']} • ${iso(r['date'] as DateTime)}'),subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${r['load']}/${r['cap']} dk • %${(r['rate'] as double).toStringAsFixed(0)} doluluk • ${r['excess']} dk aşım'),LinearProgressIndicator(value:((r['rate'] as double)/100).clamp(0.0,1.0))]),children:(r['tasks'] as List<Map<String,dynamic>>).map((t)=>ListTile(title:Text('${t['title']??'Görev'}'),subtitle:Text('${duration(t)} dk • ${t['priority']??t['level']??'Normal'}'))).toList()))),
          if(rows.length>80)Text('${rows.length-80} satır daha CSV raporunda bulunuyor.'),
          const Divider(),const Text('Kural tabanlı dengeleme önizlemesi',style:TextStyle(fontWeight:FontWeight.bold)),
          Text('${proposals.length} öneri • Tüm açık görevlerde aşım: $before → $after dk • Tahmini azalma: ${before-after} dk'),
          const Text('Bu öneriler kaydedilmez. Kritik/yüksek öncelikli görevler taşınmaz; gerçek müsaitlik ve yetkinlik kontrolü yapılmaz.'),
          ...proposals.take(20).map((p)=>ListTile(leading:const Icon(Icons.swap_horiz),title:Text('${(p['task'] as Map)['title']??'Görev'}'),subtitle:Text('${p['from']} → ${p['to']} • ${p['minutes']} dk'))),
          if(proposals.length>20)Text('${proposals.length-20} ek öneri mevcut.'),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${export.join('\r\n')}'));if(mounted)_notice('Kapasite raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Kapasite CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveDecisionCenter();},icon:const Icon(Icons.account_tree_outlined),label:const Text('Onaylı senaryo uygulama ekranına geç')),
        ]
      ])));
    }));
  }

  void _showKitchenPreventiveScorecard() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    const actionsKey = 'paket39_purchase_improvement_actions_v1';
    const capacitiesKey = 'paket39_daily_available_minutes_v1';
    const goalsKey = 'paket39_plan_decision_goals_v1';
    final versions = <Map<String, dynamic>>[];
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool initialized = false, loading = true, preventiveOnly = true, riskyOnly = false;
    int weeks = 8, goalOverflow = 0, goalCritical = 0, goalOwners = 10;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü', query = '';
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String fmt(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    List<Map<String, dynamic>> decodeRows(Object? v) => v is List
        ? v.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList()
        : <Map<String, dynamic>>[];
    String owner(Map<String, dynamic> a) {
      final x = str(a['owner']).trim();
      return x.isEmpty ? 'Atanmamış' : x;
    }
    int minutes(Map<String, dynamic> a) {
      final n = int.tryParse(str(a['estimatedMinutes']));
      return n != null && n >= 5 && n <= 1440 ? n : 30;
    }
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    bool critical(Map<String, dynamic> a) {
      final p = str(a['priority'] ?? a['level']).toLowerCase();
      return p.contains('kritik') || p.contains('critical');
    }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    Map<String, int> capacityLoad(List<Map<String, dynamic>> data) {
      final loads = <String, int>{};
      for (final a in data) {
        if (!active(a)) continue;
        final d = date(a['targetDate']);
        if (d == null) continue;
        final k = '${owner(a)}|${d.year}-${d.month}-${d.day}';
        loads[k] = (loads[k] ?? 0) + minutes(a);
      }
      return loads;
    }
    Map<String, int> capacityMetrics(List<Map<String, dynamic>> data) {
      final loads = capacityLoad(data);
      int overflow = 0, days = 0;
      for (final e in loads.entries) {
        final person = e.key.split('|').first;
        final limit = capacities[person] ?? 120;
        if (e.value > limit) { overflow += e.value - limit; days++; }
      }
      return {'overflow': overflow, 'days': days};
    }
    Map<String, dynamic> analyze(Map<String, dynamic> v) {
      final before = decodeRows(v['before']);
      final after = decodeRows(v['after']);
      final old = <String, Map<String, dynamic>>{};
      for (final a in before) { old[str(a['id'] ?? a['title'])] = a; }
      int moved = 0, ownerChanges = 0, criticalDelay = 0, missing = 0;
      for (final a in after) {
        final b = old[str(a['id'] ?? a['title'])];
        if (b == null) { missing++; continue; }
        final d0 = date(b['targetDate']), d1 = date(a['targetDate']);
        if (owner(a) != owner(b)) ownerChanges++;
        if (owner(a) != owner(b) || str(a['targetDate']) != str(b['targetDate'])) moved++;
        if (d0 != null && d1 != null && d1.isAfter(d0) && (critical(a) || critical(b))) {
          criticalDelay += DateTime(d1.year, d1.month, d1.day)
              .difference(DateTime(d0.year, d0.month, d0.day)).inDays;
        }
      }
      final b = capacityMetrics(before), a = capacityMetrics(after);
      final reduction = b['overflow']! - a['overflow']!;
      final compliant = a['overflow']! <= goalOverflow &&
          criticalDelay <= goalCritical && ownerChanges <= goalOwners;
      return {'reduction': reduction, 'before': b['overflow']!,
        'after': a['overflow']!, 'beforeDays': b['days']!, 'afterDays': a['days']!,
        'moved': moved, 'ownerChanges': ownerChanges, 'criticalDelay': criticalDelay,
        'missing': missing, 'compliant': compliant, 'partial': true};
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!initialized) {
          initialized = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              versions.addAll(decodeRows(jsonDecode(prefs.getString(versionsKey) ?? '[]')));
              actions.addAll(decodeRows(jsonDecode(prefs.getString(actionsKey) ?? '[]')));
              final caps = jsonDecode(prefs.getString(capacitiesKey) ?? '{}');
              if (caps is Map) {
                for (final e in caps.entries) {
                  final n = int.tryParse(str(e.value));
                  if (n != null && n > 0) capacities[str(e.key)] = n;
                }
              }
              final goals = jsonDecode(prefs.getString(goalsKey) ?? '{}');
              if (goals is Map) {
                goalOverflow = int.tryParse(str(goals['overflow'])) ?? 0;
                goalCritical = int.tryParse(str(goals['criticalDelay'])) ?? 0;
                goalOwners = int.tryParse(str(goals['ownerChanges'])) ?? 10;
              }
            } catch (_) { if (mounted) _notice('Performans verileri kısmen okunamadı.'); }
            if (ctx.mounted) refresh(() => loading = false);
          }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
        }
        final end = monday(anchor).add(const Duration(days: 7));
        final start = end.subtract(Duration(days: weeks * 7));
        final options = <String>{'Tümü', ...actions.map(owner)}.toList()..sort();
        if (!options.contains(ownerFilter)) ownerFilter = 'Tümü';
        final filtered = versions.where((v) {
          final at = date(v['at']);
          if (at == null || at.isBefore(start) || !at.isBefore(end)) return false;
          if (preventiveOnly && !('${v['name']} ${v['note']}'.toLowerCase().contains('önleyici') ||
              str(v['type']).toLowerCase().contains('preventive'))) { return false; }
          if (!'${v['name']} ${v['note']} ${v['type']}'.toLowerCase().contains(query.toLowerCase())) return false;
          if (ownerFilter != 'Tümü' && ![
            ...decodeRows(v['before']), ...decodeRows(v['after'])
          ].any((a) => owner(a) == ownerFilter)) { return false; }
          return true;
        }).map((v) => <String, dynamic>{'version': v, 'metrics': analyze(v)}).where((item) {
          final m = item['metrics'] as Map<String, dynamic>;
          return !riskyOnly || (m['reduction'] as int) < 0 || m['compliant'] != true;
        }).toList()..sort((a, b) => str((b['version'] as Map)['at']).compareTo(str((a['version'] as Map)['at'])));
        int sum(String k) => filtered.fold<int>(0, (p, v) => p + ((v['metrics'] as Map)[k] as int));
        final passed = filtered.where((v) => (v['metrics'] as Map)['compliant'] == true).length;
        final improved = filtered.where((v) => ((v['metrics'] as Map)['reduction'] as int) > 0).length;
        final regressed = filtered.where((v) => ((v['metrics'] as Map)['reduction'] as int) < 0).length;
        final weekly = <DateTime, List<Map<String, dynamic>>>{};
        for (final item in filtered) {
          final at = date((item['version'] as Map)['at']);
          if (at == null) continue;
          weekly.putIfAbsent(monday(at), () => []).add(item);
        }
        final activeTasks = actions.where(active).toList();
        final loads = capacityLoad(activeTasks);
        final ownerRisks = <String, Map<String, int>>{};
        for (final e in loads.entries) {
          final name = e.key.split('|').first;
          if (ownerFilter != 'Tümü' && name != ownerFilter) continue;
          final excess = e.value - (capacities[name] ?? 120);
          if (excess <= 0) continue;
          final record = ownerRisks.putIfAbsent(name, () => {'days': 0, 'minutes': 0});
          record['days'] = record['days']! + 1;
          record['minutes'] = record['minutes']! + excess;
        }
        final sortedRisks = ownerRisks.entries.toList()..sort((a, b) => b.value['minutes']!.compareTo(a.value['minutes']!));
        final recommendations = <String>[];
        if (regressed > 0) recommendations.add('$regressed sürümde planlanan kapasite aşımı arttı; ilgili görev hareketlerini inceleyin.');
        if (filtered.isNotEmpty && passed < filtered.length) recommendations.add('Hedefi karşılamayan ${filtered.length - passed} sürüm için erteleme ve sorumlu değişikliği sınırlarını kontrol edin.');
        if (sortedRisks.isNotEmpty) recommendations.add('${sortedRisks.first.key} için ${sortedRisks.first.value['days']} gün kapasite aşımı var; görevleri uygun günlere dağıtmayı değerlendirin.');
        if (sum('criticalDelay') > 0) recommendations.add('Kritik görevlerin toplam ${sum('criticalDelay')} günlük ertelenmesini gözden geçirin.');
        if (filtered.isEmpty) recommendations.add('Seçilen dönemde kayıt bulunamadı. Daha geniş dönem veya tüm sürümler filtresini deneyin.');
        if (recommendations.isEmpty) recommendations.add('Kayıtlı sürümlerde hedef sapması görünmüyor. Güncel görev kapasitesini izlemeye devam edin.');
        Future<void> export() async {
          final lines = <String>['Tarih;Sürüm;Kapasite Önce;Kapasite Sonra;Azalma;Değişen Görev;Sorumlu Değişimi;Kritik Erteleme;Hedef Uygun'];
          for (final item in filtered) {
            final v = item['version'] as Map<String, dynamic>, m = item['metrics'] as Map<String, dynamic>;
            lines.add([v['at'], v['name'], m['before'], m['after'], m['reduction'], m['moved'],
              m['ownerChanges'], m['criticalDelay'], m['compliant'] == true ? 'Evet' : 'Hayır'].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
          if (mounted) _notice('Performans karnesi CSV panoya kopyalandı.');
        }
        Widget stat(String label, String value) => Card(child: Padding(padding: const EdgeInsets.all(10),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(label, style: const TextStyle(fontSize: 12)), const SizedBox(height: 4),
            Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 18))])));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Padding(
          padding: const EdgeInsets.all(14), child: Column(children: [
            Row(children: [const Expanded(child: Text('Önleyici performans karnesi / hedef iyileştirme',
              style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold))),
              IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
            if (loading) const LinearProgressIndicator(),
            Expanded(child: ListView(children: [
              Wrap(spacing: 8, runSpacing: 4, crossAxisAlignment: WrapCrossAlignment.center, children: [
                DropdownButton<int>(value: weeks, items: [4, 8, 12, 26].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(),
                  onChanged: (v) { if (v != null) refresh(() => weeks = v); }),
                IconButton(tooltip: 'Önceki dönem', onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)),
                Text('${fmt(start)} – ${fmt(end.subtract(const Duration(days: 1)))}'),
                IconButton(tooltip: 'Sonraki dönem', onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)),
                TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün')),
              ]),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sürüm ara'),
                onChanged: (v) => refresh(() => query = v)),
              DropdownButton<String>(isExpanded: true, value: ownerFilter,
                items: options.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) { if (v != null) refresh(() => ownerFilter = v); }),
              SwitchListTile(dense: true, title: const Text('Yalnızca önleyici sürümler'), value: preventiveOnly,
                onChanged: (v) => refresh(() => preventiveOnly = v)),
              SwitchListTile(dense: true, title: const Text('Yalnızca hedef sapması / kötüleşme'), value: riskyOnly,
                onChanged: (v) => refresh(() => riskyOnly = v)),
              Wrap(spacing: 6, children: [
                SizedBox(width: 145, child: stat('Sürüm', '${filtered.length}')),
                SizedBox(width: 145, child: stat('Hedef uyumu', filtered.isEmpty ? '—' : '%${(100 * passed / filtered.length).round()}')),
                SizedBox(width: 145, child: stat('İyileşen', '$improved')),
                SizedBox(width: 145, child: stat('Kötüleşen', '$regressed')),
                SizedBox(width: 145, child: stat('Net aşım azalması', '${sum('reduction')} dk')),
                SizedBox(width: 145, child: stat('Değişen görev', '${sum('moved')}')),
              ]),
              const SizedBox(height: 8),
              Text('Mevcut hedefler: kapasite ≤ $goalOverflow dk • kritik erteleme ≤ $goalCritical gün • sorumlu değişimi ≤ $goalOwners',
                style: Theme.of(ctx).textTheme.bodySmall),
              const Text('Not: Sürüm kayıtları çoğunlukla yalnızca değişen görevleri içerir. Tarihsel kapasite karşılaştırmaları kısmi olup gerçekleşen iş yükünü göstermez.',
                style: TextStyle(fontSize: 12)),
              const Divider(),
              Text('Haftalık karne', style: Theme.of(ctx).textTheme.titleMedium),
              if (weekly.isEmpty) const ListTile(title: Text('Bu dönem için plan sürümü bulunamadı.')),
              ...((weekly.entries.toList()..sort((a,b) => b.key.compareTo(a.key))).map((entry) {
                final items = entry.value;
                final good = items.where((x) => (x['metrics'] as Map)['compliant'] == true).length;
                final net = items.fold<int>(0, (p, x) => p + ((x['metrics'] as Map)['reduction'] as int));
                return Card(child: ExpansionTile(title: Text('${fmt(entry.key)} haftası • ${items.length} sürüm'),
                  subtitle: Text('Hedef: $good/${items.length} • Net aşım azalması: $net dk'),
                  children: items.map((x) {
                    final v = x['version'] as Map<String, dynamic>, m = x['metrics'] as Map<String, dynamic>;
                    return ListTile(dense: true,
                      leading: Icon(m['compliant'] == true ? Icons.check_circle_outline : Icons.warning_amber_outlined),
                      title: Text(str(v['name'])),
                      subtitle: Text('Önce ${m['before']} dk → sonra ${m['after']} dk • değişen ${m['moved']} • kritik erteleme ${m['criticalDelay']} gün'),
                      trailing: Text('${m['reduction']} dk'));
                  }).toList()));
              })),
              const Divider(),
              Text('Güncel sorumlu kapasite riskleri', style: Theme.of(ctx).textTheme.titleMedium),
              const Text('Bu bölüm mevcut açık görevleri kullanır; geçmiş sürümlerin sonucu değildir.', style: TextStyle(fontSize: 12)),
              if (sortedRisks.isEmpty) const ListTile(title: Text('Kapasite aşımı olan sorumlu-gün bulunamadı.')),
              ...sortedRisks.take(12).map((e) => ListTile(dense: true, leading: const Icon(Icons.person_outline),
                title: Text(e.key), subtitle: Text('${e.value['days']} kapasite aşımı günü'),
                trailing: Text('+${e.value['minutes']} dk'))),
              const Divider(),
              Text('Kural tabanlı iyileştirme önerileri', style: Theme.of(ctx).textTheme.titleMedium),
              ...recommendations.map((r) => ListTile(dense: true, leading: const Icon(Icons.lightbulb_outline), title: Text(r))),
              const SizedBox(height: 12),
              FilledButton.tonalIcon(onPressed: export, icon: const Icon(Icons.copy_all_outlined), label: const Text('CSV raporunu kopyala')),
              OutlinedButton(onPressed: () { Navigator.pop(ctx); _showKitchenPreventiveSuccessDashboard(); },
                child: const Text('Önleyici başarı takibine geç')),
            ])),
          ]))));
      }));
  }

  void _showKitchenPreventiveSuccessDashboard() {
    const versionKey = 'paket40_optimization_plan_versions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalsKey = 'paket39_plan_decision_goals_v1';
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool initialized = false, loading = true, onlyPreventive = true,
        onlyChanged = false, onlyImproved = false;
    int weeks = 8;
    String search = '', sort = 'En yeni';
    DateTime anchor = DateTime.now();
    int overflowGoal = 0, criticalGoal = 0, ownerGoal = 10;
    String txt(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(txt(x));
    DateTime? date(Object? x) { final d = parse(x); return d == null ? null : DateTime(d.year,d.month,d.day); }
    String label(DateTime d) => '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    DateTime monday(DateTime d) { final x = DateTime(d.year,d.month,d.day); return x.subtract(Duration(days:x.weekday-1)); }
    List<Map<String,dynamic>> rows(Object? x) => x is List ? x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList() : <Map<String,dynamic>>[];
    String owner(Map<String,dynamic> a) { final o=txt(a['owner']).trim(); return o.isEmpty?'Atanmamış':o; }
    int duration(Map<String,dynamic> a) { final n=int.tryParse(txt(a['estimatedMinutes'])); return n!=null&&n>=5&&n<=1440?n:30; }
    String csv(Object? x) => '"${txt(x).replaceAll('"','""')}"';
    Map<String,int> load(List<Map<String,dynamic>> tasks) {
      final result=<String,int>{};
      for(final a in tasks) {
        if(['Tamamlandı','İptal'].contains(txt(a['status'])))continue;
        final d=date(a['targetDate']); if(d==null)continue;
        final k='${owner(a)}|${d.year}-${d.month}-${d.day}';
        result[k]=(result[k]??0)+duration(a);
      }
      return result;
    }
    Map<String,int> capacityStats(List<Map<String,dynamic>> tasks) {
      final loads=load(tasks); var excess=0,overloaded=0;
      for(final e in loads.entries) {
        final sep=e.key.indexOf('|'); if(sep<0)continue;
        final cap=capacities[e.key.substring(0,sep)]??120;
        if(e.value>cap){excess+=e.value-cap;overloaded++;}
      }
      return {'excess':excess,'overloaded':overloaded};
    }
    Map<String,dynamic> analyze(Map<String,dynamic> version) {
      final before=rows(version['before']), after=rows(version['after']);
      // Historical versions often store only moved tasks, not full snapshots.
      // Their capacity totals are partial; keep that distinction explicit in UI.
      final b=capacityStats(before), a=capacityStats(after);
      final oldById=<String,Map<String,dynamic>>{};
      for(final row in before){oldById[txt(row['id']??row['title'])]=row;}
      var moved=0,ownerChanges=0,delay=0,criticalDelay=0,unmatched=0;
      for(final row in after){
        final previous=oldById[txt(row['id']??row['title'])];
        if(previous==null){unmatched++;continue;}
        final changedOwner=owner(previous)!=owner(row);
        final d0=date(previous['targetDate']),d1=date(row['targetDate']);
        if(changedOwner)ownerChanges++;
        if(changedOwner||d0!=d1)moved++;
        if(d0!=null&&d1!=null&&d1.isAfter(d0)){
          final n=d1.difference(d0).inDays; delay+=n;
          final priority=txt(row['priority']??row['level']??previous['priority']??previous['level']).toLowerCase();
          if(priority.contains('kritik')||priority.contains('critical'))criticalDelay+=n;
        }
      }
      final reduction=b['excess']!-a['excess']!;
      final pass=a['excess']!<=overflowGoal&&criticalDelay<=criticalGoal&&ownerChanges<=ownerGoal;
      return {'before':b['excess']!,'after':a['excess']!,'reduction':reduction,
        'overBefore':b['overloaded']!,'overAfter':a['overloaded']!,
        'moved':moved,'ownerChanges':ownerChanges,'delay':delay,
        'criticalDelay':criticalDelay,'unmatched':unmatched,'pass':pass,
        'partial':true,'type':txt(version['type']),'note':txt(version['note'])};
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,
      builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
        if(!initialized){
          initialized=true;
          SharedPreferences.getInstance().then((prefs){
            try{
              versions.addAll(rows(jsonDecode(prefs.getString(versionKey)??'[]')));
              final caps=jsonDecode(prefs.getString(capacityKey)??'{}');
              if(caps is Map){for(final e in caps.entries){final n=int.tryParse(txt(e.value));if(n!=null&&n>0)capacities[txt(e.key)]=n;}}
              final goals=jsonDecode(prefs.getString(goalsKey)??'{}');
              if(goals is Map){
                overflowGoal=int.tryParse(txt(goals['overflow']))??0;
                criticalGoal=int.tryParse(txt(goals['criticalDelay']))??0;
                ownerGoal=int.tryParse(txt(goals['ownerChanges']))??10;
              }
            }catch(_){if(mounted)_notice('Optimizasyon geçmişi okunamadı.');}
            if(ctx.mounted)refresh(()=>loading=false);
          }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});
        }
        final start=monday(anchor).subtract(Duration(days:(weeks-1)*7));
        final end=monday(anchor).add(const Duration(days:7));
        final filtered=versions.where((v){
          final at=parse(v['at']);if(at==null||at.isBefore(start)||!at.isBefore(end))return false;
          if(onlyPreventive&&!('${v['name']} ${v['note']}'.toLowerCase().contains('önleyici')||txt(v['type']).toLowerCase().contains('preventive')))return false;
          return '${v['name']} ${v['note']} ${v['type']}'.toLowerCase().contains(search.toLowerCase());
        }).map((v)=><String,dynamic>{'version':v,'result':analyze(v)}).where((e){
          final r=e['result'] as Map<String,dynamic>;
          return (!onlyChanged||(r['moved'] as int)>0)&&(!onlyImproved||(r['reduction'] as int)>0);
        }).toList();
        filtered.sort((x,y){
          final a=x['result'] as Map<String,dynamic>,b=y['result'] as Map<String,dynamic>;
          if(sort=='En çok iyileşme')return (b['reduction'] as int).compareTo(a['reduction'] as int);
          if(sort=='En çok değişiklik')return (b['moved'] as int).compareTo(a['moved'] as int);
          if(sort=='En eski')return txt((x['version'] as Map)['at']).compareTo(txt((y['version'] as Map)['at']));
          return txt((y['version'] as Map)['at']).compareTo(txt((x['version'] as Map)['at']));
        });
        final results=filtered.map((e)=>e['result'] as Map<String,dynamic>).toList();
        final improved=results.where((r)=>(r['reduction'] as int)>0).length;
        final worsened=results.where((r)=>(r['reduction'] as int)<0).length;
        final passed=results.where((r)=>r['pass']==true).length;
        final totalReduction=results.fold<int>(0,(s,r)=>s+(r['reduction'] as int));
        final moves=results.fold<int>(0,(s,r)=>s+(r['moved'] as int));
        final buckets=<Map<String,dynamic>>[];
        for(var i=0;i<weeks;i++){
          final from=start.add(Duration(days:i*7)),to=from.add(const Duration(days:7));
          final list=filtered.where((e){final d=parse((e['version'] as Map)['at']);return d!=null&&!d.isBefore(from)&&d.isBefore(to);}).toList();
          final rs=list.map((e)=>e['result'] as Map<String,dynamic>).toList();
          buckets.add({'from':from,'count':rs.length,'improved':rs.where((r)=>(r['reduction'] as int)>0).length,
            'worsened':rs.where((r)=>(r['reduction'] as int)<0).length,
            'reduction':rs.fold<int>(0,(s,r)=>s+(r['reduction'] as int)),
            'passed':rs.where((r)=>r['pass']==true).length});
        }
        Future<void> export()async{
          final lines=<String>['\uFEFFHafta,Sürüm,Tür,Değişen görev,Önce aşım dk,Sonra aşım dk,Azalma dk,Sorumlu değişimi,Erteleme gün,Hedef uygun'];
          for(final e in filtered){final v=e['version'] as Map<String,dynamic>,r=e['result'] as Map<String,dynamic>;
            lines.add([txt(v['at']),txt(v['name']),txt(v['type']),r['moved'],r['before'],r['after'],r['reduction'],r['ownerChanges'],r['delay'],r['pass']==true?'Evet':'Hayır'].map(csv).join(','));}
          await Clipboard.setData(ClipboardData(text:lines.join('\r\n')));
          if(mounted)_notice('${filtered.length} sürüm CSV olarak kopyalandı.');
        }
        Widget metric(String name,String value)=>Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(value,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:19)),Text(name,textAlign:TextAlign.center)])));
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:Column(children:[
          Padding(padding:const EdgeInsets.fromLTRB(16,12,8,4),child:Row(children:[
            const Expanded(child:Text('Önleyici planlama • başarı ve risk azaltma',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold))),
            IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))])),
          if(loading)const LinearProgressIndicator(),
          Expanded(child:ListView(padding:const EdgeInsets.all(12),children:[
            const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('Bu rapor kayıtlı plan sürümlerini inceler. Birçok sürüm yalnızca değiştirilen görevleri saklar; kapasite aşımı ve iyileşme rakamları bu nedenle TAM PLANIN değil, kayıtlı görevlerin kısmi karşılaştırmasıdır. Haftalık toplamlar gerçek zaman tasarrufu değildir.'))),
            Wrap(spacing:8,runSpacing:6,children:[
              DropdownButton<int>(value:weeks,items:[4,8,12,26].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v){if(v!=null)refresh(()=>weeks=v);}),
              OutlinedButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:weeks*7))),child:const Text('◀ Önceki')),
              OutlinedButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün')),
              OutlinedButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:weeks*7))),child:const Text('Sonraki ▶')),
            ]),
            Text('${label(start)} – ${label(end.subtract(const Duration(days:1)))}'),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sürüm, açıklama veya tür ara'),onChanged:(v)=>refresh(()=>search=v)),
            Wrap(spacing:8,children:[
              FilterChip(label:const Text('Yalnız önleyici'),selected:onlyPreventive,onSelected:(v)=>refresh(()=>onlyPreventive=v)),
              FilterChip(label:const Text('Değişiklik içeren'),selected:onlyChanged,onSelected:(v)=>refresh(()=>onlyChanged=v)),
              FilterChip(label:const Text('İyileşme gösteren'),selected:onlyImproved,onSelected:(v)=>refresh(()=>onlyImproved=v)),
              DropdownButton<String>(value:sort,items:['En yeni','En eski','En çok iyileşme','En çok değişiklik'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)refresh(()=>sort=v);}),
            ]),
            Wrap(spacing:5,children:[metric('İncelenen sürüm','${results.length}'),metric('İyileşen','$improved'),metric('Kötüleşen','$worsened'),metric('Hedefe uygun','$passed'),metric('Kayıtlı görev hareketi','$moves'),metric('Kısmi aşım farkı','$totalReduction dk')]),
            const SizedBox(height:10),const Text('Haftalık dağılım',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
            ...buckets.reversed.map((b){final n=b['count'] as int,ok=b['passed'] as int;
              return Card(child:ExpansionTile(title:Text('${label(b['from'] as DateTime)} • $n sürüm'),subtitle:Text('İyileşen ${b['improved']} · Kötüleşen ${b['worsened']} · Kısmi fark ${b['reduction']} dk'),children:[
                Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                  Text('Hedef uygunluğu: $ok / $n'),LinearProgressIndicator(value:n==0?0:ok/n),
                  if((b['worsened'] as int)>0)const Text('⚠ Bu haftadaki kötüleşen planları inceleyin.'),
                  if(n==0)const Text('Bu haftada kayıtlı sürüm yok.'),
                ]))]));}),
            const SizedBox(height:10),const Text('Sürüm ayrıntıları',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
            if(filtered.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('Bu filtrelerde plan sürümü bulunamadı. Filtreleri kaldırabilir veya yeni optimizasyon uygulayabilirsiniz.'))),
            ...filtered.map((e){final v=e['version'] as Map<String,dynamic>,r=e['result'] as Map<String,dynamic>;
              return Card(child:ExpansionTile(title:Text(txt(v['name'])),subtitle:Text('${v['at']} · ${r['reduction']} dk kısmi fark · ${r['pass']==true?'Hedefe uygun':'Hedef dışı'}'),children:[
                Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                  Text('Tür: ${v['type']}'),Text('Not: ${v['note']}'),
                  Text('Kayıtlı görev: ${r['moved']} değişiklik · ${r['ownerChanges']} sorumlu değişimi'),
                  Text('Erteleme: ${r['delay']} gün · kritik: ${r['criticalDelay']} gün'),
                  Text('Kısmi kapasite aşımı: ${r['before']} → ${r['after']} dk'),
                  if((r['unmatched'] as int)>0)Text('Eşleşmeyen kayıt: ${r['unmatched']}'),
                ]))]));}),
            const SizedBox(height:10),const Text('Kural tabanlı iyileştirme önerileri',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
            if(worsened>0)const ListTile(leading:Icon(Icons.warning_amber_outlined),title:Text('Kötüleşen sürümleri incele'),subtitle:Text('Görevleri taşımadan önce kapasite simülasyonunu karşılaştır.')),
            if(results.isNotEmpty&&passed*2<results.length)const ListTile(leading:Icon(Icons.flag_outlined),title:Text('Hedef eşiklerini ve kapasiteyi gözden geçir'),subtitle:Text('Planların yarısından azı güncel hedeflere uyuyor.')),
            if(results.isNotEmpty&&moves==0)const ListTile(leading:Icon(Icons.info_outline),title:Text('Yeterli değişiklik kaydı yok'),subtitle:Text('Karşılaştırma için kayıtlı optimizasyon hareketi gerekli.')),
            if(results.isEmpty)const ListTile(leading:Icon(Icons.info_outline),title:Text('Henüz analiz verisi yok'),subtitle:Text('Önleyici senaryoyu onaylayıp kaydettikten sonra sonuçlar burada görünür.')),
            Wrap(spacing:8,runSpacing:8,children:[
              FilledButton.tonalIcon(onPressed:export,icon:const Icon(Icons.copy),label:const Text('CSV kopyala')),
              OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveDecisionCenter();},child:const Text('Önleyici senaryolar')),
              OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenWeeklyOptimizationTrends();},child:const Text('Haftalık trendler')),
              OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationVersions();},child:const Text('Plan sürümleri')),
            ]),
          ])),
        ])));
      }));
  }

  void _showKitchenPreventiveDecisionCenter() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, weekends = false, onlyRisk = true, busy = false;
    int horizon = 14, maxMoves = 15, threshold = 80;
    String ownerFilter = 'Tümü', query = '', selected = 'Karma';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? day(Object? v) { final d = DateTime.tryParse(str(v)); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map<String,dynamic> a) { final v = str(a['owner']).trim(); return v.isEmpty ? 'Atanmamış' : v; }
    int mins(Map<String,dynamic> a) { final n = int.tryParse(str(a['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool active(Map<String,dynamic> a) => !['Tamamlandı','İptal'].contains(str(a['status']));
    bool critical(Map<String,dynamic> a) { final v = str(a['priority'] ?? a['level']).toLowerCase(); return v.contains('kritik') || v.contains('yüksek') || v.contains('critical'); }
    String csv(Object? v) => '"${str(v).replaceAll('"','""')}"';
    String id(Map<String,dynamic> a) => '${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
            if (raw is List) actions.addAll(raw.whereType<Map>().map((e) => Map<String,dynamic>.from(e)));
            final rawCap = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (rawCap is Map) { for (final e in rawCap.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 15 && n <= 1440) capacities[str(e.key)] = n; } }
          } catch (_) { if (ctx.mounted) _notice('Görev veya kapasite verileri okunamadı.'); }
          if (ctx.mounted) refresh(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
      }
      final start = DateTime(anchor.year,anchor.month,anchor.day), end = start.add(Duration(days:horizon));
      final today = day(DateTime.now())!;
      final live = actions.where(active).toList();
      final owners = <String>{'Tümü',...live.map(who)}.toList()..sort();
      final eligibleOwners = owners.where((o) => o != 'Tümü' && o != 'Atanmamış').toList();
      String slot(String person,DateTime d) => '$person|${iso(d)}';
      final baseline = <String,int>{};
      for (final a in live) { final d = day(a['targetDate']); if (d != null) { final k = slot(who(a),d); baseline[k] = (baseline[k]??0)+mins(a); } }
      int excess(Map<String,int> loads) { var sum=0; for (final e in loads.entries) { final sep=e.key.lastIndexOf('|'); if (sep<0) continue; final d=day(e.key.substring(sep+1)); if (d==null||d.isBefore(start)||!d.isBefore(end)) continue; final owner=e.key.substring(0,sep); if (ownerFilter!='Tümü'&&ownerFilter!=owner) continue; final diff=e.value-(capacities[owner]??120); if (diff>0) sum+=diff; } return sum; }
      int overloadDays(Map<String,int> loads) { var sum=0; for(final e in loads.entries) { final sep=e.key.lastIndexOf('|'); if(sep<0)continue; final d=day(e.key.substring(sep+1)); final owner=e.key.substring(0,sep); if(d!=null&&!d.isBefore(start)&&d.isBefore(end)&&(ownerFilter=='Tümü'||ownerFilter==owner)&&e.value>(capacities[owner]??120))sum++; }return sum; }
      final candidates = live.where((a) { final d=day(a['targetDate']); if(d==null||d.isBefore(start)||!d.isBefore(end)||d.isBefore(today))return false; if(ownerFilter!='Tümü'&&who(a)!=ownerFilter)return false; if(critical(a))return false; if(query.isNotEmpty&&!('${a['title']} ${a['owner']} ${a['note']}'.toLowerCase().contains(query.toLowerCase())))return false; return true; }).toList()..sort((a,b) { final da=day(a['targetDate'])!,db=day(b['targetDate'])!; final la=(baseline[slot(who(a),da)]??0)-(capacities[who(a)]??120),lb=(baseline[slot(who(b),db)]??0)-(capacities[who(b)]??120); final c=lb.compareTo(la);return c!=0?c:da.compareTo(db); });
      Map<String,dynamic> scenario(String mode) {
        final loads=Map<String,int>.from(baseline),moves=<Map<String,dynamic>>[];
        for(final a in candidates) {
          if(moves.length>=maxMoves)break;
          final from=day(a['targetDate'])!,person=who(a),m=mins(a),old=slot(person,from),cap=capacities[person]??120;
          final current=loads[old]??0;
          if(onlyRisk&&current<=cap&&current*100<cap*threshold)continue;
          final options=<Map<String,dynamic>>[];
          final people=mode=='Tarih'?<String>[person]:mode=='Sorumlu'?eligibleOwners:eligibleOwners;
          for(final p in people) {
            if(p=='Atanmamış')continue;
            for(var shift=0;shift<=7;shift++) {
              if(mode=='Sorumlu'&&shift!=0)continue;
              if(mode=='Tarih'&&shift==0)continue;
              if(mode=='Karma'&&shift==0&&p==person)continue;
              final d=from.add(Duration(days:shift));
              if(d.isBefore(today)||!d.isBefore(end)||(!weekends&&d.weekday>=6))continue;
              final k=slot(p,d),available=(capacities[p]??120)-(loads[k]??0)-m;
              if(available<0)continue;
              final delay=shift,changed=p!=person;
              final penalty=delay*(mode=='Karma'?5:3)+(changed?8:0)+(loads[k]??0)/100;
              options.add({'owner':p,'date':d,'key':k,'penalty':penalty,'delay':delay,'changed':changed});
            }
          }
          options.sort((x,y)=>(x['penalty'] as num).compareTo(y['penalty'] as num));
          if(options.isEmpty)continue;
          final best=options.first;
          loads[old]=current-m;
          final newKey=best['key'] as String;
          loads[newKey]=(loads[newKey]??0)+m;
          moves.add({'action':a,'id':id(a),'title':str(a['title']),'from':from,'oldOwner':person,'owner':best['owner'],'date':best['date'],'minutes':m,'delay':best['delay'],'changed':best['changed']});
        }
        final before=excess(baseline),after=excess(loads),delays=moves.fold<int>(0,(n,v)=>n+(v['delay'] as int)),changes=moves.where((v)=>v['changed']==true).length;
        final improvement=before-after;
        final score=(50+(before==0?0:improvement/before*50)-delays*2-changes*3).clamp(0,100).round();
        return {'mode':mode,'moves':moves,'loads':loads,'before':before,'after':after,'beforeDays':overloadDays(baseline),'afterDays':overloadDays(loads),'delay':delays,'changes':changes,'score':score};
      }
      final scenarios=<String,Map<String,dynamic>>{for(final mode in ['Tarih','Sorumlu','Karma'])mode:scenario(mode)};
      final current=scenarios[selected]!;
      final moves=current['moves'] as List<Map<String,dynamic>>;
      final best=scenarios.values.toList()..sort((a,b) {final c=(a['after'] as int).compareTo(b['after'] as int);return c!=0?c:(b['score'] as int).compareTo(a['score'] as int);});
      Future<void> apply() async {
        if(busy||moves.isEmpty)return;
        final chosen=<int>{for(var i=0;i<moves.length;i++)i};
        final picked=await showDialog<List<int>>(context:ctx,builder:(dialog)=>StatefulBuilder(builder:(d,setD)=>AlertDialog(title:Text('$selected senaryosu • görev seçimi'),content:SizedBox(width:520,height:410,child:ListView(children:[const Text('Seçili görevler kaydedilmeden önce tekrar doğrulanır.'),...List.generate(moves.length,(i){final m=moves[i];return CheckboxListTile(value:chosen.contains(i),onChanged:(v)=>setD((){if(v==true){chosen.add(i);}else{chosen.remove(i);}}),title:Text(str(m['title'])),subtitle:Text('${m['oldOwner']} ${iso(m['from'] as DateTime)} → ${m['owner']} ${iso(m['date'] as DateTime)} • ${m['minutes']} dk'));})])),actions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('Vazgeç')),FilledButton(onPressed:chosen.isEmpty?null:()=>Navigator.pop(dialog,chosen.toList()..sort()),child:Text('${chosen.length} görevi seç'))])));
        if(picked==null||picked.isEmpty||!ctx.mounted)return;
        final confirmation=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Önleyici planı uygula'),content:Text('${picked.length} açık görevin tarihi ve/veya sorumlusu değiştirilecek. İşlem öncesi ve sonrası plan sürümü kaydedilecek. Onaylıyor musun?'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('İptal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla'))]));
        if(confirmation!=true||!ctx.mounted)return;
        refresh(()=>busy=true);
        try {
          final prefs=await SharedPreferences.getInstance();
          final fresh=jsonDecode(prefs.getString(actionKey)??'[]');
          if(fresh is! List)throw StateError('Görev listesi okunamadı');
          final latest=fresh.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
          final before=<Map<String,dynamic>>[],after=<Map<String,dynamic>>[];
          final stamp=DateTime.now().toIso8601String();
          for(final i in picked) {
            final m=moves[i],identity=str(m['id']);
            final matches=latest.where((a)=>id(a)==identity).toList();
            if(matches.length!=1)throw StateError('Görev kimliği eşleşmedi: ${m['title']}');
            final a=matches.single;
            if(!active(a)||who(a)!=m['oldOwner']||day(a['targetDate'])!=m['from'])throw StateError('Görev değişmiş: ${m['title']}');
            before.add({'id':identity,'title':a['title'],'owner':a['owner'],'targetDate':a['targetDate']});
            a['owner']=m['owner'];a['targetDate']=iso(m['date'] as DateTime);a['updated']=stamp;
            final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];
            h.add({'at':stamp,'event':'Önleyici plan ($selected): ${m['oldOwner']} ${iso(m['from'] as DateTime)} → ${m['owner']} ${a['targetDate']}'});
            a['history']=h;
            after.add({'id':identity,'title':a['title'],'owner':a['owner'],'targetDate':a['targetDate']});
          }
          final oldActions=prefs.getString(actionKey);
          final oldVersions=prefs.getString(versionsKey);
          final parsedVersions=jsonDecode(oldVersions??'[]');
          final versions=parsedVersions is List?parsedVersions.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():<Map<String,dynamic>>[];
          versions.insert(0,{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':'Önleyici risk azaltma • $selected','at':stamp,'type':'optimization','note':'${picked.length} görev • onaylı risk azaltma senaryosu','before':before,'after':after});
          try {
            final ok1=await prefs.setString(actionKey,jsonEncode(latest));
            if(!ok1)throw StateError('Görevler kaydedilemedi');
            final ok2=await prefs.setString(versionsKey,jsonEncode(versions.take(100).toList()));
            if(!ok2)throw StateError('Plan sürümü kaydedilemedi');
          }catch(_) {
            if(oldActions==null){await prefs.remove(actionKey);}else{await prefs.setString(actionKey,oldActions);}
            if(oldVersions==null){await prefs.remove(versionsKey);}else{await prefs.setString(versionsKey,oldVersions);}
            rethrow;
          }
          if(ctx.mounted)refresh(() {actions..clear()..addAll(latest);busy=false;});
          if(mounted)_notice('${picked.length} görev kaydedildi; plan sürümü oluşturuldu.');
        }catch(e){if(ctx.mounted)refresh(()=>busy=false);if(mounted)_notice('Plan uygulanamadı: $e');}
      }
      final lines=<String>['Senaryo;Görev;Önceki sorumlu;Önceki tarih;Yeni sorumlu;Yeni tarih;Dakika;Erteleme gün'];
      for(final m in moves){ lines.add([selected,m['title'],m['oldOwner'],iso(m['from'] as DateTime),m['owner'],iso(m['date'] as DateTime),m['minutes'],m['delay']].map(csv).join(';')); }
      Widget metric(String label,String value)=>Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(children:[Text(label,style:const TextStyle(fontSize:12)),Text(value,style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold))])));
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Önleyici senaryolar / risk azaltma karar merkezi',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Üç kural tabanlı senaryo karşılaştırılır. Gerçek müsaitlik veya görev yetkinliği doğrulanmaz; değişiklikler yalnızca onayla uygulanır.'),
        if(loading)const LinearProgressIndicator()else ...[
          Wrap(spacing:10,runSpacing:8,children:[DropdownButton<int>(value:horizon,items:[7,14,21,28].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>horizon=v??14)),DropdownButton<int>(value:threshold,items:[70,80,90,100].map((v)=>DropdownMenuItem(value:v,child:Text('Risk eşiği %$v'))).toList(),onChanged:(v)=>refresh(()=>threshold=v??80)),DropdownButton<int>(value:maxMoves,items:[5,10,15,25,40].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v görev'))).toList(),onChanged:(v)=>refresh(()=>maxMoves=v??15)),DropdownButton<String>(value:owners.contains(ownerFilter)?ownerFilter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü'))]),
          Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:horizon))),child:const Text('← Önceki')),OutlinedButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün')),OutlinedButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:horizon))),child:const Text('Sonraki →'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev / sorumlu / not ara'),onChanged:(v)=>refresh(()=>query=v)),
          SwitchListTile(title:const Text('Yalnızca riskli günlerin görevleri'),value:onlyRisk,onChanged:(v)=>refresh(()=>onlyRisk=v)),
          SwitchListTile(title:const Text('Hafta sonlarına öneri oluştur'),value:weekends,onChanged:(v)=>refresh(()=>weekends=v)),
          Text('Üç senaryo karşılaştırması',style:Theme.of(ctx).textTheme.titleMedium),
          ...scenarios.entries.map((e){final v=e.value;return Card(child:RadioGroup<String>(groupValue:selected,onChanged:(s)=>refresh(()=>selected=s??'Karma'),child:RadioListTile<String>(value:e.key,title:Text('${e.key} • ${(v['score'] as int)}/100 puan'),subtitle:Text('Kapasite aşımı: ${v['before']} → ${v['after']} dk • ${v['beforeDays']} → ${v['afterDays']} riskli gün\n${(v['moves'] as List).length} öneri • ${v['delay']} gün erteleme • ${v['changes']} sorumlu değişimi'))));}),
          Card(color:const Color(0xFFFFF7FC),child:ListTile(leading:const Icon(Icons.emoji_events_outlined,color:_purple),title:Text('Önerilen senaryo: ${best.first['mode']}'),subtitle:const Text('Öncelik: daha düşük kapasite aşımı, eşitlikte daha yüksek puan. Puanlar sezgiseldir.'))),
          Wrap(spacing:5,runSpacing:5,children:[metric('Önce','${current['before']} dk'),metric('Sonra','${current['after']} dk'),metric('Riskli gün','${current['afterDays']}'),metric('Öneri','${moves.length}')]),
          Text('$selected senaryosu • önerilen görevler',style:Theme.of(ctx).textTheme.titleMedium),
          if(moves.isEmpty)const ListTile(title:Text('Bu dönemde uygulanabilir alternatif bulunamadı.')),
          ...moves.take(50).map((m)=>Card(child:ListTile(leading:const Icon(Icons.swap_horiz_outlined),title:Text(str(m['title'])),subtitle:Text('${m['oldOwner']} • ${iso(m['from'] as DateTime)} → ${m['owner']} • ${iso(m['date'] as DateTime)}\n${m['minutes']} dk • ${m['delay']} gün erteleme')))),
          FilledButton.icon(onPressed:busy||moves.isEmpty?null:apply,icon:const Icon(Icons.verified_user_outlined),label:Text(busy?'Kaydediliyor...':'Seçili senaryoyu önizle ve onayla')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));if(ctx.mounted)_notice('Senaryo CSV raporu kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Senaryo CSV raporunu kopyala')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveRiskPlanner();},child:const Text('Haftalık risk haritasına geç')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationVersions();},child:const Text('Plan sürümlerine geç')),
        ]
      ]))));
    }));
  }




  // Kapasiteye göre normalize edilmiş görev dağılımı adaleti (salt okunur).

  // Haftalık adalet hedefleri: mevcut görev planı ile geçmiş tam plan görüntüleri.
  // Salt okunur; tarihsel hedefler eski sürümlerde saklanmadığı için güncel hedeflerle değerlendirilir.

  // Gelecek haftalar için kapasiteye normalize edilmiş adalet riski.
  // Salt okunur: yeni görevlerin gelecekte oluşacağını tahmin etmez.

  // Gelecek haftalar için adalet + günlük kapasite hedefli önleyici dengeleme.
  // Öneriler yalnızca önizlemedir; kayıtlı görevleri değiştirmez.


  // Tekrarlayan adalet risklerini mevcut plan ve kayıtlı optimizasyon geçmişiyle
  // birleştiren salt okunur önleyici aksiyon merkezi.

  // Haftalık aksiyon kapasitesi için seçmeli ve onaylı optimizasyon.
  // Genel görev kayıtlarına dokunmaz; yalnızca aksiyon tarih/sorumlu alanları güncellenir.
  void _showKitchenApprovedActionCapacityOptimizer() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    final actions = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    final selected = <String>{};
    bool started = false, loading = true, saving = false, weekdaysOnly = true;
    int weeks = 4, dailyBudget = 45, maxMoves = 10, strategy = 2;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü';
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year,d.month,d.day).subtract(Duration(days:d.weekday-1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? x) => '"${str(x).replaceAll('"','""')}"';
    bool isOpen(Map<String,dynamic> a) => !['Tamamlandı','İptal'].contains(str(a['status']));
    int duration(Map<String,dynamic> a) => (estimates[str(a['id'])] ?? int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5,480).toInt();
    bool protected(Map<String,dynamic> a) => ['kritik','critical','yüksek','high'].contains(str(a['priority']).toLowerCase().trim());
    showModalBottomSheet<void>(context:context,isScrollControlled:true,showDragHandle:true,
      builder:(sheet)=>StatefulBuilder(builder:(sheet,update) {
        if (!started) {
          started=true;
          Future<void>.microtask(() async {
            try {
              final p=await SharedPreferences.getInstance();
              final raw=jsonDecode(p.getString(actionKey)??'[]');
              final saved=jsonDecode(p.getString(estimateKey)??'{}');
              if (!sheet.mounted) return;
              update(() {
                if(raw is List) for(final x in raw) {if(x is Map) actions.add(Map<String,dynamic>.from(x));}
                if(saved is Map) { for(final e in saved.entries) {
                  final v=int.tryParse(str(e.value));
                  if(v!=null && v>=5 && v<=480) estimates[str(e.key)]=v;
                } }
                loading=false;
              });
            } catch(e) {
              if(sheet.mounted) update(()=>loading=false);
              if(mounted) _notice('Aksiyon planı okunamadı: $e');
            }
          });
        }
        final start=monday(anchor), end=start.add(Duration(days:weeks*7));
        final people=<String>{...actions.map((a)=>str(a['owner']).trim()).where((v)=>v.isNotEmpty)}.toList()..sort();
        final allOwners=['Tümü',...people];
        final budget=dailyBudget*(weekdaysOnly?5:7);
        final eligible=<Map<String,dynamic>>[];
        var invalid=0,protectedCount=0;
        for(final a in actions) {
          if(!isOpen(a)) continue;
          final d=parse(a['due']);
          if(d==null || str(a['owner']).trim().isEmpty || str(a['id']).trim().isEmpty) {invalid++;continue;}
          if(d.isBefore(start)||!d.isBefore(end)) continue;
          if(protected(a)) {protectedCount++;continue;}
          eligible.add(a);
        }
        Map<String,int> loads(List<Map<String,dynamic>> data) {
          final m=<String,int>{};
          for(final a in data) {
            if(!isOpen(a)) continue;
            final d=parse(a['due']); final o=str(a['owner']).trim();
            if(d==null||o.isEmpty||d.isBefore(start)||!d.isBefore(end)) continue;
            final k='$o|${iso(monday(d))}';
            m[k]=(m[k]??0)+duration(a);
          }
          return m;
        }
        int excess(Map<String,int> m) => m.values.fold<int>(0,(s,v)=>s+(v>budget?v-budget:0));
        final base=loads(actions);
        final working=<String,int>{...base};
        final proposals=<Map<String,dynamic>>[];
        final sorted=[...eligible]..sort((a,b)=>duration(b).compareTo(duration(a)));
        for(final a in sorted) {
          if(proposals.length>=maxMoves) break;
          final oldOwner=str(a['owner']).trim();
          final oldDate=parse(a['due'])!;
          final oldWeek=monday(oldDate);
          final oldKey='$oldOwner|${iso(oldWeek)}';
          final mins=duration(a);
          if((working[oldKey]??0)<=budget) continue;
          String? bestOwner; DateTime? bestDate; var bestGain=0;
          final currentOver=excess(working);
          for(var wi=0;wi<weeks;wi++) {
            final candidateWeek=start.add(Duration(days:wi*7));
            for(final person in people) {
              if(strategy==0 && person!=oldOwner) continue;
              if(strategy==1 && candidateWeek!=oldWeek) continue;
              if(person==oldOwner && candidateWeek==oldWeek) continue;
              final key='$person|${iso(candidateWeek)}';
              final trial=<String,int>{...working};
              trial[oldKey]=(trial[oldKey]??0)-mins;
              trial[key]=(trial[key]??0)+mins;
              final gain=currentOver-excess(trial);
              if(gain>bestGain) {
                bestGain=gain;bestOwner=person;
                final weekday=oldDate.weekday;
                bestDate=candidateWeek.add(Duration(days:weekday-1));
              }
            }
          }
          if(bestOwner==null||bestDate==null||bestGain<=0) continue;
          final newKey='$bestOwner|${iso(monday(bestDate))}';
          working[oldKey]=(working[oldKey]??0)-mins;
          working[newKey]=(working[newKey]??0)+mins;
          proposals.add(<String,dynamic>{'id':str(a['id']),'title':str(a['title']),
            'oldOwner':oldOwner,'newOwner':bestOwner,'oldDate':str(a['due']),
            'newDate':iso(bestDate),'minutes':mins,'gain':bestGain});
        }
        final validIds=proposals.map((p)=>str(p['id'])).toSet();
        selected.removeWhere((id)=>!validIds.contains(id));
        final chosen=proposals.where((p)=>selected.contains(str(p['id']))).toList();
        final preview=<String,int>{...base};
        for(final p in chosen) {
          final oldKey='${p['oldOwner']}|${iso(monday(parse(p['oldDate'])!))}';
          final newKey='${p['newOwner']}|${iso(monday(parse(p['newDate'])!))}';
          final m=p['minutes'] as int;
          preview[oldKey]=(preview[oldKey]??0)-m;
          preview[newKey]=(preview[newKey]??0)+m;
        }
        final before=excess(base), after=excess(preview);
        Future<void> export() async {
          final lines=<String>['Secili;Aksiyon;Eski sorumlu;Yeni sorumlu;Eski tarih;Yeni tarih;Dakika;Tahmini kazanc'];
          for(final p in proposals) {
            lines.add([selected.contains(str(p['id']))?'Evet':'Hayır',p['title'],p['oldOwner'],p['newOwner'],p['oldDate'],p['newDate'],p['minutes'],p['gain']].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text:lines.join('\n')));
          if(mounted) _notice('Aksiyon kapasitesi önerileri kopyalandı.');
        }
        Future<void> apply() async {
          if(saving||chosen.isEmpty) return;
          final approved=await showDialog<bool>(context:sheet,builder:(d)=>AlertDialog(
            title:const Text('Aksiyon planını güncelle?'),
            content:Text('${chosen.length} aksiyonun tarihi veya sorumlusu değişecek. Tahmini haftalık kapasite aşımı $before dk → $after dk. Kritik/yüksek öncelikli aksiyonlar korunur.'),
            actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla ve uygula'))]));
          if(approved!=true||!sheet.mounted) return;
          update(()=>saving=true);
          try {
            final p=await SharedPreferences.getInstance();
            final raw=p.getString(actionKey)??'[]';
            final decoded=jsonDecode(raw);
            if(decoded is! List) throw StateError('Aksiyon listesi geçersiz');
            final current=<Map<String,dynamic>>[];
            for(final x in decoded) {if(x is Map) current.add(Map<String,dynamic>.from(x));}
            final currentIds=<String>{};
            for(final change in chosen) {
              final id=str(change['id']);
              final matches=current.where((a)=>str(a['id'])==id).toList();
              if(matches.length!=1||!currentIds.add(id)) throw StateError('Aksiyon bulunamadı veya kimliği tekrar ediyor: $id');
              final a=matches.single;
              if(!isOpen(a)||protected(a)||str(a['owner'])!=change['oldOwner']||str(a['due'])!=change['oldDate']) {
                throw StateError('Aksiyon kaydı değişmiş: ${change['title']}. Planı yeniden açın.');
              }
            }
            final previous=jsonEncode(current);
            for(final change in chosen) {
              final a=current.firstWhere((a)=>str(a['id'])==str(change['id']));
              a['owner']=change['newOwner'];a['due']=change['newDate'];
            }
            final historyRaw=jsonDecode(p.getString(historyKey)??'[]');
            final history=<dynamic>[if(historyRaw is List)...historyRaw];
            history.add(<String,dynamic>{'at':DateTime.now().toIso8601String(),
              'strategy':['Tarih','Sorumlu','Karma'][strategy],
              'beforeExcessMinutes':before,'afterExcessMinutes':after,
              'dailyActionBudget':dailyBudget,'weekdaysOnly':weekdaysOnly,
              'changes':chosen.map((x)=>Map<String,dynamic>.from(x)).toList(),
              'previousPlan':previous});
            // Önce geçmişi kaydet; aksiyon yazımı başarısız olursa eski geçmişi geri yükle.
            final oldHistory=p.getString(historyKey);
            if(!await p.setString(historyKey,jsonEncode(history))) throw StateError('Geçmiş yazılamadı');
            if(!await p.setString(actionKey,jsonEncode(current))) {
              if(oldHistory==null) {await p.remove(historyKey);} else {await p.setString(historyKey,oldHistory);}
              throw StateError('Aksiyon planı yazılamadı');
            }
            if(sheet.mounted) {
              update(() {
              actions..clear()..addAll(current);
              selected.clear();saving=false;
            });
            }
            if(mounted) _notice('${chosen.length} aksiyon onayla güncellendi.');
          } catch(e) {
            if(sheet.mounted) update(()=>saving=false);
            if(mounted) _notice('Değişiklikler uygulanamadı: $e');
          }
        }
        return SafeArea(child:SizedBox(height:MediaQuery.of(sheet).size.height*.91,
          child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Onaylı haftalık aksiyon kapasite optimizasyonu',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),
            const SizedBox(height:8),
            const Text('Aşırı dolu haftalardan daha uygun haftalara veya sorumlulara aksiyon taşıma önerileri. Seçmeden ve onaylamadan kayıtlar değişmez.'),
            if(loading) const LinearProgressIndicator() else ...[
              Wrap(spacing:8,runSpacing:8,children:[
                DropdownButton<int>(value:weeks,items:[1,2,4,8,12].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>update((){weeks=v??4;selected.clear();})),
                DropdownButton<int>(value:dailyBudget,items:[15,30,45,60,90,120,180].map((v)=>DropdownMenuItem(value:v,child:Text('$v dk/gün'))).toList(),onChanged:(v)=>update((){dailyBudget=v??45;selected.clear();})),
                DropdownButton<int>(value:strategy,items:const [DropdownMenuItem(value:0,child:Text('Yalnızca tarih')),DropdownMenuItem(value:1,child:Text('Yalnızca sorumlu')),DropdownMenuItem(value:2,child:Text('Karma'))],onChanged:(v)=>update((){strategy=v??2;selected.clear();})),
                DropdownButton<int>(value:maxMoves,items:[5,10,20,40].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v'))).toList(),onChanged:(v)=>update((){maxMoves=v??10;selected.clear();})),
                DropdownButton<String>(value:allOwners.contains(ownerFilter)?ownerFilter:'Tümü',items:allOwners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>ownerFilter=v??'Tümü')),
                OutlinedButton(onPressed:()=>update((){anchor=anchor.subtract(Duration(days:weeks*7));selected.clear();}),child:const Text('Önceki')),
                OutlinedButton(onPressed:()=>update((){anchor=DateTime.now();selected.clear();}),child:const Text('Bugün')),
                OutlinedButton(onPressed:()=>update((){anchor=anchor.add(Duration(days:weeks*7));selected.clear();}),child:const Text('Sonraki')),
              ]),
              SwitchListTile(title:const Text('Yalnızca hafta içi kapasitesi'),value:weekdaysOnly,onChanged:(v)=>update((){weekdaysOnly=v;selected.clear();})),
              Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))} • $budget dk/hafta/sorumlu'),
              Text('Mevcut aşım: $before dk • Seçim sonrası: $after dk • Tahmini azalma: ${before-after} dk'),
              Text('${proposals.length} öneri • ${chosen.length} seçili • $protectedCount korunan yüksek/kritik aksiyon • $invalid eksik kayıt'),
              Wrap(spacing:8,children:[
                OutlinedButton(onPressed:()=>update(()=>selected.addAll(proposals.where((p)=>ownerFilter=='Tümü'||p['oldOwner']==ownerFilter).map((p)=>str(p['id'])))),child:const Text('Görünenleri seç')),
                OutlinedButton(onPressed:()=>update(()=>selected.clear()),child:const Text('Seçimi temizle')),
                OutlinedButton.icon(onPressed:export,icon:const Icon(Icons.copy_outlined),label:const Text('CSV kopyala')),
              ]),
              if(proposals.isEmpty) const Padding(padding:EdgeInsets.all(16),child:Text('Kapasite aşımını azaltan uygun öneri bulunamadı.')),
              ...proposals.where((p)=>ownerFilter=='Tümü'||p['oldOwner']==ownerFilter).map((p)=>CheckboxListTile(
                value:selected.contains(str(p['id'])),onChanged:(v)=>update((){if(v==true){selected.add(str(p['id']));}else{selected.remove(str(p['id']));}}),
                title:Text(str(p['title']).isEmpty?'Başlıksız aksiyon':str(p['title'])),
                subtitle:Text('${p['oldOwner']} / ${p['oldDate']} → ${p['newOwner']} / ${p['newDate']} • ${p['minutes']} dk • ~${p['gain']} dk aşım azalması'),
              )),
              const SizedBox(height:8),
              FilledButton.icon(onPressed:saving||chosen.isEmpty?null:apply,icon:const Icon(Icons.verified_outlined),label:Text(saving?'Kaydediliyor...':'Seçilen ${chosen.length} aksiyonu onayla ve uygula')),
              const SizedBox(height:12),
              const Text('Sınırlar: Aksiyon kapasitesi genel görev kapasitesinden ayrıdır. Eksik süre 30 dk kabul edilir. Yetkinlik ve gerçek müsaitlik doğrulanmaz. Yalnızca haftalık toplam aşım en aza indirilir; günlük yoğunluk veya aksiyonun zorunlu bitiş tarihi ayrıca doğrulanmalıdır.'),
              TextButton(onPressed:(){Navigator.pop(sheet);_showKitchenWeeklyActionCapacity();},child:const Text('Haftalık kapasite analizine dön')),
            ],
          ])));
      }));
  }


  // Onaylanmış aksiyon optimizasyonlarının işlem bazlı başarı karnesi.
  // Geçmişte saklanan previousPlan ve changes ile önce/sonra karşılaştırılır.
  // Riskli aksiyon haftaları için önleyici öneri, seçmeli onay ve izlenebilir kayıt.

  // Aşama 35698–36097: Onaylanan önleyici kapasite işlemlerinin sonuç karnesi.

  // Aşama 36098–36497: Onaylı önleyici aksiyonların uzun dönem eğilimleri.
  // İşlem anı görüntülerini analiz eder; gerçek kapasite tasarrufu iddiası içermez.

  // Aşama 36498–36897: Kalıcı aksiyon kapasite riskleri için
  // salt-okunur önleyici yeniden planlama senaryoları.


  // Büyük paket 36898–41897: birleşik kapasite kontrol ve karar denetimi.
  // Salt okunur: onaylanmamış değişiklikler görevleri güncellemez.
  void _showKitchenCapacityCommandDashboard() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    const auditKey = 'paket45_risk_reduction_approvals_v1';
    final actions = <Map<String, dynamic>>[];
    final audits = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    bool started = false, loading = true;
    int weeks = 12, threshold = 3, weeklyOffset = 0, dailyCapacity = 45;
    String ownerFilter = 'Tümü', riskFilter = 'Tümü', search = '';
    String str(Object? value) => value?.toString() ?? '';
    String csv(Object? value) => '"${str(value).replaceAll('"', '""')}"';
    DateTime? parse(Object? value) => DateTime.tryParse(str(value));
    DateTime monday(DateTime value) =>
        DateTime(value.year, value.month, value.day)
            .subtract(Duration(days: value.weekday - 1));
    String iso(DateTime value) =>
        '${value.year}-${value.month.toString().padLeft(2, '0')}-${value.day.toString().padLeft(2, '0')}';
    bool active(Map<String, dynamic> action) =>
        !['Tamamlandı', 'İptal'].contains(str(action['status']));
    int minutes(Map<String, dynamic> action) =>
        (estimates[str(action['id'])] ??
            int.tryParse(str(action['estimatedMinutes'])) ?? 30)
            .clamp(5, 480).toInt();

    showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final a = jsonDecode(prefs.getString(actionKey) ?? '[]');
              final e = jsonDecode(prefs.getString(estimateKey) ?? '{}');
              final h = jsonDecode(prefs.getString(auditKey) ?? '[]');
              if (!sheet.mounted) return;
              refresh(() {
                if (a is List) {
                  actions.addAll(a.whereType<Map>()
                      .map((v) => Map<String, dynamic>.from(v)));
                }
                if (e is Map) {
                  for (final entry in e.entries) {
                    final n = int.tryParse(str(entry.value));
                    if (n != null && n >= 5 && n <= 480) {
                      estimates[str(entry.key)] = n;
                    }
                  }
                }
                if (h is List) {
                  audits.addAll(h.whereType<Map>()
                      .map((v) => Map<String, dynamic>.from(v)));
                }
                loading = false;
              });
            } catch (_) {
              if (sheet.mounted) refresh(() => loading = false);
              if (mounted) _notice('Kapasite kontrol verileri okunamadı.');
            }
          });
        }

        final anchor = monday(DateTime.now())
            .add(Duration(days: weeklyOffset * 7));
        final first = anchor.subtract(Duration(days: (weeks - 1) * 7));
        final owners = actions.map((a) => str(a['owner']).trim())
            .where((v) => v.isNotEmpty).toSet().toList()..sort();
        if (ownerFilter != 'Tümü' && !owners.contains(ownerFilter)) {
          ownerFilter = 'Tümü';
        }
        final selected = actions.where((a) =>
            active(a) &&
            (ownerFilter == 'Tümü' || str(a['owner']) == ownerFilter) &&
            (search.isEmpty ||
                '${a['title']} ${a['owner']} ${a['priority']}'
                    .toLowerCase().contains(search.toLowerCase()))).toList();

        // Her sorumlu/hafta çifti tek gözlemdir. Tekrarlanan görevler
        // farklı haftalarda bulunmadıkça ayrı risk haftası sayılmaz.
        final loads = <String, Map<String, int>>{};
        final counts = <String, Map<String, int>>{};
        for (final a in selected) {
          final due = parse(a['due']);
          if (due == null) continue;
          final week = monday(due);
          if (week.isBefore(first) || week.isAfter(anchor)) continue;
          final owner = str(a['owner']).trim().isEmpty
              ? 'Atanmamış' : str(a['owner']).trim();
          final key = iso(week);
          loads.putIfAbsent(owner, () => <String, int>{});
          counts.putIfAbsent(owner, () => <String, int>{});
          loads[owner]![key] = (loads[owner]![key] ?? 0) + minutes(a);
          counts[owner]![key] = (counts[owner]![key] ?? 0) + 1;
        }
        final budget = dailyCapacity * 5;
        final summary = <Map<String, dynamic>>[];
        for (final entry in loads.entries) {
          final weeksWithRisk = entry.value.values.where((v) => v > budget).length;
          final excess = entry.value.values.fold<int>(0, (sum, value) =>
              sum + (value > budget ? value - budget : 0));
          final total = entry.value.values.fold<int>(0, (sum, v) => sum + v);
          final totalTasks = counts[entry.key]!.values.fold<int>(
              0, (sum, value) => sum + value);
          summary.add(<String, dynamic>{
            'owner': entry.key, 'riskWeeks': weeksWithRisk,
            'excess': excess, 'total': total, 'tasks': totalTasks,
            'weeksObserved': entry.value.length,
          });
        }
        summary.sort((a, b) {
          final risk = (b['riskWeeks'] as int).compareTo(a['riskWeeks'] as int);
          return risk != 0 ? risk :
              (b['excess'] as int).compareTo(a['excess'] as int);
        });
        final filtered = summary.where((r) {
          final risk = r['riskWeeks'] as int;
          if (riskFilter == 'Kalıcı') return risk >= threshold;
          if (riskFilter == 'Riskli') return risk > 0;
          if (riskFilter == 'Risksiz') return risk == 0;
          return true;
        }).toList();
        final totalExcess = summary.fold<int>(0,
            (sum, row) => sum + (row['excess'] as int));
        final persistent = summary.where(
            (row) => (row['riskWeeks'] as int) >= threshold).length;
        final weekly = <Map<String, dynamic>>[];
        for (int i = 0; i < weeks; i++) {
          final week = first.add(Duration(days: i * 7));
          final key = iso(week);
          int workload = 0, overrun = 0, affected = 0;
          for (final owner in loads.keys) {
            final value = loads[owner]![key] ?? 0;
            workload += value;
            if (value > budget) {
              overrun += value - budget;
              affected++;
            }
          }
          weekly.add({'week': key, 'load': workload,
            'overrun': overrun, 'affected': affected});
        }
        final auditsInWindow = audits.where((a) {
          final stamp = parse(a['at'] ?? a['date'] ?? a['createdAt']);
          return stamp != null &&
              !stamp.isBefore(first) &&
              stamp.isBefore(anchor.add(const Duration(days: 7)));
        }).toList();

        Widget metric(String title, String value, IconData icon) =>
            Card(color: _pink, child: Padding(
              padding: const EdgeInsets.all(12),
              child: Row(children: [
                Icon(icon, color: _purple), const SizedBox(width: 12),
                Expanded(child: Text(title)),
                Text(value, style: const TextStyle(
                    fontWeight: FontWeight.bold, color: _purple)),
              ]),
            ));

        return SafeArea(child: FractionallySizedBox(
          heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            Row(children: [
              const Expanded(child: Text('Kapasite kontrol ve risk komuta merkezi',
                  style: TextStyle(fontSize: 20,
                      fontWeight: FontWeight.bold, color: _purple))),
              IconButton(onPressed: () => Navigator.pop(sheet),
                  icon: const Icon(Icons.close)),
            ]),
            const Text('Kayıtlı planlardan hesaplanan gözlemsel göstergeler. '
                'Onay geçmişi, kapasite iyileşmesinin tek başına nedeni olarak yorumlanmaz.'),
            if (loading) const LinearProgressIndicator(),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 8, children: [
              DropdownButton<int>(value: weeks,
                  items: [4, 8, 12, 26, 52].map((v) =>
                      DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(),
                  onChanged: (v) => refresh(() => weeks = v ?? 12)),
              DropdownButton<int>(value: threshold,
                  items: [2, 3, 4, 5].map((v) =>
                      DropdownMenuItem(value: v,
                          child: Text('Tekrar ≥ $v'))).toList(),
                  onChanged: (v) => refresh(() => threshold = v ?? 3)),
              DropdownButton<int>(value: dailyCapacity,
                  items: [15, 30, 45, 60, 90, 120, 180].map((v) =>
                      DropdownMenuItem(value: v,
                          child: Text('$v dk/gün'))).toList(),
                  onChanged: (v) => refresh(() => dailyCapacity = v ?? 45)),
            ]),
            Row(children: [
              IconButton(onPressed: () => refresh(() => weeklyOffset--),
                  icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('${iso(first)} – ${iso(anchor)}',
                  textAlign: TextAlign.center)),
              IconButton(onPressed: weeklyOffset >= 0 ? null :
                  () => refresh(() => weeklyOffset++),
                  icon: const Icon(Icons.chevron_right)),
              TextButton(onPressed: () => refresh(() => weeklyOffset = 0),
                  child: const Text('Bugün')),
            ]),
            DropdownButtonFormField<String>(
              initialValue: ownerFilter,
              decoration: const InputDecoration(labelText: 'Sorumlu'),
              items: ['Tümü', ...owners].map((v) =>
                  DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) => refresh(() => ownerFilter = v ?? 'Tümü')),
            DropdownButtonFormField<String>(
              initialValue: riskFilter,
              decoration: const InputDecoration(labelText: 'Risk filtresi'),
              items: ['Tümü', 'Kalıcı', 'Riskli', 'Risksiz'].map((v) =>
                  DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) => refresh(() => riskFilter = v ?? 'Tümü')),
            TextField(decoration: const InputDecoration(
                labelText: 'Görev, sorumlu veya öncelik ara',
                prefixIcon: Icon(Icons.search)),
              onChanged: (v) => refresh(() => search = v.trim())),
            metric('İncelenen açık görev', '${selected.length}',
                Icons.assignment_outlined),
            metric('Kalıcı riskli sorumlu', '$persistent',
                Icons.warning_amber_outlined),
            metric('Toplam kapasite aşımı', '$totalExcess dk',
                Icons.timer_outlined),
            metric('Dönemdeki onay kayıtları', '${auditsInWindow.length}',
                Icons.verified_outlined),
            const SizedBox(height: 12),
            const Text('Sorumlu bazında risk sıralaması',
                style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
            if (!loading && filtered.isEmpty)
              const ListTile(title: Text('Bu filtrelerde risk kaydı bulunamadı.')),
            ...filtered.map((r) {
              final risk = r['riskWeeks'] as int;
              final isPersistent = risk >= threshold;
              return Card(child: ListTile(
                leading: Icon(isPersistent ? Icons.error_outline :
                    Icons.insights_outlined,
                    color: isPersistent ? Colors.deepOrange : _purple),
                title: Text(str(r['owner'])),
                subtitle: Text('${r['tasks']} görev • '
                    '${r['weeksObserved']} aktif hafta • '
                    '$risk riskli hafta • ${r['excess']} dk aşım'),
                trailing: Text(isPersistent ? 'Kalıcı' :
                    risk > 0 ? 'İzle' : 'Normal'),
              ));
            }),
            const SizedBox(height: 12),
            const Text('Haftalık yük ve risk trendi',
                style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
            ...weekly.reversed.map((row) => ListTile(
              dense: true,
              title: Text(str(row['week'])),
              subtitle: Text('Yük: ${row['load']} dk • '
                  'Riskli sorumlu: ${row['affected']}'),
              trailing: Text('${row['overrun']} dk aşım'),
            )),
            const Divider(),
            const Text('Onay geçmişi (salt okunur)',
                style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
            if (auditsInWindow.isEmpty)
              const ListTile(title: Text('Bu dönemde onay kaydı yok.')),
            ...auditsInWindow.take(30).map((a) => ListTile(
              dense: true,
              title: Text(str(a['type']).isEmpty
                  ? 'Onay / karar kaydı' : str(a['type'])),
              subtitle: Text('${a['at'] ?? a['date'] ?? ''} • '
                  '${a['note'] ?? ''}'),
            )),
            FilledButton.tonalIcon(
              icon: const Icon(Icons.copy_all_outlined),
              label: const Text('Filtrelenmiş analiz CSV kopyala'),
              onPressed: () async {
                final rows = <String>[
                  'Tür,Hafta,Sorumlu,Görev,Toplam dakika,Aşım dakika,Riskli hafta',
                  ...filtered.map((r) => [
                    'Sorumlu', '', r['owner'], r['tasks'],
                    r['total'], r['excess'], r['riskWeeks']
                  ].map(csv).join(',')),
                  ...weekly.map((w) => [
                    'Hafta', w['week'], '', '', w['load'],
                    w['overrun'], w['affected']
                  ].map(csv).join(',')),
                ];
                await Clipboard.setData(
                    ClipboardData(text: '\uFEFF${rows.join('\r\n')}'));
                if (mounted) _notice('Analiz CSV verisi panoya kopyalandı.');
              },
            ),
            FilledButton.tonalIcon(
              icon: const Icon(Icons.rule_folder_outlined),
              label: const Text('Önerileri seç / onay merkezine git'),
              onPressed: () {
                Navigator.pop(sheet);
                _showKitchenRiskReductionApprovalCenter();
              },
            ),
            FilledButton.tonalIcon(
              icon: const Icon(Icons.show_chart),
              label: const Text('Ayrıntılı performans trendlerine git'),
              onPressed: () {
                Navigator.pop(sheet);
                _showKitchenPreventiveCapacityTrends();
              },
            ),
            const Text('Not: Kapasite haftalık 5 iş günü varsayımıyla '
                'hesaplanır. Takvim müsaitliği ve görev bağımlılıkları '
                'ayrıca doğrulanmalıdır.',
                style: TextStyle(fontSize: 12)),
          ]),
        ));
      }),
    );
  }

  // Büyük paket: risk azaltma karar merkezi. Mevcut kayıtlar yalnızca onayla değişir.
  void _showKitchenRiskReductionApprovalCenter() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    const auditKey = 'paket45_risk_reduction_approvals_v1';
    final actions = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    final audit = <Map<String, dynamic>>[];
    final selected = <String>{};
    bool initialized = false, loading = true, saving = false;
    int dailyMinutes = 45, horizon = 8, limit = 30;
    String ownerFilter = 'Tümü', strategy = 'Karma';
    DateTime anchor = DateTime.now();

    String txt(Object? value) => value?.toString() ?? '';
    DateTime? date(Object? value) => DateTime.tryParse(txt(value));
    DateTime monday(DateTime d) =>
        DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) =>
        '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? value) => '"${txt(value).replaceAll('"', '""')}"';
    bool active(Map<String, dynamic> a) =>
        !['Tamamlandı', 'İptal'].contains(txt(a['status']));
    bool protected(Map<String, dynamic> a) =>
        ['kritik', 'critical', 'yüksek', 'high']
            .contains(txt(a['priority']).trim().toLowerCase());
    int duration(Map<String, dynamic> a) =>
        (estimates[txt(a['id'])] ??
          int.tryParse(txt(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    String loadKey(String owner, DateTime d) => '$owner|${iso(monday(d))}';
    int excess(Map<String, int> loads, int budget) =>
        loads.values.fold(0, (int sum, int value) =>
            sum + (value > budget ? value - budget : 0));

    showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, refresh) {
        if (!initialized) {
          initialized = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final a = jsonDecode(prefs.getString(actionKey) ?? '[]');
              final e = jsonDecode(prefs.getString(estimateKey) ?? '{}');
              final h = jsonDecode(prefs.getString(auditKey) ?? '[]');
              if (!sheet.mounted) return;
              refresh(() {
                if (a is List) {
                  actions.addAll(a.whereType<Map>()
                      .map((v) => Map<String, dynamic>.from(v)));
                }
                if (e is Map) {
                  for (final entry in e.entries) {
                    final n = int.tryParse(txt(entry.value));
                    if (n != null && n >= 5 && n <= 480) {
                      estimates[txt(entry.key)] = n;
                    }
                  }
                }
                if (h is List) {
                  audit.addAll(h.whereType<Map>()
                      .map((v) => Map<String, dynamic>.from(v)));
                }
                loading = false;
              });
            } catch (_) {
              if (sheet.mounted) refresh(() => loading = false);
              if (mounted) _notice('Risk azaltma verileri okunamadı.');
            }
          });
        }
        final start = monday(anchor);
        final end = start.add(Duration(days: horizon * 7));
        final owners = actions.map((a) => txt(a['owner']).trim())
            .where((v) => v.isNotEmpty).toSet().toList()..sort();
        if (ownerFilter != 'Tümü' && !owners.contains(ownerFilter)) {
          ownerFilter = 'Tümü';
        }
        final current = <String, int>{};
        final eligible = <Map<String, dynamic>>[];
        for (final a in actions) {
          final due = date(a['due']);
          final owner = txt(a['owner']).trim();
          if (!active(a) || due == null || owner.isEmpty ||
              due.isBefore(start) || !due.isBefore(end)) { continue ; }
          final key = loadKey(owner, due);
          current[key] = (current[key] ?? 0) + duration(a);
          eligible.add(a);
        }
        final budget = dailyMinutes * 5;
        final working = Map<String, int>.from(current);
        final proposals = <Map<String, dynamic>>[];
        final movable = eligible.where((a) => !protected(a) &&
            (ownerFilter == 'Tümü' || txt(a['owner']) == ownerFilter))
            .toList()..sort((a, b) => duration(b).compareTo(duration(a)));
        for (final a in movable) {
          if (proposals.length >= limit) break;
          final due = date(a['due'])!;
          final owner = txt(a['owner']).trim();
          final source = loadKey(owner, due);
          final minutes = duration(a);
          if ((working[source] ?? 0) <= budget) continue;
          var bestGain = 0;
          String? newOwner;
          DateTime? newDate;
          for (var w = 0; w < horizon; w++) {
            final week = start.add(Duration(days: w * 7));
            for (final person in owners) {
              if (strategy == 'Yalnız tarih' && person != owner) continue;
              if (strategy == 'Yalnız sorumlu' &&
                  iso(monday(due)) != iso(week)) { continue ; }
              final target = loadKey(person, week);
              if (target == source) continue;
              final before = (working[source]! - budget).clamp(0, 999999) +
                  ((working[target] ?? 0) - budget).clamp(0, 999999);
              final after = (working[source]! - minutes - budget)
                      .clamp(0, 999999) +
                  ((working[target] ?? 0) + minutes - budget)
                      .clamp(0, 999999);
              final gain = before - after;
              if (gain > bestGain) {
                bestGain = gain.toInt();
                newOwner = person;
                newDate = week.add(const Duration(days: 1));
              }
            }
          }
          if (bestGain <= 0 || newOwner == null || newDate == null) continue;
          final target = loadKey(newOwner, newDate);
          working[source] = working[source]! - minutes;
          working[target] = (working[target] ?? 0) + minutes;
          proposals.add({
            'id': txt(a['id']), 'title': txt(a['title']),
            'oldOwner': owner, 'newOwner': newOwner,
            'oldDue': txt(a['due']), 'newDue': iso(newDate),
            'minutes': minutes, 'gain': bestGain,
          });
        }
        final proposalIds = proposals.map((p) => txt(p['id'])).toSet();
        selected.removeWhere((id) => !proposalIds.contains(id));
        final preview = Map<String, int>.from(current);
        for (final p in proposals.where((p) => selected.contains(txt(p['id'])))) {
          final before = date(p['oldDue']);
          final after = date(p['newDue']);
          if (before == null || after == null) continue;
          final from = loadKey(txt(p['oldOwner']), before);
          final to = loadKey(txt(p['newOwner']), after);
          preview[from] = (preview[from] ?? 0) - (p['minutes'] as int);
          preview[to] = (preview[to] ?? 0) + (p['minutes'] as int);
        }
        final baseline = excess(current, budget);
        final projected = excess(preview, budget);
        final chosen = proposals.where((p) => selected.contains(txt(p['id']))).toList();
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Onaylı risk azaltma karar merkezi',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold,
                color: _purple)),
            const SizedBox(height: 6),
            const Text('Öneriler önizlemedir. Yalnızca seçilen ve onaylanan '
              'aksiyonların sorumlusu/tarihi değişir. Kritik/yüksek '
              'öncelikli aksiyonlar önerilmez.'),
            if (loading) const LinearProgressIndicator(),
            Wrap(spacing: 10, runSpacing: 6, children: [
              DropdownButton<int>(value: horizon,
                items: [4, 8, 12, 26, 52].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(),
                onChanged: (v) => refresh(() { horizon = v ?? 8; selected.clear(); })),
              DropdownButton<int>(value: dailyMinutes,
                items: [15, 30, 45, 60, 90, 120, 180].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n dk/gün'))).toList(),
                onChanged: (v) => refresh(() { dailyMinutes = v ?? 45; selected.clear(); })),
              DropdownButton<int>(value: limit,
                items: [5, 10, 20, 30, 40].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n öneri'))).toList(),
                onChanged: (v) => refresh(() { limit = v ?? 30; selected.clear(); })),
            ]),
            DropdownButtonFormField<String>(
              key: ValueKey('riskOwner:$ownerFilter'),
              initialValue: ownerFilter,
              decoration: const InputDecoration(labelText: 'Sorumlu'),
              items: ['Tümü', ...owners].map((o) =>
                DropdownMenuItem(value: o, child: Text(o))).toList(),
              onChanged: (v) => refresh(() { ownerFilter = v ?? 'Tümü'; selected.clear(); })),
            DropdownButtonFormField<String>(
              key: ValueKey('riskStrategy:$strategy'),
              initialValue: strategy,
              decoration: const InputDecoration(labelText: 'Optimizasyon stratejisi'),
              items: ['Karma', 'Yalnız tarih', 'Yalnız sorumlu'].map((v) =>
                DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) => refresh(() { strategy = v ?? 'Karma'; selected.clear(); })),
            Wrap(spacing: 8, children: [
              OutlinedButton(onPressed: () => refresh(() {
                anchor = anchor.subtract(Duration(days: horizon * 7));
                selected.clear();
              }), child: const Text('Önceki dönem')),
              OutlinedButton(onPressed: () => refresh(() {
                anchor = DateTime.now(); selected.clear();
              }), child: const Text('Bugün')),
              OutlinedButton(onPressed: () => refresh(() {
                anchor = anchor.add(Duration(days: horizon * 7));
                selected.clear();
              }), child: const Text('Sonraki dönem')),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
                Text('Mevcut kapasite aşımı: $baseline dk'),
                Text('Seçim sonrası aşım: $projected dk'),
                Text('Tahmini azalma: ${baseline - projected} dk'),
                Text('Seçilen: ${chosen.length} / ${proposals.length} öneri'),
                Text('Önceki onay kayıtları: ${audit.length}'),
              ]))),
            Wrap(spacing: 8, children: [
              TextButton(onPressed: proposals.isEmpty ? null : () =>
                refresh(() => selected.addAll(proposalIds)),
                child: const Text('Tümünü seç')),
              TextButton(onPressed: selected.isEmpty ? null : () =>
                refresh(selected.clear), child: const Text('Seçimi temizle')),
              OutlinedButton.icon(icon: const Icon(Icons.copy_outlined),
                label: const Text('CSV kopyala'),
                onPressed: loading ? null : () async {
                  final lines = <String>[
                    'Seçili,ID,Aksiyon,Eski sorumlu,Yeni sorumlu,Eski tarih,Yeni tarih,Dakika,Kazanç',
                    ...proposals.map((p) => [
                      selected.contains(txt(p['id'])) ? 'Evet' : 'Hayır',
                      p['id'], p['title'], p['oldOwner'], p['newOwner'],
                      p['oldDue'], p['newDue'], p['minutes'], p['gain'],
                    ].map(csv).join(',')),
                  ];
                  await Clipboard.setData(
                    ClipboardData(text: '\uFEFF${lines.join('\r\n')}'));
                  if (mounted) _notice('Öneriler CSV olarak panoya kopyalandı.');
                }),
            ]),
            if (!loading && proposals.isEmpty)
              const ListTile(title: Text('Bu dönemde uygulanabilir öneri yok.')),
            ...proposals.map((p) => CheckboxListTile(
              value: selected.contains(txt(p['id'])),
              onChanged: saving ? null : (value) => refresh(() {
                if (value == true) { selected.add(txt(p['id'])); }
                else { selected.remove(txt(p['id'])); }
              }),
              title: Text(txt(p['title']).isEmpty ? txt(p['id']) : txt(p['title'])),
              subtitle: Text('${p['oldOwner']} • ${p['oldDue']} → '
                '${p['newOwner']} • ${p['newDue']}\n'
                '${p['minutes']} dk • Tahmini kazanım ${p['gain']} dk'),
              isThreeLine: true,
            )),
            FilledButton.icon(
              icon: const Icon(Icons.verified_outlined),
              label: Text('Seçilen ${chosen.length} öneriyi onayla ve uygula'),
              onPressed: loading || saving || chosen.isEmpty ? null : () async {
                final approved = await showDialog<bool>(context: sheet,
                  builder: (dialog) => AlertDialog(
                    title: const Text('Plan değişikliklerini onayla'),
                    content: Text('${chosen.length} aksiyonun sorumlusu '
                      've/veya hedef tarihi değiştirilecek. '
                      'Tahmini aşım: $baseline → $projected dk. '
                      'Bu işlem mevcut aksiyon kayıtlarını günceller.'),
                    actions: [
                      TextButton(onPressed: () => Navigator.pop(dialog, false),
                        child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(dialog, true),
                        child: const Text('Onayla ve kaydet')),
                    ],
                  ));
                if (approved != true || !sheet.mounted) return;
                refresh(() => saving = true);
                try {
                  final prefs = await SharedPreferences.getInstance();
                  // Eski kayıtlarla çakışmayı engellemek için son hâli yeniden oku.
                  final latestRaw = jsonDecode(prefs.getString(actionKey) ?? '[]');
                  if (latestRaw is! List) throw StateError('Aksiyon listesi geçersiz');
                  final latest = latestRaw.whereType<Map>()
                      .map((e) => Map<String, dynamic>.from(e)).toList();
                  final changed = <Map<String, dynamic>>[];
                  for (final p in chosen) {
                    final matches = latest.where((a) => txt(a['id']) == txt(p['id'])).toList();
                    if (matches.length != 1) throw StateError('Aksiyon kimliği eşleşmedi');
                    final a = matches.single;
                    if (!active(a) || protected(a) ||
                        txt(a['owner']) != txt(p['oldOwner']) ||
                        txt(a['due']) != txt(p['oldDue'])) {
                      throw StateError('Aksiyon başka yerde değişmiş. Yeniden açın.');
                    }
                    changed.add({
                      ...p, 'appliedAt': DateTime.now().toIso8601String(),
                      'previousStatus': txt(a['status']),
                    });
                    a['owner'] = p['newOwner'];
                    a['due'] = p['newDue'];
                  }
                  final previous = prefs.getString(actionKey) ?? '[]';
                  final ok = await prefs.setString(actionKey, jsonEncode(latest));
                  if (!ok) throw StateError('Aksiyon kaydı yazılamadı');
                  final log = <Map<String, dynamic>>[
                    {
                      'id': DateTime.now().microsecondsSinceEpoch.toString(),
                      'date': DateTime.now().toIso8601String(),
                      'strategy': strategy, 'dailyMinutes': dailyMinutes,
                      'horizon': horizon, 'beforeExcess': baseline,
                      'afterExcess': projected, 'changes': changed,
                    },
                    ...audit,
                  ];
                  if (!await prefs.setString(auditKey, jsonEncode(log))) {
                    await prefs.setString(actionKey, previous);
                    throw StateError('Onay geçmişi kaydedilemedi');
                  }
                  if (!sheet.mounted) return;
                  refresh(() {
                    actions..clear()..addAll(latest);
                    audit..clear()..addAll(log);
                    selected.clear();
                    saving = false;
                  });
                  if (mounted) _notice('${changed.length} aksiyon onaylanıp kaydedildi.');
                } catch (_) {
                  if (sheet.mounted) refresh(() => saving = false);
                  if (mounted) _notice('Uygulama başarısız. Aksiyonları kontrol edin.');
                }
              }),
            const Divider(),
            const Text('Onay geçmişi',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (!loading && audit.isEmpty)
              const ListTile(title: Text('Henüz onay kaydı bulunmuyor.')),
            ...audit.take(30).map((entry) {
              final changes = (entry['changes'] as List? ?? const []);
              return ExpansionTile(
                title: Text('${entry['date'] ?? ''} • ${changes.length} aksiyon'),
                subtitle: Text('${entry['strategy'] ?? ''} • '
                  '${entry['beforeExcess'] ?? '?'} → '
                  '${entry['afterExcess'] ?? '?'} dk'),
                children: [
                  ...changes.take(60).whereType<Map>().map((change) => ListTile(
                    dense: true, title: Text(txt(change['title'])),
                    subtitle: Text('${change['oldOwner']} → ${change['newOwner']}\n'
                      '${change['oldDue']} → ${change['newDue']}'),
                  )),
                  TextButton.icon(
                    icon: const Icon(Icons.copy_outlined),
                    label: const Text('Onay kaydını kopyala'),
                    onPressed: () async {
                      await Clipboard.setData(
                        ClipboardData(text: jsonEncode(entry)));
                      if (mounted) _notice('Onay kaydı panoya kopyalandı.');
                    }),
                ],
              );
            }),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              icon: const Icon(Icons.auto_fix_high_outlined),
              label: const Text('Kalıcı risk önerilerine dön'),
              onPressed: () {
                Navigator.pop(sheet);
                _showKitchenPersistentCapacityRecommendations();
              }),
            const Text('Tahminler haftalık toplam süreye dayanır. '
              'Gerçek uygunluk ve teslim tarihi kısıtları ayrıca doğrulanmalıdır.',
              style: TextStyle(fontSize: 11)),
          ])));
      }),
    );
  }

  void _showKitchenPersistentCapacityRecommendations() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    final actions = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    bool started = false, loading = true, weekdaysOnly = true, risksOnly = true;
    int weeks = 8, dailyBudget = 45, repeatThreshold = 2, maxSuggestions = 20;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü';
    String str(Object? v) => '${v ?? ''}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) =>
        DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String day(DateTime d) =>
        '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String cell(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    bool open(Map<String, dynamic> a) =>
        !['Tamamlandı', 'İptal'].contains(str(a['status']));
    int minutes(Map<String, dynamic> a) =>
        (estimates[str(a['id'])] ??
          int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    bool protected(Map<String, dynamic> a) =>
        ['kritik', 'critical', 'yüksek', 'high']
            .contains(str(a['priority']).trim().toLowerCase());
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              final saved = jsonDecode(prefs.getString(estimateKey) ?? '{}');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) {
                  for (final x in raw) {
                    if (x is Map) actions.add(Map<String, dynamic>.from(x));
                  }
                }
                if (saved is Map) {
                  for (final e in saved.entries) {
                    final value = int.tryParse(str(e.value));
                    if (value != null && value >= 5 && value <= 480) {
                      estimates[str(e.key)] = value;
                    }
                  }
                }
                loading = false;
              });
            } catch (_) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Aksiyon kayıtları okunamadı.');
            }
          });
        }
        final start = monday(anchor);
        final end = start.add(Duration(days: weeks * 7));
        final people = <String>{
          ...actions.map((a) => str(a['owner']).trim())
              .where((v) => v.isNotEmpty)
        }.toList()..sort();
        final owners = ['Tümü', ...people];
        if (!owners.contains(ownerFilter)) ownerFilter = 'Tümü';
        final budget = dailyBudget * (weekdaysOnly ? 5 : 7);
        final scheduled = <Map<String, dynamic>>[];
        var invalid = 0;
        for (final a in actions) {
          if (!open(a)) continue;
          final d = parse(a['due']);
          if (d == null || str(a['owner']).trim().isEmpty ||
              str(a['id']).trim().isEmpty) {
            invalid++;
            continue;
          }
          if (!d.isBefore(start) && d.isBefore(end)) scheduled.add(a);
        }
        String key(String owner, DateTime d) => '$owner|${day(monday(d))}';
        final loads = <String, int>{};
        final counts = <String, int>{};
        for (final a in scheduled) {
          final k = key(str(a['owner']).trim(), parse(a['due'])!);
          loads[k] = (loads[k] ?? 0) + minutes(a);
          counts[k] = (counts[k] ?? 0) + 1;
        }
        int excess(Map<String, int> values) => values.values.fold<int>(
          0, (sum, v) => sum + (v > budget ? v - budget : 0));
        final initialExcess = excess(loads);
        final recurring = <String, int>{};
        for (final entry in loads.entries) {
          if (entry.value > budget) {
            final owner = entry.key.split('|').first;
            recurring[owner] = (recurring[owner] ?? 0) + 1;
          }
        }
        final riskWeeks = loads.entries.where((e) =>
            e.value > budget &&
            (ownerFilter == 'Tümü' ||
             e.key.startsWith('$ownerFilter|'))).toList()
          ..sort((a, b) => (b.value - budget).compareTo(a.value - budget));
        final candidates = scheduled.where((a) =>
          !protected(a) &&
          (ownerFilter == 'Tümü' || str(a['owner']) == ownerFilter) &&
          (loads[key(str(a['owner']), parse(a['due'])!)] ?? 0) > budget
        ).toList()..sort((a, b) => minutes(b).compareTo(minutes(a)));
        final working = Map<String, int>.from(loads);
        final proposals = <Map<String, dynamic>>[];
        for (final a in candidates) {
          if (proposals.length >= maxSuggestions) break;
          final oldOwner = str(a['owner']).trim();
          final oldDate = parse(a['due'])!;
          final fromKey = key(oldOwner, oldDate);
          final duration = minutes(a);
          if ((working[fromKey] ?? 0) <= budget) continue;
          var bestGain = 0;
          String? bestOwner;
          DateTime? bestDate;
          String bestMode = '';
          for (var w = 0; w < weeks; w++) {
            final targetWeek = start.add(Duration(days: w * 7));
            for (final person in people) {
              final targetKey = key(person, targetWeek);
              if (targetKey == fromKey) continue;
              final before = ((working[fromKey]! - budget).clamp(0, 999999) as num).toInt() +
                (((working[targetKey] ?? 0) - budget).clamp(0, 999999) as num).toInt();
              final after = (((working[fromKey]! - duration) - budget).clamp(0, 999999) as num).toInt() +
                ((((working[targetKey] ?? 0) + duration) - budget).clamp(0, 999999) as num).toInt();
              final gain = before - after;
              if (gain > bestGain) {
                bestGain = gain;
                bestOwner = person;
                // Pazartesi yerine ilk uygun hafta içi gününü kullan.
                bestDate = targetWeek.add(const Duration(days: 1));
                bestMode = person == oldOwner ? 'Tarih' :
                    monday(oldDate) == targetWeek ? 'Sorumlu' : 'Karma';
              }
            }
          }
          if (bestGain <= 0 || bestOwner == null || bestDate == null) continue;
          final targetKey = key(bestOwner, bestDate);
          working[fromKey] = working[fromKey]! - duration;
          working[targetKey] = (working[targetKey] ?? 0) + duration;
          proposals.add({
            'title': str(a['title']).isEmpty ? str(a['id']) : str(a['title']),
            'owner': oldOwner, 'newOwner': bestOwner,
            'oldDate': day(oldDate), 'newDate': day(bestDate),
            'minutes': duration, 'gain': bestGain, 'mode': bestMode,
          });
        }
        final afterExcess = excess(working);
        final visibleRisks = risksOnly
            ? riskWeeks.where((e) =>
                (recurring[e.key.split('|').first] ?? 0) >= repeatThreshold).toList()
            : riskWeeks;
        return SafeArea(child: FractionallySizedBox(
          heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Kalıcı kapasite riskleri / önleyici öneriler',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold,
                color: _purple)),
            const SizedBox(height: 8),
            const Text('Açık aksiyonların mevcut planı üzerinden hesaplanan, '
              'kayıtları değiştirmeyen senaryodur.'),
            if (loading) const LinearProgressIndicator(),
            Wrap(spacing: 8, runSpacing: 4, children: [
              DropdownButton<int>(value: weeks,
                items: [4, 8, 12, 26, 52].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(),
                onChanged: (v) { if (v != null) update(() => weeks = v); }),
              DropdownButton<int>(value: dailyBudget,
                items: [15, 30, 45, 60, 90, 120, 180].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n dk/gün'))).toList(),
                onChanged: (v) { if (v != null) update(() => dailyBudget = v); }),
              DropdownButton<int>(value: repeatThreshold,
                items: [2, 3, 4, 5].map((n) =>
                  DropdownMenuItem(value: n, child: Text('$n hafta tekrar'))).toList(),
                onChanged: (v) { if (v != null) update(() => repeatThreshold = v); }),
              DropdownButton<int>(value: maxSuggestions,
                items: [5, 10, 20, 40].map((n) =>
                  DropdownMenuItem(value: n, child: Text('En fazla $n öneri'))).toList(),
                onChanged: (v) { if (v != null) update(() => maxSuggestions = v); }),
            ]),
            DropdownButtonFormField<String>(
              key: ValueKey(ownerFilter),
              initialValue: ownerFilter,
              decoration: const InputDecoration(labelText: 'Sorumlu filtresi'),
              items: owners.map((o) => DropdownMenuItem(
                value: o, child: Text(o))).toList(),
              onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
            SwitchListTile(
              value: weekdaysOnly, title: const Text('5 iş günü kapasitesi'),
              onChanged: (v) => update(() => weekdaysOnly = v)),
            SwitchListTile(
              value: risksOnly,
              title: const Text('Yalnızca tekrarlayan riskleri göster'),
              onChanged: (v) => update(() => risksOnly = v)),
            Wrap(spacing: 8, children: [
              OutlinedButton(onPressed: () => update(() =>
                anchor = anchor.subtract(Duration(days: weeks * 7))),
                child: const Text('Önceki dönem')),
              OutlinedButton(onPressed: () => update(() => anchor = DateTime.now()),
                child: const Text('Bugün')),
              OutlinedButton(onPressed: () => update(() =>
                anchor = anchor.add(Duration(days: weeks * 7))),
                child: const Text('Sonraki dönem')),
            ]),
            Card(color: _pink, child: Padding(
              padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('${day(start)} – ${day(end.subtract(const Duration(days: 1)))}',
                    style: const TextStyle(fontWeight: FontWeight.bold)),
                  Text('Açık aksiyon: ${scheduled.length} • Eksik kayıt: $invalid'),
                  Text('Riskli sorumlu-hafta: ${riskWeeks.length}'),
                  Text('Mevcut aşım: $initialExcess dk'),
                  Text('Öneri sonrası tahmini aşım: $afterExcess dk'),
                  Text('Senaryo azalması: ${initialExcess - afterExcess} dk'),
                  Text('Önerilen değişiklik: ${proposals.length}'),
                ]))),
            const SizedBox(height: 8),
            const Text('Tekrarlayan riskli haftalar',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (!loading && visibleRisks.isEmpty)
              const ListTile(title: Text('Seçilen ölçütlerde risk bulunamadı.')),
            ...visibleRisks.take(80).map((e) {
              final parts = e.key.split('|');
              final owner = parts.first;
              return ListTile(
                leading: const Icon(Icons.warning_amber_outlined,
                  color: Colors.deepOrange),
                title: Text('$owner • ${parts.length > 1 ? parts[1] : ''}'),
                subtitle: Text('${counts[e.key] ?? 0} aksiyon • '
                  '${recurring[owner] ?? 0} riskli hafta'),
                trailing: Text('+${e.value - budget} dk'));
            }),
            const Divider(),
            const Text('Önerilen önleyici dağılım (simülasyon)',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (!loading && proposals.isEmpty)
              const ListTile(title: Text('Kapasite aşımını azaltan güvenli '
                'bir alternatif bulunamadı.')),
            ...proposals.map((p) => Card(child: ListTile(
              title: Text(str(p['title'])),
              subtitle: Text('${p['owner']} • ${p['oldDate']} → '
                '${p['newOwner']} • ${p['newDate']}\n'
                '${p['mode']} • ${p['minutes']} dk'),
              trailing: Text('-${p['gain']} dk')))),
            FilledButton.tonalIcon(
              icon: const Icon(Icons.copy_outlined),
              label: const Text('Risk ve önerileri CSV olarak kopyala'),
              onPressed: loading ? null : () async {
                final rows = <String>[
                  'Tür,Sorumlu,Hafta veya tarih,Yeni sorumlu,Yeni tarih,'
                    'Aksiyon,Planlanan dakika,Aşım veya kazanım',
                  ...visibleRisks.map((e) => [
                    'Risk', e.key.split('|').first,
                    e.key.split('|').last, '', '', '',
                    e.value, e.value - budget
                  ].map(cell).join(',')),
                  ...proposals.map((p) => [
                    'Öneri', p['owner'], p['oldDate'], p['newOwner'],
                    p['newDate'], p['title'], p['minutes'], p['gain']
                  ].map(cell).join(',')),
                ];
                await Clipboard.setData(ClipboardData(
                  text: '\uFEFF${rows.join('\r\n')}'));
                if (mounted) _notice('CSV raporu panoya kopyalandı.');
              }),
            const SizedBox(height: 8),
            const Text('Önemli: Kritik/yüksek öncelikli aksiyonlar '
              'taşınmaz. Alternatif sorumlunun yetkinliği, gerçek müsaitliği '
              've zorunlu teslim tarihleri doğrulanmaz. Öneriler kaydedilmez; '
              'uygulama için mevcut onaylı optimizasyon ekranını kullanın.',
              style: TextStyle(fontSize: 12)),
            TextButton.icon(
              onPressed: () {
                Navigator.pop(sheet);
                _showKitchenApprovedActionCapacityOptimizer();
              },
              icon: const Icon(Icons.verified_outlined),
              label: const Text('Onaylı aksiyon optimizasyonuna geç')),
          ]),
        ));
      }),
    );
  }

  void _showKitchenPreventiveCapacityTrends() {
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    final history = <Map<String, dynamic>>[];
    bool started = false, loading = true, riskyOnly = false;
    int weeks = 12, repeatThreshold = 2;
    DateTime anchor = DateTime.now();
    String owner = 'Tümü', query = '';
    String str(Object? value) => '${value ?? ''}';
    int? integer(Object? value) => value is num ? value.toInt() : int.tryParse(str(value));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day)
        .subtract(Duration(days: d.weekday - 1));
    String date(DateTime d) =>
        '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';

    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final raw = jsonDecode(prefs.getString(historyKey) ?? '[]');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) {
                  history.addAll(raw.whereType<Map>()
                      .map((e) => Map<String, dynamic>.from(e)));
                }
                loading = false;
              });
            } catch (_) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Optimizasyon geçmişi okunamadı.');
            }
          });
        }
        final start = monday(anchor).subtract(Duration(days: 7 * (weeks - 1)));
        final end = monday(anchor).add(const Duration(days: 7));
        final entries = <Map<String, dynamic>>[];
        final owners = <String>{};
        int invalid = 0;
        for (final item in history) {
          if (str(item['source']) != 'preventive_capacity_action_plan') continue;
          final at = DateTime.tryParse(str(item['at']));
          final before = integer(item['beforeExcessMinutes']);
          final after = integer(item['afterExcessMinutes']);
          final rawChanges = item['changes'];
          if (at == null || before == null || after == null ||
              before < 0 || after < 0 || rawChanges is! List ||
              rawChanges.isEmpty) {
            invalid++;
            continue;
          }
          if (at.isBefore(start) || !at.isBefore(end)) continue;
          final affected = <String>{};
          for (final change in rawChanges.whereType<Map>()) {
            for (final key in ['oldOwner', 'newOwner']) {
              final value = str(change[key]).trim();
              if (value.isNotEmpty) affected.add(value);
            }
          }
          if (affected.isEmpty) {
            invalid++;
            continue;
          }
          owners.addAll(affected);
          entries.add({
            'week': date(monday(at)),
            'date': at.toIso8601String(),
            'owners': affected.toList()..sort(),
            'before': before,
            'after': after,
            'gain': before - after,
            'strategy': str(item['strategy']),
            'changes': rawChanges.length,
          });
        }
        final options = ['Tümü', ...owners.toList()..sort()];
        final selected = entries.where((e) {
          final affected = e['owners'] as List<String>;
          if (owner != 'Tümü' && !affected.contains(owner)) return false;
          if (riskyOnly && (e['after'] as int) == 0) return false;
          final haystack = '${e['week']} ${e['strategy']} ${affected.join(' ')}'.toLowerCase();
          return haystack.contains(query.trim().toLowerCase());
        }).toList();
        final weekly = <String, List<Map<String, dynamic>>>{};
        final ownerWeeks = <String, Set<String>>{};
        final ownerRiskWeeks = <String, Set<String>>{};
        for (final e in selected) {
          final week = e['week'] as String;
          weekly.putIfAbsent(week, () => []).add(e);
          for (final person in e['owners'] as List<String>) {
            ownerWeeks.putIfAbsent(person, () => <String>{}).add(week);
            if ((e['after'] as int) > 0) {
              ownerRiskWeeks.putIfAbsent(person, () => <String>{}).add(week);
            }
          }
        }
        final weekKeys = weekly.keys.toList()..sort();
        final repeated = ownerRiskWeeks.keys.where((p) =>
            ownerRiskWeeks[p]!.length >= repeatThreshold).toList()
          ..sort((a, b) => ownerRiskWeeks[b]!.length
              .compareTo(ownerRiskWeeks[a]!.length));
        final improved = selected.where((e) => (e['gain'] as int) > 0).length;
        final worsened = selected.where((e) => (e['gain'] as int) < 0).length;
        final stillRisk = selected.where((e) => (e['after'] as int) > 0).length;
        final totalGain = selected.fold<int>(0, (n, e) => n + (e['gain'] as int));
        final weeklyStats = <Map<String, dynamic>>[];
        for (final key in weekKeys) {
          final items = weekly[key]!;
          final success = items.where((e) => (e['gain'] as int) > 0).length;
          final risk = items.where((e) => (e['after'] as int) > 0).length;
          final gain = items.fold<int>(0, (n, e) => n + (e['gain'] as int));
          weeklyStats.add({
            'week': key, 'count': items.length, 'success': success,
            'risk': risk, 'gain': gain,
            'rate': 100.0 * success / items.length,
          });
        }
        Future<void> exportCsv() async {
          final rows = <String>[
            'Hafta;Islem tarihi;Sorumlular;Strateji;Aksiyon;Onceki asim dk;Sonraki asim dk;Net degisim dk;Risk devam',
            ...selected.map((e) => [
              e['week'], e['date'], (e['owners'] as List<String>).join(', '),
              e['strategy'], e['changes'], e['before'], e['after'],
              e['gain'], (e['after'] as int) > 0 ? 'Evet' : 'Hayır',
            ].map(csv).join(';')),
            '',
            'Hafta;Islem;Iyilesen;Risk devam;Net degisim dk;Basari yuzdesi',
            ...weeklyStats.map((w) => [
              w['week'], w['count'], w['success'], w['risk'],
              w['gain'], (w['rate'] as double).toStringAsFixed(1),
            ].map(csv).join(';')),
          ];
          await Clipboard.setData(ClipboardData(text: '\uFEFF${rows.join('\r\n')}'));
          if (mounted) _notice('Trend ve risk CSV raporu panoya kopyalandı.');
        }
        return SafeArea(child: SizedBox(
          height: MediaQuery.of(sheet).size.height * .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Önleyici kapasite performans trendleri',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold,
                    color: _purple)),
            const SizedBox(height: 6),
            const Text('Onaylı önleyici optimizasyonların işlem anındaki '
                'önce/sonra kapasite aşımı kayıtları incelenir.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 8, children: [
                DropdownButton<int>(
                  value: weeks,
                  items: [4, 8, 12, 26, 52].map((n) =>
                      DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(),
                  onChanged: (v) => update(() => weeks = v ?? 12)),
                DropdownButton<String>(
                  value: options.contains(owner) ? owner : 'Tümü',
                  items: options.map((p) =>
                      DropdownMenuItem(value: p, child: Text(p))).toList(),
                  onChanged: (v) => update(() => owner = v ?? 'Tümü')),
                DropdownButton<int>(
                  value: repeatThreshold,
                  items: [2, 3, 4, 5].map((n) =>
                      DropdownMenuItem(value: n, child: Text('$n riskli hafta'))).toList(),
                  onChanged: (v) => update(() => repeatThreshold = v ?? 2)),
                OutlinedButton(
                  onPressed: () => update(() => anchor =
                      anchor.subtract(Duration(days: weeks * 7))),
                  child: const Text('Önceki')),
                OutlinedButton(
                  onPressed: () => update(() => anchor = DateTime.now()),
                  child: const Text('Bugün')),
                OutlinedButton(
                  onPressed: () => update(() => anchor =
                      anchor.add(Duration(days: weeks * 7))),
                  child: const Text('Sonraki')),
              ]),
              Text('${date(start)} – ${date(end.subtract(const Duration(days: 1)))}'),
              TextField(
                decoration: const InputDecoration(
                    prefixIcon: Icon(Icons.search),
                    labelText: 'Sorumlu, hafta veya strateji ara'),
                onChanged: (v) => update(() => query = v)),
              SwitchListTile(
                title: const Text('Yalnızca risk devam eden işlemler'),
                value: riskyOnly,
                onChanged: (v) => update(() => riskyOnly = v)),
              Card(color: _pink, child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                  Text('İşlem: ${selected.length} • İyileşen: $improved • '
                      'Kötüleşen: $worsened'),
                  Text('Başarı: ${selected.isEmpty ? '—' : '${(100 * improved / selected.length).toStringAsFixed(1)}%'}'
                      ' • Risk devam: $stillRisk'),
                  Text('İşlem bazlı net aşım azalması: $totalGain dk'),
                  Text('Tekrarlayan riskli sorumlu: ${repeated.length}'
                      ' • Eksik/geçersiz kayıt: $invalid'),
                ]))),
              FilledButton.tonalIcon(
                onPressed: exportCsv,
                icon: const Icon(Icons.copy_all_outlined),
                label: const Text('Haftalık trend ve işlem CSV kopyala')),
              const Divider(),
              const Text('Haftalık performans eğilimi',
                  style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
              if (weeklyStats.isEmpty)
                const ListTile(title: Text('Bu dönemde uygun kayıt bulunamadı.')),
              ...weeklyStats.reversed.map((w) {
                final idx = weeklyStats.indexOf(w);
                final previous = idx == 0 ? null : weeklyStats[idx - 1];
                final delta = previous == null ? null :
                    (w['rate'] as double) - (previous['rate'] as double);
                return ExpansionTile(
                  title: Text('${w['week']} • ${w['count']} işlem'),
                  subtitle: Text('Başarı: ${(w['rate'] as double).toStringAsFixed(1)}%'
                      ' • Riskli: ${w['risk']} • Net: ${w['gain']} dk'
                      '${delta == null ? '' : ' • Önceki kayıtlı haftaya göre ${delta >= 0 ? '+' : ''}${delta.toStringAsFixed(1)} puan'}'),
                  children: [
                    ...weekly[w['week']]!.map((e) => ListTile(
                      title: Text('${e['strategy']} • ${e['changes']} aksiyon'),
                      subtitle: Text('${(e['owners'] as List<String>).join(', ')}\n'
                          '${e['before']} → ${e['after']} dk'
                          ' • Net: ${e['gain']} dk'),
                      isThreeLine: true,
                    )),
                  ],
                );
              }),
              const Divider(),
              const Text('Tekrarlayan kapasite riskleri',
                  style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
              if (repeated.isEmpty)
                const ListTile(title: Text('Seçilen eşikte tekrarlayan risk yok.')),
              ...repeated.map((p) => ListTile(
                leading: const Icon(Icons.warning_amber_rounded,
                    color: Colors.deepOrange),
                title: Text(p),
                subtitle: Text('${ownerRiskWeeks[p]!.length} farklı riskli hafta'
                    ' / ${ownerWeeks[p]?.length ?? 0} kayıtlı hafta'),
                trailing: const Text('İncele'),
                onTap: () => update(() {
                  owner = p;
                  riskyOnly = true;
                }),
              )),
              const SizedBox(height: 8),
              const Text('Veri yorumu: Haftalar optimizasyonun kaydedildiği '
                  'tarihe göre gruplanır. Kayıtsız haftalar sıfır başarı '
                  'olarak sayılmaz. Aynı iş yükü birden fazla işlemde yer '
                  'alabilir; toplam dakika gerçek tasarruf değildir. '
                  'Sorumlu bazlı risk, o sorumlunun dahil olduğu işlemin '
                  'sonrasında risk kalması anlamına gelir; riskin doğrudan '
                  'o kişiden kaynaklandığı anlamına gelmez.',
                  style: TextStyle(fontSize: 12)),
              TextButton(
                onPressed: () {
                  Navigator.pop(sheet);
                  _showKitchenPreventiveCapacityResults();
                },
                child: const Text('Önleyici kapasite başarı karnesini aç')),
              TextButton(
                onPressed: () {
                  Navigator.pop(sheet);
                  _showKitchenPreventiveCapacityActionPlan();
                },
                child: const Text('Onaylı önleyici aksiyon planını aç')),
            ],
          ]),
        ));
      }),
    );
  }

  void _showKitchenPreventiveCapacityResults() {
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    final records = <Map<String, dynamic>>[];
    bool started = false, loading = true, onlyRisk = false, onlyImproved = false;
    int weeks = 12;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü', query = '';
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    int? number(Object? x) => int.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String day(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final raw = jsonDecode(prefs.getString(historyKey) ?? '[]');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) {
                  for (final item in raw) {
                    if (item is Map) records.add(Map<String, dynamic>.from(item));
                  }
                }
                loading = false;
              });
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Önleyici optimizasyon geçmişi okunamadı: $e');
            }
          });
        }
        final start = monday(anchor).subtract(Duration(days: (weeks - 1) * 7));
        final end = monday(anchor).add(const Duration(days: 7));
        final details = <Map<String, dynamic>>[];
        final owners = <String>{};
        int invalid = 0, otherOperations = 0;
        for (final r in records) {
          if (str(r['source']) != 'preventive_capacity_action_plan') { otherOperations++; continue; }
          final at = parse(r['at']);
          if (at == null) { invalid++; continue; }
          if (at.isBefore(start) || !at.isBefore(end)) continue;
          final before = number(r['beforeExcessMinutes']);
          final after = number(r['afterExcessMinutes']);
          final changesRaw = r['changes'];
          if (before == null || after == null || before < 0 || after < 0 || changesRaw is! List || changesRaw.isEmpty) {
            invalid++; continue;
          }
          final changes = <Map<String, dynamic>>[];
          for (final c in changesRaw) {
            if (c is Map) changes.add(Map<String, dynamic>.from(c));
          }
          if (changes.isEmpty) { invalid++; continue; }
          final affected = <String>{};
          for (final c in changes) {
            final oldOwner = str(c['oldOwner']).trim(), newOwner = str(c['newOwner']).trim();
            if (oldOwner.isNotEmpty) affected.add(oldOwner);
            if (newOwner.isNotEmpty) affected.add(newOwner);
          }
          owners.addAll(affected);
          details.add(<String, dynamic>{
            'at': at, 'week': day(monday(at)), 'strategy': str(r['strategy']),
            'before': before, 'after': after, 'gain': before - after,
            'count': changes.length, 'owners': affected.toList()..sort(),
            'budget': number(r['dailyActionBudget']) ?? 0,
          });
        }
        details.sort((a,b) => (b['at'] as DateTime).compareTo(a['at'] as DateTime));
        final ownerOptions = ['Tümü', ...owners.toList()..sort()];
        final filtered = details.where((d) {
          if (ownerFilter != 'Tümü' && !(d['owners'] as List<String>).contains(ownerFilter)) return false;
          if (onlyRisk && (d['after'] as int) == 0) return false;
          if (onlyImproved && (d['gain'] as int) <= 0) return false;
          final haystack = '${d['week']} ${d['strategy']} ${(d['owners'] as List<String>).join(' ')}'.toLowerCase();
          return haystack.contains(query.trim().toLowerCase());
        }).toList();
        final total = filtered.length;
        final improved = filtered.where((d) => (d['gain'] as int) > 0).length;
        final worsened = filtered.where((d) => (d['gain'] as int) < 0).length;
        final ongoing = filtered.where((d) => (d['after'] as int) > 0).length;
        final totalBefore = filtered.fold<int>(0,(n,d)=>n+(d['before'] as int));
        final totalAfter = filtered.fold<int>(0,(n,d)=>n+(d['after'] as int));
        final weekStats = <String, List<Map<String,dynamic>>>{};
        for (final d in filtered) { weekStats.putIfAbsent(str(d['week']),()=>[]).add(d); }
        final orderedWeeks = weekStats.keys.toList()..sort();
        final ownerStats = <String, Map<String,int>>{};
        for (final d in filtered) {
          for (final owner in d['owners'] as List<String>) {
            final stat = ownerStats.putIfAbsent(owner,()=>{'operations':0,'improved':0,'risk':0});
            stat['operations'] = stat['operations']! + 1;
            if ((d['gain'] as int) > 0) stat['improved'] = stat['improved']! + 1;
            if ((d['after'] as int) > 0) stat['risk'] = stat['risk']! + 1;
          }
        }
        Future<void> export() async {
          final lines = <String>['Hafta;Tarih;Strateji;Sorumlular;Aksiyon;Onceki asim dk;Sonraki asim dk;Net azalma dk;Sonrasi risk'];
          for (final d in filtered) {
            lines.add([d['week'],(d['at'] as DateTime).toIso8601String(),d['strategy'],(d['owners'] as List<String>).join(', '),d['count'],d['before'],d['after'],d['gain'],(d['after'] as int)>0?'Evet':'Hayır'].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text:lines.join('\n')));
          if (mounted) _notice('Önleyici kapasite başarı raporu kopyalandı.');
        }
        return SafeArea(child:SizedBox(height:MediaQuery.of(sheet).size.height*.92,
          child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Önleyici kapasite aksiyonları / başarı karnesi',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),
            const SizedBox(height:8),
            const Text('Yalnızca onaylanmış önleyici aksiyon optimizasyonları incelenir. Sonuçlar işlem anında kaydedilen haftalık kapasite aşımı değerlerine dayanır.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing:8,runSpacing:8,children:[
                DropdownButton<int>(value:weeks,items:[4,8,12,26,52].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>update(()=>weeks=v??12)),
                DropdownButton<String>(value:ownerOptions.contains(ownerFilter)?ownerFilter:'Tümü',items:ownerOptions.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>ownerFilter=v??'Tümü')),
                OutlinedButton(onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:weeks*7))),child:const Text('Önceki')),
                OutlinedButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),
                OutlinedButton(onPressed:()=>update(()=>anchor=anchor.add(Duration(days:weeks*7))),child:const Text('Sonraki')),
              ]),
              Text('${day(start)} – ${day(end.subtract(const Duration(days:1)))}'),
              TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sorumlu, strateji veya hafta ara'),onChanged:(v)=>update(()=>query=v)),
              SwitchListTile(title:const Text('Yalnızca iyileşen işlemler'),value:onlyImproved,onChanged:(v)=>update(()=>onlyImproved=v)),
              SwitchListTile(title:const Text('Yalnızca sonrasında risk kalan işlemler'),value:onlyRisk,onChanged:(v)=>update(()=>onlyRisk=v)),
              const SizedBox(height:8),
              Text('Onaylı işlem: $total • İyileşen: $improved • Kötüleşen: $worsened • Risk devam eden: $ongoing'),
              Text('İyileşme oranı: ${total==0?'—':'${(100*improved/total).toStringAsFixed(1)}%'}'),
              Text('İşlem bazlı aşım: $totalBefore dk → $totalAfter dk • Net azalma: ${totalBefore-totalAfter} dk'),
              Text('Eksik/geçersiz önleyici kayıt: $invalid • Diğer optimizasyon türleri: $otherOperations'),
              const SizedBox(height:8),
              OutlinedButton.icon(onPressed:export,icon:const Icon(Icons.copy_outlined),label:const Text('CSV raporunu kopyala')),
              const Divider(),
              const Text('Haftalık sonuçlar',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),
              if (orderedWeeks.isEmpty) const Padding(padding:EdgeInsets.all(12),child:Text('Seçilen dönemde uygun onaylı önleyici optimizasyon kaydı bulunamadı.')),
              ...orderedWeeks.reversed.map((w) {
                final list = weekStats[w]!;
                final gain = list.fold<int>(0,(n,d)=>n+(d['gain'] as int));
                final success = list.where((d)=>(d['gain'] as int)>0).length;
                return ExpansionTile(title:Text('$w • ${list.length} işlem'),subtitle:Text('İyileşen: $success • Net aşım azalması: $gain dk'),children:[
                  ...list.map((d)=>ListTile(
                    title:Text('${d['strategy']} • ${d['count']} aksiyon'),
                    subtitle:Text('${(d['owners'] as List<String>).join(', ')}\n${d['before']} → ${d['after']} dk • Net: ${d['gain']} dk'),
                    isThreeLine:true,
                    trailing:Icon((d['gain'] as int)>0?Icons.trending_down:(d['gain'] as int)<0?Icons.trending_up:Icons.remove),
                  )),
                ]);
              }),
              const Divider(),
              const Text('Sorumlu bazında işlem sonuçları',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),
              ...((ownerStats.keys.toList()..sort()).map((owner) {
                final stat=ownerStats[owner]!;
                return ListTile(title:Text(owner),subtitle:Text('İlgili işlem: ${stat['operations']} • İyileşen: ${stat['improved']} • Sonrasında risk kalan: ${stat['risk']}'));
              })),
              const SizedBox(height:8),
              const Text('Not: Bir optimizasyon birden fazla sorumluyu etkileyebilir. Sorumlu sayıları toplam işlem sayısına eşit olmak zorunda değildir. İşlem bazlı kazanımlar toplanırsa aynı iş yükü birden çok kez sayılabilir. Geçmiş kayıtlar güncel iş yükünün veya gerçek zaman tasarrufunun kanıtı değildir.'),
              TextButton(onPressed:(){Navigator.pop(sheet);_showKitchenPreventiveCapacityActionPlan();},child:const Text('Onaylı önleyici aksiyon planına git')),
              TextButton(onPressed:(){Navigator.pop(sheet);_showKitchenActionOptimizationScorecard();},child:const Text('Genel aksiyon optimizasyon karnesini aç')),
            ],
          ])));
      }));
  }

  void _showKitchenPreventiveCapacityActionPlan() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    const preventiveKey = 'paket46_preventive_action_capacity_approvals_v1';
    final actions = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    final selected = <String>{};
    bool initialized = false, loading = true, saving = false, weekdaysOnly = true;
    int weeks = 4, budget = 45, maxChanges = 12, strategy = 2;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü';
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String quote(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    bool protected(Map<String, dynamic> a) => ['kritik', 'critical', 'yüksek', 'high'].contains(str(a['priority']).toLowerCase().trim());
    int minutes(Map<String, dynamic> a) => (estimates[str(a['id'])] ?? int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!initialized) {
          initialized = true;
          Future<void>.microtask(() async {
            try {
              final p = await SharedPreferences.getInstance();
              final raw = jsonDecode(p.getString(actionKey) ?? '[]');
              final saved = jsonDecode(p.getString(estimateKey) ?? '{}');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) for (final a in raw) { if (a is Map) actions.add(Map<String, dynamic>.from(a)); }
                if (saved is Map) { for (final e in saved.entries) {
                  final n = int.tryParse(str(e.value));
                  if (n != null && n >= 5 && n <= 480) estimates[str(e.key)] = n;
                } }
                loading = false;
              });
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Önleyici kapasite planı okunamadı: $e');
            }
          });
        }
        final start = monday(anchor), end = start.add(Duration(days: weeks * 7));
        final owners = <String>{...actions.map((a) => str(a['owner']).trim()).where((s) => s.isNotEmpty)}.toList()..sort();
        final ownerChoices = ['Tümü', ...owners];
        final weeklyBudget = budget * (weekdaysOnly ? 5 : 7);
        final loads = <String, int>{};
        final candidates = <Map<String, dynamic>>[];
        int missing = 0, protectedCount = 0;
        for (final a in actions) {
          if (!active(a)) continue;
          final d = date(a['due']), o = str(a['owner']).trim(), id = str(a['id']).trim();
          if (d == null || o.isEmpty || id.isEmpty) { missing++; continue; }
          if (d.isBefore(start) || !d.isBefore(end)) continue;
          final key = '$o|${iso(monday(d))}';
          loads[key] = (loads[key] ?? 0) + minutes(a);
          if (protected(a)) { protectedCount++; } else { candidates.add(a); }
        }
        int overflow(Map<String, int> m) => m.values.fold<int>(0, (sum, v) => sum + (v > weeklyBudget ? v - weeklyBudget : 0));
        final baseline = overflow(loads);
        final working = <String, int>{...loads};
        final proposals = <Map<String, dynamic>>[];
        candidates.sort((a, b) {
          final da = date(a['due'])!, db = date(b['due'])!;
          final ka = '${str(a['owner'])}|${iso(monday(da))}', kb = '${str(b['owner'])}|${iso(monday(db))}';
          final c = (working[kb] ?? 0).compareTo(working[ka] ?? 0);
          return c != 0 ? c : minutes(b).compareTo(minutes(a));
        });
        for (final a in candidates) {
          if (proposals.length >= maxChanges) break;
          final oldOwner = str(a['owner']).trim(), oldDate = date(a['due'])!;
          final oldKey = '$oldOwner|${iso(monday(oldDate))}';
          final duration = minutes(a);
          if ((working[oldKey] ?? 0) <= weeklyBudget) continue;
          String? bestOwner, bestDate;
          var bestGain = 0;
          for (final owner in owners) {
            for (var offset = 0; offset < weeks * 7; offset += 7) {
              final targetWeek = start.add(Duration(days: offset));
              final proposedDate = targetWeek.add(Duration(days: oldDate.weekday - 1));
              if (proposedDate.isBefore(DateTime(DateTime.now().year, DateTime.now().month, DateTime.now().day))) continue;
              if (strategy == 0 && owner != oldOwner) continue;
              if (strategy == 1 && !targetWeek.isAtSameMomentAs(monday(oldDate))) continue;
              if (owner == oldOwner && proposedDate.isAtSameMomentAs(DateTime(oldDate.year, oldDate.month, oldDate.day))) continue;
              final newKey = '$owner|${iso(targetWeek)}';
              if (newKey == oldKey) continue;
              final before = ((working[oldKey] ?? 0) - weeklyBudget).clamp(0, 9999999).toInt() +
                  ((working[newKey] ?? 0) - weeklyBudget).clamp(0, 9999999).toInt();
              final after = ((working[oldKey] ?? 0) - duration - weeklyBudget).clamp(0, 9999999).toInt() +
                  ((working[newKey] ?? 0) + duration - weeklyBudget).clamp(0, 9999999).toInt();
              final gain = before - after;
              if (gain > bestGain) {
                bestGain = gain; bestOwner = owner; bestDate = iso(proposedDate);
              }
            }
          }
          if (bestOwner == null || bestDate == null || bestGain <= 0) continue;
          final newKey = '$bestOwner|${iso(monday(date(bestDate)!))}';
          working[oldKey] = (working[oldKey] ?? 0) - duration;
          working[newKey] = (working[newKey] ?? 0) + duration;
          proposals.add(<String, dynamic>{
            'id': str(a['id']), 'title': str(a['title']), 'oldOwner': oldOwner,
            'newOwner': bestOwner, 'oldDate': str(a['due']), 'newDate': bestDate,
            'minutes': duration, 'gain': bestGain, 'priority': str(a['priority']),
          });
        }
        final chosen = proposals.where((a) => selected.contains(str(a['id']))).toList();
        final preview = <String, int>{...loads};
        for (final a in chosen) {
          final oldKey = '${a['oldOwner']}|${iso(monday(date(a['oldDate'])!))}';
          final newKey = '${a['newOwner']}|${iso(monday(date(a['newDate'])!))}';
          final n = a['minutes'] as int;
          preview[oldKey] = (preview[oldKey] ?? 0) - n;
          preview[newKey] = (preview[newKey] ?? 0) + n;
        }
        final after = overflow(preview);
        final visible = proposals.where((a) => ownerFilter == 'Tümü' || a['oldOwner'] == ownerFilter).toList();
        Future<void> exportCsv() async {
          final rows = <String>['Secili;Aksiyon;Eski sorumlu;Yeni sorumlu;Eski tarih;Yeni tarih;Dakika;Kapasite kazanci'];
          for (final a in visible) {
            rows.add([selected.contains(str(a['id'])) ? 'Evet' : 'Hayır', a['title'], a['oldOwner'], a['newOwner'], a['oldDate'], a['newDate'], a['minutes'], a['gain']].map(quote).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: rows.join('\n')));
          if (mounted) _notice('Önleyici aksiyon önerileri CSV olarak kopyalandı.');
        }
        Future<void> approve() async {
          if (saving || chosen.isEmpty) return;
          final ok = await showDialog<bool>(context: sheet, builder: (d) => AlertDialog(
            title: const Text('Önleyici aksiyon planını onayla'),
            content: Text('${chosen.length} aksiyonun sorumlusu veya tarihi güncellenecek. Haftalık kapasite aşımı $baseline dk → $after dk. Bu işlem kayıtlı aksiyon planını değiştirir.'),
            actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Onayla ve uygula'))],
          ));
          if (ok != true || !sheet.mounted) return;
          update(() => saving = true);
          try {
            final prefs = await SharedPreferences.getInstance();
            final raw = prefs.getString(actionKey) ?? '[]';
            final decoded = jsonDecode(raw);
            if (decoded is! List) throw StateError('Aksiyon listesi geçersiz');
            final current = <Map<String, dynamic>>[];
            for (final x in decoded) { if (x is Map) current.add(Map<String, dynamic>.from(x)); }
            final ids = <String>{};
            for (final change in chosen) {
              final id = str(change['id']);
              final matches = current.where((a) => str(a['id']) == id).toList();
              if (matches.length != 1 || !ids.add(id)) throw StateError('Aksiyon kimliği eşleşmedi: $id');
              final a = matches.single;
              if (!active(a) || protected(a) || str(a['owner']) != change['oldOwner'] || str(a['due']) != change['oldDate'] || minutes(a) != change['minutes']) {
                throw StateError('Aksiyon değişmiş; ekranı yeniden açın: $id');
              }
            }
            final oldPlan = jsonEncode(current);
            for (final change in chosen) {
              final a = current.firstWhere((x) => str(x['id']) == str(change['id']));
              a['owner'] = change['newOwner']; a['due'] = change['newDate'];
            }
            final rawHistory = jsonDecode(prefs.getString(historyKey) ?? '[]');
            final rawPreventive = jsonDecode(prefs.getString(preventiveKey) ?? '[]');
            if (rawHistory is! List || rawPreventive is! List) throw StateError('Geçmiş kayıtları geçersiz');
            final at = DateTime.now().toIso8601String();
            final record = <String, dynamic>{
              'at': at, 'strategy': ['Tarih', 'Sorumlu', 'Karma'][strategy],
              'beforeExcessMinutes': baseline, 'afterExcessMinutes': after,
              'dailyActionBudget': budget, 'weekdaysOnly': weekdaysOnly,
              'changes': chosen.map((x) => Map<String, dynamic>.from(x)).toList(),
              'previousPlan': oldPlan, 'source': 'preventive_capacity_action_plan',
            };
            final oldHistory = prefs.getString(historyKey);
            final oldPreventive = prefs.getString(preventiveKey);
            rawHistory.add(record);
            rawPreventive.add(<String, dynamic>{'at': at, 'count': chosen.length,
              'before': baseline, 'after': after, 'strategy': record['strategy']});
            if (!await prefs.setString(historyKey, jsonEncode(rawHistory))) throw StateError('Optimizasyon geçmişi yazılamadı');
            if (!await prefs.setString(preventiveKey, jsonEncode(rawPreventive))) {
              if (oldHistory == null) { await prefs.remove(historyKey); } else { await prefs.setString(historyKey, oldHistory); }
              throw StateError('Önleyici işlem geçmişi yazılamadı');
            }
            if (!await prefs.setString(actionKey, jsonEncode(current))) {
              if (oldHistory == null) { await prefs.remove(historyKey); } else { await prefs.setString(historyKey, oldHistory); }
              if (oldPreventive == null) { await prefs.remove(preventiveKey); } else { await prefs.setString(preventiveKey, oldPreventive); }
              throw StateError('Aksiyonlar kaydedilemedi');
            }
            if (sheet.mounted) update(() { actions..clear()..addAll(current); selected.clear(); saving = false; });
            if (mounted) _notice('${chosen.length} önleyici aksiyon değişikliği kaydedildi.');
          } catch (e) {
            if (sheet.mounted) update(() => saving = false);
            if (mounted) _notice('Önleyici plan uygulanamadı: $e');
          }
        }
        return SafeArea(child: SizedBox(height: MediaQuery.of(sheet).size.height * .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Önleyici kapasite aksiyonları / onaylı risk azaltma', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const Text('Aşırı dolu aksiyon haftaları için alternatif tarih ve sorumlu önerileri. Seçim ve açık onay olmadan kayıtlar değişmez.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
                DropdownButton<int>(value: weeks, items: [1,2,4,8,12].map((v) => DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(), onChanged: (v) => update(() { weeks = v ?? 4; selected.clear(); })),
                DropdownButton<int>(value: budget, items: [15,30,45,60,90,120,180].map((v) => DropdownMenuItem(value: v, child: Text('$v dk/gün'))).toList(), onChanged: (v) => update(() { budget = v ?? 45; selected.clear(); })),
                DropdownButton<int>(value: strategy, items: const [DropdownMenuItem(value: 0, child: Text('Tarih')), DropdownMenuItem(value: 1, child: Text('Sorumlu')), DropdownMenuItem(value: 2, child: Text('Karma'))], onChanged: (v) => update(() { strategy = v ?? 2; selected.clear(); })),
                DropdownButton<int>(value: maxChanges, items: [5,10,12,20,40].map((v) => DropdownMenuItem(value: v, child: Text('En fazla $v'))).toList(), onChanged: (v) => update(() { maxChanges = v ?? 12; selected.clear(); })),
                DropdownButton<String>(value: ownerChoices.contains(ownerFilter) ? ownerFilter : 'Tümü', items: ownerChoices.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
                OutlinedButton(onPressed: () => update(() { anchor = anchor.subtract(Duration(days: weeks * 7)); selected.clear(); }), child: const Text('Önceki')),
                OutlinedButton(onPressed: () => update(() { anchor = DateTime.now(); selected.clear(); }), child: const Text('Bugün')),
                OutlinedButton(onPressed: () => update(() { anchor = anchor.add(Duration(days: weeks * 7)); selected.clear(); }), child: const Text('Sonraki')),
              ]),
              SwitchListTile(title: const Text('Hafta içi kapasitesi (5 gün)'), value: weekdaysOnly, onChanged: (v) => update(() { weekdaysOnly = v; selected.clear(); })),
              Text('Dönem: ${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))} • Haftalık kişi kapasitesi: $weeklyBudget dk'),
              Text('Mevcut aşım: $baseline dk • Seçilenler sonrası: $after dk • Öngörülen azalma: ${baseline - after} dk', style: const TextStyle(fontWeight: FontWeight.bold)),
              Text('${proposals.length} öneri • ${chosen.length} seçili • $protectedCount korunan kritik/yüksek aksiyon • $missing eksik kayıt'),
              Wrap(spacing: 8, children: [
                OutlinedButton(onPressed: () => update(() => selected.addAll(visible.map((a) => str(a['id'])))), child: const Text('Görünenleri seç')),
                OutlinedButton(onPressed: () => update(() => selected.clear()), child: const Text('Seçimi temizle')),
                OutlinedButton.icon(onPressed: exportCsv, icon: const Icon(Icons.copy_outlined), label: const Text('CSV kopyala')),
              ]),
              if (visible.isEmpty) const Padding(padding: EdgeInsets.all(16), child: Text('Bu koşullarda kapasite aşımını azaltan uygun öneri bulunamadı.')),
              ...visible.map((a) => CheckboxListTile(
                value: selected.contains(str(a['id'])),
                onChanged: (v) => update(() { if (v == true) { selected.add(str(a['id'])); } else { selected.remove(str(a['id'])); } }),
                title: Text(str(a['title']).isEmpty ? 'Başlıksız aksiyon' : str(a['title'])),
                subtitle: Text('${a['oldOwner']} / ${a['oldDate']} → ${a['newOwner']} / ${a['newDate']} • ${a['minutes']} dk • ${a['gain']} dk tahmini kazanım'),
              )),
              FilledButton.icon(onPressed: saving || chosen.isEmpty ? null : approve,
                icon: const Icon(Icons.verified_outlined), label: Text(saving ? 'Kaydediliyor...' : '${chosen.length} değişikliği onayla ve uygula')),
              const SizedBox(height: 12),
              const Text('Uyarı: Öneriler yalnızca haftalık toplam kapasite aşımını azaltır. Gerçek müsaitlik, görev yetkinliği ve son teslim zorunlulukları doğrulanmaz. Tarihi geçmiş güne taşıma önerilmez. Eksik süre 30 dakika kabul edilir.'),
              TextButton(onPressed: () { Navigator.pop(sheet); _showKitchenRecurringActionRiskCenter(); }, child: const Text('Tekrarlayan risk analizine dön')),
              TextButton(onPressed: () { Navigator.pop(sheet); _showKitchenActionOptimizationScorecard(); }, child: const Text('Optimizasyon başarı karnesine geç')),
            ],
          ])));
      }));
  }

  void _showKitchenRecurringActionRiskCenter() {
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    final history = <Map<String, dynamic>>[];
    final actions = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    bool started = false, loading = true, risksOnly = true;
    int weeks = 12, repeatThreshold = 2, dailyBudget = 45, addedMinutes = 0;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü', search = '';
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    int duration(Map<String, dynamic> a) => (estimates[str(a['id'])] ?? int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final rawHistory = jsonDecode(prefs.getString(historyKey) ?? '[]');
              final rawActions = jsonDecode(prefs.getString(actionKey) ?? '[]');
              final rawEstimates = jsonDecode(prefs.getString(estimateKey) ?? '{}');
              if (!sheet.mounted) return;
              update(() {
                if (rawHistory is List) for (final x in rawHistory) { if (x is Map) history.add(Map<String, dynamic>.from(x)); }
                if (rawActions is List) for (final x in rawActions) { if (x is Map) actions.add(Map<String, dynamic>.from(x)); }
                if (rawEstimates is Map) { for (final e in rawEstimates.entries) {
                  final v = int.tryParse(str(e.value));
                  if (v != null && v >= 5 && v <= 480) estimates[str(e.key)] = v;
                } }
                loading = false;
              });
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Kapasite risk kayıtları okunamadı: $e');
            }
          });
        }
        final start = monday(anchor).subtract(Duration(days: (weeks - 1) * 7));
        final end = monday(anchor).add(const Duration(days: 7));
        final historical = <String, Set<String>>{};
        final historicalMinutes = <String, int>{};
        int invalidHistory = 0;
        for (final record in history) {
          final at = parse(record['at']);
          if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
          try {
            final raw = jsonDecode(str(record['previousPlan']));
            final changes = record['changes'];
            final daily = int.tryParse(str(record['dailyActionBudget']));
            if (raw is! List || changes is! List || daily == null || daily <= 0) { invalidHistory++; continue; }
            final after = <Map<String, dynamic>>[];
            for (final x in raw) { if (x is Map) after.add(Map<String, dynamic>.from(x)); }
            for (final change in changes) {
              if (change is! Map) throw const FormatException('Geçersiz değişiklik');
              final matching = after.where((a) => str(a['id']) == str(change['id'])).toList();
              if (matching.length != 1) throw const FormatException('Aksiyon eşleşmedi');
              if (str(matching.single['owner']) != str(change['oldOwner']) || str(matching.single['due']) != str(change['oldDate'])) throw const FormatException('Kaynak uyuşmadı');
              matching.single['owner'] = change['newOwner'];
              matching.single['due'] = change['newDate'];
            }
            final loads = <String, int>{};
            for (final a in after) {
              if (!active(a)) continue;
              final d = parse(a['due']); final owner = str(a['owner']).trim();
              if (d == null || owner.isEmpty) continue;
              final key = '$owner|${iso(monday(d))}';
              loads[key] = (loads[key] ?? 0) + (int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
            }
            final budget = daily * (record['weekdaysOnly'] == false ? 7 : 5);
            for (final entry in loads.entries) {
              final extra = entry.value - budget;
              if (extra <= 0) continue;
              final owner = entry.key.split('|').first;
              historical.putIfAbsent(owner, () => <String>{}).add('${record['at']}|${entry.key}');
              historicalMinutes[owner] = (historicalMinutes[owner] ?? 0) + extra;
            }
          } catch (_) { invalidHistory++; }
        }
        final loads = <String, int>{};
        final counts = <String, int>{};
        int invalidActions = 0, assumed = 0;
        for (final a in actions) {
          if (!active(a)) continue;
          final d = parse(a['due']); final owner = str(a['owner']).trim();
          if (d == null || owner.isEmpty) { invalidActions++; continue; }
          if (d.isBefore(start) || !d.isBefore(end)) continue;
          if (!estimates.containsKey(str(a['id'])) && int.tryParse(str(a['estimatedMinutes'])) == null) assumed++;
          final key = '$owner|${iso(monday(d))}';
          loads[key] = (loads[key] ?? 0) + duration(a);
          counts[key] = (counts[key] ?? 0) + 1;
        }
        final owners = <String>{...historical.keys, ...loads.keys.map((k) => k.split('|').first)}.toList()..sort();
        final budget = dailyBudget * 5;
        final scenarioBudget = (dailyBudget + addedMinutes) * 5;
        final rows = <Map<String, dynamic>>[];
        for (final entry in loads.entries) {
          final owner = entry.key.split('|').first;
          final week = entry.key.substring(owner.length + 1);
          final excess = entry.value > budget ? entry.value - budget : 0;
          final simulated = entry.value > scenarioBudget ? entry.value - scenarioBudget : 0;
          rows.add({'owner': owner, 'week': week, 'minutes': entry.value, 'count': counts[entry.key] ?? 0,
            'excess': excess, 'scenario': simulated, 'recurring': historical[owner]?.length ?? 0});
        }
        rows.sort((a, b) => (b['excess'] as int).compareTo(a['excess'] as int));
        final filtered = rows.where((r) => (ownerFilter == 'Tümü' || r['owner'] == ownerFilter) &&
          (!risksOnly || (r['excess'] as int) > 0 || (r['recurring'] as int) >= repeatThreshold) &&
          (search.trim().isEmpty || '${r['owner']} ${r['week']}'.toLowerCase().contains(search.trim().toLowerCase()))).toList();
        final totalExcess = filtered.fold<int>(0, (n, r) => n + (r['excess'] as int));
        final simulatedExcess = filtered.fold<int>(0, (n, r) => n + (r['scenario'] as int));
        final recurringOwners = owners.where((o) => (historical[o]?.length ?? 0) >= repeatThreshold).length;
        Future<void> exportCsv() async {
          final lines = <String>['Sorumlu,Hafta,Aksiyon,Planlanan dakika,Kapasite asimi,Senaryo asimi,Gecmis riskli islem'];
          for (final r in filtered) {
            lines.add([r['owner'], r['week'], r['count'], r['minutes'], r['excess'], r['scenario'], r['recurring']].map(csv).join(','));
          }
          await Clipboard.setData(ClipboardData(text: '\uFEFF${lines.join('\n')}'));
          if (mounted) _notice('Önleyici kapasite risk raporu kopyalandı.');
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: ListView(padding: const EdgeInsets.all(16), children: [
          const Text('Tekrarlayan Aksiyon Kapasite Riskleri', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          const Text('Onaylı optimizasyon geçmişindeki tekrarlar ile güncel haftalık aksiyon yükünü birlikte değerlendirir. Kapasite senaryosu kayıtları değiştirmez.'),
          if (loading) const LinearProgressIndicator(),
          Wrap(spacing: 8, runSpacing: 8, children: [
            DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((v) => DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(), onChanged: (v) { if (v != null) update(() => weeks = v); }),
            DropdownButton<int>(value: repeatThreshold, items: [2, 3, 4, 5].map((v) => DropdownMenuItem(value: v, child: Text('$v tekrar'))).toList(), onChanged: (v) { if (v != null) update(() => repeatThreshold = v); }),
            DropdownButton<int>(value: dailyBudget, items: [15, 30, 45, 60, 90, 120, 180].map((v) => DropdownMenuItem(value: v, child: Text('$v dk/gün'))).toList(), onChanged: (v) { if (v != null) update(() => dailyBudget = v); }),
            DropdownButton<int>(value: addedMinutes, items: [0, 15, 30, 45, 60].map((v) => DropdownMenuItem(value: v, child: Text('Ek +$v dk/gün'))).toList(), onChanged: (v) { if (v != null) update(() => addedMinutes = v); }),
            DropdownButton<String>(value: owners.contains(ownerFilter) ? ownerFilter : 'Tümü', items: ['Tümü', ...owners].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) { if (v != null) update(() => ownerFilter = v); }),
          ]),
          Wrap(spacing: 8, children: [
            IconButton(tooltip: 'Önceki dönem', onPressed: () => update(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)),
            TextButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün')),
            IconButton(tooltip: 'Sonraki dönem', onPressed: () => update(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)),
            Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
          ]),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sorumlu / hafta ara'), onChanged: (v) => update(() => search = v)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('Yalnızca riskli veya tekrarlayan kayıtlar'), value: risksOnly, onChanged: (v) => update(() => risksOnly = v)),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('İncelenen sorumlu-hafta: ${filtered.length}'),
            Text('Mevcut kapasite aşımı: $totalExcess dk'),
            Text('Senaryo kapasite aşımı: $simulatedExcess dk'),
            Text('Varsayımsal azalma: ${totalExcess - simulatedExcess} dk'),
            Text('Tekrarlayan risk görülen sorumlu: $recurringOwners'),
            Text('Eksik/geçersiz geçmiş: $invalidHistory · Eksik aksiyon: $invalidActions · Varsayılan süre: $assumed'),
          ]))),
          if (filtered.isEmpty && !loading) const ListTile(title: Text('Seçilen dönemde eşleşen risk kaydı bulunamadı.')),
          for (final r in filtered.take(100)) Card(child: ListTile(
            leading: Icon((r['excess'] as int) > 0 ? Icons.warning_amber_rounded : Icons.check_circle_outline),
            title: Text('${r['owner']} · ${r['week']}'),
            subtitle: Text('${r['count']} aksiyon · ${r['minutes']} dk iş yükü · Aşım ${r['excess']} → ${r['scenario']} dk\nGeçmişte riskli optimizasyon-sorumlu-hafta kaydı: ${r['recurring']}'),
            isThreeLine: true,
            trailing: (r['recurring'] as int) >= repeatThreshold ? const Icon(Icons.repeat) : null,
          )),
          const SizedBox(height: 12),
          const Text('Önleyici aksiyon önerileri', style: TextStyle(fontWeight: FontWeight.bold)),
          if (totalExcess > 0) const ListTile(leading: Icon(Icons.event_repeat), title: Text('Yoğun haftalardaki düşük öncelikli aksiyonları başka haftalara dağıtmayı değerlendirin.')),
          if (recurringOwners > 0) const ListTile(leading: Icon(Icons.groups_outlined), title: Text('Tekrarlayan riskli sorumluların aksiyonlarını uygun kişilere yeniden dağıtmayı değerlendirin.')),
          if (assumed > 0 || invalidActions > 0) const ListTile(leading: Icon(Icons.fact_check_outlined), title: Text('Eksik tarih, sorumlu veya tahmini süre kayıtlarını tamamlayın.')),
          const Text('Not: Geçmiş tekrarlar optimizasyon işlem kayıtlarına dayanır; aynı haftadaki işlemler ayrı sayılabilir. +Dakika senaryosu gerçek kapasite artışı veya otomatik görev değişikliği değildir.'),
          Wrap(spacing: 8, runSpacing: 8, children: [
            FilledButton.tonalIcon(onPressed: exportCsv, icon: const Icon(Icons.copy_all_outlined), label: const Text('CSV kopyala')),
            OutlinedButton.icon(onPressed: () { Navigator.pop(sheet); _showKitchenApprovedActionCapacityOptimizer(); }, icon: const Icon(Icons.tune), label: const Text('Onaylı optimizasyona geç')),
            OutlinedButton.icon(onPressed: () { Navigator.pop(sheet); _showKitchenPreventiveActionTracker(); }, icon: const Icon(Icons.task_alt), label: const Text('Aksiyon planına geç')),
          ]),
        ])));
      }));
  }

  void _showKitchenActionOptimizationRiskTrends() {
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    final history = <Map<String, dynamic>>[];
    bool started = false, loading = true, onlyRecurring = false, onlyWorse = false;
    int weeks = 12, repeatThreshold = 2;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü', query = '';
    String str(Object? value) => '${value ?? ''}';
    DateTime? parse(Object? value) => DateTime.tryParse(str(value));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String day(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? value) => '"${str(value).replaceAll('"', '""')}"';
    int duration(Map<String, dynamic> a) => (int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final raw = jsonDecode(prefs.getString(historyKey) ?? '[]');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) {
                  for (final item in raw) {
                    if (item is Map) history.add(Map<String, dynamic>.from(item));
                  }
                }
                loading = false;
              });
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Aksiyon optimizasyon geçmişi okunamadı: $e');
            }
          });
        }
        final start = monday(anchor).subtract(Duration(days: (weeks - 1) * 7));
        final end = monday(anchor).add(const Duration(days: 7));
        final entries = <Map<String, dynamic>>[];
        int invalid = 0, assumed = 0;
        final ownerNames = <String>{};
        for (final record in history) {
          final at = parse(record['at']);
          if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
          try {
            final original = jsonDecode(str(record['previousPlan']));
            final changesRaw = record['changes'];
            final daily = int.tryParse(str(record['dailyActionBudget']));
            if (original is! List || changesRaw is! List || changesRaw.isEmpty || daily == null || daily <= 0) { invalid++; continue; }
            final before = <Map<String, dynamic>>[];
            for (final item in original) { if (item is Map) before.add(Map<String, dynamic>.from(item)); }
            final after = before.map((a) => Map<String, dynamic>.from(a)).toList();
            final changes = <Map<String, dynamic>>[];
            for (final item in changesRaw) { if (item is Map) changes.add(Map<String, dynamic>.from(item)); }
            if (changes.length != changesRaw.length || changes.isEmpty) { invalid++; continue; }
            for (final change in changes) {
              final id = str(change['id']);
              final matches = after.where((a) => str(a['id']) == id).toList();
              if (id.isEmpty || matches.length != 1) throw const FormatException('Kimlik eşleşmedi');
              final action = matches.single;
              if (str(action['owner']) != str(change['oldOwner']) || str(action['due']) != str(change['oldDate'])) throw const FormatException('Eski kayıt uyuşmadı');
              action['owner'] = change['newOwner'];
              action['due'] = change['newDate'];
            }
            final budget = daily * (record['weekdaysOnly'] == false ? 7 : 5);
            Map<String, int> loads(List<Map<String, dynamic>> plan) {
              final result = <String, int>{};
              for (final action in plan) {
                if (!active(action)) continue;
                final due = parse(action['due']);
                final owner = str(action['owner']).trim();
                if (due == null || owner.isEmpty) continue;
                if (int.tryParse(str(action['estimatedMinutes'])) == null) assumed++;
                final key = '$owner|${day(monday(due))}';
                result[key] = (result[key] ?? 0) + duration(action);
              }
              return result;
            }
            final oldLoad = loads(before), newLoad = loads(after);
            final owners = <String>{};
            for (final key in {...oldLoad.keys, ...newLoad.keys}) { owners.add(key.split('|').first); }
            for (final owner in owners) {
              final oldTotal = oldLoad.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (n, e) => n + e.value);
              final newTotal = newLoad.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (n, e) => n + e.value);
              final oldRisk = oldLoad.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (n, e) => n + (e.value > budget ? e.value - budget : 0));
              final newRisk = newLoad.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (n, e) => n + (e.value > budget ? e.value - budget : 0));
              ownerNames.add(owner);
              entries.add({'at': at, 'week': day(monday(at)), 'owner': owner, 'strategy': str(record['strategy']),
                'before': oldRisk, 'after': newRisk, 'gain': oldRisk - newRisk, 'oldLoad': oldTotal,
                'newLoad': newTotal, 'changes': changes.length});
            }
          } catch (_) { invalid++; }
        }
        final ownerOptions = ['Tümü', ...ownerNames.toList()..sort()];
        final matching = entries.where((e) => (ownerFilter == 'Tümü' || e['owner'] == ownerFilter) &&
          (query.trim().isEmpty || '${e['owner']} ${e['strategy']} ${e['week']}'.toLowerCase().contains(query.trim().toLowerCase()))).toList();
        final recurrence = <String, int>{};
        for (final e in matching) {
          if ((e['after'] as int) > 0) recurrence[e['owner'] as String] = (recurrence[e['owner'] as String] ?? 0) + 1;
        }
        final filtered = matching.where((e) => (!onlyRecurring || (recurrence[e['owner']] ?? 0) >= repeatThreshold) &&
          (!onlyWorse || (e['gain'] as int) < 0)).toList();
        final weekly = <String, List<Map<String, dynamic>>>{};
        for (final e in filtered) { weekly.putIfAbsent(e['week'] as String, () => <Map<String, dynamic>>[]).add(e); }
        final keys = weekly.keys.toList()..sort();
        final gain = filtered.fold<int>(0, (n, e) => n + (e['gain'] as int));
        final improved = filtered.where((e) => (e['gain'] as int) > 0).length;
        final worsening = filtered.where((e) => (e['gain'] as int) < 0).length;
        final risky = filtered.where((e) => (e['after'] as int) > 0).length;
        Future<void> export() async {
          final rows = <String>['Hafta;Islem tarihi;Sorumlu;Strateji;Onceki asim dk;Sonraki asim dk;Net iyilesme dk;Onceki yuk dk;Sonraki yuk dk;Degisen aksiyon;Risk tekrar sayisi'];
          for (final e in filtered) {
            rows.add([e['week'], day(e['at'] as DateTime), e['owner'], e['strategy'], e['before'], e['after'], e['gain'],
              e['oldLoad'], e['newLoad'], e['changes'], recurrence[e['owner']] ?? 0].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: rows.join('\n')));
          if (mounted) _notice('Haftalık aksiyon optimizasyon trendleri CSV olarak kopyalandı.');
        }
        return SafeArea(child: SizedBox(height: MediaQuery.of(sheet).size.height * .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Aksiyon optimizasyonu / performans trendleri ve tekrarlayan kapasite riskleri',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const Text('Onaylı optimizasyon geçmişindeki işlem öncesi ve sonrası haftalık aksiyon yükü karşılaştırılır. Aynı sorumlu farklı işlemlerde yeniden riskli kalırsa tekrar olarak sayılır.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 8, children: [
                DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((v) => DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(), onChanged: (v) => update(() => weeks = v ?? 12)),
                DropdownButton<String>(value: ownerOptions.contains(ownerFilter) ? ownerFilter : 'Tümü', items: ownerOptions.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
                DropdownButton<int>(value: repeatThreshold, items: [2, 3, 4, 5].map((v) => DropdownMenuItem(value: v, child: Text('$v tekrar'))).toList(), onChanged: (v) => update(() => repeatThreshold = v ?? 2)),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: weeks * 7))), child: const Text('Önceki')),
                OutlinedButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün')),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: weeks * 7))), child: const Text('Sonraki')),
              ]),
              Text('${day(start)} – ${day(end.subtract(const Duration(days: 1)))}'),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sorumlu, strateji veya hafta ara'), onChanged: (v) => update(() => query = v)),
              SwitchListTile(title: const Text('Yalnızca tekrarlayan riskli sorumlular'), value: onlyRecurring, onChanged: (v) => update(() => onlyRecurring = v)),
              SwitchListTile(title: const Text('Yalnızca kötüleşen sonuçlar'), value: onlyWorse, onChanged: (v) => update(() => onlyWorse = v)),
              Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${filtered.length} sorumlu-işlem kaydı • $improved iyileşen • $worsening kötüleşen'),
                Text('İyileşme oranı: ${filtered.isEmpty ? '—' : '${(improved * 100 / filtered.length).toStringAsFixed(1)}%'}'),
                Text('Net işlem bazlı kapasite aşımı azalması: $gain dk • Sonrasında riskli kalan: $risky'),
                Text('${recurrence.values.where((v) => v >= repeatThreshold).length} sorumluda tekrarlayan risk • $invalid okunamayan işlem • $assumed süre varsayımı'),
              ]))),
              OutlinedButton.icon(onPressed: export, icon: const Icon(Icons.copy_outlined), label: const Text('CSV raporunu kopyala')),
              if (recurrence.isNotEmpty) Card(child: ExpansionTile(title: const Text('Tekrarlayan riskli sorumlular'),
                children: (recurrence.entries.toList()..sort((a, b) => b.value.compareTo(a.value))).where((e) => e.value >= repeatThreshold)
                  .map((e) => ListTile(title: Text(e.key), subtitle: Text('${e.value} optimizasyon sonrasında kapasite aşımı sürüyor'),
                    trailing: const Icon(Icons.warning_amber_outlined))).toList())),
              if (filtered.isEmpty) const Padding(padding: EdgeInsets.all(16), child: Text('Seçilen dönemde ve filtrelerde uygun optimizasyon kaydı yok.')),
              ...keys.reversed.map((key) {
                final rows = weekly[key]!;
                final weekGain = rows.fold<int>(0, (n, e) => n + (e['gain'] as int));
                final weekImproved = rows.where((e) => (e['gain'] as int) > 0).length;
                return Card(child: ExpansionTile(
                  title: Text('$key haftası • ${rows.length} sorumlu-işlem'),
                  subtitle: Text('$weekImproved iyileşen • Net aşım azalması $weekGain dk'),
                  children: rows.map((e) => ListTile(
                    title: Text('${e['owner']} • ${e['strategy']}'),
                    subtitle: Text('${day(e['at'] as DateTime)} • Aşım ${e['before']} → ${e['after']} dk • Fark ${e['gain']} dk\nİş yükü ${e['oldLoad']} → ${e['newLoad']} dk • Risk tekrar: ${recurrence[e['owner']] ?? 0}'),
                  )).toList(),
                ));
              }),
              const SizedBox(height: 12),
              const Text('Yorumlama: Tekrar sayısı bağımsız riskli hafta sayısı değildir; aynı sorumlu aynı hafta birden fazla işlemde sayılabilir. Sonuçlar işlem bazlı plan karşılaştırmasıdır; gerçek zaman tasarrufu veya nedensel etki kanıtı değildir. Eski kayıtlarda eksik süreler 30 dk varsayılır.'),
              FilledButton.tonalIcon(onPressed: _showKitchenActionOptimizationScorecard, icon: const Icon(Icons.insights_outlined), label: const Text('Aksiyon optimizasyonu başarı karnesi')),
              FilledButton.tonalIcon(onPressed: _showKitchenApprovedActionCapacityOptimizer, icon: const Icon(Icons.rule_folder_outlined), label: const Text('Onaylı aksiyon kapasite optimizasyonu')),
            ],
          ])));
      }));
  }

  void _showKitchenActionOptimizationScorecard() {
    const historyKey = 'paket45_action_capacity_optimization_history_v1';
    const estimateKey = 'paket44_weekly_action_estimates_v1';
    final records = <Map<String, dynamic>>[];
    final estimates = <String, int>{};
    bool started = false, loading = true, improvementsOnly = false, riskOnly = false;
    int weeks = 12;
    DateTime anchor = DateTime.now();
    String ownerFilter = 'Tümü', search = '';
    String str(Object? value) => '${value ?? ''}';
    DateTime? parse(Object? value) => DateTime.tryParse(str(value));
    DateTime monday(DateTime value) => DateTime(value.year, value.month, value.day).subtract(Duration(days: value.weekday - 1));
    String day(DateTime value) => '${value.year}-${value.month.toString().padLeft(2, '0')}-${value.day.toString().padLeft(2, '0')}';
    String csv(Object? value) => '"${str(value).replaceAll('"', '""')}"';
    bool open(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    int minutes(Map<String, dynamic> a) => (estimates[str(a['id'])] ?? int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final raw = jsonDecode(prefs.getString(historyKey) ?? '[]');
              final saved = jsonDecode(prefs.getString(estimateKey) ?? '{}');
              if (!sheet.mounted) return;
              update(() {
                if (raw is List) {
                  for (final item in raw) {
                    if (item is Map) records.add(Map<String, dynamic>.from(item));
                  }
                }
                if (saved is Map) {
                  for (final entry in saved.entries) {
                    final value = int.tryParse(str(entry.value));
                    if (value != null && value >= 5 && value <= 480) estimates[str(entry.key)] = value;
                  }
                }
                loading = false;
              });
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Optimizasyon geçmişi okunamadı: $e');
            }
          });
        }
        final start = monday(anchor).subtract(Duration(days: (weeks - 1) * 7));
        final end = monday(anchor).add(const Duration(days: 7));
        final details = <Map<String, dynamic>>[];
        final owners = <String>{};
        int invalid = 0, missingDurations = 0;
        for (final record in records) {
          final at = parse(record['at']);
          if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
          try {
            final decoded = jsonDecode(str(record['previousPlan']));
            final changesRaw = record['changes'];
            if (decoded is! List || changesRaw is! List) { invalid++; continue; }
            final beforePlan = <Map<String, dynamic>>[];
            for (final item in decoded) {
              if (item is Map) beforePlan.add(Map<String, dynamic>.from(item));
            }
            final afterPlan = beforePlan.map((a) => Map<String, dynamic>.from(a)).toList();
            final changes = <Map<String, dynamic>>[];
            for (final item in changesRaw) {
              if (item is Map) changes.add(Map<String, dynamic>.from(item));
            }
            if (changes.isEmpty) { invalid++; continue; }
            for (final change in changes) {
              final matches = afterPlan.where((a) => str(a['id']) == str(change['id'])).toList();
              if (matches.length != 1 || str(change['id']).isEmpty) throw const FormatException('Geçersiz aksiyon kimliği');
              final target = matches.single;
              if (str(target['owner']) != str(change['oldOwner']) || str(target['due']) != str(change['oldDate'])) {
                throw const FormatException('Eski aksiyon planı uyuşmuyor');
              }
              target['owner'] = change['newOwner'];
              target['due'] = change['newDate'];
              owners.add(str(change['oldOwner']));
              owners.add(str(change['newOwner']));
            }
            final daily = int.tryParse(str(record['dailyActionBudget']));
            if (daily == null || daily <= 0) { invalid++; continue; }
            final budget = daily * (record['weekdaysOnly'] == false ? 7 : 5);
            Map<String, int> load(List<Map<String, dynamic>> plan) {
              final output = <String, int>{};
              for (final action in plan) {
                if (!open(action)) continue;
                final due = parse(action['due']);
                final owner = str(action['owner']).trim();
                if (due == null || owner.isEmpty) continue;
                final key = '$owner|${day(monday(due))}';
                output[key] = (output[key] ?? 0) + minutes(action);
              }
              return output;
            }
            for (final change in changes) {
              final id = str(change['id']);
              if (!estimates.containsKey(id) && beforePlan.any((a) => str(a['id']) == id && int.tryParse(str(a['estimatedMinutes'])) == null)) missingDurations++;
            }
            final before = load(beforePlan), after = load(afterPlan);
            int excess(Map<String, int> data) => data.values.fold<int>(0, (total, value) => total + (value > budget ? value - budget : 0));
            final oldExcess = excess(before), newExcess = excess(after);
            final byOwner = <String, Map<String, int>>{};
            for (final owner in {...before.keys.map((k) => k.split('|').first), ...after.keys.map((k) => k.split('|').first)}) {
              final oldLoad = before.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (sum, e) => sum + e.value);
              final newLoad = after.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (sum, e) => sum + e.value);
              final oldRisk = before.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (sum, e) => sum + (e.value > budget ? e.value - budget : 0));
              final newRisk = after.entries.where((e) => e.key.startsWith('$owner|')).fold<int>(0, (sum, e) => sum + (e.value > budget ? e.value - budget : 0));
              byOwner[owner] = {'before': oldLoad, 'after': newLoad, 'oldRisk': oldRisk, 'newRisk': newRisk};
            }
            details.add({'at': at, 'strategy': str(record['strategy']), 'changes': changes.length,
              'before': oldExcess, 'after': newExcess, 'gain': oldExcess - newExcess,
              'owners': byOwner, 'budget': budget});
          } catch (_) { invalid++; }
        }
        details.sort((a, b) => (b['at'] as DateTime).compareTo(a['at'] as DateTime));
        final ownerOptions = ['Tümü', ...owners.where((x) => x.trim().isNotEmpty).toList()..sort()];
        final filtered = details.where((r) {
          final byOwner = r['owners'] as Map<String, Map<String, int>>;
          if (ownerFilter != 'Tümü' && !byOwner.containsKey(ownerFilter)) return false;
          if (improvementsOnly && (r['gain'] as int) <= 0) return false;
          if (riskOnly && (r['after'] as int) <= 0) return false;
          final q = search.trim().toLowerCase();
          return q.isEmpty || str(r['strategy']).toLowerCase().contains(q) ||
            day(r['at'] as DateTime).contains(q) || byOwner.keys.any((x) => x.toLowerCase().contains(q));
        }).toList();
        final improved = filtered.where((r) => (r['gain'] as int) > 0).length;
        final worsened = filtered.where((r) => (r['gain'] as int) < 0).length;
        final netGain = filtered.fold<int>(0, (sum, r) => sum + (r['gain'] as int));
        final weekly = <String, List<Map<String, dynamic>>>{};
        for (final r in filtered) {
          final key = day(monday(r['at'] as DateTime));
          weekly.putIfAbsent(key, () => <Map<String, dynamic>>[]).add(r);
        }
        final weekKeys = weekly.keys.toList()..sort((a, b) => b.compareTo(a));
        Future<void> export() async {
          final rows = <String>['Tarih;Strateji;Degisen aksiyon;Onceki asim dk;Sonraki asim dk;Net iyilesme dk;Sorumlu;Onceki yuk dk;Sonraki yuk dk;Onceki sorumlu asimi dk;Sonraki sorumlu asimi dk'];
          for (final r in filtered) {
            final byOwner = r['owners'] as Map<String, Map<String, int>>;
            for (final entry in byOwner.entries) {
              if (ownerFilter != 'Tümü' && entry.key != ownerFilter) continue;
              rows.add([day(r['at'] as DateTime), r['strategy'], r['changes'], r['before'], r['after'], r['gain'], entry.key,
                entry.value['before'], entry.value['after'], entry.value['oldRisk'], entry.value['newRisk']].map(csv).join(';'));
            }
          }
          await Clipboard.setData(ClipboardData(text: rows.join('\n')));
          if (mounted) _notice('Aksiyon optimizasyon başarı karnesi CSV olarak kopyalandı.');
        }
        return SafeArea(child: SizedBox(height: MediaQuery.of(sheet).size.height * .92,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Aksiyon optimizasyonu / haftalık kapasite başarı karnesi', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const Text('Yalnızca onaylanıp geçmişe kaydedilmiş aksiyon planı değişiklikleri analiz edilir. İşlem anındaki aksiyon bütçesi kullanılır.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 8, children: [
                DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((v) => DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(), onChanged: (v) => update(() => weeks = v ?? 12)),
                DropdownButton<String>(value: ownerOptions.contains(ownerFilter) ? ownerFilter : 'Tümü', items: ownerOptions.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: weeks * 7))), child: const Text('Önceki')),
                OutlinedButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün')),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: weeks * 7))), child: const Text('Sonraki')),
              ]),
              Text('${day(start)} – ${day(end.subtract(const Duration(days: 1)))}'),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Tarih, strateji veya sorumlu ara'), onChanged: (v) => update(() => search = v)),
              SwitchListTile(title: const Text('Yalnızca iyileşen optimizasyonlar'), value: improvementsOnly, onChanged: (v) => update(() => improvementsOnly = v)),
              SwitchListTile(title: const Text('Sonrasında kapasite aşımı kalanlar'), value: riskOnly, onChanged: (v) => update(() => riskOnly = v)),
              Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${filtered.length} optimizasyon • $improved iyileşen • $worsened kötüleşen'),
                Text('İyileşme oranı: ${filtered.isEmpty ? '—' : '${(100 * improved / filtered.length).toStringAsFixed(1)}%'}'),
                Text('İşlem bazlı net kapasite aşımı azalması: $netGain dk'),
                Text('$invalid okunamayan / eksik kayıt • $missingDurations tahmini süre varsayımı'),
              ]))),
              OutlinedButton.icon(onPressed: export, icon: const Icon(Icons.copy_outlined), label: const Text('CSV raporunu kopyala')),
              if (filtered.isEmpty) const Padding(padding: EdgeInsets.all(16), child: Text('Bu filtreler ve tarih aralığında onaylı optimizasyon kaydı bulunamadı.')),
              ...weekKeys.map((week) {
                final items = weekly[week]!;
                final gain = items.fold<int>(0, (sum, r) => sum + (r['gain'] as int));
                return Card(child: ExpansionTile(
                  title: Text('$week haftası • ${items.length} işlem'),
                  subtitle: Text('Net işlem bazlı aşım azalması: $gain dk'),
                  children: items.map((r) {
                    final byOwner = r['owners'] as Map<String, Map<String, int>>;
                    final shown = byOwner.entries.where((e) => ownerFilter == 'Tümü' || e.key == ownerFilter);
                    return ExpansionTile(
                      title: Text('${day(r['at'] as DateTime)} • ${r['strategy']} • ${r['changes']} aksiyon'),
                      subtitle: Text('Kapasite aşımı: ${r['before']} → ${r['after']} dk • Fark: ${r['gain']} dk'),
                      children: shown.map((entry) => ListTile(
                        dense: true, title: Text(entry.key),
                        subtitle: Text('İş yükü: ${entry.value['before']} → ${entry.value['after']} dk\nHaftalık aşım toplamı: ${entry.value['oldRisk']} → ${entry.value['newRisk']} dk'),
                      )).toList(),
                    );
                  }).toList(),
                ));
              }),
              const SizedBox(height: 12),
              const Text('Not: Aynı aksiyon birden çok optimizasyonda bulunabilir. Toplam kazanım işlem bazlıdır; benzersiz zaman tasarrufu değildir. Eski kayıtlardaki süreler güncel tahminlerden okunur; bu nedenle geçmiş süre değişiklikleri sonuçları etkileyebilir.'),
              TextButton(onPressed: () { Navigator.pop(sheet); _showKitchenApprovedActionCapacityOptimizer(); }, child: const Text('Onaylı aksiyon optimizasyonuna geç')),
            ],
          ])));
      }));
  }

  void _showKitchenWeeklyActionCapacity() {
    const actionKey = 'paket43_preventive_fairness_action_plans_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final actions = <Map<String, dynamic>>[];
    final capacity = <String, int>{};
    final estimates = <String, int>{};
    bool started = false, loading = true, onlyOver = false, weekdaysOnly = true;
    int weeks = 4, dailyActionBudget = 45;
    DateTime anchor = DateTime.now();
    String filter = 'Tümü';
    String str(Object? v) => '${v ?? ''}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    bool open(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    int minutes(Map<String, dynamic> a) {
      final id = str(a['id']);
      return estimates[id] ?? (int.tryParse(str(a['estimatedMinutes'])) ?? 30).clamp(5, 480).toInt();
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      showDragHandle: true, builder: (sheet) => StatefulBuilder(builder: (sheet, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final p = await SharedPreferences.getInstance();
              final raw = jsonDecode(p.getString(actionKey) ?? '[]');
              final caps = jsonDecode(p.getString(capacityKey) ?? '{}');
              final saved = jsonDecode(p.getString('paket44_weekly_action_estimates_v1') ?? '{}');
              if (sheet.mounted) {
                update(() {
                if (raw is List) { for (final x in raw) {
                  if (x is Map) { actions.add(Map<String, dynamic>.from(x)); }
                } }
                if (caps is Map) { for (final e in caps.entries) {
                  final v = int.tryParse(str(e.value));
                  if (v != null && v >= 0 && v <= 1440) capacity[str(e.key)] = v;
                } }
                if (saved is Map) { for (final e in saved.entries) {
                  final v = int.tryParse(str(e.value));
                  if (v != null && v >= 5 && v <= 480) estimates[str(e.key)] = v;
                } }
                loading = false;
              });
              }
            } catch (e) {
              if (sheet.mounted) update(() => loading = false);
              if (mounted) _notice('Aksiyon kapasitesi okunamadı: $e');
            }
          });
        }
        final start = monday(anchor), end = start.add(Duration(days: weeks * 7));
        final owners = <String>{'Tümü', ...actions.map((a) => str(a['owner']).trim()).where((v) => v.isNotEmpty)}.toList()..sort();
        final buckets = <String, Map<String, dynamic>>{};
        var missing = 0;
        for (final a in actions) {
          if (!open(a)) continue;
          final d = parse(a['due']);
          final owner = str(a['owner']).trim();
          if (d == null || owner.isEmpty) { missing++; continue; }
          if (d.isBefore(start) || !d.isBefore(end)) continue;
          final w = monday(d);
          final key = '$owner|${iso(w)}';
          final b = buckets.putIfAbsent(key, () => <String, dynamic>{'owner':owner,'week':w,'actions':<Map<String, dynamic>>[],'used':0});
          (b['actions'] as List<Map<String, dynamic>>).add(a);
          b['used'] = (b['used'] as int) + minutes(a);
        }
        final rows = buckets.values.toList();
        for (final r in rows) {
          final days = weekdaysOnly ? 5 : 7;
          // Action capacity is intentionally separate from the general task capacity.
          final budget = dailyActionBudget * days;
          final used = r['used'] as int;
          r['budget'] = budget;
          r['excess'] = (used - budget).clamp(0, 999999).toInt();
          r['percent'] = budget == 0 ? 0.0 : used * 100 / budget;
        }
        rows.sort((a,b) {
          final n = (b['excess'] as int).compareTo(a['excess'] as int);
          return n != 0 ? n : (a['week'] as DateTime).compareTo(b['week'] as DateTime);
        });
        final visible = rows.where((r) => (filter == 'Tümü' || r['owner'] == filter) &&
          (!onlyOver || (r['excess'] as int) > 0)).toList();
        final used = visible.fold<int>(0,(s,r) => s + (r['used'] as int));
        final over = visible.fold<int>(0,(s,r) => s + (r['excess'] as int));
        Future<void> export() async {
          final lines = <String>['Sorumlu;Hafta;Aksiyon;Planlanan dakika;Haftalik aksiyon kapasitesi;Asim dakika;Doluluk yuzdesi'];
          for (final r in visible) {
            lines.add([r['owner'],iso(r['week'] as DateTime),(r['actions'] as List).length,r['used'],r['budget'],r['excess'],(r['percent'] as double).toStringAsFixed(1)].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: lines.join('\n')));
          if (mounted) _notice('Haftalık aksiyon kapasite raporu kopyalandı.');
        }
        Future<void> editEstimate(Map<String, dynamic> a) async {
          final id = str(a['id']);
          if (id.isEmpty) {if (mounted) _notice('Aksiyon kimliği eksik; süre kaydedilemedi.'); return;}
          final ctrl = TextEditingController(text: '${minutes(a)}');
          final value = await showDialog<int>(context: sheet, builder: (d) => AlertDialog(
            title: const Text('Tahmini aksiyon süresi (dakika)'),
            content: TextField(controller: ctrl, keyboardType: TextInputType.number,
              decoration: const InputDecoration(labelText: '5–480 dakika')),
            actions: [TextButton(onPressed: () => Navigator.pop(d),child: const Text('Vazgeç')),
              FilledButton(onPressed: () => Navigator.pop(d,int.tryParse(ctrl.text)),child: const Text('Kaydet'))]));
          disposeAfterDialog(ctrl);
          if (value == null) return;
          if (value < 5 || value > 480) {if (mounted) _notice('Süre 5–480 dakika olmalı.'); return;}
          final p = await SharedPreferences.getInstance();
          final next = {...estimates, id:value};
          await p.setString('paket44_weekly_action_estimates_v1',jsonEncode(next));
          if (sheet.mounted) update(() {estimates.clear();estimates.addAll(next);});
        }
        return SafeArea(child: SizedBox(height: MediaQuery.of(sheet).size.height * .9,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Haftalık aksiyon kapasitesi ve iş dağılımı',style: TextStyle(fontSize:20,fontWeight:FontWeight.bold)),
            const SizedBox(height:8),
            const Text('Aksiyon sürelerini planla, haftalık kapasiteyi karşılaştır. Öneriler kayıtları otomatik değiştirmez.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing:8,runSpacing:8,children:[
                DropdownButton<int>(value:weeks,items:[1,2,4,8,12,26].map((n)=>DropdownMenuItem(value:n,child:Text('$n hafta'))).toList(),onChanged:(v)=>update(()=>weeks=v??4)),
                DropdownButton<String>(value:owners.contains(filter)?filter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>filter=v??'Tümü')),
                DropdownButton<int>(value:dailyActionBudget,items:[15,30,45,60,90,120,180].map((v)=>DropdownMenuItem(value:v,child:Text('$v dk/gün'))).toList(),onChanged:(v)=>update(()=>dailyActionBudget=v??45)),
                OutlinedButton(onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:weeks*7))),child:const Text('Önceki')),
                OutlinedButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),
                OutlinedButton(onPressed:()=>update(()=>anchor=anchor.add(Duration(days:weeks*7))),child:const Text('Sonraki')),
              ]),
              SwitchListTile(title:const Text('Yalnızca hafta içi kapasitesi (5 gün)'),value:weekdaysOnly,onChanged:(v)=>update(()=>weekdaysOnly=v)),
              SwitchListTile(title:const Text('Yalnızca kapasite aşımı olan haftalar'),value:onlyOver,onChanged:(v)=>update(()=>onlyOver=v)),
              Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))} • ${visible.length} sorumlu-hafta • $used dk iş • $over dk aşım'),
              if (missing > 0) Text('$missing açık aksiyonda tarih veya sorumlu eksik.',style:const TextStyle(color:Colors.deepOrange)),
              const SizedBox(height:8),
              FilledButton.tonalIcon(onPressed:export,icon:const Icon(Icons.copy_outlined),label:const Text('CSV raporunu kopyala')),
              if (visible.isEmpty) const Padding(padding:EdgeInsets.all(20),child:Text('Seçilen dönemde uygun aksiyon bulunamadı.')),
              ...visible.map((r) {
                final items = r['actions'] as List<Map<String,dynamic>>;
                final excess = r['excess'] as int;
                return Card(child: ExpansionTile(
                  leading:Icon(excess > 0 ? Icons.warning_amber_outlined : Icons.check_circle_outline,
                    color:excess > 0 ? Colors.deepOrange : Colors.green),
                  title:Text('${r['owner']} • ${iso(r['week'] as DateTime)}'),
                  subtitle:Text('${items.length} aksiyon • ${r['used']} / ${r['budget']} dk • %${(r['percent'] as double).toStringAsFixed(0)}${excess>0?' • $excess dk aşım':''}'),
                  children:[
                    ...items.map((a)=>ListTile(
                      title:Text(str(a['title']).isEmpty?'Başlıksız aksiyon':str(a['title'])),
                      subtitle:Text('${a['priority']} • ${iso(parse(a['due']) ?? DateTime.now())} • ${minutes(a)} dk'),
                      trailing:IconButton(icon:const Icon(Icons.edit_outlined),tooltip:'Süreyi düzenle',onPressed:()=>editEstimate(a)))),
                    if (excess > 0) Padding(padding:const EdgeInsets.all(12),child:Text('Öneri: $excess dakikalık aksiyonu başka bir haftaya veya uygun bir sorumluya kaydırmayı değerlendirin.')),
                  ]));
              }),
              const SizedBox(height:12),
              const Text('Not: Aksiyonlar için ayrı günlük zaman bütçesi kullanılır; genel görev kapasitesinden otomatik düşülmez. Tahmini süre belirtilmeyen aksiyonlar 30 dakika kabul edilir. Sorumlu veya tarih değişiklikleri bu ekranda uygulanmaz.'),
              TextButton(onPressed:(){Navigator.pop(sheet);_showKitchenPreventiveActionTracker();},child:const Text('Aksiyon yönetimine geç')),
            ],
          ])));
      }));
  }

  void _showKitchenPreventiveActionPriorityPlanner() {
    const key = 'paket43_preventive_fairness_action_plans_v1';
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const targetKey = 'paket42_fairness_utilization_targets_v1';
    final actions = <Map<String, dynamic>>[];
    final tasks = <Map<String, dynamic>>[];
    final capacity = <String, int>{};
    final targets = <String, int>{};
    bool started = false, loading = true, onlyOpen = true, onlyRisk = false;
    int weeks = 4, limit = 15;
    String ownerFilter = 'Tümü', search = '';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    List<Map<String, dynamic>> records(Object? raw) => raw is List
        ? raw.whereType<Map>().map((v) => Map<String, dynamic>.from(v)).toList()
        : <Map<String, dynamic>>[];
    Map<String, int> numbers(Object? raw) {
      final out = <String, int>{};
      if (raw is Map) {
        for (final e in raw.entries) {
          final n = int.tryParse(str(e.value));
          if (n != null && n >= 0 && n <= 1440) out[str(e.key)] = n;
        }
      }
      return out;
    }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    int weeklyGap(String person, DateTime week) {
      final start = monday(week), end = monday(week).add(const Duration(days: 7));
      var minutes = 0;
      for (final task in tasks) {
        if (str(task['owner']).trim() != person ||
            ['Tamamlandı', 'İptal'].contains(str(task['status']))) { continue ; }
        final d = date(task['targetDate'] ?? task['due']);
        if (d == null || d.isBefore(start) || !d.isBefore(end) || d.weekday > 5) continue;
        final estimate = int.tryParse(str(task['estimatedMinutes']));
        minutes += estimate != null && estimate >= 5 && estimate <= 1440 ? estimate : 30;
      }
      final threshold = ((capacity[person] ?? 120) * 5 *
          (targets[person] ?? 80).clamp(0, 100) / 100).round();
      return (minutes - threshold).clamp(0, 99999999).toInt();
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      showDragHandle: true, builder: (ctx) => StatefulBuilder(builder: (ctx, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final a = records(jsonDecode(prefs.getString(key) ?? '[]'));
              final t = records(jsonDecode(prefs.getString(taskKey) ?? '[]'));
              final c = numbers(jsonDecode(prefs.getString(capacityKey) ?? '{}'));
              final g = numbers(jsonDecode(prefs.getString(targetKey) ?? '{}'));
              if (ctx.mounted) {
                update(() {
                actions.addAll(a); tasks.addAll(t); capacity.addAll(c);
                targets.addAll(g); loading = false;
              });
              }
            } catch (e) {
              if (ctx.mounted) update(() => loading = false);
              if (mounted) _notice('Haftalık aksiyon planı okunamadı: $e');
            }
          });
        }
        final first = monday(anchor);
        final last = first.add(Duration(days: weeks * 7));
        final today = DateTime.now();
        final todayDay = DateTime(today.year, today.month, today.day);
        final owners = <String>{'Tümü', ...actions.map((e) => str(e['owner']).trim())
          .where((e) => e.isNotEmpty)}.toList()..sort();
        final rows = <Map<String, dynamic>>[];
        var badDates = 0;
        for (final action in actions) {
          final due = date(action['due']);
          final riskWeek = date(action['week']);
          if (due == null || riskWeek == null) {badDates++; continue;}
          if (due.isBefore(first) || !due.isBefore(last)) continue;
          final person = str(action['owner']).trim();
          final status = str(action['status']);
          final closed = status == 'Tamamlandı' || status == 'İptal';
          final overdue = !closed && DateTime(due.year, due.month, due.day).isBefore(todayDay);
          final gap = person.isEmpty ? 0 : weeklyGap(person, riskWeek);
          final baseline = int.tryParse(str(action['baselineGap']));
          final change = baseline == null ? null : baseline - gap;
          final days = DateTime(due.year, due.month, due.day).difference(todayDay).inDays;
          final priority = str(action['priority']);
          final severity = priority == 'Kritik' ? 45 : priority == 'Yüksek' ? 30 : priority == 'Orta' ? 15 : 5;
          final urgency = overdue ? 40 : days <= 2 ? 30 : days <= 7 ? 20 : 0;
          final risk = gap >= 120 ? 30 : gap > 0 ? 20 : 0;
          final score = severity + urgency + risk + (closed ? -100 : 0);
          final label = closed ? 'Kapalı' : overdue ? 'Gecikti' : days <= 2 ? 'Acil' : gap > 0 ? 'Riskli' : 'Planlı';
          rows.add({'action':action,'person':person,'due':due,'riskWeek':riskWeek,
            'gap':gap,'baseline':baseline,'change':change,'closed':closed,
            'overdue':overdue,'score':score,'label':label,'days':days});
        }
        rows.sort((a, b) {
          final c = (b['score'] as int).compareTo(a['score'] as int);
          if (c != 0) return c;
          return (a['due'] as DateTime).compareTo(b['due'] as DateTime);
        });
        final visible = rows.where((r) {
          if (ownerFilter != 'Tümü' && r['person'] != ownerFilter) return false;
          if (onlyOpen && r['closed'] == true) return false;
          if (onlyRisk && (r['gap'] as int) <= 0 && r['overdue'] != true) return false;
          final a = r['action'] as Map<String, dynamic>;
          return '${a['title']} ${a['note']} ${r['person']} ${a['priority']}'
            .toLowerCase().contains(search.toLowerCase());
        }).toList();
        final selected = visible.take(limit).toList();
        final weekly = <String, List<Map<String, dynamic>>>{};
        for (final r in selected) {
          final w = iso(monday(r['due'] as DateTime));
          weekly.putIfAbsent(w, () => <Map<String, dynamic>>[]).add(r);
        }
        final late = rows.where((r) => r['overdue'] == true).length;
        final open = rows.where((r) => r['closed'] == false).length;
        final highRisk = rows.where((r) => r['closed'] == false && (r['gap'] as int) > 0).length;
        final personLoad = <String, int>{};
        for (final r in selected) {
          final p = str(r['person']);
          personLoad[p] = (personLoad[p] ?? 0) + 1;
        }
        final report = <String>[
          'Hedef haftası;Aksiyon;Sorumlu;Öncelik;Durum;Hedef tarih;Risk haftası;Hedef üstü dk;Başlangıç dk;Değişim dk;Puan;Öneri'
        ];
        String recommendation(Map<String, dynamic> r) {
          if (r['overdue'] == true) return 'Hedef tarihi ve sorumluyu gözden geçir';
          if ((r['gap'] as int) > 0) return 'Görevleri daha uygun günlere veya sorumluya dağıt';
          if ((r['days'] as int) <= 2) return 'Yaklaşan hedef tarihi için ilerlemeyi doğrula';
          return 'Planlanan aksiyonun durumunu takip et';
        }
        for (final r in selected) {
          final a = r['action'] as Map<String, dynamic>;
          report.add([
            iso(monday(r['due'] as DateTime)), a['title'], r['person'], a['priority'],
            a['status'], iso(r['due'] as DateTime), iso(r['riskWeek'] as DateTime),
            r['gap'], r['baseline'] ?? '', r['change'] ?? '', r['score'], recommendation(r)
          ].map(csv).join(';'));
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .95,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            Row(children: [const Expanded(child: Text('Aksiyon önceliklendirme / haftalık iyileştirme planı',
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold))),
              IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
            const Text('Kayıtlı önleyici aksiyonlar hedef tarihlerine, önemine ve güncel plan riskine göre sıralanır. Öneriler otomatik uygulanmaz.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 6, crossAxisAlignment: WrapCrossAlignment.center, children: [
                DropdownButton<int>(value: weeks, items: [1,2,4,8,12,26].map((v) =>
                  DropdownMenuItem(value: v, child: Text('$v hafta'))).toList(),
                  onChanged: (v) => update(() => weeks = v ?? 4)),
                DropdownButton<int>(value: limit, items: [5,10,15,25,50,100].map((v) =>
                  DropdownMenuItem(value: v, child: Text('İlk $v aksiyon'))).toList(),
                  onChanged: (v) => update(() => limit = v ?? 15)),
                DropdownButton<String>(value: owners.contains(ownerFilter) ? ownerFilter : 'Tümü',
                  items: owners.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                  onChanged: (v) => update(() => ownerFilter = v ?? 'Tümü')),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: weeks * 7))), child: const Text('← Önceki')),
                OutlinedButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün')),
                OutlinedButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: weeks * 7))), child: const Text('Sonraki →')),
              ]),
              Text('Hedef tarih aralığı: ${iso(first)} – ${iso(last.subtract(const Duration(days: 1)))}'),
              Card(color: const Color(0xFFFFF3FA), child: Padding(padding: const EdgeInsets.all(12),
                child: Text('Aksiyon: ${rows.length} • Açık: $open • Geciken: $late • Riskli açık: $highRisk\n'
                  'Filtrelenen: ${visible.length} • Haftalık plana alınan: ${selected.length}',
                  style: const TextStyle(fontWeight: FontWeight.bold)))),
              if (badDates > 0) Text('$badDates aksiyonun risk haftası veya hedef tarihi geçersiz.',
                style: const TextStyle(color: Colors.deepOrange)),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
                labelText: 'Aksiyon / sorumlu / not ara'), onChanged: (v) => update(() => search = v)),
              SwitchListTile(title: const Text('Yalnızca açık aksiyonlar'), value: onlyOpen,
                onChanged: (v) => update(() => onlyOpen = v)),
              SwitchListTile(title: const Text('Yalnızca geciken veya hedef üstü riskli'), value: onlyRisk,
                onChanged: (v) => update(() => onlyRisk = v)),
              const SizedBox(height: 8),
              Text('Seçilen planda sorumlu yoğunluğu', style: Theme.of(ctx).textTheme.titleMedium),
              if (personLoad.isEmpty) const Text('Bu dönemde plana alınacak aksiyon bulunamadı.'),
              ...personLoad.entries.map((e) => ListTile(dense: true,
                leading: const Icon(Icons.person_outline), title: Text(e.key.isEmpty ? 'Sorumlu belirtilmemiş' : e.key),
                trailing: Text('${e.value} aksiyon'))),
              const SizedBox(height: 8),
              Text('Haftalık öncelik planı', style: Theme.of(ctx).textTheme.titleMedium),
              ...weekly.entries.map((entry) => Card(child: ExpansionTile(
                initiallyExpanded: true, title: Text('${entry.key} haftası'),
                subtitle: Text('${entry.value.length} öncelikli aksiyon'),
                children: entry.value.map((r) {
                  final a = r['action'] as Map<String, dynamic>;
                  final change = r['change'];
                  return ListTile(isThreeLine: true,
                    leading: CircleAvatar(child: Text('${r['score']}')),
                    title: Text(str(a['title'])),
                    subtitle: Text('${r['person']} • ${a['priority']} • ${r['label']}\n'
                      'Hedef: ${iso(r['due'] as DateTime)} • Risk: ${r['gap']} dk • '
                      'Fark: ${change == null ? 'Ölçülemedi' : '$change dk'}\n'
                      'Öneri: ${recommendation(r)}'),
                  );
                }).toList(),
              ))),
              FilledButton.tonalIcon(onPressed: () async {
                await Clipboard.setData(ClipboardData(text: '\uFEFF${report.join('\r\n')}'));
                if (ctx.mounted) _notice('Haftalık öncelik planı CSV olarak kopyalandı.');
              }, icon: const Icon(Icons.copy_outlined), label: const Text('Haftalık planı CSV olarak kopyala')),
              OutlinedButton(onPressed: () {Navigator.pop(ctx); _showKitchenPreventiveActionTracker();},
                child: const Text('Aksiyonları düzenle / durum güncelle')),
              OutlinedButton(onPressed: () {Navigator.pop(ctx); _showKitchenPreventiveActionPerformance();},
                child: const Text('Performans karnesini aç')),
              const Text('Hesaplama notu: Hedef tarihi bu döneme düşen aksiyonlar listelenir; risk haftası ayrı tutulur. '
                'Güncel risk hafta içi açık görevlerin tahmini sürelerinden hesaplanır. Eksik süre 30 dk, '
                'eksik günlük kapasite 120 dk, eksik hedef %80 varsayılır. Risk puanı karar desteğidir; '
                'kişilerin gerçek müsaitliği doğrulanmaz. Öncelik planı görev veya aksiyon kayıtlarını değiştirmez.'),
            ],
          ])));
      }));
  }

  void _showKitchenPreventiveActionPerformance() {
    const planKey = 'paket43_preventive_fairness_action_plans_v1';
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const targetKey = 'paket42_fairness_utilization_targets_v1';
    final plans = <Map<String, dynamic>>[];
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final targets = <String, int>{};
    bool started = false, loading = true, onlyOpen = false, onlyOverdue = false;
    int weeks = 12;
    String ownerFilter = 'Tümü', query = '';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    List<Map<String, dynamic>> maps(Object? v) => v is List ? v.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> ints(Object? v) {
      final result = <String, int>{};
      if (v is Map) { for (final e in v.entries) {
        final n = int.tryParse(str(e.value));
        if (n != null && n >= 0 && n <= 1440) result[str(e.key)] = n;
      } }
      return result;
    }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    int gap(String owner, DateTime week) {
      final start = monday(week), end = monday(week).add(const Duration(days: 7));
      var used = 0;
      for (final t in tasks) {
        if (str(t['owner']) != owner || ['Tamamlandı', 'İptal'].contains(str(t['status']))) continue;
        final d = parse(t['targetDate'] ?? t['due']);
        if (d == null || d.isBefore(start) || !d.isBefore(end) || d.weekday >= 6) continue;
        final n = int.tryParse(str(t['estimatedMinutes']));
        used += n != null && n >= 5 && n <= 1440 ? n : 30;
      }
      final allowed = ((capacities[owner] ?? 120) * 5 * (targets[owner] ?? 80).clamp(0, 100) / 100).round();
      return (used - allowed).clamp(0, 99999999).toInt();
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, update) {
        if (!started) {
          started = true;
          Future<void>.microtask(() async {
            try {
              final prefs = await SharedPreferences.getInstance();
              final p = maps(jsonDecode(prefs.getString(planKey) ?? '[]'));
              final t = maps(jsonDecode(prefs.getString(taskKey) ?? '[]'));
              final c = ints(jsonDecode(prefs.getString(capacityKey) ?? '{}'));
              final g = ints(jsonDecode(prefs.getString(targetKey) ?? '{}'));
              if (ctx.mounted) update(() {plans.addAll(p);tasks.addAll(t);capacities.addAll(c);targets.addAll(g);loading=false;});
            } catch (e) {
              if (ctx.mounted) update(() => loading=false);
              if (mounted) _notice('Aksiyon performans verileri okunamadı: $e');
            }
          });
        }
        final from = monday(anchor).subtract(Duration(days: (weeks - 1) * 7));
        final until = monday(anchor).add(const Duration(days: 7));
        final today = DateTime.now();
        final owners = <String>{'Tümü', ...plans.map((p) => str(p['owner']).trim()).where((v) => v.isNotEmpty)}.toList()..sort();
        final rows = <Map<String, dynamic>>[];
        var invalid = 0;
        for (final p in plans) {
          final w = parse(p['week']);
          if (w == null) {invalid++;continue;}
          if (w.isBefore(from) || !w.isBefore(until)) continue;
          final person = str(p['owner']).trim();
          final status = str(p['status']);
          final due = parse(p['due']);
          final closed = status == 'Tamamlandı' || status == 'İptal';
          final overdue = !closed && due != null && DateTime(due.year, due.month, due.day).isBefore(DateTime(today.year, today.month, today.day));
          final baseline = int.tryParse(str(p['baselineGap']));
          final current = person.isNotEmpty ? gap(person, w) : 0;
          final delta = baseline == null ? null : baseline - current;
          final priority = str(p['priority']);
          final score = (overdue ? 45 : 0) + (current > 0 ? 25 : 0) + ((priority == 'Kritik' || priority == 'Yüksek') ? 20 : 0) + (!closed ? 10 : 0);
          rows.add({'plan':p,'owner':person,'week':iso(monday(w)),'status':status,'closed':closed,'overdue':overdue,
            'baseline':baseline,'current':current,'delta':delta,'score':score,'due':due});
        }
        rows.sort((a,b) => (b['score'] as int).compareTo(a['score'] as int));
        final filtered = rows.where((r) {
          if (ownerFilter != 'Tümü' && r['owner'] != ownerFilter) return false;
          if (onlyOpen && r['closed'] == true) return false;
          if (onlyOverdue && r['overdue'] != true) return false;
          final p = r['plan'] as Map<String,dynamic>;
          return '${p['title']} ${r['owner']} ${p['note']} ${r['week']}'.toLowerCase().contains(query.toLowerCase());
        }).toList();
        final complete = rows.where((r) => r['status'] == 'Tamamlandı').length;
        final overdueCount = rows.where((r) => r['overdue'] == true).length;
        final improved = rows.where((r) => r['delta'] != null && (r['delta'] as int) > 0).length;
        final worsened = rows.where((r) => r['delta'] != null && (r['delta'] as int) < 0).length;
        final open = rows.where((r) => r['closed'] == false).length;
        final ownerSummary = <String, Map<String,int>>{};
        for (final r in rows) {
          final person = str(r['owner']);
          final v = ownerSummary.putIfAbsent(person, () => {'total':0,'done':0,'late':0,'risk':0,'improved':0});
          v['total'] = v['total']! + 1;
          if (r['status'] == 'Tamamlandı') v['done'] = v['done']! + 1;
          if (r['overdue'] == true) v['late'] = v['late']! + 1;
          if ((r['current'] as int) > 0) v['risk'] = v['risk']! + 1;
          if (r['delta'] != null && (r['delta'] as int) > 0) v['improved'] = v['improved']! + 1;
        }
        final export = <String>['Aksiyon;Sorumlu;Risk haftası;Hedef tarih;Öncelik;Durum;Gecikti;Başlangıç hedef üstü dk;Güncel hedef üstü dk;Fark dk;Öncelik puanı'];
        for (final r in filtered) {
          final p = r['plan'] as Map<String,dynamic>;
          export.add([p['title'],r['owner'],r['week'],p['due'],p['priority'],r['status'],r['overdue'] == true ? 'Evet':'Hayır',r['baseline'] ?? '',r['current'],r['delta'] ?? '',r['score']].map(csv).join(';'));
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
          Row(children:[const Expanded(child:Text('Aksiyon performansı / risk azaltma önerileri',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Kayıtlı aksiyonlar ve güncel görev planı üzerinden kural tabanlı performans analizi. Sonuçlar gerçek gerçekleşme veya nedensel başarı kanıtı değildir.'),
          if (loading) const LinearProgressIndicator() else ...[
            Wrap(spacing:10,runSpacing:6,children:[
              DropdownButton<int>(value:weeks,items:[4,8,12,26,52].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>update(()=>weeks=v??12)),
              DropdownButton<String>(value:owners.contains(ownerFilter)?ownerFilter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>ownerFilter=v??'Tümü')),
              OutlinedButton(onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:weeks*7))),child:const Text('← Önceki')),
              OutlinedButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),
              OutlinedButton(onPressed:()=>update(()=>anchor=anchor.add(Duration(days:weeks*7))),child:const Text('Sonraki →')),
            ]),
            Text('${iso(from)} – ${iso(until.subtract(const Duration(days:1)))}'),
            Card(color:const Color(0xFFFFF3FA),child:Padding(padding:const EdgeInsets.all(12),child:Text('Aksiyon: ${rows.length} • Açık: $open • Tamamlanan: $complete • Geciken: $overdueCount\nHedef üstü yükü azalan: $improved • Artan: $worsened • Tamamlama: %${rows.isEmpty?0:(complete*100/rows.length).round()}',style:const TextStyle(fontWeight:FontWeight.bold)))),
            if (invalid>0) Text('Uyarı: $invalid kayıtta geçerli risk haftası bulunamadı.',style:const TextStyle(color:Colors.deepOrange)),
            const SizedBox(height:10),Text('Sorumlu bazında başarı karnesi',style:Theme.of(ctx).textTheme.titleMedium),
            ...ownerSummary.entries.map((e) => Card(child:ListTile(title:Text(e.key.isEmpty?'Sorumlu belirtilmemiş':e.key),subtitle:Text('Aksiyon ${e.value['total']} • Tamamlanan ${e.value['done']} • Geciken ${e.value['late']} • Hedef üstü ${e.value['risk']} • İyileşen ${e.value['improved']}')))),
            const SizedBox(height:10),Text('Önleyici öneriler',style:Theme.of(ctx).textTheme.titleMedium),
            if (overdueCount>0) ListTile(leading:const Icon(Icons.schedule_outlined),title:Text('$overdueCount geciken aksiyon'),subtitle:const Text('Hedef tarihleri ve aksiyon sorumlularını yeniden değerlendir.')),
            if (worsened>0) ListTile(leading:const Icon(Icons.warning_amber_outlined),title:Text('$worsened aksiyonda hedef üstü yük arttı'),subtitle:const Text('İlgili haftalardaki görev tarihlerini ve sorumlu dağılımını kontrol et.')),
            if (open>0 && improved==0) const ListTile(leading:Icon(Icons.balance_outlined),title:Text('İş yükü dengelemesini değerlendir'),subtitle:Text('Açık aksiyonların bağlı olduğu haftalar için önleyici görev dağılımını gözden geçir.')),
            if (rows.isEmpty) const ListTile(title:Text('Bu dönemde kayıtlı aksiyon bulunamadı.')),
            SwitchListTile(title:const Text('Yalnızca açık aksiyonlar'),value:onlyOpen,onChanged:(v)=>update(()=>onlyOpen=v)),
            SwitchListTile(title:const Text('Yalnızca geciken aksiyonlar'),value:onlyOverdue,onChanged:(v)=>update(()=>onlyOverdue=v)),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Aksiyon, sorumlu, hafta veya not ara'),onChanged:(v)=>update(()=>query=v)),
            const SizedBox(height:8),Text('Aksiyon detayları (${filtered.length})',style:Theme.of(ctx).textTheme.titleMedium),
            ...filtered.take(150).map((r) {
              final p = r['plan'] as Map<String,dynamic>;
              final delta = r['delta'];
              return Card(child:ExpansionTile(title:Text(str(p['title'])),subtitle:Text('${r['owner']} • ${r['week']} • ${r['status']} ${r['overdue']==true?'• GECİKTİ':''}'),children:[Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text('Öncelik: ${p['priority']} • Hedef tarih: ${p['due']} • Risk puanı: ${r['score']}'),
                Text('Başlangıç hedef üstü: ${r['baseline'] ?? 'Bilinmiyor'} dk • Güncel: ${r['current']} dk'),
                Text('Fark: ${delta == null ? 'Ölçülemiyor' : '${delta > 0 ? '+' : ''}$delta dk'}'),
                if (str(p['note']).isNotEmpty) Text('Not: ${p['note']}'),
                if (r['overdue']==true) const Text('Öneri: Aksiyon durumunu ve hedef tarihini kontrol et.'),
                if ((r['current'] as int)>0) const Text('Öneri: Risk haftasındaki açık görevlerin dağılımını incele.'),
              ]))]));
            }),
            FilledButton.tonalIcon(onPressed:() async {await Clipboard.setData(ClipboardData(text:'\uFEFF${export.join('\r\n')}'));if(ctx.mounted)_notice('Aksiyon performans CSV raporu kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Filtrelenmiş CSV raporunu kopyala')),
            OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveActionTracker();},child:const Text('Aksiyon planını yönet')),
            OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenRecurringFairnessActions();},child:const Text('Tekrarlayan riskleri incele')),
            const SizedBox(height:8),const Text('Hesaplama notu: Haftalık risk, hafta içi planlanmış açık görevlerin tahmini süreleri ve kayıtlı kişi hedefleriyle hesaplanır. Eksik görev süresi 30 dk, eksik günlük kapasite 120 dk varsayılır. Başlangıç verisi olmayan aksiyonlarda iyileşme hesaplanmaz. Bir aksiyonun tamamlanması riskin otomatik olarak ortadan kalktığı anlamına gelmez.'),
          ]
        ])));
      }));
  }

  void _showKitchenPreventiveActionTracker() {
    const key = 'paket43_preventive_fairness_action_plans_v1';
    const tasksKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const targetKey = 'paket42_fairness_utilization_targets_v1';
    final plans = <Map<String, dynamic>>[];
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final targets = <String, int>{};
    var loaded = false, busy = true, showClosed = true;
    String ownerFilter = 'Tümü', search = '';
    String str(Object? value) => '${value ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    DateTime? parse(Object? value) => DateTime.tryParse(str(value));
    List<Map<String, dynamic>> maps(Object? value) => value is List
        ? value.whereType<Map>().map((v) => Map<String, dynamic>.from(v)).toList()
        : <Map<String, dynamic>>[];
    Map<String, int> ints(Object? value) {
      final result = <String, int>{};
      if (value is Map) {
        for (final e in value.entries) {
          final n = int.tryParse(str(e.value));
          if (n != null && n >= 0 && n <= 1440) result[str(e.key)] = n;
        }
      }
      return result;
    }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    int currentRisk(String owner, DateTime week) {
      final monday = DateTime(week.year, week.month, week.day).subtract(Duration(days: week.weekday - 1));
      var used = 0;
      for (final t in tasks) {
        if (str(t['owner']) != owner || ['Tamamlandı', 'İptal'].contains(str(t['status']))) continue;
        final d = parse(t['targetDate'] ?? t['due']);
        if (d == null || d.isBefore(monday) || !d.isBefore(monday.add(const Duration(days: 7)))) continue;
        if (d.weekday >= 6) continue;
        final raw = int.tryParse(str(t['estimatedMinutes']));
        used += raw != null && raw >= 5 && raw <= 1440 ? raw : 30;
      }
      final capacity = (capacities[owner] ?? 120) * 5;
      final threshold = (capacity * ((targets[owner] ?? 80).clamp(0, 100)) / 100).round();
      return (used - threshold).clamp(0, 99999999).toInt();
    }
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (sheetContext) => StatefulBuilder(builder: (sheetContext, update) {
        Future<void> save() async {
          final prefs = await SharedPreferences.getInstance();
          await prefs.setString(key, jsonEncode(plans));
        }
        Future<void> load() async {
          if (loaded) return;
          loaded = true;
          try {
            final prefs = await SharedPreferences.getInstance();
            final p = maps(jsonDecode(prefs.getString(key) ?? '[]'));
            final t = maps(jsonDecode(prefs.getString(tasksKey) ?? '[]'));
            final c = ints(jsonDecode(prefs.getString(capacityKey) ?? '{}'));
            final g = ints(jsonDecode(prefs.getString(targetKey) ?? '{}'));
            if (sheetContext.mounted) {
              update(() {
              plans.addAll(p); tasks.addAll(t); capacities.addAll(c); targets.addAll(g); busy = false;
            });
            }
          } catch (e) {
            if (sheetContext.mounted) update(() => busy = false);
            if (mounted) _notice('Aksiyon kayıtları okunamadı: $e');
          }
        }
        if (!loaded) Future<void>.microtask(load);
        Future<void> edit([Map<String, dynamic>? original]) async {
          final title = TextEditingController(text: str(original?['title']));
          final person = TextEditingController(text: str(original?['owner']));
          final note = TextEditingController(text: str(original?['note']));
          final week = TextEditingController(text: str(original?['week']).isEmpty ? iso(DateTime.now()) : str(original?['week']));
          final due = TextEditingController(text: str(original?['due']).isEmpty ? iso(DateTime.now().add(const Duration(days: 7))) : str(original?['due']));
          String status = str(original?['status']).isEmpty ? 'Planlandı' : str(original?['status']);
          String priority = str(original?['priority']).isEmpty ? 'Orta' : str(original?['priority']);
          final accepted = await showDialog<bool>(
            context: sheetContext,
            builder: (dialogContext) => StatefulBuilder(builder: (dialogContext, refresh) => AlertDialog(
              title: Text(original == null ? 'Önleyici aksiyon oluştur' : 'Aksiyonu düzenle'),
              content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
                TextField(controller: title, decoration: const InputDecoration(labelText: 'Aksiyon / yapılacak iş *')),
                TextField(controller: person, decoration: const InputDecoration(labelText: 'Sorumlu *')),
                TextField(controller: week, decoration: const InputDecoration(labelText: 'Risk haftası (YYYY-AA-GG) *')),
                TextField(controller: due, decoration: const InputDecoration(labelText: 'Hedef tarih (YYYY-AA-GG) *')),
                TextField(controller: note, maxLines: 2, decoration: const InputDecoration(labelText: 'Not / alınacak önlem')),
                DropdownButtonFormField<String>(initialValue: priority, decoration: const InputDecoration(labelText: 'Öncelik'),
                  items: ['Düşük', 'Orta', 'Yüksek', 'Kritik'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                  onChanged: (v) { if (v != null) refresh(() => priority = v); }),
                DropdownButtonFormField<String>(initialValue: status, decoration: const InputDecoration(labelText: 'Durum'),
                  items: ['Planlandı', 'Devam Ediyor', 'Tamamlandı', 'İptal'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                  onChanged: (v) { if (v != null) refresh(() => status = v); }),
              ])),
              actions: [
                TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Vazgeç')),
                FilledButton(onPressed: () {
                  if (title.text.trim().isEmpty || person.text.trim().isEmpty || parse(week.text) == null || parse(due.text) == null) {
                    ScaffoldMessenger.of(dialogContext).showSnackBar(const SnackBar(content: Text('Zorunlu alanları ve tarihleri kontrol edin.')));
                    return;
                  }
                  Navigator.pop(dialogContext, true);
                }, child: const Text('Kaydet')),
              ],
            )),
          );
          if (accepted == true) {
            final riskWeek = parse(week.text)!;
            final current = currentRisk(person.text.trim(), riskWeek);
            final entry = <String, dynamic>{
              'id': original?['id'] ?? DateTime.now().microsecondsSinceEpoch.toString(),
              'title': title.text.trim(), 'owner': person.text.trim(),
              'week': iso(riskWeek), 'due': iso(parse(due.text)!), 'note': note.text.trim(),
              'priority': priority, 'status': status,
              'baselineGap': original?['baselineGap'] ?? current,
              'createdAt': original?['createdAt'] ?? DateTime.now().toIso8601String(),
              'updatedAt': DateTime.now().toIso8601String(),
            };
            update(() { if (original == null) { plans.add(entry); } else { final i = plans.indexOf(original); if (i >= 0) plans[i] = entry; } });
            try { await save(); } catch (e) { if (mounted) _notice('Aksiyon kaydedilemedi: $e'); }
          }
          disposeAfterDialog(title); disposeAfterDialog(person); disposeAfterDialog(note); disposeAfterDialog(week); disposeAfterDialog(due);
        }
        final owners = <String>{for (final p in plans) str(p['owner'])}.where((v) => v.isNotEmpty).toList()..sort();
        final visible = plans.where((p) {
          if (ownerFilter != 'Tümü' && p['owner'] != ownerFilter) return false;
          if (!showClosed && ['Tamamlandı', 'İptal'].contains(str(p['status']))) return false;
          return '${p['title']} ${p['owner']} ${p['note']}'.toLowerCase().contains(search.toLowerCase());
        }).toList()..sort((a, b) => str(a['due']).compareTo(str(b['due'])));
        final open = plans.where((p) => !['Tamamlandı', 'İptal'].contains(str(p['status']))).length;
        final overdue = plans.where((p) => !['Tamamlandı', 'İptal'].contains(str(p['status'])) && str(p['due']).compareTo(iso(DateTime.now())) < 0).length;
        final done = plans.where((p) => p['status'] == 'Tamamlandı').length;
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16), child: ListView(children: [
            const Text('Önleyici aksiyon planı ve risk azaltma başarı takibi', style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const Text('Riskleri somut aksiyonlara dönüştürün; sorumlu, hedef tarih, durum ve planlanan risk haftasını kaydedin.'),
            if (busy) const LinearProgressIndicator(),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 8, children: [
              Chip(label: Text('Toplam: ${plans.length}')),
              Chip(label: Text('Açık: $open')),
              Chip(label: Text('Geciken: $overdue')),
              Chip(label: Text('Tamamlanan: $done')),
            ]),
            FilledButton.icon(onPressed: busy ? null : () => edit(), icon: const Icon(Icons.add_task), label: const Text('Yeni önleyici aksiyon oluştur')),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Aksiyon / sorumlu ara'), onChanged: (v) => update(() => search = v)),
            DropdownButtonFormField<String>(initialValue: ownerFilter, decoration: const InputDecoration(labelText: 'Sorumlu filtresi'),
              items: ['Tümü', ...owners].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
              onChanged: (v) { if (v != null) update(() => ownerFilter = v); }),
            SwitchListTile(title: const Text('Tamamlanan ve iptal edilenleri göster'), value: showClosed, onChanged: (v) => update(() => showClosed = v)),
            OutlinedButton.icon(onPressed: visible.isEmpty ? null : () async {
              final lines = <String>['Aksiyon,Sorumlu,Risk haftası,Hedef tarih,Öncelik,Durum,Başlangıç sapması (dk),Güncel sapma (dk),Değişim (dk),Not'];
              for (final p in visible) {
                final baseline = int.tryParse(str(p['baselineGap'])) ?? 0;
                final current = parse(p['week']) == null ? 0 : currentRisk(str(p['owner']), parse(p['week'])!);
                lines.add([p['title'], p['owner'], p['week'], p['due'], p['priority'], p['status'], baseline, current, baseline - current, p['note']].map(csv).join(','));
              }
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('Aksiyon raporu CSV olarak panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Görünen aksiyonları CSV kopyala')),
            if (!busy && visible.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('Bu filtreye uygun aksiyon bulunamadı.')),
            ...visible.map((p) {
              final baseline = int.tryParse(str(p['baselineGap'])) ?? 0;
              final riskWeek = parse(p['week']);
              final current = riskWeek == null ? 0 : currentRisk(str(p['owner']), riskWeek);
              final improvement = baseline - current;
              final isLate = !['Tamamlandı', 'İptal'].contains(str(p['status'])) && str(p['due']).compareTo(iso(DateTime.now())) < 0;
              return Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(str(p['title']), style: const TextStyle(fontWeight: FontWeight.bold)),
                Text('${p['owner']} • ${p['priority']} • ${p['status']}'),
                Text('Risk haftası: ${p['week']} • Hedef: ${p['due']}${isLate ? ' • GECİKTİ' : ''}'),
                Text('Hedef üstü yük: $baseline → $current dk • Değişim: ${improvement >= 0 ? '+' : ''}$improvement dk'),
                if (str(p['note']).isNotEmpty) Text(str(p['note'])),
                Wrap(spacing: 8, children: [
                  TextButton.icon(onPressed: () => edit(p), icon: const Icon(Icons.edit_outlined), label: const Text('Düzenle')),
                  TextButton.icon(onPressed: () async {
                    final confirmed = await showDialog<bool>(context: sheetContext, builder: (c) => AlertDialog(
                      title: const Text('Aksiyon silinsin mi?'), content: Text(str(p['title'])),
                      actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Vazgeç')),
                        FilledButton(onPressed: () => Navigator.pop(c, true), child: const Text('Sil'))]));
                    if (confirmed == true) {
                      update(() => plans.remove(p));
                      try { await save(); } catch (e) { if (mounted) _notice('Silme kaydedilemedi: $e'); }
                    }
                  }, icon: const Icon(Icons.delete_outline), label: const Text('Sil')),
                ]),
              ])));
            }),
            const SizedBox(height: 12),
            const Text('Not: Risk azaltma hesabı, kayıt anındaki ve güncel planın aynı risk haftasına ait hedef üstü sürelerini karşılaştırır. Görevler başka nedenle değişmiş olabilir; bu sonuç aksiyonun etkisini kanıtlamaz. Tamamlanma durumu elle güncellenir. Hafta sonu hariç, eksik süre 30 dk, eksik günlük kapasite 120 dk varsayılır.'),
            const SizedBox(height: 24),
          ]),
        )));
      }),
    );
  }

  void _showKitchenRecurringFairnessActions() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const targetKey = 'paket42_fairness_utilization_targets_v1';
    const historyKey = 'paket40_optimization_plan_versions_v1';
    final tasks = <Map<String, dynamic>>[];
    final history = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final targets = <String, int>{};
    var loaded = false, busy = true, weeks = 4, tolerance = 10, repeatThreshold = 2;
    var weekends = false, risksOnly = true, query = '', owner = 'Tümü';
    DateTime anchor = DateTime.now();
    String txt(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(txt(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    List<Map<String, dynamic>> maps(Object? v) => v is List ? v.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> ints(Object? v) {
      final result = <String, int>{};
      if (v is Map) {
        for (final e in v.entries) {
          final n = int.tryParse(txt(e.value));
          if (n != null && n >= 0 && n <= 1440) result[txt(e.key)] = n;
        }
      }
      return result;
    }
    String csv(Object? v) => '"${txt(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true, showDragHandle: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, update) {
        Future<void> load() async {
          if (loaded) return;
          loaded = true;
          try {
            final prefs = await SharedPreferences.getInstance();
            final t = maps(jsonDecode(prefs.getString(actionKey) ?? '[]'));
            final h = maps(jsonDecode(prefs.getString(historyKey) ?? '[]'));
            final c = ints(jsonDecode(prefs.getString(capacityKey) ?? '{}'));
            final g = ints(jsonDecode(prefs.getString(targetKey) ?? '{}'));
            if (ctx.mounted) update(() {tasks.addAll(t); history.addAll(h); capacities.addAll(c); targets.addAll(g); busy = false;});
          } catch (e) {
            if (ctx.mounted) update(() => busy = false);
            if (mounted) _notice('Adalet riski verileri okunamadı: $e');
          }
        }
        if (!loaded) { Future<void>.microtask(load); }
        final start = monday(anchor).subtract(Duration(days: 7 * (weeks - 1)));
        final end = monday(anchor).add(const Duration(days: 7));
        final names = <String>{...capacities.keys, ...targets.keys};
        for (final t in tasks) {
          final n = txt(t['owner']).trim();
          if (n.isNotEmpty && n != 'Atanmamış') names.add(n);
        }
        final people = names.toList()..sort();
        final rows = <Map<String, dynamic>>[];
        final missing = <String, int>{'tarih': 0, 'sorumlu': 0, 'süre': 0};
        final loadByDay = <String, int>{};
        final countByWeek = <String, int>{};
        for (final t in tasks) {
          if (['Tamamlandı', 'İptal'].contains(txt(t['status']))) continue;
          final d = date(t['targetDate'] ?? t['due']);
          final n = txt(t['owner']).trim();
          final raw = int.tryParse(txt(t['estimatedMinutes']));
          if (d == null) {missing['tarih'] = missing['tarih']! + 1; continue;}
          if (n.isEmpty || n == 'Atanmamış') {missing['sorumlu'] = missing['sorumlu']! + 1; continue;}
          if (raw == null || raw < 5 || raw > 1440) missing['süre'] = missing['süre']! + 1;
          if (d.isBefore(start) || !d.isBefore(end)) continue;
          if (!weekends && d.weekday >= 6) continue;
          final minutes = raw != null && raw >= 5 && raw <= 1440 ? raw : 30;
          final key = '$n|${iso(d)}';
          loadByDay[key] = (loadByDay[key] ?? 0) + minutes;
          final wk = '$n|${iso(monday(d))}';
          countByWeek[wk] = (countByWeek[wk] ?? 0) + 1;
        }
        final repeated = <String, int>{};
        for (final h in history) {
          if (txt(h['type']) != 'fairness_approved' && !txt(h['name']).toLowerCase().contains('adalet')) continue;
          final after = maps(h['after']);
          final seen = <String>{};
          for (final t in after) {
            final n = txt(t['owner']).trim();
            if (n.isNotEmpty && n != 'Atanmamış') seen.add(n);
          }
          for (final n in seen) { repeated[n] = (repeated[n] ?? 0) + 1; }
        }
        for (final n in people) {
          for (var i = 0; i < weeks; i++) {
            final week = start.add(Duration(days: 7 * i));
            var planned = 0, capacity = 0, riskDays = 0, overflow = 0;
            for (var j = 0; j < 7; j++) {
              final d = week.add(Duration(days: j));
              if (!weekends && d.weekday >= 6) continue;
              final used = loadByDay['$n|${iso(d)}'] ?? 0;
              final cap = capacities[n] ?? 120;
              planned += used; capacity += cap;
              if (used > cap) {riskDays++; overflow += used - cap;}
            }
            final target = targets[n] ?? 80;
            final allowed = (capacity * (target + tolerance).clamp(0, 100) / 100).round();
            final gap = (planned - allowed).clamp(0, 999999999);
            final count = countByWeek['$n|${iso(week)}'] ?? 0;
            if (count == 0 && planned == 0) continue;
            final repeatedWeeks = (0 < i ? rows.where((r) => r['owner'] == n && (r['gap'] as int) > 0).length : 0);
            final riskScore = (gap > 0 ? 35 : 0) + (riskDays > 0 ? 25 : 0) + (overflow > 0 ? 15 : 0) + (repeatedWeeks >= repeatThreshold - 1 ? 20 : 0) + ((repeated[n] ?? 0) >= repeatThreshold ? 5 : 0);
            rows.add({'owner': n, 'week': iso(week), 'planned': planned, 'capacity': capacity,
              'util': capacity > 0 ? (planned * 100 / capacity).round() : 0, 'target': target,
              'gap': gap, 'riskDays': riskDays, 'overflow': overflow, 'tasks': count,
              'repeatWeeks': repeatedWeeks + (gap > 0 ? 1 : 0), 'pastRecords': repeated[n] ?? 0,
              'score': riskScore.clamp(0, 100)});
          }
        }
        rows.sort((a, b) => (b['score'] as int).compareTo(a['score'] as int));
        final filtered = rows.where((r) {
          if (owner != 'Tümü' && r['owner'] != owner) return false;
          if (risksOnly && (r['gap'] as int) == 0 && (r['riskDays'] as int) == 0) return false;
          return '${r['owner']} ${r['week']}'.toLowerCase().contains(query.toLowerCase());
        }).toList();
        final riskCount = rows.where((r) => (r['gap'] as int) > 0 || (r['riskDays'] as int) > 0).length;
        final totalGap = rows.fold<int>(0, (v, r) => v + (r['gap'] as int));
        final report = <String>['Sorumlu;Hafta;Görev;Planlanan dk;Kapasite dk;Doluluk %;Hedef %;Hedef üstü dk;Riskli gün;Kapasite aşımı dk;Risk puanı;Tekrarlayan riskli hafta'];
        for (final r in filtered) {
          report.add([r['owner'], r['week'], r['tasks'], r['planned'], r['capacity'], r['util'], r['target'], r['gap'], r['riskDays'], r['overflow'], r['score'], r['repeatWeeks']].map(csv).join(';'));
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
          Row(children:[const Expanded(child:Text('Tekrarlayan adalet riskleri / önleyici aksiyon merkezi',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Mevcut görev planından haftalık riskler hesaplanır. Geçmiş işlem sayıları yalnızca destekleyici sinyaldir; bağımsız risk veya gerçek gerçekleşme değildir. Otomatik görev değişikliği yapılmaz.'),
          if (busy) const LinearProgressIndicator() else ...[
            Wrap(spacing:10,runSpacing:8,children:[
              DropdownButton<int>(value:weeks,items:[4,8,12,26,52].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>update(()=>weeks=v??4)),
              DropdownButton<int>(value:tolerance,items:[0,5,10,15,20,30].map((v)=>DropdownMenuItem(value:v,child:Text('Tolerans +$v'))).toList(),onChanged:(v)=>update(()=>tolerance=v??10)),
              DropdownButton<int>(value:repeatThreshold,items:[2,3,4,5].map((v)=>DropdownMenuItem(value:v,child:Text('Tekrar eşiği $v'))).toList(),onChanged:(v)=>update(()=>repeatThreshold=v??2)),
              DropdownButton<String>(value:people.contains(owner)?owner:'Tümü',items:['Tümü',...people].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>owner=v??'Tümü')),
            ]),
            Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:7*weeks))),child:const Text('← Önceki')),OutlinedButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),OutlinedButton(onPressed:()=>update(()=>anchor=anchor.add(Duration(days:7*weeks))),child:const Text('Sonraki →'))]),
            Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
            SwitchListTile(title:const Text('Hafta sonlarını kapasiteye dahil et'),value:weekends,onChanged:(v)=>update(()=>weekends=v)),
            SwitchListTile(title:const Text('Yalnızca riskli haftalar'),value:risksOnly,onChanged:(v)=>update(()=>risksOnly=v)),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sorumlu veya hafta ara'),onChanged:(v)=>update(()=>query=v)),
            Card(color:const Color(0xFFFFF3FA),child:Padding(padding:const EdgeInsets.all(12),child:Text('Analiz: ${rows.length} sorumlu-hafta • Riskli: $riskCount • Hedef üstü: $totalGap dk • Geçmiş işlem: ${history.length}',style:const TextStyle(fontWeight:FontWeight.bold)))),
            if (missing.values.any((v)=>v>0)) Text('Veri kalitesi: ${missing['tarih']} tarihsiz, ${missing['sorumlu']} sorumlusuz, ${missing['süre']} varsayılan 30 dk ile hesaplanan görev.',style:const TextStyle(fontSize:12)),
            const SizedBox(height:8),
            Text('Önleyici aksiyon öncelikleri (${filtered.length})',style:Theme.of(ctx).textTheme.titleMedium),
            if (filtered.isEmpty)const ListTile(title:Text('Seçili dönemde bu filtrelerle kayıt bulunamadı.')),
            ...filtered.take(120).map((r) {
              final gap=r['gap'] as int, days=r['riskDays'] as int, rep=r['repeatWeeks'] as int;
              final advice=gap>0 && days>0?'Görev tarihlerini ve sorumlu dağılımını birlikte gözden geçir.':gap>0?'Haftalık yükü daha düşük doluluklu sorumlulara dağıtmayı değerlendir.':days>0?'Yoğun günlerdeki görevleri haftanın boş günlerine kaydırmayı değerlendir.':'Hedef içinde; düzenli izle.';
              return Card(child:ListTile(leading:CircleAvatar(child:Text('${r['score']}')),title:Text('${r['owner']} • ${r['week']}'),subtitle:Text('${r['tasks']} görev • ${r['planned']}/${r['capacity']} dk • Doluluk %${r['util']} (hedef %${r['target']})\nHedef üstü $gap dk • $days riskli gün • ${r['overflow']} dk kapasite aşımı\n${rep >= repeatThreshold ? 'Tekrarlayan haftalık risk ($rep hafta). ' : ''}$advice')));
            }),
            FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(ctx.mounted)_notice('Önleyici adalet risk raporu kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Filtrelenmiş CSV raporunu kopyala')),
            OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenFairnessApprovedDistribution();},child:const Text('Onaylı görev dengeleme merkezine geç')),
            OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenFairnessRiskTrends();},child:const Text('Geçmiş performans trendlerine geç')),
          ]
        ])));
      }),
    );
  }

  void _showKitchenFairnessRiskTrends() {
    const historyKey = 'paket40_optimization_plan_versions_v1';
    final versions = <Map<String, dynamic>>[];
    var started = false, loading = true, weeks = 12, minRepeats = 2;
    var onlyWorse = false, query = '', selectedOwner = 'Tümü';
    DateTime anchor = DateTime.now();
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    List<Map<String, dynamic>> list(Object? x) => x is List ? x.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> nums(Object? x) {
      final out = <String, int>{};
      if (x is Map) { for (final e in x.entries) { final v = int.tryParse(str(e.value)); if (v != null && v >= 0 && v <= 1440) out[str(e.key)] = v; } }
      return out;
    }
    Map<String, dynamic> measure(List<Map<String, dynamic>> tasks, Map<String, int> caps, Map<String, int> targets, int tolerance) {
      final perDay = <String, int>{}, perOwner = <String, int>{};
      final days = <DateTime>[];
      for (final t in tasks) {
        if (['Tamamlandı', 'İptal'].contains(str(t['status']))) continue;
        final d = parse(t['targetDate'] ?? t['due']);
        final o = str(t['owner']).trim();
        if (d == null || o.isEmpty || o == 'Atanmamış') continue;
        final raw = int.tryParse(str(t['estimatedMinutes']));
        final m = raw != null && raw >= 5 && raw <= 1440 ? raw : 30;
        days.add(d);
        perOwner[o] = (perOwner[o] ?? 0) + m;
        final k = '$o|${iso(d)}'; perDay[k] = (perDay[k] ?? 0) + m;
      }
      final risk = <String, int>{}, over = <String, int>{}, fairness = <String, int>{};
      for (final e in perDay.entries) {
        final o = e.key.split('|').first;
        final cap = (caps[o] ?? 120) > 0 ? (caps[o] ?? 120) : 120;
        if (e.value > cap) { risk[o] = (risk[o] ?? 0) + 1; over[o] = (over[o] ?? 0) + e.value - cap; }
      }
      if (days.isNotEmpty) {
        days.sort();
        final span = monday(days.last).difference(monday(days.first)).inDays + 7;
        for (final e in perOwner.entries) {
          final cap = (caps[e.key] ?? 120) > 0 ? (caps[e.key] ?? 120) : 120;
          final threshold = (cap * span * ((targets[e.key] ?? 75) + tolerance) / 100).round();
          fairness[e.key] = e.value > threshold ? e.value - threshold : 0;
        }
      }
      return {'risk': risk, 'over': over, 'fair': fairness, 'load': perOwner};
    }
    int sum(Map<String, int> values, String who) => who == 'Tümü' ? values.values.fold<int>(0, (a, b) => a + b) : (values[who] ?? 0);
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, update) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try { versions.addAll(list(jsonDecode(prefs.getString(historyKey) ?? '[]'))); }
          catch (_) { if (ctx.mounted) _notice('Optimizasyon geçmişi okunamadı.'); }
          if (ctx.mounted) update(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final records = <Map<String, dynamic>>[];
      final owners = <String>{};
      var legacy = 0, invalid = 0;
      for (final v in versions) {
        if (str(v['type']) != 'fairness_approved_distribution') continue;
        final at = parse(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        if (v['snapshotVersion'] != 1 || v['fullPlanBefore'] is! List || v['fullPlanAfter'] is! List || v['capacitySnapshot'] is! Map || v['fairnessTargetSnapshot'] is! Map) { legacy++; continue; }
        final before = list(v['fullPlanBefore']), after = list(v['fullPlanAfter']);
        if (before.isEmpty || after.isEmpty) { invalid++; continue; }
        final caps = nums(v['capacitySnapshot']), goals = nums(v['fairnessTargetSnapshot']);
        final tolerance = int.tryParse(str(v['fairnessToleranceSnapshot'])) ?? 10;
        final b = measure(before, caps, goals, tolerance), a = measure(after, caps, goals, tolerance);
        owners.addAll((a['load'] as Map<String, int>).keys);
        owners.addAll((b['load'] as Map<String, int>).keys);
        records.add({'date': at, 'name': str(v['name']), 'strategy': str(v['strategy']), 'before': b, 'after': a});
      }
      final choices = ['Tümü', ...(owners.toList()..sort())];
      if (!choices.contains(selectedOwner)) selectedOwner = 'Tümü';
      int val(Map<String, dynamic> r, String field, bool before) => sum((r[before ? 'before' : 'after'] as Map<String, dynamic>)[field] as Map<String, int>, selectedOwner);
      final filtered = records.where((r) {
        final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
        if (selectedOwner != 'Tümü' && !(b['load'] as Map<String, int>).containsKey(selectedOwner) && !(a['load'] as Map<String, int>).containsKey(selectedOwner)) return false;
        if (onlyWorse && val(r, 'fair', false) <= val(r, 'fair', true)) return false;
        return '${r['name']} ${r['strategy']} ${iso(r['date'] as DateTime)}'.toLowerCase().contains(query.toLowerCase());
      }).toList()..sort((a, b) => (b['date'] as DateTime).compareTo(a['date'] as DateTime));
      final weekly = <String, List<Map<String, dynamic>>>{};
      final recurring = <String, int>{};
      for (final r in filtered) {
        final key = iso(monday(r['date'] as DateTime));
        weekly.putIfAbsent(key, () => []).add(r);
        final risk = (r['after'] as Map<String, dynamic>)['risk'] as Map<String, int>;
        for (final e in risk.entries) { if (e.value > 0 && (selectedOwner == 'Tümü' || selectedOwner == e.key)) recurring[e.key] = (recurring[e.key] ?? 0) + 1; }
      }
      final weeksSorted = weekly.keys.toList()..sort((a, b) => b.compareTo(a));
      final repeated = recurring.entries.where((e) => e.value >= minRepeats).toList()..sort((a, b) => b.value.compareTo(a.value));
      final improved = filtered.where((r) => val(r, 'fair', true) > val(r, 'fair', false)).length;
      final worsened = filtered.where((r) => val(r, 'fair', true) < val(r, 'fair', false)).length;
      final netFair = filtered.fold<int>(0, (n, r) => n + val(r, 'fair', true) - val(r, 'fair', false));
      final netRisk = filtered.fold<int>(0, (n, r) => n + val(r, 'risk', true) - val(r, 'risk', false));
      return SafeArea(child: FractionallySizedBox(heightFactor: .96, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Adalet performans trendleri / tekrarlayan riskler', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        const Text('Tam plan geçmişindeki onaylı işlemleri haftalık karşılaştırır. Tekrarlayan risk, farklı işlem görüntülerinde aynı sorumlunun riskli kalmasıdır; bağımsız gün sayısı değildir.'),
        if (loading) const LinearProgressIndicator() else ...[
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (n) => update(() => weeks = n ?? 12)),
            DropdownButton<String>(value: selectedOwner, items: choices.map((o) => DropdownMenuItem(value: o, child: Text(o))).toList(), onChanged: (o) => update(() => selectedOwner = o ?? 'Tümü')),
            DropdownButton<int>(value: minRepeats, items: [2, 3, 4, 5].map((n) => DropdownMenuItem(value: n, child: Text('Tekrar ≥$n'))).toList(), onChanged: (n) => update(() => minRepeats = n ?? 2)),
          ]),
          Wrap(spacing: 8, children: [TextButton(onPressed: () => update(() => anchor = anchor.subtract(Duration(days: weeks * 7))), child: const Text('← Önceki')), TextButton(onPressed: () => update(() => anchor = DateTime.now()), child: const Text('Bugün')), TextButton(onPressed: () => update(() => anchor = anchor.add(Duration(days: weeks * 7))), child: const Text('Sonraki →'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('İşlem ${filtered.length} • İyileşen $improved • Kötüleşen $worsened'),
            Text('Net adalet hedef üstü yük azalması: $netFair dk • riskli sorumlu-gün farkı: $netRisk'),
            Text('İyileşen işlem oranı: ${filtered.isEmpty ? '—' : '${(improved * 100 / filtered.length).toStringAsFixed(1)}%'}'),
            Text('Eksik eski kayıt: $legacy • Geçersiz tam plan: $invalid'),
          ]))),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'İşlem / strateji / tarih ara'), onChanged: (v) => update(() => query = v)),
          SwitchListTile(title: const Text('Yalnızca kötüleşen işlemler'), value: onlyWorse, onChanged: (v) => update(() => onlyWorse = v)),
          const Text('Tekrarlayan sorumlu riskleri', style: TextStyle(fontWeight: FontWeight.bold)),
          if (repeated.isEmpty) const ListTile(title: Text('Seçilen tekrar eşiğini aşan sorumlu yok.')),
          ...repeated.map((e) => ListTile(dense: true, leading: const Icon(Icons.warning_amber_outlined), title: Text(e.key), subtitle: Text('${e.value} farklı optimizasyon sonrası riskli görüntü • kapasite ve görev dağılımını gözden geçirin.'))),
          const Divider(),
          const Text('Haftalık optimizasyon eğilimleri', style: TextStyle(fontWeight: FontWeight.bold)),
          if (weeksSorted.isEmpty) const ListTile(title: Text('Bu dönemde uygun tam plan optimizasyon kaydı yok.')),
          ...weeksSorted.map((week) {
            final group = weekly[week]!;
            final gain = group.fold<int>(0, (n, r) => n + val(r, 'fair', true) - val(r, 'fair', false));
            final riskGain = group.fold<int>(0, (n, r) => n + val(r, 'risk', true) - val(r, 'risk', false));
            final good = group.where((r) => val(r, 'fair', true) > val(r, 'fair', false)).length;
            return ExpansionTile(title: Text('$week • ${group.length} işlem • $good iyileşen'), subtitle: Text('Adalet kazancı $gain dk • riskli gün farkı $riskGain'), children: group.map((r) {
              final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
              return ListTile(dense: true, title: Text(str(r['name'])), subtitle: Text('${iso(r['date'] as DateTime)} • ${r['strategy']}\nAdalet: ${val(r, 'fair', true)} → ${val(r, 'fair', false)} dk • Risk: ${val(r, 'risk', true)} → ${val(r, 'risk', false)}\nGünlük aşım: ${sum(b['over'] as Map<String, int>, selectedOwner)} → ${sum(a['over'] as Map<String, int>, selectedOwner)} dk'));
            }).toList());
          }),
          FilledButton.tonalIcon(onPressed: () async {
            final lines = <String>['Hafta;Tarih;İşlem;Strateji;Sorumlu;Adalet önce dk;Adalet sonra dk;Risk önce;Risk sonra;Günlük aşım önce dk;Günlük aşım sonra dk'];
            for (final r in filtered) {
              final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
              lines.add([iso(monday(r['date'] as DateTime)), iso(r['date'] as DateTime), r['name'], r['strategy'], selectedOwner, val(r, 'fair', true), val(r, 'fair', false), val(r, 'risk', true), val(r, 'risk', false), sum(b['over'] as Map<String, int>, selectedOwner), sum(a['over'] as Map<String, int>, selectedOwner)].map(csv).join(';'));
            }
            await Clipboard.setData(ClipboardData(text: '\uFEFF${lines.join('\r\n')}'));
            if (ctx.mounted) _notice('Adalet performans trendleri CSV olarak kopyalandı.');
          }, icon: const Icon(Icons.copy_outlined), label: const Text('CSV raporunu kopyala')),
          FilledButton.tonalIcon(onPressed: () { Navigator.pop(ctx); _showKitchenFairnessOptimizationScorecard(); }, icon: const Icon(Icons.assessment_outlined), label: const Text('Optimizasyon başarı karnesini aç')),
          const Text('Not: Kayıtlar işlem bazlıdır. Aynı görev veya sorumlu birden çok optimizasyonda tekrar sayılabilir. Geçmiş kayıtlar değiştirilmez.'),
        ],
      ])));
    }));
  }

  void _showKitchenFairnessOptimizationScorecard() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    final records = <Map<String, dynamic>>[];
    var loaded = false, busy = true, weeks = 12, onlyImproved = false, onlyRisk = false;
    var search = '', ownerFilter = 'Tümü', anchor = DateTime.now();
    String str(Object? x) => '${x ?? ''}';
    DateTime? date(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String owner(Map<String, dynamic> t) { final v = str(t['owner']).trim(); return v.isEmpty ? 'Atanmamış' : v; }
    int minutes(Map<String, dynamic> t) { final v = int.tryParse(str(t['estimatedMinutes'])); return v != null && v >= 5 && v <= 1440 ? v : 30; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(str(t['status']));
    List<Map<String, dynamic>> rows(Object? x) => x is List ? x.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> numbers(Object? x) { final result = <String, int>{}; if (x is Map) { for (final e in x.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 0 && n <= 1440) result[str(e.key)] = n; } } return result; }
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    Map<String, dynamic> evaluate(List<Map<String, dynamic>> plan, Map<String, int> caps, Map<String, int> goals, int tolerance) {
      final byDay = <String, int>{}, byOwner = <String, int>{};
      final dates = <String, DateTime>{};
      for (final t in plan) {
        if (!active(t)) continue;
        final d = date(t['targetDate'] ?? t['due']);
        if (d == null) continue;
        final p = owner(t);
        if (p == 'Atanmamış') continue;
        final m = minutes(t), k = '$p|${iso(d)}';
        byDay[k] = (byDay[k] ?? 0) + m;
        byOwner[p] = (byOwner[p] ?? 0) + m;
        dates[k] = d;
      }
      var dailyOver = 0, riskDays = 0, fairnessOver = 0;
      final fairnessOwners = <String, int>{}, riskOwners = <String, int>{};
      for (final e in byDay.entries) {
        final p = e.key.split('|').first, cap = (caps[p] ?? 120) > 0 ? (caps[p] ?? 120) : 120;
        if (e.value > cap) { dailyOver += e.value - cap; riskDays++; riskOwners[p] = (riskOwners[p] ?? 0) + 1; }
      }
      // Adalet metriği: planın kapsadığı her sorumlu için en erken ve en geç görev
      // tarihleri arasındaki takvim günlerinde kullanılabilir kapasite esas alınır.
      // Bu tarih aralığı tüm geçmiş kayıtlar için aynı olmadığından karşılaştırma
      // yalnızca aynı sürümün önce/sonra görüntüleri arasında anlamlıdır.
      final allDates = dates.values.toList()..sort();
      if (allDates.isNotEmpty) {
        final first = monday(allDates.first), last = monday(allDates.last).add(const Duration(days: 7));
        final span = last.difference(first).inDays;
        for (final e in byOwner.entries) {
          final cap = (caps[e.key] ?? 120) > 0 ? (caps[e.key] ?? 120) : 120;
          final threshold = (cap * span * ((goals[e.key] ?? 75) + tolerance) / 100).round();
          final over = e.value > threshold ? e.value - threshold : 0;
          fairnessOwners[e.key] = over; fairnessOver += over;
        }
      }
      return {'daily': dailyOver, 'risk': riskDays, 'fair': fairnessOver, 'owners': byOwner, 'fairOwners': fairnessOwners, 'riskOwners': riskOwners};
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!loaded) {
        loaded = true;
        SharedPreferences.getInstance().then((prefs) {
          try { records.addAll(rows(jsonDecode(prefs.getString(versionsKey) ?? '[]'))); }
          catch (_) { if (ctx.mounted) _notice('Optimizasyon geçmişi okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final end = monday(anchor).add(const Duration(days: 7));
      final start = end.subtract(Duration(days: weeks * 7));
      final analyzed = <Map<String, dynamic>>[], allOwners = <String>{};
      var legacy = 0, invalid = 0;
      for (final v in records) {
        if (str(v['type']) != 'fairness_approved_distribution') continue;
        final at = date(v['at']);
        if (at == null || at.isBefore(start) || !at.isBefore(end)) continue;
        if (v['snapshotVersion'] != 1 || v['fullPlanBefore'] is! List || v['fullPlanAfter'] is! List || v['capacitySnapshot'] is! Map || v['fairnessTargetSnapshot'] is! Map) { legacy++; continue; }
        final before = rows(v['fullPlanBefore']), after = rows(v['fullPlanAfter']);
        if (before.isEmpty || after.isEmpty) { invalid++; continue; }
        final caps = numbers(v['capacitySnapshot']), goals = numbers(v['fairnessTargetSnapshot']);
        final tolerance = int.tryParse(str(v['fairnessToleranceSnapshot'])) ?? 10;
        final b = evaluate(before, caps, goals, tolerance), a = evaluate(after, caps, goals, tolerance);
        final ownersB = b['owners'] as Map<String, int>, ownersA = a['owners'] as Map<String, int>;
        allOwners.addAll(ownersB.keys); allOwners.addAll(ownersA.keys);
        analyzed.add({'at': at, 'name': str(v['name']), 'strategy': str(v['strategy']), 'before': b, 'after': a,
          'moves': rows(v['after']).length, 'tolerance': tolerance});
      }
      analyzed.sort((a, b) => (b['at'] as DateTime).compareTo(a['at'] as DateTime));
      final owners = ['Tümü', ...(allOwners.toList()..sort())];
      if (!owners.contains(ownerFilter)) ownerFilter = 'Tümü';
      int metric(Map<String, dynamic> r, String field, {bool before = false}) {
        final snapshot = r[before ? 'before' : 'after'] as Map<String, dynamic>;
        if (ownerFilter == 'Tümü') return snapshot[field] as int;
        final key = field == 'fair' ? 'fairOwners' : field == 'risk' ? 'riskOwners' : 'owners';
        return (snapshot[key] as Map<String, int>)[ownerFilter] ?? 0;
      }
      final filtered = analyzed.where((r) {
        if (ownerFilter != 'Tümü') {
          final b = (r['before'] as Map<String, dynamic>)['owners'] as Map<String, int>;
          final a = (r['after'] as Map<String, dynamic>)['owners'] as Map<String, int>;
          if (!b.containsKey(ownerFilter) && !a.containsKey(ownerFilter)) return false;
        }
        if (onlyImproved && metric(r, 'fair', before: true) <= metric(r, 'fair')) return false;
        if (onlyRisk && metric(r, 'risk') == 0) return false;
        return '${r['name']} ${r['strategy']} ${iso(r['at'] as DateTime)}'.toLowerCase().contains(search.toLowerCase());
      }).toList();
      final improvements = filtered.where((r) => metric(r, 'fair', before: true) > metric(r, 'fair')).length;
      final worsenings = filtered.where((r) => metric(r, 'fair', before: true) < metric(r, 'fair')).length;
      final totalGain = filtered.fold<int>(0, (sum, r) => sum + metric(r, 'fair', before: true) - metric(r, 'fair'));
      final weeksMap = <String, List<Map<String, dynamic>>>{};
      for (final r in filtered) { final w = iso(monday(r['at'] as DateTime)); weeksMap.putIfAbsent(w, () => []).add(r); }
      final weeklyKeys = weeksMap.keys.toList()..sort((a, b) => b.compareTo(a));
      return SafeArea(child: FractionallySizedBox(heightFactor: .96, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Adalet optimizasyonu / başarı karnesi', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        const Text('Onaylanmış adalet optimizasyonlarının tam plan görüntülerini, işlem anında kaydedilmiş kapasite ve hedeflerle karşılaştırır. Geçmişi değiştirmez.'),
        if (busy) const LinearProgressIndicator() else ...[
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<int>(value: weeks, items: [4, 8, 12, 26, 52].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (n) => refresh(() => weeks = n ?? 12)),
            DropdownButton<String>(value: ownerFilter, items: owners.map((p) => DropdownMenuItem(value: p, child: Text(p))).toList(), onChanged: (p) => refresh(() => ownerFilter = p ?? 'Tümü')),
          ]),
          Wrap(spacing: 8, children: [TextButton(onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), child: const Text('← Önceki')), TextButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün')), TextButton(onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), child: const Text('Sonraki →'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('İşlem ${filtered.length} • İyileşen $improvements • Kötüleşen $worsenings'),
            Text('Net adalet hedef üstü yük azalması: $totalGain dk'),
            Text('Tam planı eksik eski kayıt: $legacy • Geçersiz kayıt: $invalid'),
            Text('İyileşen işlem oranı: ${filtered.isEmpty ? '—' : '${(100 * improvements / filtered.length).toStringAsFixed(1)}%'}'),
          ]))),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'İşlem adı / strateji / tarih ara'), onChanged: (v) => refresh(() => search = v)),
          SwitchListTile(title: const Text('Yalnızca iyileşen işlemler'), value: onlyImproved, onChanged: (v) => refresh(() => onlyImproved = v)),
          SwitchListTile(title: const Text('Sonrasında riskli gün kalanlar'), value: onlyRisk, onChanged: (v) => refresh(() => onlyRisk = v)),
          if (filtered.isEmpty) const ListTile(title: Text('Seçilen koşullarda tam plan optimizasyon kaydı bulunamadı.')),
          ...weeklyKeys.map((week) {
            final group = weeksMap[week]!;
            final gain = group.fold<int>(0, (sum, r) => sum + metric(r, 'fair', before: true) - metric(r, 'fair'));
            final riskGain = group.fold<int>(0, (sum, r) => sum + metric(r, 'risk', before: true) - metric(r, 'risk'));
            return ExpansionTile(title: Text('$week haftası • ${group.length} işlem'), subtitle: Text('Hedef sapması farkı: $gain dk • riskli gün farkı: $riskGain'), children: group.map((r) {
              final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
              final bOwners = b['owners'] as Map<String, int>, aOwners = a['owners'] as Map<String, int>;
              final people = <String>{...bOwners.keys, ...aOwners.keys}.toList()..sort();
              return ExpansionTile(title: Text(str(r['name'])), subtitle: Text('${iso(r['at'] as DateTime)} • ${r['strategy']} • ${r['moves']} değişiklik\nAdalet ${metric(r, 'fair', before: true)} → ${metric(r, 'fair')} dk • Risk ${metric(r, 'risk', before: true)} → ${metric(r, 'risk')}'), children: [
                ListTile(dense: true, title: Text('Günlük aşım: ${b['daily']} → ${a['daily']} dk • tolerans ${r['tolerance']} puan')),
                ...people.where((p) => ownerFilter == 'Tümü' || p == ownerFilter).map((p) => ListTile(dense: true, title: Text(p), subtitle: Text('İş yükü: ${bOwners[p] ?? 0} → ${aOwners[p] ?? 0} dk • Adalet sapması: ${(b['fairOwners'] as Map<String, int>)[p] ?? 0} → ${(a['fairOwners'] as Map<String, int>)[p] ?? 0} dk'))),
              ]);
            }).toList());
          }),
          FilledButton.tonalIcon(onPressed: () async {
            final lines = <String>['Hafta;Tarih;İşlem;Strateji;Sorumlu;Görev değişikliği;Önceki adalet dk;Sonraki adalet dk;Önceki riskli gün;Sonraki riskli gün'];
            for (final r in filtered) { lines.add([iso(monday(r['at'] as DateTime)), iso(r['at'] as DateTime), r['name'], r['strategy'], ownerFilter, r['moves'], metric(r, 'fair', before: true), metric(r, 'fair'), metric(r, 'risk', before: true), metric(r, 'risk')].map(csv).join(';')); }
            await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
            if (ctx.mounted) _notice('Başarı karnesi CSV olarak panoya kopyalandı.');
          }, icon: const Icon(Icons.copy_outlined), label: const Text('CSV raporunu kopyala')),
          FilledButton.tonalIcon(onPressed: () { Navigator.pop(ctx); _showKitchenFairnessApprovedDistribution(); }, icon: const Icon(Icons.tune_outlined), label: const Text('Yeni onaylı optimizasyon oluştur')),
          const Text('Not: Aynı görev birden fazla işlemde yer alabilir; işlem bazlı kazanımlar bağımsız zaman tasarrufu değildir. Adalet sapması, her kayıt için planın kapsadığı haftalık aralık üzerinden hesaplanır.'),
        ],
      ])));
    }));
  }

  void _showKitchenFairnessApprovedDistribution() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const fairnessKey = 'paket42_fairness_utilization_targets_v1';
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{}, targets = <String, int>{};
    var started = false, busy = true, saving = false;
    var weeks = 2, strategy = 2, tolerance = 10, limit = 20, offset = 0;
    var weekends = true, selectedOnly = false, search = '';
    final selected = <int>{};
    String str(Object? v) => '${v ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) => DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    String owner(Map<String, dynamic> t) { final p = str(t['owner']).trim(); return p.isEmpty ? 'Atanmamış' : p; }
    int minutes(Map<String, dynamic> t) { final n = int.tryParse(str(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(str(t['status']));
    bool protected(Map<String, dynamic> t) { final p = str(t['priority'] ?? t['level']).toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high'); }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (raw is List) tasks.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            for (final pair in <String, Map<String, int>>{capacityKey: capacities, fairnessKey: targets}.entries) {
              final data = jsonDecode(prefs.getString(pair.key) ?? '{}');
              if (data is Map) for (final e in data.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 0) pair.value[str(e.key)] = n; }
            }
          } catch (_) { if (ctx.mounted) _notice('Görev veya hedef kayıtları okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final start = monday(DateTime.now()).add(Duration(days: offset * 7));
      final days = weeks * 7, end = start.add(Duration(days: days));
      final people = <String>{...capacities.keys, ...targets.keys, ...tasks.map(owner)}.where((p) => p != 'Atanmamış').toList()..sort();
      final entries = <Map<String, dynamic>>[];
      final base = <String, int>{};
      String key(String p, DateTime d) => '$p|${iso(d)}';
      int cap(String p) { final n = capacities[p] ?? 120; return n > 0 ? n : 120; }
      int pos(int n) => n > 0 ? n : 0;
      var missing = 0, protectedCount = 0;
      for (var i = 0; i < tasks.length; i++) {
        final t = tasks[i]; if (!active(t)) continue;
        final d = parse(t['targetDate'] ?? t['due']);
        if (d == null || owner(t) == 'Atanmamış') { missing++; continue; }
        if (d.isBefore(start) || !d.isBefore(end) || (!weekends && d.weekday >= 6)) continue;
        final m = minutes(t), p = owner(t);
        base[key(p, d)] = (base[key(p, d)] ?? 0) + m;
        if (protected(t)) protectedCount++;
        entries.add({'index': i, 'title': str(t['title']), 'owner': p, 'date': d, 'minutes': m, 'protected': protected(t)});
      }
      int dailyExcess(Map<String, int> loads) => loads.entries.fold<int>(0, (sum, e) => sum + pos(e.value - cap(e.key.split('|').first)));
      int riskDays(Map<String, int> loads) => loads.entries.where((e) => e.value > cap(e.key.split('|').first)).length;
      int fairnessExcess(Map<String, int> loads) {
        var total = 0;
        for (final p in people) {
          var used = 0, available = 0;
          for (var i = 0; i < days; i++) {
            final d = start.add(Duration(days: i));
            if (!weekends && d.weekday >= 6) continue;
            used += loads[key(p, d)] ?? 0; available += cap(p);
          }
          total += pos(used - (available * ((targets[p] ?? 75) + tolerance) / 100).round());
        }
        return total;
      }
      Map<String, dynamic> simulate(int mode) {
        final loads = Map<String, int>.from(base);
        final moves = <Map<String, dynamic>>[];
        final movable = entries.where((e) => e['protected'] != true).toList()..sort((a, b) => (b['minutes'] as int).compareTo(a['minutes'] as int));
        for (final e in movable) {
          if (moves.length >= limit) break;
          final p = e['owner'] as String, d = e['date'] as DateTime, m = e['minutes'] as int, from = key(p, d);
          String? bestP; DateTime? bestD; var bestScore = 0;
          final beforeFair = fairnessExcess(loads);
          for (final candidate in people) {
            if (mode == 0 && candidate != p) continue;
            for (var i = 0; i < days; i++) {
              final next = start.add(Duration(days: i));
              if (next.isBefore(d) || (!weekends && next.weekday >= 6) || (mode == 1 && next != d) || (candidate == p && next == d)) continue;
              final to = key(candidate, next), oldFrom = loads[from] ?? 0, oldTo = loads[to] ?? 0;
              final beforeDaily = pos(oldFrom - cap(p)) + pos(oldTo - cap(candidate));
              final afterDaily = pos(oldFrom - m - cap(p)) + pos(oldTo + m - cap(candidate));
              loads[from] = oldFrom - m; loads[to] = oldTo + m;
              final gainFair = beforeFair - fairnessExcess(loads);
              loads[from] = oldFrom; loads[to] = oldTo;
              final gainDaily = beforeDaily - afterDaily;
              final score = gainFair * 2 + gainDaily * 3 - next.difference(d).inDays * 2 - (candidate == p ? 0 : 5);
              if (score > bestScore && (gainFair > 0 || gainDaily > 0)) { bestScore = score; bestP = candidate; bestD = next; }
            }
          }
          if (bestP != null && bestD != null) {
            loads[from] = (loads[from] ?? 0) - m;
            final to = key(bestP, bestD); loads[to] = (loads[to] ?? 0) + m;
            moves.add({...e, 'toOwner': bestP, 'toDate': bestD, 'score': bestScore});
          }
        }
        return {'moves': moves, 'fair': fairnessExcess(loads), 'daily': dailyExcess(loads), 'risk': riskDays(loads)};
      }
      final scenarios = busy ? <Map<String, dynamic>>[] : [simulate(0), simulate(1), simulate(2)];
      final moves = busy ? <Map<String, dynamic>>[] : scenarios[strategy]['moves'] as List<Map<String, dynamic>>;
      selected.removeWhere((i) => i >= moves.length);
      final preview = Map<String, int>.from(base);
      for (final i in selected) {
        final e = moves[i], m = e['minutes'] as int;
        final from = key(e['owner'] as String, e['date'] as DateTime), to = key(e['toOwner'] as String, e['toDate'] as DateTime);
        preview[from] = (preview[from] ?? 0) - m; preview[to] = (preview[to] ?? 0) + m;
      }
      final visible = <int>[];
      for (var i = 0; i < moves.length; i++) {
        final e = moves[i];
        if (selectedOnly && !selected.contains(i)) continue;
        if (!'${e['title']} ${e['owner']} ${e['toOwner']}'.toLowerCase().contains(search.toLowerCase())) continue;
        visible.add(i);
      }
      Future<void> apply() async {
        if (saving || selected.isEmpty) return;
        final chosen = selected.toList()..sort();
        final confirmed = await showDialog<bool>(context: ctx, builder: (dialog) => AlertDialog(
          title: const Text('Seçilen görevleri uygula?'),
          content: Text('${chosen.length} görev güncellenecek. Adalet hedef üstü yük: ${fairnessExcess(base)} → ${fairnessExcess(preview)} dk. Günlük aşım: ${dailyExcess(base)} → ${dailyExcess(preview)} dk. Tam plan geçmişi kaydedilecek.'),
          actions: [TextButton(onPressed: () => Navigator.pop(dialog, false), child: const Text('Vazgeç')),
            FilledButton(onPressed: () => Navigator.pop(dialog, true), child: const Text('Onayla ve kaydet'))]));
        if (confirmed != true || !ctx.mounted) return;
        refresh(() => saving = true);
        try {
          final prefs = await SharedPreferences.getInstance();
          final original = prefs.getString(taskKey) ?? '[]';
          final raw = jsonDecode(original);
          if (raw is! List) throw StateError('Görev kayıtları geçersiz.');
          final fresh = raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          if (jsonEncode(fresh) != jsonEncode(tasks)) throw StateError('Görevler başka bir ekranda değişmiş. Yeniden açın.');
          final oldCaps = prefs.getString(capacityKey) ?? '{}', oldTargets = prefs.getString(fairnessKey) ?? '{}';
          if (jsonEncode(jsonDecode(oldCaps)) != jsonEncode(capacities) || jsonEncode(jsonDecode(oldTargets)) != jsonEncode(targets)) {
            throw StateError('Kapasite veya adalet hedefleri değişmiş. Yeniden açın.');
          }
          final originalVersions = prefs.getString(versionsKey) ?? '[]';
          final decoded = jsonDecode(originalVersions);
          if (decoded is! List) throw StateError('Plan geçmişi geçersiz.');
          final versions = decoded.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList();
          final beforePlan = fresh.map((e) => Map<String, dynamic>.from(e)).toList();
          final before = <Map<String, dynamic>>[], after = <Map<String, dynamic>>[];
          final stamp = DateTime.now().toIso8601String();
          for (final i in chosen) {
            final e = moves[i], index = e['index'] as int, task = fresh[index];
            if (!active(task) || protected(task) || owner(task) != e['owner'] ||
                iso(parse(task['targetDate'] ?? task['due']) ?? DateTime(1900)) != iso(e['date'] as DateTime)) {
              throw StateError('Görev doğrulaması başarısız.');
            }
            before.add(Map<String, dynamic>.from(task));
            task['owner'] = e['toOwner']; task['targetDate'] = iso(e['toDate'] as DateTime); task['updated'] = stamp;
            final history = task['history'] is List ? List<dynamic>.from(task['history'] as List) : <dynamic>[];
            history.add({'at': stamp, 'action': 'Onaylı adalet optimizasyonu', 'note': '${e['owner']} / ${iso(e['date'] as DateTime)} → ${e['toOwner']} / ${task['targetDate']}'});
            task['history'] = history;
            after.add(Map<String, dynamic>.from(task));
          }
          versions.insert(0, {'at': stamp, 'name': 'Adalet dengeleme • ${chosen.length} görev',
            'type': 'fairness_approved_distribution', 'note': 'Adalet ${fairnessExcess(base)} → ${fairnessExcess(preview)} dk; günlük ${dailyExcess(base)} → ${dailyExcess(preview)} dk',
            'before': before, 'after': after, 'fullPlanBefore': beforePlan,
            'fullPlanAfter': fresh.map((e) => Map<String, dynamic>.from(e)).toList(),
            'capacitySnapshot': Map<String, int>.from(capacities),
            'fairnessTargetSnapshot': Map<String, int>.from(targets), 'fairnessToleranceSnapshot': tolerance,
            'strategy': ['date', 'owner', 'hybrid'][strategy], 'snapshotVersion': 1});
          if (!await prefs.setString(taskKey, jsonEncode(fresh))) throw StateError('Görevler kaydedilemedi.');
          if (!await prefs.setString(versionsKey, jsonEncode(versions.take(100).toList()))) {
            await prefs.setString(taskKey, original);
            throw StateError('Plan geçmişi kaydedilemedi; görevler geri alındı.');
          }
          tasks..clear()..addAll(fresh); selected.clear();
          if (ctx.mounted) { refresh(() {}); _notice('${chosen.length} görev güncellendi ve plan geçmişine kaydedildi.'); }
        } catch (e) { if (ctx.mounted) _notice('Kaydetme başarısız: $e'); }
        finally { if (ctx.mounted) refresh(() => saving = false); }
      }
      return SafeArea(child: FractionallySizedBox(heightFactor: .96, child: ListView(padding: const EdgeInsets.all(14), children: [
        Row(children: [const Expanded(child: Text('Onaylı adalet optimizasyonu / görev dağılımı', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18))), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
        const Text('Öneriler bu ekranda yeniden hesaplanır. Seçimler onay verilene kadar hiçbir görevi değiştirmez. Kişilerin gerçek müsaitliği ve yetkinliği doğrulanmaz.'),
        if (busy) const LinearProgressIndicator() else ...[
          Wrap(spacing: 8, runSpacing: 4, children: [
            DropdownButton<int>(value: weeks, items: [1, 2, 4, 6, 8, 12].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (n) => refresh(() { weeks = n ?? 2; selected.clear(); })),
            DropdownButton<int>(value: tolerance, items: [0, 5, 10, 15, 20, 30].map((n) => DropdownMenuItem(value: n, child: Text('Tolerans $n puan'))).toList(), onChanged: (n) => refresh(() { tolerance = n ?? 10; selected.clear(); })),
            DropdownButton<int>(value: limit, items: [5, 10, 20, 40].map((n) => DropdownMenuItem(value: n, child: Text('En fazla $n öneri'))).toList(), onChanged: (n) => refresh(() { limit = n ?? 20; selected.clear(); })),
            DropdownButton<int>(value: strategy, items: const [DropdownMenuItem(value: 0, child: Text('Tarih')), DropdownMenuItem(value: 1, child: Text('Sorumlu')), DropdownMenuItem(value: 2, child: Text('Karma'))], onChanged: (n) => refresh(() { strategy = n ?? 2; selected.clear(); })),
          ]),
          Wrap(spacing: 8, children: [TextButton(onPressed: () => refresh(() { offset -= weeks; selected.clear(); }), child: const Text('← Önceki')), TextButton(onPressed: () => refresh(() { offset = 0; selected.clear(); }), child: const Text('Bugün')), TextButton(onPressed: () => refresh(() { offset += weeks; selected.clear(); }), child: const Text('Sonraki →'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))}'),
          SwitchListTile(title: const Text('Hafta sonlarını dahil et'), value: weekends, onChanged: (v) => refresh(() { weekends = v; selected.clear(); })),
          Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Görev: ${entries.length} • Korunan kritik/yüksek: $protectedCount • Eksik atama/tarih: $missing'),
            Text('Başlangıç: adalet hedef üstü ${fairnessExcess(base)} dk • günlük aşım ${dailyExcess(base)} dk • riskli gün ${riskDays(base)}'),
          ]))),
          ...List.generate(3, (i) { final x = scenarios[i]; return ListTile(dense: true, leading: Icon(i == strategy ? Icons.radio_button_checked : Icons.radio_button_unchecked), title: Text(['Tarih odaklı', 'Sorumlu odaklı', 'Karma'][i]), subtitle: Text('Adalet ${x['fair']} dk • Günlük aşım ${x['daily']} dk • Riskli gün ${x['risk']} • Öneri ${(x['moves'] as List).length}'), onTap: () => refresh(() { strategy = i; selected.clear(); })); }),
          const Divider(),
          Text('Seçili ${selected.length}/${moves.length} • adalet ${fairnessExcess(base)} → ${fairnessExcess(preview)} dk • günlük aşım ${dailyExcess(base)} → ${dailyExcess(preview)} dk • riskli gün ${riskDays(base)} → ${riskDays(preview)}', style: Theme.of(ctx).textTheme.titleMedium),
          Wrap(spacing: 8, children: [TextButton(onPressed: () => refresh(() { selected..clear()..addAll(List.generate(moves.length, (i) => i)); }), child: const Text('Tümünü seç')), TextButton(onPressed: () => refresh(selected.clear), child: const Text('Seçimi temizle'))]),
          SwitchListTile(title: const Text('Yalnızca seçilenleri göster'), value: selectedOnly, onChanged: (v) => refresh(() => selectedOnly = v)),
          TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Görev / sorumlu ara'), onChanged: (v) => refresh(() => search = v)),
          if (visible.isEmpty) const ListTile(title: Text('Bu koşullarda öneri bulunamadı.')),
          ...visible.map((i) { final e = moves[i]; return CheckboxListTile(value: selected.contains(i), controlAffinity: ListTileControlAffinity.leading, onChanged: (v) => refresh(() { if (v == true) { selected.add(i); } else { selected.remove(i); } }), title: Text(str(e['title'])), subtitle: Text('${e['owner']} / ${iso(e['date'] as DateTime)} → ${e['toOwner']} / ${iso(e['toDate'] as DateTime)}\n${e['minutes']} dk • Puan ${e['score']}')); }),
          FilledButton.tonalIcon(onPressed: () async { final lines = <String>['Görev;Önceki sorumlu;Önceki tarih;Yeni sorumlu;Yeni tarih;Süre;Puan;Seçili']; for (var i = 0; i < moves.length; i++) { final e = moves[i]; lines.add([e['title'], e['owner'], iso(e['date'] as DateTime), e['toOwner'], iso(e['toDate'] as DateTime), e['minutes'], e['score'], selected.contains(i)].map(csv).join(';')); } await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}')); if (ctx.mounted) _notice('CSV panoya kopyalandı.'); }, icon: const Icon(Icons.copy_outlined), label: const Text('CSV raporunu kopyala')),
          FilledButton.icon(onPressed: saving || selected.isEmpty ? null : apply, icon: const Icon(Icons.verified_user_outlined), label: Text(saving ? 'Kaydediliyor…' : 'Seçilen ${selected.length} görevi onayla ve uygula')),
          const Text('Tam plan geçmişi, mevcut geçmiş ekranından görüntülenebilir.'),
        ],
      ])));
    }));
  }

  void _showKitchenFairnessPreventiveBalancer() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const fairnessKey = 'paket42_fairness_utilization_targets_v1';
    final tasks = <Map<String,dynamic>>[];
    final caps = <String,int>{}, targets = <String,int>{};
    var started = false, busy = true, weeks = 4, tolerance = 10, strategy = 2, limit = 20;
    var weekends = true, offsetWeeks = 0, onlySelected = false, query = '';
    final selected = <int>{};
    String str(Object? v) => '${v ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) { final x=DateTime(d.year,d.month,d.day); return x.subtract(Duration(days:x.weekday-1)); }
    String owner(Map<String,dynamic> t) { final x=str(t['owner']).trim(); return x.isEmpty?'Atanmamış':x; }
    int minutes(Map<String,dynamic> t) { final n=int.tryParse(str(t['estimatedMinutes'])); return n!=null&&n>=5&&n<=1440?n:30; }
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    bool protected(Map<String,dynamic> t) { final p=str(t['priority']??t['level']).toLowerCase(); return p.contains('kritik')||p.contains('yüksek')||p.contains('critical')||p.contains('high'); }
    String csv(Object? v) => '"${str(v).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){
        started=true;
        SharedPreferences.getInstance().then((prefs){
          try{
            final raw=jsonDecode(prefs.getString(taskKey)??'[]');
            if(raw is List)tasks.addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
            for(final pair in <String,Map<String,int>>{capacityKey:caps,fairnessKey:targets}.entries){
              final data=jsonDecode(prefs.getString(pair.key)??'{}');
              if(data is Map)for(final e in data.entries){final n=int.tryParse(str(e.value));if(n!=null&&n>=0)pair.value[str(e.key)]=n;}
            }
          }catch(_){if(ctx.mounted)_notice('Görev ve hedef verileri okunamadı; hiçbir kayıt değiştirilmedi.');}
          if(ctx.mounted)refresh(()=>busy=false);
        }).catchError((Object _){if(ctx.mounted)refresh(()=>busy=false);});
      }
      final start=monday(DateTime.now()).add(Duration(days:7*offsetWeeks));
      final days=weeks*7, end=start.add(Duration(days:days));
      final people=<String>{...caps.keys,...targets.keys,...tasks.map(owner)}.where((x)=>x!='Atanmamış').toList()..sort();
      final entries=<Map<String,dynamic>>[];
      final base=<String,int>{};
      var missingDate=0,missingOwner=0,missingDuration=0,protectedCount=0;
      String key(String p,DateTime d)=>'$p|${iso(d)}';
      for(var i=0;i<tasks.length;i++){
        final t=tasks[i];if(!active(t))continue;
        final d=parse(t['targetDate']??t['due']);
        if(d==null){missingDate++;continue;}
        if(d.isBefore(start)||!d.isBefore(end))continue;
        final p=owner(t);if(p=='Atanmamış'){missingOwner++;continue;}
        if(int.tryParse(str(t['estimatedMinutes']))==null)missingDuration++;
        if(protected(t))protectedCount++;
        final m=minutes(t),k=key(p,d);
        base[k]=(base[k]??0)+m;
        entries.add({'index':i,'title':str(t['title']),'person':p,'date':d,'minutes':m,'protected':protected(t)});
      }
      int cap(String p)=>(caps[p]??120)>0?(caps[p]??120):120;
      int threshold(String p)=>targets[p]??75;
      int pos(int v)=>v>0?v:0;
      int dailyExcess(Map<String,int> load){var n=0;for(final e in load.entries){n+=pos(e.value-cap(e.key.split('|').first));}return n;}
      int riskDays(Map<String,int> load)=>load.entries.where((e)=>e.value>cap(e.key.split('|').first)).length;
      int fairnessExcess(Map<String,int> load){
        var total=0;
        for(final p in people){
          var used=0,available=0;
          for(var i=0;i<days;i++){
            final d=start.add(Duration(days:i));
            if(!weekends&&d.weekday>=6)continue;
            used+=load[key(p,d)]??0;available+=cap(p);
          }
          if(available>0){final allowed=(available*(threshold(p)+tolerance)/100).round();total+=pos(used-allowed);}
        }
        return total;
      }
      // Each strategy uses the same capacity, dates and target settings.
      Map<String,dynamic> simulate(int mode){
        final loads=Map<String,int>.from(base);
        final proposals=<Map<String,dynamic>>[];
        final movable=entries.where((e)=>e['protected']!=true).toList()..sort((a,b)=>(b['minutes'] as int).compareTo(a['minutes'] as int));
        for(final e in movable){
          if(proposals.length>=limit)break;
          final p=e['person'] as String,d=e['date'] as DateTime,m=e['minutes'] as int,from=key(p,d);
          String? bestP;DateTime? bestD;var bestScore=0,bestGain=0;
          for(final candidate in people){
            if(mode==0&&candidate!=p)continue;
            for(var i=0;i<days;i++){
              final date=start.add(Duration(days:i));
              if(date.isBefore(d)||(!weekends&&date.weekday>=6))continue;
              if(mode==1&&date!=d)continue;
              if(candidate==p&&date==d)continue;
              final to=key(candidate,date);
              final oldFrom=loads[from]??0,oldTo=loads[to]??0;
              final beforeDaily=pos(oldFrom-cap(p))+pos(oldTo-cap(candidate));
              final afterDaily=pos(oldFrom-m-cap(p))+pos(oldTo+m-cap(candidate));
              final dailyGain=beforeDaily-afterDaily;
              // Fairness improvement is evaluated on the entire period, not just one day.
              final oldFair=fairnessExcess(loads);
              loads[from]=oldFrom-m;loads[to]=oldTo+m;
              final fairGain=oldFair-fairnessExcess(loads);
              loads[from]=oldFrom;loads[to]=oldTo;
              final delay=date.difference(d).inDays;
              final score=dailyGain*3+fairGain-delay*2-(candidate==p?0:5);
              if(score>bestScore&&(dailyGain>0||fairGain>0)){
                bestScore=score;bestGain=dailyGain;bestP=candidate;bestD=date;
              }
            }
          }
          if(bestP!=null&&bestD!=null){
            loads[from]=(loads[from]??0)-m;
            final to=key(bestP,bestD);loads[to]=(loads[to]??0)+m;
            proposals.add({...e,'toPerson':bestP,'toDate':bestD,'score':bestScore,'dailyGain':bestGain});
          }
        }
        return {'loads':loads,'moves':proposals,'daily':dailyExcess(loads),'fair':fairnessExcess(loads),'risk':riskDays(loads)};
      }
      final scenarios=[simulate(0),simulate(1),simulate(2)];
      final scenario=scenarios[strategy];
      final moves=scenario['moves'] as List<Map<String,dynamic>>;
      selected.removeWhere((i)=>i>=moves.length);
      final preview=Map<String,int>.from(base);
      for(var i=0;i<moves.length;i++){
        if(!selected.contains(i))continue;
        final e=moves[i],p=e['person'] as String,d=e['date'] as DateTime,m=e['minutes'] as int;
        final old=key(p,d),next=key(e['toPerson'] as String,e['toDate'] as DateTime);
        preview[old]=(preview[old]??0)-m;preview[next]=(preview[next]??0)+m;
      }
      final beforeDaily=dailyExcess(base),beforeFair=fairnessExcess(base);
      final visible=<int>[];
      for(var i=0;i<moves.length;i++){
        final e=moves[i];
        if(onlySelected&&!selected.contains(i))continue;
        if(!'${e['title']} ${e['person']} ${e['toPerson']}'.toLowerCase().contains(query.toLowerCase()))continue;
        visible.add(i);
      }
      return SafeArea(child:FractionallySizedBox(heightFactor:.96,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Adalet riski / önleyici görev dengeleme',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Aynı koşullarda üç strateji, sorumlu bazında hedef doluluk ve günlük kapasite riskini karşılaştırır. Salt okunur önizleme; değişiklikleri kaydetmez.'),
        if(busy)const LinearProgressIndicator()else ...[
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<int>(value:weeks,items:[1,2,4,6,8,12].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>refresh((){weeks=v??4;selected.clear();})),
            DropdownButton<int>(value:tolerance,items:[0,5,10,15,20,30].map((v)=>DropdownMenuItem(value:v,child:Text('Tolerans $v puan'))).toList(),onChanged:(v)=>refresh((){tolerance=v??10;selected.clear();})),
            DropdownButton<int>(value:limit,items:[5,10,20,40].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v öneri'))).toList(),onChanged:(v)=>refresh((){limit=v??20;selected.clear();})),
            DropdownButton<int>(value:strategy,items:const [DropdownMenuItem(value:0,child:Text('Tarih')),DropdownMenuItem(value:1,child:Text('Sorumlu')),DropdownMenuItem(value:2,child:Text('Karma'))],onChanged:(v)=>refresh((){strategy=v??2;selected.clear();})),
          ]),
          Wrap(spacing:6,children:[TextButton(onPressed:()=>refresh((){offsetWeeks-=weeks;selected.clear();}),child:const Text('← Önceki')),TextButton(onPressed:()=>refresh((){offsetWeeks=0;selected.clear();}),child:const Text('Bugün')),TextButton(onPressed:()=>refresh((){offsetWeeks+=weeks;selected.clear();}),child:const Text('Sonraki →'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
          SwitchListTile(title:const Text('Hafta sonlarını analize dahil et'),value:weekends,onChanged:(v)=>refresh((){weekends=v;selected.clear();})),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Planlı görev: ${entries.length} • Korunan kritik/yüksek: $protectedCount',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('Günlük kapasite aşımı: $beforeDaily dk • Adalet hedef üstü yük: $beforeFair dk • Riskli gün: ${riskDays(base)}'),
            Text('Veri eksikleri: $missingDate tarihsiz, $missingOwner sorumlusuz, $missingDuration süresiz (30 dk varsayılır).'),
          ]))),
          Text('Aynı koşullarda strateji karşılaştırması',style:Theme.of(ctx).textTheme.titleMedium),
          ...List.generate(3,(i){final x=scenarios[i];return ListTile(dense:true,leading:Icon(i==strategy?Icons.radio_button_checked:Icons.radio_button_unchecked),title:Text(['Tarih odaklı','Sorumlu odaklı','Karma'][i]),subtitle:Text('Adalet hedef üstü: ${x['fair']} dk • Günlük aşım: ${x['daily']} dk • Riskli gün: ${x['risk']} • Öneri: ${(x['moves'] as List).length}'),onTap:()=>refresh((){strategy=i;selected.clear();}));}),
          const Divider(),
          Text('Seçilen öneriler: ${selected.length} / ${moves.length}',style:Theme.of(ctx).textTheme.titleMedium),
          Text('Seçim önizlemesi • adalet: $beforeFair → ${fairnessExcess(preview)} dk • günlük aşım: $beforeDaily → ${dailyExcess(preview)} dk • riskli gün: ${riskDays(base)} → ${riskDays(preview)}'),
          Wrap(spacing:8,children:[TextButton(onPressed:()=>refresh((){selected..clear()..addAll(List.generate(moves.length,(i)=>i));}),child:const Text('Tümünü seç')),TextButton(onPressed:()=>refresh(selected.clear),child:const Text('Seçimi temizle'))]),
          SwitchListTile(title:const Text('Yalnızca seçilenleri göster'),value:onlySelected,onChanged:(v)=>refresh(()=>onlySelected=v)),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev veya sorumlu ara'),onChanged:(v)=>refresh(()=>query=v)),
          if(visible.isEmpty)const ListTile(title:Text('Bu koşullarda görüntülenecek öneri bulunamadı.')),
          ...visible.take(60).map((i){final e=moves[i];return CheckboxListTile(value:selected.contains(i),onChanged:(v)=>refresh((){if(v==true){selected.add(i);}else{selected.remove(i);}}),title:Text(str(e['title'])),subtitle:Text('${e['person']} / ${iso(e['date'] as DateTime)} → ${e['toPerson']} / ${iso(e['toDate'] as DateTime)}\n${e['minutes']} dk • Puan: ${e['score']}'),controlAffinity:ListTileControlAffinity.leading);}),
          FilledButton.tonalIcon(onPressed:()async{
            final lines=<String>[["Görev","Önceki sorumlu","Önceki tarih","Önerilen sorumlu","Önerilen tarih","Dakika","Puan","Seçildi"].map(csv).join(';')];
            for(var i=0;i<moves.length;i++){final e=moves[i];lines.add([e['title'],e['person'],iso(e['date'] as DateTime),e['toPerson'],iso(e['toDate'] as DateTime),e['minutes'],e['score'],selected.contains(i)].map(csv).join(';'));}
            await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
            if(ctx.mounted)_notice('Önleyici adalet dengeleme CSV raporu kopyalandı.');
          },icon:const Icon(Icons.copy_outlined),label:const Text('Önerileri CSV kopyala')),
          const Text('Bu ekrandaki seçimler kaydedilmez. Onaylı optimizasyon ekranına geçildiğinde öneriler yeniden hesaplanır; burada seçilen öneriler otomatik aktarılmaz.',style:TextStyle(fontSize:12)),
          FilledButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenGoalDeviationRedistribution();},icon:const Icon(Icons.verified_outlined),label:const Text('Onaylı görev optimizasyonuna geç')),
        ],
      ])));
    }));
  }

  void _showKitchenFutureFairnessRisk() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const fairnessKey = 'paket42_fairness_utilization_targets_v1';
    final tasks = <Map<String,dynamic>>[];
    final capacities = <String,int>{};
    final targets = <String,int>{};
    var loaded = false, loading = true, onlyRisk = false, weekends = true;
    var weeks = 4, tolerance = 10, extraMinutes = 0, search = '';
    var offsetWeeks = 0;
    String str(Object? v) => '${v ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    DateTime? parse(Object? v) => DateTime.tryParse(str(v));
    DateTime monday(DateTime d) { final t=DateTime(d.year,d.month,d.day);return t.subtract(Duration(days:t.weekday-1)); }
    String owner(Map<String,dynamic> t) {final x=str(t['owner']).trim();return x.isEmpty?'Atanmamış':x;}
    int minutes(Map<String,dynamic> t) {final x=int.tryParse(str(t['estimatedMinutes']));return x!=null&&x>=5&&x<=1440?x:30;}
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    String csv(Object? x) => '"${str(x).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!loaded){
        loaded=true;
        SharedPreferences.getInstance().then((prefs){
          try{
            final raw=jsonDecode(prefs.getString(taskKey)??'[]');
            if(raw is List)tasks.addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
            for(final pair in <String,Map<String,int>>{capacityKey:capacities,fairnessKey:targets}.entries){
              final v=jsonDecode(prefs.getString(pair.key)??'{}');
              if(v is Map)for(final entry in v.entries){final n=int.tryParse(str(entry.value));if(n!=null&&n>=0)pair.value[str(entry.key)]=n;}
            }
          }catch(_){if(ctx.mounted)_notice('Kapasite risk verileri okunamadı.');}
          if(ctx.mounted)refresh(()=>loading=false);
        }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});
      }
      final start=monday(DateTime.now()).add(Duration(days:7*offsetWeeks));
      final end=start.add(Duration(days:7*weeks));
      final people=<String>{...capacities.keys,...targets.keys,...tasks.map(owner)}.where((p)=>p!='Atanmamış').toList()..sort();
      final daily=<String,int>{};
      final perWeek=<String,int>{};
      final taskCounts=<String,int>{};
      var missingDate=0,missingOwner=0,missingDuration=0,overdue=0;
      final today=DateTime.now();
      for(final t in tasks){
        if(!active(t))continue;
        final d=parse(t['targetDate']??t['due']);
        if(d==null){missingDate++;continue;}
        if(d.isBefore(DateTime(today.year,today.month,today.day)))overdue++;
        if(d.isBefore(start)||!d.isBefore(end))continue;
        final p=owner(t);
        if(p=='Atanmamış'){missingOwner++;continue;}
        if(int.tryParse(str(t['estimatedMinutes']))==null)missingDuration++;
        final m=minutes(t);
        final dk='$p|${iso(d)}';daily[dk]=(daily[dk]??0)+m;
        final w=monday(d);
        final wk='$p|${iso(w)}';perWeek[wk]=(perWeek[wk]??0)+m;
        taskCounts[wk]=(taskCounts[wk]??0)+1;
      }
      final details=<Map<String,dynamic>>[];
      final totals=<String,Map<String,int>>{};
      for(var i=0;i<weeks;i++){
        final w=start.add(Duration(days:7*i));
        for(final p in people){
          final cap=(capacities[p]??120)>0?(capacities[p]??120):120;
          final dailyCap=cap+extraMinutes;
          var available=0,over=0,riskDays=0;
          for(var j=0;j<7;j++){
            final d=w.add(Duration(days:j));
            if(!weekends&&d.weekday>=6)continue;
            available+=dailyCap;
            final used=daily['$p|${iso(d)}']??0;
            if(used>dailyCap){over+=used-dailyCap;riskDays++;}
          }
          final used=perWeek['$p|${iso(w)}']??0;
          final rate=available>0?used*100/available:0.0;
          final limit=(targets[p]??75)+tolerance;
          final gap=available>0?(used-available*limit/100).ceil():used;
          final targetGap=gap>0?gap:0;
          final item=<String,dynamic>{'week':w,'owner':p,'used':used,'capacity':available,'rate':rate,'target':targets[p]??75,'gap':targetGap,'over':over,'riskDays':riskDays,'tasks':taskCounts['$p|${iso(w)}']??0};
          details.add(item);
          final sum=totals.putIfAbsent(p,()=>{'used':0,'capacity':0,'gap':0,'over':0,'risk':0,'tasks':0});
          for(final k in ['used','capacity','gap','over','tasks']) {sum[k]=sum[k]!+(item[k] as int); }
          sum['risk']=sum['risk']!+riskDays;
        }
      }
      final shown=details.where((e)=>(search.isEmpty||str(e['owner']).toLowerCase().contains(search.toLowerCase()))&&(!onlyRisk||(e['gap'] as int)>0||(e['riskDays'] as int)>0)).toList()
        ..sort((a,b){final c=(b['gap'] as int).compareTo(a['gap'] as int);return c!=0?c:(a['week'] as DateTime).compareTo(b['week'] as DateTime);});
      final totalGap=details.fold<int>(0,(v,e)=>v+(e['gap'] as int));
      final totalOver=details.fold<int>(0,(v,e)=>v+(e['over'] as int));
      final riskWeeks=details.where((e)=>(e['gap'] as int)>0).length;
      final owners=totals.entries.toList()..sort((a,b)=>(b.value['gap']??0).compareTo(a.value['gap']??0));
      final lines=<String>['Hafta;Sorumlu;Görev dakika;Kapasite dakika;Doluluk yüzde;Hedef yüzde;Tolerans;Hedef üstü dakika;Günlük aşım dakika;Riskli gün;Görev sayısı'];
      for(final e in shown){lines.add([iso(e['week'] as DateTime),e['owner'],e['used'],e['capacity'],(e['rate'] as double).toStringAsFixed(1),e['target'],tolerance,e['gap'],e['over'],e['riskDays'],e['tasks']].map(csv).join(';'));}
      Widget stat(String name,String value)=>Chip(label:Text('$name: $value'));
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Haftalık iş yükü ve adalet risklerini önleme',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        if(loading)const LinearProgressIndicator()else ...[
          const Card(color:_pink,child:Padding(padding:EdgeInsets.all(12),child:Text('Bu ekran yalnızca geleceğe planlanmış mevcut görevleri analiz eder. Yeni görevleri, gerçek müsaitliği veya gelecekteki iş yükünü tahmin etmez. + kapasite seçeneği simülasyondur; kayıtları değiştirmez.'))),
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<int>(value:weeks,items:[1,2,4,6,8,12].map((v)=>DropdownMenuItem(value:v,child:Text('$v hafta'))).toList(),onChanged:(v)=>refresh(()=>weeks=v??4)),
            DropdownButton<int>(value:tolerance,items:[0,5,10,15,20,30].map((v)=>DropdownMenuItem(value:v,child:Text('Tolerans $v puan'))).toList(),onChanged:(v)=>refresh(()=>tolerance=v??10)),
            DropdownButton<int>(value:extraMinutes,items:[0,15,30,45,60].map((v)=>DropdownMenuItem(value:v,child:Text('Ek kapasite +$v dk'))).toList(),onChanged:(v)=>refresh(()=>extraMinutes=v??0)),
          ]),
          Row(children:[IconButton(onPressed:()=>refresh(()=>offsetWeeks-=weeks),icon:const Icon(Icons.chevron_left)),Expanded(child:Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}',textAlign:TextAlign.center)),IconButton(onPressed:()=>refresh(()=>offsetWeeks+=weeks),icon:const Icon(Icons.chevron_right)),TextButton(onPressed:()=>refresh(()=>offsetWeeks=0),child:const Text('Bu hafta'))]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sorumlu ara'),onChanged:(v)=>refresh(()=>search=v.trim())),
          SwitchListTile(title:const Text('Hafta sonlarını kapasiteye dahil et'),value:weekends,onChanged:(v)=>refresh(()=>weekends=v)),
          SwitchListTile(title:const Text('Yalnızca riskli sorumlu-haftalar'),value:onlyRisk,onChanged:(v)=>refresh(()=>onlyRisk=v)),
          Wrap(spacing:6,runSpacing:4,children:[stat('Hedef üstü', '$totalGap dk'),stat('Günlük aşım','$totalOver dk'),stat('Riskli sorumlu-hafta','$riskWeeks'),stat('Sorumlu','${people.length}')]),
          Text('Sorumlu bazında gelecek dönem',style:Theme.of(ctx).textTheme.titleMedium),
          if(owners.isEmpty)const ListTile(title:Text('Kayıtlı sorumlu bulunamadı.')),
          for(final e in owners)Card(child:ListTile(title:Text(e.key),subtitle:Text('${e.value['used']} dk iş / ${e.value['capacity']} dk kapasite • ${e.value['risk']} riskli gün'),trailing:Text('${e.value['gap']} dk hedef üstü'))),
          const Divider(),Text('Haftalık risk ayrıntıları',style:Theme.of(ctx).textTheme.titleMedium),
          if(shown.isEmpty)const ListTile(title:Text('Filtreye uygun kayıt bulunamadı.')),
          for(final e in shown.take(100))Card(child:ListTile(leading:Icon((e['gap'] as int)>0?Icons.warning_amber_outlined:Icons.check_circle_outline,color:_purple),title:Text('${e['owner']} • ${iso(e['week'] as DateTime)}'),subtitle:Text('${e['tasks']} görev • ${e['used']}/${e['capacity']} dk • %${(e['rate'] as double).toStringAsFixed(1)} doluluk\nHedef %${e['target']} + $tolerance puan tolerans • ${e['riskDays']} riskli gün'),trailing:Text('${e['gap']} dk'))),
          const Divider(),Text('Veri kalitesi ve önleyici öneriler',style:Theme.of(ctx).textTheme.titleMedium),
          ListTile(title:Text('Eksik tarih: $missingDate • Atanmamış: $missingOwner • Eksik süre: $missingDuration'),subtitle:Text('Bugünden önce hedef tarihi olan açık görev: $overdue. Eksik süreler analizde 30 dakika kabul edilir.')),
          if(totalGap>0)const ListTile(leading:Icon(Icons.tips_and_updates_outlined),title:Text('Hedef üstü haftaları önceliklendirin'),subtitle:Text('Önce kritik görevleri koruyun; esnek görevler için alternatif gün veya uygun sorumlu değerlendirin.')),
          if(totalOver>0)const ListTile(leading:Icon(Icons.event_busy_outlined),title:Text('Günlük aşım görüldü'),subtitle:Text('Haftalık toplam normal görünse bile belirli günlerde aşırı yük olabilir. Günlük planlama ekranını kontrol edin.')),
          if(totalGap==0&&totalOver==0)const ListTile(leading:Icon(Icons.check_circle_outline),title:Text('Seçili varsayımlarla belirgin kapasite riski bulunamadı.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));if(ctx.mounted)_notice('Gelecek hafta adalet riski CSV raporu kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('CSV raporunu kopyala')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenFairnessGoalsDecision();},child:const Text('Adalet hedeflerini düzenle')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveStrategyDecision();},child:const Text('Önleyici optimizasyon senaryolarına geç')),
        ]
      ])));
    }));
  }

  void _showKitchenFairnessWeeklyTrends() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const fairnessKey = 'paket42_fairness_utilization_targets_v1';
    const versionKey = 'paket40_optimization_plan_versions_v1';
    final tasks = <Map<String, dynamic>>[];
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final targets = <String, int>{};
    var started = false, loading = true, onlyGaps = false, onlyImproved = false;
    var weeks = 8, tolerance = 15, search = '';
    var anchor = DateTime.now();
    String str(Object? x) => '${x ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime monday(DateTime d) { final t = DateTime(d.year,d.month,d.day); return t.subtract(Duration(days:t.weekday-1)); }
    String owner(Map<String,dynamic> t) { final x = str(t['owner']).trim(); return x.isEmpty ? 'Atanmamış' : x; }
    int duration(Map<String,dynamic> t) { final x = int.tryParse(str(t['estimatedMinutes'])); return x != null && x >= 5 && x <= 1440 ? x : 30; }
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    List<Map<String,dynamic>> rows(Object? x) => x is List ? x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList() : <Map<String,dynamic>>[];
    String csv(Object? x) => '"${str(x).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs){
          try {
            tasks.addAll(rows(jsonDecode(prefs.getString(taskKey) ?? '[]')));
            versions.addAll(rows(jsonDecode(prefs.getString(versionKey) ?? '[]')));
            for (final entry in <String,Map<String,int>>{capacityKey:capacities,fairnessKey:targets}.entries) {
              final raw = jsonDecode(prefs.getString(entry.key) ?? '{}');
              if (raw is Map) { for (final pair in raw.entries) {
                final n = int.tryParse(str(pair.value));
                if (n != null && n >= 0) entry.value[str(pair.key)] = n;
              } }
            }
          } catch (_) { if (ctx.mounted) _notice('Haftalık adalet verileri okunamadı.'); }
          if (ctx.mounted) refresh(()=>loading=false);
        }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});
      }
      final end = monday(anchor).add(const Duration(days:7));
      final start = end.subtract(Duration(days:weeks*7));
      final people = <String>{...capacities.keys,...targets.keys,...tasks.map(owner)}.where((p)=>p!='Atanmamış').toList()..sort();
      final selectedPeople = people.where((p)=>search.isEmpty || p.toLowerCase().contains(search.toLowerCase())).toList();
      Map<String,dynamic> measure(List<Map<String,dynamic>> plan, DateTime from, DateTime until, Map<String,int> caps) {
        final totals = <String,int>{};
        final daily = <String,int>{};
        for(final t in plan){
          if(!active(t))continue;
          final d=parse(t['targetDate']??t['due']);
          if(d==null || d.isBefore(from) || !d.isBefore(until))continue;
          final p=owner(t);if(p=='Atanmamış')continue;
          final m=duration(t);
          totals[p]=(totals[p]??0)+m;
          final k='$p|${iso(d)}';daily[k]=(daily[k]??0)+m;
        }
        final rates=<String,double>{};
        final gaps=<String,int>{};
        var risk=0,over=0;
        final dayCount=until.difference(from).inDays;
        for(final p in <String>{...people,...totals.keys}){
          final c=(caps[p]??120)>0?(caps[p]??120):120;
          final rate=dayCount>0?100*(totals[p]??0)/(c*dayCount):0.0;
          rates[p]=rate;
          final limit=(targets[p]??75)+tolerance;
          final excess=(totals[p]??0)-((c*dayCount*limit)/100).round();
          gaps[p]=excess>0?excess:0;
        }
        for(final e in daily.entries){
          final p=e.key.split('|').first;
          final c=(caps[p]??120)>0?(caps[p]??120):120;
          if(e.value>c){risk++;over+=e.value-c;}
        }
        return {'totals':totals,'rates':rates,'gaps':gaps,'risk':risk,'over':over,'gap':gaps.values.fold<int>(0,(a,b)=>a+b)};
      }
      final weeksData=<Map<String,dynamic>>[];
      for(var i=0;i<weeks;i++){
        final from=start.add(Duration(days:i*7));
        final until=from.add(const Duration(days:7));
        weeksData.add({'start':from,'metrics':measure(tasks,from,until,capacities)});
      }
      final current = measure(tasks,start,end,capacities);
      final currentGaps=current['gaps'] as Map<String,int>;
      final currentRates=current['rates'] as Map<String,double>;
      final currentTotals=current['totals'] as Map<String,int>;
      final versionResults=<Map<String,dynamic>>[];
      var oldRecords=0, invalidRecords=0;
      for(final v in versions){
        final at=parse(v['at']);
        if(at==null || at.isBefore(start) || !at.isBefore(end))continue;
        if(v['fullPlanBefore'] is! List || v['fullPlanAfter'] is! List || v['capacitySnapshot'] is! Map){oldRecords++;continue;}
        final before=rows(v['fullPlanBefore']),after=rows(v['fullPlanAfter']);
        if(before.isEmpty || after.isEmpty){invalidRecords++;continue;}
        final caps=<String,int>{};
        for(final e in (v['capacitySnapshot'] as Map).entries){final n=int.tryParse(str(e.value));if(n!=null&&n>0)caps[str(e.key)]=n;}
        // Karşılaştırma işlem haftasıyla sınırlıdır; hedefler güncel ayarlardan alınır.
        final w=monday(at);
        final b=measure(before,w,w.add(const Duration(days:7)),caps);
        final a=measure(after,w,w.add(const Duration(days:7)),caps);
        final gain=(b['gap'] as int)-(a['gap'] as int);
        versionResults.add({'at':at,'name':str(v['name']),'gain':gain,'before':b,'after':a});
      }
      final filteredVersions=versionResults.where((v)=>!onlyImproved || (v['gain'] as int)>0).toList()
        ..sort((a,b)=>(b['at'] as DateTime).compareTo(a['at'] as DateTime));
      final rank=selectedPeople.toList()..sort((a,b)=>(currentGaps[b]??0).compareTo(currentGaps[a]??0));
      final report=<String>['Tür;Hafta / Tarih;Sorumlu;Görev dakikası;Doluluk %;Hedef %;Tolerans puan;Hedef üstü dakika;İşlem kazancı'];
      for(final w in weeksData){final m=w['metrics'] as Map<String,dynamic>;
        for(final p in selectedPeople){final t=m['totals'] as Map<String,int>,r=m['rates'] as Map<String,double>,g=m['gaps'] as Map<String,int>;
          report.add(['Haftalık',iso(w['start'] as DateTime),p,t[p]??0,(r[p]??0).toStringAsFixed(1),targets[p]??75,tolerance,g[p]??0,''].map(csv).join(';'));
        }
      }
      for(final v in filteredVersions){ report.add(['Sürüm',iso(v['at'] as DateTime),v['name'],'','','','','',v['gain']].map(csv).join(';')); }
      final improving=versionResults.where((v)=>(v['gain'] as int)>0).length;
      final worsening=versionResults.where((v)=>(v['gain'] as int)<0).length;
      final sumGain=versionResults.fold<int>(0,(a,v)=>a+(v['gain'] as int));
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Haftalık adalet hedefleri ve denge takibi',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        if(loading)const LinearProgressIndicator()else ...[
          const Card(color:_pink,child:Padding(padding:EdgeInsets.all(12),child:Text('Haftalık iş yükü, güncel görev planının hedef tarihlerine göre hesaplanır. Geçmişte gerçekten gerçekleşen iş yükü değildir. Eski optimizasyon kayıtlarında adalet hedefi saklanmadığından geçmiş sürümler güncel hedeflerle yeniden değerlendirilir.'))),
          Wrap(spacing:8,runSpacing:6,children:[
            DropdownButton<int>(value:weeks,items:[4,8,12,26,52].map((n)=>DropdownMenuItem(value:n,child:Text('$n hafta'))).toList(),onChanged:(v)=>refresh(()=>weeks=v??8)),
            DropdownButton<int>(value:tolerance,items:[0,5,10,15,20,30].map((n)=>DropdownMenuItem(value:n,child:Text('Tolerans $n puan'))).toList(),onChanged:(v)=>refresh(()=>tolerance=v??15)),
            FilterChip(label:const Text('Hedefi aşan sorumlular'),selected:onlyGaps,onSelected:(v)=>refresh(()=>onlyGaps=v)),
            FilterChip(label:const Text('Yalnızca iyileşen sürümler'),selected:onlyImproved,onSelected:(v)=>refresh(()=>onlyImproved=v)),
          ]),
          Row(children:[IconButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:weeks*7))),icon:const Icon(Icons.chevron_left)),Expanded(child:Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}',textAlign:TextAlign.center)),IconButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:weeks*7))),icon:const Icon(Icons.chevron_right)),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün'))]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Sorumlu ara'),onChanged:(v)=>refresh(()=>search=v.trim())),
          Card(child:ListTile(title:Text('${current['gap']} dk hedef üstü iş yükü · ${current['over']} dk günlük kapasite aşımı'),subtitle:Text('${current['risk']} riskli sorumlu-gün · ${versionResults.length} karşılaştırılabilir sürüm · $improving iyileşen / $worsening kötüleşen · işlem bazında net $sumGain dk'))),
          Text('Sorumlu bazında hedef durumu',style:Theme.of(ctx).textTheme.titleMedium),
          if(rank.isEmpty)const ListTile(title:Text('Bu dönemde sorumlu kaydı bulunamadı.')),
          for(final p in rank.where((p)=>!onlyGaps || (currentGaps[p]??0)>0))Card(child:ListTile(
            leading:Icon((currentGaps[p]??0)>0?Icons.warning_amber_outlined:Icons.check_circle_outline,color:_purple),
            title:Text(p),subtitle:Text('${currentTotals[p]??0} dk · Doluluk %${(currentRates[p]??0).toStringAsFixed(1)} · Hedef %${targets[p]??75} ±$tolerance puan'),
            trailing:Text('${currentGaps[p]??0} dk',style:const TextStyle(fontWeight:FontWeight.bold)))),
          const Divider(),Text('Haftalık plan görünümü',style:Theme.of(ctx).textTheme.titleMedium),
          for(final w in weeksData.reversed)Builder(builder:(_){final m=w['metrics'] as Map<String,dynamic>;final gaps=m['gaps'] as Map<String,int>;final rates=m['rates'] as Map<String,double>;
            return ExpansionTile(title:Text('${iso(w['start'] as DateTime)} · ${m['gap']} dk hedef üstü'),subtitle:Text('${m['risk']} riskli gün · ${m['over']} dk kapasite aşımı'),children:[
              for(final p in selectedPeople.where((p)=>!onlyGaps || (gaps[p]??0)>0))ListTile(dense:true,title:Text(p),subtitle:Text('Doluluk %${(rates[p]??0).toStringAsFixed(1)} · Hedef %${targets[p]??75}'),trailing:Text('${gaps[p]??0} dk')),
            ]);
          }),
          const Divider(),Text('Tam plan optimizasyon geçmişi',style:Theme.of(ctx).textTheme.titleMedium),
          Text('Karşılaştırılabilir ${versionResults.length} · Eski/kısmi $oldRecords · Geçersiz $invalidRecords'),
          if(filteredVersions.isEmpty)const ListTile(title:Text('Seçili dönemde uygun tam plan kaydı bulunamadı.')),
          for(final v in filteredVersions.take(40))ListTile(dense:true,title:Text(str(v['name'])),subtitle:Text(iso(v['at'] as DateTime)),trailing:Text('${(v['gain'] as int)>=0?'+':''}${v['gain']} dk')),
          const Card(color:_pink,child:Padding(padding:EdgeInsets.all(12),child:Text('Öneri: Hedef üstü yükü yüksek sorumluların görev tarihlerini ve tahmini sürelerini gözden geçirin. Sürüm kazanımları aynı görevleri tekrar içerebilir; bağımsız zaman tasarrufu olarak toplanmamalıdır.'))),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(ctx.mounted)_notice('Haftalık adalet raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy_outlined),label:const Text('Haftalık CSV raporunu kopyala')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenFairnessGoalsDecision();},child:const Text('Adalet hedeflerini düzenle')),
          OutlinedButton(onPressed:(){Navigator.pop(ctx);_showKitchenFullPlanOptimizationAudit();},child:const Text('Tam plan geçmişine geç')),
        ]
      ])));
    }));
  }

  void _showKitchenFairnessGoalsDecision() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalsKey = 'paket41_owner_capacity_decision_goals_v1';
    const fairnessKey = 'paket42_fairness_utilization_targets_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacity = <String, int>{};
    final excessGoals = <String, int>{};
    final targets = <String, int>{};
    var started = false, loading = true, weekends = true, onlyGaps = false;
    var horizon = 14, tolerance = 15, maxMoves = 15, selectedStrategy = 2;
    var search = '';
    var anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    DateTime? date(Object? v) { final d = DateTime.tryParse(str(v)); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String owner(Map<String, dynamic> t) { final p = str(t['owner']).trim(); return p.isEmpty ? 'Atanmamış' : p; }
    int minutes(Map<String, dynamic> t) { final n = int.tryParse(str(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(str(t['status']));
    bool protected(Map<String, dynamic> t) { final p = str(t['priority'] ?? t['level']).toLowerCase(); return ['kritik','yüksek','critical','high'].any(p.contains); }
    bool allowed(DateTime d) => weekends || (d.weekday != DateTime.saturday && d.weekday != DateTime.sunday);
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, update) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (raw is List) tasks.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
            for (final pair in <String, Map<String, int>>{capacityKey: capacity, goalsKey: excessGoals, fairnessKey: targets}.entries) {
              final rawMap = jsonDecode(prefs.getString(pair.key) ?? '{}');
              if (rawMap is Map) { for (final entry in rawMap.entries) {
                final n = int.tryParse(str(entry.value));
                if (n != null && n >= 0) pair.value[str(entry.key)] = n;
              } }
            }
          } catch (_) { if (ctx.mounted) _notice('Kapasite hedefleri okunurken sorun oluştu.'); }
          if (ctx.mounted) update(() => loading = false);
        }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
      }
      final start = DateTime(anchor.year, anchor.month, anchor.day);
      final end = start.add(Duration(days: horizon));
      final days = <DateTime>[for (var i = 0; i < horizon; i++) if (allowed(start.add(Duration(days: i)))) start.add(Duration(days: i))];
      final people = <String>{...capacity.keys, ...excessGoals.keys, ...targets.keys, ...tasks.map(owner)}.where((p) => p != 'Atanmamış').toList()..sort();
      String key(String p, DateTime d) => '$p|${iso(d)}';
      int cap(String p) => (capacity[p] ?? 120) > 0 ? (capacity[p] ?? 120) : 120;
      int allowance(String p) => cap(p) + (excessGoals[p] ?? 0);
      final entries = <Map<String, dynamic>>[];
      final initial = <String, int>{};
      var missingOwner = 0, missingDate = 0, missingMinutes = 0, locked = 0;
      for (final task in tasks) {
        if (!active(task)) continue;
        final p = owner(task), d = date(task['targetDate'] ?? task['due']);
        if (p == 'Atanmamış') missingOwner++;
        if (d == null) missingDate++;
        if (int.tryParse(str(task['estimatedMinutes'])) == null) missingMinutes++;
        if (d == null || d.isBefore(start) || !d.isBefore(end) || !allowed(d)) continue;
        if (protected(task)) locked++;
        final m = minutes(task);
        entries.add({'task': task, 'owner': p, 'day': d, 'minutes': m});
        initial[key(p,d)] = (initial[key(p,d)] ?? 0) + m;
      }
      Map<String, dynamic> measure(Map<String, int> loads) {
        final totals = <String, int>{};
        final rates = <String, double>{};
        var overload = 0, riskDays = 0, targetGap = 0;
        for (final p in people) {
          var total = 0;
          for (final d in days) {
            final m = loads[key(p,d)] ?? 0;
            total += m;
            final excess = m - allowance(p);
            if (excess > 0) { overload += excess; riskDays++; }
          }
          totals[p] = total;
          final available = days.length * cap(p);
          final rate = available > 0 ? total * 100 / available : 0.0;
          rates[p] = rate;
          final upper = (targets[p] ?? 80) + tolerance;
          if (rate > upper) targetGap += ((rate - upper) * available / 100).round();
        }
        final values = rates.values.toList();
        final spread = values.isEmpty ? 0.0 : values.reduce((a,b) => a > b ? a : b) - values.reduce((a,b) => a < b ? a : b);
        return {'totals': totals, 'rates': rates, 'overload': overload, 'risk': riskDays, 'gap': targetGap, 'spread': spread};
      }
      final before = measure(initial);
      final candidates = entries.where((e) => e['owner'] != 'Atanmamış' && !protected(e['task'] as Map<String, dynamic>)).toList()
        ..sort((a,b) => (b['minutes'] as int).compareTo(a['minutes'] as int));
      Map<String, dynamic> simulate(int mode) {
        final loads = Map<String, int>.from(initial);
        final moves = <Map<String, dynamic>>[];
        for (final e in candidates) {
          if (moves.length >= maxMoves) break;
          final oldP = e['owner'] as String, oldD = e['day'] as DateTime, m = e['minutes'] as int;
          final source = key(oldP, oldD), oldLoad = loads[source] ?? 0;
          if (oldLoad <= allowance(oldP)) continue;
          final baseline = measure(loads);
          String? bestP; DateTime? bestD; var bestScore = 0.0;
          for (final p in people) {
            if (mode == 0 && p != oldP) continue;
            if (mode == 1 && p == oldP) continue;
            for (final d in days) {
              if (d.isBefore(oldD)) continue;
              if (mode == 1 && iso(d) != iso(oldD)) continue;
              if (mode == 0 && iso(d) == iso(oldD)) continue;
              if (p == oldP && iso(d) == iso(oldD)) continue;
              final dest = key(p,d);
              final trial = Map<String, int>.from(loads);
              trial[source] = oldLoad - m;
              trial[dest] = (trial[dest] ?? 0) + m;
              final result = measure(trial);
              final reduction = (baseline['overload'] as int) - (result['overload'] as int);
              final gapGain = (baseline['gap'] as int) - (result['gap'] as int);
              final spreadGain = (baseline['spread'] as double) - (result['spread'] as double);
              final delay = d.difference(oldD).inDays;
              final score = reduction * 2.0 + gapGain * (mode == 2 ? 1.0 : 0.5) + spreadGain * 0.2 - delay * 2 - (p == oldP ? 0 : 5);
              if (reduction < 0 || gapGain < -m || score <= bestScore) continue;
              bestScore = score; bestP = p; bestD = d;
            }
          }
          if (bestP == null || bestD == null) continue;
          loads[source] = oldLoad - m;
          final destination = key(bestP,bestD);
          loads[destination] = (loads[destination] ?? 0) + m;
          moves.add({'title': str((e['task'] as Map<String,dynamic>)['title']), 'oldOwner': oldP, 'newOwner': bestP,
            'oldDate': iso(oldD), 'newDate': iso(bestD), 'minutes': m, 'score': bestScore});
        }
        return {'loads': loads, 'moves': moves, 'metrics': measure(loads)};
      }
      final scenarios = [simulate(0), simulate(1), simulate(2)];
      final chosen = scenarios[selectedStrategy];
      final after = chosen['metrics'] as Map<String,dynamic>;
      final moves = chosen['moves'] as List<Map<String,dynamic>>;
      final beforeRates = before['rates'] as Map<String,double>;
      final afterRates = after['rates'] as Map<String,double>;
      final filtered = people.where((p) => (search.isEmpty || p.toLowerCase().contains(search.toLowerCase())) &&
        (!onlyGaps || (afterRates[p] ?? 0) > (targets[p] ?? 80) + tolerance)).toList();
      Widget selector(String label, int current, List<int> options, void Function(int) set) => DropdownButtonFormField<int>(
        initialValue: current, isExpanded: true, decoration: InputDecoration(labelText: label),
        items: options.map((n) => DropdownMenuItem(value: n, child: Text('$n'))).toList(),
        onChanged: (v) { if (v != null) update(() => set(v)); });
      final report = <String>['Sorumlu,Hedef %,Mevcut doluluk %,Önerilen doluluk %,Günlük kapasite dk'];
      for (final p in people) {
        report.add([csv(p), '${targets[p] ?? 80}', (beforeRates[p] ?? 0).toStringAsFixed(1),
        (afterRates[p] ?? 0).toStringAsFixed(1), '${cap(p)}'].join(','));
      }
      report.add('Görev,Eski sorumlu,Yeni sorumlu,Eski tarih,Yeni tarih,Dakika');
      for (final m in moves) { report.add([csv(m['title']), csv(m['oldOwner']), csv(m['newOwner']), csv(m['oldDate']), csv(m['newDate']), '${m['minutes']}'].join(',')); }
      return SafeArea(child: FractionallySizedBox(heightFactor: .95, child: Column(children: [
        ListTile(title: const Text('İş yükü adalet hedefleri ve dengeleme kararları', style: TextStyle(fontWeight: FontWeight.bold)),
          subtitle: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))} · Önizleme'),
          trailing: IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))),
        if (loading) const LinearProgressIndicator(),
        Expanded(child: ListView(padding: const EdgeInsets.all(12), children: [
          const Text('Kişi bazında hedef doluluk oranlarını kaydet. Senaryolar aynı görev ve kapasite koşullarında karşılaştırılır.'),
          Wrap(spacing: 8, children: [ActionChip(label: const Text('← Önceki'), onPressed: () => update(() => anchor = anchor.subtract(Duration(days: horizon)))),
            ActionChip(label: const Text('Bugün'), onPressed: () => update(() => anchor = DateTime.now())),
            ActionChip(label: const Text('Sonraki →'), onPressed: () => update(() => anchor = anchor.add(Duration(days: horizon))))]),
          Row(children: [Expanded(child: selector('Analiz günü', horizon, [7,14,21,28,42,56], (v) => horizon = v)),
            const SizedBox(width: 8), Expanded(child: selector('Hedef toleransı (puan)', tolerance, [0,5,10,15,20,30], (v) => tolerance = v))]),
          Row(children: [Expanded(child: selector('Azami öneri', maxMoves, [5,10,15,30,50], (v) => maxMoves = v)),
            Expanded(child: SwitchListTile(title: const Text('Hafta sonu'), value: weekends, onChanged: (v) => update(() => weekends = v)))]),
          const SizedBox(height: 8),
          const Text('Stratejiler (aynı koşullarda)', style: TextStyle(fontWeight: FontWeight.bold)),
          for (var i = 0; i < scenarios.length; i++) RadioGroup<int>(groupValue: selectedStrategy, onChanged: (v) { if (v != null) update(() => selectedStrategy = v); }, child: RadioListTile<int>(value: i,
            title: Text(['Tarih odaklı','Sorumlu odaklı','Karma'][i]),
            subtitle: Text('Hedef üstü yük: ${(scenarios[i]['metrics'] as Map<String,dynamic>)['overload']} dk · '
              'Adalet hedefi sapması: ${(scenarios[i]['metrics'] as Map<String,dynamic>)['gap']} dk · '
              'Öneri: ${(scenarios[i]['moves'] as List).length}'),
            )),
          Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Kapasite hedefi aşımı: ${before['overload']} → ${after['overload']} dk'),
            Text('Adalet hedefi üstü yük: ${before['gap']} → ${after['gap']} dk'),
            Text('Riskli sorumlu-gün: ${before['risk']} → ${after['risk']}'),
            Text('Doluluk aralığı: ${(before['spread'] as double).toStringAsFixed(1)} → ${(after['spread'] as double).toStringAsFixed(1)} yüzde puan'),
          ]))),
          const Divider(),
          const Text('Kişisel hedefler (kalıcı kayıt)', style: TextStyle(fontWeight: FontWeight.bold)),
          TextField(decoration: const InputDecoration(labelText: 'Sorumlu ara', prefixIcon: Icon(Icons.search)),
            onChanged: (v) => update(() => search = v)),
          SwitchListTile(title: const Text('Yalnızca hedefi aşanlar'), value: onlyGaps, onChanged: (v) => update(() => onlyGaps = v)),
          if (people.isEmpty) const ListTile(title: Text('Atanmış sorumlu bulunamadı.')),
          for (final p in filtered) Card(child: Column(children: [
            ListTile(title: Text(p), subtitle: Text('Doluluk: %${(beforeRates[p] ?? 0).toStringAsFixed(1)} → '
              '%${(afterRates[p] ?? 0).toStringAsFixed(1)} · Günlük kapasite: ${cap(p)} dk')),
            Padding(padding: const EdgeInsets.symmetric(horizontal: 16), child: selector('Hedef doluluk %',
              [50,60,70,75,80,85,90,95,100].contains(targets[p] ?? 80) ? (targets[p] ?? 80) : 80,
              [50,60,70,75,80,85,90,95,100], (v) async {
                targets[p] = v;
                final prefs = await SharedPreferences.getInstance();
                await prefs.setString(fairnessKey, jsonEncode(targets));
                if (ctx.mounted) _notice('$p için hedef %$v kaydedildi.');
              })),
          ])),
          const Divider(),
          Text('Önerilen görev hareketleri (${moves.length})', style: const TextStyle(fontWeight: FontWeight.bold)),
          if (moves.isEmpty) const ListTile(title: Text('Bu koşullarda olumlu puan alan görev değişikliği bulunamadı.')),
          for (final m in moves.where((m) => search.isEmpty || str(m['title']).toLowerCase().contains(search.toLowerCase()) ||
            str(m['oldOwner']).toLowerCase().contains(search.toLowerCase()) || str(m['newOwner']).toLowerCase().contains(search.toLowerCase())))
            ListTile(title: Text(str(m['title'])), subtitle: Text('${m['oldOwner']} (${m['oldDate']}) → '
              '${m['newOwner']} (${m['newDate']}) · ${m['minutes']} dk · Puan: ${(m['score'] as double).toStringAsFixed(1)}')),
          Text('Veri kalitesi: Atanmamış $missingOwner · Tarihsiz $missingDate · Süresi eksik $missingMinutes · Korunan öncelikli $locked'),
          const Text('Hedef aşımı günlük; adalet hedefi sapması dönemlik doluluk üzerinden ölçülür. '
            'Eksik görev süresi 30 dk, eksik günlük kapasite 120 dk varsayılır. '
            'Öneriler kaydedilmez; onaylı uygulama ekranında yeniden hesaplanır.'),
          const SizedBox(height: 12),
          FilledButton.tonalIcon(onPressed: () async { await Clipboard.setData(ClipboardData(text: report.join('\n')));
            if (ctx.mounted) _notice('Adalet hedefleri ve öneriler CSV olarak kopyalandı.'); },
            icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
          FilledButton.tonalIcon(onPressed: () { Navigator.pop(ctx); _showKitchenGoalDeviationRedistribution(); },
            icon: const Icon(Icons.verified_outlined), label: const Text('Onaylı görev dağılımı ekranına geç')),
        ])),
      ])));
    }));
  }

  void _showKitchenWorkloadFairnessCenter() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    bool started = false, loading = true, onlyRisk = false, weekends = true;
    int horizon = 14, bonus = 0, maxMoves = 15, strategy = 2;
    String search = '';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    DateTime? day(Object? v) {
      final d = DateTime.tryParse(str(v));
      return d == null ? null : DateTime(d.year, d.month, d.day);
    }
    String owner(Map<String, dynamic> t) {
      final value = str(t['owner']).trim();
      return value.isEmpty ? 'Atanmamış' : value;
    }
    int minutes(Map<String, dynamic> t) {
      final value = int.tryParse(str(t['estimatedMinutes']));
      return value != null && value >= 5 && value <= 1440 ? value : 30;
    }
    bool active(Map<String, dynamic> t) => !['Tamamlandı', 'İptal'].contains(str(t['status']));
    bool protected(Map<String, dynamic> t) {
      final p = str(t['priority'] ?? t['level']).toLowerCase();
      return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high');
    }
    bool allowedDay(DateTime d) => weekends || (d.weekday != DateTime.saturday && d.weekday != DateTime.sunday);
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, update) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(taskKey) ?? '[]');
              if (raw is List) tasks.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
              final cap = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (cap is Map) { for (final e in cap.entries) {
                final n = int.tryParse(str(e.value));
                if (n != null && n > 0) capacities[str(e.key)] = n;
              } }
              final savedGoals = jsonDecode(prefs.getString(goalKey) ?? '{}');
              if (savedGoals is Map) { for (final e in savedGoals.entries) {
                final n = int.tryParse(str(e.value));
                if (n != null && n >= 0) goals[str(e.key)] = n;
              } }
            } catch (_) {
              if (ctx.mounted) _notice('Adalet analizi verileri okunamadı.');
            }
            if (ctx.mounted) update(() => loading = false);
          }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
        }
        final start = DateTime(anchor.year, anchor.month, anchor.day);
        final end = start.add(Duration(days: horizon));
        final people = <String>{...tasks.map(owner), ...capacities.keys, ...goals.keys}
            .where((p) => p != 'Atanmamış').toList()..sort();
        final entries = <Map<String, dynamic>>[];
        final base = <String, int>{};
        int noOwner = 0, noDate = 0, noDuration = 0, protectedCount = 0;
        String key(String p, DateTime d) => '$p|${iso(d)}';
        int allowance(String p) => (capacities[p] ?? 120) + bonus + (goals[p] ?? 0);
        for (final t in tasks) {
          if (!active(t)) continue;
          final p = owner(t), d = day(t['targetDate'] ?? t['due']);
          if (p == 'Atanmamış') noOwner++;
          if (d == null) noDate++;
          if (int.tryParse(str(t['estimatedMinutes'])) == null) noDuration++;
          if (d == null || d.isBefore(start) || !d.isBefore(end) || !allowedDay(d)) continue;
          final m = minutes(t);
          entries.add({'task': t, 'owner': p, 'date': d, 'minutes': m});
          base[key(p, d)] = (base[key(p, d)] ?? 0) + m;
          if (protected(t)) protectedCount++;
        }
        final days = <DateTime>[];
        for (var i = 0; i < horizon; i++) {
          final d = start.add(Duration(days: i));
          if (allowedDay(d)) days.add(d);
        }
        Map<String, dynamic> metrics(Map<String, int> loads) {
          final totals = <String, int>{};
          final utilization = <String, double>{};
          var overload = 0, risky = 0;
          for (final p in people) {
            var total = 0;
            for (final d in days) {
              final m = loads[key(p, d)] ?? 0;
              total += m;
              final excess = m - allowance(p);
              if (excess > 0) { overload += excess; risky++; }
            }
            totals[p] = total;
            final totalCapacity = days.length * ((capacities[p] ?? 120) + bonus);
            utilization[p] = totalCapacity > 0 ? total / totalCapacity : 0;
          }
          final values = utilization.values.toList();
          final mean = values.isEmpty ? 0.0 : values.reduce((a, b) => a + b) / values.length;
          final spread = values.isEmpty ? 0.0 : values.reduce((a, b) => a > b ? a : b) - values.reduce((a, b) => a < b ? a : b);
          final mad = values.isEmpty ? 0.0 : values.map((v) => (v - mean).abs()).reduce((a, b) => a + b) / values.length;
          return {'totals': totals, 'rates': utilization, 'overload': overload, 'risk': risky, 'spread': spread, 'mad': mad};
        }
        final candidates = entries.where((e) => e['owner'] != 'Atanmamış' && !protected(e['task'] as Map<String, dynamic>)).toList()
          ..sort((a, b) => (b['minutes'] as int).compareTo(a['minutes'] as int));
        Map<String, dynamic> simulate(int mode) {
          final loads = Map<String, int>.from(base);
          final changes = <Map<String, dynamic>>[];
          for (final e in candidates) {
            if (changes.length >= maxMoves) break;
            final fromOwner = e['owner'] as String;
            final fromDay = e['date'] as DateTime;
            final m = e['minutes'] as int;
            final fromKey = key(fromOwner, fromDay);
            final fromLoad = loads[fromKey] ?? 0;
            final fromExcess = (fromLoad - allowance(fromOwner)).clamp(0, 10000000);
            if (fromExcess == 0) continue;
            String? bestOwner;
            DateTime? bestDay;
            var bestGain = 0.0;
            for (final p in people) {
              if (mode == 0 && p != fromOwner) continue;
              if (mode == 1 && p == fromOwner) continue;
              for (final d in days) {
                if (mode == 1 && iso(d) != iso(fromDay)) continue;
                if (mode == 0 && iso(d) == iso(fromDay)) continue;
                if (mode == 2 && p == fromOwner && iso(d) == iso(fromDay)) continue;
                if (d.isBefore(fromDay)) continue; // Geri tarihe taşıma yok.
                final destKey = key(p, d);
                final destLoad = loads[destKey] ?? 0;
                final oldDestExcess = (destLoad - allowance(p)).clamp(0, 10000000);
                final newDestExcess = (destLoad + m - allowance(p)).clamp(0, 10000000);
                final newFromExcess = (fromLoad - m - allowance(fromOwner)).clamp(0, 10000000);
                final reduction = (fromExcess - newFromExcess) - (newDestExcess - oldDestExcess);
                if (reduction <= 0) continue;
                final delay = d.difference(fromDay).inDays;
                final ownerPenalty = p == fromOwner ? 0 : 4;
                final gain = reduction.toDouble() - delay * 1.5 - ownerPenalty;
                if (gain > bestGain) { bestGain = gain; bestOwner = p; bestDay = d; }
              }
            }
            if (bestOwner == null || bestDay == null) continue;
            loads[fromKey] = (loads[fromKey] ?? 0) - m;
            final destKey = key(bestOwner, bestDay);
            loads[destKey] = (loads[destKey] ?? 0) + m;
            changes.add({'title': str((e['task'] as Map<String, dynamic>)['title']), 'from': fromOwner, 'to': bestOwner,
              'oldDate': iso(fromDay), 'newDate': iso(bestDay), 'minutes': m, 'gain': bestGain});
          }
          return {'loads': loads, 'changes': changes, 'metrics': metrics(loads)};
        }
        final before = metrics(base);
        final scenarios = [simulate(0), simulate(1), simulate(2)];
        final chosen = scenarios[strategy];
        final after = chosen['metrics'] as Map<String, dynamic>;
        final changes = chosen['changes'] as List<Map<String, dynamic>>;
        final beforeTotals = before['totals'] as Map<String, int>;
        final afterTotals = after['totals'] as Map<String, int>;
        final beforeRates = before['rates'] as Map<String, double>;
        final afterRates = after['rates'] as Map<String, double>;
        final filtered = people.where((p) => (!onlyRisk || (afterRates[p] ?? 0) > 1 || (beforeRates[p] ?? 0) > 1) &&
            (search.isEmpty || p.toLowerCase().contains(search.toLowerCase()))).toList();
        Widget selector(String title, int value, List<int> values, void Function(int) onChange) =>
          DropdownButtonFormField<int>(initialValue: value, isExpanded: true, decoration: InputDecoration(labelText: title),
            items: values.map((n) => DropdownMenuItem(value: n, child: Text('$n'))).toList(), onChanged: (v) { if (v != null) update(() => onChange(v)); });
        Widget card(String label, String value) => Card(child: Padding(padding: const EdgeInsets.all(12),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label, style: const TextStyle(fontSize: 12)),
            Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 17, color: _purple))])));
        final rows = <String>['Sorumlu,Önceki dakika,Sonraki dakika,Önceki doluluk %,Sonraki doluluk %'];
        for (final p in people) {
          rows.add([csv(p), '${beforeTotals[p] ?? 0}', '${afterTotals[p] ?? 0}',
            ((beforeRates[p] ?? 0) * 100).toStringAsFixed(1), ((afterRates[p] ?? 0) * 100).toStringAsFixed(1)].join(','));
        }
        rows.add('Görev,Önceki sorumlu,Yeni sorumlu,Önceki tarih,Yeni tarih,Dakika');
        for (final c in changes) { rows.add([csv(c['title']), csv(c['from']), csv(c['to']), csv(c['oldDate']), csv(c['newDate']), '${c['minutes']}'].join(',')); }
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Column(children: [
          ListTile(title: const Text('Görev dağılımı adalet ve kapasite dengesi', style: TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text('${iso(start)} – ${iso(end.subtract(const Duration(days: 1)))} · Salt okunur'),
            trailing: IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))),
          if (loading) const LinearProgressIndicator(),
          Expanded(child: ListView(padding: const EdgeInsets.all(12), children: [
            const Text('Sorumluların kapasiteye göre normalize edilmiş doluluk oranlarını karşılaştırır. Simülasyon hiçbir kaydı değiştirmez.'),
            Wrap(spacing: 8, children: [
              ChoiceChip(label: const Text('Bugün'), selected: false, onSelected: (_) => update(() => anchor = DateTime.now())),
              ActionChip(label: const Text('← Önceki'), onPressed: () => update(() => anchor = anchor.subtract(Duration(days: horizon)))),
              ActionChip(label: const Text('Sonraki →'), onPressed: () => update(() => anchor = anchor.add(Duration(days: horizon)))),
            ]),
            Row(children: [Expanded(child: selector('Gün', horizon, [7,14,21,28,42,56], (v) => horizon = v)),
              const SizedBox(width: 8), Expanded(child: selector('Ek kapasite dk', bonus, [0,15,30,60], (v) => bonus = v))]),
            Row(children: [Expanded(child: selector('Azami değişiklik', maxMoves, [5,10,15,30,50], (v) => maxMoves = v)),
              const SizedBox(width: 8), Expanded(child: SwitchListTile(title: const Text('Hafta sonu'), value: weekends,
                onChanged: (v) => update(() => weekends = v)))]),
            const SizedBox(height: 8),
            const Text('Optimizasyon yaklaşımı', style: TextStyle(fontWeight: FontWeight.bold)),
            Wrap(spacing: 6, children: [for (var i = 0; i < 3; i++) ChoiceChip(
              label: Text(['Tarih', 'Sorumlu', 'Karma'][i]), selected: strategy == i,
              onSelected: (_) => update(() => strategy = i))]),
            Wrap(spacing: 6, children: [card('Önceki hedef üstü yük', '${before['overload']} dk'),
              card('Önerilen hedef üstü yük', '${after['overload']} dk'),
              card('Öneri', '${changes.length} görev'), card('Riskli gün', '${before['risk']} → ${after['risk']}')]),
            const Text('Stratejiler aynı kapasite varsayımlarıyla değerlendirilir:', style: TextStyle(fontWeight: FontWeight.w600)),
            for (var i = 0; i < scenarios.length; i++) ListTile(
              leading: Icon(i == strategy ? Icons.radio_button_checked : Icons.radio_button_unchecked),
              title: Text(['Tarih odaklı', 'Sorumlu odaklı', 'Karma'][i]),
              subtitle: Text('Hedef üstü yük: ${(scenarios[i]['metrics'] as Map<String,dynamic>)['overload']} dk · '
                'Öneri: ${(scenarios[i]['changes'] as List).length}'),
              onTap: () => update(() => strategy = i)),
            const Divider(),
            Text('İş yükü adaleti: Ortalama mutlak doluluk sapması '
              '${((before['mad'] as double) * 100).toStringAsFixed(1)} → ${((after['mad'] as double) * 100).toStringAsFixed(1)} yüzde puan'),
            Text('En yüksek ve en düşük doluluk farkı: '
              '${((before['spread'] as double) * 100).toStringAsFixed(1)} → ${((after['spread'] as double) * 100).toStringAsFixed(1)} yüzde puan'),
            const SizedBox(height: 8),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sorumlu ara'),
              onChanged: (v) => update(() => search = v)),
            SwitchListTile(title: const Text('Yalnızca kapasitesi aşılan sorumlular'), value: onlyRisk,
              onChanged: (v) => update(() => onlyRisk = v)),
            if (people.isEmpty) const ListTile(title: Text('Analiz edilecek atanmış sorumlu bulunamadı.')),
            for (final p in filtered) Card(child: ExpansionTile(
              title: Text(p),
              subtitle: Text('${beforeTotals[p] ?? 0} → ${afterTotals[p] ?? 0} dk · '
                '%${((beforeRates[p] ?? 0) * 100).toStringAsFixed(0)} → '
                '%${((afterRates[p] ?? 0) * 100).toStringAsFixed(0)} doluluk'),
              children: [ListTile(title: Text('Günlük kapasite: ${capacities[p] ?? 120} dk (+$bonus dk varsayım)'),
                subtitle: Text('Kabul edilen hedef aşımı: ${goals[p] ?? 0} dk · '
                  'Önerilen iş yükü farkı: ${(afterTotals[p] ?? 0) - (beforeTotals[p] ?? 0)} dk'))])),
            const Divider(),
            Text('Önerilen görev hareketleri (${changes.length})', style: const TextStyle(fontWeight: FontWeight.bold)),
            if (changes.isEmpty) const ListTile(title: Text('Hedef sapmasını azaltan uygun değişiklik bulunamadı.')),
            for (final c in changes.where((c) => search.isEmpty ||
                str(c['title']).toLowerCase().contains(search.toLowerCase()) ||
                str(c['from']).toLowerCase().contains(search.toLowerCase()) ||
                str(c['to']).toLowerCase().contains(search.toLowerCase())))
              ListTile(title: Text(str(c['title'])), subtitle: Text('${c['from']} (${c['oldDate']}) → '
                '${c['to']} (${c['newDate']}) · ${c['minutes']} dk')),
            const Divider(),
            Text('Veri kalitesi: Atanmamış $noOwner · Tarihsiz $noDate · Süresiz $noDuration · '
              'Korunan öncelikli görev $protectedCount'),
            const Text('Not: Doluluk karşılaştırması, her sorumlunun kendi toplam kapasitesine göre yapılır. '
              'Eksik süreler 30 dk, eksik günlük kapasite 120 dk varsayılır. Gerçek müsaitlik ve yetkinlik doğrulanmaz.'),
            const SizedBox(height: 12),
            FilledButton.tonalIcon(onPressed: () async {
              await Clipboard.setData(ClipboardData(text: rows.join('\n')));
              if (ctx.mounted) _notice('Adalet analizi CSV olarak kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV raporunu kopyala')),
          ])),
        ])));
      }),
    );
  }

  void _showKitchenOwnerBalanceDecision() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    bool loaded = false, busy = true, weekends = false, onlyRisk = false;
    int horizon = 14, bonus = 0, maxMoves = 20, selectedStrategy = 2;
    DateTime anchor = DateTime.now();
    String query = '';
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) { final d = DateTime.tryParse(str(v)); return d == null ? null : DateTime(d.year,d.month,d.day); }
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String owner(Map<String,dynamic> t) { final p = str(t['owner']).trim(); return p.isEmpty ? 'Atanmamış' : p; }
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    bool protected(Map<String,dynamic> t) { final p=str(t['priority'] ?? t['level']).toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high'); }
    int duration(Map<String,dynamic> t) { final n=int.tryParse(str(t['estimatedMinutes'])); return n != null && n>=5 && n<=1440 ? n : 30; }
    String csv(Object? v) => '"${str(v).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_) => StatefulBuilder(builder:(ctx,refresh) {
      if(!loaded) {
        loaded=true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw=jsonDecode(prefs.getString(taskKey) ?? '[]');
            if(raw is List) tasks.addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
            final c=jsonDecode(prefs.getString(capKey) ?? '{}');
            if(c is Map) for(final e in c.entries) { final n=int.tryParse(str(e.value)); if(n!=null && n>0) capacities[str(e.key)]=n; }
            final g=jsonDecode(prefs.getString(goalKey) ?? '{}');
            if(g is Map) for(final e in g.entries) { final n=int.tryParse(str(e.value)); if(n!=null && n>=0) goals[str(e.key)]=n; }
          } catch (_) { if(ctx.mounted) _notice('Görev dağılımı verileri okunamadı.'); }
          if(ctx.mounted) refresh(()=>busy=false);
        }).catchError((Object _) { if(ctx.mounted) refresh(()=>busy=false); });
      }
      final start=DateTime(anchor.year,anchor.month,anchor.day);
      final end=start.add(Duration(days:horizon));
      final people=<String>{...tasks.map(owner),...capacities.keys,...goals.keys}.where((p)=>p!='Atanmamış').toList()..sort();
      String key(String p,DateTime d) => '$p|${iso(d)}';
      int allowance(String p) => (capacities[p] ?? 120)+bonus+(goals[p] ?? 0);
      int pos(int x) => x>0?x:0;
      int excess(Map<String,int> loads) => loads.entries.fold<int>(0,(sum,e)=>sum+pos(e.value-allowance(e.key.split('|').first)));
      int risk(Map<String,int> loads) => loads.entries.where((e)=>e.value>allowance(e.key.split('|').first)).length;
      final base=<String,int>{};
      final entries=<Map<String,dynamic>>[];
      int missingDate=0,missingOwner=0,missingTime=0,protectedCount=0;
      for(final t in tasks) {
        if(!active(t)) continue;
        final p=owner(t),d=date(t['targetDate'] ?? t['due']);
        if(p=='Atanmamış') missingOwner++;
        if(d==null) missingDate++;
        if(int.tryParse(str(t['estimatedMinutes']))==null) missingTime++;
        if(d==null || d.isBefore(start) || !d.isBefore(end)) continue;
        final m=duration(t);
        base[key(p,d)]=(base[key(p,d)]??0)+m;
        if(protected(t)) protectedCount++;
        entries.add({'task':t,'owner':p,'date':d,'minutes':m});
      }
      final candidates=entries.where((e)=>e['owner']!='Atanmamış' && !protected(e['task'] as Map<String,dynamic>)).toList()
        ..sort((a,b)=>(b['minutes'] as int).compareTo(a['minutes'] as int));
      Map<String,dynamic> simulate(int strategy) {
        final loads=Map<String,int>.from(base);
        final changes=<Map<String,dynamic>>[];
        var delayTotal=0,ownerChanges=0;
        for(final e in candidates) {
          if(changes.length>=maxMoves) break;
          final p=e['owner'] as String,d=e['date'] as DateTime,m=e['minutes'] as int;
          final from=key(p,d);
          if((loads[from]??0)<=allowance(p)) continue;
          String? chosen; DateTime? chosenDate;
          double best=0;
          int gainBest=0;
          for(final q in people) {
            if(strategy==0 && q!=p) continue;
            for(var i=0;i<horizon;i++) {
              final next=start.add(Duration(days:i));
              if(next.isBefore(d) || (q==p && next==d)) continue;
              if(strategy==1 && next!=d) continue;
              if(!weekends && next.weekday>=6) continue;
              final to=key(q,next);
              final before=pos((loads[from]??0)-allowance(p))+pos((loads[to]??0)-allowance(q));
              final after=pos((loads[from]??0)-m-allowance(p))+pos((loads[to]??0)+m-allowance(q));
              final gain=before-after;
              final delay=next.difference(d).inDays;
              final score=gain.toDouble()-delay*5-(q==p?0:12);
              if(gain>0 && score>best) { best=score;gainBest=gain;chosen=q;chosenDate=next; }
            }
          }
          if(chosen!=null && chosenDate!=null) {
            loads[from]=(loads[from]??0)-m;
            final to=key(chosen,chosenDate);loads[to]=(loads[to]??0)+m;
            final delay=chosenDate.difference(d).inDays;
            delayTotal+=delay;
            if(chosen!=p) ownerChanges++;
            changes.add({'title':str((e['task'] as Map<String,dynamic>)['title']),'from':p,'to':chosen,'oldDate':d,'newDate':chosenDate,'minutes':m,'gain':gainBest,'delay':delay});
          }
        }
        final ownerLoad=<String,int>{};
        for(final p in people) {
          var sum=0;
          for(var i=0;i<horizon;i++) { sum+=loads[key(p,start.add(Duration(days:i)))]??0; }
          ownerLoad[p]=sum;
        }
        final vals=ownerLoad.values.toList();
        final spread=vals.isEmpty?0:vals.reduce((a,b)=>a>b?a:b)-vals.reduce((a,b)=>a<b?a:b);
        final mean=vals.isEmpty?0.0:vals.reduce((a,b)=>a+b)/vals.length;
        final imbalance=vals.isEmpty?0.0:vals.fold<double>(0,(s,v)=>s+(v-mean).abs())/vals.length;
        return {'loads':loads,'changes':changes,'after':excess(loads),'risk':risk(loads),'delay':delayTotal,'transfers':ownerChanges,'spread':spread,'imbalance':imbalance,'ownerLoad':ownerLoad};
      }
      final simulations=[simulate(0),simulate(1),simulate(2)];
      final selected=simulations[selectedStrategy];
      final selectedLoads=selected['loads'] as Map<String,int>;
      final ownerRows=<Map<String,dynamic>>[];
      for(final p in people) {
        var before=0,after=0,oldExcess=0,newExcess=0,oldRisk=0,newRisk=0;
        for(var i=0;i<horizon;i++) {
          final d=start.add(Duration(days:i)),k=key(p,d),a=base[k]??0,b=selectedLoads[k]??0;
          before+=a;after+=b;oldExcess+=pos(a-allowance(p));newExcess+=pos(b-allowance(p));
          if(a>allowance(p)) oldRisk++;
          if(b>allowance(p)) newRisk++;
        }
        ownerRows.add({'owner':p,'before':before,'after':after,'oldExcess':oldExcess,'newExcess':newExcess,'oldRisk':oldRisk,'newRisk':newRisk});
      }
      ownerRows.sort((a,b)=>(b['newExcess'] as int).compareTo(a['newExcess'] as int));
      final filteredOwners=ownerRows.where((r)=>str(r['owner']).toLowerCase().contains(query.toLowerCase()) && (!onlyRisk || (r['newExcess'] as int)>0)).toList();
      final filteredChanges=(selected['changes'] as List<Map<String,dynamic>>).where((r)=>'${r['title']} ${r['from']} ${r['to']}'.toLowerCase().contains(query.toLowerCase())).toList();
      final beforeTotal=excess(base);
      final bestIndex=List<int>.generate(3,(i)=>i)..sort((a,b) {
        final c=(simulations[a]['after'] as int).compareTo(simulations[b]['after'] as int);
        if(c!=0) return c;
        final d=(simulations[a]['delay'] as int).compareTo(simulations[b]['delay'] as int);
        return d!=0?d:(simulations[a]['transfers'] as int).compareTo(simulations[b]['transfers'] as int);
      });
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Akıllı kararlar / sorumlu bazlı kapasite dengeleme',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Aynı dönem, kapasite ve hedef koşullarında üç strateji karşılaştırılır. Analiz yalnızca önizlemedir; görev kayıtları değişmez.'),
        if(busy) const LinearProgressIndicator() else ...[
          Wrap(spacing:10,runSpacing:4,children:[
            DropdownButton<int>(value:horizon,items:[7,14,21,28,42,56].map((x)=>DropdownMenuItem(value:x,child:Text('$x gün'))).toList(),onChanged:(v)=>refresh(()=>horizon=v??14)),
            DropdownButton<int>(value:bonus,items:[0,15,30,60].map((x)=>DropdownMenuItem(value:x,child:Text('Ek kapasite +$x dk'))).toList(),onChanged:(v)=>refresh(()=>bonus=v??0)),
            DropdownButton<int>(value:maxMoves,items:[5,10,20,40,60].map((x)=>DropdownMenuItem(value:x,child:Text('En fazla $x öneri'))).toList(),onChanged:(v)=>refresh(()=>maxMoves=v??20)),
          ]),
          Wrap(spacing:8,children:[TextButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:horizon))),child:const Text('◀ Önceki')),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün')),TextButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:horizon))),child:const Text('Sonraki ▶'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
          SwitchListTile(title:const Text('Hafta sonuna görev öner'),value:weekends,onChanged:(v)=>refresh(()=>weekends=v)),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Dönemde ${entries.length} aktif görev • $protectedCount korunan kritik/yüksek görev',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('Başlangıç hedef üstü yük: $beforeTotal dk • Riskli sorumlu-gün: ${risk(base)}'),
            Text('Veri kontrolü: $missingDate tarihsiz • $missingOwner sorumlusuz • $missingTime süresiz'),
            Text('En düşük hedef üstü yük: ${['Tarih','Sorumlu','Karma'][bestIndex.first]} stratejisi'),
          ]))),
          const SizedBox(height:8),
          const Text('Strateji karşılaştırması',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold)),
          for(var i=0;i<3;i++) Card(child:RadioGroup<int>(groupValue:selectedStrategy,onChanged:(v)=>refresh(()=>selectedStrategy=v??2),child:RadioListTile<int>(value:i,title:Text(['Tarih odaklı','Sorumlu odaklı','Karma'][i]),subtitle:Text('Hedef üstü: ${simulations[i]['after']} dk (kazanç ${beforeTotal-(simulations[i]['after'] as int)} dk) • Riskli gün: ${simulations[i]['risk']}\nTaşıma: ${(simulations[i]['changes'] as List).length} • Erteleme: ${simulations[i]['delay']} gün • Yeniden atama: ${simulations[i]['transfers']}\nSorumlular arası iş yükü farkı: ${simulations[i]['spread']} dk • Ortalama mutlak sapma: ${(simulations[i]['imbalance'] as double).toStringAsFixed(1)} dk')))),
          const SizedBox(height:8),
          Text('Seçilen strateji: ${['Tarih odaklı','Sorumlu odaklı','Karma'][selectedStrategy]}',style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold)),
          Text('Hedef üstü yük $beforeTotal → ${selected['after']} dk • Riskli gün ${risk(base)} → ${selected['risk']}'),
          const Text('İş yükü dengesi toplam görev dakikalarına göre hesaplanır; kişilerin farklı kapasite ve uygunluklarını tek başına temsil etmez.'),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Görev veya sorumlu ara'),onChanged:(v)=>refresh(()=>query=v)),
          SwitchListTile(title:const Text('Yalnızca hedefi aşan sorumlular'),value:onlyRisk,onChanged:(v)=>refresh(()=>onlyRisk=v)),
          const Text('Sorumlu bazlı etki',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
          if(filteredOwners.isEmpty) const Text('Filtreye uygun sorumlu bulunamadı.'),
          for(final r in filteredOwners) Card(child:ListTile(title:Text(str(r['owner'])),subtitle:Text('İş yükü: ${r['before']} → ${r['after']} dk\nHedef üstü: ${r['oldExcess']} → ${r['newExcess']} dk • Riskli gün: ${r['oldRisk']} → ${r['newRisk']}\nGünlük kapasite: ${capacities[str(r['owner'])]??120}+$bonus dk • Tolerans: ${goals[str(r['owner'])]??0} dk'))),
          const Text('Önerilen görev hareketleri',style:TextStyle(fontSize:16,fontWeight:FontWeight.bold)),
          if(filteredChanges.isEmpty) const Text('Bu koşullarda uygun öneri bulunamadı.'),
          for(final r in filteredChanges) Card(child:ListTile(title:Text(str(r['title'])),subtitle:Text('${r['from']} / ${iso(r['oldDate'] as DateTime)} → ${r['to']} / ${iso(r['newDate'] as DateTime)}\n${r['minutes']} dk • Yerel hedef sapması kazancı: ${r['gain']} dk • Erteleme: ${r['delay']} gün'))),
          Wrap(spacing:8,runSpacing:8,children:[
            OutlinedButton.icon(onPressed:() async {
              final rows=<String>['Tür;Sorumlu;Önceki;Sonraki;Önceki hedef üstü;Sonraki hedef üstü'];
              for(final r in filteredOwners) { rows.add(['Sorumlu',r['owner'],r['before'],r['after'],r['oldExcess'],r['newExcess']].map(csv).join(';')); }
              rows.add('Tür;Görev;Eski sorumlu;Yeni sorumlu;Eski tarih;Yeni tarih;Dakika');
              for(final r in filteredChanges) { rows.add(['Görev',r['title'],r['from'],r['to'],iso(r['oldDate'] as DateTime),iso(r['newDate'] as DateTime),r['minutes']].map(csv).join(';')); }
              await Clipboard.setData(ClipboardData(text:rows.join('\n')));
              if(ctx.mounted) _notice('Karar destek raporu CSV olarak panoya kopyalandı.');
            },icon:const Icon(Icons.copy_outlined),label:const Text('CSV kopyala')),
            FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenPreventiveStrategyDecision();},icon:const Icon(Icons.compare_arrows_outlined),label:const Text('Strateji karar merkezine geç')),
          ]),
          const Text('Öneriler yalnızca kayıtlı görev tarihleri, tahmini süreler ve kapasite hedeflerine dayanır. Gerçek müsaitlik, yetkinlik ve dış takvimler doğrulanmaz.'),
        ],
      ])));
    }));
  }

  void _showKitchenPreventiveStrategyDecision() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    bool loaded = false, busy = true, weekends = false, includeLate = false;
    int horizon = 14, limit = 20, bonus = 0, delayWeight = 5, ownerWeight = 12;
    DateTime anchor = DateTime.now();
    String search = '';
    String str(Object? x) => '${x ?? ''}';
    DateTime? date(Object? x) { final d = DateTime.tryParse(str(x)); return d == null ? null : DateTime(d.year,d.month,d.day); }
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String person(Map<String,dynamic> t) { final p = str(t['owner']).trim(); return p.isEmpty ? 'Atanmamış' : p; }
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    bool protected(Map<String,dynamic> t) { final p = str(t['priority'] ?? t['level']).toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high'); }
    int minutes(Map<String,dynamic> t) { final n = int.tryParse(str(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String csv(Object? x) => '"${str(x).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context: context,isScrollControlled:true,builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!loaded) {
        loaded = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (raw is List) tasks.addAll(raw.whereType<Map>().map((x)=>Map<String,dynamic>.from(x)));
            final rawCaps = jsonDecode(prefs.getString(capKey) ?? '{}');
            if (rawCaps is Map) for (final e in rawCaps.entries) { final n = int.tryParse(str(e.value)); if(n != null && n > 0) capacities[str(e.key)] = n; }
            final rawGoals = jsonDecode(prefs.getString(goalKey) ?? '{}');
            if (rawGoals is Map) for (final e in rawGoals.entries) { final n = int.tryParse(str(e.value)); if(n != null && n >= 0) goals[str(e.key)] = n; }
          } catch (_) { if(ctx.mounted) _notice('Kapasite stratejisi verileri okunamadı.'); }
          if(ctx.mounted) refresh(()=>busy=false);
        }).catchError((Object _) { if(ctx.mounted) refresh(()=>busy=false); });
      }
      final start = DateTime(anchor.year,anchor.month,anchor.day);
      final end = start.add(Duration(days:horizon));
      final people = <String>{...tasks.map(person),...capacities.keys,...goals.keys}.where((x)=>x!='Atanmamış').toList()..sort();
      String slot(String p,DateTime d) => '$p|${iso(d)}';
      int allowance(String p) => (capacities[p] ?? 120) + bonus + (goals[p] ?? 0);
      int pos(int n) => n > 0 ? n : 0;
      int excess(Map<String,int> load) => load.entries.fold<int>(0,(sum,e)=>sum+pos(e.value-allowance(e.key.split('|').first)));
      int risks(Map<String,int> load) => load.entries.where((e)=>e.value>allowance(e.key.split('|').first)).length;
      final baseline = <String,int>{};
      final entries = <Map<String,dynamic>>[];
      var missingOwner=0,missingDate=0,missingMinutes=0,critical=0,late=0;
      for(var i=0;i<tasks.length;i++) {
        final t=tasks[i]; if(!active(t)) continue;
        final p=person(t), d=date(t['targetDate'] ?? t['due']);
        if(p=='Atanmamış') missingOwner++;
        if(d==null) missingDate++;
        if(int.tryParse(str(t['estimatedMinutes']))==null) missingMinutes++;
        if(d!=null && d.isBefore(start)) late++;
        if(d==null || d.isBefore(start) || !d.isBefore(end)) continue;
        final m=minutes(t);
        baseline[slot(p,d)]=(baseline[slot(p,d)]??0)+m;
        if(protected(t)) critical++;
        entries.add({'index':i,'task':t,'owner':p,'date':d,'minutes':m});
      }
      final candidates=entries.where((e)=>e['owner']!='Atanmamış' && !protected(e['task'] as Map<String,dynamic>)).toList()
        ..sort((a,b)=>(b['minutes'] as int).compareTo(a['minutes'] as int));
      final results=<Map<String,dynamic>>[];
      for(var strategy=0;strategy<3;strategy++) {
        final loads=Map<String,int>.from(baseline);
        final proposals=<Map<String,dynamic>>[];
        var delays=0,transfers=0;
        for(final e in candidates) {
          if(proposals.length>=limit) break;
          final p=e['owner'] as String,d=e['date'] as DateTime,m=e['minutes'] as int;
          final from=slot(p,d);
          if((loads[from]??0)<=allowance(p)) continue;
          String? bestP; DateTime? bestD;
          var bestScore=0.0,bestGain=0;
          for(final q in people) {
            if(strategy==0 && q!=p) continue;
            for(var offset=0;offset<horizon;offset++) {
              final next=start.add(Duration(days:offset));
              if(next.isBefore(d) || (q==p && next==d)) continue;
              if(strategy==1 && next!=d) continue;
              if(!weekends && next.weekday>=6) continue;
              final to=slot(q,next);
              final oldFrom=pos((loads[from]??0)-allowance(p));
              final oldTo=pos((loads[to]??0)-allowance(q));
              final gain=oldFrom+oldTo-pos((loads[from]??0)-m-allowance(p))-pos((loads[to]??0)+m-allowance(q));
              final delay=next.difference(d).inDays;
              final score=gain.toDouble()-delay*delayWeight-(q==p?0:ownerWeight);
              if(gain>0 && score>bestScore) { bestScore=score; bestGain=gain; bestP=q; bestD=next; }
            }
          }
          if(bestP!=null && bestD!=null) {
            loads[from]=(loads[from]??0)-m;
            final to=slot(bestP,bestD); loads[to]=(loads[to]??0)+m;
            final delay=bestD.difference(d).inDays;
            delays+=delay; if(bestP!=p) transfers++;
            proposals.add({'title':str((e['task'] as Map<String,dynamic>)['title']),'from':p,'to':bestP,'date':d,'next':bestD,'minutes':m,'gain':bestGain,'delay':delay,'score':bestScore});
          }
        }
        final ownerTotals=<String,int>{};
        for(final p in people) { var total=0; for(var k=0;k<horizon;k++) { total+=loads[slot(p,start.add(Duration(days:k)))]??0; } ownerTotals[p]=total; }
        final values=ownerTotals.values.toList();
        final spread=values.isEmpty?0:(values.reduce((a,b)=>a>b?a:b)-values.reduce((a,b)=>a<b?a:b));
        results.add({'name':['Tarih odaklı','Sorumlu odaklı','Karma'][strategy],'before':excess(baseline),'after':excess(loads),'risks':risks(loads),'proposals':proposals,'delays':delays,'transfers':transfers,'spread':spread,'loads':loads,'owners':ownerTotals});
      }
      results.sort((a,b) { final aGain=(a['before'] as int)-(a['after'] as int),bGain=(b['before'] as int)-(b['after'] as int); final c=bGain.compareTo(aGain); return c!=0?c:(a['delays'] as int).compareTo(b['delays'] as int); });
      final winner=results.first;
      final displayed=(winner['proposals'] as List<Map<String,dynamic>>).where((r)=>'${r['title']} ${r['from']} ${r['to']}'.toLowerCase().contains(search.toLowerCase())).toList();
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Önleyici senaryo karşılaştırması / karar desteği',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Üç strateji aynı kapasite, hedef ve dönem koşullarında karşılaştırılır. Gecikme ve sorumlu değişikliği cezaları karar puanını etkiler. Bu ekran kayıt değiştirmez.'),
        if(busy) const LinearProgressIndicator() else ...[
          Wrap(spacing:10,runSpacing:5,children:[
            DropdownButton<int>(value:horizon,items:[7,14,21,28,42,56].map((x)=>DropdownMenuItem(value:x,child:Text('$x gün'))).toList(),onChanged:(v)=>refresh(()=>horizon=v??14)),
            DropdownButton<int>(value:limit,items:[5,10,20,40,60].map((x)=>DropdownMenuItem(value:x,child:Text('En fazla $x taşıma'))).toList(),onChanged:(v)=>refresh(()=>limit=v??20)),
            DropdownButton<int>(value:bonus,items:[0,15,30,60].map((x)=>DropdownMenuItem(value:x,child:Text('Ek kapasite +$x dk'))).toList(),onChanged:(v)=>refresh(()=>bonus=v??0)),
            DropdownButton<int>(value:delayWeight,items:[0,2,5,10,20].map((x)=>DropdownMenuItem(value:x,child:Text('Gecikme cezası $x'))).toList(),onChanged:(v)=>refresh(()=>delayWeight=v??5)),
            DropdownButton<int>(value:ownerWeight,items:[0,5,12,20,40].map((x)=>DropdownMenuItem(value:x,child:Text('Sorumlu değişim cezası $x'))).toList(),onChanged:(v)=>refresh(()=>ownerWeight=v??12)),
          ]),
          Wrap(spacing:8,children:[TextButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:horizon))),child:const Text('◀ Önceki')),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün')),TextButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:horizon))),child:const Text('Sonraki ▶'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
          SwitchListTile(title:const Text('Hafta sonlarına görev öner'),value:weekends,onChanged:(v)=>refresh(()=>weekends=v)),
          SwitchListTile(title:const Text('Gecikmiş görevleri veri kalitesi özetinde göster'),value:includeLate,onChanged:(v)=>refresh(()=>includeLate=v)),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Aktif dönem görevi: ${entries.length} • Kritik/yüksek öncelik korunan: $critical',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('Mevcut hedef üstü yük: ${excess(baseline)} dk • Riskli sorumlu-gün: ${risks(baseline)}'),
            Text('Veri kalitesi: $missingOwner sorumlusuz • $missingDate tarihsiz • $missingMinutes süre eksik${includeLate?' • $late gecikmiş':''}'),
          ]))),
          Text('Aynı koşullarda üç strateji',style:Theme.of(ctx).textTheme.titleMedium),
          ...results.map((r)=>Card(child:ListTile(leading:Icon(r==winner?Icons.emoji_events_outlined:Icons.compare_arrows),title:Text('${r['name']}${r==winner?' • En yüksek iyileşme':''}'),subtitle:Text('Hedef üstü yük: ${r['before']} → ${r['after']} dk • Riskli gün: ${r['risks']}\nTaşıma: ${(r['proposals'] as List).length} • Toplam erteleme: ${r['delays']} gün • Sorumlu değişimi: ${r['transfers']}\nSorumlular arası toplam iş yükü farkı: ${r['spread']} dk')))),
          const Text('Karar kuralı: Önce en fazla hedef sapması azalması; eşitlikte en az toplam erteleme. Öneri puanı = hedef sapması kazancı − (erteleme günü × ceza) − (sorumlu değişikliği cezası). Pozitif puanlı hareketler önerilir.'),
          const SizedBox(height:8),
          Text('Öne çıkan strateji: ${winner['name']}',style:Theme.of(ctx).textTheme.titleMedium),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Önerilerde görev veya sorumlu ara'),onChanged:(v)=>refresh(()=>search=v)),
          if(displayed.isEmpty) const ListTile(title:Text('Bu koşullarda öneri bulunamadı.')),
          ...displayed.take(60).map((r)=>Card(child:ListTile(title:Text(str(r['title'])),subtitle:Text('${r['from']} / ${iso(r['date'] as DateTime)} → ${r['to']} / ${iso(r['next'] as DateTime)}\n${r['minutes']} dk • Hedef sapması kazancı ${r['gain']} dk • Erteleme ${r['delay']} gün • Puan ${r['score']}')))),
          Text('Sorumlu bazında önerilen dönem yükü',style:Theme.of(ctx).textTheme.titleMedium),
          ...(winner['owners'] as Map<String,int>).entries.take(30).map((e)=>ListTile(dense:true,title:Text(e.key),trailing:Text('${e.value} dk'))),
          FilledButton.tonalIcon(onPressed:() async {
            final rows=<String>['Strateji;Önceki sapma;Sonraki sapma;Riskli gün;Taşıma;Erteleme;Sorumlu değişimi;İş yükü farkı'];
            for(final r in results) { rows.add([r['name'],r['before'],r['after'],r['risks'],(r['proposals'] as List).length,r['delays'],r['transfers'],r['spread']].map(csv).join(';')); }
            rows.add('Görev;Eski sorumlu;Eski tarih;Yeni sorumlu;Yeni tarih;Süre;Kazanç;Erteleme;Puan');
            for(final r in displayed) { rows.add([r['title'],r['from'],iso(r['date'] as DateTime),r['to'],iso(r['next'] as DateTime),r['minutes'],r['gain'],r['delay'],r['score']].map(csv).join(';')); }
            await Clipboard.setData(ClipboardData(text:'\uFEFF${rows.join('\r\n')}'));
            if(ctx.mounted) _notice('Strateji karşılaştırması CSV olarak panoya kopyalandı.');
          },icon:const Icon(Icons.copy_outlined),label:const Text('Karşılaştırmayı ve önerileri CSV kopyala')),
          FilledButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenGoalDeviationRedistribution();},icon:const Icon(Icons.verified_outlined),label:const Text('Onaylı seçimli optimizasyona geç')),
          const Text('Uyarı: Bu öneriler başka ekrana aktarılmaz. Onaylı ekranda yeniden hesaplama gerekir. Gerçek kişi müsaitliği ve yetkinliği doğrulanmaz.'),
        ],
      ])));
    }));
  }

  void _showKitchenPreventiveWeeklyOptimizer() {
    const taskKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket41_owner_capacity_decision_goals_v1';
    final tasks = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    final goals = <String, int>{};
    bool started = false, busy = true, weekends = false, onlyImproving = false;
    int horizon = 14, limit = 20, buffer = 0, strategy = 2;
    String search = '', ownerFilter = 'Tümü';
    DateTime anchor = DateTime.now();
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) { final d = DateTime.tryParse(str(x)); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String owner(Map<String,dynamic> t) { final v = str(t['owner']).trim(); return v.isEmpty ? 'Atanmamış' : v; }
    bool active(Map<String,dynamic> t) => !['Tamamlandı','İptal'].contains(str(t['status']));
    bool protected(Map<String,dynamic> t) { final p = str(t['priority'] ?? t['level']).toLowerCase(); return p.contains('kritik') || p.contains('yüksek') || p.contains('critical') || p.contains('high'); }
    int duration(Map<String,dynamic> t) { final n = int.tryParse(str(t['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String csv(Object? v) => '"${str(v).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
      if (!started) {
        started = true;
        SharedPreferences.getInstance().then((prefs) {
          try {
            final raw = jsonDecode(prefs.getString(taskKey) ?? '[]');
            if (raw is List) tasks.addAll(raw.whereType<Map>().map((e) => Map<String,dynamic>.from(e)));
            final caps = jsonDecode(prefs.getString(capacityKey) ?? '{}');
            if (caps is Map) for (final e in caps.entries) { final n = int.tryParse(str(e.value)); if (n != null && n > 0) capacities[str(e.key)] = n; }
            final gs = jsonDecode(prefs.getString(goalKey) ?? '{}');
            if (gs is Map) for (final e in gs.entries) { final n = int.tryParse(str(e.value)); if (n != null && n >= 0) goals[str(e.key)] = n; }
          } catch (_) { if (ctx.mounted) _notice('Görev veya kapasite kayıtları okunamadı.'); }
          if (ctx.mounted) refresh(() => busy = false);
        }).catchError((Object _) { if (ctx.mounted) refresh(() => busy = false); });
      }
      final start = DateTime(anchor.year, anchor.month, anchor.day);
      final end = start.add(Duration(days: horizon));
      final people = <String>{...tasks.map(owner), ...capacities.keys, ...goals.keys}.where((p) => p != 'Atanmamış').toList()..sort();
      final filters = <String>['Tümü', ...people];
      String slot(String p, DateTime d) => '$p|${iso(d)}';
      int cap(String p) => (capacities[p] ?? 120) + buffer;
      int goal(String p) => goals[p] ?? 0;
      final entries = <Map<String,dynamic>>[];
      final baseline = <String,int>{};
      var missingOwner = 0, missingDate = 0, missingDuration = 0, protectedCount = 0;
      for (var i = 0; i < tasks.length; i++) {
        final t = tasks[i]; if (!active(t)) continue;
        if (owner(t) == 'Atanmamış') missingOwner++;
        if (parse(t['targetDate'] ?? t['due']) == null) missingDate++;
        if (int.tryParse(str(t['estimatedMinutes'])) == null) missingDuration++;
        final d = parse(t['targetDate'] ?? t['due']);
        if (d == null || d.isBefore(start) || !d.isBefore(end)) continue;
        final p = owner(t), m = duration(t);
        baseline[slot(p,d)] = (baseline[slot(p,d)] ?? 0) + m;
        if (protected(t)) protectedCount++;
        entries.add({'index':i,'task':t,'owner':p,'date':d,'minutes':m});
      }
      int excess(Map<String,int> loads) { var sum = 0; for (final e in loads.entries) { final p = e.key.split('|').first; final x = e.value - cap(p) - goal(p); if (x > 0) sum += x; } return sum; }
      int risks(Map<String,int> loads) => loads.entries.where((e) => e.value > cap(e.key.split('|').first) + goal(e.key.split('|').first)).length;
      final before = excess(baseline);
      final simulated = Map<String,int>.from(baseline);
      final proposals = <Map<String,dynamic>>[];
      final movable = entries.where((e) => !protected(e['task'] as Map<String,dynamic>) && e['owner'] != 'Atanmamış').toList()
        ..sort((a,b) => (b['minutes'] as int).compareTo(a['minutes'] as int));
      int pos(int x) => x > 0 ? x : 0;
      for (final e in movable) {
        if (proposals.length >= limit) break;
        final p = e['owner'] as String, d = e['date'] as DateTime, m = e['minutes'] as int;
        if (ownerFilter != 'Tümü' && p != ownerFilter) continue;
        final from = slot(p,d);
        if ((simulated[from] ?? 0) <= cap(p) + goal(p)) continue;
        String? bestPerson; DateTime? bestDate; var bestGain = 0; var bestDelay = 9999;
        for (final candidate in people) {
          if (strategy == 0 && candidate != p) continue;
          for (var offset = 0; offset < horizon; offset++) {
            final day = start.add(Duration(days:offset));
            if (day.isBefore(d) || (candidate == p && day == d)) continue;
            if (strategy == 1 && day != d) continue;
            if (!weekends && day.weekday >= 6) continue;
            final to = slot(candidate,day);
            final oldFrom = (simulated[from] ?? 0) - cap(p) - goal(p);
            final oldTo = (simulated[to] ?? 0) - cap(candidate) - goal(candidate);
            final gain = pos(oldFrom) + pos(oldTo) - pos(oldFrom-m) - pos(oldTo+m);
            final delay = day.difference(d).inDays;
            if (gain > bestGain || (gain == bestGain && gain > 0 && delay < bestDelay)) {
              bestGain = gain; bestPerson = candidate; bestDate = day; bestDelay = delay;
            }
          }
        }
        if (bestPerson != null && bestDate != null && bestGain > 0) {
          simulated[from] = (simulated[from] ?? 0) - m;
          final to = slot(bestPerson,bestDate);
          simulated[to] = (simulated[to] ?? 0) + m;
          proposals.add({'title':str((e['task'] as Map<String,dynamic>)['title']), 'fromOwner':p,'toOwner':bestPerson,
            'fromDate':d,'toDate':bestDate,'minutes':m,'gain':bestGain,'delay':bestDelay});
        }
      }
      final after = excess(simulated);
      final visible = proposals.where((e) => !onlyImproving || (e['gain'] as int) > 0).where((e) =>
        '${e['title']} ${e['fromOwner']} ${e['toOwner']} ${iso(e['fromDate'] as DateTime)}'.toLowerCase().contains(search.toLowerCase())).toList();
      final ownerRows = <Map<String,dynamic>>[];
      for (final p in people) {
        var prev = 0, next = 0, oldRisk = 0, newRisk = 0;
        for (var k = 0; k < horizon; k++) {
          final d = start.add(Duration(days:k)); final key = slot(p,d);
          final a = baseline[key] ?? 0, b = simulated[key] ?? 0;
          prev += pos(a-cap(p)-goal(p)); next += pos(b-cap(p)-goal(p));
          if (a > cap(p)+goal(p)) oldRisk++;
          if (b > cap(p)+goal(p)) newRisk++;
        }
        if (prev > 0 || next > 0 || proposals.any((e) => e['fromOwner'] == p || e['toOwner'] == p)) {
          ownerRows.add({'owner':p,'before':prev,'after':next,'oldRisk':oldRisk,'newRisk':newRisk});
        }
      }
      ownerRows.sort((a,b) => (b['before'] as int).compareTo(a['before'] as int));
      return SafeArea(child: FractionallySizedBox(heightFactor:.95, child: ListView(padding:const EdgeInsets.all(14),children:[
        Row(children:[const Expanded(child:Text('Önleyici görev optimizasyonu / haftalık karar merkezi',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Kayıtlı görevler için tarih, sorumlu ve karma strateji karşılaştırması. Kritik/yüksek öncelikli görevler korunur. Bu ekran salt okunurdur.'),
        if (busy) const LinearProgressIndicator() else ...[
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<int>(value:horizon,items:[7,14,21,28,42,56].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>horizon=v??14)),
            DropdownButton<int>(value:limit,items:[5,10,20,40,60].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v öneri'))).toList(),onChanged:(v)=>refresh(()=>limit=v??20)),
            DropdownButton<int>(value:strategy,items:const [DropdownMenuItem(value:0,child:Text('Tarih odaklı')),DropdownMenuItem(value:1,child:Text('Sorumlu odaklı')),DropdownMenuItem(value:2,child:Text('Karma'))],onChanged:(v)=>refresh(()=>strategy=v??2)),
            DropdownButton<int>(value:buffer,items:[0,15,30,60].map((v)=>DropdownMenuItem(value:v,child:Text('Ek kapasite +$v dk'))).toList(),onChanged:(v)=>refresh(()=>buffer=v??0)),
            DropdownButton<String>(value:filters.contains(ownerFilter)?ownerFilter:'Tümü',items:filters.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü')),
          ]),
          Wrap(spacing:6,children:[TextButton.icon(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:horizon))),icon:const Icon(Icons.chevron_left),label:const Text('Önceki')),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün')),TextButton.icon(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:horizon))),icon:const Icon(Icons.chevron_right),label:const Text('Sonraki'))]),
          Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
          SwitchListTile(title:const Text('Hafta sonuna görev öner'),value:weekends,onChanged:(v)=>refresh(()=>weekends=v)),
          SwitchListTile(title:const Text('Yalnızca iyileştiren öneriler'),value:onlyImproving,onChanged:(v)=>refresh(()=>onlyImproving=v)),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Görev, sorumlu veya tarih ara'),onChanged:(v)=>refresh(()=>search=v)),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Açık görev: ${entries.length} • Korunan öncelikli görev: $protectedCount • Öneri: ${proposals.length}',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('Hedef üstü yük: $before → $after dk • Azalma: ${before-after} dk'),
            Text('Riskli sorumlu-gün: ${risks(baseline)} → ${risks(simulated)}'),
            Text('Tarih değişimi: ${proposals.where((e)=>e['fromDate']!=e['toDate']).length} • Sorumlu değişimi: ${proposals.where((e)=>e['fromOwner']!=e['toOwner']).length}'),
          ]))),
          Text('Veri kalitesi: $missingOwner atanmamış • $missingDate tarihsiz • $missingDuration süre bilgisi eksik (30 dk varsayılır).'),
          const SizedBox(height:8),
          Text('Sorumlu bazında etki',style:Theme.of(ctx).textTheme.titleMedium),
          if(ownerRows.isEmpty) const ListTile(title:Text('İncelenen dönemde kapasite sapması yok.')),
          ...ownerRows.take(30).map((r)=>Card(child:ListTile(title:Text(str(r['owner'])),subtitle:Text('Hedef üstü yük: ${r['before']} → ${r['after']} dk • Riskli gün: ${r['oldRisk']} → ${r['newRisk']}')))),
          const SizedBox(height:8),
          Text('Önerilen görev değişiklikleri (önizleme)',style:Theme.of(ctx).textTheme.titleMedium),
          if(visible.isEmpty) const ListTile(title:Text('Bu filtrelerde iyileştirici öneri bulunamadı.')),
          ...visible.take(60).map((r)=>Card(child:ListTile(leading:const Icon(Icons.swap_horiz),title:Text(str(r['title'])),subtitle:Text('${r['fromOwner']} / ${iso(r['fromDate'] as DateTime)} → ${r['toOwner']} / ${iso(r['toDate'] as DateTime)}\n${r['minutes']} dk • Hedef sapması kazancı ${r['gain']} dk • Erteleme ${r['delay']} gün')))),
          FilledButton.tonalIcon(onPressed:() async {
            final lines=<String>['Tür;Görev;Önceki sorumlu;Önceki tarih;Yeni sorumlu;Yeni tarih;Süre;Kazanç'];
            for(final r in visible) { lines.add([csv('Öneri'),csv(r['title']),csv(r['fromOwner']),csv(iso(r['fromDate'] as DateTime)),csv(r['toOwner']),csv(iso(r['toDate'] as DateTime)),csv(r['minutes']),csv(r['gain'])].join(';')); }
            for(final r in ownerRows) { lines.add([csv('Sorumlu özeti'),csv(''),csv(r['owner']),csv(''),csv(''),csv(''),csv(r['before']),csv(r['after'])].join(';')); }
            await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
            if(ctx.mounted) _notice('Önleyici optimizasyon raporu panoya kopyalandı.');
          },icon:const Icon(Icons.copy_outlined),label:const Text('Önerileri ve sorumlu özetini CSV kopyala')),
          const SizedBox(height:8),
          const Text('Uygulama: Seçimli hedef sapması merkezinde önerileri yeniden hesaplayıp tek tek seçebilir, onaylayarak plan geçmişine kaydedebilirsin. Bu önizleme kaydedilmez.'),
          FilledButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenGoalDeviationRedistribution();},icon:const Icon(Icons.verified_outlined),label:const Text('Onaylı seçimli optimizasyon merkezine geç')),
        ],
      ])));
    }));
  }

  void _showKitchenPreventiveRiskPlanner() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, onlyRisk = false, includeWeekends = false;
    int horizon = 14, threshold = 80, maxSuggestions = 20;
    String ownerFilter = 'Tümü', query = '';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) { final d = DateTime.tryParse(str(v)); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String who(Map<String, dynamic> a) { final v = str(a['owner']).trim(); return v.isEmpty ? 'Atanmamış' : v; }
    int minutes(Map<String, dynamic> a) { final n = int.tryParse(str(a['estimatedMinutes'])); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    bool critical(Map<String, dynamic> a) { final v = str(a['priority'] ?? a['level']).toLowerCase(); return v.contains('kritik') || v.contains('critical') || v.contains('yüksek'); }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, update) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (raw is List) { actions.addAll(raw.whereType<Map>().map((v) => Map<String, dynamic>.from(v))); }
              final rawCapacity = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (rawCapacity is Map) {
                for (final e in rawCapacity.entries) {
                  final n = int.tryParse(str(e.value));
                  if (n != null && n > 0) capacities[str(e.key)] = n;
                }
              }
            } catch (_) { if (ctx.mounted) _notice('Planlama kayıtlarının bir bölümü okunamadı.'); }
            if (ctx.mounted) update(() => loading = false);
          }).catchError((Object _) { if (ctx.mounted) update(() => loading = false); });
        }
        final start = DateTime(anchor.year, anchor.month, anchor.day);
        final end = start.add(Duration(days: horizon));
        final activeActions = actions.where(active).toList();
        final owners = <String>{'Tümü', ...activeActions.map(who)}.toList()..sort();
        final bySlot = <String, int>{};
        final byCritical = <String, int>{};
        final byCount = <String, int>{};
        for (final a in activeActions) {
          final d = date(a['targetDate']); if (d == null) continue;
          final key = '${who(a)}|${iso(d)}';
          bySlot[key] = (bySlot[key] ?? 0) + minutes(a);
          byCount[key] = (byCount[key] ?? 0) + 1;
          if (critical(a)) byCritical[key] = (byCritical[key] ?? 0) + 1;
        }
        final daily = <Map<String, dynamic>>[];
        for (var offset = 0; offset < horizon; offset++) {
          final d = start.add(Duration(days: offset));
          for (final owner in owners.where((v) => v != 'Tümü')) {
            if (ownerFilter != 'Tümü' && ownerFilter != owner) continue;
            final key = '$owner|${iso(d)}';
            final used = bySlot[key] ?? 0;
            final cap = capacities[owner] ?? 120;
            final risk = used > cap ? 'Kapasite aşımı' : used * 100 >= cap * threshold ? 'Yüksek doluluk' : (byCritical[key] ?? 0) >= 2 ? 'Kritik görev yoğunluğu' : 'Normal';
            if (!onlyRisk || risk != 'Normal') daily.add({'day': d, 'owner': owner, 'used': used, 'cap': cap, 'critical': byCritical[key] ?? 0, 'count': byCount[key] ?? 0, 'risk': risk});
          }
        }
        daily.sort((a,b) {
          int weight(String v) => v == 'Kapasite aşımı' ? 3 : v == 'Yüksek doluluk' ? 2 : v == 'Kritik görev yoğunluğu' ? 1 : 0;
          final c = weight(str(b['risk'])).compareTo(weight(str(a['risk'])));
          return c != 0 ? c : (a['day'] as DateTime).compareTo(b['day'] as DateTime);
        });
        final proposals = <Map<String, dynamic>>[];
        final projected = Map<String, int>.from(bySlot);
        final candidates = activeActions.where((a) {
          final d = date(a['targetDate']);
          return d != null && !d.isBefore(start) && d.isBefore(end) &&
            (ownerFilter == 'Tümü' || who(a) == ownerFilter) &&
            '${a['title']} ${a['owner']}'.toLowerCase().contains(query.toLowerCase());
        }).toList()..sort((a,b) {
          final d = (date(a['targetDate']) ?? start).compareTo(date(b['targetDate']) ?? start);
          return d != 0 ? d : minutes(b).compareTo(minutes(a));
        });
        for (final a in candidates) {
          if (proposals.length >= maxSuggestions) break;
          final d = date(a['targetDate'])!;
          final person = who(a);
          final oldKey = '$person|${iso(d)}';
          final cap = capacities[person] ?? 120;
          final current = projected[oldKey] ?? 0;
          if (current <= cap && current * 100 < cap * threshold && (byCritical[oldKey] ?? 0) < 2) continue;
          if (critical(a)) continue; // Kritik görevlerin tarihini otomatik öneriyle değiştirme.
          final m = minutes(a);
          DateTime? best;
          int bestLoad = 999999;
          for (var shift = 1; shift <= 7; shift++) {
            final target = d.add(Duration(days: shift));
            if (!target.isBefore(end)) break;
            if (!includeWeekends && target.weekday >= 6) continue;
            final load = projected['$person|${iso(target)}'] ?? 0;
            if (load + m <= cap && load < bestLoad) { best = target; bestLoad = load; }
          }
          if (best != null) {
            final newKey = '$person|${iso(best)}';
            projected[oldKey] = current - m;
            projected[newKey] = (projected[newKey] ?? 0) + m;
            proposals.add({'title': str(a['title']), 'owner': person, 'from': d, 'to': best, 'minutes': m, 'reason': current > cap ? 'Kapasite aşımı' : 'Yoğunluk azaltma'});
          }
        }
        int excess(Map<String,int> slots) {
          var total = 0;
          for (final entry in slots.entries) {
            final bits = entry.key.split('|');
            if (bits.length < 2) continue;
            final d = date(bits.last);
            if (d == null || d.isBefore(start) || !d.isBefore(end)) continue;
            if (ownerFilter != 'Tümü' && bits.first != ownerFilter) continue;
            final diff = entry.value - (capacities[bits.first] ?? 120);
            if (diff > 0) total += diff;
          }
          return total;
        }
        final before = excess(bySlot), after = excess(projected);
        final riskCount = daily.where((v) => v['risk'] != 'Normal').length;
        final filtered = daily.where((v) => '${v['owner']} ${v['risk']} ${iso(v['day'] as DateTime)}'.toLowerCase().contains(query.toLowerCase())).toList();
        Widget metric(String title, String value) => Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(children: [Text(title, textAlign: TextAlign.center, style: const TextStyle(fontSize: 12)), Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 18))])));
        return SafeArea(child: Padding(padding: const EdgeInsets.all(16), child: SizedBox(
          height: MediaQuery.of(ctx).size.height * .90,
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [Expanded(child: Text('Önleyici planlama ve haftalık risk tahmini', style: Theme.of(ctx).textTheme.titleLarge)), IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
            const Text('Riskler mevcut görev tarihlerine ve günlük süre kapasitesine göre hesaplanır; geleceği kesin olarak tahmin etmez.'),
            if (loading) const LinearProgressIndicator(),
            Expanded(child: ListView(children: [
              Wrap(spacing: 8, runSpacing: 6, children: [
                DropdownButton<int>(value: horizon, items: [7,14,21,28].map((v) => DropdownMenuItem(value:v,child:Text('$v gün'))).toList(), onChanged:(v) { if(v!=null) update(()=>horizon=v); }),
                DropdownButton<int>(value: threshold, items: [70,80,90,100].map((v)=>DropdownMenuItem(value:v,child:Text('Risk eşiği %$v'))).toList(),onChanged:(v){if(v!=null)update(()=>threshold=v);}),
                DropdownButton<int>(value:maxSuggestions,items:[5,10,20,40].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v öneri'))).toList(),onChanged:(v){if(v!=null)update(()=>maxSuggestions=v);}),
                DropdownButton<String>(value:owners.contains(ownerFilter)?ownerFilter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)update(()=>ownerFilter=v);}),
              ]),
              Wrap(spacing: 8, children: [
                OutlinedButton.icon(onPressed:()=>update(()=>anchor=anchor.subtract(Duration(days:horizon))),icon:const Icon(Icons.chevron_left),label:const Text('Önceki')),
                OutlinedButton(onPressed:()=>update(()=>anchor=DateTime.now()),child:const Text('Bugün')),
                OutlinedButton.icon(onPressed:()=>update(()=>anchor=anchor.add(Duration(days:horizon))),icon:const Icon(Icons.chevron_right),label:const Text('Sonraki')),
              ]),
              Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
              TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Görev, sorumlu, tarih veya risk ara'),onChanged:(v)=>update(()=>query=v)),
              SwitchListTile(title:const Text('Yalnızca riskli sorumlu-günleri göster'),value:onlyRisk,onChanged:(v)=>update(()=>onlyRisk=v)),
              SwitchListTile(title:const Text('Alternatif önerilerde hafta sonunu kullan'),value:includeWeekends,onChanged:(v)=>update(()=>includeWeekends=v)),
              Wrap(spacing:6,runSpacing:6,children:[metric('Riskli sorumlu-gün','$riskCount'),metric('Mevcut aşım','$before dk'),metric('Öneri sonrası','$after dk'),metric('Öneri','${proposals.length}')]),
              const SizedBox(height:10),
              Text('Günlük risk haritası',style:Theme.of(ctx).textTheme.titleMedium),
              if(filtered.isEmpty) const ListTile(title:Text('Bu filtrede kayıt bulunamadı.')),
              ...filtered.take(100).map((v) {
                final used=v['used'] as int,cap=v['cap'] as int;
                return Card(child: ListTile(
                  leading: Icon(v['risk']=='Normal'?Icons.check_circle_outline:Icons.warning_amber_outlined,color:v['risk']=='Normal'?Colors.green:Colors.deepOrange),
                  title:Text('${v['owner']} • ${iso(v['day'] as DateTime)}'),
                  subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${v['risk']} • $used/$cap dk • ${v['count']} görev • ${v['critical']} öncelikli'),LinearProgressIndicator(value:(used/cap).clamp(0.0,1.0))]),
                ));
              }),
              const SizedBox(height:10),
              Text('Önleyici tarih önerileri (salt okunur)',style:Theme.of(ctx).textTheme.titleMedium),
              const Text('Kritik görevler korunur. Öneriler yalnızca aynı sorumlunun uygun sonraki günlerini arar; otomatik kayıt yapılmaz.'),
              if(proposals.isEmpty) const ListTile(title:Text('Uygun alternatif bulunamadı.')),
              ...proposals.map((v)=>Card(child:ListTile(leading:const Icon(Icons.event_available_outlined),title:Text(str(v['title'])),subtitle:Text('${v['owner']} • ${iso(v['from'] as DateTime)} → ${iso(v['to'] as DateTime)} • ${v['minutes']} dk\n${v['reason']}')))),
              FilledButton.tonalIcon(onPressed:() async {
                final lines=<String>['Tür;Sorumlu;Tarih;Görev;Dakika;Kapasite;Risk;Önerilen tarih'];
                for(final v in filtered) { lines.add([csv('Günlük risk'),csv(v['owner']),csv(iso(v['day'] as DateTime)),csv(v['count']),csv(v['used']),csv(v['cap']),csv(v['risk']),csv('')].join(';')); }
                for(final v in proposals) { lines.add([csv('Öneri'),csv(v['owner']),csv(iso(v['from'] as DateTime)),csv(v['title']),csv(v['minutes']),csv(''),csv(v['reason']),csv(iso(v['to'] as DateTime))].join(';')); }
                await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));
                if(ctx.mounted) _notice('Risk ve öneri raporu panoya kopyalandı.');
              },icon:const Icon(Icons.copy_outlined),label:const Text('Risk ve önerileri CSV kopyala')),
              const SizedBox(height:12),
            ])),
          ]),
        )));
      }));
  }

  void _showKitchenWeeklyOptimizationTrends() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    const goalsKey = 'paket39_plan_decision_goals_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool initialized = false, loading = true, onlyAutomated = false, onlyRegressions = false;
    int weeks = 8, overflowTarget = 0, criticalTarget = 0, ownerTarget = 10;
    DateTime anchor = DateTime.now();
    String search = '';
    String txt(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(txt(x));
    DateTime? day(Object? x) { final d = parse(x); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String csv(Object? x) => '"${txt(x).replaceAll('"', '""')}"';
    int duration(Object? x) { final n = int.tryParse(txt(x)); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String owner(Map<String, dynamic> a) { final x = txt(a['owner']).trim(); return x.isEmpty ? 'Atanmamış' : x; }
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(txt(a['status']));
    List<Map<String, dynamic>> rows(Object? x) => x is List ? x.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, int> load(List<Map<String, dynamic>> items) {
      final byDay = <String, int>{};
      for (final a in items) {
        if (!active(a)) continue;
        final d = day(a['targetDate']); if (d == null) continue;
        final key = '${owner(a)}|${d.year}-${d.month}-${d.day}';
        byDay[key] = (byDay[key] ?? 0) + duration(a['estimatedMinutes']);
      }
      var excess = 0, overloaded = 0;
      for (final entry in byDay.entries) {
        final who = entry.key.split('|').first;
        final over = entry.value - (capacities[who] ?? 120);
        if (over > 0) { excess += over; overloaded++; }
      }
      return {'excess': excess, 'overloaded': overloaded};
    }
    Map<String, dynamic> analyze(Map<String, dynamic> v) {
      final before = rows(v['before']), after = rows(v['after']);
      final b = load(before), a = load(after);
      final old = <String, Map<String, dynamic>>{};
      for (final row in before) { final id = txt(row['id']); if (id.isNotEmpty) old[id] = row; }
      var changes = 0, owners = 0, criticalDelay = 0, delayed = 0, missing = 0;
      for (final row in after) {
        final previous = old[txt(row['id'])];
        if (previous == null) { missing++; continue; }
        final changedOwner = owner(previous) != owner(row);
        final d1 = day(previous['targetDate']), d2 = day(row['targetDate']);
        final changedDate = txt(previous['targetDate']) != txt(row['targetDate']);
        if (changedOwner || changedDate) changes++;
        if (changedOwner) owners++;
        if (d1 != null && d2 != null && d2.isAfter(d1)) {
          final n = d2.difference(d1).inDays; delayed += n;
          final priority = txt(row['priority'] ?? row['level'] ?? previous['priority'] ?? previous['level']).toLowerCase();
          if (priority.contains('kritik') || priority.contains('critical')) criticalDelay += n;
        }
      }
      final reduction = b['excess']! - a['excess']!;
      return {'before': b['excess']!, 'after': a['excess']!, 'reduction': reduction,
        'overloadedBefore': b['overloaded']!, 'overloadedAfter': a['overloaded']!,
        'changes': changes, 'owners': owners, 'criticalDelay': criticalDelay, 'delayed': delayed, 'missing': missing,
        'pass': a['excess']! <= overflowTarget && criticalDelay <= criticalTarget && owners <= ownerTarget};
    }
    DateTime weekStart(DateTime d) { final x = DateTime(d.year, d.month, d.day); return x.subtract(Duration(days: x.weekday - 1)); }
    String dateLabel(DateTime d) => '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}.${d.year}';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!initialized) {
          initialized = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              versions.addAll(rows(jsonDecode(prefs.getString(versionsKey) ?? '[]')));
              final c = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (c is Map) { for (final e in c.entries) { final n = int.tryParse(txt(e.value)); if (n != null && n > 0) capacities[txt(e.key)] = n; } }
              final g = jsonDecode(prefs.getString(goalsKey) ?? '{}');
              if (g is Map) {
                overflowTarget = int.tryParse(txt(g['overflow'])) ?? 0;
                criticalTarget = int.tryParse(txt(g['criticalDelay'])) ?? 0;
                ownerTarget = int.tryParse(txt(g['ownerChanges'])) ?? 10;
              }
            } catch (_) { if (mounted) _notice('Trend kayıtlarının bir bölümü okunamadı.'); }
            if (ctx.mounted) refresh(() => loading = false);
          }).catchError((Object _) { if (ctx.mounted) refresh(() => loading = false); });
        }
        final lastWeek = weekStart(anchor);
        final firstWeek = lastWeek.subtract(Duration(days: (weeks - 1) * 7));
        final end = lastWeek.add(const Duration(days: 7));
        final relevant = versions.where((v) {
          final d = parse(v['at']);
          return d != null && !d.isBefore(firstWeek) && d.isBefore(end) &&
            (!onlyAutomated || txt(v['type']).toLowerCase() != 'manual') &&
            '${v['name']} ${v['note']} ${v['type']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        final analyzed = relevant.map((v) => <String, dynamic>{'version': v, 'result': analyze(v)}).toList();
        final buckets = <Map<String, dynamic>>[];
        for (var i = 0; i < weeks; i++) {
          final from = firstWeek.add(Duration(days: 7 * i));
          final to = from.add(const Duration(days: 7));
          final entries = analyzed.where((e) {
            final d = parse((e['version'] as Map<String, dynamic>)['at']);
            return d != null && !d.isBefore(from) && d.isBefore(to);
          }).toList();
          final results = entries.map((e) => e['result'] as Map<String, dynamic>).toList();
          final n = results.length;
          final improved = results.where((r) => (r['reduction'] as int) > 0).length;
          final worse = results.where((r) => (r['reduction'] as int) < 0).length;
          final passed = results.where((r) => r['pass'] == true).length;
          final reduction = results.fold<int>(0, (s, r) => s + (r['reduction'] as int));
          final before = results.fold<int>(0, (s, r) => s + (r['before'] as int));
          final after = results.fold<int>(0, (s, r) => s + (r['after'] as int));
          final changed = results.fold<int>(0, (s, r) => s + (r['changes'] as int));
          buckets.add({'from': from, 'count': n, 'improved': improved, 'worse': worse, 'passed': passed,
            'reduction': reduction, 'before': before, 'after': after, 'changed': changed, 'entries': entries});
        }
        final visible = buckets.where((b) => !onlyRegressions || (b['worse'] as int) > 0).toList().reversed.toList();
        final total = analyzed.length;
        final improved = analyzed.where((e) => ((e['result'] as Map<String, dynamic>)['reduction'] as int) > 0).length;
        final worse = analyzed.where((e) => ((e['result'] as Map<String, dynamic>)['reduction'] as int) < 0).length;
        final passed = analyzed.where((e) => (e['result'] as Map<String, dynamic>)['pass'] == true).length;
        final noChange = total - improved - worse;
        final totalReduction = analyzed.fold<int>(0, (s, e) => s + ((e['result'] as Map<String, dynamic>)['reduction'] as int));
        final nonEmpty = buckets.where((b) => (b['count'] as int) > 0).toList();
        final deteriorating = <Map<String, dynamic>>[];
        for (var i = 1; i < nonEmpty.length; i++) {
          final prev = nonEmpty[i - 1], current = nonEmpty[i];
          final pAvg = (prev['after'] as int) / (prev['count'] as int);
          final cAvg = (current['after'] as int) / (current['count'] as int);
          if (cAvg > pAvg) deteriorating.add(current);
        }
        final suggestions = <String>[];
        if (total == 0) {
          suggestions.add('Bu dönemde plan sürümü bulunmuyor. Önce optimizasyon çalıştırıp plan sürümü kaydet.');
        } else {
          if (worse > 0) suggestions.add('$worse sürümde kapasite aşımı arttı. Bu sürümlerin görev taşımalarını ve sorumlu değişimlerini karşılaştır.');
          if (deteriorating.isNotEmpty) suggestions.add('${deteriorating.length} haftada sürüm başına ortalama son-plan kapasite aşımı önceki veri bulunan haftadan yüksek.');
          if (passed < total) suggestions.add('${total - passed} sürüm güncel hedefleri karşılamıyor. Hedef merkezinde sınırları ve kritik görev ertelemelerini incele.');
          if (noChange > 0) suggestions.add('$noChange sürümde kapasite aşımı değişmedi; manuel anlık görüntüler de bu grupta olabilir.');
          if (suggestions.isEmpty) suggestions.add('İncelenen sürümlerde kapasite aşımı artışı veya hedef ihlali saptanmadı.');
        }
        Future<void> export() async {
          final lines = <String>['Hafta başlangıcı;Sürüm;İyileşen;Kötüleşen;Hedefe uygun;Önce aşım dk toplamı;Sonra aşım dk toplamı;Aşım farkı dk;Değişen görev kaydı'];
          for (final b in visible) {
            lines.add([dateLabel(b['from'] as DateTime), b['count'], b['improved'], b['worse'], b['passed'], b['before'], b['after'], b['reduction'], b['changed']].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
          if (mounted) _notice('Haftalık trend CSV raporu panoya kopyalandı.');
        }
        Widget metric(String label, String value) => Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label, style: const TextStyle(fontSize: 12)),
          Text(value, style: const TextStyle(fontSize: 19, fontWeight: FontWeight.bold))])));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Column(children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 12, 8, 4), child: Row(children: [
            const Expanded(child: Text('Haftalık optimizasyon trendleri / iyileştirme önerileri', style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold))),
            IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))])),
          Expanded(child: loading ? const Center(child: CircularProgressIndicator()) : ListView(padding: const EdgeInsets.all(12), children: [
            const Card(child: Padding(padding: EdgeInsets.all(12), child: Text('Trendler kayıtlı plan sürümlerinin önce/sonra kapasite tahminlerini gösterir; gerçekleşmiş görev performansı değildir. Aynı görev farklı sürümlerde tekrar bulunabilir. Haftalık toplamlar tekil tasarruf olarak yorumlanmamalıdır. Hedef uyumu mevcut hedef ayarlarına göre yeniden hesaplanır.'))),
            Wrap(spacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
              DropdownButton<int>(value: weeks, items: [4, 8, 12, 26].map((n) => DropdownMenuItem(value: n, child: Text('$n hafta'))).toList(), onChanged: (v) { if (v != null) refresh(() => weeks = v); }),
              IconButton(tooltip: 'Önceki dönem', onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_left)),
              OutlinedButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün')),
              IconButton(tooltip: 'Sonraki dönem', onPressed: () => refresh(() => anchor = anchor.add(Duration(days: weeks * 7))), icon: const Icon(Icons.chevron_right)),
              Text('${dateLabel(firstWeek)} – ${dateLabel(end.subtract(const Duration(days: 1)))}'),
            ]),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sürüm adı, türü veya notunda ara'), onChanged: (v) => refresh(() => search = v)),
            Wrap(spacing: 10, children: [
              FilterChip(label: const Text('Manuel sürümleri hariç tut'), selected: onlyAutomated, onSelected: (v) => refresh(() => onlyAutomated = v)),
              FilterChip(label: const Text('Yalnızca kötüleşme olan haftalar'), selected: onlyRegressions, onSelected: (v) => refresh(() => onlyRegressions = v)),
            ]),
            Wrap(spacing: 6, runSpacing: 6, children: [
              metric('İncelenen sürüm', '$total'), metric('İyileşen / kötüleşen', '$improved / $worse'),
              metric('Hedef uyumu', '$passed / $total'), metric('Değişmeyen', '$noChange'),
              metric('Aşım farkı toplamı', '$totalReduction dk'),
            ]),
            Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Kural tabanlı iyileştirme önerileri', style: TextStyle(fontWeight: FontWeight.bold)),
              const SizedBox(height: 8), ...suggestions.map((x) => Padding(padding: const EdgeInsets.only(bottom: 7), child: Text('• $x'))),
              Text('Güncel hedefler: kapasite aşımı ≤ $overflowTarget dk; kritik erteleme ≤ $criticalTarget gün; sorumlu değişimi ≤ $ownerTarget.'),
            ]))),
            const Padding(padding: EdgeInsets.symmetric(vertical: 8), child: Text('Haftalık sürüm eğilimi', style: TextStyle(fontWeight: FontWeight.bold))),
            if (visible.isEmpty) const Padding(padding: EdgeInsets.all(18), child: Text('Bu filtrelerde görüntülenecek hafta bulunmuyor.')),
            ...visible.map((b) {
              final n = b['count'] as int;
              final from = b['from'] as DateTime;
              final reduction = b['reduction'] as int;
              final entries = b['entries'] as List<Map<String, dynamic>>;
              final rate = n == 0 ? 0.0 : (b['passed'] as int) / n;
              return Card(child: ExpansionTile(
                leading: Icon(reduction < 0 ? Icons.trending_down : reduction > 0 ? Icons.trending_up : Icons.remove, color: reduction < 0 ? Colors.red : _purple),
                title: Text('${dateLabel(from)} haftası • $n sürüm'),
                subtitle: Text('Aşım farkı $reduction dk • İyileşen ${b['improved']} / Kötüleşen ${b['worse']}'),
                children: [Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('Önce toplam aşım: ${b['before']} dk • Sonra: ${b['after']} dk'),
                  Text('Hedefe uygun: ${b['passed']}/$n • Değişen görev kayıtları: ${b['changed']}'),
                  const SizedBox(height: 6), LinearProgressIndicator(value: rate, minHeight: 8),
                  const SizedBox(height: 8),
                  ...entries.map((e) { final v = e['version'] as Map<String, dynamic>, r = e['result'] as Map<String, dynamic>;
                    return ListTile(dense: true, title: Text(txt(v['name']).isEmpty ? 'Adsız sürüm' : txt(v['name'])),
                      subtitle: Text('${txt(v['type'])} • ${r['before']} → ${r['after']} dk • ${r['changes']} görev'),
                      trailing: Icon(r['pass'] == true ? Icons.check_circle_outline : Icons.warning_amber_outlined, color: r['pass'] == true ? Colors.green : Colors.orange));
                  }),
                ]))]));
            }),
            Wrap(spacing: 8, runSpacing: 8, children: [
              FilledButton.tonalIcon(onPressed: export, icon: const Icon(Icons.copy), label: const Text('Haftalık CSV kopyala')),
              OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenPlanGoalProgress(); }, icon: const Icon(Icons.insights_outlined), label: const Text('Hedef takibi')),
              OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenOptimizationVersions(); }, icon: const Icon(Icons.history), label: const Text('Plan sürümleri')),
              OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenOptimizationGoalCenter(); }, icon: const Icon(Icons.flag_outlined), label: const Text('Hedefleri düzenle')),
            ]),
          ])),
        ])));
      }));
  }

  void _showKitchenPlanGoalProgress() {
    const versionsKey = 'paket40_optimization_plan_versions_v1';
    const goalsKey = 'paket39_plan_decision_goals_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final versions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, onlyChanged = false, onlySuccess = false;
    int period = 28, overflowGoal = 0, criticalLimit = 0, ownerLimit = 10;
    String search = '', sort = 'En yeni';
    DateTime anchor = DateTime.now();
    String str(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(str(v));
    DateTime? day(Object? v) { final d = date(v); return d == null ? null : DateTime(d.year, d.month, d.day); }
    String csv(Object? v) => '"${str(v).replaceAll('"', '""')}"';
    int minutes(Object? v) { final n = int.tryParse(str(v)); return n != null && n >= 5 && n <= 1440 ? n : 30; }
    String owner(Map<String, dynamic> row) { final x = str(row['owner']).trim(); return x.isEmpty ? 'Atanmamış' : x; }
    bool active(Map<String, dynamic> row) => !['Tamamlandı', 'İptal'].contains(str(row['status']));
    bool critical(Map<String, dynamic> row) { final x = str(row['priority'] ?? row['level']).toLowerCase(); return x.contains('kritik') || x.contains('critical'); }
    List<Map<String, dynamic>> rows(Object? raw) => raw is List ? raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList() : <Map<String, dynamic>>[];
    Map<String, dynamic> measure(List<Map<String, dynamic>> items) {
      final loads = <String, int>{};
      var total = 0;
      for (final row in items) {
        if (!active(row)) continue;
        final d = day(row['targetDate']);
        if (d == null) continue;
        final k = '${owner(row)}|${d.year}-${d.month}-${d.day}';
        final m = minutes(row['estimatedMinutes']);
        loads[k] = (loads[k] ?? 0) + m;
        total += m;
      }
      var excess = 0, overloaded = 0;
      for (final entry in loads.entries) {
        final who = entry.key.split('|').first;
        final diff = entry.value - (capacities[who] ?? 120);
        if (diff > 0) { excess += diff; overloaded++; }
      }
      return {'excess': excess, 'overloaded': overloaded, 'minutes': total, 'days': loads.length};
    }
    Map<String, dynamic> analyze(Map<String, dynamic> version) {
      final before = rows(version['before']), after = rows(version['after']);
      final b = measure(before), a = measure(after);
      final oldById = <String, Map<String, dynamic>>{};
      for (final row in before) { final id = str(row['id']); if (id.isNotEmpty) oldById[id] = row; }
      var moved = 0, ownerChanges = 0, delayed = 0, criticalDelay = 0, unmatched = 0;
      for (final row in after) {
        final old = oldById[str(row['id'])];
        if (old == null) { unmatched++; continue; }
        final changedOwner = owner(row) != owner(old);
        final oldDate = day(old['targetDate']), newDate = day(row['targetDate']);
        final dateChanged = str(old['targetDate']) != str(row['targetDate']);
        if (changedOwner || dateChanged) moved++;
        if (changedOwner) ownerChanges++;
        if (oldDate != null && newDate != null && newDate.isAfter(oldDate)) {
          delayed += newDate.difference(oldDate).inDays;
          if (critical(row)) criticalDelay += newDate.difference(oldDate).inDays;
        }
      }
      final reduction = (b['excess'] as int) - (a['excess'] as int);
      final passOverflow = (a['excess'] as int) <= overflowGoal;
      final passCritical = criticalDelay <= criticalLimit;
      final passOwner = ownerChanges <= ownerLimit;
      return {'before': b, 'after': a, 'reduction': reduction, 'moved': moved,
        'ownerChanges': ownerChanges, 'delayed': delayed, 'criticalDelay': criticalDelay,
        'unmatched': unmatched, 'passOverflow': passOverflow, 'passCritical': passCritical,
        'passOwner': passOwner, 'passes': [passOverflow, passCritical, passOwner].where((v) => v).length,
        'success': passOverflow && passCritical && passOwner};
    }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              versions.addAll(rows(jsonDecode(prefs.getString(versionsKey) ?? '[]')));
              final caps = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (caps is Map) { for (final e in caps.entries) { final n = int.tryParse(str(e.value)); if (n != null && n > 0) capacities[str(e.key)] = n; } }
              final goals = jsonDecode(prefs.getString(goalsKey) ?? '{}');
              if (goals is Map) {
                overflowGoal = (int.tryParse(str(goals['overflow'])) ?? 0).clamp(0, 600).toInt();
                criticalLimit = (int.tryParse(str(goals['criticalDelay'])) ?? 0).clamp(0, 14).toInt();
                ownerLimit = (int.tryParse(str(goals['ownerChanges'])) ?? 10).clamp(0, 50).toInt();
              }
            } catch (_) { if (mounted) _notice('Hedef takip kayıtlarının bir bölümü okunamadı.'); }
            if (ctx.mounted) refresh(() => loading = false);
          });
        }
        final end = DateTime(anchor.year, anchor.month, anchor.day).add(const Duration(days: 1));
        final start = end.subtract(Duration(days: period));
        final dated = versions.where((v) {
          final d = date(v['at']);
          return d != null && !d.isBefore(start) && d.isBefore(end) &&
            '${v['name']} ${v['note']} ${v['type']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        final evaluated = dated.map((v) => <String, dynamic>{'version': v, 'result': analyze(v)}).where((e) {
          final r = e['result'] as Map<String, dynamic>;
          return (!onlyChanged || (r['moved'] as int) > 0) && (!onlySuccess || r['success'] == true);
        }).toList();
        evaluated.sort((a, b) {
          final va = a['version'] as Map<String, dynamic>, vb = b['version'] as Map<String, dynamic>;
          final ra = a['result'] as Map<String, dynamic>, rb = b['result'] as Map<String, dynamic>;
          if (sort == 'En eski') return str(va['at']).compareTo(str(vb['at']));
          if (sort == 'En çok iyileşme') return (rb['reduction'] as int).compareTo(ra['reduction'] as int);
          if (sort == 'En yüksek uyum') return (rb['passes'] as int).compareTo(ra['passes'] as int);
          return str(vb['at']).compareTo(str(va['at']));
        });
        final allResults = dated.map(analyze).toList();
        final count = allResults.length;
        final successful = allResults.where((r) => r['success'] == true).length;
        final improved = allResults.where((r) => (r['reduction'] as int) > 0).length;
        final worse = allResults.where((r) => (r['reduction'] as int) < 0).length;
        final totalReduction = allResults.fold<int>(0, (sum, r) => sum + (r['reduction'] as int));
        final totalMoves = allResults.fold<int>(0, (sum, r) => sum + (r['moved'] as int));
        final goalRate = count == 0 ? 0.0 : successful / count;
        Future<void> export() async {
          final lines = <String>['Sürüm;Tarih;Tür;Önce aşım dk;Sonra aşım dk;İyileşme dk;Taşınan görev;Sorumlu değişimi;Kritik erteleme gün;Hedef uyumu'];
          for (final e in evaluated) {
            final v = e['version'] as Map<String, dynamic>, r = e['result'] as Map<String, dynamic>;
            final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
            lines.add([v['name'], v['at'], v['type'], b['excess'], a['excess'], r['reduction'], r['moved'], r['ownerChanges'], r['criticalDelay'], r['success'] == true ? 'Uygun' : 'Uygun değil'].map(csv).join(';'));
          }
          await Clipboard.setData(ClipboardData(text: '﻿${lines.join('\r\n')}'));
          if (mounted) _notice('Hedef takip CSV raporu panoya kopyalandı.');
        }
        Widget metric(String title, String value, {String? note}) => Card(child: Padding(padding: const EdgeInsets.all(10),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontSize: 12)),
            Text(value, style: const TextStyle(fontSize: 19, fontWeight: FontWeight.bold)), if (note != null) Text(note, style: const TextStyle(fontSize: 11))])));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94, child: Column(children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 12, 8, 4), child: Row(children: [
            const Expanded(child: Text('Plan hedef takibi / optimizasyon başarı analizi', style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold))),
            IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))])),
          Expanded(child: loading ? const Center(child: CircularProgressIndicator()) : ListView(padding: const EdgeInsets.all(12), children: [
            const Card(child: Padding(padding: EdgeInsets.all(12), child: Text('Geçmiş analiz, kayıtlı plan sürümlerinin önce/sonra görüntülerine dayanır. Bu görüntüler anlık plan durumudur; gerçek görev tamamlama başarısı veya tarihsel kapasite kullanımı değildir. Manuel sürümler değişiklik içermeyebilir.'))),
            Wrap(spacing: 8, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
              DropdownButton<int>(value: period, items: [7, 14, 28, 60, 90].map((n) => DropdownMenuItem(value: n, child: Text('$n gün'))).toList(), onChanged: (v) { if (v != null) refresh(() => period = v); }),
              IconButton(tooltip: 'Önceki dönem', onPressed: () => refresh(() => anchor = anchor.subtract(Duration(days: period))), icon: const Icon(Icons.chevron_left)),
              OutlinedButton(onPressed: () => refresh(() => anchor = DateTime.now()), child: const Text('Bugün')),
              IconButton(tooltip: 'Sonraki dönem', onPressed: () => refresh(() => anchor = anchor.add(Duration(days: period))), icon: const Icon(Icons.chevron_right)),
              Text('${start.day}.${start.month}.${start.year} – ${anchor.day}.${anchor.month}.${anchor.year}'),
            ]),
            Wrap(spacing: 6, runSpacing: 6, children: [
              metric('Sürüm sayısı', '$count'), metric('Hedefe uygun', '$successful / $count'),
              metric('Hedef uyumu', '%${(goalRate * 100).toStringAsFixed(0)}'),
              metric('İyileşen / kötüleşen', '$improved / $worse'),
              metric('Toplam aşım farkı', '$totalReduction dk', note: 'Sürümler arası toplam; tekil tasarruf değildir'),
              metric('Taşınan görev kayıtları', '$totalMoves'),
            ]),
            Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Kayıtlı karar hedefleri', style: TextStyle(fontWeight: FontWeight.bold)),
              Text('Azami kapasite aşımı: $overflowGoal dk  •  Kritik erteleme: $criticalLimit gün  •  Sorumlu değişimi: $ownerLimit'),
              const SizedBox(height: 8), LinearProgressIndicator(value: goalRate, minHeight: 9),
              const SizedBox(height: 6), Text('Hedefe uygun sürüm oranı: %${(goalRate * 100).toStringAsFixed(1)}'),
              TextButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenOptimizationGoalCenter(); }, icon: const Icon(Icons.tune), label: const Text('Hedefleri düzenle / senaryo karar merkezi')),
            ]))),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Sürüm adı, notu veya türünde ara'), onChanged: (v) => refresh(() => search = v)),
            Wrap(spacing: 12, crossAxisAlignment: WrapCrossAlignment.center, children: [
              FilterChip(label: const Text('Yalnızca değişen'), selected: onlyChanged, onSelected: (v) => refresh(() => onlyChanged = v)),
              FilterChip(label: const Text('Hedefe uygun'), selected: onlySuccess, onSelected: (v) => refresh(() => onlySuccess = v)),
              DropdownButton<String>(value: sort, items: ['En yeni', 'En eski', 'En çok iyileşme', 'En yüksek uyum'].map((x) => DropdownMenuItem(value: x, child: Text(x))).toList(), onChanged: (v) { if (v != null) refresh(() => sort = v); }),
            ]),
            if (evaluated.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('Bu dönemde filtrelere uyan plan sürümü yok.')),
            ...evaluated.map((e) {
              final v = e['version'] as Map<String, dynamic>, r = e['result'] as Map<String, dynamic>;
              final b = r['before'] as Map<String, dynamic>, a = r['after'] as Map<String, dynamic>;
              return Card(child: ExpansionTile(
                leading: Icon(r['success'] == true ? Icons.check_circle_outline : Icons.info_outline, color: r['success'] == true ? Colors.green : _purple),
                title: Text(str(v['name']).isEmpty ? 'Adsız plan' : str(v['name'])),
                subtitle: Text('${str(v['at']).replaceAll('T', ' ').split('.').first} • Aşım ${b['excess']} → ${a['excess']} dk • ${r['passes']}/3 hedef'),
                children: [Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('Tür: ${v['type'] ?? '—'}  •  ${v['note'] ?? ''}'),
                  Text('Aşım iyileşmesi: ${r['reduction']} dk  •  Aşırı yüklü gün: ${b['overloaded']} → ${a['overloaded']}'),
                  Text('Planlanan süre: ${b['minutes']} → ${a['minutes']} dk'),
                  Text('Değişen görev: ${r['moved']}  •  Sorumlu değişimi: ${r['ownerChanges']}'),
                  Text('Erteleme toplamı: ${r['delayed']} gün  •  Kritik erteleme: ${r['criticalDelay']} gün'),
                  Text('Hedef kontrolü: aşım ${r['passOverflow'] == true ? '✓' : '✗'}, kritik erteleme ${r['passCritical'] == true ? '✓' : '✗'}, sorumlu değişimi ${r['passOwner'] == true ? '✓' : '✗'}'),
                  if ((r['unmatched'] as int) > 0) Text('Önceki görüntüde eşleşmeyen görev: ${r['unmatched']}'),
                ]))]));
            }),
            const SizedBox(height: 8),
            Wrap(spacing: 8, runSpacing: 8, children: [
              FilledButton.tonalIcon(onPressed: export, icon: const Icon(Icons.copy), label: const Text('Filtrelenmiş CSV kopyala')),
              OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenOptimizationVersions(); }, icon: const Icon(Icons.history), label: const Text('Plan sürümlerine geç')),
              OutlinedButton.icon(onPressed: () { Navigator.pop(ctx); _showKitchenVersionDeepComparison(); }, icon: const Icon(Icons.compare_arrows), label: const Text('Ayrıntılı karşılaştırma')),
            ]),
          ])),
        ])));
      }));
  }

  void _showKitchenOptimizationGoalCenter() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const goalKey = 'paket39_plan_decision_goals_v1';
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, weekends = false;
    int horizon = 14, maxMoves = 15, overflowGoal = 0,
        criticalDelayLimit = 0, ownerChangeLimit = 10;
    String query = '', ownerFilter = 'Tümü';
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime? day(Object? x) {
      final d = parse(x);
      return d == null ? null : DateTime(d.year, d.month, d.day);
    }
    String stamp(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String person(Map<String, dynamic> a) {
      final o = str(a['owner']).trim();
      return o.isEmpty ? 'Atanmamış' : o;
    }
    bool active(Map<String, dynamic> a) => !['Tamamlandı', 'İptal'].contains(str(a['status']));
    int duration(Map<String, dynamic> a) {
      final v = int.tryParse(str(a['estimatedMinutes']));
      return v != null && v >= 5 && v <= 1440 ? v : 30;
    }
    int priority(Map<String, dynamic> a) {
      final p = str(a['priority'] ?? a['level']).toLowerCase();
      if (p.contains('kritik') || p.contains('critical')) return 4;
      if (p.contains('yüksek') || p.contains('high')) return 3;
      return 1;
    }
    String identity(Map<String, dynamic> a) =>
        '${a['createdAt'] ?? a['created'] ?? ''}|${a['title'] ?? ''}|${a['sourceProduct'] ?? ''}';
    String csv(Object? x) => '"${str(x).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(
      context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (raw is List) actions.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
              final capRaw = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (capRaw is Map) {
                for (final entry in capRaw.entries) {
                  final n = int.tryParse(str(entry.value));
                  if (n != null && n > 0) capacities[str(entry.key)] = n;
                }
              }
              final goals = jsonDecode(prefs.getString(goalKey) ?? '{}');
              if (goals is Map) {
                overflowGoal = (int.tryParse(str(goals['overflow'])) ?? 0).clamp(0, 600).toInt();
                criticalDelayLimit = (int.tryParse(str(goals['criticalDelay'])) ?? 0).clamp(0, 14).toInt();
                ownerChangeLimit = (int.tryParse(str(goals['ownerChanges'])) ?? 10).clamp(0, 50).toInt();
              }
            } catch (_) {
              if (ctx.mounted) _notice('Karar merkezi verileri okunamadı.');
            }
            if (ctx.mounted) refresh(() => loading = false);
          });
        }
        final now = DateTime.now();
        final start = DateTime(now.year, now.month, now.day);
        final end = start.add(Duration(days: horizon));
        final owners = actions.where(active).map(person).toSet().toList()..sort();
        if (ownerFilter != 'Tümü' && !owners.contains(ownerFilter)) ownerFilter = 'Tümü';
        int cap(String o) => capacities[o] ?? 120;
        String key(String o, DateTime d) => '$o|${stamp(d)}';
        final load = <String, int>{};
        final counts = <String, int>{};
        for (final a in actions) {
          counts[identity(a)] = (counts[identity(a)] ?? 0) + 1;
          final d = day(a['targetDate']);
          if (!active(a) || d == null || d.isBefore(start) || !d.isBefore(end)) continue;
          final k = key(person(a), d);
          load[k] = (load[k] ?? 0) + duration(a);
        }
        int excess(Map<String, int> m) {
          var total = 0;
          for (final e in m.entries) {
            final o = e.key.split('|').first;
            if (e.value > cap(o)) total += e.value - cap(o);
          }
          return total;
        }
        int overloadDays(Map<String, int> m) => m.entries.where((e) => e.value > cap(e.key.split('|').first)).length;
        final baseline = excess(load);
        final candidates = actions.where((a) {
          final d = day(a['targetDate']);
          return active(a) && d != null && !d.isBefore(start) && d.isBefore(end) &&
              counts[identity(a)] == 1 &&
              (ownerFilter == 'Tümü' || person(a) == ownerFilter) &&
              '${a['title']} ${person(a)}'.toLowerCase().contains(query.toLowerCase());
        }).toList()..sort((a, b) {
          final da = day(a['targetDate'])!, db = day(b['targetDate'])!;
          final oa = (load[key(person(a), da)] ?? 0) - cap(person(a));
          final ob = (load[key(person(b), db)] ?? 0) - cap(person(b));
          final c = ob.compareTo(oa);
          return c != 0 ? c : priority(b).compareTo(priority(a));
        });
        Map<String, dynamic> scenario(int policy) {
          final working = Map<String, int>.from(load);
          final changes = <Map<String, dynamic>>[];
          for (final a in candidates) {
            if (changes.length >= maxMoves) break;
            final fromDay = day(a['targetDate'])!, fromOwner = person(a);
            final minutes = duration(a), oldKey = key(fromOwner, fromDay);
            if ((working[oldKey] ?? 0) <= cap(fromOwner)) continue;
            final originalExcess = excess(working);
            Map<String, dynamic>? best;
            var bestGain = 0;
            final options = policy == 1 ? [fromOwner] : policy == 2 ? owners : owners;
            for (final o in options) {
              if (policy == 2 && o == fromOwner) continue;
              for (var shift = 0; shift < horizon; shift++) {
                if (policy == 2 && shift != 0) continue;
                if (policy == 1 && shift == 0) continue;
                final d = fromDay.add(Duration(days: shift));
                if (!d.isBefore(end) || (shift == 0 && o == fromOwner)) continue;
                if (!weekends && d.weekday >= DateTime.saturday) continue;
                if (priority(a) >= 4 && shift > criticalDelayLimit) continue;
                final newKey = key(o, d);
                if ((working[newKey] ?? 0) + minutes > cap(o)) continue;
                working[oldKey] = (working[oldKey] ?? 0) - minutes;
                working[newKey] = (working[newKey] ?? 0) + minutes;
                final gain = originalExcess - excess(working);
                working[oldKey] = (working[oldKey] ?? 0) + minutes;
                working[newKey] = (working[newKey] ?? 0) - minutes;
                if (gain > bestGain || (gain == bestGain && gain > 0 &&
                    (best == null || shift < (best['delay'] as int)))) {
                  bestGain = gain;
                  best = {'task': str(a['title']), 'from': fromOwner,
                    'to': o, 'oldDate': stamp(fromDay), 'newDate': stamp(d),
                    'delay': shift, 'priority': priority(a), 'minutes': minutes,
                    'oldKey': oldKey, 'newKey': newKey};
                }
              }
            }
            if (best == null || bestGain <= 0) continue;
            final changesOwner = changes.where((e) => e['from'] != e['to']).length;
            if (best['from'] != best['to'] && changesOwner >= ownerChangeLimit) continue;
            working[best['oldKey'] as String] = (working[best['oldKey'] as String] ?? 0) - minutes;
            working[best['newKey'] as String] = (working[best['newKey'] as String] ?? 0) + minutes;
            changes.add(best);
          }
          final ownerMoves = changes.where((e) => e['from'] != e['to']).length;
          final criticalDelays = changes.where((e) => (e['priority'] as int) >= 4 && (e['delay'] as int) > criticalDelayLimit).length;
          final remaining = excess(working);
          return {'policy': policy, 'changes': changes, 'excess': remaining,
            'days': overloadDays(working), 'ownerMoves': ownerMoves,
            'criticalDelays': criticalDelays, 'gain': baseline - remaining,
            'passes': remaining <= overflowGoal && ownerMoves <= ownerChangeLimit && criticalDelays == 0};
        }
        final results = [scenario(1), scenario(2), scenario(3)];
        int score(Map<String, dynamic> r) {
          final gain = r['gain'] as int;
          final changes = r['changes'] as List;
          final ownerMoves = r['ownerMoves'] as int;
          final delayed = changes.fold<int>(0, (sum, x) => sum + (x['delay'] as int));
          final improvement = baseline == 0 ? 0 : (gain * 75 / baseline).round();
          return (improvement - ownerMoves * 2 - delayed + (r['passes'] == true ? 25 : 0)).clamp(0, 100).toInt();
        }
        results.sort((a, b) {
          final c = (b['passes'] == true ? 1 : 0).compareTo(a['passes'] == true ? 1 : 0);
          return c != 0 ? c : score(b).compareTo(score(a));
        });
        Future<void> saveGoals() async {
          try {
            final prefs = await SharedPreferences.getInstance();
            await prefs.setString(goalKey, jsonEncode({'overflow': overflowGoal,
              'criticalDelay': criticalDelayLimit, 'ownerChanges': ownerChangeLimit}));
            if (ctx.mounted) _notice('Optimizasyon hedefleri kaydedildi.');
          } catch (_) {
            if (ctx.mounted) _notice('Hedefler kaydedilemedi.');
          }
        }
        Widget metric(String title, String value) => Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: Row(children: [Expanded(child: Text(title)), Text(value, style: const TextStyle(fontWeight: FontWeight.bold))]));
        final names = {1: 'Tarih değişimi', 2: 'Sorumlu değişimi', 3: 'Karma plan'};
        return SafeArea(child: Padding(
          padding: EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
          child: SizedBox(height: MediaQuery.of(ctx).size.height * .92,
            child: ListView(padding: const EdgeInsets.all(16), children: [
              const Text('🎯 Plan hedefleri ve senaryo karar merkezi',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
              const SizedBox(height: 6),
              const Text('Öneriler kural tabanlıdır. Bu ekran görev kayıtlarını değiştirmez.'),
              if (loading) const LinearProgressIndicator(),
              Wrap(spacing: 8, children: [
                DropdownButton<int>(value: horizon, items: [7,14,21,28].map((v) => DropdownMenuItem(value: v, child: Text('$v gün'))).toList(), onChanged: (v) => refresh(() => horizon = v ?? 14)),
                DropdownButton<int>(value: maxMoves, items: [5,10,15,25,50].map((v) => DropdownMenuItem(value: v, child: Text('En çok $v öneri'))).toList(), onChanged: (v) => refresh(() => maxMoves = v ?? 15)),
                DropdownButton<String>(value: ownerFilter, items: ['Tümü', ...owners].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => refresh(() => ownerFilter = v ?? 'Tümü')),
              ]),
              TextField(decoration: const InputDecoration(labelText: 'Görev / sorumlu ara', prefixIcon: Icon(Icons.search)), onChanged: (v) => refresh(() => query = v)),
              SwitchListTile(title: const Text('Hafta sonu alternatiflerine izin ver'), value: weekends, onChanged: (v) => refresh(() => weekends = v)),
              const Divider(),
              Text('Hedef kapasite aşımı: en fazla $overflowGoal dakika'),
              Slider(value: overflowGoal.toDouble(), min: 0, max: 600, divisions: 60, label: '$overflowGoal dk', onChanged: (v) => refresh(() => overflowGoal = v.round())),
              Text('Kritik görev erteleme sınırı: $criticalDelayLimit gün'),
              Slider(value: criticalDelayLimit.toDouble(), min: 0, max: 14, divisions: 14, label: '$criticalDelayLimit gün', onChanged: (v) => refresh(() => criticalDelayLimit = v.round())),
              Text('Sorumlu değişikliği sınırı: $ownerChangeLimit görev'),
              Slider(value: ownerChangeLimit.toDouble(), min: 0, max: 50, divisions: 50, label: '$ownerChangeLimit', onChanged: (v) => refresh(() => ownerChangeLimit = v.round())),
              FilledButton.tonalIcon(onPressed: saveGoals, icon: const Icon(Icons.save_outlined), label: const Text('Hedefleri cihazda sakla')),
              const Divider(),
              metric('Mevcut kapasite aşımı', '$baseline dk'),
              metric('Mevcut aşırı yüklü sorumlu-gün', '${overloadDays(load)}'),
              metric('Değerlendirilen görev', '${candidates.length}'),
              const Text('Senaryolar (hedef uygunluğu ve puana göre)', style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold)),
              for (final r in results) Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(
                crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('${names[r['policy']]} • ${r['passes'] == true ? 'HEDEFE UYGUN' : 'HEDEF DIŞI'}',
                    style: const TextStyle(fontWeight: FontWeight.bold)),
                  LinearProgressIndicator(value: score(r) / 100),
                  metric('Karar puanı', '${score(r)}/100'),
                  metric('Kalan kapasite aşımı', '${r['excess']} dk'),
                  metric('Azalan kapasite aşımı', '${r['gain']} dk'),
                  metric('Aşırı yüklü sorumlu-gün', '${r['days']}'),
                  metric('Önerilen görev hareketi', '${(r['changes'] as List).length}'),
                  metric('Sorumlu değişimi', '${r['ownerMoves']}'),
                  ExpansionTile(title: const Text('Önerilen hareketleri incele'), children: [
                    if ((r['changes'] as List).isEmpty) const ListTile(title: Text('Uygun iyileştirme önerisi bulunamadı.')),
                    for (final m in (r['changes'] as List)) ListTile(
                      dense: true, title: Text('${m['task']}'),
                      subtitle: Text('${m['from']} / ${m['oldDate']} → ${m['to']} / ${m['newDate']} • ${m['minutes']} dk')),
                  ]),
                ]))),
              const SizedBox(height: 8),
              OutlinedButton.icon(onPressed: () async {
                final rows = <String>['Senaryo;Uygun;Puan;KalanAsim;KazanilanDakika;AsiriYukluGun;SorumluDegisimi;Gorev;EskiSorumlu;YeniSorumlu;EskiTarih;YeniTarih'];
                for (final r in results) {
                  final moves = r['changes'] as List;
                  if (moves.isEmpty) rows.add([names[r['policy']], r['passes'], score(r), r['excess'], r['gain'], r['days'], r['ownerMoves'], '', '', '', '', ''].map(csv).join(';'));
                  for (final m in moves) {
                    rows.add([names[r['policy']], r['passes'], score(r), r['excess'], r['gain'], r['days'], r['ownerMoves'], m['task'], m['from'], m['to'], m['oldDate'], m['newDate']].map(csv).join(';'));
                  }
                }
                await Clipboard.setData(ClipboardData(text: '\uFEFF${rows.join('\r\n')}'));
                if (ctx.mounted) _notice('Senaryo karar raporu panoya kopyalandı.');
              }, icon: const Icon(Icons.copy_all_outlined), label: const Text('Karar raporunu CSV olarak kopyala')),
              FilledButton.tonalIcon(onPressed: () { Navigator.pop(ctx); _showKitchenConflictAlternatives(); },
                icon: const Icon(Icons.alt_route_outlined), label: const Text('Alternatif plan uygulama ekranına git')),
              const Text('Not: Filtreler yalnızca değişiklik adaylarını sınırlar; kapasite hesabı tüm açık görevleri kapsar. Geçmiş görevlerin gerçek takvim müsaitliği doğrulanmaz.'),
            ]))));
      }),
    );
  }

  void _showKitchenPlanOptimizationScore() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool initiated = false, loading = true, allowWeekends = false;
    int window = 14, maxMoves = 15, capacityWeight = 45,
        delayWeight = 25, ownerWeight = 15, priorityWeight = 15;
    String ownerFilter = 'Tümü', search = '';
    String txt(Object? v) => '${v ?? ''}';
    DateTime? date(Object? v) => DateTime.tryParse(txt(v));
    DateTime? day(Object? v) {
      final d = date(v);
      return d == null ? null : DateTime(d.year, d.month, d.day);
    }
    String fmt(DateTime d) => '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
    String owner(Map<String, dynamic> a) {
      final v = txt(a['owner']).trim();
      return v.isEmpty ? 'Atanmamış' : v;
    }
    bool open(Map<String, dynamic> a) =>
        !['Tamamlandı', 'İptal'].contains(txt(a['status']));
    int mins(Map<String, dynamic> a) {
      final v = int.tryParse(txt(a['estimatedMinutes']));
      return v != null && v >= 5 && v <= 1440 ? v : 30;
    }
    int urgency(Map<String, dynamic> a) {
      final p = '${a['priority'] ?? a['level'] ?? ''}'.toLowerCase();
      if (p.contains('kritik') || p.contains('critical')) return 4;
      if (p.contains('yüksek') || p.contains('high')) return 3;
      if (p.contains('orta') || p.contains('medium')) return 2;
      return 1;
    }
    String id(Map<String, dynamic> a) =>
        '${a['createdAt'] ?? a['created'] ?? ''}|${a['title'] ?? ''}|${a['sourceProduct'] ?? ''}';
    String csv(Object? v) => '"${txt(v).replaceAll('"', '""')}"';
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (!initiated) {
          initiated = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw = jsonDecode(prefs.getString(actionKey) ?? '[]');
              if (raw is List) {
                actions.addAll(raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)));
              }
              final rawCap = jsonDecode(prefs.getString(capacityKey) ?? '{}');
              if (rawCap is Map) {
                for (final e in rawCap.entries) {
                  final v = int.tryParse(txt(e.value));
                  if (v != null && v > 0) capacities[txt(e.key)] = v;
                }
              }
            } catch (_) {
              if (mounted) _notice('Planlama verileri okunamadı.');
            }
            if (ctx.mounted) refresh(() => loading = false);
          });
        }
        final today = DateTime.now();
        final start = DateTime(today.year, today.month, today.day);
        final end = start.add(Duration(days: window));
        final owners = actions.where(open).map(owner).toSet().toList()..sort();
        if (ownerFilter != 'Tümü' && !owners.contains(ownerFilter)) ownerFilter = 'Tümü';
        String loadKey(String o, DateTime d) => '$o|${fmt(d)}';
        int cap(String o) => capacities[o] ?? 120;
        final loads = <String, int>{};
        final identities = <String, int>{};
        for (final a in actions) {
          identities[id(a)] = (identities[id(a)] ?? 0) + 1;
          if (!open(a)) continue;
          final d = day(a['targetDate']);
          if (d == null || d.isBefore(start) || !d.isBefore(end)) continue;
          final k = loadKey(owner(a), d);
          loads[k] = (loads[k] ?? 0) + mins(a);
        }
        int overflow(Map<String, int> values) {
          var sum = 0;
          for (final e in values.entries) {
            final o = e.key.split('|').first;
            if (e.value > cap(o)) sum += e.value - cap(o);
          }
          return sum;
        }
        int overloaded(Map<String, int> values) => values.entries
            .where((e) => e.value > cap(e.key.split('|').first)).length;
        final baseline = overflow(loads);
        final candidates = actions.where((a) {
          final d = day(a['targetDate']);
          return open(a) && d != null && !d.isBefore(start) && d.isBefore(end) &&
              identities[id(a)] == 1 &&
              (ownerFilter == 'Tümü' || owner(a) == ownerFilter) &&
              '${a['title']} ${owner(a)}'.toLowerCase().contains(search.toLowerCase());
        }).toList()..sort((a, b) {
          final ka = loadKey(owner(a), day(a['targetDate'])!);
          final kb = loadKey(owner(b), day(b['targetDate'])!);
          final overA = (loads[ka] ?? 0) - cap(owner(a));
          final overB = (loads[kb] ?? 0) - cap(owner(b));
          final c = overB.compareTo(overA);
          return c != 0 ? c : urgency(b).compareTo(urgency(a));
        });
        List<Map<String, dynamic>> simulate(int policy) {
          final working = Map<String, int>.from(loads);
          final moves = <Map<String, dynamic>>[];
          for (final a in candidates) {
            if (moves.length >= maxMoves) break;
            final oldDay = day(a['targetDate'])!;
            final oldOwner = owner(a), duration = mins(a);
            final oldKey = loadKey(oldOwner, oldDay);
            final oldLoad = working[oldKey] ?? 0;
            if (oldLoad <= cap(oldOwner)) continue;
            final oldOver = (oldLoad - cap(oldOwner)).clamp(0, 1000000).toInt();
            Map<String, dynamic>? best;
            double bestScore = double.negativeInfinity;
            final candidateOwners = policy == 0 ? [oldOwner] : owners;
            for (final nextOwner in candidateOwners) {
              if (nextOwner == 'Atanmamış' && oldOwner != 'Atanmamış') continue;
              for (var offset = 0; offset < window; offset++) {
                final nextDay = start.add(Duration(days: offset));
                if (!allowWeekends && nextDay.weekday >= 6) continue;
                if (nextOwner == oldOwner && nextDay == oldDay) continue;
                if (policy == 1 && nextDay != oldDay) continue;
                if (policy == 2 && nextOwner != oldOwner && nextDay == oldDay) continue;
                final nextKey = loadKey(nextOwner, nextDay);
                if (cap(nextOwner) - (working[nextKey] ?? 0) < duration) continue;
                final afterOver = (oldLoad - duration - cap(oldOwner)).clamp(0, 1000000).toInt();
                final gain = oldOver - afterOver;
                if (gain <= 0) continue;
                final delay = nextDay.difference(oldDay).inDays;
                final changedOwner = nextOwner != oldOwner;
                // Weighted, transparent heuristic; higher scores are preferred.
                final score = gain * capacityWeight * 1.0 -
                    (delay > 0 ? delay : 0) * delayWeight * urgency(a) * 2.0 -
                    (changedOwner ? ownerWeight * 20.0 : 0.0) -
                    (delay > 0 ? priorityWeight * urgency(a) * delay * 2.0 : 0.0);
                if (score > bestScore) {
                  bestScore = score;
                  best = {'title': txt(a['title']), 'oldOwner': oldOwner,
                    'newOwner': nextOwner, 'oldDate': fmt(oldDay),
                    'newDate': fmt(nextDay), 'minutes': duration,
                    'gain': gain, 'delay': delay, 'priority': urgency(a),
                    'ownerChanged': changedOwner, 'score': score};
                }
              }
            }
            if (best == null) continue;
            final nextKey = loadKey(txt(best['newOwner']), day(best['newDate'])!);
            working[oldKey] = oldLoad - duration;
            working[nextKey] = (working[nextKey] ?? 0) + duration;
            moves.add(best);
          }
          return moves;
        }
        final plans = [simulate(0), simulate(1), simulate(2)];
        Map<String, int> after(List<Map<String, dynamic>> moves) {
          final result = Map<String, int>.from(loads);
          for (final m in moves) {
            final a = loadKey(txt(m['oldOwner']), day(m['oldDate'])!);
            final b = loadKey(txt(m['newOwner']), day(m['newDate'])!);
            final n = m['minutes'] as int;
            result[a] = (result[a] ?? 0) - n;
            result[b] = (result[b] ?? 0) + n;
          }
          return result;
        }
        final results = plans.map(after).toList();
        double grade(int i) {
          final moves = plans[i];
          final gain = baseline - overflow(results[i]);
          final delay = moves.fold<int>(0, (v, m) => v + ((m['delay'] as int) > 0 ? m['delay'] as int : 0));
          final changes = moves.where((m) => m['ownerChanged'] == true).length;
          final criticalDelay = moves.fold<int>(0, (v, m) => v +
              ((m['delay'] as int) > 0 ? (m['delay'] as int) * (m['priority'] as int) : 0));
          final capacityScore = baseline == 0 ? 100.0 : 100.0 * gain / baseline;
          final delayScore = (100.0 - delay * 5.0).clamp(0.0, 100.0);
          final ownerScore = moves.isEmpty ? 100.0 : 100.0 * (1 - changes / moves.length);
          final priorityScore = (100.0 - criticalDelay * 5.0).clamp(0.0, 100.0);
          final total = capacityWeight + delayWeight + ownerWeight + priorityWeight;
          return (capacityScore * capacityWeight + delayScore * delayWeight +
              ownerScore * ownerWeight + priorityScore * priorityWeight) / total;
        }
        final scores = [for (var i = 0; i < 3; i++) grade(i)];
        final ranked = [0, 1, 2]..sort((a, b) => scores[b].compareTo(scores[a]));
        final best = ranked.first;
        final names = ['Tarih kaydırma', 'Sorumlu değiştirme', 'Karma alternatif'];
        final report = <String>[
          'Senaryo;Puan;Öneri;Aşım önce dk;Aşım sonra dk;Aşırı yüklü gün önce;Aşırı yüklü gün sonra',
          for (var i = 0; i < 3; i++) [names[i], scores[i].toStringAsFixed(1),
            plans[i].length, baseline, overflow(results[i]), overloaded(loads),
            overloaded(results[i])].map(csv).join(';'),
          '', 'Senaryo;Görev;Eski sorumlu;Yeni sorumlu;Eski tarih;Yeni tarih;Süre dk;Gecikme gün;Kapasite kazancı dk',
          for (var i = 0; i < 3; i++)
            for (final m in plans[i]) [names[i], m['title'], m['oldOwner'], m['newOwner'],
              m['oldDate'], m['newDate'], m['minutes'], m['delay'], m['gain']].map(csv).join(';'),
        ];
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            Row(children: [Expanded(child: Text('Plan optimizasyon skoru',
              style: Theme.of(ctx).textTheme.titleLarge)),
              IconButton(onPressed: () => Navigator.pop(ctx), icon: const Icon(Icons.close))]),
            const Text('Üç senaryoyu kapasite kazanımı, erteleme, sorumlu değişimi ve kritik görev etkisine göre puanlar. Bu ekran yalnızca analiz yapar; kayıtları değiştirmez.'),
            if (loading) const LinearProgressIndicator() else ...[
              Wrap(spacing: 8, runSpacing: 6, children: [
                for (final n in [7, 14, 21, 28]) ChoiceChip(label: Text('$n gün'),
                  selected: window == n, onSelected: (_) => refresh(() => window = n)),
                FilterChip(label: const Text('Hafta sonuna izin ver'), selected: allowWeekends,
                  onSelected: (v) => refresh(() => allowWeekends = v)),
              ]),
              DropdownButtonFormField<String>(initialValue: ownerFilter,
                decoration: const InputDecoration(labelText: 'Sorumlu'),
                items: [for (final o in ['Tümü', ...owners]) DropdownMenuItem(value: o, child: Text(o))],
                onChanged: (v) => refresh(() => ownerFilter = v ?? 'Tümü')),
              TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
                labelText: 'Görev veya sorumlu ara'), onChanged: (v) => refresh(() => search = v)),
              Wrap(spacing: 8, children: [for (final n in [5, 10, 15, 25, 50])
                ChoiceChip(label: Text('En fazla $n'), selected: maxMoves == n,
                  onSelected: (_) => refresh(() => maxMoves = n))]),
              const SizedBox(height: 8),
              const Text('Puanlama ağırlıkları (toplam otomatik normalize edilir)',
                style: TextStyle(fontWeight: FontWeight.bold)),
              for (final label in ['Kapasite aşımı', 'Erteleme', 'Sorumlu değişimi', 'Kritik görev'])
                Builder(builder: (_) {
                  final value = label == 'Kapasite aşımı' ? capacityWeight :
                      label == 'Erteleme' ? delayWeight :
                      label == 'Sorumlu değişimi' ? ownerWeight : priorityWeight;
                  return Row(children: [SizedBox(width: 130, child: Text(label)),
                    Expanded(child: Slider(value: value.toDouble(), min: 5, max: 70, divisions: 13,
                      label: '$value', onChanged: (v) => refresh(() {
                        final n = v.round();
                        if (label == 'Kapasite aşımı') { capacityWeight = n; }
                        else if (label == 'Erteleme') { delayWeight = n; }
                        else if (label == 'Sorumlu değişimi') { ownerWeight = n; }
                        else { priorityWeight = n; }
                      }))), Text('$value')]);
                }),
              Card(child: ListTile(leading: const Icon(Icons.analytics_outlined),
                title: Text('Başlangıç kapasite aşımı: $baseline dk'),
                subtitle: Text('${overloaded(loads)} aşırı yüklü sorumlu-gün • ${candidates.length} uygun görev • varsayılan günlük kapasite 120 dk'))),
              Card(child: ListTile(leading: const Icon(Icons.emoji_events_outlined),
                title: Text('En yüksek puan: ${names[best]} • ${scores[best].toStringAsFixed(1)}/100'),
                subtitle: Text('Kapasite aşımı: $baseline → ${overflow(results[best])} dk. Puanlar sezgiseldir; tamamlanma garantisi vermez.'))),
              for (final i in ranked) Card(child: ExpansionTile(
                initiallyExpanded: i == best,
                leading: CircleAvatar(child: Text('${i + 1}')),
                title: Text('${names[i]} • ${scores[i].toStringAsFixed(1)}/100'),
                subtitle: Text('${plans[i].length} öneri • Aşım ${overflow(results[i])} dk • ${overloaded(results[i])} aşırı yüklü sorumlu-gün'),
                children: [Padding(padding: const EdgeInsets.symmetric(horizontal: 16),
                  child: LinearProgressIndicator(value: (scores[i] / 100).clamp(0.0, 1.0))),
                  if (plans[i].isEmpty) const ListTile(title: Text('Uygun değişiklik önerisi bulunamadı.')),
                  for (final m in plans[i].take(30)) ListTile(dense: true,
                    title: Text(txt(m['title'])),
                    subtitle: Text('${m['oldOwner']} ${m['oldDate']} → ${m['newOwner']} ${m['newDate']}\n'
                      '${m['minutes']} dk • Kazanç ${m['gain']} dk • Erteleme ${m['delay']} gün')),
                ])),
              Wrap(spacing: 8, runSpacing: 8, children: [
                OutlinedButton.icon(onPressed: () async {
                  await Clipboard.setData(ClipboardData(text: '\uFEFF${report.join('\r\n')}'));
                  if (mounted) _notice('Senaryo puanları ve öneriler CSV olarak kopyalandı.');
                }, icon: const Icon(Icons.copy), label: const Text('CSV raporu kopyala')),
                FilledButton.tonalIcon(onPressed: () {
                  Navigator.pop(ctx);
                  _showKitchenConflictAlternatives();
                }, icon: const Icon(Icons.tune), label: const Text('Senaryoları uygula ekranı')),
              ]),
              const SizedBox(height: 8),
              const Text('Not: Bu puanlar mevcut görev ve kapasite kayıtlarından üretilen kural tabanlı simülasyonlardır. Tarihsel başarı oranı, harici takvim veya kişisel yetkinlik bilgisi kullanılmaz. Uygulama için açılan ekranda senaryoyu yeniden seçip onaylamalısın.'),
            ],
          ])));
      }),
    );
  }

  void _showKitchenConflictAlternatives() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const capacityKey = 'paket39_daily_available_minutes_v1';
    const versionKey = 'paket40_optimization_plan_versions_v1';
    final actions = <Map<String, dynamic>>[];
    final capacities = <String, int>{};
    bool started = false, loading = true, weekends = false, onlyOverloaded = true;
    int days = 14, strategy = 0, maxChanges = 15;
    String ownerFilter = 'Tümü', query = '';
    String str(Object? x) => '${x ?? ''}';
    DateTime? parse(Object? x) => DateTime.tryParse(str(x));
    DateTime? day(Object? x) { final d = parse(x); return d == null ? null : DateTime(d.year,d.month,d.day); }
    String fmt(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String who(Map<String,dynamic> a) { final o=str(a['owner']).trim(); return o.isEmpty?'Atanmamış':o; }
    int duration(Map<String,dynamic> a) { final n=int.tryParse(str(a['estimatedMinutes'])); return n!=null&&n>=5&&n<=1440?n:30; }
    String identity(Map<String,dynamic> a) => '${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
    bool active(Map<String,dynamic> a) => !['Tamamlandı','İptal'].contains(str(a['status']));
    String csv(Object? v) => '"${str(v).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,setSheet){
      if(!started){started=true;SharedPreferences.getInstance().then((prefs){
        try{
          final a=jsonDecode(prefs.getString(actionKey)??'[]');
          if(a is List)actions.addAll(a.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
          final c=jsonDecode(prefs.getString(capacityKey)??'{}');
          if(c is Map){for(final e in c.entries){final n=int.tryParse(str(e.value));if(n!=null&&n>0)capacities[str(e.key)]=n;}}
        }catch(_){if(mounted)_notice('Görev veya kapasite verileri okunamadı.');}
        if(ctx.mounted)setSheet(()=>loading=false);
      });}
      final now=DateTime.now(),start=DateTime(now.year,now.month,now.day),end=start.add(Duration(days:days));
      final owners=actions.where(active).map(who).toSet().toList()..sort();
      if(ownerFilter!='Tümü'&&!owners.contains(ownerFilter))ownerFilter='Tümü';
      final tasks=actions.where((a)=>active(a)&&day(a['targetDate'])!=null).toList();
      final allIds=<String,int>{};
      for(final a in actions){final id=identity(a);allIds[id]=(allIds[id]??0)+1;}
      String key(String o,DateTime d)=>'$o::${fmt(d)}';
      Map<String,int> buildLoads(List<Map<String,dynamic>> rows){
        final loads=<String,int>{};
        for(final a in rows){if(!active(a))continue;final d=day(a['targetDate']);if(d==null||d.isBefore(start)||!d.isBefore(end))continue;
          final k=key(who(a),d);loads[k]=(loads[k]??0)+duration(a);
        }return loads;
      }
      final initial=buildLoads(actions);
      int limit(String o)=>capacities[o]??120;
      int excess(Map<String,int> loads)=>loads.entries.fold(0,(sum,e){final o=e.key.split('::').first;return sum+(e.value>limit(o)?e.value-limit(o):0);});
      int overloadCount(Map<String,int> loads)=>loads.entries.where((e)=>e.value>limit(e.key.split('::').first)).length;
      final baselineExcess=excess(initial);
      // Three independently simulated policies. No writes occur while previewing.
      List<Map<String,dynamic>> propose(int policy){
        final loads=Map<String,int>.from(initial),moves=<Map<String,dynamic>>[];
        final candidates=tasks.where((a){final d=day(a['targetDate'])!;return !d.isBefore(start)&&d.isBefore(end)&&
          (ownerFilter=='Tümü'||who(a)==ownerFilter)&&'${a['title']} ${who(a)}'.toLowerCase().contains(query.toLowerCase())&&allIds[identity(a)]==1;
        }).toList()..sort((a,b){
          final da=day(a['targetDate'])!,db=day(b['targetDate'])!;
          final aa=(initial[key(who(a),da)]??0)-limit(who(a));final bb=(initial[key(who(b),db)]??0)-limit(who(b));
          final risk=bb.compareTo(aa);return risk!=0?risk:da.compareTo(db);
        });
        for(final a in candidates){if(moves.length>=maxChanges)break;
          final oldDate=day(a['targetDate'])!,oldOwner=who(a),oldKey=key(oldOwner,oldDate),mins=duration(a);
          if(onlyOverloaded&&(loads[oldKey]??0)<=limit(oldOwner))continue;
          final oldExcess=((loads[oldKey]??0)-limit(oldOwner)).clamp(0,1000000).toInt();
          final choices=<Map<String,dynamic>>[];
          final candidateOwners=policy==0?[oldOwner]:policy==1?[...owners]:[...owners];
          for(final o in candidateOwners){if(o=='Atanmamış'&&oldOwner!='Atanmamış')continue;
            for(var offset=0;offset<days;offset++){
              final d=start.add(Duration(days:offset));
              if(!weekends&&(d.weekday==DateTime.saturday||d.weekday==DateTime.sunday))continue;
              if(o==oldOwner&&d==oldDate)continue;
              if(policy==1&&d!=oldDate)continue; // responsibility-only
              if(policy==2&&o!=oldOwner&&d==oldDate)continue; // date + responsibility
              final k=key(o,d),available=limit(o)-(loads[k]??0);
              if(available<mins)continue;
              final afterOld=((loads[oldKey]??0)-mins-limit(oldOwner)).clamp(0,1000000).toInt();
              final gain=oldExcess-afterOld;
              if(gain<=0)continue;
              final shift=d.difference(oldDate).inDays.abs();
              final score=gain*1000-shift*10-(o==oldOwner?0:15)-(d.isBefore(oldDate)?3:0);
              choices.add({'owner':o,'date':d,'score':score,'gain':gain});
            }
          }
          if(choices.isEmpty)continue;
          choices.sort((a,b)=>(b['score'] as int).compareTo(a['score'] as int));
          final best=choices.first,newOwner=str(best['owner']),newDate=best['date'] as DateTime;
          loads[oldKey]=(loads[oldKey]??0)-mins;
          final newKey=key(newOwner,newDate);loads[newKey]=(loads[newKey]??0)+mins;
          moves.add({'id':identity(a),'title':str(a['title']),'oldOwner':oldOwner,'newOwner':newOwner,
            'oldDate':fmt(oldDate),'newDate':fmt(newDate),'minutes':mins,'gain':best['gain']});
        }
        return moves;
      }
      final scenarios=[propose(0),propose(1),propose(2)];
      Map<String,int> simulated(List<Map<String,dynamic>> moves){
        final loads=Map<String,int>.from(initial);
        for(final m in moves){final old=key(str(m['oldOwner']),day(m['oldDate'])!),next=key(str(m['newOwner']),day(m['newDate'])!),mins=m['minutes'] as int;
          loads[old]=(loads[old]??0)-mins;loads[next]=(loads[next]??0)+mins;
        }return loads;
      }
      final outcomes=scenarios.map(simulated).toList();
      final chosen=scenarios[strategy],result=outcomes[strategy];
      Future<void> apply()async{
        if(chosen.isEmpty){if(mounted)_notice('Uygulanabilecek öneri yok.');return;}
        final approved=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(
          title:const Text('Alternatif planı uygula'),
          content:Text('${chosen.length} açık görevin tarihi veya sorumlusu değişecek. Kapasite aşımı $baselineExcess → ${excess(result)} dakika. Değişiklik öncesi ve sonrası plan sürümü kaydedilecek. Onaylıyor musun?'),
          actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Uygula'))]));
        if(approved!=true)return;
        try{
          final prefs=await SharedPreferences.getInstance();
          final raw=prefs.getString(actionKey)??'[]',decoded=jsonDecode(raw);
          if(decoded is! List)throw StateError('Görev listesi geçersiz');
          final fresh=decoded.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
          final lookup=<String,List<Map<String,dynamic>>>{};
          for(final a in fresh){lookup.putIfAbsent(identity(a),()=>[]).add(a);}
          for(final m in chosen){final matches=lookup[str(m['id'])]??[];
            if(matches.length!=1||!active(matches.single)||who(matches.single)!=str(m['oldOwner'])||
              str(matches.single['targetDate'])!=str(m['oldDate'])||duration(matches.single)!=m['minutes']){
              throw StateError('Görevler değişmiş. Planı yeniden açıp kontrol edin.');
            }
          }
          List<Map<String,dynamic>> snapshot()=>fresh.map((a)=>{'id':identity(a),'title':a['title'],'owner':a['owner'],'targetDate':a['targetDate'],'estimatedMinutes':a['estimatedMinutes'],'status':a['status']}).toList();
          final before=snapshot(),stamp=DateTime.now().toIso8601String();
          for(final m in chosen){final a=lookup[str(m['id'])]!.single;
            a['owner']=m['newOwner'];a['targetDate']=m['newDate'];a['updated']=stamp;
            final history=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];
            history.add({'at':stamp,'event':'Alternatif plan: ${m['oldOwner']} ${m['oldDate']} → ${m['newOwner']} ${m['newDate']}'});
            a['history']=history;
          }
          final oldVersions=prefs.getString(versionKey);
          final decodedVersions=jsonDecode(oldVersions??'[]');
          if(decodedVersions is! List)throw StateError('Plan sürümleri geçersiz');
          final versions=decodedVersions.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
          versions.insert(0,{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':'Alternatif plan • ${['Tarih kaydırma','Sorumlu değiştirme','Karma plan'][strategy]}',
            'note':'${chosen.length} görev; kapasite aşımı $baselineExcess → ${excess(result)} dk',
            'type':'conflict_alternative','at':stamp,'before':before,'after':snapshot()});
          if(!await prefs.setString(actionKey,jsonEncode(fresh)))throw StateError('Görevler kaydedilemedi');
          if(!await prefs.setString(versionKey,jsonEncode(versions.take(100).toList()))){
            await prefs.setString(actionKey,raw);
            throw StateError('Sürüm kaydı başarısız; görev kaydı geri alındı');
          }
          if(ctx.mounted)setSheet((){actions..clear()..addAll(fresh);});
          if(mounted)_notice('${chosen.length} görev güncellendi ve plan sürümü kaydedildi.');
        }catch(e){if(mounted)_notice('Plan uygulanamadı: $e');}
      }
      final report=['Görev;Önceki sorumlu;Yeni sorumlu;Önceki tarih;Yeni tarih;Süre dk;Azalan aşım dk',
        ...chosen.map((m)=>[m['title'],m['oldOwner'],m['newOwner'],m['oldDate'],m['newDate'],m['minutes'],m['gain']].map(csv).join(';'))];
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,
        child:ListView(padding:const EdgeInsets.all(16),children:[
          Row(children:[Expanded(child:Text('Akıllı çakışma çözümü • Alternatif planlar',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Üç kural tabanlı senaryoyu karşılaştır. Plan önerileri yalnızca kayıtlı günlük dakika kapasitesine dayanır; gerçek takvim müsaitliğini doğrulamaz.'),
          if(loading)const LinearProgressIndicator()else ...[
            Wrap(spacing:8,runSpacing:6,children:[for(final n in [7,14,21,28])ChoiceChip(label:Text('$n gün'),selected:days==n,onSelected:(_)=>setSheet(()=>days=n)),
              FilterChip(label:const Text('Hafta sonuna izin ver'),selected:weekends,onSelected:(v)=>setSheet(()=>weekends=v)),
              FilterChip(label:const Text('Yalnız aşırı yüklü'),selected:onlyOverloaded,onSelected:(v)=>setSheet(()=>onlyOverloaded=v))]),
            DropdownButtonFormField<String>(initialValue:ownerFilter,decoration:const InputDecoration(labelText:'Sorumlu'),items:[for(final o in ['Tümü',...owners])DropdownMenuItem(value:o,child:Text(o))],onChanged:(v)=>setSheet(()=>ownerFilter=v??'Tümü')),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev veya sorumlu ara'),onChanged:(v)=>setSheet(()=>query=v)),
            Wrap(spacing:8,children:[for(final n in [5,10,15,25,50])ChoiceChip(label:Text('En fazla $n'),selected:maxChanges==n,onSelected:(_)=>setSheet(()=>maxChanges=n))]),
            Card(child:ListTile(title:Text('Mevcut kapasite aşımı: $baselineExcess dk'),subtitle:Text('Aşırı yüklü sorumlu-gün: ${overloadCount(initial)} • Planlanan aktif görev: ${tasks.length}\nVarsayılan kapasite: 120 dk / sorumlu / gün'))),
            for(var i=0;i<3;i++)Card(child:RadioGroup<int>(groupValue:strategy,onChanged:(v)=>setSheet(()=>strategy=v??0),child:RadioListTile<int>(value:i,
              title:Text(['Yalnız tarih değiştir','Yalnız sorumlu değiştir','Tarih + sorumlu alternatifleri'][i]),
              subtitle:Text('${scenarios[i].length} öneri • Aşım ${excess(outcomes[i])} dk • ${overloadCount(outcomes[i])} aşırı yüklü sorumlu-gün')))),
            Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Seçilen senaryo • ${chosen.length} değişiklik',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Kapasite aşımı: $baselineExcess → ${excess(result)} dk (fark: ${excess(result)-baselineExcess} dk)'),
              Text('Aşırı yüklü sorumlu-gün: ${overloadCount(initial)} → ${overloadCount(result)}'),
              LinearProgressIndicator(value:baselineExcess==0?1:(1-excess(result)/baselineExcess).clamp(0.0,1.0)),
            ]))),
            if(chosen.isEmpty)const Card(child:ListTile(title:Text('Uygun alternatif bulunamadı'),subtitle:Text('Dönemi, hafta sonu ayarını veya günlük kapasiteyi gözden geçirebilirsin.'))),
            for(final m in chosen.take(50))Card(child:ListTile(dense:true,leading:const Icon(Icons.swap_horiz),title:Text(str(m['title'])),
              subtitle:Text('${m['oldOwner']} • ${m['oldDate']} → ${m['newOwner']} • ${m['newDate']}\n${m['minutes']} dk • Yerel aşım azalması: ${m['gain']} dk'),isThreeLine:true)),
            Wrap(spacing:8,runSpacing:8,children:[FilledButton.icon(onPressed:chosen.isEmpty?null:apply,icon:const Icon(Icons.check_circle_outline),label:Text('${chosen.length} öneriyi onayla ve uygula')),
              OutlinedButton.icon(onPressed:chosen.isEmpty?null:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('Öneri CSV raporu kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('CSV kopyala')),
              OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenSmartRestoreSimulator();},icon:const Icon(Icons.restore),label:const Text('Geri alma simülasyonu'))]),
            const Text('Güvenlik: kapalı görevler değiştirilmez; kimlik çakışması olan görevler önerilmez. Kayıt öncesi değişiklikler yeniden doğrulanır. Geçmiş plan sürümleri korunur.'),
          ],
        ]))));
    }));
  }

  void _showKitchenSmartRestoreSimulator() {
    const versionKey='paket40_optimization_plan_versions_v1';
    const actionKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final versions=<Map<String,dynamic>>[],actions=<Map<String,dynamic>>[];
    final capacity=<String,int>{};
    final selected=<String>{};
    bool started=false,loading=true,onlyRisk=false,onlyChanged=true;
    int chosen=0,window=14;
    String search='',target='before';
    String txt(Object? x)=>'${x??''}';
    String identity(Map<String,dynamic> a)=>'${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
    DateTime? parse(Object? v)=>DateTime.tryParse(txt(v));
    String date(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    DateTime? day(Object? x){final d=parse(x);return d==null?null:DateTime(d.year,d.month,d.day);}
    int minutes(Object? x){final n=int.tryParse(txt(x));return n!=null&&n>=5&&n<=1440?n:30;}
    String owner(Map<String,dynamic> a){final s=txt(a['owner']).trim();return s.isEmpty?'Atanmamış':s;}
    String csv(Object? x)=>'"${txt(x).replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((prefs){try{
        final v=jsonDecode(prefs.getString(versionKey)??'[]');
        if(v is List)versions.addAll(v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
        final a=jsonDecode(prefs.getString(actionKey)??'[]');
        if(a is List)actions.addAll(a.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
        final c=jsonDecode(prefs.getString(capacityKey)??'{}');
        if(c is Map){for(final e in c.entries){final n=int.tryParse(txt(e.value));if(n!=null&&n>0)capacity[txt(e.key)]=n;}}
      }catch(_){if(mounted)_notice('Plan verileri okunamadı.');}if(ctx.mounted)refresh(()=>loading=false);});}
      final ordered=[...versions]..sort((a,b)=>txt(b['at']).compareTo(txt(a['at'])));
      final version=chosen<ordered.length?ordered[chosen]:null;
      final raw=version?[target];
      final saved=<String,Map<String,dynamic>>{};
      if(raw is List){for(final r in raw){if(r is Map){final a=Map<String,dynamic>.from(r);final id=txt(a['id']);if(id.isNotEmpty)saved[id]=a;}}}
      final indexed=<String,List<Map<String,dynamic>>>{};
      for(final a in actions){indexed.putIfAbsent(identity(a),()=>[]).add(a);}
      final rows=<Map<String,dynamic>>[];
      for(final e in saved.entries){final matches=indexed[e.key]??[];final current=matches.length==1?matches.single:null;
        final old=e.value;
        final changed=current!=null&&(txt(current['owner'])!=txt(old['owner'])||txt(current['targetDate'])!=txt(old['targetDate']));
        final closed=current!=null&&['Tamamlandı','İptal'].contains(txt(current['status']));
        final reason=matches.isEmpty?'Görev silinmiş':matches.length>1?'Kimlik çakışması':closed?'Kapalı görev':day(old['targetDate'])==null?'Hedef tarihi geçersiz':'Uygulanabilir';
        rows.add({'id':e.key,'saved':old,'current':current,'changed':changed,'reason':reason,'safe':reason=='Uygulanabilir','title':txt(current?['title']??old['title'])});
      }
      final validIds=rows.where((r)=>r['safe']==true&&r['changed']==true).map((r)=>txt(r['id'])).toSet();
      selected.removeWhere((id)=>!validIds.contains(id));
      final today=DateTime.now(),start=DateTime(today.year,today.month,today.day);
      final end=start.add(Duration(days:window));
      Map<String,int> loads(bool proposed){final out=<String,int>{};
        for(final a in actions){if(['Tamamlandı','İptal'].contains(txt(a['status'])))continue;
          final id=identity(a);final row=saved[id];final apply=proposed&&selected.contains(id)&&row!=null;
          final d=day(apply?row['targetDate']:a['targetDate']);if(d==null||d.isBefore(start)||!d.isBefore(end))continue;
          final o=apply?owner(row):owner(a);
          final k='$o::${date(d)}';out[k]=(out[k]??0)+minutes(a['estimatedMinutes']);
        }return out;
      }
      final before=loads(false),after=loads(true);
      int excess(Map<String,int> l)=>l.entries.fold(0,(n,e){final o=e.key.split('::').first;final c=capacity[o]??120;return n+(e.value>c?e.value-c:0);});
      int overDays(Map<String,int> l)=>l.entries.where((e)=>e.value>(capacity[e.key.split('::').first]??120)).length;
      final allKeys=<String>{...before.keys,...after.keys}.toList()..sort();
      final shown=rows.where((r)=>(!onlyChanged||r['changed']==true)&&(!onlyRisk||r['safe']!=true)&&'${r['title']} ${r['reason']}'.toLowerCase().contains(search.toLowerCase())).toList();
      final risk=rows.where((r)=>r['safe']!=true).length;
      final report=<String>['Görev;Durum;Mevcut sorumlu;Hedef sorumlu;Mevcut tarih;Hedef tarih;Seçili'];
      for(final r in shown){final a=r['current'] as Map<String,dynamic>?,b=r['saved'] as Map<String,dynamic>;
        report.add([r['title'],r['reason'],a?['owner'],b['owner'],a?['targetDate'],b['targetDate'],selected.contains(txt(r['id']))?'Evet':'Hayır'].map(csv).join(';'));
      }
      Future<void> apply()async{
        if(selected.isEmpty){if(mounted)_notice('Önce uygulanacak görevleri seç.');return;}
        final count=selected.length;
        final approved=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Seçili görevleri geri yükle'),content:Text('$count açık görevin sorumlusu ve tarihi değiştirilecek. Kapasite aşımı: ${excess(before)} → ${excess(after)} dk. Bu işlem için yeni bir geri alma sürümü oluşturulacak. Devam edilsin mi?'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla'))]));
        if(approved!=true)return;
        try{
          final prefs=await SharedPreferences.getInstance();
          // Onay ile kayıt arasındaki değişiklikleri denetle; eski ekran verisiyle üzerine yazma.
          final latest=jsonDecode(prefs.getString(actionKey)??'[]');
          if(latest is! List)throw StateError('Görev listesi geçersiz');
          final fresh=latest.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
          final freshIndex=<String,List<Map<String,dynamic>>>{};
          for(final a in fresh){freshIndex.putIfAbsent(identity(a),()=>[]).add(a);}
          final picked=rows.where((r)=>selected.contains(txt(r['id']))).toList();
          for(final r in picked){final matches=freshIndex[txt(r['id'])]??[];final prior=r['current'] as Map<String,dynamic>?;
            if(matches.length!=1||prior==null||['Tamamlandı','İptal'].contains(txt(matches.single['status']))||txt(matches.single['owner'])!=txt(prior['owner'])||txt(matches.single['targetDate'])!=txt(prior['targetDate']))throw StateError('Görevler değişmiş. Yeniden açıp kontrol edin.');
          }
          List<Map<String,dynamic>> snapshot()=>fresh.map((a)=>{'id':identity(a),'owner':a['owner'],'targetDate':a['targetDate'],'estimatedMinutes':a['estimatedMinutes'],'status':a['status'],'title':a['title']}).toList();
          final previous=snapshot();final stamp=DateTime.now().toIso8601String();
          for(final r in picked){final a=freshIndex[txt(r['id'])]!.single,b=r['saved'] as Map<String,dynamic>;
            final oldOwner=txt(a['owner']),oldDate=txt(a['targetDate']);
            a['owner']=b['owner'];a['targetDate']=b['targetDate'];a['updated']=stamp;
            final history=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];
            history.add({'at':stamp,'event':'Seçmeli plan geri alma: $oldOwner $oldDate → ${b['owner']} ${b['targetDate']}'});a['history']=history;
          }
          final audit={'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':'Seçmeli geri alma • ${version?['name']??''}','note':'$count görev; simülasyon: ${excess(before)} → ${excess(after)} dk','type':'selective_restore','at':stamp,'before':previous,'after':snapshot()};
          final newVersions=[audit,...ordered].take(100).toList();
          final original=prefs.getString(actionKey);
          if(!await prefs.setString(actionKey,jsonEncode(fresh)))throw StateError('Görev kaydı başarısız');
          if(!await prefs.setString(versionKey,jsonEncode(newVersions))){if(original!=null)await prefs.setString(actionKey,original);throw StateError('Sürüm kaydı başarısız');}
          if(ctx.mounted)refresh((){actions..clear()..addAll(fresh);versions..clear()..addAll(newVersions);chosen=0;selected.clear();});
          if(mounted)_notice('$count görev geri yüklendi ve yeni plan sürümü kaydedildi.');
        }catch(e){if(mounted)_notice('Geri alma tamamlanamadı: $e');}
      }
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Akıllı geri alma • Simülasyon ve çakışma çözümü',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Görevleri tek tek seç, mevcut kapasite etkisini gör, onayla ve yeni sürüm oluştur. Tahminler yalnızca planlanan dakikaları kullanır.'),
        if(loading)const LinearProgressIndicator()else if(ordered.isEmpty)const Card(child:ListTile(title:Text('Kayıtlı plan sürümü yok'),subtitle:Text('Önce Plan Sürümleri ekranından bir sürüm oluştur.')))else ...[
          DropdownButtonFormField<int>(initialValue:chosen<ordered.length?chosen:0,decoration:const InputDecoration(labelText:'Kaynak plan sürümü'),items:[for(var i=0;i<ordered.length;i++)DropdownMenuItem(value:i,child:Text('${ordered[i]['name']??'Plan'} • ${txt(ordered[i]['at']).split('T').first}',overflow:TextOverflow.ellipsis))],onChanged:(v)=>refresh((){chosen=v??0;selected.clear();})),
          Wrap(spacing:8,children:[ChoiceChip(label:const Text('Önceki plan'),selected:target=='before',onSelected:(_)=>refresh((){target='before';selected.clear();})),ChoiceChip(label:const Text('Sonraki plan'),selected:target=='after',onSelected:(_)=>refresh((){target='after';selected.clear();})),for(final n in [7,14,28,60])ChoiceChip(label:Text('$n gün'),selected:window==n,onSelected:(_)=>refresh(()=>window=n))]),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Toplam ${rows.length} görev • ${validIds.length} değişiklik • $risk çakışma • ${selected.length} seçili'),Text('Kapasite aşımı: ${excess(before)} → ${excess(after)} dk (${excess(after)-excess(before)>=0?'+':''}${excess(after)-excess(before)} dk)'),Text('Aşırı yüklü sorumlu-gün: ${overDays(before)} → ${overDays(after)}'),Text('Karşılaştırma: bugünden itibaren $window gün • Varsayılan kapasite: 120 dk/gün')]))),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev veya çakışma ara'),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:8,children:[FilterChip(label:const Text('Yalnız değişenler'),selected:onlyChanged,onSelected:(v)=>refresh(()=>onlyChanged=v)),FilterChip(label:const Text('Yalnız çakışmalar'),selected:onlyRisk,onSelected:(v)=>refresh(()=>onlyRisk=v)),ActionChip(label:const Text('Uygunların tümünü seç'),onPressed:()=>refresh(()=>selected.addAll(validIds))),ActionChip(label:const Text('Seçimi temizle'),onPressed:()=>refresh(()=>selected.clear()))]),
          for(final r in shown.take(150))Builder(builder:(ctx){final a=r['current'] as Map<String,dynamic>?,b=r['saved'] as Map<String,dynamic>;final id=txt(r['id']),safe=r['safe']==true&&r['changed']==true;
            return Card(child:CheckboxListTile(value:selected.contains(id),onChanged:safe?(v)=>refresh((){if(v==true){selected.add(id);}else{selected.remove(id);}}):null,title:Text(txt(r['title'])),subtitle:Text('${r['reason']}\n${a==null?'—':owner(a)} • ${txt(a?['targetDate'])}  →  ${owner(b)} • ${txt(b['targetDate'])}'),isThreeLine:true));
          }),
          if(shown.length>150)Text('İlk 150 kayıt gösteriliyor (${shown.length} eşleşme). Aramayla daraltabilirsin.'),
          const Divider(),const Text('Seçilen görevlerin günlük kapasite etkisi',style:TextStyle(fontWeight:FontWeight.bold)),
          for(final k in allKeys.where((k)=>(before[k]??0)!=(after[k]??0)).take(35))ListTile(dense:true,title:Text(k.replaceAll('::',' • ')),subtitle:Text('${before[k]??0} → ${after[k]??0} dk / kapasite ${capacity[k.split('::').first]??120} dk')),
          Wrap(spacing:8,runSpacing:8,children:[FilledButton.icon(onPressed:selected.isEmpty?null:apply,icon:const Icon(Icons.restore),label:Text('Seçili ${selected.length} görevi onayla ve uygula')),OutlinedButton.icon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('Simülasyon CSV kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('CSV kopyala')),OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationVersions();},icon:const Icon(Icons.history),label:const Text('Plan sürümlerine geç'))]),
          const Text('Not: Çakışmalı, kapalı veya silinmiş görevler uygulanamaz. Kapasite analizi gerçek müsaitlik değil, kayıtlı günlük dakika ve tahmini görev sürelerine dayanır.'),
        ],
      ]))));
    }));
  }

  void _showKitchenVersionDeepComparison() {
    const versionKey='paket40_optimization_plan_versions_v1';
    const actionKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final versions=<Map<String,dynamic>>[];
    final actions=<Map<String,dynamic>>[];
    final capacities=<String,int>{};
    bool loading=true,started=false,onlyChanged=true,onlyConflicts=false;
    int left=0,right=-1,defaultCapacity=120;
    String search='',sort='Değişenler önce';
    String txt(Object? x)=>'${x??''}';
    String csv(Object? x)=>'"${txt(x).replaceAll('"','""')}"';
    String identity(Map<String,dynamic> a)=>'${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
    DateTime? parse(Object? v)=>DateTime.tryParse(txt(v));
    String day(Object? v){final d=parse(v);if(d==null)return '—';return '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';}
    int minutes(Object? v){final n=int.tryParse(txt(v));return n!=null&&n>=5&&n<=1440?n:30;}
    String owner(Map<String,dynamic> r){final s=txt(r['owner']).trim();return s.isEmpty?'Atanmamış':s;}
    Map<String,Map<String,dynamic>> rows(Map<String,dynamic>? v){
      final result=<String,Map<String,dynamic>>{};
      if(v==null)return result;
      final source=v['after'] is List?v['after'] as List:const [];
      for(final raw in source){if(raw is! Map)continue;final a=Map<String,dynamic>.from(raw),id=txt(a['id']);if(id.isNotEmpty)result[id]=a;}
      return result;
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((p){try{
        final v=jsonDecode(p.getString(versionKey)??'[]');if(v is List)versions.addAll(v.whereType<Map>().map((x)=>Map<String,dynamic>.from(x)));
        final a=jsonDecode(p.getString(actionKey)??'[]');if(a is List)actions.addAll(a.whereType<Map>().map((x)=>Map<String,dynamic>.from(x)));
        final c=jsonDecode(p.getString(capacityKey)??'{}');if(c is Map){for(final e in c.entries){final n=int.tryParse(txt(e.value));if(n!=null&&n>0)capacities[txt(e.key)]=n;}}
      }catch(_){if(mounted)_notice('Sürüm karşılaştırma verileri okunamadı.');}if(ctx.mounted)refresh(()=>loading=false);});}
      final ordered=[...versions]..sort((a,b)=>txt(b['at']).compareTo(txt(a['at'])));
      final leftVersion=left>=0&&left<ordered.length?ordered[left]:null;
      final rightVersion=right>=0&&right<ordered.length?ordered[right]:null;
      final before=rows(leftVersion);
      final after=right==-1?<String,Map<String,dynamic>>{for(final a in actions)identity(a):a}:rows(rightVersion);
      final allIds=<String>{...before.keys,...after.keys};
      final current=<String,List<Map<String,dynamic>>>{};
      for(final a in actions){current.putIfAbsent(identity(a),()=>[]).add(a);}
      final changes=<Map<String,dynamic>>[];
      final beforeLoads=<String,int>{},afterLoads=<String,int>{};
      void addLoad(Map<String,int> loads,Map<String,dynamic> r){
        final d=day(r['targetDate']);if(d=='—')return;
        if(['Tamamlandı','İptal'].contains(txt(r['status'])))return;
        final key='${owner(r)}::$d';loads[key]=(loads[key]??0)+minutes(r['estimatedMinutes']);
      }
      for(final id in allIds){final b=before[id],a=after[id];if(b!=null)addLoad(beforeLoads,b);if(a!=null)addLoad(afterLoads,a);
        final changed=b==null||a==null||owner(b)!=owner(a)||day(b['targetDate'])!=day(a['targetDate'])||minutes(b['estimatedMinutes'])!=minutes(a['estimatedMinutes']);
        final matches=current[id]??[];
        final conflict=matches.length!=1||['Tamamlandı','İptal'].contains(txt(matches.single['status']));
        final reason=matches.isEmpty?'Mevcut görev bulunamadı':matches.length>1?'Birden fazla görev eşleşiyor':conflict?'Görev kapalı':'Uygulanabilir';
        changes.add({'id':id,'before':b,'after':a,'changed':changed,'conflict':conflict,'reason':reason,'title':txt(a?['title']??b?['title']??id)});
      }
      int cap(String key)=>capacities[key.split('::').first]??defaultCapacity;
      int overDays(Map<String,int> loads)=>loads.entries.where((e)=>e.value>cap(e.key)).length;
      int excess(Map<String,int> loads)=>loads.entries.fold(0,(sum,e)=>sum+(e.value>cap(e.key)?e.value-cap(e.key):0));
      final shown=changes.where((r)=>(!onlyChanged||r['changed']==true)&&(!onlyConflicts||r['conflict']==true)&&'${r['title']} ${r['id']} ${r['reason']}'.toLowerCase().contains(search.toLowerCase())).toList();
      shown.sort((a,b){if(sort=='Görev adı')return txt(a['title']).compareTo(txt(b['title']));if(sort=='Çakışmalar önce'){final c=(b['conflict']==true?1:0).compareTo(a['conflict']==true?1:0);if(c!=0)return c;}return (b['changed']==true?1:0).compareTo(a['changed']==true?1:0);});
      final totalBefore=beforeLoads.values.fold<int>(0,(a,b)=>a+b),totalAfter=afterLoads.values.fold<int>(0,(a,b)=>a+b);
      final report=<String>['Görev,Önceki sorumlu,Önceki tarih,Önceki dakika,Sonraki sorumlu,Sonraki tarih,Sonraki dakika,Değişti,Çakışma,Durum'];
      for(final r in shown){final b=r['before'] as Map<String,dynamic>?,a=r['after'] as Map<String,dynamic>?;report.add([r['title'],b==null?'':owner(b),b==null?'':day(b['targetDate']),b==null?'':minutes(b['estimatedMinutes']),a==null?'':owner(a),a==null?'':day(a['targetDate']),a==null?'':minutes(a['estimatedMinutes']),r['changed'],r['conflict'],r['reason']].map(csv).join(','));}
      Widget metric(String title,String value)=>Card(color:const Color(0xFFFFF1FA),child:ListTile(dense:true,title:Text(title),trailing:Text(value,style:const TextStyle(fontWeight:FontWeight.bold))));
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Plan sürümleri • Ayrıntılı karşılaştırma ve geri alma önizlemesi',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('İki kayıtlı planı veya bir planı mevcut görevlerle karşılaştır. Önizleme kayıtları değiştirmez. Geri alma işlemleri mevcut Plan Sürümleri ekranından onaylanır.'),
        if(loading)const LinearProgressIndicator()else if(ordered.isEmpty)const Card(child:ListTile(title:Text('Henüz kayıtlı plan sürümü yok.'),subtitle:Text('Önce Plan Sürümleri ekranından anlık görüntü oluştur.')))else ...[
          DropdownButtonFormField<int>(initialValue:left,decoration:const InputDecoration(labelText:'Başlangıç sürümü'),isExpanded:true,items:[for(var i=0;i<ordered.length;i++)DropdownMenuItem(value:i,child:Text('${ordered[i]['name']} • ${day(ordered[i]['at'])}',overflow:TextOverflow.ellipsis))],onChanged:(v)=>refresh(()=>left=v??0)),
          const SizedBox(height:8),
          DropdownButtonFormField<int>(initialValue:right,decoration:const InputDecoration(labelText:'Karşılaştırılacak plan'),isExpanded:true,items:[const DropdownMenuItem(value:-1,child:Text('Mevcut görev planı')),for(var i=0;i<ordered.length;i++)DropdownMenuItem(value:i,child:Text('${ordered[i]['name']} • ${day(ordered[i]['at'])}',overflow:TextOverflow.ellipsis))],onChanged:(v)=>refresh(()=>right=v??-1)),
          Wrap(spacing:8,children:[ChoiceChip(label:const Text('120 dk varsayılan'),selected:defaultCapacity==120,onSelected:(_)=>refresh(()=>defaultCapacity=120)),ChoiceChip(label:const Text('180 dk varsayılan'),selected:defaultCapacity==180,onSelected:(_)=>refresh(()=>defaultCapacity=180)),ChoiceChip(label:const Text('240 dk varsayılan'),selected:defaultCapacity==240,onSelected:(_)=>refresh(()=>defaultCapacity=240))]),
          metric('Karşılaştırılan görev','${allIds.length}'),metric('Değişen görev','${changes.where((r)=>r['changed']==true).length}'),metric('Eşleşme / kapalı görev çakışması','${changes.where((r)=>r['conflict']==true).length}'),
          metric('Planlanan toplam süre','$totalBefore → $totalAfter dk'),metric('Aşırı yüklü sorumlu-gün','${overDays(beforeLoads)} → ${overDays(afterLoads)}'),metric('Kapasite aşımı','${excess(beforeLoads)} → ${excess(afterLoads)} dk'),
          const Text('Kapasite hesabı, sürümlerdeki açık görevler ile kaydedilmiş günlük dakika limitlerine dayanır. Eski sürümlerde durum/süre bilgisi eksikse sonuçlar yaklaşık olabilir.'),
          TextField(decoration:const InputDecoration(labelText:'Görev veya çakışma ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:10,children:[DropdownButton<String>(value:sort,items:['Değişenler önce','Çakışmalar önce','Görev adı'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'Değişenler önce'))]),
          SwitchListTile(title:const Text('Yalnızca değişen görevler'),value:onlyChanged,onChanged:(v)=>refresh(()=>onlyChanged=v)),
          SwitchListTile(title:const Text('Yalnızca çakışmalar'),value:onlyConflicts,onChanged:(v)=>refresh(()=>onlyConflicts=v)),
          for(final r in shown.take(150))Builder(builder:(_){final b=r['before'] as Map<String,dynamic>?,a=r['after'] as Map<String,dynamic>?;return Card(child:ListTile(leading:Icon(r['conflict']==true?Icons.warning_amber_outlined:r['changed']==true?Icons.compare_arrows:Icons.check_circle_outline,color:r['conflict']==true?Colors.deepOrange:null),title:Text(txt(r['title'])),subtitle:Text('Önce: ${b==null?'Sürümde yok':'${owner(b)} • ${day(b['targetDate'])} • ${minutes(b['estimatedMinutes'])} dk'}\nSonra: ${a==null?'Sürümde yok':'${owner(a)} • ${day(a['targetDate'])} • ${minutes(a['estimatedMinutes'])} dk'}\n${r['reason']}')));}),
          if(shown.isEmpty)const ListTile(title:Text('Bu filtreye uygun görev bulunamadı.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('${shown.length} görev karşılaştırması kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Karşılaştırmayı CSV olarak kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationVersions();},icon:const Icon(Icons.restore_outlined),label:const Text('Plan sürümleri / onaylı geri alma ekranına geç')),
        ]
      ])));
    }));
  }

  void _showKitchenOptimizationVersions() {
    const versionsKey='paket40_optimization_plan_versions_v1';
    const actionKey='paket39_purchase_improvement_actions_v1';
    final versions=<Map<String,dynamic>>[];
    final actions=<Map<String,dynamic>>[];
    bool started=false,loading=true,onlyChanged=false;
    String search='',sort='En yeni';
    int limit=50;
    String txt(Object? v)=>'${v??''}';
    String csv(Object? v)=>'"${txt(v).replaceAll('"','""')}"';
    String identity(Map<String,dynamic> a)=>'${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
    String dateText(Object? v){final d=DateTime.tryParse(txt(v));return d==null?'—':'${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';}
    Future<void> reload(StateSetter refresh,BuildContext ctx)async{
      try{final prefs=await SharedPreferences.getInstance();
        final v=jsonDecode(prefs.getString(versionsKey)??'[]');
        final a=jsonDecode(prefs.getString(actionKey)??'[]');
        versions..clear()..addAll(v is List?v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)):const <Map<String,dynamic>>[]);
        actions..clear()..addAll(a is List?a.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)):const <Map<String,dynamic>>[]);
      }catch(_){if(mounted)_notice('Plan sürümleri okunamadı.');}
      if(ctx.mounted)refresh(()=>loading=false);
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;reload(refresh,ctx);}
      final shown=versions.where((v)=>'${v['name']} ${v['at']} ${v['note']}'.toLowerCase().contains(search.toLowerCase())).toList();
      shown.sort((a,b)=>sort=='En eski'?txt(a['at']).compareTo(txt(b['at'])):txt(b['at']).compareTo(txt(a['at'])));
      int changed(Map<String,dynamic> v){final b=v['before'] is List?v['before'] as List:const [];final a=v['after'] is List?v['after'] as List:const [];var n=0;for(var i=0;i<b.length&&i<a.length;i++){if(jsonEncode(b[i])!=jsonEncode(a[i]))n++;}return n;}
      final filtered=onlyChanged?shown.where((v)=>changed(v)>0).toList():shown;
      Future<void> capture()async{
        final title=TextEditingController(text:'Manuel plan • ${DateTime.now().day}.${DateTime.now().month}');
        final note=TextEditingController();
        final ok=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Plan sürümünü kaydet'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,maxLength:80,decoration:const InputDecoration(labelText:'Sürüm adı')),TextField(controller:note,maxLines:2,maxLength:250,decoration:const InputDecoration(labelText:'Not (isteğe bağlı)')),Text('${actions.length} görev için planın anlık görüntüsü saklanacak.')])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        final name=title.text.trim(),memo=note.text.trim();disposeAfterDialog(title);disposeAfterDialog(note);
        if(ok!=true||name.isEmpty)return;
        final state=actions.map((a)=>{'id':identity(a),'owner':txt(a['owner']),'targetDate':txt(a['targetDate']),'estimatedMinutes':a['estimatedMinutes'],'status':txt(a['status']),'title':txt(a['title'])}).toList();
        final record=<String,dynamic>{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':name,'note':memo,'at':DateTime.now().toIso8601String(),'before':state,'after':state,'type':'manual'};
        try{final prefs=await SharedPreferences.getInstance();final next=[record,...versions].take(100).toList();await prefs.setString(versionsKey,jsonEncode(next));if(ctx.mounted)refresh(()=>versions..clear()..addAll(next));if(mounted)_notice('Plan sürümü kaydedildi.');}catch(_){if(mounted)_notice('Sürüm kaydedilemedi.');}
      }
      Future<void> restore(Map<String,dynamic> version,bool before)async{
        final rows=version[before?'before':'after'];if(rows is! List)return;
        final changes=<Map<String,dynamic>>[];var missing=0,conflicts=0;
        for(final raw in rows){if(raw is! Map)continue;final row=Map<String,dynamic>.from(raw);final matches=actions.where((a)=>identity(a)==txt(row['id'])).toList();
          if(matches.length!=1){missing++;continue;}
          final a=matches.single;
          if(['Tamamlandı','İptal'].contains(txt(a['status']))){conflicts++;continue;}
          if(txt(a['owner'])!=txt(row['owner'])||txt(a['targetDate'])!=txt(row['targetDate']))changes.add({'action':a,'row':row});
        }
        if(changes.isEmpty){if(mounted)_notice('Geri alınabilecek farklı açık görev yok. Eksik: $missing, kapalı: $conflicts.');return;}
        final approved=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Plan sürümüne geri dön'),content:Text('${changes.length} açık görevin sorumlusu ve hedef tarihi değişecek. $missing eşleşmeyen, $conflicts kapalı görev atlanacak. Diğer görev alanları ve geçmiş korunacak. Devam edilsin mi?'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('İptal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla'))]));
        if(approved!=true)return;
        final old=jsonEncode(actions);final stamp=DateTime.now().toIso8601String();
        for(final c in changes){final a=c['action'] as Map<String,dynamic>,row=c['row'] as Map<String,dynamic>;final prev='${a['owner']??''} ${a['targetDate']??''}';a['owner']=row['owner'];a['targetDate']=row['targetDate'];a['updated']=stamp;final history=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];history.add({'at':stamp,'event':'Plan sürümünden geri yükleme (${version['name']}): $prev → ${row['owner']} ${row['targetDate']}'});a['history']=history;}
        try{final prefs=await SharedPreferences.getInstance();final ok=await prefs.setString(actionKey,jsonEncode(actions));if(!ok)throw StateError('Kayıt başarısız');
          final audit=<String,dynamic>{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':'Geri yükleme • ${version['name']}','at':stamp,'note':'${changes.length} görev geri yüklendi','type':'restore','before':(jsonDecode(old) as List).whereType<Map>().map((a)=>{'id':identity(Map<String,dynamic>.from(a)),'owner':a['owner'],'targetDate':a['targetDate'],'title':a['title']}).toList(),'after':actions.map((a)=>{'id':identity(a),'owner':a['owner'],'targetDate':a['targetDate'],'title':a['title']}).toList()};
          final next=[audit,...versions].take(100).toList();await prefs.setString(versionsKey,jsonEncode(next));if(ctx.mounted)refresh(()=>versions..clear()..addAll(next));if(mounted)_notice('${changes.length} görev için plan geri yüklendi.');
        }catch(_){actions..clear()..addAll((jsonDecode(old) as List).whereType<Map>().map((a)=>Map<String,dynamic>.from(a)));if(mounted)_notice('Geri yükleme kaydedilemedi.');}
      }
      Future<void> remove(Map<String,dynamic> version)async{final ok=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Sürümü sil'),content:Text('"${version['name']}" sürüm kaydı silinsin mi? Görevler değişmez.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Sil'))]));if(ok!=true)return;try{final prefs=await SharedPreferences.getInstance();final next=versions.where((v)=>v['id']!=version['id']).toList();await prefs.setString(versionsKey,jsonEncode(next));if(ctx.mounted)refresh(()=>versions..clear()..addAll(next));}catch(_){if(mounted)_notice('Sürüm silinemedi.');}}
      final report=<String>['Sürüm,Tarih,Tür,Değişen görev,Not'];for(final v in filtered){report.add([v['name'],v['at'],v['type'],changed(v),v['note']].map(csv).join(','));}
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Optimizasyon geçmişi • Plan sürümleri ve geri alma',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Plan sürümleri bu cihazda saklanır. Geri alma yalnızca eşleşen, açık görevlerin sorumlu ve hedef tarihini değiştirir; geçmişi silmez. Silinen veya tamamlanan görevler geri getirilmez.'),
        if(loading)const LinearProgressIndicator()else ...[
          Card(color:const Color(0xFFFFF1FA),child:ListTile(title:Text('${versions.length} kayıtlı sürüm'),subtitle:Text('${actions.length} mevcut görev • En fazla 100 sürüm saklanır.'))),
          FilledButton.icon(onPressed:capture,icon:const Icon(Icons.save_outlined),label:const Text('Mevcut planın sürümünü kaydet')),
          TextField(decoration:const InputDecoration(labelText:'Sürüm adı veya notunda ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:8,children:[DropdownButton<String>(value:sort,items:['En yeni','En eski'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'En yeni')),DropdownButton<int>(value:limit,items:[20,50,100].map((v)=>DropdownMenuItem(value:v,child:Text('İlk $v'))).toList(),onChanged:(v)=>refresh(()=>limit=v??50))]),
          SwitchListTile(title:const Text('Yalnızca değişiklik içeren sürümler'),value:onlyChanged,onChanged:(v)=>refresh(()=>onlyChanged=v)),
          for(final v in filtered.take(limit))Card(child:ExpansionTile(title:Text(txt(v['name'])),subtitle:Text('${dateText(v['at'])} • ${changed(v)} farklı kayıt • ${v['type']=='manual'?'Manuel':'Optimizasyon / geri yükleme'}'),children:[
            if(txt(v['note']).isNotEmpty)ListTile(title:Text(txt(v['note']))),
            if(v['before'] is List&&v['after'] is List)for(var i=0;i<(v['before'] as List).length&&i<(v['after'] as List).length&&i<100;i++)if((v['before'] as List)[i] is Map&&(v['after'] as List)[i] is Map)Builder(builder:(_){final b=(v['before'] as List)[i] as Map,a=(v['after'] as List)[i] as Map;return ListTile(dense:true,title:Text(txt(a['title']??b['title'])),subtitle:Text('${b['owner']} • ${b['targetDate']} → ${a['owner']} • ${a['targetDate']}'));}),
            Wrap(spacing:8,children:[TextButton.icon(onPressed:()=>restore(v,true),icon:const Icon(Icons.restore),label:const Text('Önceki plana dön')),TextButton.icon(onPressed:()=>restore(v,false),icon:const Icon(Icons.redo),label:const Text('Sonraki planı uygula')),TextButton.icon(onPressed:()=>remove(v),icon:const Icon(Icons.delete_outline),label:const Text('Sil'))])
          ])),
          if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('Bu filtreye uygun plan sürümü yok. İlk sürümünüzü kaydedebilirsiniz.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('Plan sürümleri CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Sürüm listesini CSV kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenOptimizationComparison();},icon:const Icon(Icons.compare_arrows),label:const Text('Optimizasyon karşılaştırmasına geç')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenBatchWeekOptimizer();},icon:const Icon(Icons.auto_fix_high),label:const Text('Toplu optimizasyona geç')),
        ]
      ])));
    }));
  }

  void _showKitchenOptimizationComparison() {
    const actionKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final actions=<Map<String,dynamic>>[];
    final capacities=<String,int>{};
    bool started=false,loading=true,onlyMoved=false,onlyImproved=false;
    int days=28,defaultCapacity=120;
    String search='',ownerFilter='Tümü',sort='En yeni';
    DateTime anchor=DateTime.now();
    DateTime? date(Object? value)=>DateTime.tryParse('${value??''}');
    DateTime day(DateTime d)=>DateTime(d.year,d.month,d.day);
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    String owner(Map<String,dynamic> a)=>'${a['owner']??''}'.trim().isEmpty?'Atanmamış':'${a['owner']}';
    int minutes(Map<String,dynamic> a){final n=int.tryParse('${a['estimatedMinutes']??''}');return n!=null&&n>=5&&n<=1440?n:30;}
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains('${a['status']??'Açık'}');
    String group(String who,DateTime d)=>'$who::${iso(d)}';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((p){try{
        final raw=jsonDecode(p.getString(actionKey)??'[]');
        if(raw is List)actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
        final caps=jsonDecode(p.getString(capacityKey)??'{}');
        if(caps is Map){for(final e in caps.entries){final n=int.tryParse('${e.value}');if(n!=null&&n>=15&&n<=1440)capacities['${e.key}']=n;}}
      }catch(_){if(mounted)_notice('Karşılaştırma kayıtları okunamadı.');}if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:days));
      final current=<String,int>{},baseline=<String,int>{};
      final records=<Map<String,dynamic>>[];
      final activeActions=actions.where(active).toList();
      // Tarihsel tam anlık görüntü tutulmadığından, geçmiş kayıtlardaki
      // son optimizasyon hareketi başlangıç planı için vekil olarak kullanılır.
      for(final a in activeActions){
        final nowDate=date(a['targetDate']??a['due']??a['nextDate']);
        if(nowDate==null)continue;
        final nowDay=day(nowDate),nowOwner=owner(a),mins=minutes(a);
        final history=a['history'] is List?a['history'] as List:const [];
        final events=<Map<String,dynamic>>[];
        for(final h in history){if(h is! Map)continue;
          final event='${h['event']??''}';
          final match=RegExp(r'Toplu haftalık optimizasyon:\s*(.*?)\s+(\d{4}-\d\d-\d\d)\s*→\s*(.*?)\s+(\d{4}-\d\d-\d\d)').firstMatch(event);
          if(match!=null){events.add({'at':date(h['at']),'fromOwner':match.group(1)!.trim(),'fromDate':date(match.group(2)),'toOwner':match.group(3)!.trim(),'toDate':date(match.group(4))});}
        }
        events.sort((a,b)=>(a['at'] as DateTime? ?? DateTime(1970)).compareTo(b['at'] as DateTime? ?? DateTime(1970)));
        final latest=events.isEmpty?null:events.last;
        final oldDate=latest?['fromDate'] as DateTime? ?? nowDay;
        final oldOwner=latest?['fromOwner'] as String? ?? nowOwner;
        if(!nowDay.isBefore(start)&&nowDay.isBefore(end))current[group(nowOwner,nowDay)]=(current[group(nowOwner,nowDay)]??0)+mins;
        if(!day(oldDate).isBefore(start)&&day(oldDate).isBefore(end))baseline[group(oldOwner,day(oldDate))]=(baseline[group(oldOwner,day(oldDate))]??0)+mins;
        if(latest!=null){
          final changed=oldOwner!=nowOwner||iso(oldDate)!=iso(nowDay);
          records.add({'title':'${a['title']??'Görev'}','owner':nowOwner,'oldOwner':oldOwner,'oldDate':oldDate,'newDate':nowDay,'minutes':mins,'changed':changed,'at':latest['at'],'priority':'${a['priority']??a['level']??'Orta'}','historyCount':events.length});
        }
      }
      final keys=<String>{...current.keys,...baseline.keys};
      int cap(String k)=>capacities[k.split('::').first]??defaultCapacity;
      int overloaded(Map<String,int> m)=>m.entries.where((e)=>e.value>cap(e.key)).length;
      int excess(Map<String,int> m)=>m.entries.fold<int>(0,(sum,e)=>sum+(e.value-cap(e.key)>0?e.value-cap(e.key):0));
      final beforeOver=overloaded(baseline),afterOver=overloaded(current);
      final beforeExcess=excess(baseline),afterExcess=excess(current);
      final owners=<String>{'Tümü',...records.map((e)=>e['owner'] as String),...records.map((e)=>e['oldOwner'] as String)}.toList()..sort();
      final filtered=records.where((r){
        if(ownerFilter!='Tümü'&&r['owner']!=ownerFilter&&r['oldOwner']!=ownerFilter)return false;
        if(onlyMoved&&r['changed']!=true)return false;
        if(onlyImproved&&beforeExcess<=afterExcess)return false;
        return '${r['title']} ${r['owner']} ${r['oldOwner']} ${r['priority']}'.toLowerCase().contains(search.toLowerCase());
      }).toList();
      filtered.sort((a,b){if(sort=='Görev')return '${a['title']}'.compareTo('${b['title']}');if(sort=='Süre')return (b['minutes'] as int).compareTo(a['minutes'] as int);if(sort=='Sorumlu')return '${a['owner']}'.compareTo('${b['owner']}');return (b['at'] as DateTime? ?? DateTime(1970)).compareTo(a['at'] as DateTime? ?? DateTime(1970));});
      final perOwner=<String,Map<String,int>>{};
      for(final k in keys){final name=k.split('::').first;final row=perOwner.putIfAbsent(name,()=>{'before':0,'after':0,'beforeOver':0,'afterOver':0});row['before']=row['before']!+(baseline[k]??0);row['after']=row['after']!+(current[k]??0);if((baseline[k]??0)>cap(k))row['beforeOver']=row['beforeOver']!+1;if((current[k]??0)>cap(k))row['afterOver']=row['afterOver']!+1;}
      final report=<String>['Görev,Önceki sorumlu,Önceki tarih,Mevcut sorumlu,Mevcut tarih,Tahmini dakika,Öncelik,Hareket sayısı'];
      for(final r in filtered){report.add([r['title'],r['oldOwner'],iso(r['oldDate'] as DateTime),r['owner'],iso(r['newDate'] as DateTime),r['minutes'],r['priority'],r['historyCount']].map(csv).join(','));}
      Widget stat(String title,String value,{bool warn=false})=>Card(color:warn?const Color(0xFFFFEDF0):const Color(0xFFFFF7FC),child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Text(title)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold))])));
      return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Toplu optimizasyon • Öncesi / sonrası plan karşılaştırması',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Karşılaştırma, görev geçmişindeki SON toplu optimizasyon hareketini ve mevcut planı kullanır. Eski planın tam anlık görüntüsü bulunmadığı için sonuçlar yaklaşık olabilir. Sonraki elle değişiklikler ve tamamlanan görevler sonuçları etkiler.'),
        if(loading)const LinearProgressIndicator()else ...[
          Wrap(spacing:8,children:[for(final n in [7,14,21,28,60,90])ChoiceChip(label:Text('$n gün'),selected:days==n,onSelected:(_)=>refresh(()=>days=n))]),
          Row(children:[IconButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:days))),icon:const Icon(Icons.chevron_left)),Expanded(child:Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}',textAlign:TextAlign.center)),IconButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:days))),icon:const Icon(Icons.chevron_right)),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün'))]),
          stat('Aktif görev', '${activeActions.length}'),
          stat('Geçmişinde toplu optimizasyon olan görev','${records.length}'),
          stat('Aşırı yüklü sorumlu-gün • önce / sonra','$beforeOver / $afterOver',warn:afterOver>0),
          stat('Kapasite aşımı • önce / sonra','$beforeExcess / $afterExcess dk',warn:afterExcess>0),
          stat('Kapasite aşımı değişimi','${afterExcess-beforeExcess>=0?'+':''}${afterExcess-beforeExcess} dk'),
          stat('Planlanan süre • önce / sonra','${baseline.values.fold<int>(0,(a,b)=>a+b)} / ${current.values.fold<int>(0,(a,b)=>a+b)} dk'),
          stat('İzlenen sorumlu','${perOwner.length}'),
          const SizedBox(height:10),
          TextField(decoration:const InputDecoration(labelText:'Görev, sorumlu veya öncelik ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:10,children:[DropdownButton<String>(value:owners.contains(ownerFilter)?ownerFilter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü')),DropdownButton<String>(value:sort,items:['En yeni','Görev','Süre','Sorumlu'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'En yeni'))]),
          SwitchListTile(title:const Text('Yalnızca gerçekten taşınan görevler'),value:onlyMoved,onChanged:(v)=>refresh(()=>onlyMoved=v)),
          SwitchListTile(title:const Text('Yalnızca toplam kapasite aşımı azalan dönem'),value:onlyImproved,onChanged:(v)=>refresh(()=>onlyImproved=v)),
          Card(child:ExpansionTile(title:const Text('Sorumlu bazında önce / sonra'),children:[for(final e in perOwner.entries)ListTile(title:Text(e.key),subtitle:Text('Planlanan: ${e.value['before']} → ${e.value['after']} dk'),trailing:Text('Aşım günü: ${e.value['beforeOver']} → ${e.value['afterOver']}'))])),
          for(final r in filtered.take(100))Card(child:ListTile(title:Text('${r['title']} • ${r['minutes']} dk'),subtitle:Text('${r['oldOwner']} • ${iso(r['oldDate'] as DateTime)} → ${r['owner']} • ${iso(r['newDate'] as DateTime)}\n${r['priority']} • ${r['historyCount']} optimizasyon kaydı'),leading:Icon(r['changed']==true?Icons.compare_arrows:Icons.history,color:_purple))),
          if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('Bu filtreye uygun geçmiş optimizasyon hareketi bulunamadı.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}'));if(mounted)_notice('${filtered.length} görev CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Karşılaştırma raporunu CSV kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenBatchWeekOptimizer();},icon:const Icon(Icons.auto_fix_high),label:const Text('Toplu haftalık optimizasyona geç')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenWeeklyPlanQuality();},icon:const Icon(Icons.analytics_outlined),label:const Text('Haftalık plan performansına geç')),
        ]
      ])));
    }));
