  void _showKitchenBatchWeekOptimizer() {
    const actionKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final actions=<Map<String,dynamic>>[];
    final capacities=<String,int>{};
    bool initiated=false,loading=true,onlyOverloaded=false,includeUnassigned=true,keepOwner=false,includeWeekends=true;
    int days=7,minSamples=2,defaultCapacity=120,maxMoves=15;
    String ownerFilter='Tümü',query='',order='Öncelik';
    DateTime anchor=DateTime.now();
    DateTime? parse(Object? v)=>DateTime.tryParse('${v??''}');
    DateTime day(DateTime v)=>DateTime(v.year,v.month,v.day);
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String who(Map<String,dynamic> a){final x='${a['owner']??''}'.trim();return x.isEmpty?'Atanmamış':x;}
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains('${a['status']??'Açık'}');
    int valid(Object? v,int fallback){final n=int.tryParse('${v??''}');return n!=null&&n>=5&&n<=1440?n:fallback;}
    int priority(Map<String,dynamic> a)=>'${a['priority']??a['level']??''}'=='Kritik'?3:'${a['priority']??a['level']??''}'=='Yüksek'?2:1;
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    Future<void> persist()async{final p=await SharedPreferences.getInstance();if(!await p.setString(actionKey,jsonEncode(actions)))throw StateError('Kaydedilemedi');}
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!initiated){initiated=true;SharedPreferences.getInstance().then((p){try{
        final raw=jsonDecode(p.getString(actionKey)??'[]');if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((a)=>Map<String,dynamic>.from(a)));}
        final rawCaps=jsonDecode(p.getString(capacityKey)??'{}');if(rawCaps is Map){for(final e in rawCaps.entries){capacities['${e.key}']=valid(e.value,defaultCapacity);}}
      }catch(_){if(mounted)_notice('Optimizasyon verileri okunamadı.');}if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:days)),today=day(DateTime.now());
      final historical=<String,List<int>>{};
      for(final a in actions){final actual=int.tryParse('${a['actualMinutes']??''}');final title='${a['title']??''}'.trim().toLowerCase();if(actual!=null&&actual>=1&&actual<=1440&&title.isNotEmpty){historical.putIfAbsent(title,()=>[]).add(actual);}}
      int estimate(Map<String,dynamic> a){final v=historical['${a['title']??''}'.trim().toLowerCase()]??<int>[];if(v.length>=minSamples){final sorted=[...v]..sort();final values=sorted.length>=5?sorted.sublist(1,sorted.length-1):sorted;return (values.reduce((x,y)=>x+y)/values.length).round().clamp(5,1440);}return valid(a['estimatedMinutes'],30);}
      final owners=<String>{'Tümü',...actions.map(who)}.toList()..sort();
      final people=owners.where((x)=>x!='Tümü'&&x!='Atanmamış').toList();
      final scoped=actions.where((a){final due=parse(a['targetDate']??a['due']??a['nextDate']);return active(a)&&due!=null&&!day(due).isBefore(start)&&day(due).isBefore(end);}).toList();
      String key(String name,DateTime date)=>'$name::${iso(date)}';
      final original=<String,int>{};
      for(final a in scoped){final d=day(parse(a['targetDate']??a['due']??a['nextDate'])!);final k=key(who(a),d);original[k]=(original[k]??0)+estimate(a);}
      final over=original.entries.where((e)=>e.value>(capacities[e.key.split('::').first]??defaultCapacity)).toList();
      final visible=scoped.where((a){final d=day(parse(a['targetDate']??a['due']??a['nextDate'])!);return (ownerFilter=='Tümü'||who(a)==ownerFilter)&&(!onlyOverloaded||(original[key(who(a),d)]??0)>(capacities[who(a)]??defaultCapacity))&&(includeUnassigned||who(a)!='Atanmamış')&&'$a'.toLowerCase().contains(query.toLowerCase());}).toList();
      visible.sort((a,b){if(order=='Tarih')return '${a['targetDate']??''}'.compareTo('${b['targetDate']??''}');if(order=='Süre')return estimate(b).compareTo(estimate(a));if(order=='Sorumlu')return who(a).compareTo(who(b));return priority(b).compareTo(priority(a));});
      final proposed=Map<String,int>.from(original);
      final suggestions=<Map<String,dynamic>>[];
      final candidates=[...visible]..sort((a,b){final ad=day(parse(a['targetDate']??a['due']??a['nextDate'])!),bd=day(parse(b['targetDate']??b['due']??b['nextDate'])!);final x=ad.compareTo(bd);return x!=0?x:priority(b).compareTo(priority(a));});
      for(final a in candidates){if(suggestions.length>=maxMoves)break;
        final from=day(parse(a['targetDate']??a['due']??a['nextDate'])!),name=who(a),mins=estimate(a),oldKey=key(name,from);
        final sourceOver=(proposed[oldKey]??0)>(capacities[name]??defaultCapacity);
        if(!sourceOver&&name!='Atanmamış')continue;
        final eligible=keepOwner?[name]:people;
        final options=<Map<String,dynamic>>[];
        for(final person in eligible){if(person=='Atanmamış')continue;for(var i=0;i<days;i++){
          final date=start.add(Duration(days:i));if(date.isBefore(today)||(!includeWeekends&&date.weekday>=6))continue;
          if(date.isBefore(from)&&priority(a)>=3)continue;
          if(person==name&&iso(date)==iso(from))continue;
          final k=key(person,date),cap=capacities[person]??defaultCapacity,load=proposed[k]??0;
          if(load+mins>cap)continue;
          options.add({'owner':person,'date':date,'free':cap-load-mins,'load':load,'shift':date.difference(from).inDays.abs()});
        }}
        options.sort((x,y){final c=(x['shift'] as int).compareTo(y['shift'] as int);if(c!=0)return c;return (y['free'] as int).compareTo(x['free'] as int);});
        if(options.isEmpty)continue;
        final choice=options.first,newDate=choice['date'] as DateTime,newOwner=choice['owner'] as String;
        proposed[oldKey]=(proposed[oldKey]??0)-mins;
        final dest=key(newOwner,newDate);proposed[dest]=(proposed[dest]??0)+mins;
        suggestions.add({'action':a,'from':from,'oldOwner':name,'owner':newOwner,'date':newDate,'minutes':mins,'priority':priority(a)});
      }
      Future<void> preview()async{
        if(suggestions.isEmpty){if(mounted)_notice('Uygun toplu değişiklik önerisi bulunamadı.');return;}
        final picked=<int>{for(var i=0;i<suggestions.length;i++)i};
        final approved=await showDialog<List<int>>(context:ctx,builder:(dialog)=>StatefulBuilder(builder:(d,setD)=>AlertDialog(title:const Text('Toplu optimizasyon önerileri'),content:SizedBox(width:520,height:420,child:ListView(children:[Text('${suggestions.length} öneri • ${over.length} aşırı yüklü sorumlu-gün. Seçilenler onaydan sonra kaydedilir.'),...List.generate(suggestions.length,(i){final s=suggestions[i],a=s['action'] as Map<String,dynamic>;return CheckboxListTile(value:picked.contains(i),onChanged:(v)=>setD((){if(v==true){picked.add(i);}else{picked.remove(i);}}),title:Text('${a['title']??'Görev'} • ${s['minutes']} dk'),subtitle:Text('${s['oldOwner']} ${iso(s['from'] as DateTime)} → ${s['owner']} ${iso(s['date'] as DateTime)}'));})])),actions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('Vazgeç')),FilledButton(onPressed:picked.isEmpty?null:()=>Navigator.pop(dialog,picked.toList()..sort()),child:Text('${picked.length} değişikliği uygula'))])));
        if(approved==null||approved.isEmpty||!ctx.mounted)return;
        final confirmation=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:const Text('Toplu görev planını kaydet'),content:Text('${approved.length} görev için sorumlu ve/veya tarih değiştirilecek. Devam edilsin mi?'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('İptal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        if(confirmation!=true)return;
        final before=<Map<String,dynamic>,Map<String,dynamic>>{};
        final stamp=DateTime.now().toIso8601String();
        refresh((){for(final i in approved){final s=suggestions[i],a=s['action'] as Map<String,dynamic>;before[a]=Map<String,dynamic>.from(a);a['owner']=s['owner'];a['targetDate']=iso(s['date'] as DateTime);a['updated']=stamp;final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];h.add({'at':stamp,'event':'Toplu haftalık optimizasyon: ${s['oldOwner']} ${iso(s['from'] as DateTime)} → ${s['owner']} ${a['targetDate']}'});a['history']=h;}});
        try{await persist();
          try{const versionKey='paket40_optimization_plan_versions_v1';final prefs=await SharedPreferences.getInstance();final oldVersions=jsonDecode(prefs.getString(versionKey)??'[]');final history=oldVersions is List?oldVersions.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():<Map<String,dynamic>>[];
            String id(Map<String,dynamic> a)=>'${a['createdAt']??a['created']??''}|${a['title']??''}|${a['sourceProduct']??''}';
            final prev=<Map<String,dynamic>>[],next=<Map<String,dynamic>>[];
            for(final i in approved){final a=suggestions[i]['action'] as Map<String,dynamic>;final b=before[a]!;prev.add({'id':id(a),'title':a['title'],'owner':b['owner'],'targetDate':b['targetDate']});next.add({'id':id(a),'title':a['title'],'owner':a['owner'],'targetDate':a['targetDate']});}
            history.insert(0,{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':'Toplu optimizasyon • ${approved.length} görev','at':stamp,'type':'optimization','note':'Kullanıcı onaylı toplu planlama','before':prev,'after':next});await prefs.setString(versionKey,jsonEncode(history.take(100).toList()));
          }catch(_){if(mounted)_notice('Görevler kaydedildi ancak sürüm geçmişi kaydedilemedi.');}
          if(mounted)_notice('${approved.length} görev planı kaydedildi.');}catch(_){if(ctx.mounted)refresh((){for(final e in before.entries){e.key..clear()..addAll(e.value);}});if(mounted)_notice('Kayıt başarısız; tüm değişiklikler geri alındı.');}
      }
      final rows=<String>['Görev,Öncelik,Mevcut sorumlu,Mevcut tarih,Tahmini dk,Önerilen sorumlu,Önerilen tarih'];
      for(final s in suggestions){final a=s['action'] as Map<String,dynamic>;rows.add([a['title'],a['priority']??a['level'],s['oldOwner'],iso(s['from'] as DateTime),s['minutes'],s['owner'],iso(s['date'] as DateTime)].map(csv).join(','));}
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Akıllı süre tahmini / toplu haftalık optimizasyon',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Önizleme önce oluşturulur. Kritik görevler geçmiş tarihe çekilmez; öneriler otomatik uygulanmaz. Kapasite, kaydedilmiş tahmini dakika üzerinden hesaplanır.'),
        if(loading)const LinearProgressIndicator() else ...[
          Wrap(spacing:10,runSpacing:8,children:[DropdownButton<int>(value:days,items:[7,14,21,28].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>days=v??7)),DropdownButton<int>(value:minSamples,items:[1,2,3,5].map((v)=>DropdownMenuItem(value:v,child:Text('Öğrenme: $v ölçüm'))).toList(),onChanged:(v)=>refresh(()=>minSamples=v??2)),DropdownButton<int>(value:maxMoves,items:[5,10,15,25,50].map((v)=>DropdownMenuItem(value:v,child:Text('En fazla $v öneri'))).toList(),onChanged:(v)=>refresh(()=>maxMoves=v??15)),DropdownButton<String>(value:owners.contains(ownerFilter)?ownerFilter:'Tümü',items:owners.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü')),DropdownButton<String>(value:order,items:['Öncelik','Tarih','Süre','Sorumlu'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>order=v??'Öncelik'))]),
          Row(children:[IconButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:days))),icon:const Icon(Icons.chevron_left)),Expanded(child:Text('${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}',textAlign:TextAlign.center)),IconButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:days))),icon:const Icon(Icons.chevron_right)),TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün'))]),
          TextField(decoration:const InputDecoration(labelText:'Görev, ürün, sorumlu veya açıklama ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>query=v)),
          SwitchListTile(title:const Text('Yalnızca kapasitesi aşılmış günlerin görevleri'),value:onlyOverloaded,onChanged:(v)=>refresh(()=>onlyOverloaded=v)),
          SwitchListTile(title:const Text('Atanmamış görevleri dahil et'),value:includeUnassigned,onChanged:(v)=>refresh(()=>includeUnassigned=v)),
          SwitchListTile(title:const Text('Görev sorumlusunu değiştirme'),value:keepOwner,onChanged:(v)=>refresh(()=>keepOwner=v)),
          SwitchListTile(title:const Text('Hafta sonlarına planlama yap'),value:includeWeekends,onChanged:(v)=>refresh(()=>includeWeekends=v)),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Wrap(spacing:14,runSpacing:8,children:[Text('Planlanan görev: ${scoped.length}'),Text('Filtrelenen: ${visible.length}'),Text('Kapasite aşımı: ${over.length} gün'),Text('Öneri: ${suggestions.length}'),Text('Sorumlu: ${people.length}'),Text('Tahmini yük: ${scoped.fold<int>(0,(n,a)=>n+estimate(a))} dk')]))),
          if(over.isNotEmpty)Card(child:ExpansionTile(title:const Text('Aşırı yüklü günler'),children:over.map((e){final person=e.key.split('::').first,cap=capacities[person]??defaultCapacity;return ListTile(title:Text(e.key.replaceAll('::',' • ')),subtitle:LinearProgressIndicator(value:(e.value/cap).clamp(0.0,1.0),color:Colors.red),trailing:Text('${e.value}/$cap dk'));}).toList())),
          ...suggestions.take(25).map((s){final a=s['action'] as Map<String,dynamic>;return Card(child:ListTile(title:Text('${a['title']??'Görev'} • ${s['minutes']} dk'),subtitle:Text('${s['oldOwner']} ${iso(s['from'] as DateTime)} → ${s['owner']} ${iso(s['date'] as DateTime)}'),leading:Icon(Icons.auto_fix_high,color:_purple)));}),
          if(suggestions.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('Bu dönem için uygun optimizasyon önerisi yok. Kapasiteyi, sorumlu kayıtlarını veya tarih aralığını kontrol et.')),
          FilledButton.icon(onPressed:suggestions.isEmpty?null:preview,icon:const Icon(Icons.rule),label:Text('Önerileri incele ve toplu uygula (${suggestions.length})')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${rows.join('\r\n')}'));if(mounted)_notice('Optimizasyon önerileri CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Önerileri CSV olarak kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenDurationLearningPlanner();},icon:const Icon(Icons.school_outlined),label:const Text('Görev süresi öğrenme merkezine geç')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenWeeklyPlanQuality();},icon:const Icon(Icons.analytics_outlined),label:const Text('Haftalık plan performansına geç')),
        ]
      ]))));
    }));
