  void _showKitchenWeeklyPlanQuality() {
    const actionKey='paket39_purchase_improvement_actions_v1';
    const capacityKey='paket39_daily_available_minutes_v1';
    final actions=<Map<String,dynamic>>[];
    final capacities=<String,int>{};
    bool initiated=false,loading=true,onlyOver=false,onlyMissing=false,onlyLate=false;
    int days=7,defaultMinutes=120;
    String owner='Tümü',status='Tümü',order='Hedef tarihi',query='';
    DateTime anchor=DateTime.now();
    DateTime? parse(Object? v)=>DateTime.tryParse('${v??''}');
    DateTime day(DateTime v)=>DateTime(v.year,v.month,v.day);
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    String who(Map<String,dynamic> a){final t='${a['owner']??''}'.trim();return t.isEmpty?'Atanmamış':t;}
    bool done(Map<String,dynamic> a)=>'${a['status']??''}'=='Tamamlandı';
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains('${a['status']??'Açık'}');
    int? number(Object? v){final n=int.tryParse('${v??''}');return n!=null&&n>0&&n<=1440?n:null;}
    int estimate(Map<String,dynamic> a)=>number(a['estimatedMinutes'])??30;
    int? actual(Map<String,dynamic> a)=>number(a['actualMinutes']);
    int priority(Map<String,dynamic> a)=>'${a['priority']??a['level']??''}'=='Kritik'?3:'${a['priority']??a['level']??''}'=='Yüksek'?2:1;
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!initiated){initiated=true;SharedPreferences.getInstance().then((p){try{
        final raw=jsonDecode(p.getString(actionKey)??'[]');
        if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}
        final c=jsonDecode(p.getString(capacityKey)??'{}');
        if(c is Map){for(final e in c.entries){final n=number(e.value);if(n!=null)capacities['${e.key}']=n;}}
      }catch(_){if(mounted)_notice('Haftalık performans verileri okunamadı.');}
      if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:days)),today=day(DateTime.now());
      final owners=<String>{'Tümü',...actions.map(who)}.toList()..sort();
      if(!owners.contains(owner))owner='Tümü';
      final dated=actions.where((a){final d=parse(a['targetDate']??a['due']??a['nextDate']);return d!=null&&!day(d).isBefore(start)&&day(d).isBefore(end);}).toList();
      final visible=dated.where((a){final due=day(parse(a['targetDate']??a['due']??a['nextDate'])!);
        return (owner=='Tümü'||owner==who(a))&&(status=='Tümü'||(status=='Tamamlanan'&&done(a))||(status=='Açık'&&active(a))||(status=='İptal'&&'${a['status']}'=='İptal'))&&(!onlyMissing||actual(a)==null)&&(!onlyLate||active(a)&&due.isBefore(today))&&('$a'.toLowerCase().contains(query.toLowerCase()));
      }).toList();
      final grouped=<String,List<Map<String,dynamic>>>{};
      for(final a in visible){final d=iso(day(parse(a['targetDate']??a['due']??a['nextDate'])!));grouped.putIfAbsent('${who(a)}|$d',()=>[]).add(a);}
      final overloaded=<String>{};
      for(final e in grouped.entries){final person=e.key.split('|').first,cap=capacities[person]??defaultMinutes;
        final load=e.value.where(active).fold<int>(0,(s,a)=>s+estimate(a));if(load>cap)overloaded.add(e.key);
      }
