  void _showKitchenActualDurationInsights() {
    const key='paket39_purchase_improvement_actions_v1';
    final actions=<Map<String,dynamic>>[];
    var loaded=false, busy=true, query='', owner='Tümü', status='Tümü', order='En büyük sapma', onlyMeasured=false;
    int period=90;
    DateTime? date(Object? value)=>DateTime.tryParse('${value??''}');
    int? valid(Object? v){final n=int.tryParse('${v??''}');return n!=null&&n>=1&&n<=1440?n:null;}
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    Future<void> persist()async{final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(actions));}
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!loaded){loaded=true;SharedPreferences.getInstance().then((p){try{final raw=jsonDecode(p.getString(key)??'[]');if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}}catch(_){if(mounted)_notice('Görev süre kayıtları okunamadı.');}if(ctx.mounted)refresh(()=>busy=false);});}
      final now=DateTime.now(),cutoff=now.subtract(Duration(days:period));
      final owners=<String>{'Tümü',...actions.map((a)=>'${a['owner']??''}'.trim().isEmpty?'Atanmamış':'${a['owner']}')}.toList()..sort();
      final base=actions.where((a){final d=date(a['completedAt'])??date(a['updated'])??date(a['createdAt'])??date(a['created']);return d==null||!d.isBefore(cutoff);}).toList();
      final filtered=base.where((a){final who='${a['owner']??''}'.trim().isEmpty?'Atanmamış':'${a['owner']}';final done='${a['status']??'Açık'}'=='Tamamlandı';return (owner=='Tümü'||owner==who)&&(status=='Tümü'||(status=='Tamamlanan'&&done)||(status=='Açık olanlar'&&!done))&&(!onlyMeasured||valid(a['actualMinutes'])!=null)&&('$a'.toLowerCase().contains(query.toLowerCase()));}).toList();
      int estimate(Map<String,dynamic> a)=>valid(a['estimatedMinutes'])??30;
      int? actual(Map<String,dynamic> a)=>valid(a['actualMinutes']);
      int difference(Map<String,dynamic> a)=>(actual(a)??estimate(a))-estimate(a);
      filtered.sort((a,b){switch(order){case 'En yeni':return '${b['updated']??b['createdAt']??''}'.compareTo('${a['updated']??a['createdAt']??''}');case 'Sorumlu':return '${a['owner']??''}'.compareTo('${b['owner']??''}');case 'Görev adı':return '${a['title']??''}'.compareTo('${b['title']??''}');default:return difference(b).abs().compareTo(difference(a).abs());}});
      final measured=filtered.where((a)=>actual(a)!=null).toList();
      final estimatedTotal=measured.fold<int>(0,(v,a)=>v+estimate(a));
      final actualTotal=measured.fold<int>(0,(v,a)=>v+actual(a)!);
      final over=measured.where((a)=>difference(a)>0).length;
      final under=measured.where((a)=>difference(a)<0).length;
      final exact=measured.where((a)=>difference(a)==0).length;
      final accuracy=measured.isEmpty?0.0:measured.map((a)=>((1-(difference(a).abs()/estimate(a))).clamp(0.0,1.0))).reduce((a,b)=>a+b)/measured.length*100;
      Future<void> edit(Map<String,dynamic> a)async{
        final c=TextEditingController(text:'${a['actualMinutes']??''}');
        final ok=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:Text('${a['title']??'Görev'} • gerçekleşen süre'),content:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Tahmin: ${estimate(a)} dakika'),const SizedBox(height:10),TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Gerçekleşen dakika (1–1440)',helperText:'Boş bırakırsan önceki ölçüm silinir.'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        final input=c.text.trim();disposeAfterDialog(c);if(ok!=true)return;final n=input.isEmpty?null:int.tryParse(input);if(input.isNotEmpty&&(n==null||n<1||n>1440)){if(mounted)_notice('1–1440 dakika arasında değer gir.');return;}
        final old=Map<String,dynamic>.from(a);refresh((){if(n==null){a.remove('actualMinutes');}else{a['actualMinutes']=n;}a['updated']=DateTime.now().toIso8601String();final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':n==null?'Gerçekleşen süre silindi':'Gerçekleşen süre: $n dakika'});a['history']=h;});
        try{await persist();if(mounted)_notice('Gerçekleşen süre kaydedildi.');}catch(_){if(ctx.mounted)refresh((){a..clear()..addAll(old);});if(mounted)_notice('Kayıt başarısız; değişiklik geri alındı.');}
      }
      Future<void> applyEstimate(Map<String,dynamic> a,int n)async{if(n<5||n>1440)return;final old=Map<String,dynamic>.from(a);refresh((){a['estimatedMinutes']=n;a['updated']=DateTime.now().toIso8601String();final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':'Geçmiş ölçümlerden tahmin: $n dakika'});a['history']=h;});try{await persist();if(mounted)_notice('Yeni tahmin kaydedildi.');}catch(_){if(ctx.mounted)refresh((){a..clear()..addAll(old);});if(mounted)_notice('Tahmin kaydedilemedi.');}}
      final rows=<String>['Görev,Sorumlu,Durum,Tahmin dk,Gerçekleşen dk,Sapma dk,Sapma %,Güncelleme'];
      for(final a in filtered){final e=estimate(a),v=actual(a);rows.add([a['title'],a['owner'],a['status'],e,v,v==null?'':v-e,v==null?'':((v-e)/e*100).toStringAsFixed(1),a['updated']].map(csv).join(','));}
      final groups=<String,List<Map<String,dynamic>>>{};for(final a in measured){final who='${a['owner']??''}'.trim().isEmpty?'Atanmamış':'${a['owner']}';groups.putIfAbsent(who,()=>[]).add(a);}
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
        Row(children:[Expanded(child:Text('Gerçekleşen süre / tahmin doğruluğu',style:Theme.of(ctx).textTheme.titleLarge)),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
        const Text('Ölçümler kullanıcı girişidir; otomatik zaman tutma yapılmaz. Tahminsiz görevlerde 30 dk varsayılır.'),
        if(busy)const LinearProgressIndicator() else ...[
          Wrap(spacing:8,runSpacing:8,children:[DropdownButton<int>(value:period,items:[30,60,90,180,365].map((n)=>DropdownMenuItem(value:n,child:Text('$n gün'))).toList(),onChanged:(n)=>refresh(()=>period=n??90)),DropdownButton<String>(value:owners.contains(owner)?owner:'Tümü',items:owners.map((n)=>DropdownMenuItem(value:n,child:Text(n))).toList(),onChanged:(n)=>refresh(()=>owner=n??'Tümü')),DropdownButton<String>(value:status,items:['Tümü','Tamamlanan','Açık olanlar'].map((n)=>DropdownMenuItem(value:n,child:Text(n))).toList(),onChanged:(n)=>refresh(()=>status=n??'Tümü')),DropdownButton<String>(value:order,items:['En büyük sapma','En yeni','Sorumlu','Görev adı'].map((n)=>DropdownMenuItem(value:n,child:Text(n))).toList(),onChanged:(n)=>refresh(()=>order=n??'En büyük sapma'))]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev / sorumlu ara'),onChanged:(v)=>refresh(()=>query=v)),SwitchListTile(title:const Text('Yalnızca gerçekleşen süresi girilenler'),value:onlyMeasured,onChanged:(v)=>refresh(()=>onlyMeasured=v)),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Görev: ${filtered.length} • Ölçülen: ${measured.length} • Ölçülmeyen: ${filtered.length-measured.length}'),Text('Tahmin toplamı: $estimatedTotal dk • Gerçekleşen: $actualTotal dk'),Text('Toplam fark: ${actualTotal-estimatedTotal} dk • Doğruluk göstergesi: %${accuracy.toStringAsFixed(1)}'),Text('Tahmini aşan: $over • Tahminden kısa: $under • Tam eşleşen: $exact'),if(measured.isNotEmpty)LinearProgressIndicator(value:(accuracy/100).clamp(0.0,1.0))]))),
          if(groups.isNotEmpty)Card(child:ExpansionTile(title:const Text('Sorumlu bazlı süre performansı'),children:groups.entries.map((e){final est=e.value.fold<int>(0,(v,a)=>v+estimate(a)),act=e.value.fold<int>(0,(v,a)=>v+actual(a)!);return ListTile(title:Text('${e.key} • ${e.value.length} ölçüm'),subtitle:Text('Tahmin: $est dk • Gerçekleşen: $act dk • Fark: ${act-est} dk'));}).toList())),
          ...filtered.map((a){final e=estimate(a),v=actual(a),d=v==null?null:v-e;final comparable=measured.where((b)=>'${b['title']??''}'.trim().toLowerCase()=='${a['title']??''}'.trim().toLowerCase()).toList();final suggested=comparable.isEmpty?null:(comparable.fold<int>(0,(sum,b)=>sum+actual(b)!)/comparable.length).round().clamp(5,1440);return Card(child:ExpansionTile(title:Text('${a['title']??'Görev'}'),subtitle:Text('${a['owner']??'Atanmamış'} • ${a['status']??'Açık'} • Tahmin $e dk • ${v==null?'Ölçüm yok':'Gerçek $v dk (${d!>=0?'+':''}$d dk)'}'),children:[if(v!=null)ListTile(title:Text('Sapma: %${(d!/e*100).toStringAsFixed(1)}'),subtitle:Text(d>0?'Tahminin üzerinde tamamlandı':d<0?'Tahminden kısa sürdü':'Tahminle eşleşti')),if(suggested!=null)ListTile(title:Text('Benzer başlıklı ${comparable.length} ölçümün ortalaması: $suggested dk'),subtitle:const Text('Öneri yalnızca aynı başlıklı kayıtların kullanıcı girişlerine dayanır.'),trailing:TextButton(onPressed:()=>applyEstimate(a,suggested),child:const Text('Tahmini güncelle'))),TextButton.icon(onPressed:()=>edit(a),icon:const Icon(Icons.edit_outlined),label:Text(v==null?'Gerçekleşen süre gir':'Gerçekleşen süreyi düzenle'))]));}),
          if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('Bu filtrelerde görev bulunamadı.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${rows.join('\r\n')}'));if(mounted)_notice('Süre performans raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('CSV raporunu kopyala')),
          OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenDurationCapacityOptimizer();},icon:const Icon(Icons.timer_outlined),label:const Text('Tahmini süre ve kapasite ekranına geç')),
        ]
      ]))));
    }));
  }

  void _showKitchenDurationCapacityOptimizer() {
    const actionKey='paket39_purchase_improvement_actions_v1';
    const hoursKey='paket39_daily_available_minutes_v1';
    final actions=<Map<String,dynamic>>[];
    final available=<String,int>{};
    var started=false,loading=true,query='',ownerFilter='Tümü',window=7,onlyOver=false,onlyMissing=false;
    DateTime anchor=DateTime.now();
    DateTime? parse(Object? v)=>DateTime.tryParse((v??'').toString());
    DateTime day(DateTime d)=>DateTime(d.year,d.month,d.day);
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains('${a['status']??'Açık'}');
    int minutes(Map<String,dynamic> a){final n=int.tryParse('${a['estimatedMinutes']??''}');return n!=null&&n>=5&&n<=1440?n:30;}
    Future<void> saveActions()async{final p=await SharedPreferences.getInstance();await p.setString(actionKey,jsonEncode(actions));}
    Future<void> saveHours()async{final p=await SharedPreferences.getInstance();await p.setString(hoursKey,jsonEncode(available));}
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((p){
        try{final raw=jsonDecode(p.getString(actionKey)??'[]');if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}
          final h=jsonDecode(p.getString(hoursKey)??'{}');if(h is Map){for(final e in h.entries){final n=int.tryParse('${e.value}');if(n!=null&&n>=15&&n<=1440)available['${e.key}']=n;}}}
        catch(_){if(mounted)_notice('Süre ve kapasite kayıtlarının bir kısmı okunamadı.');}
        if(ctx.mounted)refresh(()=>loading=false);
      }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:window));
      final owners={'Atanmamış',...actions.map((a)=>'${a['owner']??''}'.trim()).where((v)=>v.isNotEmpty)}.toList()..sort();
      final selectedOwner=ownerFilter=='Tümü'||owners.contains(ownerFilter)?ownerFilter:'Tümü';
      final visible=actions.where((a){if(!active(a))return false;final d=parse(a['due']);if(d==null||day(d).isBefore(start)||!day(d).isBefore(end))return false;
        final who='${a['owner']??''}'.trim();if(selectedOwner!='Tümü'&&(who.isEmpty?'Atanmamış':who)!=selectedOwner)return false;
        if(onlyMissing&&a['estimatedMinutes']!=null)return false;
        return '${a['title']} ${a['product']} ${a['owner']} ${a['note']}'.toLowerCase().contains(query.toLowerCase());}).toList();
      final groups=<String,List<Map<String,dynamic>>>{};
      for(final a in visible){final who='${a['owner']??''}'.trim();groups.putIfAbsent(who.isEmpty?'Atanmamış':who,()=>[]).add(a);}
      final summary=<Map<String,dynamic>>[];
      for(final entry in groups.entries){final daily=<String,int>{};final counts=<String,int>{};for(final a in entry.value){final date=parse(a['due']);if(date==null)continue;final k=iso(date);daily[k]=(daily[k]??0)+minutes(a);counts[k]=(counts[k]??0)+1;}
        final cap=available[entry.key]??120;summary.add({'owner':entry.key,'tasks':entry.value,'daily':daily,'counts':counts,'cap':cap,'over':daily.values.where((v)=>v>cap).length,'total':daily.values.fold<int>(0,(a,b)=>a+b)});}
      summary.sort((a,b)=>(b['over'] as int).compareTo(a['over'] as int));
      final shown=summary.where((g)=>!onlyOver||(g['over'] as int)>0).toList();
      final totalMinutes=visible.fold<int>(0,(v,a)=>v+minutes(a));
      final missing=visible.where((a)=>a['estimatedMinutes']==null).length;
      final overDays=summary.fold<int>(0,(v,g)=>v+(g['over'] as int));
      Future<void> editCapacity(String who)async{final c=TextEditingController(text:'${available[who]??120}');
        final ok=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:Text('$who • günlük kullanılabilir süre'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Dakika (15–1440)',helperText:'Örnek: 120 dakika = 2 saat')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        final n=int.tryParse(c.text.trim());disposeAfterDialog(c);if(ok!=true)return;if(n==null||n<15||n>1440){if(mounted)_notice('15–1440 dakika arasında değer gir.');return;}
        final previous=available[who];refresh(()=>available[who]=n);try{await saveHours();if(mounted)_notice('Günlük süre kaydedildi.');}catch(_){if(ctx.mounted)refresh((){if(previous==null){available.remove(who);}else{available[who]=previous;}});if(mounted)_notice('Kapasite kaydedilemedi.');}
      }
      Future<void> editDuration(Map<String,dynamic> a)async{final c=TextEditingController(text:'${a['estimatedMinutes']??30}');
        final ok=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:Text('${a['title']??'Görev'} • tahmini süre'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Dakika (5–1440)',helperText:'Tahmini süredir; gerçek süreyi ölçmez.')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        final n=int.tryParse(c.text.trim());disposeAfterDialog(c);if(ok!=true)return;if(n==null||n<5||n>1440){if(mounted)_notice('5–1440 dakika arasında değer gir.');return;}
        final old=Map<String,dynamic>.from(a);refresh((){a['estimatedMinutes']=n;a['updated']=DateTime.now().toIso8601String();final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':'Tahmini süre: $n dakika'});a['history']=h;});
        try{await saveActions();if(mounted)_notice('Tahmini görev süresi kaydedildi.');}catch(_){if(ctx.mounted)refresh((){a..clear()..addAll(old);});if(mounted)_notice('Kayıt başarısız; işlem geri alındı.');}
      }
      Future<void> suggest(Map<String,dynamic> task)async{
        final due=parse(task['due']);if(due==null)return;final candidates=<Map<String,dynamic>>[];
        final candidateOwners=owners.where((o)=>o!='Atanmamış').toList();
        for(var offset=0;offset<14;offset++){final date=day(due).add(Duration(days:offset));for(final who in candidateOwners){
          final occupied=actions.where((a)=>!identical(a,task)&&active(a)&&'${a['owner']??''}'.trim()==who&&parse(a['due'])!=null&&iso(parse(a['due'])!)==iso(date)).fold<int>(0,(v,a)=>v+minutes(a));
          final capacity=available[who]??120;final remaining=capacity-occupied-minutes(task);
          candidates.add({'owner':who,'date':date,'occupied':occupied,'capacity':capacity,'remaining':remaining});}}
        candidates.sort((a,b){final aFit=(a['remaining'] as int)>=0,bFit=(b['remaining'] as int)>=0;if(aFit!=bFit)return aFit?-1:1;final c=(a['date'] as DateTime).compareTo(b['date'] as DateTime);if(c!=0)return c;return (b['remaining'] as int).compareTo(a['remaining'] as int);});
        if(candidates.isEmpty){if(mounted)_notice('Öneri için atanmış sorumlu bulunamadı.');return;}
        final best=candidates.take(12).toList();int? chosen;
        final ok=await showDialog<bool>(context:ctx,builder:(d)=>StatefulBuilder(builder:(dc,update)=>AlertDialog(title:const Text('Süreye dayalı plan önerileri'),content:SizedBox(width:420,child:ListView(shrinkWrap:true,children:[Text('Görev tahmini: ${minutes(task)} dk. Kapasite ve diğer görevlerin tahmini süreleri esas alınır.'),...List.generate(best.length,(i){final c=best[i];return RadioGroup<int>(groupValue:chosen,onChanged:(v)=>update(()=>chosen=v),child:RadioListTile<int>(value:i,title:Text('${c['owner']} • ${iso(c['date'] as DateTime)}'),subtitle:Text('Kalan: ${c['remaining']} dk • Kullanılan: ${c['occupied']}/${c['capacity']} dk${(c['remaining'] as int)<0?' • AŞIM':''}')));})])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:chosen==null?null:()=>Navigator.pop(d,true),child:const Text('Planı uygula'))])));
        if(ok!=true||chosen==null||!ctx.mounted)return;final pick=best[chosen!],old=Map<String,dynamic>.from(task);
        refresh((){final before='${task['owner']??''} / ${task['due']??''}';task['owner']=pick['owner'];task['due']=iso(pick['date'] as DateTime);task['updated']=DateTime.now().toIso8601String();final h=task['history'] is List?List<dynamic>.from(task['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':'Süre bazlı planlama: $before → ${task['owner']} / ${task['due']}'});task['history']=h;});
        try{await saveActions();if(mounted)_notice('Süre bazlı görev planı kaydedildi.');}catch(_){if(ctx.mounted)refresh((){task..clear()..addAll(old);});if(mounted)_notice('Kaydetme başarısız; işlem geri alındı.');}
      }
      final report=<String>['Sorumlu;Tarih;Görev sayısı;Planlanan dakika;Kapasite dakika;Kalan dakika;Aşım',for(final g in shown)for(final e in (g['daily'] as Map<String,int>).entries)[g['owner'],e.key,(g['counts'] as Map<String,int>)[e.key],e.value,g['cap'],(g['cap'] as int)-e.value,e.value>(g['cap'] as int)?'Evet':'Hayır'].map(csv).join(';')];
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
        Text('Görev süresi / gerçek zaman kapasitesi',style:Theme.of(ctx).textTheme.titleLarge),
        const Text('Görevlerin tahmini dakika bilgisi ve kişi başına günlük kullanılabilir süre ile planlama. Eksik süre için 30 dk, eksik kapasite için 120 dk varsayılır.'),
        if(loading)const LinearProgressIndicator(),
        TextField(decoration:const InputDecoration(labelText:'Görev, ürün, sorumlu ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>query=v)),
        Wrap(spacing:8,runSpacing:6,children:[DropdownButton<int>(value:window,items:[7,14,21,28].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh(()=>window=v??7)),DropdownButton<String>(value:selectedOwner,items:['Tümü',...owners].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(anchor).subtract(Duration(days:window))),child:const Text('◀ Önceki')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(DateTime.now())),child:const Text('Bugün')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(anchor).add(Duration(days:window))),child:const Text('Sonraki ▶'))]),
        Text('Dönem: ${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
        Wrap(spacing:8,children:[FilterChip(label:const Text('Yalnız kapasite aşımı'),selected:onlyOver,onSelected:(v)=>refresh(()=>onlyOver=v)),FilterChip(label:const Text('Süresi girilmemiş görevler'),selected:onlyMissing,onSelected:(v)=>refresh(()=>onlyMissing=v))]),
        Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Text('Görev: ${visible.length} • Planlanan süre: $totalMinutes dk (${(totalMinutes/60).toStringAsFixed(1)} saat)\nSüresi eksik: $missing • Kapasite aşımı kişi-gün: $overDays • Sorumlu: ${summary.length}'))),
        OutlinedButton.icon(onPressed:()=>Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}')).then((_){if(mounted)_notice('Süre bazlı kapasite CSV kopyalandı.');}),icon:const Icon(Icons.copy),label:const Text('Kapasite CSV kopyala')),
        if(shown.isEmpty)const Padding(padding:EdgeInsets.all(16),child:Text('Bu dönemde uygun görev bulunamadı.')),
        ...shown.map((g){final who=g['owner'] as String,daily=g['daily'] as Map<String,int>,rows=g['tasks'] as List<Map<String,dynamic>>,cap=g['cap'] as int;return Card(child:ExpansionTile(title:Text('$who • ${rows.length} görev • ${g['total']} dk'),subtitle:Text('Günlük kapasite: $cap dk • Aşım: ${g['over']} gün'),children:[TextButton.icon(onPressed:()=>editCapacity(who),icon:const Icon(Icons.schedule),label:const Text('Günlük kullanılabilir süreyi düzenle')),...(daily.entries.toList()..sort((a,b)=>a.key.compareTo(b.key))).map((e)=>ListTile(dense:true,title:Text(e.key),subtitle:LinearProgressIndicator(value:(e.value/cap).clamp(0.0,1.0),color:e.value>cap?Colors.red:_purple),trailing:Text('${e.value}/$cap dk${e.value>cap?' ⚠':''}'))),...rows.map((a)=>ListTile(title:Text('${a['title']??'Görev'}'),subtitle:Text('${a['due']??''} • ${a['level']??'Orta'} • ${minutes(a)} dk${a['estimatedMinutes']==null?' (varsayılan)':''}'),trailing:Wrap(children:[IconButton(tooltip:'Tahmini süreyi düzenle',icon:const Icon(Icons.timer_outlined),onPressed:()=>editDuration(a)),IconButton(tooltip:'Süreye göre plan öner',icon:const Icon(Icons.auto_fix_high),onPressed:()=>suggest(a))])))]));}),
        const SizedBox(height:12),OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenWeeklyCapacityPlanner();},icon:const Icon(Icons.calendar_month_outlined),label:const Text('Görev sayısına göre kapasite ekranı')),
      ]))));
    }));
  }

  void _showKitchenWeeklyCapacityPlanner() {
    const storageKey='paket39_purchase_improvement_actions_v1';
    const limitsKey='paket39_weekly_capacity_limits_v1';
    final actions=<Map<String,dynamic>>[];
    final limits=<String,int>{};
    var loaded=false,loading=true,search='',filter='Tümü',horizon=7,onlyOverloaded=false,onlyLate=false;
    DateTime anchor=DateTime.now();
    DateTime? parse(Object? v)=>DateTime.tryParse((v??'').toString());
    DateTime day(DateTime d)=>DateTime(d.year,d.month,d.day);
    String iso(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains((a['status']??'Açık').toString());
    int points(Map<String,dynamic> a)=>a['level']=='Kritik'?5:a['level']=='Yüksek'?3:1;
    Future<void> saveActions()async{final p=await SharedPreferences.getInstance();await p.setString(storageKey,jsonEncode(actions));}
    Future<void> saveLimits()async{final p=await SharedPreferences.getInstance();await p.setString(limitsKey,jsonEncode(limits));}
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(ctx,refresh){
      if(!loaded){loaded=true;SharedPreferences.getInstance().then((p){
        try{final raw=jsonDecode(p.getString(storageKey)??'[]');if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}
          final l=jsonDecode(p.getString(limitsKey)??'{}');if(l is Map){for(final e in l.entries){final v=int.tryParse('${e.value}');if(v!=null&&v>=1&&v<=100)limits['${e.key}']=v;}}}
        catch(_){if(mounted)_notice('Kapasite kayıtlarının bir kısmı okunamadı.');}
        if(ctx.mounted)refresh(()=>loading=false);
      }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});}
      final start=day(anchor),end=start.add(Duration(days:horizon));
      final owners={'Atanmamış',...actions.map((a)=>(a['owner']??'').toString().trim()).where((s)=>s.isNotEmpty)}.toList()..sort();
      final visible=actions.where((a){final due=parse(a['due']);if(!active(a)||due==null)return false;final d=day(due);if(d.isBefore(start)||!d.isBefore(end))return false;final who=(a['owner']??'').toString().trim();if(filter!='Tümü'&&(who.isEmpty?'Atanmamış':who)!=filter)return false;if(onlyLate&&!d.isBefore(day(DateTime.now())))return false;return '${a['title']} ${a['product']} ${a['owner']} ${a['note']}'.toLowerCase().contains(search.toLowerCase());}).toList();
      final grouped=<String,List<Map<String,dynamic>>>{};
      for(final a in visible){final o=(a['owner']??'').toString().trim();grouped.putIfAbsent(o.isEmpty?'Atanmamış':o,()=>[]).add(a);}
      final summary=<Map<String,dynamic>>[];
      for(final entry in grouped.entries){final rows=entry.value,limit=limits[entry.key]??3;final days=<String,int>{};for(final a in rows){final d=parse(a['due']);if(d!=null){final k=iso(d);days[k]=(days[k]??0)+1;}}
        final overload=days.values.where((v)=>v>limit).length;
        summary.add({'owner':entry.key,'rows':rows,'limit':limit,'overload':overload,'peak':days.values.fold<int>(0,(a,b)=>a>b?a:b),'points':rows.fold<int>(0,(v,a)=>v+points(a)),'days':days});}
      summary.sort((a,b)=>(b['overload'] as int).compareTo(a['overload'] as int));
      final shown=summary.where((g)=>!onlyOverloaded||(g['overload'] as int)>0).toList();
      final overloaded=summary.fold<int>(0,(v,g)=>v+(g['overload'] as int));
      Future<void> changeLimit(String owner)async{
        final controller=TextEditingController(text:'${limits[owner]??3}');
        final accepted=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(title:Text('$owner • günlük görev sınırı'),content:TextField(controller:controller,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'1–100 görev / gün')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Kaydet'))]));
        final value=int.tryParse(controller.text.trim());disposeAfterDialog(controller);if(accepted!=true||value==null||value<1||value>100){if(accepted==true&&mounted)_notice('1 ile 100 arasında sınır gir.');return;}
        final old=limits[owner];refresh(()=>limits[owner]=value);
        try{await saveLimits();if(mounted)_notice('Günlük kapasite kaydedildi.');}catch(_){if(ctx.mounted)refresh((){if(old==null){limits.remove(owner);}else{limits[owner]=old;}});if(mounted)_notice('Kapasite kaydedilemedi.');}
      }
      Future<void> suggest(Map<String,dynamic> task)async{
        final due=parse(task['due']);if(due==null)return;
        final options=<Map<String,dynamic>>[];
        for(var offset=0;offset<7;offset++){
          final date=day(due).add(Duration(days:offset));
          for(final owner in owners.where((o)=>o!='Atanmamış')){
            final occupied=actions.where((a)=>active(a)&&(a['owner']??'').toString().trim()==owner&&parse(a['due'])!=null&&iso(parse(a['due'])!)==iso(date)&&!identical(a,task)).length;
            options.add({'owner':owner,'date':date,'occupied':occupied,'remaining':(limits[owner]??3)-occupied});
          }
        }
        options.sort((a,b){final c=(b['remaining'] as int).compareTo(a['remaining'] as int);return c!=0?c:(a['date'] as DateTime).compareTo(b['date'] as DateTime);});
        if(options.isEmpty){if(mounted)_notice('Öneri için önce en az bir sorumlu atanmış görev olmalı.');return;}
        final best=options.take(8).toList();Map<String,dynamic>? picked;
        final accepted=await showDialog<bool>(context:ctx,builder:(d)=>StatefulBuilder(builder:(dc,update)=>AlertDialog(title:const Text('Kapasiteye göre görev önerisi'),content:SizedBox(width:420,child:ListView(shrinkWrap:true,children:[const Text('Öneriler kayıtlı günlük görev sınırına göre sıralanır. Süre ve yetkinlik bilgisi içermez.'),...best.map((o)=>RadioGroup<int>(groupValue:picked==null?null:best.indexOf(picked!),onChanged:(v)=>update(()=>picked=v==null?null:best[v]),child:RadioListTile<int>(value:best.indexOf(o),title:Text('${o['owner']} • ${iso(o['date'] as DateTime)}'),subtitle:Text('Boş kapasite: ${o['remaining']} • Planlı: ${o['occupied']}'))))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:picked==null?null:()=>Navigator.pop(d,true),child:const Text('Uygula'))])));
        if(accepted!=true||picked==null||!ctx.mounted)return;
        final old=Map<String,dynamic>.from(task);refresh((){final previous='${task['owner']??''} / ${task['due']??''}';task['owner']=picked!['owner'];task['due']=iso(picked!['date'] as DateTime);task['updated']=DateTime.now().toIso8601String();final h=task['history'] is List?List<dynamic>.from(task['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':'Kapasite planı: $previous → ${task['owner']} / ${task['due']}'});task['history']=h;});
        try{await saveActions();if(mounted)_notice('Görev yeniden planlandı.');}catch(_){if(ctx.mounted)refresh((){task..clear()..addAll(old);});if(mounted)_notice('Kaydetme başarısız; değişiklik geri alındı.');}
      }
      final report=<String>['Sorumlu;Görev;Günlük sınır;Aşırı yüklü gün;En yoğun gün;Öncelik puanı',...shown.map((g)=>[g['owner'],(g['rows'] as List).length,g['limit'],g['overload'],g['peak'],g['points']].map(csv).join(';'))];
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
        Text('Haftalık kapasite / akıllı görev önerileri',style:Theme.of(ctx).textTheme.titleLarge),
        const Text('Günlük görev sayısına göre kapasite kontrolü. Varsayılan sınır: 3 görev/gün; gerçek çalışma saati veya kişi uygunluğu değildir.'),
        if(loading)const LinearProgressIndicator(),
        TextField(decoration:const InputDecoration(labelText:'Görev, ürün veya sorumlu ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
        Wrap(spacing:8,runSpacing:6,children:[DropdownButton<int>(value:horizon,items:[7,14,21,28].map((n)=>DropdownMenuItem(value:n,child:Text('$n gün'))).toList(),onChanged:(v)=>refresh(()=>horizon=v??7)),DropdownButton<String>(value:filter=='Tümü'||owners.contains(filter)?filter:'Tümü',items:['Tümü',...owners].map((o)=>DropdownMenuItem(value:o,child:Text(o))).toList(),onChanged:(v)=>refresh(()=>filter=v??'Tümü')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(anchor).subtract(Duration(days:horizon))),child:const Text('◀ Önceki')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(DateTime.now())),child:const Text('Bugün')),OutlinedButton(onPressed:()=>refresh(()=>anchor=day(anchor).add(Duration(days:horizon))),child:const Text('Sonraki ▶'))]),
        Text('Dönem: ${iso(start)} – ${iso(end.subtract(const Duration(days:1)))}'),
        Wrap(spacing:8,children:[FilterChip(label:const Text('Yalnız aşırı yük'),selected:onlyOverloaded,onSelected:(v)=>refresh(()=>onlyOverloaded=v)),FilterChip(label:const Text('Yalnız geciken'),selected:onlyLate,onSelected:(v)=>refresh(()=>onlyLate=v))]),
        Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Text('Aktif planlı görev: ${visible.length} • Sorumlu grubu: ${summary.length}\nKapasite aşımı olan kişi-gün: $overloaded • Kritik görev: ${visible.where((a)=>a['level']=='Kritik').length}'))),
        OutlinedButton.icon(onPressed:()=>Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}')).then((_){if(mounted)_notice('Kapasite raporu kopyalandı.');}),icon:const Icon(Icons.copy),label:const Text('CSV kopyala')),
        if(shown.isEmpty)const Padding(padding:EdgeInsets.all(16),child:Text('Seçilen dönemde görev veya aşırı yük bulunamadı.')),
        ...shown.map((g){final owner=g['owner'] as String,rows=g['rows'] as List<Map<String,dynamic>>,daily=g['days'] as Map<String,int>;return Card(child:ExpansionTile(title:Text('$owner • ${rows.length} görev'),subtitle:Text('Günlük sınır: ${g['limit']} • Aşırı yüklü gün: ${g['overload']} • En yoğun gün: ${g['peak']}'),children:[TextButton.icon(onPressed:()=>changeLimit(owner),icon:const Icon(Icons.tune),label:const Text('Günlük sınırı düzenle')),...(daily.entries.toList()..sort((a,b)=>a.key.compareTo(b.key))).map((e)=>ListTile(dense:true,title:Text(e.key),subtitle:LinearProgressIndicator(value:(e.value/(g['limit'] as int)).clamp(0.0,1.0),color:e.value>(g['limit'] as int)?Colors.red:_purple),trailing:Text('${e.value}/${g['limit']}${e.value>(g['limit'] as int)?' ⚠':''}'))),...rows.map((a)=>ListTile(title:Text((a['title']??'Görev').toString()),subtitle:Text('${a['level']??'Orta'} • ${a['due']??''}'),trailing:IconButton(icon:const Icon(Icons.auto_fix_high),tooltip:'Uygun sorumlu ve tarih öner',onPressed:()=>suggest(a))))]));}),
        const SizedBox(height:12),OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenWorkloadBalancer();},icon:const Icon(Icons.balance_outlined),label:const Text('Görev dağılımı ekranını aç')),
      ]))));
    }));
  }

  void _showKitchenWorkloadBalancer() {
    const key='paket39_purchase_improvement_actions_v1';
    final actions=<Map<String,dynamic>>[];
    var started=false,loading=true,query='',owner='Tümü',priority='Tümü',status='Aktif',sort='Yük (azalan)',window=7;
    var onlyLate=false,onlyUnassigned=false,onlyCritical=false;
    final selected=<String>{};
    DateTime today()=>DateTime(DateTime.now().year,DateTime.now().month,DateTime.now().day);
    DateTime? date(Object? value)=>DateTime.tryParse((value??'').toString());
    String id(Map<String,dynamic> a,int index)=>'${a['id']??a['created']??a['title']}_$index';
    String csv(Object? value)=>'"${(value??'').toString().replaceAll('"','""')}"';
    bool active(Map<String,dynamic> a)=>!['Tamamlandı','İptal'].contains((a['status']??'Açık').toString());
    int weight(Map<String,dynamic> a){final p=(a['level']??'Orta').toString();return p=='Kritik'?5:p=='Yüksek'?3:1;}
    Future<void> persist() async {final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(actions));}
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(outer)=>StatefulBuilder(builder:(ctx,refresh){
      if(!started){started=true;SharedPreferences.getInstance().then((p){
        try{final raw=jsonDecode(p.getString(key)??'[]');if(raw is List){actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));}}
        catch(_){if(mounted)_notice('Görev verileri okunamadı.');}
        if(ctx.mounted)refresh(()=>loading=false);
      }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});}
      final now=today();
      final names={'Tümü','Atanmamış',...actions.map((a)=>(a['owner']??'').toString().trim()).where((v)=>v.isNotEmpty)}.toList()..sort();
      if(!names.contains(owner))owner='Tümü';
      final indexed=<MapEntry<int,Map<String,dynamic>>>[];
      for(var i=0;i<actions.length;i++){
        final a=actions[i],who=(a['owner']??'').toString().trim(),due=date(a['due']);
        if(status=='Aktif'&&!active(a)||status=='Tamamlandı'&&a['status']!='Tamamlandı'||status=='İptal'&&a['status']!='İptal')continue;
        if(owner!='Tümü'&&(owner=='Atanmamış'?who.isNotEmpty:who!=owner))continue;
        if(priority!='Tümü'&&a['level']!=priority)continue;
        if(onlyLate&&(due==null||!due.isBefore(now)||!active(a)))continue;
        if(onlyUnassigned&&who.isNotEmpty||onlyCritical&&a['level']!='Kritik')continue;
        if(!'${a['title']} ${a['source']} ${a['product']} ${a['owner']} ${a['note']}'.toLowerCase().contains(query.toLowerCase()))continue;
        indexed.add(MapEntry(i,a));
      }
      final buckets=<String,List<MapEntry<int,Map<String,dynamic>>>>{};
      for(final row in indexed){final who=(row.value['owner']??'').toString().trim();buckets.putIfAbsent(who.isEmpty?'Atanmamış':who,()=>[]).add(row);}
      final stats=buckets.entries.map((e){
        final rows=e.value,late=rows.where((r){final d=date(r.value['due']);return d!=null&&d.isBefore(now)&&active(r.value);}).length;
        final near=rows.where((r){final d=date(r.value['due']);return d!=null&&!d.isBefore(now)&&d.isBefore(now.add(Duration(days:window+1)))&&active(r.value);}).length;
        final points=rows.where((r)=>active(r.value)).fold<int>(0,(v,r)=>v+weight(r.value));
        return {'name':e.key,'count':rows.length,'late':late,'near':near,'points':points,'rows':rows};
      }).toList();
      stats.sort((a,b){if(sort=='İsim')return (a['name'] as String).compareTo(b['name'] as String);if(sort=='Geciken')return (b['late'] as int).compareTo(a['late'] as int);if(sort=='Görev sayısı')return (b['count'] as int).compareTo(a['count'] as int);return (b['points'] as int).compareTo(a['points'] as int);});
      final totalPoints=stats.fold<int>(0,(v,e)=>v+(e['points'] as int));
      final average=stats.isEmpty?0.0:totalPoints/stats.length;
      final report=<String>['Sorumlu;Görev;Geciken;Yaklaşan;Ağırlıklı yük',...stats.map((e)=>[e['name'],e['count'],e['late'],e['near'],e['points']].map(csv).join(';'))];
      final validIds=indexed.map((e)=>id(e.value,e.key)).toSet();selected.removeWhere((v)=>!validIds.contains(v));
      Future<void> batch({required bool reassign}) async {
        if(selected.isEmpty){if(mounted)_notice('Önce görev seç.');return;}
        final chosen=indexed.where((e)=>selected.contains(id(e.value,e.key))).toList();
        final input=TextEditingController();
        DateTime target=now.add(const Duration(days:3));
        final accepted=await showDialog<bool>(context:ctx,builder:(dialog)=>StatefulBuilder(builder:(d,update)=>AlertDialog(
          title:Text(reassign?'Toplu sorumlu değiştir':'Toplu yeniden planla'),
          content:Column(mainAxisSize:MainAxisSize.min,children:[Text('${chosen.length} görev güncellenecek.'),if(reassign)TextField(controller:input,maxLength:80,decoration:const InputDecoration(labelText:'Yeni sorumlu')),if(!reassign)ListTile(title:Text('${target.day}.${target.month}.${target.year}'),trailing:const Icon(Icons.calendar_month),onTap:()async{final p=await showDatePicker(context:d,initialDate:target,firstDate:DateTime(2020),lastDate:DateTime(2100));if(p!=null)update(()=>target=p);})]),
          actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Onayla'))],
        )));
        if(accepted!=true||!ctx.mounted){disposeAfterDialog(input);return;}
        final newOwner=input.text.trim();disposeAfterDialog(input);
        if(reassign&&newOwner.isEmpty){if(mounted)_notice('Sorumlu boş bırakılamaz.');return;}
        final backup=chosen.map((e)=>Map<String,dynamic>.from(e.value)).toList();
        refresh((){for(final e in chosen){final a=e.value;final before=(reassign?a['owner']:a['due'])?.toString()??'';if(reassign){a['owner']=newOwner;}else{a['due']='${target.year}-${target.month.toString().padLeft(2,'0')}-${target.day.toString().padLeft(2,'0')}';}a['updated']=DateTime.now().toIso8601String();final h=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];h.add({'at':DateTime.now().toIso8601String(),'event':reassign?'Sorumlu: $before → $newOwner':'Hedef tarih: $before → ${a['due']}'});a['history']=h;}});
        try{await persist();if(ctx.mounted)refresh(()=>selected.clear());if(mounted)_notice('${chosen.length} görev güncellendi.');}
        catch(_){if(ctx.mounted)refresh((){for(var i=0;i<chosen.length;i++){chosen[i].value..clear()..addAll(backup[i]);}});if(mounted)_notice('Kaydetme başarısız; değişiklikler geri alındı.');}
      }
      Widget dropdown(String value,List<String> values,ValueChanged<String?> change)=>DropdownButton<String>(value:values.contains(value)?value:values.first,isExpanded:true,items:values.map((v)=>DropdownMenuItem(value:v,child:Text(v,overflow:TextOverflow.ellipsis))).toList(),onChanged:change);
      return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
        Text('Akıllı görev dağılımı / iş yükü dengeleme',style:Theme.of(ctx).textTheme.titleLarge),
        const Text('Aksiyon kayıtlarına dayalı iş yükü; ağırlıklar Kritik=5, Yüksek=3, Orta=1. Tahmini çalışma saati değildir.'),
        if(loading)const LinearProgressIndicator(),
        TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev, ürün, kaynak veya sorumlu ara'),onChanged:(v)=>refresh(()=>query=v)),
        Wrap(spacing:8,children:[SizedBox(width:135,child:dropdown(status,['Aktif','Tümü','Tamamlandı','İptal'],(v)=>refresh(()=>status=v??'Aktif'))),SizedBox(width:130,child:dropdown(priority,['Tümü','Kritik','Yüksek','Orta'],(v)=>refresh(()=>priority=v??'Tümü'))),SizedBox(width:155,child:dropdown(owner,names,(v)=>refresh(()=>owner=v??'Tümü'))),SizedBox(width:135,child:dropdown(sort,['Yük (azalan)','Geciken','Görev sayısı','İsim'],(v)=>refresh(()=>sort=v??'Yük (azalan'))),SizedBox(width:110,child:dropdown('$window',['3','7','14','30','60'],(v)=>refresh(()=>window=int.tryParse(v??'7')??7)))]),
        Wrap(spacing:6,children:[FilterChip(label:const Text('Gecikenler'),selected:onlyLate,onSelected:(v)=>refresh(()=>onlyLate=v)),FilterChip(label:const Text('Atanmamış'),selected:onlyUnassigned,onSelected:(v)=>refresh(()=>onlyUnassigned=v)),FilterChip(label:const Text('Kritik'),selected:onlyCritical,onSelected:(v)=>refresh(()=>onlyCritical=v))]),
        Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Text('Görev: ${indexed.length}  •  Sorumlu grubu: ${stats.length}  •  Ağırlıklı yük: $totalPoints\nGrup başına ortalama: ${average.toStringAsFixed(1)} puan  •  Seçilen: ${selected.length}'))),
        Wrap(spacing:8,runSpacing:6,children:[OutlinedButton.icon(onPressed:indexed.isEmpty?null:()=>refresh((){selected..clear()..addAll(indexed.map((e)=>id(e.value,e.key)));}),icon:const Icon(Icons.select_all),label:const Text('Tümünü seç')),OutlinedButton(onPressed:selected.isEmpty?null:()=>refresh(()=>selected.clear()),child:const Text('Seçimi kaldır')),FilledButton.tonalIcon(onPressed:selected.isEmpty?null:()=>batch(reassign:true),icon:const Icon(Icons.person_add_alt),label:const Text('Sorumlu ata')),FilledButton.tonalIcon(onPressed:selected.isEmpty?null:()=>batch(reassign:false),icon:const Icon(Icons.event_repeat),label:const Text('Tarih planla')),OutlinedButton.icon(onPressed:()=>Clipboard.setData(ClipboardData(text:'\uFEFF${report.join('\r\n')}')).then((_){if(mounted)_notice('İş yükü raporu kopyalandı.');}),icon:const Icon(Icons.copy),label:const Text('CSV kopyala'))]),
        if(stats.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('Seçilen filtrelerde görev bulunamadı.')),
        ...stats.map((group){final rows=group['rows'] as List<MapEntry<int,Map<String,dynamic>>>;final points=group['points'] as int;return Card(child:ExpansionTile(initiallyExpanded:stats.length<=3,title:Text('${group['name']} • ${group['count']} görev'),subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Yük: $points puan • Geciken: ${group['late']} • $window günde: ${group['near']}'),LinearProgressIndicator(value:totalPoints==0?0:points/totalPoints,color:_purple)]),children:rows.map((entry){final a=entry.value,identifier=id(a,entry.key),due=date(a['due']);return CheckboxListTile(value:selected.contains(identifier),onChanged:(v)=>refresh((){if(v==true){selected.add(identifier);}else{selected.remove(identifier);}}),title:Text((a['title']??'Görev').toString()),subtitle:Text('${a['level']??'Orta'} • ${a['status']??'Açık'} • ${due==null?'Tarihsiz':'${due.day}.${due.month}.${due.year}'}${due!=null&&due.isBefore(now)&&active(a)?' • Gecikti':''}'),secondary:Icon(a['level']=='Kritik'?Icons.priority_high:Icons.task_alt,color:a['level']=='Kritik'?Colors.red:_purple));}).toList()));}),
        const SizedBox(height:12),OutlinedButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenOperationsCalendar();},icon:const Icon(Icons.calendar_month),label:const Text('Görev takvimini aç')),
      ]))));
    }));
  }

  void _showKitchenOperationsCalendar() {
    const storageKey = 'paket39_purchase_improvement_actions_v1';
    final actions = <Map<String,dynamic>>[];
    var loading = true, started = false, search = '', status = 'Tümü', priority = 'Tümü', ownerFilter = 'Tümü', ordering = 'Hedef tarihi';
    var days = 7, onlyLate = false, onlyAssigned = false, includeWithoutDate = true, groupByOwner = false;
    DateTime anchor = DateTime.now();
    DateTime? parse(Object? v) => DateTime.tryParse((v ?? '').toString());
    DateTime dateOnly(DateTime d) => DateTime(d.year,d.month,d.day);
    String day(DateTime d) => '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String iso(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String csv(Object? v) => '"${(v??'').toString().replaceAll('"','""')}"';
    int level(String s) => s=='Kritik'?0:s=='Yüksek'?1:2;
    Future<void> save() async {
      final prefs=await SharedPreferences.getInstance();
      await prefs.setString(storageKey,jsonEncode(actions));
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>
      StatefulBuilder(builder:(ctx,refresh){
        if(!started){
          started=true;
          SharedPreferences.getInstance().then((prefs){
            try {
              final data=jsonDecode(prefs.getString(storageKey)??'[]');
              if(data is! List) throw const FormatException('Beklenmeyen kayıt');
              actions..clear()..addAll(data.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
            }catch(_){if(mounted)_notice('Görev kayıtları okunamadı; kayıtlar değiştirilmedi.');}
            if(ctx.mounted)refresh(()=>loading=false);
          }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});
        }
        final today=dateOnly(DateTime.now());
        final start=dateOnly(anchor);
        final end=start.add(Duration(days:days-1));
        final owners={'Tümü',...actions.map((a)=>(a['owner']??'').toString().trim()).where((v)=>v.isNotEmpty)}.toList()..sort();
        final chosenOwner=owners.contains(ownerFilter)?ownerFilter:'Tümü';
        final rows=actions.where((a){
          final due=parse(a['due']);
          final s=(a['status']??'Açık').toString();
          final o=(a['owner']??'').toString().trim();
          if(status!='Tümü' && s!=status)return false;
          if(priority!='Tümü' && a['level']!=priority)return false;
          if(chosenOwner!='Tümü' && o!=chosenOwner)return false;
          if(onlyAssigned && o.isEmpty)return false;
          if(onlyLate && (due==null || !dateOnly(due).isBefore(today) || s=='Tamamlandı' || s=='İptal'))return false;
          if(!onlyLate && (due==null?!includeWithoutDate:dateOnly(due).isBefore(start)||dateOnly(due).isAfter(end)))return false;
          return '${a['title']} ${a['product']} ${a['source']} ${a['owner']} ${a['note']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        rows.sort((a,b){
          if(ordering=='Öncelik'){
            final c=level((a['level']??'Orta').toString()).compareTo(level((b['level']??'Orta').toString()));if(c!=0)return c;
          }
          if(ordering=='Sorumlu'){
            final c=(a['owner']??'').toString().compareTo((b['owner']??'').toString());if(c!=0)return c;
          }
          if(ordering=='Durum'){
            final c=(a['status']??'').toString().compareTo((b['status']??'').toString());if(c!=0)return c;
          }
          final da=parse(a['due'])??DateTime(9999),db=parse(b['due'])??DateTime(9999);
          return da.compareTo(db);
        });
        final completed=rows.where((a)=>a['status']=='Tamamlandı').length;
        final active=rows.where((a)=>a['status']!='Tamamlandı'&&a['status']!='İptal').length;
        final late=rows.where((a){final d=parse(a['due']);return d!=null&&dateOnly(d).isBefore(today)&&a['status']!='Tamamlandı'&&a['status']!='İptal';}).length;
        final upcoming=rows.where((a){final d=parse(a['due']);return d!=null&&!dateOnly(d).isBefore(today)&&!dateOnly(d).isAfter(today.add(const Duration(days:3)))&&a['status']!='Tamamlandı'&&a['status']!='İptal';}).length;
        final assigned=rows.where((a)=>(a['owner']??'').toString().trim().isNotEmpty).length;
        final critical=rows.where((a)=>a['level']=='Kritik'&&a['status']!='Tamamlandı').length;
        final onTime=rows.where((a){final due=parse(a['due']),done=parse(a['completed']);return a['status']=='Tamamlandı'&&due!=null&&done!=null&&!dateOnly(done).isAfter(dateOnly(due));}).length;
        final measured=rows.where((a)=>a['status']=='Tamamlandı'&&parse(a['due'])!=null&&parse(a['completed'])!=null).length;
        final durationRows=rows.where((a)=>a['status']=='Tamamlandı'&&parse(a['created'])!=null&&parse(a['completed'])!=null).toList();
        final avgDuration=durationRows.isEmpty?null:durationRows.map((a)=>parse(a['completed'])!.difference(parse(a['created'])!).inHours/24).reduce((a,b)=>a+b)/durationRows.length;
        final byOwner=<String,List<Map<String,dynamic>>>{};
        for(final a in rows){byOwner.putIfAbsent((a['owner']??'').toString().trim().isEmpty?'Atanmamış':a['owner'].toString().trim(),()=>[]).add(a);}
        final export=<String>['Başlık;Sorumlu;Öncelik;Durum;Hedef;Oluşturma;Tamamlanma;Kaynak;Gecikme günü',
          ...rows.map((a){final d=parse(a['due']);final overdue=d!=null&&dateOnly(d).isBefore(today)&&a['status']!='Tamamlandı'&&a['status']!='İptal'?today.difference(dateOnly(d)).inDays:0;
            return [a['title'],a['owner'],a['level'],a['status'],a['due'],a['created'],a['completed'],a['source'],overdue].map(csv).join(';');})];
        Widget metric(String label,String value)=>Card(color:_pink,child:Padding(padding:const EdgeInsets.all(10),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(label,style:const TextStyle(fontSize:12)),Text(value,style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold))])));
        Future<void> changeStatus(Map<String,dynamic> a,String value) async {
          final previous=(a['status']??'Açık').toString();
          final before=Map<String,dynamic>.from(a);
          refresh((){
            a['status']=value;
            a['updated']=DateTime.now().toIso8601String();
            a['completed']=value=='Tamamlandı'?DateTime.now().toIso8601String():'';
            final history=a['history'] is List?List<dynamic>.from(a['history'] as List):<dynamic>[];
            history.add({'at':DateTime.now().toIso8601String(),'event':'Durum: $previous → $value'});
            a['history']=history;
          });
          try{await save();if(mounted)_notice('Görev durumu güncellendi.');}
          catch(_){refresh((){a..clear()..addAll(before);});if(mounted)_notice('Kaydetme başarısız; değişiklik geri alındı.');}
        }
        Future<void> changeDue(Map<String,dynamic> a) async {
          final current=parse(a['due'])??today;
          final picked=await showDatePicker(context:ctx,initialDate:current,firstDate:DateTime(2020),lastDate:DateTime(2100));
          if(picked==null||!ctx.mounted)return;
          final old=Map<String,dynamic>.from(a);
          refresh((){a['due']=iso(picked);a['updated']=DateTime.now().toIso8601String();});
          try{await save();}catch(_){refresh((){a..clear()..addAll(old);});if(mounted)_notice('Hedef tarihi kaydedilemedi.');}
        }
        Widget task(Map<String,dynamic> a){
          final due=parse(a['due']);final done=a['status']=='Tamamlandı';
          final overdue=due!=null&&dateOnly(due).isBefore(today)&&!done&&a['status']!='İptal';
          return Card(child:ExpansionTile(
            leading:Icon(done?Icons.check_circle:overdue?Icons.warning_amber:Icons.event_note,color:done?Colors.green:overdue?Colors.red:_purple),
            title:Text((a['title']??'Görev').toString(),style:const TextStyle(fontWeight:FontWeight.w600)),
            subtitle:Text('${a['level']??'Orta'} • ${a['status']??'Açık'} • ${a['owner']?.toString().isNotEmpty==true?a['owner']:'Atanmamış'}\n${due==null?'Tarih yok':day(due)}${overdue?' • ${today.difference(dateOnly(due)).inDays} gün gecikti':''}'),
            children:[Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Kaynak: ${a['source']??'—'}'),Text('Ürün: ${a['product']??'—'}'),Text('Not: ${a['note']??'—'}'),
              Text('Oluşturma: ${a['created']??'—'}'),Text('Tamamlanma: ${a['completed']??'—'}'),
              Wrap(spacing:8,runSpacing:4,children:[
                DropdownButton<String>(value:['Açık','Devam ediyor','Beklemede','Tamamlandı','İptal'].contains(a['status'])?a['status'].toString():'Açık',
                  items:['Açık','Devam ediyor','Beklemede','Tamamlandı','İptal'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:loading?null:(v){if(v!=null)changeStatus(a,v);}),
                OutlinedButton.icon(onPressed:()=>changeDue(a),icon:const Icon(Icons.edit_calendar),label:const Text('Tarihi değiştir')),
              ]),
              if(a['history'] is List)for(final e in (a['history'] as List).whereType<Map>().toList().reversed.take(5))Text('• ${e['at']??'—'}: ${e['event']??'—'}',style:const TextStyle(fontSize:11)),
            ]))]));
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(14),children:[
          Row(children:[const Expanded(child:Text('Günlük / Haftalık Operasyon Takvimi',style:TextStyle(fontWeight:FontWeight.bold,fontSize:19,color:_purple))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Kayıtlı aksiyonlar üzerinden takvim ve sorumlu iş yükü hesaplanır. Stok veya alışveriş kayıtları değiştirilmez.',style:TextStyle(fontSize:12)),
          if(loading)const LinearProgressIndicator(),
          Wrap(spacing:5,runSpacing:5,children:[for(final d in [1,3,7,14,30,60,90])ChoiceChip(label:Text('$d gün'),selected:days==d,onSelected:(_)=>refresh(()=>days=d))]),
          Row(children:[IconButton(onPressed:()=>refresh(()=>anchor=anchor.subtract(Duration(days:days))),icon:const Icon(Icons.chevron_left)),
            Expanded(child:Text('${day(start)} – ${day(end)}',textAlign:TextAlign.center)),
            IconButton(onPressed:()=>refresh(()=>anchor=anchor.add(Duration(days:days))),icon:const Icon(Icons.chevron_right)),
            TextButton(onPressed:()=>refresh(()=>anchor=DateTime.now()),child:const Text('Bugün'))]),
          Wrap(spacing:8,runSpacing:5,children:[
            DropdownButton<String>(value:status,items:['Tümü','Açık','Devam ediyor','Beklemede','Tamamlandı','İptal'].map((v)=>DropdownMenuItem(value:v,child:Text('Durum: $v'))).toList(),onChanged:(v)=>refresh(()=>status=v??'Tümü')),
            DropdownButton<String>(value:priority,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text('Öncelik: $v'))).toList(),onChanged:(v)=>refresh(()=>priority=v??'Tümü')),
            DropdownButton<String>(value:chosenOwner,items:owners.map((v)=>DropdownMenuItem(value:v,child:Text('Sorumlu: $v'))).toList(),onChanged:(v)=>refresh(()=>ownerFilter=v??'Tümü')),
            DropdownButton<String>(value:ordering,items:['Hedef tarihi','Öncelik','Sorumlu','Durum'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>ordering=v??'Hedef tarihi')),
          ]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Görev, ürün, kaynak veya sorumlu ara'),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:5,children:[
            FilterChip(label:const Text('Gecikenler'),selected:onlyLate,onSelected:(v)=>refresh(()=>onlyLate=v)),
            FilterChip(label:const Text('Atananlar'),selected:onlyAssigned,onSelected:(v)=>refresh(()=>onlyAssigned=v)),
            FilterChip(label:const Text('Tarihsizler'),selected:includeWithoutDate,onSelected:(v)=>refresh(()=>includeWithoutDate=v)),
            FilterChip(label:const Text('Sorumluya göre grupla'),selected:groupByOwner,onSelected:(v)=>refresh(()=>groupByOwner=v)),
          ]),
          Wrap(spacing:5,runSpacing:5,children:[metric('Görev','${rows.length}'),metric('Açık','$active'),metric('Tamamlanan','$completed'),metric('Geciken','$late'),metric('3 gün içinde','$upcoming'),metric('Kritik','$critical'),metric('Atanan','$assigned'),metric('Tamamlanma','${rows.isEmpty?0:(completed*100/rows.length).round()}%')]),
          Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Zamanında tamamlanan: $onTime / $measured ölçülebilen'),
            Text('Ortalama tamamlanma: ${avgDuration==null?'Veri yok':'${avgDuration.toStringAsFixed(1)} gün'}'),
            const Text('Oranlar seçili filtredeki görevleri temel alır; tarihsiz ve iptal edilmiş görevler toplamı etkileyebilir.',style:TextStyle(fontSize:11)),
          ]))),
          if(groupByOwner)for(final entry in byOwner.entries)Card(child:ExpansionTile(
            title:Text('${entry.key} • ${entry.value.length} görev'),
            subtitle:Text('${entry.value.where((a)=>a['status']=='Tamamlandı').length} tamamlandı • ${entry.value.where((a){final d=parse(a['due']);return d!=null&&dateOnly(d).isBefore(today)&&a['status']!='Tamamlandı'&&a['status']!='İptal';}).length} gecikmiş'),
            children:[for(final a in entry.value)task(a)])),
          if(!groupByOwner)for(var d=0;d<days;d++)if(rows.any((a){final due=parse(a['due']);return due!=null&&dateOnly(due)==start.add(Duration(days:d));}))
            Card(child:ExpansionTile(initiallyExpanded:d==0,title:Text(day(start.add(Duration(days:d)))),children:[
              for(final a in rows.where((a){final due=parse(a['due']);return due!=null&&dateOnly(due)==start.add(Duration(days:d));}))task(a)])),
          if(!groupByOwner && (onlyLate||includeWithoutDate))...[
            if(onlyLate)for(final a in rows)task(a),
            if(!onlyLate)for(final a in rows.where((a)=>parse(a['due'])==null))task(a),
          ],
          if(rows.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('Seçilen dönemde veya filtrelerde görev bulunamadı.')),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${export.join('\r\n')}'));if(mounted)_notice('Görev takvimi CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Görev takvimini CSV kopyala')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt),label:const Text('Aksiyon planlarını aç')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenDailyDecisionActions();},icon:const Icon(Icons.playlist_add_check),label:const Text('Günlük kararları aç')),
        ])));
      }));
  }

  void _showKitchenDailyDecisionActions() {
    const actionKey='paket39_purchase_improvement_actions_v1';
    final actions=<Map<String,dynamic>>[];
    var loaded=false, loading=true, query='', filter='Tümü', sort='Öncelik';
    var horizon=7, selectedOnly=false, showLinked=true;
    final selected=<String>{};
    final owner=TextEditingController();
    DateTime? parse(Object? v)=>DateTime.tryParse((v??'').toString());
    String date(DateTime d)=>'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
    String quote(Object? v)=>'"${(v??'').toString().replaceAll('"','""')}"';
    int weight(String s)=>s=='Kritik'?0:s=='Yüksek'?1:2;
    Future<void> persist() async {
      final prefs=await SharedPreferences.getInstance();
      await prefs.setString(actionKey,jsonEncode(actions));
    }
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>
      StatefulBuilder(builder:(ctx,refresh){
        if(!loaded){
          loaded=true;
          SharedPreferences.getInstance().then((prefs){
            try{
              final raw=jsonDecode(prefs.getString(actionKey)??'[]');
              if(raw is! List) throw const FormatException('Aksiyon kayıtları');
              actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
            }catch(_){if(mounted)_notice('Aksiyon kayıtları okunamadı. Mevcut veriler değiştirilmedi.');}
            if(ctx.mounted)refresh(()=>loading=false);
          }).catchError((Object _){if(ctx.mounted)refresh(()=>loading=false);});
        }
        final now=DateTime.now();
        final today=DateTime(now.year,now.month,now.day);
        final suggestions=<Map<String,dynamic>>[];
        void suggest(String type,String title,String source,String priority,String detail,String advice,{DateTime? due,double cost=0}){
          final id='$type::$source::$title';
          if(suggestions.any((r)=>r['id']==id))return;
          final linked=actions.any((a)=>a['decisionId']==id && a['status']!='Tamamlandı');
          suggestions.add({'id':id,'type':type,'title':title,'source':source,'priority':priority,
            'detail':detail,'advice':advice,'due':due,'cost':cost,'linked':linked});
        }
        for(final record in _namedLists){
          final title=(record['title']??'Adsız liste').toString();
          final due=parse(record['replenishmentOrderDate']);
          final purchases=record['marketPurchases'] is Map?record['marketPurchases'] as Map:const <String,dynamic>{};
          final priorities=record['replenishmentPriorities'] is Map?record['replenishmentPriorities'] as Map:const <String,dynamic>{};
          for(final raw in (record['items'] as List? ?? const [])){
            final name=raw.toString();
            final planned=_planNum(_namedQuantity(record,name)['amount']);
            final purchase=purchases[name] is Map?purchases[name] as Map:const <String,dynamic>{};
            final bought=_planNum(purchase['quantity']);
            final remaining=(planned-bought).clamp(0.0,double.infinity).toDouble();
            if(remaining<=0)continue;
            final urgent=priorities[name]=='Zorunlu';
            final cost=_namedItemTotal(record,name);
            if(due!=null && DateTime(due.year,due.month,due.day).isBefore(today)){
              suggest('Geciken alışveriş',name,title,urgent?'Kritik':'Yüksek',
                '${today.difference(DateTime(due.year,due.month,due.day)).inDays} gün gecikti • ${remaining.toStringAsFixed(2)} eksik',
                'Kalan miktarın satın alınması için market ve sorumlu belirle.',due:today,cost:cost);
            }else if(due!=null && !due.isAfter(today.add(Duration(days:horizon)))){
              suggest('Yaklaşan alışveriş',name,title,urgent?'Yüksek':'Orta',
                'Planlanan tarih ${date(due)} • ${remaining.toStringAsFixed(2)} eksik',
                'Alışveriş hazırlığını tamamla.',due:due,cost:cost);
            }
            if(bought>0 && remaining>0) {
              suggest('Kısmi alım',name,title,urgent?'Yüksek':'Orta',
              '${remaining.toStringAsFixed(2)} miktar eksik','Eksik miktar için tamamlayıcı alışveriş planla.',due:today.add(const Duration(days:2)),cost:cost);
            }
            if(urgent) {
              suggest('Kritik ihtiyaç',name,title,'Kritik','Zorunlu ürün • açık miktar ${remaining.toStringAsFixed(2)}',
              'Stok ve tedarik durumunu kontrol et.',due:today.add(const Duration(days:1)),cost:cost);
            }
            if(cost<=0) {
              suggest('Eksik fiyat',name,title,'Orta','Planlanan maliyet girilmemiş',
              'Güncel fiyatı ve bütçe karşılığını kaydet.',due:today.add(const Duration(days:3)));
            }
          }
        }
        for(final a in actions){
          final status=(a['status']??'Açık').toString();
          final due=parse(a['due']);
          if(status!='Tamamlandı' && due!=null && DateTime(due.year,due.month,due.day).isBefore(today)){
            suggest('Geciken aksiyon',(a['title']??'Aksiyon').toString(),(a['source']??'Aksiyon planı').toString(),
              'Yüksek','Hedef tarih ${date(due)}','Aksiyon sorumlusu ve hedef tarihini gözden geçir.',due:today);
          }
        }
        final linkedCount=suggestions.where((r)=>r['linked']==true).length;
        final visible=suggestions.where((r){
          if(!showLinked && r['linked']==true)return false;
          if(selectedOnly && !selected.contains(r['id']))return false;
          if(filter!='Tümü' && r['priority']!=filter && r['type']!=filter)return false;
          return '${r['title']} ${r['source']} ${r['type']} ${r['detail']}'.toLowerCase().contains(query.toLowerCase());
        }).toList();
        visible.sort((a,b){
          if(sort=='Tarih')return ((a['due'] as DateTime?)?.toIso8601String()??'9999').compareTo((b['due'] as DateTime?)?.toIso8601String()??'9999');
          if(sort=='Maliyet')return (b['cost'] as double).compareTo(a['cost'] as double);
          if(sort=='Başlık')return (a['title'] as String).compareTo(b['title'] as String);
          final v=weight(a['priority'] as String).compareTo(weight(b['priority'] as String));
          return v!=0?v:(a['title'] as String).compareTo(b['title'] as String);
        });
        final pending=visible.where((r)=>r['linked']!=true).toList();
        final export=<String>[
          ['Tür','Ürün / konu','Kaynak','Öncelik','Açıklama','Öneri','Hedef tarih','Maliyet','Açık aksiyon bağlantısı'].map(quote).join(','),
          for(final r in visible)[r['type'],r['title'],r['source'],r['priority'],r['detail'],r['advice'],r['due'] is DateTime?date(r['due'] as DateTime):'',r['cost'],r['linked']==true?'Evet':'Hayır'].map(quote).join(',')
        ];
        Future<void> createSelected() async{
          final rows=suggestions.where((r)=>selected.contains(r['id']) && r['linked']!=true).toList();
          if(rows.isEmpty){_notice('Aktarılacak yeni karar seçilmedi.');return;}
          final confirmed=await showDialog<bool>(context:ctx,builder:(dialog)=>AlertDialog(
            title:const Text('Toplu aksiyon oluştur'),content:Text('${rows.length} karar aksiyon planına eklenecek. Stok ve satın alma kayıtları değişmeyecek.'),
            actions:[TextButton(onPressed:()=>Navigator.pop(dialog,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(dialog,true),child:const Text('Onayla'))]));
          if(confirmed!=true||!ctx.mounted)return;
          final stamp=DateTime.now().toIso8601String();
          var added=0;
          for(final r in rows){
            final id=r['id'] as String;
            if(actions.any((a)=>a['decisionId']==id && a['status']!='Tamamlandı'))continue;
            final due=r['due'] is DateTime?r['due'] as DateTime:today.add(Duration(days:weight(r['priority'] as String)+1));
            actions.add({'id':'${DateTime.now().microsecondsSinceEpoch}_${added++}',
              'decisionId':id,'title':'${r['type']}: ${r['title']}','product':r['title'],
              'source':r['source'],'owner':owner.text.trim(),'level':r['priority'],'status':'Açık',
              'note':'${r['detail']}\nÖneri: ${r['advice']}','due':date(due),
              'created':stamp,'completed':''});
          }
          try{await persist();if(ctx.mounted)refresh((){selected.clear();});if(mounted)_notice('$added aksiyon oluşturuldu.');}
          catch(_){if(mounted)_notice('Aksiyonlar kaydedilemedi; lütfen tekrar deneyin.');}
        }
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[
          Row(children:[const Expanded(child:Text('Günlük Operasyon Planı • Toplu Aksiyonlar',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),
            IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          if(loading)const LinearProgressIndicator(),
          Wrap(spacing:8,runSpacing:6,children:[
            Chip(label:Text('Karar: ${suggestions.length}')),
            Chip(label:Text('Kritik: ${suggestions.where((r)=>r['priority']=='Kritik').length}')),
            Chip(label:Text('Bağlı: $linkedCount')),
            Chip(label:Text('Seçili: ${selected.length}')),
          ]),
          Wrap(spacing:8,runSpacing:4,children:[
            DropdownButton<int>(value:horizon,items:[1,3,7,14,30].map((v)=>DropdownMenuItem(value:v,child:Text('$v gün'))).toList(),onChanged:(v)=>refresh((){horizon=v??7;selected.clear();})),
            DropdownButton<String>(value:filter,items:['Tümü','Kritik','Yüksek','Orta','Geciken alışveriş','Yaklaşan alışveriş','Kısmi alım','Kritik ihtiyaç','Eksik fiyat','Geciken aksiyon'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>filter=v??'Tümü')),
            DropdownButton<String>(value:sort,items:['Öncelik','Tarih','Maliyet','Başlık'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'Öncelik')),
            FilterChip(label:const Text('Yalnız seçilenler'),selected:selectedOnly,onSelected:(v)=>refresh(()=>selectedOnly=v)),
            FilterChip(label:const Text('Bağlı aksiyonlar'),selected:showLinked,onSelected:(v)=>refresh(()=>showLinked=v)),
          ]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Ürün, liste, risk veya karar ara'),onChanged:(v)=>refresh(()=>query=v)),
          TextField(controller:owner,decoration:const InputDecoration(labelText:'Yeni aksiyonların sorumlusu (isteğe bağlı)',isDense:true)),
          Wrap(spacing:8,runSpacing:4,children:[
            OutlinedButton.icon(onPressed:()=>refresh((){selected.addAll(pending.map((r)=>r['id'] as String));}),icon:const Icon(Icons.select_all),label:const Text('Görünen yeni kararları seç')),
            OutlinedButton.icon(onPressed:()=>refresh(selected.clear),icon:const Icon(Icons.deselect),label:const Text('Seçimi temizle')),
            FilledButton.icon(onPressed:loading?null:createSelected,icon:const Icon(Icons.add_task),label:const Text('Seçilenleri aksiyona dönüştür')),
          ]),
          Expanded(child:visible.isEmpty?const Center(child:Text('Filtreye uygun karar bulunamadı.')):ListView.builder(itemCount:visible.length,itemBuilder:(_,i){
            final r=visible[i];final id=r['id'] as String;final linked=r['linked']==true;
            return Card(child:CheckboxListTile(value:selected.contains(id),onChanged:linked?null:(v)=>refresh((){if(v==true){selected.add(id);}else{selected.remove(id);}}),
              title:Text('${r['priority']} • ${r['type']} • ${r['title']}'),
              subtitle:Text('${r['source']}\n${r['detail']}\nÖneri: ${r['advice']}\n${r['due'] is DateTime?'Hedef: ${date(r['due'] as DateTime)} • ':''}${linked?'Açık aksiyon zaten var':'Aksiyon oluşturulabilir'}'),
              isThreeLine:true,secondary:Icon(linked?Icons.link:Icons.assignment_outlined,color:_purple)));
          })),
          Wrap(spacing:8,children:[
            TextButton.icon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${export.join('\r\n')}'));if(mounted)_notice('Karar raporu CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('CSV kopyala')),
            TextButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt),label:const Text('Aksiyonları yönet')),
            TextButton.icon(onPressed:(){Navigator.pop(ctx);_showKitchenDecisionSupportCenter();},icon:const Icon(Icons.insights),label:const Text('Karar destek merkezi')),
          ])
        ]))));
      }));
  }

  void _showKitchenDecisionSupportCenter() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    const goalKey = 'kitchen_risk_reduction_goals_v1';
    const riskKey = 'kitchen_risk_tracking_v1';
    final actions = <Map<String,dynamic>>[];
    final goals = <Map<String,dynamic>>[];
    final history = <Map<String,dynamic>>[];
    var started = false;
    var loadingError = '';
    var period = 90;
    var search = '';
    var category = 'Tümü';
    var level = 'Tümü';
    var sort = 'Risk puanı';
    var onlyOpen = true;
    var onlyCritical = false;
    var maxRows = 100;
    var dueSoon = 7;
    DateTime? parse(Object? value) => DateTime.tryParse((value ?? '').toString());
    String quote(Object? value) => '"${(value ?? '').toString().replaceAll('"','""')}"';
    String dateLabel(DateTime? value) => value == null ? '—' : '${value.day.toString().padLeft(2,'0')}.${value.month.toString().padLeft(2,'0')}.${value.year}';
    int scoreLevel(String value) => value == 'Kritik' ? 3 : value == 'Yüksek' ? 2 : 1;
    showModalBottomSheet<void>(context:context,isScrollControlled:true,
      builder: (_) => StatefulBuilder(builder:(ctx, refresh) {
        if (!started) {
          started = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final a=jsonDecode(prefs.getString(actionKey)??'[]');
              final g=jsonDecode(prefs.getString(goalKey)??'[]');
              final h=jsonDecode(prefs.getString(riskKey)??'{}');
              if(a is! List || g is! List || h is! Map) throw const FormatException('Beklenmeyen kayıt yapısı');
              actions.addAll(a.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
              goals.addAll(g.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
              history.addAll(h.values.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)));
            } catch (_) {loadingError='Bazı yerel kayıtlar okunamadı. Veriler değiştirilmedi.';}
            if(ctx.mounted) refresh((){});
          }).catchError((Object _) {if(ctx.mounted) refresh(()=>loadingError='Yerel kayıtlar açılamadı.');});
        }
        final now=DateTime.now();
        final today=DateTime(now.year,now.month,now.day);
        final cutoff=today.subtract(Duration(days:period));
        final rows=<Map<String,dynamic>>[];
        void add(String type,String severity,String title,String detail,String suggestion,
          {String source='',String status='Açık',DateTime? due,double cost=0,int weight=0}) {
          final score=(scoreLevel(severity)*20+weight).clamp(0,100);
          rows.add({'type':type,'level':severity,'title':title,'detail':detail,
            'suggestion':suggestion,'source':source,'status':status,'due':due,
            'cost':cost,'score':score});
        }
        var scanned=0, completed=0, partial=0, late=0, missingPrice=0, critical=0;
        var expectedTotal=0.0, paidTotal=0.0;
        final repeated=<String,int>{};
        for(final record in _namedLists) {
          final due=parse(record['replenishmentOrderDate']);
          final day=due==null?null:DateTime(due.year,due.month,due.day);
          if(day!=null && day.isBefore(cutoff)) continue;
          final title=(record['title']??'Adsız liste').toString();
          final purchases=record['marketPurchases'] is Map ? record['marketPurchases'] as Map : const <String,dynamic>{};
          final priorities=record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : const <String,dynamic>{};
          for(final item in (record['items'] as List? ?? const [])) {
            final name=item.toString();
            final planned=_planNum(_namedQuantity(record,name)['amount']);
            final purchase=purchases[name] is Map ? purchases[name] as Map : const <String,dynamic>{};
            final bought=_planNum(purchase['quantity']);
            final remaining=(planned-bought).clamp(0.0,double.infinity).toDouble();
            final cost=_namedItemTotal(record,name);
            expectedTotal+=cost;
            paidTotal+=_planNum(purchase['total']);
            scanned++;
            if(planned>0 && remaining<=0) completed++;
            if(bought>0 && remaining>0) partial++;
            if(remaining<=0) continue;
            repeated[name]=1+(repeated[name]??0);
            final isCritical=priorities[name]=='Zorunlu';
            if(isCritical) critical++;
            if(cost<=0) {
              missingPrice++;
              add('Fiyat eksik','Orta',name,'$title • planlanan maliyet girilmemiş',
                'Birim fiyatı ve planlanan alışveriş maliyetini kaydet.',source:title,weight:8);
            }
            if(day!=null && day.isBefore(today)) {
              late++;
              final lag=today.difference(day).inDays;
              add('Geciken satın alma',isCritical?'Kritik':'Yüksek',name,
                '$title • $lag gün gecikti • kalan ${remaining.toStringAsFixed(2)}',
                'Kalan miktar için satın alma tarihini ve sorumlusunu netleştir.',
                source:title,due:day,cost:cost,weight:(lag*3).clamp(0,30));
            } else if(day!=null && day.difference(today).inDays<=dueSoon) {
              add('Yaklaşan satın alma',isCritical?'Yüksek':'Orta',name,
                '$title • ${day.difference(today).inDays} gün kaldı',
                'Stok ve market hazırlığını tamamla.',source:title,due:day,cost:cost,weight:8);
            }
            if(bought>0) {
              add('Kısmi satın alma',isCritical?'Yüksek':'Orta',name,
              '$title • ${remaining.toStringAsFixed(2)} miktar eksik',
              'Kalan miktarı yeni satın alma planına ekle.',source:title,cost:cost,weight:12);
            }
            if(isCritical) {
              add('Kritik ihtiyaç','Kritik',name,
              '$title • karşılanmamış zorunlu ihtiyaç',
              'Öncelikli temin ve stok kontrolü yap.',source:title,cost:cost,weight:18);
            }
          }
        }
        for(final e in repeated.entries) {
          if(e.value>=2) {
            add('Tekrarlayan ihtiyaç',e.value>=3?'Yüksek':'Orta',e.key,
            '${e.value} farklı listede açık ihtiyaç',
            'Tüketim sıklığını ve minimum stok seviyesini gözden geçir.',weight:(e.value*4).clamp(0,20));
          }
        }
        final budget=_monthlyBudgets[_monthKey()]??0;
        final spent=_monthlyTotals()[_monthKey()]??0;
        if(budget>0 && spent>budget) {
          add('Bütçe','Kritik','Aylık bütçe aşıldı',
          'Harcama: ${_money(spent)} • bütçe: ${_money(budget)}',
          'Zorunlu olmayan alımları ertele ve market fiyatlarını karşılaştır.',
          cost:spent-budget,weight:25);
        } else if(budget>0 && spent>=budget*.85) { add('Bütçe','Yüksek','Bütçe sınırına yaklaşılıyor',
          'Bütçe kullanım oranı: %${(spent/budget*100).toStringAsFixed(1)}',
          'Kalan harcama alanını kritik ihtiyaçlara ayır.',weight:15); }
        var openActions=0, lateActions=0, doneActions=0;
        for(final a in actions) {
          final status=(a['status']??'Açık').toString();
          final due=parse(a['due']);
          final done=status=='Tamamlandı';
          if(done) {doneActions++;continue;}
          openActions++;
          if(due!=null && DateTime(due.year,due.month,due.day).isBefore(today)) {
            lateActions++;
            add('Geciken aksiyon',(a['level']??'Yüksek').toString(),(a['title']??'Aksiyon').toString(),
              '${today.difference(due).inDays} gün gecikti • ${a['owner']??'Sorumlu belirtilmedi'}',
              'Aksiyon sorumlusuyla hedef tarihi ve ilerlemeyi gözden geçir.',
              source:(a['source']??'Aksiyon planı').toString(),due:due,weight:25);
          } else if(due!=null && due.difference(today).inDays<=dueSoon) {
            add('Yaklaşan aksiyon',(a['level']??'Orta').toString(),(a['title']??'Aksiyon').toString(),
              '${due.difference(today).inDays} gün kaldı • $status',
              'Tamamlanma durumunu güncelle.',source:'Aksiyon planı',due:due,weight:10);
          }
        }
        var endedGoals=0, failedGoals=0, achievedGoals=0, unmeasuredGoals=0;
        for(final g in goals) {
          final created=parse(g['createdAt']);
          if(created==null) {unmeasuredGoals++;continue;}
          final duration=(g['days'] is num ? (g['days'] as num).toInt() : int.tryParse('${g['days']}')??30);
          final end=created.add(Duration(days:duration>0?duration:30));
          if(end.isAfter(now)) continue;
          endedGoals++;
          final baseline=_planNum(g['baseline']);
          final target=_planNum(g['target']);
          var observed=0;
          for(final r in history) {
            if(g['type']!='Tüm riskler' && r['type']!=g['type']) { continue; }
            final events=r['events'];
            if(events is! List) continue;
            for(final event in events.whereType<Map>()) {
              final at=parse(event['at']);
              if(at!=null && !at.isBefore(created) && at.isBefore(end) &&
                (event['event']=='Aktif'||event['event']=='Çözüldü')) {
                observed++;
              }
            }
          }
          if(baseline<=0) {unmeasuredGoals++;continue;}
          if(observed<=target) {achievedGoals++;continue;}
          failedGoals++;
          add('Risk hedefi','Yüksek',(g['title']??'Risk azaltma hedefi').toString(),
            'Hedef $target olay • ölçülen $observed olay • dönem tamamlandı',
            'Başarısız hedefi düzeltici aksiyon takviminde değerlendir.',
            source:(g['type']??'Tüm riskler').toString(),due:end,weight:22);
        }
        final types=<String>{'Tümü',...rows.map((r)=>r['type'].toString())}.toList()..sort();
        final safeCategory=types.contains(category)?category:'Tümü';
        final visible=rows.where((r) {
          if(safeCategory!='Tümü' && r['type']!=safeCategory) return false;
          if(level!='Tümü' && r['level']!=level) return false;
          if(onlyCritical && r['level']!='Kritik') return false;
          if(onlyOpen && r['status']=='Tamamlandı') return false;
          return '${r['title']} ${r['detail']} ${r['source']} ${r['suggestion']}'
            .toLowerCase().contains(search.toLowerCase());
        }).toList();
        visible.sort((a,b) {
          if(sort=='Başlık') return a['title'].toString().compareTo(b['title'].toString());
          if(sort=='Hedef tarih') return ((a['due'] as DateTime?)??DateTime(9999)).compareTo((b['due'] as DateTime?)??DateTime(9999));
          if(sort=='Maliyet') return (b['cost'] as double).compareTo(a['cost'] as double);
          return (b['score'] as int).compareTo(a['score'] as int);
        });
        final shown=visible.take(maxRows).toList();
        final csvRows=<String>['Kategori,Önem,Risk puanı,Başlık,Ayrıntı,Öneri,Kaynak,Hedef tarih,Tutar'];
        for(final r in visible) { csvRows.add([r['type'],r['level'],r['score'],r['title'],r['detail'],r['suggestion'],r['source'],dateLabel(r['due'] as DateTime?),r['cost']].map(quote).join(',')); }
        Widget metric(String title,String value,{bool warning=false})=>Card(
          color:warning?const Color(0xFFFFEEF2):const Color(0xFFFFF7FC),
          child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Text(title)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold,color:_purple))])));
        return SafeArea(child:FractionallySizedBox(heightFactor:.95,child:ListView(padding:const EdgeInsets.all(16),children:[
          const Text('Akıllı Mutfak • Karar Destek Merkezi',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold,color:_purple)),
          const SizedBox(height:8),
          const Text('Alışveriş, bütçe, risk hedefleri ve aksiyon kayıtları tek bir öncelik sıralamasında değerlendirilir.'),
          if(loadingError.isNotEmpty) Text(loadingError,style:const TextStyle(color:Colors.red)),
          Wrap(spacing:6,runSpacing:4,children:[for(final n in [30,60,90,180,365]) ChoiceChip(label:Text('$n gün'),selected:period==n,onSelected:(_)=>refresh(()=>period=n))]),
          Wrap(spacing:8,children:[for(final n in [3,7,14,30]) ChoiceChip(label:Text('Yaklaşan $n gün'),selected:dueSoon==n,onSelected:(_)=>refresh(()=>dueSoon=n))]),
          metric('Analiz edilen alışveriş kalemi','$scanned'),
          metric('Tamamlanan / kısmi','$completed / $partial'),
          metric('Geciken satın alma','$late',warning:late>0),
          metric('Kritik açık ihtiyaç','$critical',warning:critical>0),
          metric('Fiyatı eksik kalem','$missingPrice'),
          metric('Açık / tamamlanan aksiyon','$openActions / $doneActions'),
          metric('Geciken aksiyon','$lateActions',warning:lateActions>0),
          metric('Biten risk hedefi / başarı','$endedGoals / $achievedGoals'),
          metric('Başarısız / ölçülemeyen hedef','$failedGoals / $unmeasuredGoals',warning:failedGoals>0),
          metric('Planlanan toplam maliyet',_money(expectedTotal)),
          metric('Kayıtlı gerçekleşen alım',_money(paidTotal)),
          metric('Aylık bütçe / harcama','${_money(budget.toDouble())} / ${_money(spent.toDouble())}',warning:budget>0&&spent>budget),
          metric('Üretilen öncelik kaydı','${rows.length}'),
          TextField(decoration:const InputDecoration(labelText:'Ürün, liste, risk veya öneri ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>search=v)),
          Wrap(spacing:8,children:[
            DropdownButton<String>(value:safeCategory,items:types.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>category=v??'Tümü')),
            DropdownButton<String>(value:level,items:['Tümü','Kritik','Yüksek','Orta'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>level=v??'Tümü')),
            DropdownButton<String>(value:sort,items:['Risk puanı','Hedef tarih','Maliyet','Başlık'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>refresh(()=>sort=v??'Risk puanı')),
          ]),
          SwitchListTile(title:const Text('Yalnızca kritik öncelikler'),value:onlyCritical,onChanged:(v)=>refresh(()=>onlyCritical=v)),
          SwitchListTile(title:const Text('Açık kayıtları göster'),value:onlyOpen,onChanged:(v)=>refresh(()=>onlyOpen=v)),
          Wrap(spacing:8,children:[for(final n in [25,50,100,250]) ChoiceChip(label:Text('İlk $n'),selected:maxRows==n,onSelected:(_)=>refresh(()=>maxRows=n))]),
          Text('Filtre sonucu: ${visible.length} • gösterilen: ${shown.length}',style:const TextStyle(fontWeight:FontWeight.bold)),
          if(shown.isEmpty) const Padding(padding:EdgeInsets.all(16),child:Text('Bu filtrelere uygun karar kaydı bulunamadı.')),
          for(final r in shown) Card(color:const Color(0xFFFFF7FC),child:ExpansionTile(
            leading:CircleAvatar(backgroundColor:const Color(0xFFF4E1F5),child:Text('${r['score']}',style:const TextStyle(fontSize:12,color:_purple))),
            title:Text('${r['title']} • ${r['level']}'),
            subtitle:Text('${r['type']} • ${r['source']}\n${r['detail']}'),
            children:[ListTile(title:const Text('Önerilen karar'),subtitle:Text(r['suggestion'].toString())),
              ListTile(title:const Text('Hedef tarih / maliyet'),subtitle:Text('${dateLabel(r['due'] as DateTime?)} • ${_money(r['cost'] as double)}'))])),
          FilledButton.tonalIcon(onPressed:()async {await Clipboard.setData(ClipboardData(text:'\uFEFF${csvRows.join('\r\n')}'));if(mounted)_notice('${visible.length} karar kaydı CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Filtrelenmiş karar raporunu CSV kopyala')),
          const SizedBox(height:8),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenOperationsCenter();},child:const Text('Operasyon paneline geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenCriticalRiskCenter();},child:const Text('Kritik uyarı merkezine geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},child:const Text('Aksiyon planlarına geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenRiskGoalsExecutiveSummary();},child:const Text('Risk hedefleri özetine geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenCorrectiveOutcomeDashboard();},child:const Text('Entegre performans analizine geç')),
          const Padding(padding:EdgeInsets.only(top:12),child:Text('Karar puanları kural tabanlı öncelik göstergesidir; tahmin veya kesin risk olasılığı değildir. Kayıtlar değiştirilmez. Tarihsiz alışveriş listeleri de değerlendirmeye alınır.',style:TextStyle(fontSize:12))),
        ])));
      }));
  }

  void _showKitchenOperationsCenter() {
    var days = 90;
    var query = '';
    var onlyRisks = false;
    var group = 'Durum';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final cutoff = today.subtract(Duration(days: days));
        final rows = <Map<String, dynamic>>[];
        var allLists = 0;
        var purchaseLists = 0;
        for (final record in _namedLists) {
          allLists++;
          final purchases = record['marketPurchases'] is Map ? record['marketPurchases'] as Map : <String, dynamic>{};
          final dueRaw = DateTime.tryParse((record['replenishmentOrderDate'] ?? '').toString());
          final due = dueRaw == null ? null : DateTime(dueRaw.year, dueRaw.month, dueRaw.day);
          if (due != null && due.isBefore(cutoff)) continue;
          if (purchases.isNotEmpty) purchaseLists++;
          final priorities = record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : <String, dynamic>{};
          final title = (record['title'] ?? 'Adsız liste').toString();
          for (final item in (record['items'] as List? ?? const [])) {
            final name = item.toString();
            final qty = _namedQuantity(record, name);
            final expectedQty = _planNum(qty['amount']).clamp(0.0, double.infinity).toDouble();
            final raw = purchases[name];
            final purchase = raw is Map ? raw : <String, dynamic>{};
            final bought = _planNum(purchase['quantity']).clamp(0.0, double.infinity).toDouble();
            final paid = _planNum(purchase['total']).clamp(0.0, double.infinity).toDouble();
            final expected = _namedItemTotal(record, name);
            final remaining = (expectedQty - bought).clamp(0.0, double.infinity).toDouble();
            final late = due != null && due.isBefore(today) && remaining > 0;
            final status = expectedQty <= 0 ? 'Miktar eksik' : remaining <= 0 ? 'Tamamlandı' : bought > 0 ? 'Kısmi' : late ? 'Gecikti' : 'Bekliyor';
            final priority = (priorities[name] ?? 'Normal').toString();
            final market = (purchase['store'] ?? 'Belirtilmedi').toString();
            rows.add({'name':name,'list':title,'planned':expectedQty,'bought':bought,
              'remaining':remaining,'expected':expected,'paid':paid,'status':status,
              'late':late,'priority':priority,'market':market,
              'due':due == null ? '—' : '${due.day}.${due.month}.${due.year}',
              'unit':(qty['unit'] ?? 'Adet').toString()});
          }
        }
        final planned = rows.fold<double>(0, (v,r)=>v+(r['expected'] as double));
        final paid = rows.fold<double>(0, (v,r)=>v+(r['paid'] as double));
        final completed = rows.where((r)=>r['status']=='Tamamlandı').length;
        final partial = rows.where((r)=>r['status']=='Kısmi').length;
        final late = rows.where((r)=>r['late']==true).length;
        final critical = rows.where((r)=>r['remaining']>0 && r['priority']=='Zorunlu').length;
        final missingPrice = rows.where((r)=>r['expected']==0 && r['remaining']>0).length;
        final budget = _monthlyBudgets[_monthKey()] ?? 0;
        final monthSpent = _monthlyTotals()[_monthKey()] ?? 0;
        final filtered = rows.where((r) {
          if (onlyRisks && r['late']!=true && !(r['remaining']>0 && r['priority']=='Zorunlu') && !(r['expected']==0 && r['remaining']>0)) return false;
          return '${r['name']} ${r['list']} ${r['market']} ${r['status']}'.toLowerCase().contains(query.toLowerCase());
        }).toList()..sort((a,b) {
          final riskA = (a['late']==true?4:0)+(a['priority']=='Zorunlu' && a['remaining']>0?2:0);
          final riskB = (b['late']==true?4:0)+(b['priority']=='Zorunlu' && b['remaining']>0?2:0);
          return riskB.compareTo(riskA);
        });
        final grouped = <String,List<Map<String,dynamic>>>{};
        for (final r in filtered) {
          final key = (r[group=='Liste'?'list':group=='Market'?'market':'status']).toString();
          grouped.putIfAbsent(key,()=>[]).add(r);
        }
        final csvLines = <String>['Liste,Ürün,Durum,Öncelik,Planlanan,Alınan,Kalan,Birim,Plan Tutarı,Ödenen,Market,Tarih'];
        for (final r in filtered) {
          csvLines.add([r['list'],r['name'],r['status'],r['priority'],r['planned'],r['bought'],r['remaining'],r['unit'],r['expected'],r['paid'],r['market'],r['due']].map(csv).join(','));
        }
        Widget metric(String title, String value, IconData icon, {bool warning=false}) => Card(
          color:warning?const Color(0xFFFFEDF0):const Color(0xFFFFF7FC),
          child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Icon(icon,color:_purple),const SizedBox(width:8),Expanded(child:Text(title)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold))])));
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:ListView(padding:const EdgeInsets.all(16),children:[
          const Text('Mutfak Operasyonları • Birleşik Yönetim Paneli',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold,color:_purple)),
          const SizedBox(height:8),
          Wrap(spacing:8,children:[for(final n in [30,60,90,180,365]) ChoiceChip(label:Text('$n gün'),selected:days==n,onSelected:(_)=>refresh(()=>days=n))]),
          metric('Kayıtlı liste / alım kaydı olan', '$allLists / $purchaseLists', Icons.list_alt),
          metric('İzlenen ürün kalemi', '${rows.length}', Icons.inventory_2_outlined),
          metric('Tamamlanan', '$completed / ${rows.length}', Icons.check_circle_outline),
          metric('Kısmi satın alma', '$partial', Icons.timelapse,warning:partial>0),
          metric('Geciken ürün', '$late', Icons.warning_amber_outlined,warning:late>0),
          metric('Açık zorunlu ihtiyaç', '$critical', Icons.priority_high,warning:critical>0),
          metric('Fiyatı eksik açık ihtiyaç', '$missingPrice', Icons.price_change_outlined,warning:missingPrice>0),
          metric('Planlanan toplam', _money(planned), Icons.receipt_long_outlined),
          metric('Gerçekleşen toplam', _money(paid), Icons.payments_outlined),
          metric('Plan / gerçekleşen farkı', _money(planned-paid), Icons.compare_arrows),
          metric('Bu ay harcama / bütçe', '${_money(monthSpent)} / ${budget>0?_money(budget):'Tanımsız'}', Icons.account_balance_wallet_outlined,warning:budget>0 && monthSpent>budget),
          if(rows.isNotEmpty) ...[
            const SizedBox(height:6),
            Text('Tamamlanma oranı: %${(100*completed/rows.length).toStringAsFixed(1)}'),
            LinearProgressIndicator(value:completed/rows.length,color:_purple),
          ],
          const SizedBox(height:12),
          TextField(decoration:const InputDecoration(labelText:'Ürün, liste, market veya durum ara',prefixIcon:Icon(Icons.search)),onChanged:(v)=>refresh(()=>query=v)),
          SwitchListTile(title:const Text('Yalnızca riskli kayıtlar'),value:onlyRisks,onChanged:(v)=>refresh(()=>onlyRisks=v)),
          Wrap(spacing:8,children:[for(final g in ['Durum','Liste','Market']) ChoiceChip(label:Text(g),selected:group==g,onSelected:(_)=>refresh(()=>group=g))]),
          for(final entry in grouped.entries) Card(child:ExpansionTile(title:Text('${entry.key} (${entry.value.length})'),subtitle:Text('Ödenen: ${_money(entry.value.fold<double>(0,(v,r)=>v+(r['paid'] as double)))}'),children:[
            for(final r in entry.value) ListTile(dense:true,title:Text('${r['name']} • ${r['status']}'),subtitle:Text('${r['list']} • ${r['priority']} • ${r['due']}\n${r['bought']} / ${r['planned']} ${r['unit']} • ${r['market']}'),trailing:Text(_money(r['paid'] as double))),
          ])),
          FilledButton.tonalIcon(onPressed:()async {await Clipboard.setData(ClipboardData(text:'\uFEFF${csvLines.join('\r\n')}'));if(mounted)_notice('${filtered.length} satır CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Filtrelenmiş operasyon raporunu CSV kopyala')),
          const Text('Panel kayıtlı verileri analiz eder. Tarihi olmayan listeler de görüntülenir; harcama verileri farklı dönemleri kapsayabilir. Kayıtlar değiştirilmez.',style:TextStyle(fontSize:12)),
          const SizedBox(height:12),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenPurchaseCompletionPerformance();},child:const Text('Satın alma performansına geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},child:const Text('İyileştirme aksiyonlarına geç')),
          FilledButton.tonal(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementImpact();},child:const Text('Önce–sonra etki analizine geç')),
        ])));
      }));
  }

  void _showKitchenImprovementImpact() {
    const actionKey = 'paket39_purchase_improvement_actions_v1';
    final actions = <Map<String,dynamic>>[];
    var loaded = false;
    var days = 30;
    var selectedId = 'Tümü';
    var productOnly = true;
    var completedOnly = true;
    var search = '';
    String quote(Object? value) => '"${(value ?? '').toString().replaceAll('"','""')}"';
    DateTime? parse(Object? value) => DateTime.tryParse((value ?? '').toString());
    DateTime dateOnly(DateTime d) => DateTime(d.year,d.month,d.day);
    showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>
      StatefulBuilder(builder:(ctx,refresh) {
        if (!loaded) {
          loaded = true;
          SharedPreferences.getInstance().then((prefs) {
            try {
              final raw=jsonDecode(prefs.getString(actionKey)??'[]');
              if(raw is List) actions..clear()..addAll(raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));
            } catch (_) { if(mounted)_notice('Aksiyon geçmişi okunamadı; kayıtlar değiştirilmedi.'); }
            if(ctx.mounted)refresh((){});
          });
        }
        final now=dateOnly(DateTime.now());
        final completed=actions.where((a)=>a['status']=='Tamamlandı' && parse(a['completed'])!=null).toList();
        final choices=<String>['Tümü',...completed.map((a)=>a['id'].toString())];
        if(!choices.contains(selectedId))selectedId='Tümü';
        final focus=selectedId=='Tümü'?completed:completed.where((a)=>a['id'].toString()==selectedId).toList();
        final results=<Map<String,dynamic>>[];
        for(final action in focus) {
          final finished=parse(action['completed']);
          if(finished==null)continue;
          final pivot=dateOnly(finished);
          final start=pivot.subtract(Duration(days:days));
          final end=pivot.add(Duration(days:days));
          final target=(action['product']??'').toString().trim().toLowerCase();
          final source=(action['source']??'').toString().trim().toLowerCase();
          final before=<Map<String,dynamic>>[];
          final after=<Map<String,dynamic>>[];
          for(final list in _namedLists) {
            final orderDate=parse(list['replenishmentOrderDate']);
            if(orderDate==null)continue;
            final date=dateOnly(orderDate);
            if(date.isBefore(start)||date.isAfter(end)||date.isAfter(now))continue;
            final listName=(list['title']??'').toString();
            if(productOnly && target.isNotEmpty && !(list['items'] as List? ?? const []).any((v)=>v.toString().trim().toLowerCase()==target))continue;
            if(source.isNotEmpty && !productOnly && !listName.toLowerCase().contains(source))continue;
            final purchases=list['marketPurchases'] is Map ? list['marketPurchases'] as Map : <String,dynamic>{};
            for(final raw in (list['items'] as List? ?? const [])) {
              final name=raw.toString();
              if(productOnly && target.isNotEmpty && name.trim().toLowerCase()!=target)continue;
              final planned=_planNum(_namedQuantity(list,name)['amount']);
              if(planned<=0)continue;
              final purchase=purchases[name] is Map ? purchases[name] as Map : <String,dynamic>{};
              final bought=_planNum(purchase['quantity']).clamp(0.0,planned).toDouble();
              final expected=_namedItemTotal(list,name);
              final paid=_planNum(purchase['total']);
              final row=<String,dynamic>{'name':name,'list':listName,'date':date,'planned':planned,'bought':bought,
                'complete':bought>=planned,'missing':planned>bought,'expected':expected,'paid':paid,
                'late':date.isBefore(now) && planned>bought,'priceComparable':expected>0 && bought>0 && paid>0,
                'priceDelta':expected>0 && bought>0 && paid>0 ? paid-expected*bought/planned : 0.0};
              // The completion day is excluded from both windows to avoid ambiguous attribution.
              if(date.isBefore(pivot))before.add(row);
              if(date.isAfter(pivot))after.add(row);
            }
          }
          Map<String,dynamic> stats(List<Map<String,dynamic>> rows) {
            final count=rows.length;
            final full=rows.where((r)=>r['complete']==true).length;
            final partial=rows.where((r)=>_planNum(r['bought'])>0 && r['complete']!=true).length;
            final missing=rows.where((r)=>r['missing']==true).length;
            final late=rows.where((r)=>r['late']==true).length;
            final priced=rows.where((r)=>r['priceComparable']==true).toList();
            final totalExpected=rows.fold<double>(0,(v,r)=>v+_planNum(r['expected']));
            final totalPaid=rows.fold<double>(0,(v,r)=>v+_planNum(r['paid']));
            final priceDelta=priced.fold<double>(0,(v,r)=>v+_planNum(r['priceDelta']));
            return {'count':count,'full':full,'partial':partial,'missing':missing,'late':late,
              'fullRate':count==0?null:100*full/count,'lateRate':count==0?null:100*late/count,
              'expected':totalExpected,'paid':totalPaid,'priced':priced.length,'priceDelta':priceDelta};
          }
          final a=stats(before),b=stats(after);
          final valid=a['count']>0 && b['count']>0;
          final delta=valid ? _planNum(b['fullRate'])-_planNum(a['fullRate']) : null;
          results.add({'action':action,'before':a,'after':b,'valid':valid,'delta':delta,
            'start':start,'pivot':pivot,'end':end,'beforeRows':before,'afterRows':after});
        }
        final visible=results.where((r) {
          final a=r['action'] as Map;
          if(completedOnly && r['valid']!=true)return false;
          return '${a['title']} ${a['product']} ${a['source']} ${a['owner']}'.toLowerCase().contains(search.toLowerCase());
        }).toList();
        visible.sort((a,b)=>((b['pivot'] as DateTime).compareTo(a['pivot'] as DateTime)));
        final measurable=visible.where((r)=>r['valid']==true).toList();
        final improving=measurable.where((r)=>_planNum(r['delta'])>0).length;
        final declining=measurable.where((r)=>_planNum(r['delta'])<0).length;
        final csvRows=<String>[
          ['Aksiyon','Ürün','Kaynak','Tamamlanma','Pencere gün','Önce kayıt','Sonra kayıt','Önce tamamlama %','Sonra tamamlama %','Fark puan','Önce gecikme','Sonra gecikme','Önce ödenen','Sonra ödenen','Önce fiyat sapması','Sonra fiyat sapması','Karşılaştırılabilir'].map(quote).join(','),
          for(final r in visible) [
            (r['action'] as Map)['title'],(r['action'] as Map)['product'],(r['action'] as Map)['source'],(r['action'] as Map)['completed'],days,
            (r['before'] as Map)['count'],(r['after'] as Map)['count'],(r['before'] as Map)['fullRate'],(r['after'] as Map)['fullRate'],r['delta'],
            (r['before'] as Map)['late'],(r['after'] as Map)['late'],(r['before'] as Map)['paid'],(r['after'] as Map)['paid'],
            (r['before'] as Map)['priceDelta'],(r['after'] as Map)['priceDelta'],r['valid']
          ].map(quote).join(',')
        ];
        String pct(Object? v)=>v==null?'Veri yok':'%${_planNum(v).toStringAsFixed(1)}';
        String date(DateTime d)=>'${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
        return SafeArea(child:FractionallySizedBox(heightFactor:.94,child:Padding(padding:const EdgeInsets.all(14),child:ListView(children:[
          Row(children:[Expanded(child:Text('Aksiyon etki analizi / önce–sonra',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple))),IconButton(onPressed:()=>Navigator.pop(ctx),icon:const Icon(Icons.close))]),
          const Text('Tamamlanan aksiyonların çevresindeki sipariş kayıtlarını iki eşit zaman penceresinde karşılaştırır. Korelasyon gösterir; aksiyonun etki yarattığını kanıtlamaz.',style:TextStyle(fontSize:12)),
          Wrap(spacing:8,runSpacing:8,children:[
            DropdownButton<int>(value:days,items:[7,14,30,60,90].map((v)=>DropdownMenuItem(value:v,child:Text('Önce / sonra $v gün'))).toList(),onChanged:(v)=>refresh(()=>days=v??30)),
            DropdownButton<String>(value:selectedId,items:[const DropdownMenuItem(value:'Tümü',child:Text('Tüm tamamlananlar')),...completed.map((a)=>DropdownMenuItem(value:a['id'].toString(),child:SizedBox(width:175,child:Text((a['title']??'Aksiyon').toString(),overflow:TextOverflow.ellipsis))))],onChanged:(v)=>refresh(()=>selectedId=v??'Tümü')),
            FilterChip(label:const Text('Yalnız ilgili ürün'),selected:productOnly,onSelected:(v)=>refresh(()=>productOnly=v)),
            FilterChip(label:const Text('Yalnız karşılaştırılabilir'),selected:completedOnly,onSelected:(v)=>refresh(()=>completedOnly=v)),
          ]),
          TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Aksiyon, ürün, kaynak veya sorumlu ara'),onChanged:(v)=>refresh(()=>search=v)),
          Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
            Text('Tamamlanan aksiyon: ${completed.length} • İncelenen: ${visible.length}',style:const TextStyle(fontWeight:FontWeight.bold)),
            Text('İki dönemde de kayıt bulunan: ${measurable.length} • Tamamlama oranı artan: $improving • Azalan: $declining'),
            const Text('Ölçüm için her iki dönemde en az bir planlı satın alma kalemi gerekir. Eşitlik, gelişme olarak sayılmaz.',style:TextStyle(fontSize:12)),
          ]))),
          if(completed.isEmpty) const Text('Henüz tamamlanma tarihi bulunan aksiyon yok. Aksiyon planlarında bir aksiyonu tamamlayın.'),
          if(completed.isNotEmpty && visible.isEmpty) const Text('Seçilen filtrelerde karşılaştırılabilir kayıt yok. Pencereyi genişletin veya filtreyi kaldırın.'),
          for(final r in visible) Builder(builder:(_){
            final action=r['action'] as Map;
            final before=r['before'] as Map;
            final after=r['after'] as Map;
            final valid=r['valid']==true;
            final delta=r['delta'];
            return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text((action['title']??'Aksiyon').toString(),style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Ürün: ${action['product']??'—'} • Kaynak: ${action['source']??'—'}'),
              Text('Tamamlanma: ${date(r['pivot'] as DateTime)} • Önce ${date(r['start'] as DateTime)} – ${date((r['pivot'] as DateTime).subtract(const Duration(days:1)))} • Sonra ${date((r['pivot'] as DateTime).add(const Duration(days:1)))} – ${date(r['end'] as DateTime)}',style:const TextStyle(fontSize:11)),
              const Divider(),
              Text('Sipariş kalemi: ${before['count']} → ${after['count']}'),
              Text('Tamamlanan: ${before['full']} → ${after['full']} • Kısmi: ${before['partial']} → ${after['partial']}'),
              Text('Tamamlama oranı: ${pct(before['fullRate'])} → ${pct(after['fullRate'])}${valid?' • ${_planNum(delta)>=0?'+':''}${_planNum(delta).toStringAsFixed(1)} puan':''}'),
              Text('Açık ihtiyaç: ${before['missing']} → ${after['missing']} • Gecikmiş: ${before['late']} → ${after['late']}'),
              Text('Planlanan tutar: ${_money(_planNum(before['expected']))} → ${_money(_planNum(after['expected']))}'),
              Text('Ödenen tutar: ${_money(_planNum(before['paid']))} → ${_money(_planNum(after['paid']))}'),
              Text('Fiyat sapması: ${_money(_planNum(before['priceDelta']))} (${before['priced']} kayıt) → ${_money(_planNum(after['priceDelta']))} (${after['priced']} kayıt)'),
              if(!valid) const Text('Karşılaştırma yetersiz: önce veya sonra döneminde kayıt yok.',style:TextStyle(fontSize:12)),
            ])));
          }),
          FilledButton.tonalIcon(onPressed:()async{await Clipboard.setData(ClipboardData(text:'\uFEFF${csvRows.join('\r\n')}'));if(mounted)_notice('Etki analizi CSV olarak kopyalandı.');},icon:const Icon(Icons.copy),label:const Text('Önce–sonra raporunu CSV kopyala')),
          FilledButton.tonalIcon(onPressed:(){Navigator.pop(ctx);_showKitchenImprovementActionPlans();},icon:const Icon(Icons.task_alt_outlined),label:const Text('Aksiyon planlarını aç')),
          const Text('Sınırlar: Sipariş tarihleri üzerinden değerlendirme yapılır; satın alma tarihleri farklı olabilir. Bugünden sonraki kayıtlar dışlanır. Farklı ürün/miktar karmaları, mevsimsellik ve eksik fiyat kayıtları sonuçları etkileyebilir. Aksiyonun tamamlandığı gün karşılaştırma dışındadır. Stok ve satın alma verileri değiştirilmez.',style:TextStyle(fontSize:12)),
        ]))));
      }));
  }

  void _showKitchenReplenishmentActions() {
    var selected = 0;
    var query = '';
    var filter = 'Eksik';
    var sort = 'Gecikme';
    var onlyCritical = false;
    final chosen = <String>{};
    final priorityOverrides = <String,String>{};
    final postponed = <String>{};
    var initialized = false;
    String csv(Object? value) => '"${(value ?? '').toString().replaceAll('"','""')}"';
    String fmt(DateTime date) => '${date.day.toString().padLeft(2,'0')}.${date.month.toString().padLeft(2,'0')}.${date.year}';
    final eligible = _namedLists.where((r) => DateTime.tryParse((r['replenishmentOrderDate'] ?? '').toString()) != null).toList();
    if (eligible.isEmpty) { _notice('Önce stok yenileme takviminden tarihli alışveriş listesi oluşturun.'); return; }
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        if (selected >= eligible.length) selected = 0;
        final record = eligible[selected];
        final orderDate = DateTime.tryParse(record['replenishmentOrderDate'].toString())!;
        final todayNow = DateTime.now();
        final today = DateTime(todayNow.year,todayNow.month,todayNow.day);
        final purchaseRaw = record['marketPurchases'];
        final purchases = purchaseRaw is Map ? purchaseRaw : <String,dynamic>{};
        final priorityRaw = record['replenishmentPriorities'];
        final priorities = priorityRaw is Map ? priorityRaw : <String,dynamic>{};
        final actionRaw = record['replenishmentActions'];
        final actions = actionRaw is Map ? Map<String,dynamic>.from(actionRaw) : <String,dynamic>{};
        final rows = <Map<String,dynamic>>[];
        for (final rawName in (record['items'] as List? ?? const [])) {
          final name = rawName.toString();
          final q = _namedQuantity(record,name);
          final planned = _planNum(q['amount']);
          final unit = (q['unit'] ?? 'Adet').toString();
          final p = purchases[name];
          final purchase = p is Map ? p : <String,dynamic>{};
          final bought = _planNum(purchase['quantity']).clamp(0.0,double.infinity).toDouble();
          final left = (planned-bought).clamp(0.0,double.infinity).toDouble();
          final act = actions[name];
          final action = act is Map ? act : <String,dynamic>{};
          final moved = DateTime.tryParse((action['nextDate'] ?? '').toString());
          final effective = moved ?? orderDate;
          final date = DateTime(effective.year,effective.month,effective.day);
          final late = left>0 && date.isBefore(today) ? today.difference(date).inDays : 0;
          final status = left<=0 ? 'Tamamlandı' : bought>0 ? 'Kısmi' : late>0 ? 'Gecikti' : 'Bekliyor';
          final cost = _namedItemTotal(record,name);
          final remainingCost = planned>0 && cost>0 ? cost*left/planned : 0.0;
          final priority = priorityOverrides[name] ?? (action['priority'] ?? priorities[name] ?? 'Normal').toString();
          rows.add({'name':name,'planned':planned,'bought':bought,'left':left,'unit':unit,
            'date':date,'late':late,'status':status,'priority':priority,'cost':remainingCost,
            'known':cost>0,'paid':_planNum(purchase['total']), 'store':(purchase['store'] ?? '').toString(),
            'transferred':purchase['stockTransferred']==true,'note':(action['note'] ?? '').toString()});
        }
        final validNames = rows.where((r)=>_planNum(r['left'])>0).map((r)=>r['name'].toString()).toSet();
        if (!initialized) { chosen.addAll(validNames); initialized=true; }
        chosen.removeWhere((n)=>!validNames.contains(n));
        postponed.removeWhere((n)=>!validNames.contains(n));
        final remaining = rows.where((r)=>_planNum(r['left'])>0).toList();
        final partial = rows.where((r)=>r['status']=='Kısmi').length;
        final overdue = remaining.where((r)=>(r['late'] as int)>0).length;
        final critical = remaining.where((r)=>r['priority']=='Zorunlu').length;
        final unknown = remaining.where((r)=>r['known']!=true).length;
        final estimated = remaining.fold<double>(0,(a,r)=>a+_planNum(r['cost']));
        final visible = rows.where((r) {
          if (filter=='Eksik' && _planNum(r['left'])<=0) return false;
          if (filter=='Geciken' && (r['late'] as int)<=0) return false;
          if (filter=='Kısmi' && r['status']!='Kısmi') return false;
          if (filter=='Tamamlanan' && r['status']!='Tamamlandı') return false;
          if (onlyCritical && r['priority']!='Zorunlu') return false;
          return '${r['name']} ${r['store']} ${r['note']}'.toLowerCase().contains(query.toLowerCase());
        }).toList();
        visible.sort((a,b) {
          if(sort=='Ürün') return a['name'].toString().compareTo(b['name'].toString());
          if(sort=='Tutar') return _planNum(b['cost']).compareTo(_planNum(a['cost']));
          if(sort=='Miktar') return _planNum(b['left']).compareTo(_planNum(a['left']));
          if(sort=='Tarih') return (a['date'] as DateTime).compareTo(b['date'] as DateTime);
          return (b['late'] as int).compareTo(a['late'] as int);
        });
        Future<void> edit(Map<String,dynamic> r) async {
          final name = r['name'].toString();
          final note = TextEditingController(text:r['note'].toString());
          var date = r['date'] as DateTime;
          var priority = r['priority'].toString();
          final ok = await showDialog<bool>(context:ctx,builder:(dialog)=>StatefulBuilder(builder:(dctx,update)=>AlertDialog(
            title:Text('$name • Aksiyon'),
            content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
              Text('Kalan: ${_planNumberText(_planNum(r['left']))} ${r['unit']} • ${r['status']}'),
              DropdownButtonFormField<String>(initialValue:['Zorunlu','Normal','Ertelenebilir'].contains(priority)?priority:'Normal',
                decoration:const InputDecoration(labelText:'Öncelik'),
                items:[for(final v in ['Zorunlu','Normal','Ertelenebilir']) DropdownMenuItem(value:v,child:Text(v))],
                onChanged:(v)=>update(()=>priority=v??'Normal')),
              ListTile(title:const Text('Yeni hedef alışveriş tarihi'),subtitle:Text(fmt(date)),
                trailing:const Icon(Icons.calendar_today_outlined),onTap:() async {
                  final picked=await showDatePicker(context:dctx,initialDate:date.isBefore(today)?today:date,
                    firstDate:DateTime(2020),lastDate:DateTime(2100));
                  if(picked!=null) update(()=>date=picked);
                }),
              TextField(controller:note,maxLength:200,maxLines:2,decoration:const InputDecoration(labelText:'Aksiyon notu')),
            ])),actions:[TextButton(onPressed:()=>Navigator.pop(dialog,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(dialog,true),child:const Text('Kaydet'))])));
          if(ok!=true) return;
          final next = Map<String,dynamic>.from(actions);
          next[name]={'nextDate':DateTime(date.year,date.month,date.day).toIso8601String(),
            'priority':priority,'note':note.text.trim(),'updated':DateTime.now().toIso8601String()};
          setState(()=>record['replenishmentActions']=next);
          await _save();
          if(ctx.mounted) refresh(() { priorityOverrides[name]=priority; });
          if(mounted) _notice('$name için aksiyon kaydedildi.');
        }
        Future<void> createList() async {
          final picked = remaining.where((r)=>chosen.contains(r['name'])&&!postponed.contains(r['name'])).toList();
          if(picked.isEmpty) { _notice('Listeye eklenecek eksik ürün seçilmedi.');return; }
          final title='Eksik sipariş • ${record['title'] ?? 'Liste'} • ${fmt(today)}';
          final exists=_namedLists.any((r)=>r['replenishmentFollowupSource']==record['id'] &&
            r['replenishmentFollowupDate']=='${_monthKey(today)}-${today.day.toString().padLeft(2,'0')}');
          if(exists) { _notice('Bu kaynak için bugün zaten takip listesi oluşturulmuş.');return; }
          final confirmed=await showDialog<bool>(context:ctx,builder:(d)=>AlertDialog(
            title:const Text('Eksik ürünlerden liste oluştur'),
            content:Text('${picked.length} ürün için bağımsız takip listesi oluşturulsun mu? Mevcut satın alma ve stok kayıtları değişmez.'),
            actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Oluştur'))]));
          if(confirmed!=true) return;
          final details=<String,dynamic>{};final prices=<String,dynamic>{};final priorityMap=<String,dynamic>{};
          final names=<String>[];
          for(final r in picked) {
            final name=r['name'].toString();names.add(name);
            details[name]={'amount':_planNumberText(_planNum(r['left'])),'unit':r['unit']};
            if(r['known']==true) prices[name]=r['cost'];
            priorityMap[name]=r['priority'];
          }
          final newRecord=<String,dynamic>{'id':DateTime.now().microsecondsSinceEpoch.toString(),
            'title':title,'updated':DateTime.now().toIso8601String(),
            'items':names,'done':<String>[],'details':details,'prices':prices,
            'actualPrices':<String,dynamic>{},'budget':picked.fold<double>(0,(a,r)=>a+_planNum(r['cost'])),
            'replenishmentPriorities':priorityMap,'replenishmentOrderDate':today.toIso8601String(),
            'replenishmentFollowupSource':record['id'],
            'replenishmentFollowupDate':'${_monthKey(today)}-${today.day.toString().padLeft(2,'0')}',
            'replenishmentFollowupCreated':DateTime.now().toIso8601String()};
          setState(()=>_namedLists.insert(0,newRecord));
          await _save();
          if(ctx.mounted) Navigator.pop(ctx);
          if(mounted) _notice('${names.length} eksik üründen yeni alışveriş listesi oluşturuldu.');
        }
        final lines=<String>['Liste;Ürün;Durum;Plan miktarı;Alınan;Kalan;Birim;Hedef tarih;Gecikme günü;Öncelik;Kalan tahmini TL;Gerçek ödenen TL;Market;Stok aktarımı;Aksiyon notu'];
        for(final r in visible) { lines.add([record['title'],r['name'],r['status'],r['planned'],r['bought'],r['left'],r['unit'],fmt(r['date'] as DateTime),r['late'],r['priority'],r['known']==true?r['cost']:'',r['paid'],r['store'],r['transferred']==true?'Evet':'Hayır',r['note']].map(csv).join(';')); }
        return SafeArea(child:SizedBox(height:MediaQuery.of(ctx).size.height*.94,
          child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Geciken sipariş / kısmi alım aksiyonları',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple)),
            const Text('Kalan miktar, yeni hedef tarih ve öncelik üzerinden takip. Satın alma ve stok hareketleri değiştirilmez.',style:TextStyle(fontSize:12)),
            DropdownButtonFormField<int>(initialValue:selected,isExpanded:true,decoration:const InputDecoration(labelText:'Tarihli stok yenileme listesi'),
              items:[for(var i=0;i<eligible.length;i++) DropdownMenuItem(value:i,child:Text((eligible[i]['title']??'Adsız').toString(),overflow:TextOverflow.ellipsis))],
              onChanged:(v)=>refresh(() {selected=v??0;initialized=false;chosen.clear();postponed.clear();priorityOverrides.clear();})),
            Card(color:_pink,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Toplam: ${rows.length} • Eksik: ${remaining.length} • Kısmi: $partial'),
              Text('Geciken: $overdue • Zorunlu eksik: $critical',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Kalan tahmini maliyet: ${_money(estimated)}'),
              if(unknown>0) Text('$unknown ürünün fiyatı bilinmiyor; tahmin eksik olabilir.',style:const TextStyle(fontSize:12)),
              if(rows.isNotEmpty) LinearProgressIndicator(value:(rows.length-remaining.length)/rows.length),
            ]))),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Ürün, market veya not ara'),onChanged:(v)=>refresh(()=>query=v)),
            Wrap(spacing:6,runSpacing:6,children:[for(final f in ['Eksik','Tümü','Geciken','Kısmi','Tamamlanan'])
              ChoiceChip(label:Text(f),selected:filter==f,onSelected:(_)=>refresh(()=>filter=f))]),
            SwitchListTile(title:const Text('Yalnızca zorunlu ürünler'),value:onlyCritical,onChanged:(v)=>refresh(()=>onlyCritical=v)),
            DropdownButtonFormField<String>(initialValue:sort,decoration:const InputDecoration(labelText:'Sırala'),
              items:[for(final v in ['Gecikme','Tarih','Ürün','Tutar','Miktar']) DropdownMenuItem(value:v,child:Text(v))],
              onChanged:(v)=>refresh(()=>sort=v??'Gecikme')),
            for(final r in visible) Card(child:Column(children:[
              CheckboxListTile(value:chosen.contains(r['name']),onChanged:_planNum(r['left'])<=0?null:(v)=>refresh(() {if(v==true) {
                chosen.add(r['name']);
              } else {
                chosen.remove(r['name']);
              }}),
                title:Text('${r['name']} • ${r['status']}'),
                subtitle:Text('Plan ${_planNumberText(_planNum(r['planned']))} • Alınan ${_planNumberText(_planNum(r['bought']))} • Kalan ${_planNumberText(_planNum(r['left']))} ${r['unit']}\n'
                  '${fmt(r['date'] as DateTime)}${(r['late'] as int)>0?' • ${r['late']} gün gecikti':''} • ${r['priority']}\n'
                  'Kalan tahmini ${r['known']==true?_money(_planNum(r['cost'])):'Bilinmiyor'}${r['note'].toString().isNotEmpty?' • ${r['note']}':''}'),
                isThreeLine:true,secondary:Icon(r['status']=='Tamamlandı'?Icons.check_circle_outline:Icons.warning_amber_outlined,color:_purple)),
              if(_planNum(r['left'])>0) Padding(padding:const EdgeInsets.symmetric(horizontal:8),child:Row(children:[
                Expanded(child:TextButton.icon(onPressed:()=>edit(r),icon:const Icon(Icons.edit_calendar_outlined),label:const Text('Tarih / öncelik / not'))),
                Expanded(child:TextButton(onPressed:()=>refresh(() {if(postponed.contains(r['name'])) {
                  postponed.remove(r['name']);
                } else {
                  postponed.add(r['name']);
                }}),
                  child:Text(postponed.contains(r['name'])?'Plana geri al':'Bu listede ertele'))),
              ])),
            ])),
            Text('Takip listesine seçilen: ${remaining.where((r)=>chosen.contains(r['name'])&&!postponed.contains(r['name'])).length} ürün'),
            FilledButton.icon(onPressed:createList,icon:const Icon(Icons.playlist_add),label:const Text('Kalan miktarlardan takip listesi oluştur')),
            FilledButton.tonalIcon(onPressed:() async {await Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));if(mounted)_notice('${visible.length} satırlık CSV kopyalandı.');},
              icon:const Icon(Icons.copy_outlined),label:const Text('Görünen aksiyonları CSV kopyala')),
            const Text('Not: Kısmi alımlar planlanan miktardan düşülür. Aynı ürün için satın alma kaydı tek toplam miktardır. Yeniden planlama yalnızca aksiyon tarihini değiştirir; orijinal sipariş tarihi korunur.',style:TextStyle(fontSize:12)),
          ])));
      }));
  }

  void _showKitchenReplenishmentExecution() {
    var query = '';
    var filter = 'Tümü';
    var days = 90;
    var sort = 'Tarih';
    var selectedSource = 'Tümü';
    var includeUnplanned = false;
    String fmt(DateTime d) => '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (_) => StatefulBuilder(builder: (ctx, refresh) {
        final todayNow = DateTime.now();
        final today = DateTime(todayNow.year, todayNow.month, todayNow.day);
        final rows = <Map<String, dynamic>>[];
        final sourceNames = <String>{};
        for (final record in _namedLists) {
          final orderRaw = record['replenishmentOrderDate']?.toString() ?? '';
          final parsed = DateTime.tryParse(orderRaw);
          if (parsed == null && !includeUnplanned) continue;
          final orderDay = parsed == null ? null : DateTime(parsed.year, parsed.month, parsed.day);
          if (orderDay != null && orderDay.isBefore(today.subtract(Duration(days: days)))) continue;
          final title = (record['title'] ?? 'Adsız liste').toString();
          sourceNames.add(title);
          final names = (record['items'] as List? ?? const []).map((e) => e.toString()).toList();
          final rawPurchases = record['marketPurchases'];
          final purchases = rawPurchases is Map ? rawPurchases : <String, dynamic>{};
          final priorities = record['replenishmentPriorities'] is Map ? record['replenishmentPriorities'] as Map : <String,dynamic>{};
          final sources = record['replenishmentSources'] is Map ? record['replenishmentSources'] as Map : <String,dynamic>{};
          for (final name in names) {
            final raw = purchases[name];
            final purchase = raw is Map ? raw : null;
            final planned = _namedQuantity(record, name);
            final amount = _planNum(planned['amount']);
            final bought = purchase == null ? 0.0 : _planNum(purchase['quantity']);
            final paid = purchase == null ? 0.0 : _planNum(purchase['total']);
            final expected = _namedItemTotal(record, name);
            final done = purchase != null;
            final overdue = !done && orderDay != null && orderDay.isBefore(today);
            final remaining = !done && orderDay != null ? orderDay.difference(today).inDays : null;
            final status = done ? 'Satın alındı' : overdue ? 'Gecikti' : orderDay == null ? 'Tarih yok' : remaining == 0 ? 'Bugün' : 'Bekliyor';
            rows.add({'name':name,'title':title,'date':orderDay,'status':status,
              'priority':(priorities[name] ?? 'Belirtilmedi').toString(),
              'origin':(sources[name] ?? '').toString(),
              'qty':amount,'unit':planned['unit']?.toString() ?? '',
              'bought':bought,'paid':paid,'expected':expected,
              'store':purchase?['store']?.toString() ?? '',
              'transferred':purchase?['stockTransferred'] == true,
              'daysLate':overdue ? today.difference(orderDay).inDays : 0,
              'daysLeft':remaining});
          }
        }
        final total = rows.length;
        final boughtRows = rows.where((r)=>r['status']=='Satın alındı').toList();
        final lateRows = rows.where((r)=>r['status']=='Gecikti').toList();
        final todayRows = rows.where((r)=>r['status']=='Bugün').toList();
        final pendingRows = rows.where((r)=>r['status']!='Satın alındı').toList();
        final transferred = rows.where((r)=>r['transferred']==true).length;
        final plannedCost = rows.fold<double>(0,(v,r)=>v+_planNum(r['expected']));
        final paidCost = boughtRows.fold<double>(0,(v,r)=>v+_planNum(r['paid']));
        final boughtBudget = boughtRows.fold<double>(0,(v,r)=>v+_planNum(r['expected']));
        final pendingCost = pendingRows.fold<double>(0,(v,r)=>v+_planNum(r['expected']));
        final unknownCost = rows.where((r)=>_planNum(r['expected'])<=0).length;
        final byStore = <String,double>{};
        for (final r in boughtRows) {
          final store = (r['store'] as String).trim().isEmpty ? 'Market belirtilmedi' : r['store'] as String;
          byStore[store]=(byStore[store]??0)+_planNum(r['paid']);
        }
        final stores = byStore.entries.toList()..sort((a,b)=>b.value.compareTo(a.value));
        final visible = rows.where((r) {
          if (selectedSource!='Tümü' && r['title']!=selectedSource) return false;
          if (filter!='Tümü' && r['status']!=filter && !(filter=='Stoğa aktarılan' && r['transferred']==true) &&
            !(filter=='Kritik bekleyen' && r['status']!='Satın alındı' && r['priority']=='Zorunlu')) { return false; }
          return '${r['name']} ${r['title']} ${r['store']} ${r['priority']}'.toLowerCase().contains(query.toLowerCase());
        }).toList();
        visible.sort((a,b) {
          if (sort=='Ürün') return a['name'].toString().compareTo(b['name'].toString());
          if (sort=='Tutar') return _planNum(b['expected']).compareTo(_planNum(a['expected']));
          if (sort=='Gecikme') return (b['daysLate'] as int).compareTo(a['daysLate'] as int);
          if (sort=='Durum') return a['status'].toString().compareTo(b['status'].toString());
          final da=a['date'] as DateTime?; final db=b['date'] as DateTime?;
          return (da??DateTime(9999)).compareTo(db??DateTime(9999));
        });
        final lines = <String>['Plan tarihi;Liste;Ürün;Öncelik;Durum;Gecikme günü;Planlanan miktar;Birim;Alınan miktar;Tahmini tutar;Ödenen tutar;Market;Stoğa aktarıldı'];
        for (final r in visible) {
          lines.add([r['date']==null?'':fmt(r['date'] as DateTime),r['title'],r['name'],r['priority'],r['status'],r['daysLate'],r['qty'],r['unit'],r['bought'],r['expected'],r['paid'],r['store'],r['transferred']==true?'Evet':'Hayır'].map(csv).join(';'));
        }
        return SafeArea(child: SizedBox(height:MediaQuery.of(ctx).size.height*.94,
          child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Stok siparişleri / gerçekleşme ve gecikme',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple)),
            const SizedBox(height:6),
            const Text('Stok yenileme takviminden oluşturulmuş listeler ve kayıtlı satın almalar karşılaştırılır. Bu ekran yalnızca rapor üretir.',style:TextStyle(fontSize:12)),
            Wrap(spacing:6,runSpacing:6,children:[for(final n in [30,90,180,365]) ChoiceChip(label:Text('Son $n gün'),selected:days==n,onSelected:(_)=>refresh(()=>days=n))]),
            SwitchListTile(title:const Text('Sipariş tarihi olmayan listeleri de göster'),value:includeUnplanned,onChanged:(v)=>refresh(()=>includeUnplanned=v)),
            Card(color:const Color(0xFFF3E8FF),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Toplam: $total • Alınan: ${boughtRows.length} • Bekleyen: ${pendingRows.length}'),
              Text('Geciken: ${lateRows.length} • Bugün: ${todayRows.length} • Stoğa aktarılan: $transferred',style:const TextStyle(fontWeight:FontWeight.bold)),
              if(total>0) LinearProgressIndicator(value:boughtRows.length/total),
              Text('Planlanan: ${_money(plannedCost)} • Gerçekleşen: ${_money(paidCost)}'),
              Text('Alınan ürünlerin plan farkı: ${_money(paidCost-boughtBudget)} • Bekleyen tahmini: ${_money(pendingCost)}'),
              if(unknownCost>0) Text('Fiyatı bilinmeyen: $unknownCost ürün; toplam tahmin eksik olabilir.',style:const TextStyle(fontSize:12)),
            ]))),
            DropdownButtonFormField<String>(initialValue:selectedSource,isExpanded:true,decoration:const InputDecoration(labelText:'Alışveriş listesi'),
              items:[const DropdownMenuItem(value:'Tümü',child:Text('Tüm listeler')),
                for(final n in (sourceNames.toList()..sort())) DropdownMenuItem(value:n,child:Text(n,overflow:TextOverflow.ellipsis))],
              onChanged:(v)=>refresh(()=>selectedSource=v??'Tümü')),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Ürün, liste, market veya öncelik ara'),onChanged:(v)=>refresh(()=>query=v)),
            Wrap(spacing:6,runSpacing:6,children:[for(final f in ['Tümü','Gecikti','Bugün','Bekliyor','Satın alındı','Stoğa aktarılan','Kritik bekleyen','Tarih yok'])
              ChoiceChip(label:Text(f),selected:filter==f,onSelected:(_)=>refresh(()=>filter=f))]),
            DropdownButtonFormField<String>(initialValue:sort,decoration:const InputDecoration(labelText:'Sıralama'),
              items:[for(final f in ['Tarih','Gecikme','Durum','Tutar','Ürün']) DropdownMenuItem(value:f,child:Text(f))],
              onChanged:(v)=>refresh(()=>sort=v??'Tarih')),
            const SizedBox(height:12),
            const Text('Market bazlı gerçekleşen harcama',style:TextStyle(fontWeight:FontWeight.bold)),
            if(stores.isEmpty) const Text('Henüz satın alma kaydı bulunmuyor.'),
            for(final e in stores.take(10)) ListTile(dense:true,title:Text(e.key),trailing:Text(_money(e.value))),
            const Divider(),
            Text('Sipariş kayıtları (${visible.length})',style:const TextStyle(fontWeight:FontWeight.bold)),
            if(visible.isEmpty) const Padding(padding:EdgeInsets.all(12),child:Text('Seçilen filtrelere uygun kayıt bulunamadı.')),
            for(final r in visible) Card(child:ListTile(
              leading:Icon(r['status']=='Satın alındı'?Icons.check_circle_outline:r['status']=='Gecikti'?Icons.warning_amber_outlined:Icons.schedule_outlined,
                color:r['status']=='Gecikti'?Colors.deepOrange:_purple),
              title:Text('${r['name']} • ${r['status']}'),
              subtitle:Text('${r['title']} • ${r['date']==null?'Tarih yok':fmt(r['date'] as DateTime)}\n'
                '${r['qty']} ${r['unit']} plan • ${r['bought']} alındı • ${_money(_planNum(r['expected']))} tahmin\n'
                '${r['priority']}${(r['daysLate'] as int)>0?' • ${r['daysLate']} gün gecikti':''}${r['transferred']==true?' • Stoğa aktarıldı':''}'),
              isThreeLine:true,
              trailing:r['status']=='Satın alındı'?Text(_money(_planNum(r['paid']))):null,
            )),
            const SizedBox(height:8),
            FilledButton.icon(onPressed:()=>Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}')).then((_){if(mounted)_notice('${visible.length} satırlık rapor kopyalandı.');}),
              icon:const Icon(Icons.copy_all_outlined),label:const Text('Filtrelenmiş sipariş raporunu CSV kopyala')),
            const SizedBox(height:10),
            const Text('Not: Satın alma durumu, ilgili listedeki marketPurchases kayıtlarına göre belirlenir. Kısmi alımlar satın alındı sayılır; stok hareketleri ve satın alma kayıtları bu ekranda değiştirilmez.',style:TextStyle(fontSize:12)),
          ])));
      }));
  }

  void _showKitchenReplenishmentSchedule() {
    var historyDays = 60;
    var safetyDays = 3;
    var leadDays = 2;
    var horizonDays = 30;
    var selectedList = 0;
    var budget = 3000.0;
    var query = '';
    var status = 'Tümü';
    var sort = 'Sipariş tarihi';
    var includeUnknown = false;
    final excluded = <String>{};
    final priority = <String,String>{};
    final selected = <String>{};
    var initialized = false;
    String fmt(DateTime d) => '${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}.${d.year}';
    String csv(Object? v) => '"${(v ?? '').toString().replaceAll('"','""')}"';
    showModalBottomSheet<void>(context:context,isScrollControlled:true,
      builder: (_) => StatefulBuilder(builder:(ctx,refresh) {
        final now = DateTime.now();
        final today = DateTime(now.year,now.month,now.day);
        final from = now.subtract(Duration(days:historyDays));
        final sources = selectedList == 0 ? _namedLists :
          (selectedList <= _namedLists.length ? [_namedLists[selectedList-1]] : <Map<String,dynamic>>[]);
        final rows = <Map<String,dynamic>>[];
        var noHistory = 0;
        var expired = 0;
        var noPrice = 0;
        for (final list in sources) {
          final sourceId = (list['id'] ?? list['title'] ?? '').toString();
          final sourceName = (list['title'] ?? 'Adsız').toString();
          for (final item in (list['items'] as List? ?? const [])) {
            final name = item.toString();
            final id = '$sourceId::$name';
            final unit = (_namedQuantity(list,name)['unit'] ?? 'Adet').toString();
            final stock = _namedStock(list,name);
            final amount = _planNum(stock['amount']).clamp(0.0,double.infinity).toDouble();
            final expiry = _kitchenDaysUntil((stock['expiry'] ?? '').toString());
            final isExpired = expiry != null && expiry < 0;
            if (isExpired && amount > 0) expired++;
            final usable = isExpired ? 0.0 : amount;
            var consumed = 0.0;
            var movementCount = 0;
            DateTime? oldest;
            for (final movement in _stockMovements(list)) {
              if (movement['product']?.toString() != name || movement['reversed'] == true || !_isConsumptionMovement(movement)) continue;
              final date = _movementDate(movement);
              if (date == null || date.isBefore(from) || date.isAfter(now)) continue;
              final delta = _planNum(movement['change']);
              if (!delta.isFinite || delta >= 0) continue;
              consumed -= delta;
              movementCount++;
              if (oldest == null || date.isBefore(oldest)) oldest = date;
            }
            if (movementCount == 0) noHistory++;
            final days = oldest == null ? 0.0 :
              (now.difference(oldest).inMinutes / 1440.0).clamp(1.0,historyDays.toDouble()).toDouble();
            final daily = days > 0 ? consumed / days : 0.0;
            final coverage = daily > 0 ? usable / daily : null;
            final minStock = _planNum(stock['minimum']).clamp(0.0,double.infinity).toDouble();
            final target = _planNum(stock['target']).clamp(0.0,double.infinity).toDouble();
            final need = daily * (horizonDays + safetyDays + leadDays);
            final desired = [need,minStock,target].reduce((a,b)=>a>b?a:b);
            final qty = (desired - usable).clamp(0.0,double.infinity).toDouble();
            if (qty <= 0 || !qty.isFinite) continue;
            final orderIn = coverage == null ? null : coverage - safetyDays - leadDays;
            final urgent = usable <= 0 || isExpired || (orderIn != null && orderIn <= 0);
            final orderDay = today.add(Duration(days:orderIn == null ? 0 : orderIn.floor().clamp(0,3650)));
            final unitCost = _stockUnitCost(list,name);
            final known = unitCost.isFinite && unitCost > 0;
            if (!known) noPrice++;
            final cost = known ? unitCost * qty : 0.0;
            final risk = urgent ? 'Acil' : orderIn == null ? 'Veri eksik' : orderIn <= 7 ? '7 gün içinde' : 'Planlı';
            rows.add({'id':id,'name':name,'source':sourceName,'sourceId':sourceId,
              'unit':unit,'qty':qty,'usable':usable,'daily':daily,'coverage':coverage,
              'orderDay':orderDay,'orderIn':orderIn,'urgent':urgent,'risk':risk,
              'known':known,'unitCost':known?unitCost:0.0,'cost':cost,
              'movements':movementCount,'expired':isExpired});
          }
        }
        final ids = rows.map((r)=>r['id'] as String).toSet();
        if (!initialized) { selected.addAll(ids); initialized=true; }
        selected.removeWhere((id)=>!ids.contains(id));
        excluded.removeWhere((id)=>!ids.contains(id));
        int rank(Map<String,dynamic> r) => (priority[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal')) == 'Zorunlu' ? 0 :
          (priority[r['id']] == 'Ertelenebilir' ? 2 : 1);
        rows.sort((a,b) {
          final aDate = a['orderDay'] as DateTime;
          final bDate = b['orderDay'] as DateTime;
          if (sort == 'Maliyet') return _planNum(b['cost']).compareTo(_planNum(a['cost']));
          if (sort == 'Ürün') return a['name'].toString().compareTo(b['name'].toString());
          if (sort == 'Öncelik') return rank(a).compareTo(rank(b));
          final d = aDate.compareTo(bDate);
          return d != 0 ? d : rank(a).compareTo(rank(b));
        });
        final eligible = rows.where((r)=>selected.contains(r['id']) && !excluded.contains(r['id']) &&
          (includeUnknown || r['known']==true)).toList();
        eligible.sort((a,b) {
          final d=rank(a).compareTo(rank(b));
          return d!=0?d:(a['orderDay'] as DateTime).compareTo(b['orderDay'] as DateTime);
        });
        final accepted = <Map<String,dynamic>>[];
        final deferred = <Map<String,dynamic>>[];
        var spent = 0.0;
        for (final r in eligible) {
          final cost = _planNum(r['cost']);
          if (budget == 0 || spent + cost <= budget + 0.00001) {
            accepted.add(r); spent += cost;
          } else { deferred.add(r); }
        }
        final acceptedIds = accepted.map((r)=>r['id']).toSet();
        final upcoming = rows.where((r)=>(r['orderDay'] as DateTime).difference(today).inDays <= 7).length;
        final urgentCount = rows.where((r)=>r['urgent']==true).length;
        final plannedCost = rows.fold<double>(0,(v,r)=>v+_planNum(r['cost']));
        final buckets = <String,List<Map<String,dynamic>>>{};
        for (final r in accepted) {
          final key = fmt(r['orderDay'] as DateTime);
          buckets.putIfAbsent(key,()=>[]).add(r);
        }
        final visible = rows.where((r) {
          if (!'${r['name']} ${r['source']}'.toLowerCase().contains(query.toLowerCase())) return false;
          if (status=='Acil' && r['urgent']!=true) return false;
          if (status=='7 gün' && (r['orderDay'] as DateTime).difference(today).inDays > 7) return false;
          if (status=='Seçilen' && !acceptedIds.contains(r['id'])) return false;
          if (status=='Ertelenen' && acceptedIds.contains(r['id'])) return false;
          if (status=='Fiyat yok' && r['known']==true) return false;
          if (status=='Geçmiş yok' && r['movements']!=0) return false;
          return true;
        }).toList();
        Future<void> createForDay(String dateKey,List<Map<String,dynamic>> group) async {
          if (group.isEmpty) return;
          final titleController=TextEditingController(text:'Stok siparişi $dateKey');
          final title=await showDialog<String>(context:ctx,builder:(d)=>AlertDialog(
            title:const Text('Tarihe göre alışveriş listesi'),
            content:TextField(controller:titleController,decoration:const InputDecoration(labelText:'Liste adı')),
            actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Vazgeç')),
              FilledButton(onPressed:()=>Navigator.pop(d,titleController.text.trim()),child:const Text('Liste oluştur'))]));
          disposeAfterDialog(titleController);
          if (title==null || title.isEmpty || !mounted) return;
          final names=<String>[];
          final details=<String,dynamic>{};
          final prices=<String,dynamic>{};
          final origins=<String,dynamic>{};
          final priorities=<String,dynamic>{};
          for (final r in group) {
            var name=r['name'] as String;
            if (names.contains(name)) name='$name (${r['source']})';
            if (names.contains(name)) { _notice('Tekrarlanan ürün adı: $name'); return; }
            names.add(name);
            details[name]={'amount':_planNumberText(_planNum(r['qty'])),'unit':r['unit']};
            if (r['known']==true) prices[name]=r['cost'];
            origins[name]=r['sourceId'];
            priorities[name]=priority[r['id']] ?? (r['urgent']==true?'Zorunlu':'Normal');
          }
          final record=<String,dynamic>{
            'id':DateTime.now().microsecondsSinceEpoch.toString(),
            'title':title,'updated':DateTime.now().toIso8601String(),
            'items':names,'done':<String>[],'details':details,'prices':prices,
            'actualPrices':<String,dynamic>{},'budget':budget,
            'replenishmentSources':origins,'replenishmentPriorities':priorities,
            'replenishmentOrderDate':dateKey,'replenishmentHistoryDays':historyDays,
            'replenishmentHorizonDays':horizonDays,'replenishmentCreated':now.toIso8601String(),
          };
          setState(()=>_namedLists.insert(0,record));
          await _save();
          if (mounted) _notice('$dateKey için ${names.length} ürünlük liste oluşturuldu.');
          if (ctx.mounted) Navigator.pop(ctx);
        }
        final lines=<String>['Sipariş tarihi;Liste;Ürün;Öncelik;Risk;Birim;Önerilen miktar;Kullanılabilir stok;Günlük tüketim;Stok günü;Birim fiyat;Maliyet;Durum'];
        for (final r in rows) {
          lines.add([fmt(r['orderDay'] as DateTime),r['source'],r['name'],
            priority[r['id']]??(r['urgent']==true?'Zorunlu':'Normal'),r['risk'],r['unit'],
            r['qty'],r['usable'],r['daily'],r['coverage']??'',
            r['known']==true?r['unitCost']:'',r['known']==true?r['cost']:'',
            acceptedIds.contains(r['id'])?'Plana alındı':'Ertelendi'].map(csv).join(';'));
        }
        return SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx).viewInsets.bottom),
          child:SizedBox(height:MediaQuery.of(ctx).size.height*.94,child:ListView(padding:const EdgeInsets.all(16),children:[
            const Text('Stok yenileme takvimi / kritik satın alma',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold,color:_purple)),
            const Text('Tüketim ve stok hareketlerine göre sipariş tarihleri. Stok kayıtları değiştirilmez.'),
            DropdownButtonFormField<int>(initialValue:selectedList,isExpanded:true,decoration:const InputDecoration(labelText:'Stok kaynağı'),
              items:[const DropdownMenuItem(value:0,child:Text('Tüm stok listeleri')),
                for(var i=0;i<_namedLists.length;i++) DropdownMenuItem(value:i+1,
                  child:Text((_namedLists[i]['title']??'Adsız').toString(),overflow:TextOverflow.ellipsis))],
              onChanged:(v)=>refresh((){selectedList=v??0;initialized=false;selected.clear();excluded.clear();priority.clear();})),
            Wrap(spacing:6,runSpacing:6,children:[
              for(final d in [30,60,90,180]) ChoiceChip(label:Text('$d gün geçmiş'),selected:historyDays==d,onSelected:(_)=>refresh(()=>historyDays=d)),
              for(final d in [7,14,30,60]) ChoiceChip(label:Text('$d gün ihtiyaç'),selected:horizonDays==d,onSelected:(_)=>refresh(()=>horizonDays=d)),
            ]),
            Row(children:[const Expanded(child:Text('Güvenlik süresi (gün)')),
              IconButton(onPressed:safetyDays==0?null:()=>refresh(()=>safetyDays--),icon:const Icon(Icons.remove_circle_outline)),
              Text('$safetyDays'),IconButton(onPressed:()=>refresh(()=>safetyDays=(safetyDays+1).clamp(0,30)),icon:const Icon(Icons.add_circle_outline))]),
            Row(children:[const Expanded(child:Text('Tedarik süresi (gün)')),
              IconButton(onPressed:leadDays==0?null:()=>refresh(()=>leadDays--),icon:const Icon(Icons.remove_circle_outline)),
              Text('$leadDays'),IconButton(onPressed:()=>refresh(()=>leadDays=(leadDays+1).clamp(0,30)),icon:const Icon(Icons.add_circle_outline))]),
            TextFormField(initialValue:budget.toStringAsFixed(0),keyboardType:const TextInputType.numberWithOptions(decimal:true),
              decoration:const InputDecoration(labelText:'Toplam bütçe (TL, 0 = sınırsız)'),
              onChanged:(v){final n=double.tryParse(v.replaceAll(',','.'));if(n!=null&&n.isFinite&&n>=0)refresh(()=>budget=n);}),
            SwitchListTile(title:const Text('Fiyatı bilinmeyenleri dahil et'),value:includeUnknown,onChanged:(v)=>refresh(()=>includeUnknown=v)),
            Card(color:const Color(0xFFF3E8FF),child:Padding(padding:const EdgeInsets.all(12),child:Column(
              crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('Yenilenecek: ${rows.length} • Acil: $urgentCount • 7 gün içinde: $upcoming'),
              Text('Planlanan: ${accepted.length} • Bütçeye sığmayan: ${deferred.length}'),
              Text('Tahmini toplam: ${_money(plannedCost)} • Seçilen: ${_money(spent)}',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text('Kalan bütçe: ${budget==0?'Sınırsız':_money(budget-spent)}'),
              if(budget>0) LinearProgressIndicator(value:(spent/budget).clamp(0.0,1.0)),
              Text('Geçmişi olmayan: $noHistory • Fiyatı olmayan: $noPrice • Süresi geçmiş stok: $expired'),
              if(noPrice>0) const Text('Fiyatı bilinmeyen ürünler toplam maliyete dahil değildir.',style:TextStyle(fontSize:12)),
              if(noHistory>0) const Text('Tüketim geçmişi olmayan ürünlerde sipariş tarihi bugüne alınabilir; tahmin sınırlıdır.',style:TextStyle(fontSize:12)),
            ]))),
            TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Ürün veya stok listesi ara'),onChanged:(v)=>refresh(()=>query=v)),
            Wrap(spacing:6,children:[for(final f in ['Tümü','Acil','7 gün','Seçilen','Ertelenen','Fiyat yok','Geçmiş yok'])
              ChoiceChip(label:Text(f),selected:status==f,onSelected:(_)=>refresh(()=>status=f))]),
            DropdownButtonFormField<String>(initialValue:sort,decoration:const InputDecoration(labelText:'Sıralama'),
              items:[for(final f in ['Sipariş tarihi','Öncelik','Maliyet','Ürün']) DropdownMenuItem(value:f,child:Text(f))],
              onChanged:(v)=>refresh(()=>sort=v??'Sipariş tarihi')),
            const SizedBox(height:8),
            const Text('Sipariş tarihi bazında planlanan listeler',style:TextStyle(fontWeight:FontWeight.bold)),
            for(final entry in buckets.entries) Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(
              crossAxisAlignment:CrossAxisAlignment.start,children:[
              Text('${entry.key} • ${entry.value.length} ürün • ${_money(entry.value.fold<double>(0,(v,r)=>v+_planNum(r['cost'])))}',style:const TextStyle(fontWeight:FontWeight.bold)),
              Text(entry.value.map((r)=>r['name'].toString()).join(', '),maxLines:3,overflow:TextOverflow.ellipsis),
              Align(alignment:Alignment.centerRight,child:TextButton.icon(onPressed:()=>createForDay(entry.key,entry.value),
                icon:const Icon(Icons.playlist_add),label:const Text('Bu tarihe liste oluştur'))),
            ]))),
            const Divider(),
            Text('Ürünler (${visible.length})',style:const TextStyle(fontWeight:FontWeight.bold)),
            for(final r in visible) Card(child:Padding(padding:const EdgeInsets.all(8),child:Column(
              crossAxisAlignment:CrossAxisAlignment.start,children:[
              CheckboxListTile(contentPadding:EdgeInsets.zero,value:selected.contains(r['id'])&&!excluded.contains(r['id']),
                title:Text('${r['name']} • ${r['risk']}'),
                subtitle:Text('${r['source']} • ${fmt(r['orderDay'] as DateTime)} • ${_planNumberText(_planNum(r['qty']))} ${r['unit']}'),
                onChanged:(v)=>refresh(() {if(v==true){selected.add(r['id'] as String);excluded.remove(r['id']);}else{selected.remove(r['id']);excluded.add(r['id'] as String);}})),
              Text('Stok: ${_planNumberText(_planNum(r['usable']))} • Günlük tüketim: ${_planNumberText(_planNum(r['daily']))} • Tahmini maliyet: ${r['known']==true?_money(_planNum(r['cost'])):'Fiyat bilinmiyor'}'),
              if(r['expired']==true) const Text('Son kullanma tarihi geçmiş stok kullanılabilir kabul edilmedi.',style:TextStyle(color:Colors.deepOrange)),
              if(r['movements']==0) const Text('Tüketim hareketi bulunamadı.',style:TextStyle(fontSize:12)),
              Wrap(spacing:6,children:[for(final p in ['Zorunlu','Normal','Ertelenebilir']) ChoiceChip(label:Text(p),
                selected:(priority[r['id']]??(r['urgent']==true?'Zorunlu':'Normal'))==p,
                onSelected:(_)=>refresh(()=>priority[r['id'] as String]=p))]),
            ]))),
            OutlinedButton.icon(onPressed:(){Clipboard.setData(ClipboardData(text:'\uFEFF${lines.join('\r\n')}'));_notice('Sipariş takvimi CSV olarak kopyalandı.');},
              icon:const Icon(Icons.copy_all_outlined),label:const Text('Sipariş takvimini CSV kopyala')),
            const Text('Planlama tahminidir. Aynı ürün farklı stok listelerinde ayrı değerlendirilir. Liste oluşturma dışında kayıt değiştirilmez.',style:TextStyle(fontSize:12)),
          ]))));
      }));
  }

  void _showKitchenForecastBudget() {
    var horizon = 14;
    var historyDays = 60;
    var safetyDays = 3;
    var budget = 1000.0;
    var onlyNeeded = false;
    var search = '';
    var listIndex = 0;
    var order = 'Öncelik';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final start = now.subtract(Duration(days: historyDays));
        final records = _namedLists;
        if (listIndex > records.length) listIndex = 0;
        final selected = listIndex == 0 ? records : [records[listIndex - 1]];
        final rows = <Map<String, dynamic>>[];
        var insufficientHistory = 0;
        var expired = 0;
        var unknownPrice = 0;
        for (final record in selected) {
          final title = (record['title'] ?? 'Adsız liste').toString();
          for (final item in (record['items'] as List? ?? const [])) {
            final name = item.toString();
            final quantity = _namedQuantity(record, name);
            final unit = (quantity['unit'] ?? 'Adet').toString();
            final stockInfo = _namedStock(record, name);
            final current = _planNum(stockInfo['amount']).clamp(0.0, double.infinity).toDouble();
            final expiryDays = _kitchenDaysUntil((stockInfo['expiry'] ?? '').toString());
            final usable = expiryDays != null && expiryDays < 0 ? 0.0 : current;
            if (expiryDays != null && expiryDays < 0 && current > 0) expired++;
            var consumed = 0.0;
            var movementCount = 0;
            DateTime? oldest;
            for (final movement in _stockMovements(record)) {
              if (movement['product']?.toString() != name || movement['reversed'] == true) continue;
              final date = _movementDate(movement);
              if (date == null || date.isBefore(start) || date.isAfter(now) ||
                  !_isConsumptionMovement(movement)) { continue ; }
              final raw = movement['change'];
              final change = raw is num ? raw.toDouble() : double.tryParse(raw?.toString() ?? '');
              if (change == null || !change.isFinite || change >= 0) continue;
              consumed -= change;
              movementCount++;
              if (oldest == null || date.isBefore(oldest)) oldest = date;
            }
            // Gözlenen ilk tüketim gününden bugüne kadar günlük ortalama.
            final observedDays = oldest == null ? 0.0 :
              (now.difference(oldest).inHours / 24.0).clamp(1.0, historyDays.toDouble());
            final daily = observedDays > 0 ? consumed / observedDays : 0.0;
            if (movementCount == 0) insufficientHistory++;
            final target = _planNum(stockInfo['target']);
            final minimum = _planNum(stockInfo['minimum']);
            final projected = daily * (horizon + safetyDays);
            final baseline = target > 0 ? target : (minimum > 0 ? minimum : 0.0);
            final required = projected > baseline ? projected : baseline;
            final deficit = (required - usable).clamp(0.0, double.infinity).toDouble();
            final coverage = daily > 0 ? usable / daily : null;
            final price = _stockUnitCost(record, name);
            final validPrice = price.isFinite && price > 0 ? price : null;
            if (deficit > 0 && validPrice == null) unknownPrice++;
            final cost = validPrice == null ? null : deficit * validPrice;
            final urgency = usable <= 0 ? 0 :
              (coverage != null && coverage <= safetyDays ? 1 :
              (coverage != null && coverage <= horizon ? 2 : 3));
            rows.add(<String, dynamic>{'name': name, 'list': title, 'unit': unit,
              'stock': current, 'usable': usable, 'expiry': expiryDays,
              'daily': daily, 'consumed': consumed, 'count': movementCount,
              'coverage': coverage, 'target': baseline, 'required': required,
              'deficit': deficit, 'price': validPrice, 'cost': cost,
              'urgency': urgency});
          }
        }
        final filtered = rows.where((r) =>
          (!onlyNeeded || (r['deficit'] as double) > 0) &&
          ('${r['name']} ${r['list']}'.toLowerCase().contains(search.toLowerCase()))).toList();
        if (order == 'Maliyet') {
          filtered.sort((a,b) => _planNum(b['cost']).compareTo(_planNum(a['cost'])));
        } else if (order == 'İsim') {
          filtered.sort((a,b) => a['name'].toString().compareTo(b['name'].toString()));
        } else if (order == 'Stok günü') {
          filtered.sort((a,b) => _planNum(a['coverage'] ?? 999999).compareTo(_planNum(b['coverage'] ?? 999999)));
        } else {
          filtered.sort((a,b) { final cmp = (a['urgency'] as int).compareTo(b['urgency'] as int);
            return cmp != 0 ? cmp : _planNum(b['deficit']).compareTo(_planNum(a['deficit'])); });
        }
        final needed = filtered.where((r) => _planNum(r['deficit']) > 0).toList();
        final knownCost = needed.fold<double>(0, (v,r) => v + _planNum(r['cost']));
        var remaining = budget;
        final affordable = <Map<String, dynamic>>[];
        final excluded = <Map<String, dynamic>>[];
        for (final r in needed) {
          final cost = r['cost'];
          if (cost == null || (cost as double) > remaining) { excluded.add(r); continue; }
          affordable.add(r);
          remaining -= cost;
        }
        String cell(Object? v) => '"${(v ?? '').toString().replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Akıllı tüketim tahmini / bütçe planı',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            const Text('Tahminler geçmiş stok çıkışlarına dayanır; sayım düzeltmeleri hariçtir. '
              'Fiyatlar kayıtlı stok birim maliyetinden alınır. Otomatik satın alma yapılmaz.'),
            Wrap(spacing: 10, runSpacing: 4, children: [
              DropdownButton<int>(value: horizon, items: [7,14,30,60].map((n) =>
                DropdownMenuItem(value: n, child: Text('$n günlük plan'))).toList(),
                onChanged: (v) { if (v != null) refresh(() => horizon = v); }),
              DropdownButton<int>(value: historyDays, items: [30,60,90,180].map((n) =>
                DropdownMenuItem(value: n, child: Text('$n gün geçmiş'))).toList(),
                onChanged: (v) { if (v != null) refresh(() => historyDays = v); }),
              DropdownButton<int>(value: safetyDays, items: [0,3,7,14].map((n) =>
                DropdownMenuItem(value: n, child: Text('$n gün güvenlik'))).toList(),
                onChanged: (v) { if (v != null) refresh(() => safetyDays = v); }),
              DropdownButton<int>(value: listIndex, items: [
                const DropdownMenuItem(value: 0, child: Text('Tüm stok listeleri')),
                ...List.generate(records.length, (i) => DropdownMenuItem(value: i + 1,
                  child: Text((records[i]['title'] ?? 'Adsız liste').toString(),
                    overflow: TextOverflow.ellipsis)))],
                onChanged: (v) { if (v != null) refresh(() => listIndex = v); }),
            ]),
            TextFormField(initialValue: budget.toStringAsFixed(0),
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Simülasyon bütçesi (TL)',
                prefixIcon: Icon(Icons.account_balance_wallet_outlined)),
              onChanged: (v) { final parsed = double.tryParse(v.replaceAll(',', '.'));
                if (parsed != null && parsed.isFinite && parsed >= 0) refresh(() => budget = parsed); }),
            TextField(decoration: const InputDecoration(labelText: 'Ürün veya liste ara',
              prefixIcon: Icon(Icons.search)), onChanged: (v) => refresh(() => search = v)),
            Wrap(spacing: 10, children: [
              FilterChip(label: const Text('Yalnızca ihtiyaçlar'), selected: onlyNeeded,
                onSelected: (v) => refresh(() => onlyNeeded = v)),
              DropdownButton<String>(value: order, items: ['Öncelik','Maliyet','Stok günü','İsim']
                .map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(),
                onChanged: (v) { if (v != null) refresh(() => order = v); }),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Görüntülenen: ${filtered.length} • Alım ihtiyacı: ${needed.length}'),
                Text('Bilinen satın alma maliyeti: ${_money(knownCost)}'),
                Text('Bütçe: ${_money(budget)} • Bilinen fark: ${_money(budget - knownCost)}'),
                LinearProgressIndicator(value: budget > 0 ? (knownCost / budget).clamp(0.0, 1.0) : 0),
                Text('Öncelik sırasıyla bütçeye sığan: ${affordable.length} ürün • '
                  'Bilinen kalan bütçe: ${_money(remaining)}'),
                if (excluded.isNotEmpty) Text('${excluded.length} ürün bütçeye sığmadı veya fiyatı bilinmiyor.',
                  style: const TextStyle(color: Colors.deepOrange)),
                if (unknownPrice > 0) Text('$unknownPrice ihtiyaç ürününde fiyat eksik; maliyet alt sınırdır.'),
                if (insufficientHistory > 0) Text('$insufficientHistory ürünün tüketim geçmişi yok; '
                  'varsa hedef/minimum stok seviyesi kullanıldı.'),
                if (expired > 0) Text('$expired ürünün SKT geçmiş stoku kullanılabilir sayılmadı.'),
              ]))),
            const Text('Önerilen alımlar (stok ve birim bazında)',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (filtered.isEmpty) const ListTile(title: Text('Bu filtreye uygun ürün yok.')),
            ...filtered.take(100).map((r) {
              final deficit = _planNum(r['deficit']);
              final coverage = r['coverage'] as double?;
              final expiry = r['expiry'] as int?;
              final isAffordable = affordable.contains(r);
              return Card(child: ListTile(
                leading: Icon(deficit <= 0 ? Icons.check_circle_outline :
                  isAffordable ? Icons.shopping_cart_outlined : Icons.warning_amber_outlined,
                  color: deficit <= 0 ? Colors.green : isAffordable ? _purple : Colors.deepOrange),
                title: Text('${r['name']} • ${r['list']}'),
                subtitle: Text('Stok: ${_planNum(r['stock']).toStringAsFixed(2)} ${r['unit']} • '
                  'Günlük: ${_planNum(r['daily']).toStringAsFixed(2)}\n'
                  'Yeterlilik: ${coverage == null ? 'Veri yok' : '${coverage.toStringAsFixed(1)} gün'} • '
                  'Hedef: ${_planNum(r['required']).toStringAsFixed(2)}\n'
                  'Önerilen alım: ${deficit.toStringAsFixed(2)} ${r['unit']}'
                  '${expiry != null && expiry < 0 ? ' • SKT geçmiş' : ''}'),
                trailing: Text(r['cost'] == null ? 'Fiyat yok' : _money(_planNum(r['cost']))),
              ));
            }),
            if (filtered.length > 100) Text('İlk 100 ürün gösteriliyor (${filtered.length} kayıt).'),
            FilledButton.tonalIcon(onPressed: () async {
              final csv = <String>['Liste;Ürün;Birim;Mevcut;Kullanılabilir;Günlük tüketim;'
                'Kalan gün;Hedef;Alım önerisi;Birim fiyat;Maliyet;Bütçeye sığar'];
              for (final r in filtered) {
                csv.add([r['list'],r['name'],r['unit'],r['stock'],r['usable'],
                  r['daily'],r['coverage'],r['required'],r['deficit'],r['price'],
                  r['cost'],affordable.contains(r) ? 'Evet' : 'Hayır']
                  .map(cell).join(';'));
              }
              await Clipboard.setData(ClipboardData(text: csv.join('\n')));
              if (mounted) _notice('Tahmin ve bütçe CSV raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Tahmin / bütçe CSV kopyala')),
            const Text('Uyarı: Bu panel tahmini tüketim hızını kullanır. Farklı listelerde '
              'aynı ürün varsa ayrı satırdır. Birim dönüşümü ve gerçek fiyat doğrulaması '
              'yapılmaz. Bütçe simülasyonu yalnızca fiyatı bilinen tam ürün alımlarını seçer.',
              style: TextStyle(fontSize: 12)),
          ])));
      }));
  }

  void _showKitchenConsumptionAnalytics() {
    var days = 30;
    var listFilter = 'Tümü';
    var query = '';
    var onlyConsumption = true;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final since = now.subtract(Duration(days: days));
        final names = _namedLists.map((r) => r['title']?.toString() ?? 'Adsız liste').toSet().toList()..sort();
        if (listFilter != 'Tümü' && !names.contains(listFilter)) listFilter = 'Tümü';
        final rows = <Map<String, dynamic>>[];
        var invalidDates = 0;
        var invalidAmounts = 0;
        var reversed = 0;
        for (final list in _namedLists) {
          final title = list['title']?.toString() ?? 'Adsız liste';
          if (listFilter != 'Tümü' && title != listFilter) continue;
          for (final movement in _stockMovements(list)) {
            if (movement['reversed'] == true) { reversed++; continue; }
            final date = _movementDate(movement);
            if (date == null) { invalidDates++; continue; }
            if (date.isBefore(since) || date.isAfter(now)) continue;
            final rawChange = movement['change'];
            final change = rawChange is num ? rawChange.toDouble() : double.tryParse(rawChange?.toString() ?? '');
            if (change == null || !change.isFinite) { invalidAmounts++; continue; }
            if (onlyConsumption && change >= 0) continue;
            final product = movement['product']?.toString() ?? '';
            if (!('$product $title ${movement['reason'] ?? ''}').toLowerCase().contains(query.toLowerCase())) continue;
            rows.add(<String, dynamic>{'date': date, 'list': title, 'product': product,
              'unit': movement['unit']?.toString() ?? '', 'change': change,
              'reason': movement['reason']?.toString() ?? ''});
          }
        }
        rows.sort((a, b) => (b['date'] as DateTime).compareTo(a['date'] as DateTime));
        final groups = <String, Map<String, dynamic>>{};
        var totalIn = 0.0;
        var totalOut = 0.0;
        for (final row in rows) {
          final change = row['change'] as double;
          if (change < 0) { totalOut += -change; } else { totalIn += change; }
          final key = '${row['product']}|${row['unit']}';
          final group = groups.putIfAbsent(key, () => <String, dynamic>{
            'product': row['product'], 'unit': row['unit'], 'out': 0.0, 'in': 0.0, 'count': 0});
          group['count'] = (group['count'] as int) + 1;
          if (change < 0) { group['out'] = (group['out'] as double) - change; }
          else { group['in'] = (group['in'] as double) + change; }
        }
        final ranked = groups.values.toList()..sort((a,b) => (b['out'] as double).compareTo(a['out'] as double));
        final meals = _kitchenMeals.where((m) {
          final d = DateTime.tryParse((m['stockDeductedAt'] ?? m['preparedAt'] ?? '').toString());
          return d != null && !d.isBefore(since) && !d.isAfter(now) &&
            (listFilter == 'Tümü' || m['stockDeductedList'] == listFilter);
        }).toList();
        final stockedMeals = meals.where((m) => m['stockDeductedAt'] != null).toList();
        final mealCost = stockedMeals.fold<double>(0, (sum,m) => sum + _planNum(m['stockDeductedCost']));
        final knownPortions = stockedMeals.fold<double>(0, (sum,m) => sum + _planNum(m['preparedPortions']));
        final missingCost = stockedMeals.where((m) => m['preparedCostIncomplete'] == true).length;
        String csv(String value) => '"${value.replaceAll('"', '""')}"';
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Mutfak tüketim analitiği', style: TextStyle(fontSize: 20,
              fontWeight: FontWeight.bold, color: _purple)),
            const Text('Hareketler kaydedildiği liste üzerinden değerlendirilir. Farklı birimler toplanmaz; toplam giriş/çıkış yalnızca işlem göstergesidir.'),
            Wrap(spacing: 8, runSpacing: 8, children: [
              DropdownButton<int>(value: days, items: [7,14,30,60,90,180,365]
                .map((n) => DropdownMenuItem(value: n, child: Text('Son $n gün'))).toList(),
                onChanged: (n) { if(n != null) refresh(() => days = n); }),
              DropdownButton<String>(value: listFilter, items: ['Tümü', ...names]
                .map((n) => DropdownMenuItem(value: n, child: Text(n,
                  overflow: TextOverflow.ellipsis))).toList(),
                onChanged: (n) { if(n != null) refresh(() => listFilter = n); }),
            ]),
            TextField(decoration: const InputDecoration(prefixIcon: Icon(Icons.search),
              labelText: 'Ürün, liste veya işlem nedeni ara'),
              onChanged: (v) => refresh(() => query = v)),
            SwitchListTile(title: const Text('Yalnızca tüketim hareketleri'),
              value: onlyConsumption, onChanged: (v) => refresh(() => onlyConsumption = v)),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Hareket: ${rows.length} • Ürün/birim grubu: ${ranked.length}'),
                Text('Çıkış toplamı: ${totalOut.toStringAsFixed(2)} (karma birim)'),
                if (!onlyConsumption) Text('Giriş toplamı: ${totalIn.toStringAsFixed(2)} (karma birim)'),
                Text('Stoktan düşülen öğün: ${stockedMeals.length} • Porsiyon: ${knownPortions.toStringAsFixed(1)}'),
                Text('Bilinen öğün maliyeti: ${_money(mealCost)}'),
                if (knownPortions > 0) Text('Bilinen maliyet / porsiyon: ${_money(mealCost / knownPortions)}'),
                if (missingCost > 0) Text('$missingCost öğünün maliyeti eksik olabilir.',
                  style: const TextStyle(color: Colors.deepOrange)),
                if (invalidDates + invalidAmounts + reversed > 0)
                  Text('Hariç tutulan: $invalidDates tarihsiz, $invalidAmounts miktarı geçersiz, $reversed ters çevrilmiş.'),
              ]))),
            const Text('En çok tüketilen ürünler (ürün ve birim ayrı)',
              style: TextStyle(fontWeight: FontWeight.bold)),
            if (ranked.isEmpty) const ListTile(title: Text('Bu aralıkta hareket bulunamadı.')),
            ...ranked.take(30).map((g) => ListTile(dense: true,
              title: Text('${g['product']} • ${g['unit']}'),
              subtitle: Text('${g['count']} işlem • Günlük ortalama: ${((g['out'] as double)/days).toStringAsFixed(2)}'),
              trailing: Text((g['out'] as double).toStringAsFixed(2)))),
            const Divider(),
            const Text('Son stok hareketleri', style: TextStyle(fontWeight: FontWeight.bold)),
            ...rows.take(50).map((r) => ListTile(dense: true,
              title: Text('${r['product']} • ${r['change']} ${r['unit']}'),
              subtitle: Text('${r['list']} • ${(r['date'] as DateTime).toIso8601String().substring(0,10)}\n${r['reason']}'))),
            FilledButton.tonalIcon(onPressed: () async {
              final lines = <String>['Tarih;Liste;Ürün;Birim;Değişim;Neden',
                ...rows.map((r) => [
                  (r['date'] as DateTime).toIso8601String(), r['list'].toString(),
                  r['product'].toString(), r['unit'].toString(),
                  r['change'].toString(), r['reason'].toString(),
                ].map(csv).join(';'))];
              await Clipboard.setData(ClipboardData(text: lines.join('\n')));
              if (mounted) _notice('${rows.length} stok hareketi CSV olarak kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Hareketleri CSV kopyala')),
            const Text('Not: Bu rapor muhasebe gideri değildir. Stok hareketleri maliyet bilgisi taşımadığında parasal tutar hesaplanmaz. Öğün maliyeti kayıtlı tahmindir.',
              style: TextStyle(fontSize: 12)),
          ])));
      }));
  }

  void _showKitchenMonthlyOverview() {
    var monthOffset = 0;
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => StatefulBuilder(builder: (ctx, refresh) {
        final now = DateTime.now();
        final month = DateTime(now.year, now.month + monthOffset);
        final start = DateTime(month.year, month.month);
        final end = DateTime(month.year, month.month + 1);
        final weekStart = _kitchenWeekStart(start);
        var knownCost = 0.0;
        var missing = 0;
        var meals = 0;
        for (final meal in _kitchenMeals) {
          final date = DateTime.tryParse(meal['date']?.toString() ?? '');
          if (date == null || date.isBefore(start) || !date.isBefore(end)) continue;
          meals++;
          Map<String, dynamic>? recipe;
          for (final item in _customRecipes) {
            if (item['name']?.toString() == meal['recipe']?.toString()) { recipe = item; break; }
          }
          if (recipe == null) { missing++; continue; }
          final count = _planNum(meal['portions']).toInt().clamp(1, 100);
          final result = _customRecipeCost(recipe, count);
          knownCost += _planNum(result['known']);
          missing += (result['missing'] as List).length;
        }
        var wasteCost = 0.0;
        var wasteCount = 0;
        final reasons = <String, double>{};
        for (final row in _kitchenWaste) {
          final date = DateTime.tryParse(row['date']?.toString() ?? '');
          if (date == null || date.isBefore(start) || !date.isBefore(end)) continue;
          wasteCount++;
          final cost = _planNum(row['cost']);
          wasteCost += cost;
          final reason = row['reason']?.toString() ?? 'Diğer';
          reasons[reason] = (reasons[reason] ?? 0) + cost;
        }
        var weeklyBudget = 0.0;
        for (var week = weekStart; week.isBefore(end); week = week.add(const Duration(days: 7))) {
          // Yalnızca ay içinde başlayan haftaların bütçeleri sayılır.
          if (!week.isBefore(start)) weeklyBudget += _kitchenWeeklyBudgets[_kitchenWeekKey(week)] ?? 0;
        }
        final combined = knownCost + wasteCost;
        return SafeArea(child: FractionallySizedBox(heightFactor: .86,
          child: ListView(padding: const EdgeInsets.all(16), children: [
            const Text('Aylık mutfak ve israf kontrol paneli',
              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: _purple)),
            Row(children: [
              IconButton(onPressed: () => refresh(() => monthOffset--), icon: const Icon(Icons.chevron_left)),
              Expanded(child: Text('${month.month.toString().padLeft(2, '0')}.${month.year}',
                textAlign: TextAlign.center, style: const TextStyle(fontWeight: FontWeight.bold))),
              IconButton(onPressed: () => refresh(() => monthOffset++), icon: const Icon(Icons.chevron_right)),
            ]),
            Card(color: _pink, child: Padding(padding: const EdgeInsets.all(14),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('Planlanan öğün: $meals'),
                Text('Bilinen yemek maliyeti: ${_money(knownCost)}'),
                Text('İsraf kaybı: ${_money(wasteCost)} ($wasteCount kayıt)'),
                Text('Yemek maliyeti + israf: ${_money(combined)}',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
                Text('Ay içinde başlayan haftaların bütçeleri: ${_money(weeklyBudget)}'),
                if (weeklyBudget > 0) ...[
                  Text('Gösterge farkı: ${_money(weeklyBudget - combined)}'),
                  LinearProgressIndicator(value: (combined / weeklyBudget).clamp(0.0, 1.0)),
                ],
                if (missing > 0) Text('$missing öğün veya malzemenin maliyeti eksik.',
                  style: const TextStyle(color: Colors.deepOrange)),
              ]))),
            const Text('İsraf nedenleri', style: TextStyle(fontWeight: FontWeight.bold)),
            if (reasons.isEmpty) const ListTile(title: Text('Bu ay israf kaydı yok.')),
            ...reasons.entries.map((e) => ListTile(dense: true,
              title: Text(e.key), trailing: Text(_money(e.value)))),
            const Text('Not: Haftalık bütçeler takvim aylarıyla tam örtüşmeyebilir. '
              'Yemek maliyetleri gerçekleşmiş harcama değil, kayıtlı fiyatlardan tahmindir. '
              'İsraf tutarı ayrıca girilen kayıp değeridir.', style: TextStyle(fontSize: 12)),
            FilledButton.tonalIcon(onPressed: () async {
              final report = 'Ay;Öğün;Bilinen yemek maliyeti TL;Eksik veri;İsraf kaybı TL;'
                'İsraf kaydı;Ay içinde başlayan hafta bütçeleri TL\n'
                '${month.year}-${month.month.toString().padLeft(2, '0')};$meals;$knownCost;'
                '$missing;$wasteCost;$wasteCount;$weeklyBudget';
              await Clipboard.setData(ClipboardData(text: report));
              if (mounted) _notice('Aylık mutfak raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('Aylık CSV raporunu kopyala')),
          ])));
      }));
  }


  // Paket 39 kapanış kontrolü: yalnızca mevcut kayıtları okur; hiçbir veriyi silmez.
  List<Map<String, String>> _kitchenAuditItems() {
    final rows = <Map<String, String>>[];
    void add(String area, String title, String detail, String severity) {
      rows.add(<String, String>{'area': area, 'title': title,
        'detail': detail, 'severity': severity});
    }
    if (_customRecipes.isEmpty) {
      add('Tarif', 'Kişisel tarif bulunmuyor',
        'Porsiyon ve maliyet hesapları için kişisel tarif ekleyin.', 'Bilgi');
    }
    for (final recipe in _customRecipes) {
      final name = recipe['title']?.toString() ??
        recipe['name']?.toString() ?? 'Adsız tarif';
      final portions = _planNum(recipe['basePortions']);
      if (portions <= 0) {
        add('Tarif', '$name: porsiyon bilgisi eksik',
          'Tarifin temel porsiyon sayısını kontrol edin.', 'Uyarı');
      }
    }
    final seen = <String>{};
    for (final item in _items) {
      final normalized = item.trim().toLowerCase();
      if (!seen.add(normalized)) {
        add('Alışveriş', 'Tekrarlanan ürün: $item',
          'Aynı isimle birden fazla aktif ürün bulunuyor.', 'Uyarı');
      }
      if (!_prices.containsKey(item)) {
        add('Alışveriş', 'Tahmini fiyat eksik: $item',
          'Bütçe toplamı bu ürünün maliyetini içermiyor.', 'Bilgi');
      }
      if (_done.contains(item) && !_actualPrices.containsKey(item)) {
        add('Alışveriş', 'Gerçek fiyat eksik: $item',
          'Tamamlanan ürünün gerçek tutarı girilmemiş.', 'Bilgi');
      }
    }
    if (_budget > 0) {
      final total = _items.fold<double>(0, (a, n) => a + (_prices[n] ?? 0));
      if (total > _budget) {
        add('Bütçe', 'Aktif alışveriş bütçesi aşılıyor',
          'Tahmini ${_money(total)} / bütçe ${_money(_budget)}.', 'Uyarı');
      }
    }
    for (final plan in _shoppingPlans) {
      final title = plan['title']?.toString() ?? 'Adsız plan';
      final budget = _planNum(plan['budget']);
      if (budget > 0 && _planTotal(plan) > budget) {
        add('Plan', '$title: bütçe aşımı',
          'Plan toplamı ${_money(_planTotal(plan))}, bütçe ${_money(budget)}.',
          'Uyarı');
      }
    }
    for (final meal in _kitchenMeals) {
      final recipeName = meal['recipe']?.toString() ?? '';
      if (recipeName.trim().isEmpty) {
        add('Yemek planı', 'Tarifsiz öğün kaydı',
          'Öğünün tarif alanını kontrol edin.', 'Uyarı');
      }
    }
    for (final row in _kitchenStockRows()) {
      final product = row['name']?.toString() ?? 'Ürün';
      final days = _kitchenDaysUntil(row['expiry']?.toString() ?? '');
      if (days != null && days < 0) {
        add('Stok', 'SKT geçmiş: $product',
          'Son kullanma tarihi ${-days} gün önce geçmiş. Ürünü kontrol edin.',
          'Kritik');
      } else if (days != null && days <= 3) {
        add('Stok', 'SKT yaklaşıyor: $product',
          'Son kullanma tarihine $days gün kaldı.', 'Uyarı');
      }
    }
    if (_ingredientUnitPrices.isEmpty && _customRecipes.isNotEmpty) {
      add('Maliyet', 'Birim fiyat tanımlanmamış',
        'Tarif maliyetleri için malzeme birim fiyatlarını kaydedin.', 'Uyarı');
    }
    if (_savedMenuDrafts.isEmpty && _customRecipes.isNotEmpty) {
      add('Menü', 'Kaydedilmiş menü taslağı yok',
        'Karşılaştırma için en az iki taslak kaydedebilirsiniz.', 'Bilgi');
    }
    // Modüller arası ilişkiler: kayıtları değiştirmeden referans ve miktar denetimi.
    final knownRecipes = _allKitchenRecipes().keys.toSet();
    final recipeNames = <String>{};
    for (final recipe in _customRecipes) {
      final name = (recipe['name'] ?? '').toString().trim();
      if (name.isEmpty) {
        add('Tarif', 'İsimsiz kişisel tarif', 'Tarif adını düzenleyin.', 'Kritik');
      } else if (!recipeNames.add(_normalizeName(name))) {
        add('Tarif', 'Yinelenen tarif adı: $name',
          'Aynı isimli tarifler menü ve maliyet eşleştirmesini belirsizleştirebilir.', 'Uyarı');
      }
      final base = _planNum(recipe['basePortions']);
      if (base <= 0 || base > 30) {
        add('Tarif', '$name: temel porsiyon geçersiz',
          'Temel porsiyon 1–30 aralığında olmalı.', 'Uyarı');
      }
      final ingredients = recipe['ingredients'];
      if (ingredients is! List || ingredients.isEmpty) {
        add('Tarif', '$name: malzeme listesi boş',
          'Tarife en az bir malzeme ekleyin.', 'Uyarı');
        continue;
      }
      for (final ingredient in ingredients) {
        if (ingredient is! Map) {
          add('Tarif', '$name: geçersiz malzeme kaydı',
            'Malzeme kaydı nesne biçiminde olmalı.', 'Kritik');
          continue;
        }
        final part = (ingredient['name'] ?? '').toString().trim();
        final amount = _planNum(ingredient['quantity']);
        final unit = (ingredient['unit'] ?? '').toString();
        if (part.isEmpty || amount <= 0 || !['adet', 'g', 'kg', 'ml', 'L'].contains(unit)) {
          add('Tarif', '$name: hatalı malzeme ${part.isEmpty ? '(adsız)' : part}',
            'Malzeme adı, pozitif miktar ve geçerli birim gerekli.', 'Uyarı');
        }
      }
    }
    void checkMeal(Map<String, dynamic> meal, String source) {
      final recipe = (meal['recipe'] ?? meal['name'] ?? '').toString().trim();
      if (recipe.isNotEmpty && !knownRecipes.contains(recipe)) {
        add(source, 'Bulunamayan tarif: $recipe',
          'Tarif silinmiş veya yeniden adlandırılmış olabilir. Kaydı inceleyin.', 'Uyarı');
      }
      final portions = meal['portions'];
      if (portions != null && (_planNum(portions) <= 0 || _planNum(portions) > 30)) {
        add(source, 'Geçersiz porsiyon: $recipe',
          'Porsiyon değeri 1–30 aralığında olmalı.', 'Uyarı');
      }
      final date = meal['date'];
      if (date != null && date.toString().isNotEmpty &&
          DateTime.tryParse(date.toString()) == null) {
        add(source, 'Geçersiz tarih: $recipe',
          'Öğün tarihini kontrol edin.', 'Uyarı');
      }
    }
    for (final meal in _kitchenMeals) {
      checkMeal(meal, 'Yemek planı');
    }
    for (final draft in _savedMenuDrafts) {
      final title = (draft['title'] ?? 'Adsız taslak').toString();
      final meals = draft['meals'];
      if (meals is! List) {
        add('Menü', '$title: öğün listesi geçersiz',
          'Taslak öğünleri liste biçiminde saklanmalı.', 'Kritik');
        continue;
      }
      for (final entry in meals) {
        if (entry is Map) {
          checkMeal(Map<String, dynamic>.from(entry), 'Menü: $title');
        } else {
          add('Menü', '$title: geçersiz öğün',
            'Taslakta öğün kaydı nesne biçiminde değil.', 'Kritik');
        }
      }
    }
    for (final price in _ingredientUnitPrices.entries) {
      if (price.value < 0 || !price.value.isFinite) {
        add('Maliyet', 'Geçersiz birim fiyat: ${price.key}',
          'Fiyat sıfır veya pozitif, sonlu bir sayı olmalı.', 'Kritik');
      }
    }
    for (final budget in _kitchenWeeklyBudgets.entries) {
      if (budget.value < 0 || !budget.value.isFinite) {
        add('Bütçe', 'Geçersiz haftalık bütçe: ${budget.key}',
          'Bütçe sıfır veya pozitif, sonlu bir sayı olmalı.', 'Kritik');
      }
    }
    return rows;
  }

  // Yedek içindeki JSON koleksiyonlarının temel eleman türlerini doğrular.
  // Hatalı kayıtları sessizce atmak yerine geri yüklemeyi durdurur.
  List<String> _kitchenSchemaIssues(String key, dynamic value) {
    final issues = <String>[];
    const textLists = <String>{'alisveris', 'tamamlanan'};
    const recordLists = <String>{
      'paket39_shopping_history_v1', 'paket39_named_shopping_lists_v1',
      'paket39_shopping_plans_v1', 'paket39_kitchen_waste_v1',
      'paket39_kitchen_meals_v1', 'paket39_custom_recipes_v1',
      'paket39_meal_templates_v1', 'paket39_saved_menu_drafts_v1',
      'paket39_kitchen_trash_v1',
    };
    const numericMaps = <String>{
      'paket39_shopping_prices_v1', 'paket39_shopping_actual_prices_v1',
      'paket39_monthly_shopping_budgets_v1', 'paket39_consumption_goals_v1',
      'paket39_ingredient_unit_prices_v1', 'paket39_kitchen_weekly_budgets_v1',
    };
    if (value is List) {
      for (var i = 0; i < value.length; i++) {
        if (textLists.contains(key) && value[i] is! String) {
          issues.add('$key[$i]: metin bekleniyor');
        } else if (recordLists.contains(key) && value[i] is! Map) {
          issues.add('$key[$i]: kayıt nesnesi bekleniyor');
        } else if (key == _kitchenTrashKey && value[i] is Map) {
          final deleted = value[i] as Map;
          const types = <String>{'lists', 'plans', 'recipes', 'drafts', 'meals', 'waste'};
          if (deleted['id'] is! String || !types.contains(deleted['type']) ||
              deleted['record'] is! Map || deleted['index'] is! num ||
              (deleted['index'] as num) < 0 || deleted['label'] is! String ||
              deleted['deletedAt'] is! String) {
            issues.add('$key[$i]: geçersiz silinmiş kayıt');
          }
        }
        if (issues.length >= 12) break;
      }
    } else if (value is Map) {
      for (final entry in value.entries) {
        if (entry.key is! String) {
          issues.add('$key: metin anahtar bekleniyor');
        } else if (numericMaps.contains(key) &&
            (entry.value is! num || !(entry.value as num).isFinite)) {
          issues.add('$key / ${entry.key}: geçerli sayı bekleniyor');
        } else if (key == 'paket39_shopping_details_v1' && entry.value is! Map) {
          issues.add('$key / ${entry.key}: detay nesnesi bekleniyor');
        }
        if (issues.length >= 12) break;
      }
    }
    return issues;
  }

  // Kapanış güvenlik aracı: tüm mutfak/alışveriş verileri tek JSON yedeğinde.
  // Panoya kopyalanır; mevcut kayıtlar üzerinde değişiklik yapmaz.
  Future<void> _copyKitchenBackup() async {
    final prefs = await SharedPreferences.getInstance();
    const keys = <String>[
      'alisveris', 'tamamlanan', 'paket39_shopping_details_v1',
      'paket39_shopping_budget_v1', 'paket39_shopping_prices_v1',
      'paket39_shopping_actual_prices_v1', 'paket39_shopping_history_v1',
      'paket39_monthly_shopping_budgets_v1',
      'paket39_named_shopping_lists_v1', 'paket39_shopping_plans_v1',
      'paket39_consumption_goals_v1', 'paket39_kitchen_waste_v1',
      'paket39_kitchen_meals_v1', 'paket39_custom_recipes_v1',
      'paket39_ingredient_unit_prices_v1', 'paket39_meal_templates_v1',
      'paket39_kitchen_weekly_budgets_v1', 'paket39_saved_menu_drafts_v1',
      'paket39_kitchen_trash_v1',
    ];
    final data = <String, dynamic>{};
    for (final key in keys) {
      if (!prefs.containsKey(key)) continue;
      final value = prefs.get(key);
      if (value is String || value is num || value is bool) {
        data[key] = value;
      }
    }
    final backup = jsonEncode(<String, dynamic>{
      'format': 'anne_bebek_paket39_backup_v1',
      'createdAt': DateTime.now().toIso8601String(),
      'entries': data,
    });
    await Clipboard.setData(ClipboardData(text: backup));
    if (mounted) _notice('JSON yedeği panoya kopyalandı (${data.length} alan; çöp kutusu dahil). Güvenli bir yerde saklayın.');
  }

  // Kapanış: yedekten geri yükleme. Yalnızca bu modülün bilinen
  // anahtarlarını kabul eder; diğer uygulama verilerine dokunmaz.
  Future<void> _restoreKitchenBackup() async {
    final controller = TextEditingController();
    final input = await showDialog<String>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Mutfak yedeğini geri yükle'),
      content: SizedBox(width: 520, child: Column(mainAxisSize: MainAxisSize.min, children: [
        const Text('Önceden kaydettiğiniz JSON yedeğini yapıştırın. Önce biçim ve alanlar doğrulanacak; onay olmadan hiçbir kayıt değişmeyecek.'),
        const SizedBox(height: 10),
        TextField(controller: controller, minLines: 4, maxLines: 8,
          decoration: const InputDecoration(border: OutlineInputBorder(), hintText: '{"format": ...}')),
      ])),
      actions: [
        TextButton.icon(onPressed: () async {
          final clip = await Clipboard.getData('text/plain');
          if (clip?.text != null) controller.text = clip!.text!;
        }, icon: const Icon(Icons.content_paste), label: const Text('Panodan yapıştır')),
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Vazgeç')),
        FilledButton(onPressed: () => Navigator.pop(ctx, controller.text), child: const Text('Yedeği kontrol et'))],
    ));
    disposeAfterDialog(controller);
    if (input == null || !mounted) return;
    try {
      if (input.length > 8000000) throw const FormatException('Yedek boyutu 8 MB sınırını aşıyor.');
      final decoded = jsonDecode(input);
      if (decoded is! Map || decoded['format'] != 'anne_bebek_paket39_backup_v1' || decoded['entries'] is! Map) {
        throw const FormatException('Desteklenmeyen yedek biçimi.');
      }
      final entries = decoded['entries'] as Map;
      const listKeys = <String>{
        'alisveris', 'tamamlanan', 'paket39_shopping_history_v1',
        'paket39_named_shopping_lists_v1', 'paket39_shopping_plans_v1',
        'paket39_kitchen_waste_v1', 'paket39_kitchen_meals_v1',
        'paket39_custom_recipes_v1', 'paket39_meal_templates_v1',
        'paket39_saved_menu_drafts_v1', 'paket39_kitchen_trash_v1',
      };
      const mapKeys = <String>{
        'paket39_shopping_details_v1', 'paket39_shopping_prices_v1',
        'paket39_shopping_actual_prices_v1', 'paket39_monthly_shopping_budgets_v1',
        'paket39_consumption_goals_v1', 'paket39_ingredient_unit_prices_v1',
        'paket39_kitchen_weekly_budgets_v1',
      };
      const numberKeys = <String>{'paket39_shopping_budget_v1'};
      final allowed = <String>{...listKeys, ...mapKeys, ...numberKeys};
      if (entries.isEmpty) throw const FormatException('Yedekte kayıt bulunamadı.');
      final restored = <String, Object>{};
      for (final entry in entries.entries) {
        final key = entry.key;
        final value = entry.value;
        if (key is! String || !allowed.contains(key)) {
          throw FormatException('Bilinmeyen veri alanı: $key');
        }
        if (numberKeys.contains(key)) {
          if (value is! num || !value.isFinite) throw FormatException('$key: sayı bekleniyor.');
          restored[key] = value.toDouble();
        } else {
          if (value is! String) throw FormatException('$key: metin bekleniyor.');
          final parsed = jsonDecode(value);
          if (listKeys.contains(key) && parsed is! List) throw FormatException('$key: liste bekleniyor.');
          if (mapKeys.contains(key) && parsed is! Map) throw FormatException('$key: nesne bekleniyor.');
          final issues = _kitchenSchemaIssues(key, parsed);
          if (issues.isNotEmpty) throw FormatException(issues.first);
          restored[key] = value;
        }
      }
      if (!mounted) return;
      final prefsPreview = await SharedPreferences.getInstance();
      final changes = <String>[];
      var emptyCollections = 0;
      for (final entry in restored.entries) {
        final oldValue = prefsPreview.get(entry.key);
        final newValue = entry.value;
        if (oldValue == newValue) continue;
        String detail = 'Değer değişecek';
        if (newValue is String) {
          final parsed = jsonDecode(newValue);
          if (parsed is List || parsed is Map) {
            final count = parsed is List ? parsed.length : (parsed as Map).length;
            detail = entry.key == _kitchenTrashKey
                ? '$count silinmiş kayıt (çöp kutusu)'
                : '$count kayıt/alan';
            if (count == 0 && oldValue != null) emptyCollections++;
          }
        }
        changes.add('${entry.key}: $detail${oldValue == null ? ' (yeni)' : ' (üzerine yazılacak)'}');
      }
      if (changes.isEmpty) {
        _notice('Yedekteki veriler zaten mevcut kayıtlarla aynı. Değişiklik yapılmadı.');
        return;
      }
      if (!mounted) return;
      final confirmed = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
        title: const Text('Geri yükleme önizlemesi'),
        content: SizedBox(width: 540, child: SingleChildScrollView(child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min,
          children: [
            Text('${restored.length} alan kontrol edildi; ${changes.length} alan değişecek.'),
            if (emptyCollections > 0) Padding(padding: const EdgeInsets.only(top: 8),
              child: Text('Dikkat: $emptyCollections mevcut veri alanı boş liste/nesne ile değiştirilecek.',
                style: const TextStyle(color: Colors.red, fontWeight: FontWeight.bold))),
            const SizedBox(height: 8),
            const Text('Geri yükleme mevcut kayıtların üzerine yazabilir. Önce güncel JSON yedeğinizi saklayın.'),
            const Divider(),
            ...changes.map((v) => Padding(padding: const EdgeInsets.symmetric(vertical: 3), child: Text('• $v'))),
          ],
        ))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Vazgeç')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Değişiklikleri onayla')),
        ],
      ));
      if (confirmed != true || !mounted) return;
      final prefs = await SharedPreferences.getInstance();
      final previous = <String, Object?>{for (final key in restored.keys) key: prefs.get(key)};
      try {
        for (final entry in restored.entries) {
          final ok = entry.value is double
              ? await prefs.setDouble(entry.key, entry.value as double)
              : await prefs.setString(entry.key, entry.value as String);
          if (!ok) throw StateError('Kaydedilemedi: ${entry.key}');
        }
      } catch (_) {
        for (final entry in previous.entries) {
          if (entry.value == null) {
            await prefs.remove(entry.key);
          } else if (entry.value is double) {
            await prefs.setDouble(entry.key, entry.value as double);
          } else if (entry.value is int) {
            await prefs.setInt(entry.key, entry.value as int);
          } else if (entry.value is bool) {
            await prefs.setBool(entry.key, entry.value as bool);
          } else if (entry.value is String) {
            await prefs.setString(entry.key, entry.value as String);
          } else if (entry.value is List<String>) {
            await prefs.setStringList(entry.key, entry.value as List<String>);
          }
        }
        rethrow;
      }
      await _load();
      if (mounted) _notice('${restored.length} alan geri yüklendi. Kayıtları kontrol edin.');
    } catch (error) {
      if (mounted) _notice('Geri yükleme yapılmadı: $error');
    }
  }

  // Yalnızca JSON biçimini ve bilinen veri türlerini kontrol eder.
  // Otomatik onarım veya veri silme yapmaz.
  // Aşama 6898–7147: aktif liste, metadata ve kalıcı depolama arasında
  // salt-okunur çapraz kontrol. Otomatik temizlik/veri silme yapılmaz.
  Future<void> _showKitchenCrossCheck() async {
    final prefs = await SharedPreferences.getInstance();
    final findings = <Map<String, String>>[];
    void add(String level, String area, String detail) {
      findings.add({'level': level, 'area': area, 'detail': detail});
    }
    final active = _items.toSet();
    final duplicates = <String>{};
    final seen = <String>{};
    for (final item in _items) {
      if (!seen.add(item)) { duplicates.add(item); }
      if (item.trim().isEmpty) add('Uyarı', 'Aktif liste', 'Boş ürün adı bulundu.');
    }
    for (final item in duplicates) {
      add('Uyarı', 'Aktif liste', 'Tekrarlanan ürün: $item');
    }
    for (final item in _done) {
      if (!active.contains(item)) {
        add('Uyarı', 'Tamamlanan',
        'Aktif listede bulunmayan tamamlanmış ürün: $item');
      }
    }
    for (final entry in _details.entries) {
      if (!active.contains(entry.key)) {
        add('Bilgi', 'Ürün ayrıntıları',
        'Aktif listede olmayan ürün için saklanan ayrıntı: ${entry.key}');
      }
    }
    for (final name in _prices.keys) {
      if (!active.contains(name)) {
        add('Bilgi', 'Tahmini fiyat',
        'Aktif listede olmayan ürüne ait fiyat: $name');
      }
    }
    for (final name in _actualPrices.keys) {
      if (!active.contains(name)) {
        add('Bilgi', 'Gerçek fiyat',
        'Aktif listede olmayan ürüne ait fiyat: $name');
      }
    }
    // Uygulama verisi bellekte değişmiş fakat henüz diske yazılmamışsa
    // bu yalnızca bir uyarıdır; kontrol hiçbir kaydı değiştirmez.
    final persistedItems = prefs.getString('alisveris');
    if (persistedItems != null) {
      try {
        final stored = jsonDecode(persistedItems);
        if (stored is! List) {
          add('Kritik', 'Depolama', 'Aktif liste depoda liste biçiminde değil.');
        } else if (jsonEncode(stored) != jsonEncode(_items)) {
          add('Uyarı', 'Depolama',
            'Aktif liste belleği ile cihazda saklanan liste farklı.');
        }
      } catch (_) {
        add('Kritik', 'Depolama', 'Aktif listenin kayıtlı JSON verisi okunamıyor.');
      }
    }
    final persistedTrash = prefs.getString(_kitchenTrashKey);
    if (persistedTrash != null) {
      try {
        final stored = jsonDecode(persistedTrash);
        if (stored is! List) {
          add('Kritik', 'Çöp kutusu', 'Kayıtlı çöp kutusu liste biçiminde değil.');
        } else if (jsonEncode(stored) != jsonEncode(_kitchenTrash)) {
          add('Uyarı', 'Çöp kutusu',
            'Çöp kutusunun bellekteki ve depodaki kayıtları farklı.');
        }
      } catch (_) {
        add('Kritik', 'Çöp kutusu', 'Çöp kutusunun kayıtlı JSON verisi okunamıyor.');
      }
    }
    if (!mounted) return;
    final report = <String>[
      'Seviye;Alan;Açıklama',
      ...findings.map((r) => [r['level'], r['area'], r['detail']]
        .map((v) => _planCsvCell(v ?? '')).join(';')),
    ].join('\n');
    await showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .82,
        child: Padding(padding: const EdgeInsets.all(16), child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Çapraz kayıt ve depolama denetimi', style: TextStyle(
            fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
          const SizedBox(height: 6),
          const Text('Bu denetim yalnızca okur; kayıtları silmez, birleştirmez veya değiştirmez.'),
          const SizedBox(height: 8),
          Text('Aktif ürün: ${_items.length} • Tamamlanan: ${_done.length} • '
            'Çöp kutusu: ${_kitchenTrash.length} • Bulgu: ${findings.length}'),
          const Divider(),
          Expanded(child: findings.isEmpty
            ? const Center(child: Text('Kontrol edilen ilişkilerde tutarsızlık bulunmadı.'))
            : ListView.builder(itemCount: findings.length, itemBuilder: (ctx, i) {
              final r = findings[i];
              return ListTile(dense: true,
                leading: Icon(r['level'] == 'Kritik' ? Icons.error_outline
                  : r['level'] == 'Uyarı' ? Icons.warning_amber_outlined
                  : Icons.info_outline, color: _purple),
                title: Text('${r['level']} • ${r['area']}'),
                subtitle: Text(r['detail'] ?? ''));
            })),
          Row(children: [
            Expanded(child: OutlinedButton.icon(onPressed: () async {
              await Clipboard.setData(ClipboardData(text: report));
              if (mounted) _notice('Çapraz denetim raporu panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala'))),
            const SizedBox(width: 8),
            TextButton(onPressed: () => Navigator.pop(ctx),
              child: const Text('Kapat')),
          ]),
        ])))));
  }

  // Modül kapanış testi: cihazdaki kayıtlar üzerinde yazma/silme yapmadan
  // JSON serileştirme, şema ve temel referans ilişkilerini sınar.
  Future<void> _showKitchenReadOnlySmokeTest() async {
    final prefs = await SharedPreferences.getInstance();
    final results = <Map<String, String>>[];
    void check(String label, bool success, String detail) {
      results.add({'name': label, 'status': success ? 'GEÇTİ' : 'HATA', 'detail': detail});
    }
    const listKeys = <String>[
      'alisveris', 'tamamlanan', 'paket39_shopping_history_v1',
      'paket39_named_shopping_lists_v1', 'paket39_shopping_plans_v1',
      'paket39_kitchen_waste_v1', 'paket39_kitchen_meals_v1',
      'paket39_custom_recipes_v1', 'paket39_meal_templates_v1',
      'paket39_saved_menu_drafts_v1', 'paket39_kitchen_trash_v1',
    ];
    const mapKeys = <String>[
      'paket39_shopping_details_v1', 'paket39_shopping_prices_v1',
      'paket39_shopping_actual_prices_v1',
      'paket39_monthly_shopping_budgets_v1', 'paket39_consumption_goals_v1',
      'paket39_ingredient_unit_prices_v1',
      'paket39_kitchen_weekly_budgets_v1',
    ];
    for (final key in <String>[...listKeys, ...mapKeys]) {
      final raw = prefs.getString(key);
      if (raw == null) {
        check(key, true, 'Henüz kayıt yok; varsayılan boş değer kullanılacak.');
        continue;
      }
      try {
        final parsed = jsonDecode(raw);
        final validType = listKeys.contains(key) ? parsed is List : parsed is Map;
        final schema = validType ? _kitchenSchemaIssues(key, parsed) : <String>['Beklenmeyen veri türü'];
        final roundTrip = jsonDecode(jsonEncode(parsed));
        final same = jsonEncode(roundTrip) == jsonEncode(parsed);
        check(key, validType && schema.isEmpty && same,
          schema.isNotEmpty ? schema.first : same ? 'JSON tur testi başarılı.' : 'JSON tur testi başarısız.');
      } catch (error) {
        check(key, false, 'JSON okunamadı: $error');
      }
    }
    final budget = prefs.get('paket39_shopping_budget_v1');
    check('Alışveriş bütçesi', budget == null ||
      (budget is num && budget.isFinite && budget >= 0),
      budget == null ? 'Henüz bütçe tanımlanmadı.' : 'Sayısal değer kontrol edildi.');
    final recipeIds = _customRecipes.map((r) => r['id']?.toString() ?? '').toSet();
    var missingRecipe = 0;
    for (final meal in _kitchenMeals) {
      final id = meal['recipeId']?.toString() ?? '';
      if (id.isNotEmpty && !recipeIds.contains(id)) missingRecipe++;
    }
    check('Yemek / tarif referansları', missingRecipe == 0,
      '$missingRecipe yemek kaydında bulunamayan tarif kimliği.');
    final activeItems = _items.toSet();
    final unknownDone = _done.where((name) => !activeItems.contains(name)).length;
    check('Tamamlanan / aktif liste', unknownDone == 0,
      '$unknownDone tamamlanmış ürün aktif listede bulunmuyor.');
    final failed = results.where((r) => r['status'] == 'HATA').length;
    final report = <String>[
      'Kontrol;Durum;Açıklama',
      ...results.map((r) => [r['name'], r['status'], r['detail']]
        .map((v) => _planCsvCell(v ?? '')).join(';')),
    ].join('\n');
    if (!mounted) return;
    await showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (ctx) => SafeArea(child: FractionallySizedBox(heightFactor: .85,
        child: Padding(padding: const EdgeInsets.all(16), child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Mutfak • salt okunur test paketi', style: TextStyle(
            fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
          const SizedBox(height: 8),
          Text('${results.length} kontrol • ${results.length - failed} geçti • $failed hata'),
          const Text('Bu test veri değiştirmez. Derleme, gerçek cihaz ve geri yükleme testi yerine geçmez.'),
          const Divider(),
          Expanded(child: ListView.builder(itemCount: results.length,
            itemBuilder: (ctx, i) {
              final r = results[i];
              return ListTile(dense: true,
                leading: Icon(r['status'] == 'GEÇTİ' ? Icons.check_circle_outline
                  : Icons.error_outline, color: r['status'] == 'GEÇTİ'
                    ? Colors.green : Colors.red),
                title: Text('${r['status']} • ${r['name']}'),
                subtitle: Text(r['detail'] ?? ''));
            })),
          Row(children: [
            Expanded(child: OutlinedButton.icon(onPressed: () async {
              await Clipboard.setData(ClipboardData(text: report));
              if (mounted) _notice('Test raporu CSV olarak panoya kopyalandı.');
            }, icon: const Icon(Icons.copy), label: const Text('CSV kopyala'))),
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Kapat')),
          ]),
        ])))));
  }

  // Manuel uçtan uca doğrulama: test sonucunu kullanıcı belirler; veri değiştirmez.
  // Bu kayıtlar uygulama verilerinden ayrı tutulur.
  static const _kitchenQaKey = 'paket39_kitchen_manual_qa_v1';
  static const _kitchenQaCases = <String, String>{
    'shopping_add': 'Alışveriş ürünü ekle, düzenle ve tamamla',
    'shopping_delete': 'Ürün silme onayı ve 7 saniyelik geri alma',
    'shopping_archive': 'Liste kaydet, yeniden aç ve geçmişi kontrol et',
    'shopping_paging': 'Arama, filtre ve sayfalama ile ürünleri bul',
    'stock': 'Stok miktarı ve SKT kaydını düzenle',
    'expired': 'SKT geçmiş ürünleri ve CSV raporunu kontrol et',
    'recipe': 'Kişisel tarif oluştur, değiştir ve tekrar aç',
    'meal': 'Yemek planı oluştur, düzenle ve silinen öğünü geri al',
    'menu': 'Menü taslağı kaydet ve karşılaştır',
    'budget': 'Bütçe, fiyat ve alışveriş maliyetini doğrula',
    'waste': 'İsraf kaydı oluştur, sil ve geri al',
    'trash': 'Çöp kutusundan tekli ve toplu kayıt kurtar',
    'backup': 'JSON yedeğini güvenli yerde sakla',
    'restore': 'Test verisiyle JSON geri yüklemeyi doğrula',
    'persistence': 'Uygulamayı kapatıp açınca kayıtların korunduğunu doğrula',
    'flutter_analyze': 'flutter analyze komutunda hata olmadığını doğrula',
    'flutter_build': 'flutter build apk --release komutunu doğrula',
    'device': 'Android cihazda temel akışları doğrula',
  };

  Future<void> _showKitchenManualQa() async {
    final prefs = await SharedPreferences.getInstance();
    final saved = <String, String>{};
    try {
      final decoded = jsonDecode(prefs.getString(_kitchenQaKey) ?? '{}');
      if (decoded is Map) {
        for (final e in decoded.entries) {
          if (_kitchenQaCases.containsKey(e.key) &&
              <String>['Bekliyor', 'Geçti', 'Hata'].contains(e.value.toString())) {
            saved[e.key.toString()] = e.value.toString();
          }
        }
      }
    } catch (_) {
      // Bozuk kontrol kaydı uygulamanın ana verilerini etkilemez.
    }
    if (!mounted) return;
    await showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final passed = _kitchenQaCases.keys.where((k) => saved[k] == 'Geçti').length;
        final failed = _kitchenQaCases.keys.where((k) => saved[k] == 'Hata').length;
        final waiting = _kitchenQaCases.length - passed - failed;
        Future<void> update(String key, String value) async {
          refresh(() { saved[key] = value; });
          await prefs.setString(_kitchenQaKey, jsonEncode(saved));
        }
        Future<void> copyReport() async {
          final lines = <String>['Kontrol;Sonuç',
            ..._kitchenQaCases.entries.map((e) =>
              '${_planCsvCell(e.value)};${_planCsvCell(saved[e.key] ?? 'Bekliyor')}')];
          await Clipboard.setData(ClipboardData(text: lines.join('\n')));
          if (mounted) _notice('Manuel test raporu CSV olarak kopyalandı.');
        }
        return SafeArea(child: FractionallySizedBox(heightFactor: .93,
          child: Padding(padding: const EdgeInsets.all(14), child: Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Mutfak • uçtan uca test kontrol listesi', style: TextStyle(
              fontSize: 19, fontWeight: FontWeight.bold, color: _purple)),
            const SizedBox(height: 7),
            Text('$passed geçti • $failed hata • $waiting bekliyor'),
            const SizedBox(height: 5),
            const Text('Bu sonuçlar otomatik test değildir. Her adımı uygulamada '
              'denedikten sonra durumunu kendin işaretle. Test durumları ayrı '
              'kaydedilir; alışveriş ve mutfak verileri değiştirilmez.'),
            const Divider(),
            Expanded(child: ListView(children: _kitchenQaCases.entries.map((e) {
              final value = saved[e.key] ?? 'Bekliyor';
              return Card(child: Padding(padding: const EdgeInsets.symmetric(
                horizontal: 10, vertical: 4), child: Row(children: [
                Expanded(child: Text(e.value)),
                const SizedBox(width: 8),
                DropdownButton<String>(value: value,
                  items: const ['Bekliyor', 'Geçti', 'Hata'].map((v) =>
                    DropdownMenuItem(value: v, child: Text(v))).toList(),
                  onChanged: (v) { if (v != null) update(e.key, v); }),
              ])));
            }).toList())),
            Wrap(spacing: 8, runSpacing: 5, children: [
              OutlinedButton.icon(onPressed: copyReport,
                icon: const Icon(Icons.copy), label: const Text('CSV kopyala')),
              OutlinedButton.icon(onPressed: () async {
                final confirm = await showDialog<bool>(context: ctx,
                  builder: (d) => AlertDialog(
                    title: const Text('Test durumlarını sıfırla?'),
                    content: const Text('Yalnızca manuel test işaretleri silinir. '
                      'Alışveriş ve mutfak kayıtları korunur.'),
                    actions: [
                      TextButton(onPressed: () => Navigator.pop(d, false),
                        child: const Text('Vazgeç')),
                      FilledButton(onPressed: () => Navigator.pop(d, true),
                        child: const Text('Sıfırla')),
                    ]));
                if (confirm != true) return;
                refresh(saved.clear);
                await prefs.remove(_kitchenQaKey);
              }, icon: const Icon(Icons.restart_alt),
                label: const Text('Testleri sıfırla')),
              TextButton(onPressed: () => Navigator.pop(ctx),
                child: const Text('Kapat')),
            ]),
          ]))));
      }));
  }

  Future<void> _showKitchenStorageCheck() async {
    final prefs = await SharedPreferences.getInstance();
    final expectations = <String, bool>{
      'alisveris': true, 'tamamlanan': true,
      'paket39_shopping_details_v1': false,
      'paket39_shopping_prices_v1': false,
      'paket39_shopping_actual_prices_v1': false,
      'paket39_shopping_history_v1': true,
      'paket39_monthly_shopping_budgets_v1': false,
      _namedListsKey: true, _plansKey: true, _goalsKey: false,
      _wasteKey: true, _mealsKey: true, _customRecipesKey: true,
      _ingredientUnitPricesKey: false, _mealTemplatesKey: true,
      _kitchenWeeklyBudgetKey: false, _savedMenuDraftsKey: true,
      _kitchenTrashKey: true,
    };
    final results = <String>[];
    var checked = 0;
    var errors = 0;
    for (final entry in expectations.entries) {
      final raw = prefs.getString(entry.key);
      if (raw == null) continue;
      checked++;
      try {
        final decoded = jsonDecode(raw);
        final valid = entry.value ? decoded is List : decoded is Map;
        if (!valid) {
          errors++;
          results.add('HATA • ${entry.key}: beklenen ${entry.value ? 'liste' : 'nesne'} değil');
        } else {
          final issues = _kitchenSchemaIssues(entry.key, decoded);
          errors += issues.length;
          results.addAll(issues.map((issue) => 'HATA • $issue'));
        }
      } catch (_) {
        errors++;
        results.add('HATA • ${entry.key}: JSON okunamıyor');
      }
    }
    final budget = prefs.get('paket39_shopping_budget_v1');
    if (budget != null && (budget is! num || !budget.isFinite || budget < 0)) {
      errors++;
      results.add('HATA • Alışveriş bütçesi geçerli pozitif sayı değil');
    }
    if (!mounted) return;
    await showDialog<void>(context: context, builder: (ctx) => AlertDialog(
      title: const Text('Veri bütünlüğü kontrolü'),
      content: SingleChildScrollView(child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('$checked JSON alanı kontrol edildi. Hata: $errors'),
          const SizedBox(height: 8),
          const Text('JSON biçimi ve temel kayıt türleri kontrol edilir. Tariflerin içerik doğruluğu, cihaz testi ve yedekten geri yükleme ayrıca test edilmelidir.'),
          const SizedBox(height: 8),
          if (results.isEmpty) const Text('Kontrol edilen alanlarda biçim hatası bulunmadı.'),
          ...results.map((r) => Padding(
            padding: const EdgeInsets.only(bottom: 6), child: Text(r))),
        ],
      )),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Kapat')),
        TextButton(onPressed: () async {
          await Clipboard.setData(ClipboardData(text: [
            'Kontrol edilen alan: $checked • Hata: $errors', ...results,
          ].join('\n')));
          if (ctx.mounted) Navigator.pop(ctx);
          if (mounted) _notice('Kontrol sonucu panoya kopyalandı.');
        }, child: const Text('Sonucu kopyala')),
      ],
    ));
  }

  void _showKitchenCompletionCenter() {
    String filter = 'Tümü';
    String search = '';
    showModalBottomSheet<void>(context: context, isScrollControlled: true,
      builder: (sheet) => StatefulBuilder(builder: (ctx, refresh) {
        final issues = _kitchenAuditItems();
        final visible = issues.where((r) =>
          (filter == 'Tümü' || r['severity'] == filter) &&
          ('${r['area']} ${r['title']} ${r['detail']}')
            .toLowerCase().contains(search.toLowerCase())).toList();
        final critical = issues.where((r) => r['severity'] == 'Kritik').length;
        final warnings = issues.where((r) => r['severity'] == 'Uyarı').length;
        final info = issues.where((r) => r['severity'] == 'Bilgi').length;
        Widget countCard(String label, int value) => Expanded(child: Card(
          color: const Color(0xFFF3E8FF), child: Padding(
            padding: const EdgeInsets.all(10), child: Column(children: [
              Text('$value', style: const TextStyle(fontSize: 22,
                fontWeight: FontWeight.bold, color: _purple)),
              Text(label, style: const TextStyle(fontSize: 12)),
            ]))));
        return SafeArea(child: FractionallySizedBox(heightFactor: .94,
          child: Padding(padding: const EdgeInsets.all(14), child: ListView(children: [
            const Text('Mutfak modülü • kapanış ve kalite kontrolü',
              style: TextStyle(fontSize: 19, fontWeight: FontWeight.bold,
                color: _purple)),
            const SizedBox(height: 6),
            const Text('Bu ekran verileri yalnızca inceler. Stok, plan veya '
              'alışveriş kayıtlarını kendiliğinden değiştirmez.'),
            const SizedBox(height: 10),
            Row(children: [countCard('Kritik', critical),
              countCard('Uyarı', warnings), countCard('Bilgi', info)]),
            const SizedBox(height: 8),
            const Text('Modül envanteri', style: TextStyle(
              fontWeight: FontWeight.bold, color: _purple)),
            Text('Aktif ürün: ${_items.length} • Kayıtlı liste: ${_namedLists.length}'),
            Text('Alışveriş planı: ${_shoppingPlans.length} • Kişisel tarif: ${_customRecipes.length}'),
            Text('Yemek kaydı: ${_kitchenMeals.length} • Menü taslağı: ${_savedMenuDrafts.length}'),
            Text('Yemek şablonu: ${_mealTemplates.length} • İsraf kaydı: ${_kitchenWaste.length}'),
            Text('Birim fiyat: ${_ingredientUnitPrices.length} • Haftalık bütçe: ${_kitchenWeeklyBudgets.length}'),
            const Divider(),
            Wrap(spacing: 7, runSpacing: 6, children: [
              OutlinedButton.icon(onPressed: () {
                final lines = <String>[
                  'Alan;Seviye;Konu;Açıklama',
                  ...issues.map((r) => [r['area'], r['severity'],
                    r['title'], r['detail']].map((v) =>
                    '"${(v ?? '').replaceAll('"', '""')}"').join(';')),
                ];
                Clipboard.setData(ClipboardData(text: lines.join('\n')));
                _notice('Kalite kontrol raporu panoya kopyalandı.');
              }, icon: const Icon(Icons.copy),
                label: const Text('Kontrol raporunu kopyala')),
              OutlinedButton.icon(onPressed: () => refresh(() {}),
                icon: const Icon(Icons.refresh), label: const Text('Yeniden tara')),
              OutlinedButton.icon(onPressed: _showKitchenStorageCheck,
                icon: const Icon(Icons.verified_user_outlined),
                label: const Text('Veri bütünlüğünü kontrol et')),
              OutlinedButton.icon(onPressed: _showKitchenManualQa,
                icon: const Icon(Icons.checklist_rtl),
                label: const Text('Uçtan uca test kontrol listesi')),
              OutlinedButton.icon(onPressed: _showKitchenReadOnlySmokeTest,
                icon: const Icon(Icons.fact_check_outlined),
                label: const Text('Salt okunur test paketi')),
              OutlinedButton.icon(onPressed: _showKitchenCrossCheck,
                icon: const Icon(Icons.rule_folder_outlined),
                label: const Text('Çapraz kayıt ve depolama denetimi')),
              OutlinedButton.icon(onPressed: _copyKitchenBackup,
                icon: const Icon(Icons.backup_outlined),
                label: const Text('Tüm modül verilerini yedekle (JSON)')),
              OutlinedButton.icon(onPressed: _restoreKitchenBackup,
                icon: const Icon(Icons.settings_backup_restore),
                label: const Text('JSON yedeğinden geri yükle')),
              OutlinedButton.icon(onPressed: _showKitchenTrash,
                icon: const Icon(Icons.delete_outline),
                label: Text('Kalıcı çöp kutusu (${_kitchenTrash.length})')),
            ]),
            const SizedBox(height: 8),
            const Text('Modül kısayolları', style: TextStyle(
              fontWeight: FontWeight.bold, color: _purple)),
            Wrap(spacing: 6, runSpacing: 4, children: [
              ActionChip(label: const Text('Tarifler'), onPressed: () {
                Navigator.pop(ctx); _showCustomRecipes();
              }),
              ActionChip(label: const Text('Stok ve SKT'), onPressed: () {
                Navigator.pop(ctx); _showKitchenDashboard();
              }),
              ActionChip(label: const Text('Menü taslakları'), onPressed: () {
                Navigator.pop(ctx); _showSavedMenuDrafts();
              }),
              ActionChip(label: const Text('Alışveriş planları'), onPressed: () {
                Navigator.pop(ctx); _showShoppingPlans();
              }),
              ActionChip(label: const Text('Birim fiyatlar'), onPressed: () {
                Navigator.pop(ctx); _showKitchenUnitCosts();
              }),
              ActionChip(label: const Text('Aylık rapor'), onPressed: () {
                Navigator.pop(ctx); _showKitchenMonthlyOverview();
              }),
            ]),
            const Divider(),
            TextField(decoration: const InputDecoration(
              prefixIcon: Icon(Icons.search), labelText: 'Kontrollerde ara'),
              onChanged: (v) => refresh(() => search = v)),
            Wrap(spacing: 6, children: [
              for (final f in const ['Tümü', 'Kritik', 'Uyarı', 'Bilgi'])
                ChoiceChip(label: Text(f), selected: filter == f,
                  onSelected: (_) => refresh(() => filter = f)),
            ]),
            if (visible.isEmpty) const Padding(
              padding: EdgeInsets.all(16), child: Text(
                'Bu filtrede kontrol bulgusu yok. Bu, cihaz testi yerine geçmez.')),
            for (final row in visible) Card(
              color: row['severity'] == 'Kritik'
                ? const Color(0xFFFFE3E3) : const Color(0xFFFFF7FC),
              child: ListTile(
                leading: Icon(row['severity'] == 'Kritik'
                  ? Icons.error_outline : row['severity'] == 'Uyarı'
                  ? Icons.warning_amber_outlined : Icons.info_outline,
                  color: _purple),
                title: Text(row['title'] ?? ''),
                subtitle: Text('${row['area']} • ${row['severity']}\n${row['detail']}'),
                isThreeLine: true)),
            const SizedBox(height: 12),
            const Text('Kapanış durumu: işlevsel kontrol listesi hazır. '
              'Flutter analyze, APK derlemesi, veri geçişi ve gerçek cihaz '
              'testleri ayrıca tamamlanmalıdır.',
              style: TextStyle(fontSize: 12)),
          ]))));
      }));
  }

