  Future<void> _openKitchenTools() async {
    final tools = _kitchenTools;
    final selected = await Navigator.of(context).push<VoidCallback>(
      MaterialPageRoute(builder: (_) => _KitchenToolsPage(tools: tools)));
    if (selected != null && mounted) selected();
  }

  @override
  Widget build(BuildContext context) {
    final normalizedQuery = _query.trim().toLowerCase();
    final visible = _items.where((name) {
      final cat = _details[name]?['category'] ?? _guess(name);
      return (_category == 'Tümü' || cat == _category) &&
          (!_hideDone || !_done.contains(name)) &&
          name.toLowerCase().contains(normalizedQuery);
    }).toList()..sort((a, b) {
      final doneOrder = (_done.contains(a) ? 1 : 0).compareTo(_done.contains(b) ? 1 : 0);
      return doneOrder != 0 ? doneOrder : a.toLowerCase().compareTo(b.toLowerCase());
    });
    // Filtre sonucu küçülürse mevcut sayfa güvenli biçimde son sayfaya alınır.
    final pageCount = visible.isEmpty ? 1 : (visible.length + _shoppingPageSize - 1) ~/ _shoppingPageSize;
    final currentPage = _shoppingPage.clamp(0, pageCount - 1).toInt();
    final pageStart = currentPage * _shoppingPageSize;
    final pageItems = visible.skip(pageStart).take(_shoppingPageSize).toList();
    final estimated = _items.fold<double>(0, (sum, item) => sum + (_prices[item] ?? 0));
    final purchased = _items.where(_done.contains).fold<double>(0, (sum, item) => sum + (_prices[item] ?? 0));
    final unpriced = _items.where((item) => !_prices.containsKey(item)).length;
    final actualPurchased = _items.where(_done.contains).fold<double>(0, (sum, item) => sum + (_actualPrices[item] ?? 0));
    final estimatedPurchased = _items.where(_done.contains).fold<double>(0, (sum, item) => sum + (_prices[item] ?? 0));
    final missingActual = _items.where((item) => _done.contains(item) && !_actualPrices.containsKey(item)).length;
    return Scaffold(
      backgroundColor: _pink,
      appBar: AppBar(title: const Text('Akıllı alışveriş listem'),
        actions: [IconButton(tooltip: 'Yenile', icon: const Icon(Icons.refresh), onPressed: _load)]),
      floatingActionButton: FloatingActionButton.extended(onPressed: () => _edit(),
        icon: const Icon(Icons.add), label: const Text('Ürün ekle')),
      body: _loading ? const Center(child: CircularProgressIndicator()) :
        ListView(padding: const EdgeInsets.fromLTRB(14, 12, 14, 100), children: [
          Card(color: const Color(0xFFFFE4F1), child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Alışveriş durumum', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: _purple)),
              const SizedBox(height: 8),
              Text('${_items.where(_done.contains).length} / ${_items.length} ürün tamamlandı'),
              const SizedBox(height: 8),
              LinearProgressIndicator(value: _items.isEmpty ? 0 : _items.where(_done.contains).length / _items.length),
            ]))),
          const SizedBox(height: 12),
          Card(color: const Color(0xFFFFE4F1), child: Padding(padding: const EdgeInsets.all(14),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [const Expanded(child: Text('Alışveriş bütçem', style: TextStyle(fontWeight: FontWeight.bold, color: _purple))),
                TextButton.icon(onPressed: _setBudget, icon: const Icon(Icons.edit), label: const Text('Düzenle'))]),
              Text(_budget > 0 ? _money(_budget) : 'Henüz bütçe belirlenmedi'),
              const SizedBox(height: 8),
              Text('Tahmini toplam: ${_money(estimated)}'),
              Text('Satın alınanların tahmini toplamı: ${_money(purchased)}'),
              Text('Gerçek harcama (fiyatı girilen): ${_money(actualPurchased)}'),
              Text('Tahmini / gerçek farkı: ${_money(estimatedPurchased - actualPurchased)}'),
              if (missingActual > 0) Text('$missingActual alınmış ürünün gerçek fiyatı girilmedi; karşılaştırma eksik olabilir.', style: const TextStyle(fontSize: 12)),
              Text('Kalan ürünlerin tahmini tutarı: ${_money(estimated - purchased)}'),
              if (_budget > 0) Text('Bütçe farkı: ${_money(_budget - estimated)}',
                style: TextStyle(fontWeight: FontWeight.bold, color: estimated > _budget ? Colors.red : Colors.green.shade800)),
              if (_budget > 0) LinearProgressIndicator(value: (estimated / _budget).clamp(0.0, 1.0)),
              if (unpriced > 0) Text('$unpriced ürünün fiyatı girilmedi. Tahmin eksik olabilir.',
                style: const TextStyle(fontSize: 12)),
            ]))),
          const SizedBox(height: 10),
          Card(color: const Color(0xFFF3E8FF), child: Padding(padding: const EdgeInsets.all(14),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [Expanded(child: Text('${_monthKey()} • Aylık bütçem',
                style: const TextStyle(fontWeight: FontWeight.bold, color: _purple))),
                TextButton.icon(onPressed: _setMonthlyBudget, icon: const Icon(Icons.edit), label: const Text('Düzenle'))]),
              Text(_monthlyBudgets[_monthKey()] == null || _monthlyBudgets[_monthKey()] == 0
                ? 'Aylık bütçe belirlenmedi' : _money(_monthlyBudgets[_monthKey()]!)),
              Text('Bu ay arşivlenen gerçek harcama: ${_money(_monthlyTotals()[_monthKey()] ?? 0)}'),
              if ((_monthlyBudgets[_monthKey()] ?? 0) > 0) ...[
                Text('Kalan: ${_money(_monthlyBudgets[_monthKey()]! - (_monthlyTotals()[_monthKey()] ?? 0))}',
                  style: TextStyle(color: (_monthlyTotals()[_monthKey()] ?? 0) > _monthlyBudgets[_monthKey()]! ? Colors.red : Colors.green.shade800)),
                LinearProgressIndicator(value: ((_monthlyTotals()[_monthKey()] ?? 0) / _monthlyBudgets[_monthKey()]!).clamp(0.0, 1.0)),
                if ((_monthlyTotals()[_monthKey()] ?? 0) > _monthlyBudgets[_monthKey()]!)
                  const Text('Aylık bütçe aşıldı!', style: TextStyle(color: Colors.red)),
              ],
            ]))),
          const SizedBox(height: 8),
          Card(color: const Color(0xFFF3E8FF), child: Padding(padding: const EdgeInsets.all(14),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                const Expanded(child: Text('Mutfak araçları', style: TextStyle(fontWeight: FontWeight.bold, color: _purple))),
                FilledButton.tonalIcon(onPressed: _openKitchenTools, icon: const Icon(Icons.apps_rounded),
                  label: Text('Tümü (${_kitchenTools.length})')),
              ]),
              const SizedBox(height: 8),
              Wrap(spacing: 8, runSpacing: 4, children: [
              ActionChip(avatar: const Icon(Icons.menu_book, size: 18), label: Text('Kendi tariflerim'), onPressed: _showCustomRecipes),
              ActionChip(avatar: const Icon(Icons.calendar_month, size: 18), label: Text('Haftalık yemek şablonları'), onPressed: _showMealTemplates),
              ActionChip(avatar: const Icon(Icons.kitchen, size: 18), label: Text('Akıllı mutfak / israf'), onPressed: _showKitchenDashboard),
              ActionChip(avatar: const Icon(Icons.folder_open, size: 18), label: Text('Kayıtlı listeler'), onPressed: _showNamedLists),
              ActionChip(avatar: const Icon(Icons.history, size: 18), label: Text('Geçmiş ve aylık rapor'), onPressed: _showHistory),
              ActionChip(avatar: const Icon(Icons.inventory_2_outlined, size: 18), label: Text('Alınanları arşivle'), onPressed: _archivePurchased),
              ]),
              // Modül kapanış/kalite kontrol aracı yalnızca geliştirme sürümünde.
              if (!kReleaseMode) TextButton.icon(onPressed: _showKitchenCompletionCenter,
                icon: const Icon(Icons.fact_check_outlined),
                label: const Text('Mutfak modülü • kapanış ve kalite kontrolü (geliştirici)')),
            ]))),
          const SizedBox(height: 12),
          TextField(onChanged: (s) => setState(() { _query = s; _shoppingPage = 0; }),
            decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Ürün ara')),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(initialValue: _category,
            decoration: const InputDecoration(labelText: 'Kategori'),
            items: _categories.map((c) => DropdownMenuItem(value: c, child: Text(c))).toList(),
            onChanged: (v) { if (v != null) setState(() { _category = v; _shoppingPage = 0; }); }),
          SwitchListTile(title: const Text('Tamamlananları gizle'), value: _hideDone,
            onChanged: (v) => setState(() { _hideDone = v; _shoppingPage = 0; })),
          if (visible.isEmpty) const Padding(padding: EdgeInsets.all(20),
            child: Text('Bu filtrede ürün bulunamadı.')),
          if (visible.isNotEmpty) Padding(
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Row(children: [
              Expanded(child: Text(
                '${visible.length} ürün • ${pageStart + 1}–${pageStart + pageItems.length} gösteriliyor',
                style: const TextStyle(fontSize: 12, color: _purple),
              )),
              IconButton(
                tooltip: 'Önceki sayfa',
                onPressed: currentPage == 0 ? null : () => setState(() => _shoppingPage = currentPage - 1),
                icon: const Icon(Icons.chevron_left),
              ),
              Text('${currentPage + 1}/$pageCount', style: const TextStyle(color: _purple)),
              IconButton(
                tooltip: 'Sonraki sayfa',
                onPressed: currentPage + 1 >= pageCount ? null : () => setState(() => _shoppingPage = currentPage + 1),
                icon: const Icon(Icons.chevron_right),
              ),
            ]),
          ),
          ...pageItems.map((name) => Card(child: CheckboxListTile(
            value: _done.contains(name),
            onChanged: (checked) async {
              setState(() { if (checked == true) { _done.add(name); } else { _done.remove(name); } });
              await _save();
            },
            title: Text(name, style: TextStyle(decoration: _done.contains(name) ? TextDecoration.lineThrough : null)),
            subtitle: Text('${_details[name]?['category'] ?? _guess(name)}${(_details[name]?['note'] ?? '').isEmpty ? '' : '  •  ${_details[name]!['note']}'}\nTahmini: ${_prices.containsKey(name) ? _money(_prices[name]!) : 'Girilmedi'}  •  Gerçek: ${_actualPrices.containsKey(name) ? _money(_actualPrices[name]!) : 'Girilmedi'}'),
            secondary: PopupMenuButton<String>(tooltip: 'Ürün işlemleri',
              onSelected: (action) async {
                if (action == 'edit') { await _edit(original: name); }
                if (action == 'price') { await _setPrice(name); }
                if (action == 'actual') { await _setActualPrice(name); }
                if (action == 'delete') {
                  if (!await _confirmKitchenDelete('Alışveriş ürünü', name)) return;
                  if (!mounted) return;
                  final originalIndex = _items.indexOf(name);
                  final wasDone = _done.contains(name);
                  final oldDetails = _details[name] == null
                      ? null : Map<String, dynamic>.from(_details[name]!);
                  final oldPrice = _prices[name];
                  final oldActual = _actualPrices[name];
                  setState(() { _items.remove(name); _done.remove(name); _details.remove(name); _prices.remove(name); _actualPrices.remove(name); });
                  await _save();
                  if (!context.mounted) return;
                  final messenger = ScaffoldMessenger.of(context);
                  messenger.hideCurrentSnackBar();
                  messenger.showSnackBar(SnackBar(
                    content: Text('$name silindi.'),
                    duration: const Duration(seconds: 7),
                    action: SnackBarAction(label: 'Geri al', onPressed: () async {
                      if (!mounted || _items.contains(name)) return;
                      setState(() {
                        _items.insert(originalIndex.clamp(0, _items.length), name);
                        if (wasDone) _done.add(name);
                        if (oldDetails != null) _details[name] = Map<String, String>.from(oldDetails);
                        if (oldPrice != null) _prices[name] = oldPrice;
                        if (oldActual != null) _actualPrices[name] = oldActual;
                      });
                      await _save();
                    }),
                  ));
                }
              },
              itemBuilder: (_) => const [
                PopupMenuItem(value: 'edit', child: Text('Düzenle')),
                PopupMenuItem(value: 'price', child: Text('Tahmini fiyat ekle / düzenle')),
                PopupMenuItem(value: 'actual', child: Text('Gerçek satın alma fiyatı')),
                PopupMenuItem(value: 'delete', child: Text('Sil')),
              ]),
          ))),
          if (pageCount > 1) Padding(
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
              OutlinedButton.icon(
                onPressed: currentPage == 0 ? null : () => setState(() => _shoppingPage = currentPage - 1),
                icon: const Icon(Icons.chevron_left), label: const Text('Önceki'),
              ),
              const SizedBox(width: 12),
              Text('${currentPage + 1} / $pageCount'),
              const SizedBox(width: 12),
              OutlinedButton.icon(
                onPressed: currentPage + 1 >= pageCount ? null : () => setState(() => _shoppingPage = currentPage + 1),
                icon: const Icon(Icons.chevron_right), label: const Text('Sonraki'),
              ),
            ]),
          ),
          const SizedBox(height: 8),
          const Text('Tariflerden ve haftalık plandan eklenen ürünler aynı listede görünür. Miktar notları mevcut malzeme metinlerini değiştirmez.',
            style: TextStyle(fontSize: 12, color: _purple)),
        ]),
    );
  }
}


class _KitchenToolsPage extends StatefulWidget {
  final List<(String, String, IconData, VoidCallback)> tools;
  const _KitchenToolsPage({required this.tools});
  @override
  State<_KitchenToolsPage> createState() => _KitchenToolsPageState();
}

class _KitchenToolsPageState extends State<_KitchenToolsPage> {
  String _query = '';

  @override
  Widget build(BuildContext context) {
    final q = _query.trim().toLowerCase();
    final groups = <String, List<(String, String, IconData, VoidCallback)>>{};
    for (final tool in widget.tools) {
      if (q.isNotEmpty && !tool.$2.toLowerCase().contains(q)) continue;
      groups.putIfAbsent(tool.$1, () => []).add(tool);
    }
    return Scaffold(
      appBar: AppBar(title: const Text('Mutfak araçları')),
      body: ListView(padding: const EdgeInsets.fromLTRB(12, 8, 12, 24), children: [
        TextField(
          key: const ValueKey('kitchen_tools_search'),
          onChanged: (v) => setState(() => _query = v),
          decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Araç ara (ör. bütçe, stok, menü)')),
        const SizedBox(height: 8),
        if (groups.isEmpty) const Padding(padding: EdgeInsets.all(24),
          child: Text('Aramanla eşleşen araç yok.', textAlign: TextAlign.center)),
        for (final entry in groups.entries)
          Card(child: ExpansionTile(
            initiallyExpanded: q.isNotEmpty,
            title: Text(entry.key, style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text('${entry.value.length} araç'),
            children: [
              for (final tool in entry.value) ListTile(
                leading: Icon(tool.$3),
                title: Text(tool.$2),
                trailing: const Icon(Icons.chevron_right),
                onTap: () => Navigator.of(context).pop(tool.$4)),
            ],
          )),
      ]),
    );
  }
}
